const a="https://www.churchofjesuschrist.org/study/scriptures",e=JSON.parse('[{"id":"doctrine-and-covenants","title":"Mataupu Faavae ma Feagaiga","englishTitle":"Doctrine and Covenants","volume":"Doctrine and Covenants","volumeId":"dc-testament","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Faalogo maia, E outou e tagata o la’u ekalesia, ua fetalai mai ai le siufofoga o ia o lē o afio i luga, ma o lē o ona fofoga ua i luga o tagata uma; ioe, e moni Ou te fai atu: Faalogo mai ia outou e tagata mai mea mamao; ma outou o loo i luga o motu o le sami, faafofoga mai faatasi."},{"verse":2,"text":"Aua e moni o le siufofoga o le Alii ua mo tagata uma, ma e leai se tasi e sao mai ai; ma e leai se mata o le a lē vaai, po o se taliga o le a lē faalogo, po o se loto o le a lē tuia."},{"verse":3,"text":"Ma o e e fouvale o le a tuia i le faanoanoa tele; ona o le a alagaina a latou amioletonu i luga o tumutumu o fale, ma o le a faaalia a latou galuega lilo."},{"verse":4,"text":"Ma o le leo o le lapataiga ua mo tagata uma, e ala atu i fofoga o o’u soo, o e ua Ou filifilia i aso nei e gata ai."},{"verse":5,"text":"Ma o le a latou o atu ma e leai se tasi o le a taofia i latou, ona o A’u o le Alii ua poloaiina i latou."},{"verse":6,"text":"Faauta, o la’u pule lenei, ma le pule a a’u auauna, ma la’u uputomua i le tusi o a’u poloaiga, ua Ou tuu atu ia te i latou e faasalalau atu ia te outou, E, outou e o nonofo i le lalolagi."},{"verse":7,"text":"O le mea lea, ia matatau ai ma gatete, E, outou tagata e, ona o mea ua folafola ai i totonu o i latou e A’u o le Alii o le a faataunuuina."},{"verse":8,"text":"Ma e moni Ou te fai atu ia te outou, o i latou o e e o atu, ma tau atu nei tala i e o nonofo i le lalolagi, e tuu atu ia te i latou le mana e faamau ai i le lalolagi ma i le lagi, e e lē talitonu ma fouvale;"},{"verse":9,"text":"Ioe, e moni, e faamau ai i latou mo le aso o le a sasaa mai ai ma le lē fuaina le toasa o le Atua i luga o e e amioleaga—"},{"verse":10,"text":"Mo le aso e afio mai ai le Alii e taui i tagata taitoatasi e tusa ma lana galuega, ma fua mai i tagata taitoatasi e tusa ma le fua na ia fua atu i lona uso-a-tagata."},{"verse":11,"text":"O le mea lea ua oo mai le siufofoga o le Alii ia oo atu i tuluiga o le lalolagi, ina ia mafai ona faalogoina e i latou uma o e e fia faalogo:"},{"verse":12,"text":"Inā outou saunia ia, inā outou saunia ia mo mea o le a oo mai, ona ua latalata mai le Alii;"},{"verse":13,"text":"Ma ua faateteleina le toasa o le Alii, ma ua faamama lana pelu i le lagi, ma o le a pa’ū ifo i luga o e o nonofo i le lalolagi."},{"verse":14,"text":"Ma o le a faaalia le aao o le Alii; ma e oo mai le aso, o i latou o e e lē fia faalogo i le siufofoga o le Alii, po o le leo o ana auauna, pe lē gauai i upu a perofeta ma aposetolo, o le a vavae ese mai totonu o le nuu;"},{"verse":15,"text":"Ona ua latou se ese mai a’u sauniga, ma soli la’u feagaiga tumau e faavavau;"},{"verse":16,"text":"Ua latou lē sailia le Alii e faatu lana amiotonu, ae ua taitoatasi le tagata ma savali i lona lava ala, ma tusa ai ma le faatusa o lona lava atua, o lona foliga ua tusa ma foliga o le lalolagi, ma o lona uiga o lena o se tupua, lea e oo ina tuai ma o le a fano i Papelonia, o Papelonia tele lava lea o le a pa’ū."},{"verse":17,"text":"O le mea lea, o A’u o le Alii, ona ua Ou iloa le malaia o le a oo mai i luga o e o nonofo i le lalolagi, na Ou valaau atu ai i la’u auauna o Iosefa Samita, Le Itiiti, ma tautala atu ia te ia mai le lagi, ma tuu atu ia te ia poloaiga;"},{"verse":18,"text":"Ma sa tuu atu foi i isi poloaiga, e tatau ona latou folafola atu nei mea i le lalolagi; ma ua faia lenei mea atoa ina ia mafai ona faataunuuina o mea na tusia e perofeta—"},{"verse":19,"text":"O le a oo mai mea vaivai o le lalolagi ma gaui i lalo mea tautaua ma le malolosi, ina ia lē fautuaina e le tagata lona uso-a-tagata, pe faalagolago i le lima o le tagata—"},{"verse":20,"text":"Ae ia mafai e tagata taitoatasi ona tautala i le suafa o le Atua le Alii, le Faaola lea o le lalolagi;"},{"verse":21,"text":"Ina ia mafai foi ona faateleina o le faatuatua i le lalolagi;"},{"verse":22,"text":"Ina ia mafai ona faatuina o la’u feagaiga tumau e faavavau;"},{"verse":23,"text":"Ina ia mafai ona folafola atu le atoatoaga o la’u talalelei e e vaivai ma e faatauvaa i tuluiga o le lalolagi, ma i luma o tupu ma pule."},{"verse":24,"text":"Faauta, o A’u o le Atua ma ua Ou tautala atu ai; o nei poloaiga ua a a’u ia, ma sa tuuina atu i a’u auauna i lo latou vaivai, e tusa ma le ala o la latou gagana, ina ia mafai ona latou malamalama."},{"verse":25,"text":"Ma e tusa ai ma lo latou sese, e mafai ona faailoaina;"},{"verse":26,"text":"Ma e tusa ai ma lo latou sailiga o le poto, e mafai ona aoaoina ai i latou;"},{"verse":27,"text":"Ma e tusa ai ma la latou agasala, e mafai ona aoaiina ai i latou, ina ia latou salamo;"},{"verse":28,"text":"Ma e tusa ai ma lo latou lotomaualalalo, e mafai ona faamalolosia ai i latou, ma faamanuiaina mai lugā, ma maua le malamalama mai lea taimi i lea taimi."},{"verse":29,"text":"Ma ina ua uma ona maua o le talafaamaumau o sa Nifaē, ioe, ina ia mafai ai e la’u auauna lea o Iosefa Samita, Le Itiiti, ona maua o le mana e faaliliu ai le Tusi a Mamona e ala i le alofa mutimutivale o le Atua, i le mana o le Atua."},{"verse":30,"text":"Ma ina ia mafai ai foi e i latou o e ua tuuina atu i ai nei poloaiga, ona maua le mana e faataoto ai le faavae o lenei ekalesia, ma aumai ai mai le lē mailoa ma le pouliuli, le ekalesia moni ma ola e tasi i luga o le fogaeleele atoa, lea ua fiafia tele i ai A’u, o le Alii, i le tautala atu lea i le ekalesia atoa ae lē i tagata taitoatasi—"},{"verse":31,"text":"Ona o A’u o le Alii e lē mafai ona Ou vaai atu i le agasala ma sina vaega itiiti e ono talia ai;"},{"verse":32,"text":"Ae ui i lea, o ia o lē e salamo ma faia poloaiga a le Alii o le a faamagaloina;"},{"verse":33,"text":"Ma o ia o lē e lē salamo, o le a aveesea mai ia te ia le malamalama lava lea na ia maua; ona e lē taumafai pea lo’u Agaga i le tagata, ua fetalai mai ai le Alii o ’Au."},{"verse":34,"text":"O lenei foi, e moni Ou te fai atu ia te outou, E, e o nonofo i le lalolagi: O A’u o le Alii ua Ou loto e faailoa atu nei mea i tagata uma;"},{"verse":35,"text":"Ona o A’u e lē o se faailoga tagata, ma Ou te manao ia iloa e tagata uma ua vave ona oo mai o le aso; e lei oo mai le itula, ae ua latalata lava ona oo mai, le taimi o le a aveesea ai le filemu mai le lalolagi, ma o le a maua ai e le tiapolo le mana i luga o lana lava puleaga."},{"verse":36,"text":"Ma o le a i ai foi i le Alii le mana i luga o lana au paia, ma o le a nofotupu i lo latou lotolotoi, ma o le a afio ifo i le faamasinoga i luga o Etoma, po o le lalolagi."},{"verse":37,"text":"Suesue i nei poloaiga, ona ua moni ma faamaoni i latou, ma o le a faataunuuina lava valoaga ma folafolaga uma ua i totonu o i latou."},{"verse":38,"text":"O le mea ua fai atu ai A’u o le Alii ua Ou fai atu ai, ma Ou te lē faatoese a’u lava ia; ma e ui ina mavae atu le lagi ma le lalolagi, e lē mavae atu lava la’u upu, ae o le a faataunuuina uma lava, pe i lo’u lava leo po o i le leo o a’u auauna, ua tutusa lava."},{"verse":39,"text":"Aua faauta, ma tagai, o le Alii o le Atua lea, ma ua molimau ai le Agaga, ma ua moni le molimau, ma e tumau le upumoni e faavavau faavavau lava. Amene."}]},{"chapter":2,"verses":[{"verse":1,"text":"Faauta, o le a Ou faaali atu ia te outou le Perisitua, e ala i le lima o Elia le perofeta, ae lei oo i le oo mai o le aso tele ma le matautia o le Alii."},{"verse":2,"text":"Ma o le a totō e ia i loto o fanau folafolaga na faia i tamā, ma o le a liliu atu loto o fanau i o latou tamā."},{"verse":3,"text":"Afai e lē faapea, o le a faama’umauina atoa le lalolagi i lona afio mai."}]},{"chapter":3,"verses":[{"verse":1,"text":"O galuega, ma fuafuaga, ma faamoemoega o le Atua e lē mafai ona taofia, pe mafai foi ona avea i latou ma meanoa."},{"verse":2,"text":"Aua e lē savali le Atua i ala faapiopio, pe liliu foi o ia i le itu taumatau po o le itu tauagavale, pe ese foi o ia mai le mea na ia fetalai mai ai, o lea o ona ala e sao, ma o lona alafua o se taamilosaga faavavau e tasi."},{"verse":3,"text":"Ia manatua, ia manatua, e lē o le galuega a le Atua e taofia, ae o le galuega a tagata;"},{"verse":4,"text":"Aua e ui atonu e maua e se tagata faaaliga e tele, ma ia te ia le mana e fai ai galuega maoae, ae afai e mitamitavale o ia i lona lava malosi, ma ia tuu faameanoa fautuaga a le Atua, ma mulmuli i taitaiga a lona lava loto ma manaoga faaletino, o le a pa’ū o ia ma ia aumai i ona luga le tauimasui a le Atua faamasinotonu."},{"verse":5,"text":"Faauta, sa faatuatua atu ia te oe le tausiga o ia mea, ma sa patino lava ou poloaiga; ma ia manatua foi folafolaga na fai atu ia te oe, pe afai e te lē solia i latou."},{"verse":6,"text":"Faauta foi, ua faafia ona e soli o poloaiga ma tulafono a le Atua, ma e alu pea i faatauanauga a tagata."},{"verse":7,"text":"Aua, faauta, sa lē tatau ona sili atu lou fefe i tagata nai lo i le Atua. E ui ina tuu faameanoa e tagata fautuaga a le Atua, ma latou inoino i ana afioga—"},{"verse":8,"text":"Peitai sa tatau lava ona e faamaoni; ma semanu e faaloaloa atu e ia lona aao ma lagolago ia te oe e faasaga i u fanafana mu uma a le fili; ma semanu e faatasi atu o ia ma oe i taimi uma o puapuaga."},{"verse":9,"text":"Faauta, o oe o Iosefa, ma sa filifilia oe e faia le galuega a le Alii, ae ona o le solitulafono, afai e te lē faaeteete, o le a e pa’ū."},{"verse":10,"text":"Ae ia manatua, ua alofa mutimutivale le Atua; o lea, salamo i lena mea na e faia ua lē tusa ai ma le poloaiga na Ou tuu atu ia te oe, ma ua filifilia pea oe, ma ua toe valaaulia oe i le galuega;"},{"verse":11,"text":"Vagana ai ua e faia lenei mea, o le a tuu atu oe ma avea ai e pei o isi tagata, ma lē toe maua se meaalofa."},{"verse":12,"text":"Ma ina ua e tuu atu lena mea na tuu atu e le Atua ia te oe le vaaiga ma le mana e faaliliu ai, sa e tuu atu lena mea ua paia i lima o se tagata amioleaga,"},{"verse":13,"text":"O lē na ia tuu faameanoa fautuaga a le Atua, ma ua ia solia folafolaga sili ona paia sa faia i luma o le Atua, ma faalagolago i lona lava manatu ma mitamitavale i lona lava poto."},{"verse":14,"text":"Ma o le pogai lenei ua aveesea ai mai ia te oe ou faamanuiaga mo se vaitau—"},{"verse":15,"text":"Ona sa e tuu le fautuaga a lou faatonu ia solia i lalo mai le amataga."},{"verse":16,"text":"Ae ui i lea, o le a alu pea i luma la’u galuega, ona e tusa ai ma le alu atu i le lalolagi o le malamalama e uiga i se Faaola, e ala atu i le molimau a tagata Iutaia, o le a faapea lava ona alu atu o le malamalama e uiga i se Faaola i lo’u nuu—"},{"verse":17,"text":"Ma ia sa Nifaē, ma sa Iakopō, ma sa Iosefā, ma sa Soramā, e ala atu i le molimau a o latou tamā—"},{"verse":18,"text":"Ma o lenei molimau o le a oo atu i le malamalama o sa Lamanā, ma sa Lemuelū, ma sa Isamaelī, o e na faaitiitia i le lē talitonu ona o le amioletonu o o latou tamā, o e na tuu e le Alii e faaumatiaina o latou uso o sa Nifaē, ona o a latou amioletonu ma a latou mea inosia."},{"verse":19,"text":"Ma o le faamoemoega tonu lava lenei na faasaoina ai nei papatusi, ia ua i ai nei talafaamaumau—ina ia mafai ona faataunuuina o folafolaga a le Alii, na faia e ia i lona nuu;"},{"verse":20,"text":"Ma ina ia mafai ona o mai ai o sa Lamanā i le malamalama o o latou tamā, ma ina ia latou iloa ai folafolaga a le Alii, ma ina ia mafai ai ona latou talitonu i le talalelei ma faalagolago i galuega a Iesu Keriso, ma faamamaluina e ala i le faatuatua i lona suafa, ma ina ia faaolaina i latou e ala i lo latou salamo. Amene."}]},{"chapter":4,"verses":[{"verse":1,"text":"O Lenei faauta, ua lē pine ona oo mai o se galuega ofoofogia i le fanauga a tagata."},{"verse":2,"text":"O lea, outou o e e o atu i le galuega a le Atua, vaai ia outou auauna atu ia te ia ma o outou loto atoa, mafaufau atoa, manatu atoa, ma le malosi atoa, ina ia mafai ona outou tutu ma le lē pōnā i luma o le Atua i le aso gataaga."},{"verse":3,"text":"O lea, afai ua ia te outou le manao e auauna atu i le Atua, ua valaaulia outou i le galuega;"},{"verse":4,"text":"Aua faauta ua sinasina le fanua ua saunia e selesele; ma faauta, o ia o lē e sasau atu lana selesaito ma lona malosi, o ia lava lea ua na faaputu ma teu ina ia lē fano o ia, ae aumai e ia le olataga i lona agaga;"},{"verse":5,"text":"Ma o le faatuatua, faamoemoe, alofa mama ma le alofa, ma le manatu tasi i le mamalu o le Atua, e agavaa ai o ia mo le galuega."},{"verse":6,"text":"Ia manatua le faatuatua, amiomamā, poto, faautauta, onosai, agalelei faaleuso, amio-atua, alofa mama, lotomaualalo, filiga."},{"verse":7,"text":"Ole atu, ma o le a outou maua ai; tuitui atu, ma o le a tatala mai ia te outou. Amene."}]},{"chapter":5,"verses":[{"verse":1,"text":"Faauta, Ou te fai atu ia te oe, ona ua manao la’u auauna o Matini Harisi i se molimau mai lo’u lima, e faapea ua ia te oe, o la’u auauna, o Iosefa Samita, Le Itiiti, papatusi na e molimau ma tautino atu na e maua mai ia te a’u;"},{"verse":2,"text":"Ma o lenei, faauta, o le mea lenei ia e fai atu ia te ia—o ia o lē na fetalai mai ia te oe, na fai mai ia te oe: O A’u, o le Alii, o le Atua, ma na Ou tuu atu ia te oe, o la’u auauna o Iosefa Samita, Le Itiiti, nei mea, ma ua Ou poloaiina oe e tatau ona e tulai o se molimau o nei mea;"},{"verse":3,"text":"Ma sa Ou faia ia e ulu mai i se feagaiga faatasi ma a’u, o le a e lē faaalia atu ia mea vagana ai ia i latou na o tagata o e na Ou poloaiina ai oe; ma ua leai sau pule i luga o ia mea vagana ai ua Ou tuu atu ia te oe."},{"verse":4,"text":"Ma ua ia te oe se meaalofa e faaliliu ai papatusi; ma o le meaalofa muamua lenei Ou te faaee atu i ou luga; ma ua Ou poloaiina ia leai se isi meaalofa e tatau ona e manatu i ai seia oo ina faataunuuina lo’u faamoemoe i lenei mea; ona e leai se isi meaalofa Ou te tuu atu ia te oe seia maea."},{"verse":5,"text":"E moni, Ou te fai atu ia te oe, o le a oo mai le ōi i e o nonofo i le lalolagi pe afai latou te lē faalogo mai i a’u upu;"},{"verse":6,"text":"Aua a mavae nei o le a faauuina oe ma e alu atu ma avatu a’u upu i le fanauga a tagata."},{"verse":7,"text":"Faauta, afai latou te lē talitonu i a’u upu, o le a latou lē talitonu ia te oe, la’u auauna e, Iosefa, e tusa pe a na mafai ona e faaali atu ia te i latou mea uma ua Ou tuu atu ia te oe."},{"verse":8,"text":"E, lenei tupulaga e lē talitonu ma le ua maaa—ua sasao a’e lo’u ita e faasaga ia te i latou."},{"verse":9,"text":"Faauta, e moni Ou te fai atu ia te oe, na Ou faasaoina mea na ua Ou faatuatuaina atu ia te oe, la’u auauna, Iosefa, mo se faamoemoega poto ua ia te a’u, ma o le a faailoa atu i tupulaga o lumanai;"},{"verse":10,"text":"Ae o le tupulaga lenei o le a latou maua la’u upu e ala atu ia te oe;"},{"verse":11,"text":"Ma e faaopoopo i lau molimau, le molimau a le toatolu o a’u auauna, o e o le a Ou valaaulia ma faauuina, o e o le a Ou faaali atu i ai nei mea, ma o le a latou o atu ma a’u upu e tuu atu e ala atu ia te oe."},{"verse":12,"text":"Ioe, o le a latou iloa ma le mautinoa ua moni nei mea, ona o le a Ou tautinoina atu ia te i latou mai le lagi."},{"verse":13,"text":"O le a Ou tuu atu ia te i latou le mana e mafai ai ona latou vaai ma tagatagai i nei mea e pei ona i ai;"},{"verse":14,"text":"Ma e leai ni isi i totonu o lenei tupulaga e ese mai ai o le a Ou tuu atu i ai lenei mana, ia mauaina lenei molimau, i le amataga lenei o le fanae ma le oo mai o la’u ekalesia i fafo na i le vao—ua manino e pei o le masina, ma susulu e pei o le la, ma matautia e pei o se autau ua i ai ni tagavai."},{"verse":15,"text":"Ma o le a Ou auina atu le mau a molimau e toatolu e uiga i la’u upu."},{"verse":16,"text":"Faauta foi, ai se e talitonu i a’u upu, o i latou ia o le a Ou asiasi atu i ai ma le faaaliga a lo’u Agaga; ma o le a fanauina i latou ia te a’u, i le vai lava ma le Agaga—"},{"verse":17,"text":"Ma e ao ina outou faatalitali pea laitiiti teisi, ona e lei faauuina outou—"},{"verse":18,"text":"Ma o le a alu atu foi la latou molimau mo le tausalaina o lenei tupulaga pe afai latou te faamaaa o latou loto e faasaga ia te i latou;"},{"verse":19,"text":"Ona o le a oo atu se sasa faatafunaga ia i latou o e o nonofo i le lalolagi, ma o le a faaauau ona sasaa mai lea taimi i lea taimi, pe afai latou te lē salamo, seia oo ina gaogao le lalolagi, ma ua susunuina e ua nonofo ai ma matua faaumatia lava i le pupula o lo’u oo mai."},{"verse":20,"text":"Faauta, Ou te tau atu ia te oe nei mea, e pei lava foi ona sa Ou tau atu i tagata e uiga i le faafanoga o Ierusalema; ma o le a faamaonia la’u ’upu i le taimi nei e pei lava ona sa faamaonia e oo mai i le taimi nei."},{"verse":21,"text":"Ma o lenei Ou te poloai atu ia te oe, la’u auauna Iosefa, ia e salamo ma savali sao atili i o’u luma, ma ia e lē toe tuu atu i faatauanauga a tagata;"},{"verse":22,"text":"Ma ia e tumau i le tausiga o poloaiga ua Ou poloaiina ai oe; ma afai e te faia lenei mea, faauta Ou te tuu atu ia te oe le ola e faavavau, e tusa pe fasiotia oe."},{"verse":23,"text":"Ma o lenei, Ou te toe tautala atu ia te oe, la’u auauna Iosefa, e uiga i le tagata o lē ua manao i le molimau—"},{"verse":24,"text":"Faauta, Ou te fai atu ia te ia, ua ia faamaualugaina o ia lava ma ua lē lava ona ia faamaualalo o ia lava i o’u luma; ae afai e ifo o ia i lalo i o’u luma, ma faamaualalo o ia lava i le tatalo malosi ma le faatuatua, i le faamaoni o lona loto, ona Ou tuu atu lea ia te ia se vaaiga o mea ua manao o ia e vaai i ai."},{"verse":25,"text":"Ma ona ia fai atu lea i tagata o lenei tupulaga: Faauta, ua Ou vaai i mea na faaali mai e le Alii ia Iosefa Samita, Le Itiiti, ma ua Ou iloa ma le mautinoa ua moni i latou, aua ua Ou vaai i ai, ona sa faaali mai i latou ia te a’u i le mana o le Atua a e lē o le tagata."},{"verse":26,"text":"Ma o A’u o le Alii Ou te poloai atu ia te ia, la’u auauna lea o Matini Harisi, ia lē toe fai atu e ia ni isi upu ia te i latou e uiga i ia mea, vagana ai le fai atu o ia: Ua Ou vaai i ia mea, ma sa faaali mai i latou ia te a’u i le mana o le Atua; ma o upu ia ia fai atu e ia."},{"verse":27,"text":"Ae afai e faafiti e ia lenei mea o le a soli e ia le feagaiga na ia osifeagaiga muamua ai ma a’u, faauta foi, o le a tausalaina o ia."},{"verse":28,"text":"Ma o lenei, vagana ai ua faalotomaualalo e ia o ia lava ma tautau mai ia te a’u mea sese na ia faia, ma osifeagaiga ma a’u o le a ia tausia a’u poloaiga, ma faatino le faatuatua mai ia te a’u, faauta, Ou te fai atu ia te ia, o le a lē maua e ia ni vaaiga faapena, ona o le a Ou lē tuuina atu ia te ia ni vaaiga o mea ua Ou tautala atu ai."},{"verse":29,"text":"Ma afai o le tulaga lea e i ai, Ou te poloai atu ia te oe, la’u auauna Iosefa, ia e fai atu ia te ia, ia lē toe faia e ia se mea, pe toe faalavelave mai ia te a’u e uiga i lenei mataupu."},{"verse":30,"text":"Ma afai o le tulaga lea e i ai, faauta, Ou te fai atu ia te oe Iosefa, a uma ona e faaliliu o ni isi itulau itiiti, ona e taofi lea mo se vaitau, seia oo ina Ou toe poloaiina oe; ona mafai ai lea ona e toe faaliliu."},{"verse":31,"text":"Ma vagana ai ua e faia lenei mea, faauta, o le a e lē toe mauaina se meaalofa, ma o le a Ou aveese mea na Ou faatuatuaina atu ia te oe."},{"verse":32,"text":"Ma o lenei, ona ua Ou muai iloa le lamalamaga o faatalitali mai e faaumatia oe, ioe, ua Ou muai iloa afai e lē faalotomaualaloina e la’u auauna o Matini Harisi o ia lava ma maua se molimau mai lo’u lima, o le a pa’ū atu o ia i le solitulafono;"},{"verse":33,"text":"Ma e toatele o loo faapupuna faatalitali mai e faaumatia ese oe mai luga o le fogaeleele; ma o le pogai lenei, ina ia mafai ona faalevalevaina o ou aso, ua Ou tuu atu ai ia te oe nei poloaiga."},{"verse":34,"text":"Ioe, o le pogai lenei na Ou fai atu ai: Ia taofi, ma tu lē gaoioi, seia Ou poloaiina oe, ma o le a Ou saunia ala e mafai ai ona e faataunuu o le mea ua Ou poloaiina ai oe."},{"verse":35,"text":"Ma afai e te faamaoni i le tausiga o a’u poloaiga, o le a siitia a’e oe i luga i le aso gataaga. Amene."}]},{"chapter":6,"verses":[{"verse":1,"text":"Ua Lē pine ona oo mai o se galuega tele ma le ofoofogia i le fanauga a tagata."},{"verse":2,"text":"Faauta, o A’u o le Atua; ia uai mai i la’u upu, lea ua vave ma mamana, ua sili atu le maai nai lo se pelu mata-lua, e vavae ai sooga o ivi ma le su; o lea ia uai mai ai i a’u upu."},{"verse":3,"text":"Faauta, ua sinasina le fanua ua saunia e selesele; o lea, ai se e fia selesele, ia tuu ia te ia e sasau atu lana selesaito ma lona malosi, ma selesele mai manū o ao, ina ia mafai ona ia teu mo lona agaga le olataga tumau e faavavau i le malo o le Atua."},{"verse":4,"text":"Ioe, ai se tasi e sasau atu lana selesaito ma selesele mai, o ia lava lea ua valaaulia e le Atua."},{"verse":5,"text":"O lea, afai tou te ole mai ia te a’u o le a outou mauaina; afai tou te tuitui mai o le a tatala atu ia te outou."},{"verse":6,"text":"O lenei, ona ua oulua ole mai, faauta, Ou te fai atu ia te oulua, tausi i a’u poloaiga, ma saili e aumai i luma ma faatu le faamoemoe o Siona."},{"verse":7,"text":"Aua le saili mo ’oa ae mo le poto, ma faauta, o le a fofola atu ia te oe mealilo a le Atua, ona faamauoaina ai lea o oe. Faauta, o ia o lē ua ia maua le ola e faavavau, ua mauoa o ia."},{"verse":8,"text":"E moni, e moni, Ou te fai atu ia te oe, e pei ona e manao mai ai ia te a’u, o le a faapea lava ona tuu atu ia te oe; ma afai e te manao i ai, o le a avea oe ma ala o le faia o mea lelei e tele i le tupulaga lenei."},{"verse":9,"text":"Ia leai se mea e te fai atu i lenei tupulaga tau lava o le salamo; tausi i a’u poloaiga, ma fesoasoani e aumai i luma la’u galuega, e tusa ma a’u poloaiga, ma o le a faamanuiaina oe."},{"verse":10,"text":"Faauta, ua ia te oe se meaalofa, ma amuia oe ona o lau meaalofa. Ia manatua ua paia ma ua sau mai lugā—"},{"verse":11,"text":"Ma afai e te ole atu, o le a e iloa mealilo ua silisili ma ofoofogia; o lea ia e faaaoga ai lau meaalofa, ina ia mafai ona e iloa o mealilo, ina ia mafai ona e aumai o le toatele i le malamalama o le upumoni, ioe, e faatalitonu ai i latou i le sese o o latou ala."},{"verse":12,"text":"Aua le faailoa atu lau meaalofa i se tasi vagana ai i latou o e o lou faatuatuaga. Aua le faatauvaaina mea paia."},{"verse":13,"text":"Afai e te faia mea lelei, ioe, ma tumau faamaoni e oo i le iuga, o le a faaolaina oe i le malo o le Atua, o le meaalofa aupito silisili lea o meaalofa uma a le Atua; ona ua leai se meaalofa e sili atu nai lo le meaalofa o le olataga."},{"verse":14,"text":"E moni, e moni, Ou te fai atu ia te oe, amuia oe ona o mea ua e faia; aua sa e ole mai ia te a’u, ma faauta, o le tele o taimi na e ole mai ai na e maua ai faatonuga mai lo’u Agaga. A na fai e lē faapea, po ua e lē oo mai i le mea ua e i ai i le taimi nei."},{"verse":15,"text":"Faauta, ua e iloa na e ole mai ia te a’u ma sa Ou faapupulaina lou mafaufau; ma o lenei ua Ou tau atu ia te oe nei mea ina ia mafai ona e iloa ai sa faapupulaina oe e le Agaga o le upumoni;"},{"verse":16,"text":"Ioe, ua Ou tau atu ia te oe, ina ia mafai ona e iloa e leai lava se tasi ae ua nao le Atua ua ia silafia ou mafaufauga ma faamoemoega o lou loto."},{"verse":17,"text":"Ua Ou tau atu ia te oe nei mea o se molimau ia te oe—o upu po o le galuega na e tusia ua moni."},{"verse":18,"text":"O lea ia e filiga; tulai i tafatafa o la’u auauna, o Iosefa, ma le faamaoni, i soo se tulaga faigata atonu e i ai o ia, ona o le afioga."},{"verse":19,"text":"Timai atu ia te ia i ona sese, ma ia e talia foi timaiga mai ia te ia. Ia onosai; ia faamamalu; ia faautauta; ia ia te oe le faapalepale, faatuatua, faamoemoe ma le alofa mama."},{"verse":20,"text":"Faauta, o oe o Oliva, ma ua Ou tautala atu ia te oe ona o ou manao; o lea ia teu nei upu i lou loto. Ia e faamaoni ma filiga i le tausiga o poloaiga a le Atua, ma o le a Ou siomia ai oe i lima o lo’u alofa."},{"verse":21,"text":"Faauta, o A’u o Iesu Keriso, o le Atalii o le Atua. O A’u lava lea na sau i lo’u lava nuu, ae sa lē talia a’u e lo’u lava nuu. O A’u o le malamalama ua susulu i le pouliuli, ae ua lē malamalama i ai le pouliuli."},{"verse":22,"text":"E moni, e moni, Ou te fai atu ia te oe, afai e te manao i se isi molimau, liliu ane lou mafaufau i le po na e tagi mai ai ia te a’u i lou loto, ina ia mafai ona e iloa e uiga i le moni o nei mea."},{"verse":23,"text":"Ou te lei tautala atu ea le filemu i lou mafaufau e uiga i le mataupu? O le a se molimau sili atu e mafai ona e maua mai lo lena mai le Atua?"},{"verse":24,"text":"Ma o lenei, faauta, ua e maua se molimau; aua afai ua Ou tau atu ia te oe mea e leai se tagata na te iloaina, ua e lē mauaina ea se molimau?"},{"verse":25,"text":"Ma, faauta, Ou te tuu atu ia te oe se meaalofa, pe afai e te manao i ai mai ia te a’u, e faaliliu, e pei lava o la’u auauna o Iosefa."},{"verse":26,"text":"E moni, e moni, Ou te fai atu ia te oe, o loo i ai ni talafaamaumau ua i ai i totonu le tele o la’u talalelei, sa taofia ona o le amioleaga o tagata;"},{"verse":27,"text":"Ma o lenei Ou te poloai atu ia te oe, afai ua ia te oe manaoga lelei—se manao lea ia teu mo oe lava ni ’oa i le lagi—ona mafai lea ona e fesoasoani e aumai i le malamalama, ma lau meaalofa, o vaega na o a’u tusitusiga paia lea sa natia ona o le amioletonu."},{"verse":28,"text":"Ma o lenei, faauta, Ou te tuu atu ia te oe, ma la’u auauna foi o Iosefa, ki o lenei meaalofa, o le a aumai ai i le malamalama lenei auaunaga; ma o fofoga o molimau e toalua pe toatolu e faamautu ai upu uma."},{"verse":29,"text":"E moni, e moni, Ou te fai atu ia te oulua, afai latou te teena a’u upu, ma le vaega lenei o la’u talalelei ma la’u auaunaga, amuia oulua, ona e lē mafai ona sili atu se mea latou te faia ia te oulua nai lo ia te a’u."},{"verse":30,"text":"Ma e tusa pe latou te faia ia te oulua e pei lava ona sa latou faia ia te a’u, amuia oulua, ona o le a oulua mau faatasi ma a’u i le mamalu."},{"verse":31,"text":"Ae afai latou te lē teena a’u upu, ia o le a faamautuina i le molimau o le a tuu atu, amuia i latou, ma ona oulua maua ai lea o le olioli i le fua o a oulua galuega."},{"verse":32,"text":"E moni, e moni, Ou te fai atu ia te oulua, e pei ona ou fai atu i o’u soo, o le mea e potopoto faatasi ai le toalua po o le toatolu i lo’u igoa, e faatatau i se mea e tasi, faauta, o iina o le a Ou i ai i le lotolotoi o i latou—e faapei lava ona Ou i ai ia te oulua."},{"verse":33,"text":"Aua le fefefe e fai mea lelei, o’u atalii e, auā o soo se mea e te lua lulu, o lena foi o le a oulua selesele; o lea, afai lua te luluina le lelei o le a oulua seleseleina foi le lelei mo lo oulua taui."},{"verse":34,"text":"O lea, aua le matatau, le lafu itiiti e; fai mea lelei; ia tuu le lalolagi ma seoli e aufaatasi faasaga mai ia te oulua, auā afai ua lua atia’e i luga o la’u papa, e lē mafai ona latou manumalo."},{"verse":35,"text":"Faauta, ou te lē tausalaina oulua; o i o oulua ala ma ia lē toe agasala; fai ma le mamalu le galuega ua Ou poloaiina ai oulua."},{"verse":36,"text":"Vaai mai ia te a’u i mafaufauga uma; aua le masalosalo, aua le fefefe."},{"verse":37,"text":"Faauta i manu’a ua tuia ai lo’u itu, ma tulaga fao foi i o’u lima ma o’u vae; ia faamaoni, tausi i a’u poloaiga, ma o le a oulua mautofi ai i le malo o le lagi. Amene."}]},{"chapter":7,"verses":[{"verse":1,"text":"Ma sa fetalai mai le Alii ia te a’u: Ioane e, la’u pele, o le a le mea e te manao i ai? Aua afai e te ole mai i se mea ua e manao i ai, o le a tuu atu ia te oe."},{"verse":2,"text":"Ma sa ou fai atu ia te ia: Le Alii e, tuu mai ia te a’u le mana i luga o le oti, ina ia mafai ona ou ola ma aumai agaga ia te oe."},{"verse":3,"text":"Ma sa fetalai mai le Alii ia te a’u: E moni, e moni, Ou te fai atu ia te oe, ona ua e manao mai i lenei mea, o le a e ola pea ma vavalo atu i luma o atunuu, ituaiga, gagana ma nuu, seia Ou sau i lo’u mamalu."},{"verse":4,"text":"Ma o le pogai lenei na fetalai atu ai le Alii ia Peteru: Afai Ou te loto ia ola pea o ia seia Ou sau, o le a lena mea ia te oe? Ona ua manao mai o ia ia te a’u ia mafai ona ia aumai agaga ia te a’u, ae o oe, ua e manao ia vave ona e sau ia te a’u i lo’u malo."},{"verse":5,"text":"Ou te fai atu ia te oe, Peteru, sa o se manao lelei lea; ae o la’u pele, ua manao ia faia e ia ni isi mea e tele atu, po o se galuega e lei faia i totonu o tagata e tele atu nai lo mea na ia faia muamua."},{"verse":6,"text":"Ioe, ua ia tauaveina se galuega tele atu; o lea o le a Ou faia ai o ia o se afi mumū ma se agelu auauna atu; o le a auauna atu o ia mo i latou o e e nonofo i luga o le lalolagi o e o le a avea ma suli o le olataga."},{"verse":7,"text":"Ma o le a Ou faia oe e auauna atu mo ia ma mo lou uso o Iakopo; ma o outou ia e toatolu o le a Ou tuu atu i ai lenei mana ma ki o lenei auaunaga seia Ou sau."},{"verse":8,"text":"E moni Ou te fai atu ia te oulua, o le a oulua maua e tusa ma o oulua manao, ona ua oulua olioli uma i mea ua oulua mananao i ai."}]},{"chapter":8,"verses":[{"verse":1,"text":"Oliva Kaotui e, e moni, e moni Ou te fai atu ia te oe, e pei ona mautinoa o loo soifua le Alii, o lē o lou Atua ma lou Togiola, o le a faapea lava ona mautinoa ona e maua o se malamalama e uiga i soo se mea e te ole mai ai i le faatuatua, ma le loto faamaoni, ma le talitonu o le a e maua se malamalama e uiga i togitogiga o talafaamaumau tuai, ua mai anamua, ia ua i ai vaega na o a’u tusitusiga paia na fetalaia e ala i le faaaliga a lo’u Agaga."},{"verse":2,"text":"Ioe, faauta, o le a Ou tau atu ia te oe i lou mafaufau ma lou loto, e ala i le Agaga Paia, lea o le a oo atu i ou luga ma lea o le a mau i lou loto."},{"verse":3,"text":"O lenei, faauta, o le agaga lenei o faaaliga; faauta, o le agaga lenei na aumai ai e Mose le fanauga a Isaraelu mai totonu o le Sami Ulaula i luga o le eleele matutu."},{"verse":4,"text":"O lea, o lau meaalofa lea; toaga i ai, ma amuia oe, ona o le a laveai ai oe mai lima o ou fili, lea a na le faapea, po ua latou fasioti ia te oe ma aumai lou agaga i le faafanoga."},{"verse":5,"text":"E, ia manatua nei upu, ma tausi i a’u poloaiga. Ia manatua, o lau meaalofa lea."},{"verse":6,"text":"O lenei ua lē ona pau lea o lau meaalofa; ona ua i ai ia te oe se isi meaalofa, o le meaalofa lea a Arona; faauta, ua tau atu e lena meaalofa ia te oe mea e tele;"},{"verse":7,"text":"Faauta, e leai se isi mana, vagana ai le mana o le Atua, e mafai ona faia ai lenei meaalofa a Arona ia faatasi ma oe."},{"verse":8,"text":"O lea, aua le masalosalo, ona o se meaalofa lea a le Atua; ma ia e umiaina i ou lima, ma fai ai galuega ofoofogia; ma e leai se mana e mafai ona aveesea ai mai ou lima, ona o le galuega lea a le Atua."},{"verse":9,"text":"Ma, o lea, soo se mea e te ole mai ai ia te a’u e tau atu ia te oe e ala atu i lena auala, o le a Ou tuu atu lena mea ia te oe, ma o le a e mauaina le malamalama e faatatau i ai."},{"verse":10,"text":"Ia manatua a aunoa ma le faatuatua e lē mafai ona e faia se mea; o lea ia ole mai ai i le faatuatua. Aua ne’i manatu faatauvaa i nei mea; aua le ole mai mo mea e lē tatau ona e ole mai ai."},{"verse":11,"text":"Ole mai ina ia e iloa mealilo a le Atua, ma ina ia mafai ona e faaliliu ma maua le malamalama mai talafaamaumau uma na mai anamua sa natia, ia ua paia; ma o le a faia lava ia te oe e tusa ai ma lou faatuatua."},{"verse":12,"text":"Faauta, o A’u lava ua tautala atu i nei mea; ma o A’u lava lea e tasi na tautala atu ia te oe mai le amataga. Amene."}]},{"chapter":9,"verses":[{"verse":1,"text":"Faauta, Ou te fai atu ia te oe, lo’u atalii e, ona sa e lē faaliliu e tusa ai ma le mea na e manao i ai mai ia te a’u, ma amata ona e toe tusitusi mo la’u auauna, o Iosefa Samita, Le Itiiti, ua faapea lava ona Ou manao e tatau ona e faaauau pea seia oo ina e faamaeaina lenei talafaamaumau, lea ua Ou tuuina atu ia te ia."},{"verse":2,"text":"Ma lea, faauta, ua i ai ia te a’u ni isi talafaamaumau, o le a Ou tuu atu ia te oe le mana e mafai ai ona e fesoasoani e faaliliu."},{"verse":3,"text":"Ia onosai, lo’u atalii e, ona o le poto ua ia te a’u, ma ua lē tatau ai ona e faaliliu i le taimi nei."},{"verse":4,"text":"Faauta, o le galuega ua valaaulia oe e te faia o le tusitusi lea mo la’u auauna o Iosefa."},{"verse":5,"text":"Ma, faauta, ona sa e lē faaauau pea e pei ona sa e amata mai ina ua amata ona e faaliliu, o lea na Ou aveesea ai lenei avanoa mai ia te oe."},{"verse":6,"text":"Aua e te muimui, lo’u atalii e, ona o le poto ua ia te a’u ua Ou faia ai ia te oe i lenei ala."},{"verse":7,"text":"Faauta, sa e lē malamalama; sa e manatu o le a Ou tuu atu ia te oe lena mea, ae e te lei mafaufau i ai ae na o lou ole mai ai ia te a’u."},{"verse":8,"text":"Ae, faauta, Ou te fai atu ia te oe, e ao ina e suesue i ai i lou mafaufau; ona ao lea ona e ole mai ia te a’u pe ua tonu, ma afai ua tonu, o le a Ou faia ia mu lou loto i totonu ia te oe; o lea, o le a e lagona ai ua tonu."},{"verse":9,"text":"Ae afai ua lē sao, o le a e lē maua ni lagona faapena, ae o le a e maua se mafaufauga lē manino o le a fai ia galo ai ia te oe le mea ua sese; o lea, e lē mafai ona e tusia mea ua paia vagana ai ua tuu atu ia te oe mai ia te a’u."},{"verse":10,"text":"O lenei a na e iloa lenei mea po ua mafai ona e faaliliu; ae ui i lea, ua lē tatau ona e faaliliu nei."},{"verse":11,"text":"Faauta, sa tatau ai ina ua e amata mai; peitai sa e fefe, ma ua tuanai le taimi, ma ua lē tatau nei;"},{"verse":12,"text":"Aua, ua e lē tagai ea ua Ou tuu atu i la’u auauna o Iosefa le malosi ua lava, e faalava ai? Ma Ou te lei tausalaina se tasi o oulua."},{"verse":13,"text":"Ia fai lenei mea ua Ou poloaiina ai oe, ma o le a e manuia. Ia faamaoni, ma ia lē tuu atu i se faaosoosoga."},{"verse":14,"text":"Ia tu mausali i le galuega ua Ou valaauina ai oe, ma o le a leai se lauulu o lou ulu e leiloa, ma o le a siitia a’e oe i luga i le aso gataaga. Amene."}]},{"chapter":10,"verses":[{"verse":1,"text":"O Lenei, faauta, Ou te fai atu ia te oe, ona ua e tuu atu i lima o se tagata amioleaga tusitusiga na tuu atu ia te oe le mana e faaliliu ai e ala i le Urima ma le Tumema, o lea ua leiloa ai ia te oe."},{"verse":2,"text":"Ma sa toesea foi lau meaalofa i lea lava taimi, ma sa oo ina faapouliuligia lou mafaufau."},{"verse":3,"text":"Ae ui i lea, ua toefuatai atu nei ia te oe; o lea, vaai ia e faamaoni ma faaauau pea i le faamaeaina o le toega o le galuega o le faaliliuga e pei ona e amata mai ai."},{"verse":4,"text":"Aua le momo’e televave pe galue sili atu nai lo le malosi ua ia te oe ma ala ua tuu atu e mafai ai ona e faaliliu; ae ia e filiga e oo i le iuga."},{"verse":5,"text":"Tatalo e lē aunoa, ina ia mafai ona e sau ai o lē ua manumalo; ioe, ina ia mafai ona e manumalo ia Satani, ma ina ia e sao ese mai lima o auauna a Satani ua sapasapaia lana galuega."},{"verse":6,"text":"Faauta, sa latou saili e faaumatia oe; ioe, e oo lava i le tagata o lē na e faatuatuaina na saili e faaumatia oe."},{"verse":7,"text":"Ma o le pogai lenei na Ou fai atu ai o ia o se tagata amioleaga, ona sa saili o ia e aveese mea na faatuatuaina atu ia te oe; ma sa saili foi o ia e faaumatia lau meaalofa."},{"verse":8,"text":"Ma ona ua e tuu atu tusitusiga i ona lima, faauta, ua ave i latou e tagata amioleaga mai ia te oe."},{"verse":9,"text":"O lea, ua e tuu atu i latou, ioe, ia mea ua paia, i e amioleaga."},{"verse":10,"text":"Ma, faauta, ua tuu e Satani i o latou loto e sui upu na e faia ia tusia, po o ia na e faaliliuina, lea ua tea ese atu mai ou lima."},{"verse":11,"text":"Ma faauta, Ou te fai atu ia te oe, ona ua latou suia upu, ua ese lo latou faitauina mai mea na e faaliliuina ma faia ia tusiaina;"},{"verse":12,"text":"Ma, o le ala lenei, ua saili ai le tiapolo e faataoto se fuafuaga poto, e mafai ai ona ia faaumatia lenei galuega;"},{"verse":13,"text":"Ona ua ia tuu i o latou loto ia faia lenei mea, ina ia mafai, i le pepelo, ona latou fai mai ua latou maua oe i upu na e faatagā faaliliuina."},{"verse":14,"text":"E moni, Ou te fai atu ia te oe, Ou te lē tuu atu ia faataunuu e Satani lana fuafuaga leaga i lenei mea."},{"verse":15,"text":"Aua faauta, ua tuu e ia i o latou loto e uunai oe ia e tofotofo i le Alii lou Atua, i le ole atu lea ia toe faaliliu ia upu."},{"verse":16,"text":"Ma, faauta, ona latou fai ane lea ma mafaufau i o latou loto—O le a tatou vaai pe na tuu mai e le Atua ia te ia le mana e faaliliu ai; afai na faapea, o le a ia toe tuu mai ia te ia le mana;"},{"verse":17,"text":"Ma afai e toe tuu mai e le Atua ia te ia le mana, pe afai e toe faaliliu o ia, po o, i ni isi upu, afai na te aumai upu lava ia e tasi, faauta, ua i ai ia te i tatou ia lava upu e tasi, ma ua tatou suia i latou;"},{"verse":18,"text":"O lea o le a lē tutusa i latou, ma o le a tatou fai atu ai ua pepelo o ia i ana upu, ma ua lē o ia te ia se meaalofa, ma ua lē o ia te ia se mana;"},{"verse":19,"text":"O lea o le a tatou faaumatia ai o ia, ma le galuega foi; ma o le a tatou faia lenei mea ina ia tatou lē maasiasi i le iuga, ma ina ia tatou maua viiga a le lalolagi."},{"verse":20,"text":"E moni, e moni, Ou te fai atu ia te oe, ua i ai ia Satani se uumau malosi i o latou loto; ua ia faaoso a’e i latou i le amioletonu e faasaga i mea ua lelei;"},{"verse":21,"text":"Ma ua eleelea o latou loto, ma tumu i le amioleaga ma mea inosia; ma ua latou fiafia i le pouliuli nai lo le malamalama, ona ua leaga a latou mea e fai; o lea latou te lē ole mai ai ia te a’u."},{"verse":22,"text":"Ua faaoso a’e i latou e Satani, ina ia mafai ona ia taitai atu o latou agaga i le faafanoga."},{"verse":23,"text":"Ma ua faapea ona ia faataoto o se fuafuaga poto, i le manatu e faaumatia ai le galuega a le Atua; ae o le a Ou manaomia lenei mea mai o latou lima, ma o le a liliu i lo latou maasiasi ma tausalaga i le aso o le faamasinoga."},{"verse":24,"text":"Ioe, ua ia faaoso a’e o latou loto ia feitai e faasaga i lenei galuega."},{"verse":25,"text":"Ioe, ua ia fai atu ia te i latou: Ia taufaasese ma lamalama e pu’e, ina ia mafai ona outou lepeti; faauta, ua lē o se mea e leaga lenei mea. Ma ua faapea ona ia faasee o i latou, ma fai atu ia te i latou e lē o se agasala le pepelo ina ia latou maua ai se tagata i se pepelo, ina ia mafai ona latou faaumatia o ia."},{"verse":26,"text":"Ma ua faapea ona ia faasee o i latou, ma taitai ai i latou seia oo ina tosoina e ia o latou agaga i lalo i seoli; ma ua faapea ona ia faia ia te i latou, ia maua ai i latou lava i la latou lava mailei."},{"verse":27,"text":"Ma ua faapea ona alu o ia i luga ma lalo, i lea mea ma lea mea i le lalolagi, e saili e faaumatia agaga o tagata."},{"verse":28,"text":"E moni, e moni, Ou te fai atu ia te oe, oi talofa ia te ia o lē e pepelo e faasese atu ai ona ua manatu o ia ua pepelo se tasi tagata e faasese mai ai, ona o tagata faapea e lē sao mai le faamasinotonu a le Atua."},{"verse":29,"text":"O lenei, faauta, ua latou suia nei upu, ona ua fai atu Satani ia te i latou: Ua ia faaseseina outou—ma ua faapea ona ia faasee ese o i latou ia fai le amioletonu, e faaoso ai oe ia e faaosooso i le Alii lou Atua."},{"verse":30,"text":"Faauta, Ou te fai atu ia te oe, ia e le toe faaliliuina ia upu ua tea ese atu mai ou lima;"},{"verse":31,"text":"Aua, faauta, o le a latou lē faataunuuina a latou fuafuaga leaga i le pepelo e faasaga i upu na. Aua, faauta, afai e te aumai ia lava upu e tasi, o le a latou fai mai ua e pepelo ma ua e faatagā faaliliuina, ae ua e toe tetee ia te oe lava."},{"verse":32,"text":"Ma, faauta, o le a latou faasalalauina lenei mea, ma o le a faamaaa e Satani loto o tagata e faaoso ai i latou ia feitai faasaga mai ia te oe, o le a latou lē talitonu ai i a’u upu."},{"verse":33,"text":"Ua faapea ona manatu o Satani e faatoilalo lau molimau i lenei tupulaga, ina ia lē mafai ona agai ai i luma le galuega i lenei tupulaga."},{"verse":34,"text":"Ae faauta, o le poto lenei, ma ona ua Ou faaali atu ia te oe le poto, ma tuu atu ia te oe poloaiga e faatatau i nei mea, le mea e tatau ona e faia, aua le faaalia atu lenei mea i le lalolagi, seia maea ona e faataunuu o le galuega o le faaliliuga."},{"verse":35,"text":"Aua e te ofo ina ua Ou fai atu ia te oe: O le poto lenei, aua le faaalia atu lenei mea i le lalolagi—ona sa Ou fai atu, aua le faaalia atu lenei mea i le lalolagi, ina ia faasaoina ai oe."},{"verse":36,"text":"Faauta, Ou te lē o fai atu aua e te faaalia atu lenei mea i e ua amiotonu;"},{"verse":37,"text":"Ae ona e lē mafai ona e iloa i taimi uma e ua amiotonu, pe ona e lē mafai ona e iloa e ua amioleaga mai e ua amiotonu i taimi uma, o lea ua Ou fai atu ai ia te oe, ia taofi lou filemu seia Ou vaai ua tatau ai ona faailoa atu o mea uma i le lalolagi e faatatau i le mataupu."},{"verse":38,"text":"Ma o lenei, e moni Ou te fai atu ia te oe, o se tala o mea ia na e tusia, ia ua aveese atu mai ou lima, ua togitogia i luga o papatusi a Nifae;"},{"verse":39,"text":"Ioe, ma e te manatua na fai mai i tusitusiga na, e i ai se tala faapitoa tele atu e uiga i ia mea, ua tuuina mai i luga o papatusi a Nifae."},{"verse":40,"text":"Ma o lenei, ona o le tala ua togitogia i luga o papatusi a Nifae ua faapitoa tele e uiga i mea ia o le a Ou aumai, e tusa ai ma lo’u poto, i le malamalama o tagata i lenei tala—"},{"verse":41,"text":"O lea, ia e faaliliu ai togitogiga ua i ai i luga o papatusi a Nifae, i lalo seia e oo atu lava i le nofoaiga a le tupu o Peniamina, pe seia e oo atu i mea ia na e faaliliuina, ia na e taofia;"},{"verse":42,"text":"Ma faauta, ia e lomia ia mea o se talafaamaumau a Nifae; ma o le a faapea ona Ou faafemēmēa’i ai o i latou o e ua suia a’u upu."},{"verse":43,"text":"O le a Ou lē tuua ia latou faaumatia la’u galuega; ioe, o le a Ou faaali atu ia te i latou e sili atu lo’u poto nai lo le faitogafiti-poto o le tiapolo."},{"verse":44,"text":"Faauta, ua latou maua na o se vaega, po o se otootoga o le tala a Nifae."},{"verse":45,"text":"Faauta, e tele mea ua togitogia i luga o papatusi a Nifae ua tuuina mai ai ni vaaiga tetele atu e uiga i la’u talalelei; o lea, o le poto ua ia te a’u ua tatau ai ona e faaliliu o le vaega muamua lenei o togitogiga a Nifae, ma auina atu i le galuega lenei."},{"verse":46,"text":"Ma, faauta, o le vaega atoa o totoe o lenei galuega o loo i ai vaega uma na o la’u talalelei na mananao i ai a’u perofeta paia, ioe, ma o’u soo foi, ia latou talosaga, ia oo mai i lenei nuu."},{"verse":47,"text":"Ma sa Ou fai atu ia te i latou, o le a tuu atu ia te i latou lena mea e tusa ma lo latou faatuatua ia latou talosaga;"},{"verse":48,"text":"Ioe, ma o lo latou faatuatua lenei—ia oo atu i o latou uso o sa Lamanā, ma i latou uma foi o e ua avea ma sa Lamanā ona o a latou faatuiesega, la’u talalelei lea na Ou tuu atu ia te i latou ia latou talai atu."},{"verse":49,"text":"O lenei, ua lē ona pau lea—o lo latou faatuatua ia latou talosaga o lenei, ia faailoa atu foi lenei talalelei, pe afai o le a mafai ona maua e isi atunuu lenei laueleele;"},{"verse":50,"text":"Ma sa faapea ona latou tuu ai o se faamanuiaga i luga o lenei laueleele ia latou talosaga, ia mafai e soo se tasi e talitonu i lenei talalelei i lenei laueleele ona maua le ola e faavavau;"},{"verse":51,"text":"Ioe, ina ia saoloto tagata uma o soo se atunuu, ituaiga, gagana, po o se nuu po o ai lava i latou."},{"verse":52,"text":"Ma o lenei, faauta, e tusa ma lo latou faatuatua ia latou talosaga o le a Ou aumai ai le vaega lenei o la’u talalelei i le malamalama o o’u tagata. Faauta, Ou te lē aumaia e faaumatia ai mea ua latou maua, ae e ati a’e ai i luga."},{"verse":53,"text":"Ma o le pogai lenei na Ou fai atu ai: Afai e lē faamaaaina e lenei tupulaga o latou loto, o le a Ou faatuina la’u ekalesia i totonu o i latou."},{"verse":54,"text":"O lenei ua Ou lē fai atu lenei mea e faaumatia ai la’u ekalesia, ae ua Ou fai atu lenei mea e ati a’e ai i luga la’u ekalesia;"},{"verse":55,"text":"O lea, ai se tasi ua auai i la’u ekalesia, e lē tatau ona mata’u, ona o i latou ia o le a mautofi i le malo o le lagi."},{"verse":56,"text":"Ae o i latou o e e lē matatau mai ia te a’u, pe tausi i a’u poloaiga, ae ua latou atia’e ekalesia ia te i latou lava e maua ai le ’oa, ioe, o i latou uma o e e fai amioleaga ma latou atia’e le malo o le tiapolo—ioe, e moni, e moni, Ou te fai atu ia te oe, o i latou ia o le a Ou faalavelaveaina, ma faia ia tetete ma luluina e oo i le totonugalemu."},{"verse":57,"text":"Faauta, o A’u o Iesu Keriso, le Atalii o le Atua. Sa Ou sau i o’u lava, ae sa lē talia a’u e o’u lava."},{"verse":58,"text":"O A’u o le malamalama ua susulu i le pouliuli, ae ua lē malamalama i ai le pouliuli."},{"verse":59,"text":"O A’u o lē na fai atu—i o’u soo—Ua ia te A’u isi mamoe ua lē o i ai i lenei lotoa, ma e toatele e sa i ai sa lē malamalama mai ia te a’u."},{"verse":60,"text":"Ma o le a Ou faaali atu i lenei nuu sa i ai ia te a’u ni isi mamoe, ma o i latou ia o se lala o le aiga o Iakopo;"},{"verse":61,"text":"Ma o le a Ou aumai i le malamalama a latou galuega ofoofogia sa latou faia i lo’u igoa;"},{"verse":62,"text":"Ioe, ma o le a Ou aumai foi i le malamalama la’u talalelei sa aoao atu ia te i latou, ma, faauta, o le a latou lē faafitia mea ua uma ona e maua, ae o le a latou atia’e i luga, ma o le a latou aumai i le malamalama aoaoga moni o la’u mataupu faavae, ioe, ma le mataupu faavae lea e tasi ua ia te a’u."},{"verse":63,"text":"Ma Ou te faia lenei mea ina ia mafai ona Ou faatuina o la’u talalelei, ina ia mafai ona lē i ai o ni finauga e tele; ioe, ua faaoso e Satani loto o tagata i finauga e uiga i aoaoga o la’u mataupu faavae; ma ua latou sese i ia mea, ona ua latou faauiga ese tusitusiga paia ma lē malamalama ia te i latou."},{"verse":64,"text":"O lea, o le a Ou fofola atu ai ia te i latou le mealilo tele lenei;"},{"verse":65,"text":"Aua, faauta, o le a Ou faapotopotoina i latou e pei ona ofaofatai e se matuamoa lana toloai i lalo o ona apaau, pe afai latou te lē faamaaa o latou loto;"},{"verse":66,"text":"Ioe, afai latou te fia o mai, e mafai ona latou o mai, ma taumamafa saoloto i le vai o le ola."},{"verse":67,"text":"Faauta, o la’u aoaoga faavae lenei—ai se e salamo ma sau ia te a’u, o ia lava lea o la’u ekalesia."},{"verse":68,"text":"Ai se na te folafola atu, e sili a’e pe itiiti ifo nai lo lenei, ua lē a a’u lava lea, ae ua tetee ia te a’u; o lea ua lē o ia o se o la’u ekalesia."},{"verse":69,"text":"Ma o lenei, faauta, ai se ua auai i la’u ekalesia, ma tumau i la’u ekalesia e oo i le gataaga, o ia lea o le a Ou faatuina i luga o la’u papa, ma o le a lē mafai e faitotoa o seoli ona manumalo e faasaga ia te i latou."},{"verse":70,"text":"Ma o lenei, ia manatua upu a ia o lē o le ola ma le malamalama o le lalolagi, o lou Togiola, o lou Alii ma lou Atua. Amene."}]},{"chapter":11,"verses":[{"verse":1,"text":"Ua le pine ona oo mai o se galuega tele ma le ofoofogia i totonu o le fanauga a tagata."},{"verse":2,"text":"Faauta, o A’u o le Atua; uai mai i la’u upu, lea ua vave ma mamana, ua maai sili atu nai lo se pelu mata-lua, i le vavaeina o sooga ma le su o ivi; o lea ia uai mai ai i la’u upu."},{"verse":3,"text":"Faauta, ua sinasina le fanua, ua saunia e selesele; o lea, ai se e fia selesele ia tuu atu o ia e sasau atu lana selesaito ma lona malosi, ma selesele mai manū o ao, ina ia mafai ona teu e ia mo lona agaga le olataga tumau e faavavau i le malo o le Atua."},{"verse":4,"text":"Ioe, ai se e fia sasau atu lana selesaito ma selesele mai, o ia lava lea ua valaaulia e le Atua."},{"verse":5,"text":"O lea, afai e te ole mai ia te a’u o le a e mauaina; afai e te tuitui mai o le a tatala atu ia te oe."},{"verse":6,"text":"O lenei, ona ua e ole mai, faauta, Ou te fai atu ia te oe, tausi i a’u poloaiga, ma saili e aumai ma faatu le faamoemoe o Siona."},{"verse":7,"text":"Aua le saili mo ’oa ae mo le poto; ma, faauta, o le a fofola atu ia te oe mealilo o le malo o le Atua, ma ona faamauoaina ai lea o oe. Faauta, o ia o lē e mauaina le ola e faavavau, ua mauoa."},{"verse":8,"text":"E moni, e moni, Ou te fai atu ia te oe, e pei ona e manao mai ia te a’u o le a faapea lava ona faia ia te oe; ma, afai e te manao i ai, o le a avea oe ma ala o le faia o mea lelei e tele i lenei tupulaga."},{"verse":9,"text":"Ia lē fai atu se mea i lenei tupulaga tau lava o le salamo. Tausi i a’u poloaiga, ma fesoasoani e aumai i luma la’u galuega, e tusa ma a’u poloaiga, ma o le a faamanuiaina ai oe."},{"verse":10,"text":"Faauta, ua ia te oe se meaalofa, pe o le a e maua se meaalofa pe afai e te manao i ai mai ia te a’u i le faatuatua, faatasi ma le loto faamaoni, i le talitonu i le mana o Iesu Keriso, po o lo’u mana lea o loo tautala atu ia te oe;"},{"verse":11,"text":"Ona, faauta, o A’u lava lea o loo tautala atu; faauta, o A’u o le malamalama e susulu atu i le pouliuli, ma Ou te tuu atu ia te oe nei upu e ala i lo’u mana."},{"verse":12,"text":"Ma o lenei, e moni, e moni, Ou te fai atu ia te oe, ia tuu atu lou faalagolago i le Agaga lena lea na te taitai ia fai mea lelei—ioe, ia fai mea sao, ia savali ma le lotomaualalo, ia faamasino ma le amiotonu; ma o lo’u Agaga lea."},{"verse":13,"text":"E moni, e moni, Ou te fai atu ia te oe, o le a Ou faaali atu ia te oe lo’u Agaga, lea o le a faapupula ai lou mafaufau, lea o le a faatumulia ai lou agaga i le olioli;"},{"verse":14,"text":"Ma ona e iloa ai lea, pe o le a e iloa i lenei mea, i le faatuatua i le talitonu mai ia te a’u o le a e mauaina, mea uma o soo se mea e te manao mai ai ia te a’u, ua faatatau i mea o le amiotonu."},{"verse":15,"text":"Faauta, Ou te poloai atu ia te oe ua lē manaomia ona e manatu e faapea ua valaaulia oe e te talai atu seia valaaulia oe."},{"verse":16,"text":"Faatali laitiiti tēisi, seia e maua la’u upu, la’u papa, la’u ekalesia, ma la’u talalelei, ina ia mafai ona e iloa ma le mautinoa la’u aoaoga faavae."},{"verse":17,"text":"Faauta ona oo lea ina, tusa ai ma ou manao, ioe, o le a faia lava ia te oe e tusa ai ma lou faatuatua."},{"verse":18,"text":"Tausi i a’u poloaiga; taofi lou filemu; aioi atu i lo’u Agaga;"},{"verse":19,"text":"Ioe, pipii mai ia te a’u ma lou loto atoa, ina ia mafai ona e fesoasoani i le aumaia i le malamalama o mea na ua fetalaia—ioe, le faaliliuga o la’u galuega; onosai seia maea ona e faataunuuina."},{"verse":20,"text":"Faauta, o lau galuega lenei, e tausi i a’u poloaiga, ioe, ma lou manatu atoa, mafaufau ma lou malosi atoa."},{"verse":21,"text":"Aua le saili e talai atu la’u upu, ae ia muamua saili ia maua la’u upu, ona matala ai lea o lou laulaufaiva; ona oo lea, afai e te manao i ai, o le a e maua lo’u Agaga ma la’u upu, ioe, le mana o le Atua i le faatalitonuina o tagata."},{"verse":22,"text":"Ae i le taimi nei ia taofi lou filemu; suesue i la’u upu lea ua uma ona tuuina atu i le fanauga a tagata, ma suesue foi i la’u upu lea o le a alu atu i totonu o le fanauga a tagata, po o lena lea o loo faaliliuina nei, ioe, seia oo ina e maua mea uma o le a Ou tuu atu i le fanauga a tagata i le tupulaga lenei, ma ona faaopoopo atu ai lea i ai o mea uma."},{"verse":23,"text":"Faauta o oe o Ailama, lo’u atalii; saili le malo o le Atua, ma o le a faaopoopo atu mea uma e tusa ma le mea ua tonu."},{"verse":24,"text":"Ati a’e i luga o la’u papa, o la’u talalelei lea;"},{"verse":25,"text":"Aua le teena le agaga o faaaliga, po o le agaga o valoaga, aua oi talofa ia te ia o lē e teena ia mea;"},{"verse":26,"text":"O lea, ia teu i totonu o lou loto seia oo mai le taimi lea ua i lo’u poto e te alu atu ai."},{"verse":27,"text":"Faauta, Ou te tautala atu ia te i latou uma ua i ai manaoga lelei, ma ua sasau atu a latou selesaito e selesele mai."},{"verse":28,"text":"Faauta, o A’u o Iesu Keriso, le Atalii o le Atua. O A’u o le ola ma le malamalama o le lalolagi."},{"verse":29,"text":"O A’u lava lea o lē na alu atu i o’u lava ae sa lē talia a’u e o’u lava;"},{"verse":30,"text":"Peitai e moni, e moni, Ou te fai atu ia te oe, o le toatele o i latou e talia a’u, o i latou lava ia o e e talitonu i lo’u igoa, o le a Ou tuu atu ia te i latou le mana e avea ai ma atalii o le Atua. Amene."}]},{"chapter":12,"verses":[{"verse":1,"text":"Ua le pine ona oo mai o se galuega tele ma le ofoofogia i le fanauga a tagata."},{"verse":2,"text":"Faauta, o A’u o le Atua; uai mai i la’u upu, lea ua vave ma mamana, ua maai sili atu nai lo se pelu mata-lua, i le vavaeina o sooga ma le su o ivi; o lea, ia uai mai ai i la’u upu."},{"verse":3,"text":"Faauta, ua sinasina le fanua ua saunia e selesele; o lea, ai se e fia selesele, ia tuu o ia e sasau atu lana selesaito ma lona malosi, ma selesele mai manū o ao, ina ia mafai ona teu e ia mo lona agaga le olataga tumau e faavavau i le malo o le Atua."},{"verse":4,"text":"Ioe, ai se e fia sasau atu lana selesaito ma selesele mai, o ia lava lea ua valaaulia e le Atua."},{"verse":5,"text":"O lea, afai e te ole mai ia te a’u o le a e maua; afai e te tuitui mai o le a tatalaina atu ia te oe."},{"verse":6,"text":"O lenei, ona ua e ole mai, faauta, Ou te fai atu ia te oe, tausi i a’u poloaiga, ma saili e aumai i luma ma faatuina le faamoemoe o Siona."},{"verse":7,"text":"Faauta, Ou te tautala atu ia te oe, ma i latou uma foi o e ua i ai manaoga e aumai i luma ma faatuina lenei galuega;"},{"verse":8,"text":"Ma e leai se tasi e mafai ona fesoasoani i lenei galuega vagana ai ua lotomaualalo o ia ma tumu i le alofa, ua i ai le faatuatua, faamoemoe, ma le alofa mama, ua faautauta i mea uma, i soo se mea e tuu atu i lana tausiga."},{"verse":9,"text":"Faauta, o A’u, o lē ua tautala atu i nei upu, o le malamalama ma le ola o le lalolagi, o lea ia uai mai ma lou malosi, ona valaaulia ai lea o oe. Amene."}]},{"chapter":13,"verses":[{"verse":1,"text":"I Luga o oulua o’u uso a auauna e, i le suafa o le Mesia, ou te faaee atu i ai le Perisitua o Arona, ua umia ki o le auaunaga a agelu, ma o le talalelei o le salamo, ma o le papatisoga i le faatofuina mo le faamagaloina o agasala; ma o le a lē toe aveesea lava lenei perisitua mai le lalolagi, seia toe osia e atalii o Levi se taulaga i le Alii i le amiotonu."}]},{"chapter":14,"verses":[{"verse":1,"text":"Ua le pine ona oo mai o se galuega tele ma le ofoofogia i le fanauga a tagata."},{"verse":2,"text":"Faauta, o A’u o le Atua; uai mai i la’u upu, lea ua vave ma manana, ua maai sili atu nai lo se pelu mata-lua, i le vavaeina o sooga ma le su o ivi; o lea ia uai mai i la’u upu."},{"verse":3,"text":"Faauta, ua sinasina le fanua ua saunia e selesele; o lea, ai se e fia selesele ia tuu atu o ia e sasau atu lana selesaito ma lona malosi, ma selesele mai manū o ao, ina ia mafai ona teu e ia mo lona agaga le olataga tumau e faavavau i le malo o le Atua."},{"verse":4,"text":"Ioe, ai se e sasau atu lana selesaito ma selesele mai, o ia lava lea ua valaaulia e le Atua."},{"verse":5,"text":"O lea, afai e te ole mai ia te a’u o le a e maua; afai e te tuitui mai o le a tatalaina atu ia te oe."},{"verse":6,"text":"Saili e aumai i luma ma faatuina la’u Siona. Tausi i a’u poloaiga i mea uma."},{"verse":7,"text":"Ma, afai e te tausia a’u poloaiga ma tumau e oo i le iuga, o le a e maua le ola e faavavau, le meaalofa silisili lea o meaalofa uma a le Atua."},{"verse":8,"text":"Ma o le a oo mai foi, afai e te ole atu i le Tamā i lo’u igoa, i le faatuatua ma le talitonu, o le a e maua le Agaga Paia, lea na te tuu atu upu, ina ia mafai ona e tulai o se molimau o mea o le a e faalogo ma vaai i ai, ma ina ia mafai foi ona e alaga atu le salamo i lenei tupulaga."},{"verse":9,"text":"Faauta, o A’u o Iesu Keriso, le Atalii o le Atua soifua, o lē na foafoaina le lagi ma le lalolagi, o se malamalama e lē mafai ona natia i le pouliuli;"},{"verse":10,"text":"O le mea lea, e ao ina Ou aumai ai i luma le atoatoaga o la’u talalelei mai Nuuese i le aiga o Isaraelu."},{"verse":11,"text":"Ma faauta, o oe o Tavita, ma ua valaaulia oe e te fesoasoani; o se mea afai e te faia, ma faamaoni, o le a e manuia faaleagaga ma faaletino, ma o le a tele lava lou taui. Amene."}]},{"chapter":15,"verses":[{"verse":1,"text":"Faalogo mai ia, la’u auauna Ioane, ma faalogo mai i upu a Iesu Keriso, lou Alii ma lou Togiola."},{"verse":2,"text":"Aua faauta, Ou te tautala atu ia te oe ma le aoaiga tuusao ma le mana, ona o lo’u lima ua i luga o le lalolagi atoa."},{"verse":3,"text":"Ma o le a Ou tau atu ia te oe le mea ua leai se tagata na te iloaina vagana ai na o a’u lava ma oe—"},{"verse":4,"text":"Ona e tele taimi na e manao mai ai ia te a’u ia e iloa le mea lea ua sili ona taua mo oe."},{"verse":5,"text":"Faauta, amuia oe ona o lenei mea, ma ona o lou tautala atu o a’u upu na Ou tuu atu ia te oe e tusa ai ma a’u poloaiga."},{"verse":6,"text":"Ma o lenei, faauta, Ou te fai atu ia te oe, o le mea o le a sili atu ona taua mo oe o le alaga atu lea o le salamo i lenei nuu, ina ia mafai ona e aumai o agaga ia te a’u, ina ia mafai ona e mapu faatasi ma i latou i le malo o lo’u Tamā. Amene."}]},{"chapter":16,"verses":[{"verse":1,"text":"Faalogo mai ia, la’u auauna Peteru, ma faalogo mai i upu a Iesu Keriso, lou Alii ma lou Togiola."},{"verse":2,"text":"Aua faauta, Ou te tautala atu ia te oe ma le aoaiga tuusao ma le mana, ona o lo’u lima ua i luga o le lalolagi atoa."},{"verse":3,"text":"Ma o le a Ou tau atu ia te oe le mea ua leai se tagata na te iloaina vagana ai na o a’u lava ma oe—"},{"verse":4,"text":"Aua e tele taimi na e manao mai ai ia te a’u ia e iloa le mea ua sili ona taua mo oe."},{"verse":5,"text":"Faauta, amuia oe ona o lenei mea, ma ona o lou tautala atu o a’u upu na Ou tuu atu ia te oe e tusa ai ma a’u poloaiga."},{"verse":6,"text":"Ma o lenei, faauta, Ou te fai atu ia te oe, o le mea e sili ona taua ia te oe o le alaga atu lea o le salamo i lenei nuu, ina ia mafai ona e aumai o agaga ia te a’u, ina ia mafai ona e mapu faatasi ma i latou i le malo o lo’u Tamā. Amene."}]},{"chapter":17,"verses":[{"verse":1,"text":"Faauta, Ou te fai atu ia te outou, e ao ina outou faalagolago i la’u upu, lea afai tou te faia ma le faamoemoe atoa o le loto, o le a outou maua se vaaiga o papatusi, ma le ufifatafata foi, le pelu a Lapana, le Urima ma le Tumema, ia na tuu atu i le uso o Iareto i luga o le mauga, i le taimi na talanoa faafesagai ai o ia ma le Alii, ma faasinoala faavavega ia na tuu atu ia Liae a’o i ai i le vao, i tuaoi o le Sami Ulaula."},{"verse":2,"text":"Ma o lo outou faatuatua, lena lava faatuatua sa i ai i perofeta o anamua, o le a outou maua ai se vaaiga o ia mea."},{"verse":3,"text":"Ma a uma ona outou maua o le faatuatua, ma uma ona outou vaai i ia mea i o outou lava mata, ia outou molimau atu e uiga ia i latou, i le mana o le Atua;"},{"verse":4,"text":"Ma ia outou faia lenei mea ina ia lē faaumatiaina la’u auauna o Iosefa Samita, Le Itiiti, ina ia mafai ona Ou faataunuuina o’u faamoemoega amiotonu i le fanauga a tagata i lenei galuega."},{"verse":5,"text":"Ma ia outou molimau atu sa outou vaai i ia mea, e pei lava ona vaai i ai la’u auauna o Iosefa Samita, Le Itiiti; ona o lo’u mana na vaai ai o ia i ai, ma o le pogai ona sa ia te ia le faatuatua."},{"verse":6,"text":"Ma ua ia faaliliuina le tusi, le vaega lava lea na Ou poloaiina ai o ia, ma e pei ona soifua lo outou Alii ma lo outou Atua, ua moni ia."},{"verse":7,"text":"O le mea lea, ua outou maua lea lava mana, ma lea lava faatuatua, ma lea lava meaalofa e pei o ia;"},{"verse":8,"text":"Ma afai tou te faia a’u poloaiga mulimuli nei, ia ua Ou tuu atu ia te outou, o le a lē manumalo faitotoa o seoli ia te outou; ona ua lava lo’u alofa tunoa mo outou, ma o le a siitia a’e outou i luga i le aso gataaga."},{"verse":9,"text":"Ma o A’u, o Iesu Keriso, lo outou Alii ma lo outou Atua, ua tautala atu i lenei mea ia te outou, ina ia mafai ona Ou faataunuuina o’u faamoemoega amiotonu mo le fanauga a tagata. Amene."}]},{"chapter":18,"verses":[{"verse":1,"text":"O Lenei, faauta, ona o le mea na manao mai ai oe, la’u auauna o Oliva Kaotui, e te fia iloa mai ia te a’u, Ou te tuu atu ai ia te oe upu nei:"},{"verse":2,"text":"Faauta, sa Ou faaali atu ia te oe, i le tele o taimi, e ala i lo’u Agaga, o mea ia na e tusia ua moni; o le mea lea ua e iloa ai ua moni i latou."},{"verse":3,"text":"Ma afai ua e iloa ua moni i latou, faauta, Ou te tuu atu ia te oe se poloaiga, ia e faalagolago i mea ua tusia;"},{"verse":4,"text":"Ona ua tusia i totonu o i latou mea uma e faatatau i le faavae o la’u ekalesia, la’u talalelei, ma la’u papa."},{"verse":5,"text":"O le mea lea, afai e te ati a’e i luga la’u ekalesia, i luga o le faavae o la’u talalelei ma la’u papa, o le a lē manumalo faitotoa o seoli e faasaga ia te oe."},{"verse":6,"text":"Faauta, ua matua le lalolagi i le amioleaga; ma ua ao ona fafagu i luga le fanauga a tagata ia salamo, o Nuuese atoa foi ma le aiga o Isaraelu."},{"verse":7,"text":"O le mea lea, ona ua uma ona papatisoina oe i lima o la’u auauna o Iosefa Samita, Le Itiiti, e tusa ma lena mea na Ou poloaiina ai o ia, ua faataunuuina e ia le mea na Ou poloaiina ai o ia."},{"verse":8,"text":"Ma o lenei, aua le ofo ua Ou valaauina o ia mo lo’u lava faamoemoe, o se faamoemoe ua iloa e a’u; o le mea lea, afai e filiga o ia i le tausiga o a’u poloaiga o le a faamanuiaina o ia i le ola e faavavau; ma o lona igoa o Iosefa."},{"verse":9,"text":"Ma o lenei, Oliva Kaotui e, Ou te tautala atu ia te oe, ma ia Tavita Uitimera foi, e ala i se poloaiga; aua, faauta, Ou te poloai atu i tagata uma i soo mea ia salamo, ma Ou te tautala atu ia te oulua, e pei ona fai ia Paulo la’u aposetolo, ona ua valaaulia oulua i lena lava valaauga e tasi na valaaulia i ai o ia."},{"verse":10,"text":"Ia manatua ua tele lava le taua o agaga i le silafaga a le Atua;"},{"verse":11,"text":"Aua, faauta, na mafatia le Alii lo oulua Togiola i le oti i la le tino; o le mea lea na mafatia o ia i le tiga o tagata uma, ina ia mafai ona salamo tagata uma ma o mai ia te ia."},{"verse":12,"text":"Ma ua toetu mai o ia mai le oti, ina ia mafai ona ia aumai o tagata uma ia te ia, i luga o tuutuuga o le salamo."},{"verse":13,"text":"Ma ua matua tele lava lona olioli i le agaga e salamo!"},{"verse":14,"text":"O le mea lea, ua valaaulia ai oulua e alaga atu le salamo i lenei nuu."},{"verse":15,"text":"Ma afai e faapea lua te galulue i o oulua aso uma i le alagaina o le salamo i lenei nuu, ma aumai, na o se agaga e toatasi ia te a’u, e matua tele lava lo oulua olioli faatasi ma ia i le malo o lo’u Tamā!"},{"verse":16,"text":"Ma o lenei, afai o le a tele lo oulua olioli faatasi ma se agaga e toatasi na oulua aumai ia te a’u i le malo o lo’u Tamā, e matua tele atu lo oulua olioli pe afai lua te aumai ni agaga e toatele ia te a’u!"},{"verse":17,"text":"Faauta, ua i o oulua luma la’u talalelei, ma la’u papa, ma la’u olataga."},{"verse":18,"text":"Ole atu i le Tamā i lo’u igoa i le faatuatua, ma le talitonu o le a oulua maua, ma o le a oulua maua ai le Agaga Paia, lea na te faaali atu mea uma e tatau ai mo le fanauga a tagata."},{"verse":19,"text":"Ma afai e lē ia te oulua le faatuatua, faamoemoe, ma le alofa mama, e leai se mea lua te mafaia."},{"verse":20,"text":"Aua le finau faasaga atu i se ekalesia, vagana ai le ekalesia a le tiapolo."},{"verse":21,"text":"Ave i o oulua luga le suafa o Keriso, ma tautala atu le upumoni ma le faamaoni."},{"verse":22,"text":"Ma o le toatele o e salamo ma papatiso i lo’u igoa, o Iesu Keriso lea, ma tumau e oo i le iuga, o i latou lava ia o le a faaolaina."},{"verse":23,"text":"Faauta, o Iesu Keriso o le suafa lea ua tuu mai e le Tamā, ma ua leai se isi igoa ua tuu mai e mafai ona faaolaina ai le tagata;"},{"verse":24,"text":"O le mea lea, e ao i tagata uma ona latou ave i o latou luga le suafa ua tuu mai e le Tamā, ona o le suafa lena o le a valaau ai i latou i le aso gataaga."},{"verse":25,"text":"O le mea lea, afai latou te lē iloa le igoa e valaau ai i latou, e lē mafai ona latou maua se nofoaga i le malo o lo’u Tamā."},{"verse":26,"text":"Ma o lenei, faauta, e toatele isi o i ai ua valaaulia e talai atu la’u talalelei i Nuuese ma i Iutaia;"},{"verse":27,"text":"Ioe, e toasefululua lava; ma o le Toasefululua o le a avea mo o’u soo, ma o le a latou ave i o latou luga lo’u igoa; ma o le Toasefululua o i latou ia o e o le a mananao latou te ave i o latou luga lo’u igoa ma le faamoemoe atoa o le loto."},{"verse":28,"text":"Ma afai latou te mananao latou te ave i o latou luga lo’u igoa ma le faamoemoe atoa o le loto, ua valaaulia i latou e o atu i le lalolagi atoa ma talai atu la’u talalelei i tagata uma."},{"verse":29,"text":"Ma o i latou ia o i latou o e ua Ou faauuina e papatiso atu i lo’u igoa, e tusa ma mea ua tusia;"},{"verse":30,"text":"Ma ua i ai i o oulua luma ia mea ua tusia; o le mea lea, e ao ina oulua faia lenei mea e tusa ai ma upu ua tusia."},{"verse":31,"text":"Ma o lenei Ou te tautala atu ia te outou, le Toasefululua—Faauta, ua lava lo’u alofa tunoa mo outou; ia outou savavali sao i o’u luma ma ia lē agasala."},{"verse":32,"text":"Ma, faauta, o outou ia o i latou o e ua faauuina ia te au e faauu ositaulaga ma aoao; e talai atu i tagata la’u talalelei, e tusa ma le mana o le Agaga Paia ua i totonu ia te outou, ma e tusa ai ma valaauga ma meaalofa a le Atua i tagata;"},{"verse":33,"text":"Ma o A’u, o Iesu Keriso, lo outou Alii ma lo outou Atua, ua tautala atu i nei mea."},{"verse":34,"text":"O nei upu ua lē mai tagata pe mai se tagata, ae ua mai ia te a’u; o le mea lea, ia outou molimau atu o nei upu ua mai ia te a’u ae ua lē mai i se tagata;"},{"verse":35,"text":"Aua o lo’u leo lea o loo tautala atu ia upu ia te outou; ona ua tuu i latou e lo’u Agaga ia te outou, ma e mafai ona outou faitauina i latou o le tasi i le isi e ala i lo’u mana; ma e lē mafai ona outou mauaina i latou vagana ai e ala i lo’u mana;"},{"verse":36,"text":"O le mea lea, e mafai ona outou molimau atu sa outou faalogo i lo’u leo, ma iloa a’u upu."},{"verse":37,"text":"Ma o lenei, faauta, Ou te tuu atu ia te oe, Oliva Kaotui, ma ia Tavita Uitimera foi, ia oulua saili mai le Toasefululua, o e o le a i ai manaoga ia na Ou tautala atu ai;"},{"verse":38,"text":"Ma o o latou manaoga ma a latou galuega o le a oulua iloa ai i latou."},{"verse":39,"text":"Ma a oulua maua i latou, ia oulua faaali atu nei mea ia te i latou."},{"verse":40,"text":"Ma ia oulua faapa’u’ū i lalo ma ifo atu i le Tamā i lo’u igoa."},{"verse":41,"text":"Ma e ao ina oulua talai atu i le lalolagi, fai atu: E ao ina outou salamo ma papatiso, i le suafa o Iesu Keriso;"},{"verse":42,"text":"Ona e ao i tagata uma ona salamo ma papatiso, ma e lē na o tane, ae o fafine, ma tamaiti o e ua oo i tausaga e tatau ai."},{"verse":43,"text":"Ma o lenei, a uma ona oulua maua o lenei faaaliga, e ao ina oulua tausi i a’u poloaiga i mea uma;"},{"verse":44,"text":"Ma o le a Ou galueaiina se galuega ofoofogia i totonu o le fanauga a tagata e ala atu i o oulua lima, mo le faatalitonuina o le toatele e uiga ia latou agasala, ina ia latou salamo, ma ina ia latou o mai i le malo o lo’u Tamā."},{"verse":45,"text":"O le mea lea, o faamanuiaga ua Ou tuu atu ia te oulua ua silisili atu i luga o mea uma."},{"verse":46,"text":"Ma a uma ona oulua maua lenei faaaliga, afai lua te lē tausi i a’u poloaiga e lē mafai ona faaolaina oulua i le malo o lo’u Tamā."},{"verse":47,"text":"Faauta, o A’u, o Iesu Keriso, lo oulua Alii ma lo oulua Atua, ma lo oulua Togiola, o le mana o lo’u Agaga ua Ou tautala atu ai. Amene."}]},{"chapter":19,"verses":[{"verse":1,"text":"O A’U o le Alefa ma le Omeka, o Keriso le Alii; ioe, o A’u lava o ia, o le amataga ma le gataaga, o le Togiola o le lalolagi."},{"verse":2,"text":"O A’u, ina ua uma ona Ou faataunuuina ma faaumaina o le finagalo o ia o lē e ona A’u, o le Tamā lava lea, e uiga ia te a’u—ina ua uma ona Ou faia o lenei mea ina ia mafai ona Ou aumai o mea uma i lalo o la’u pule—"},{"verse":3,"text":"Ma taofi le mana uma, e oo i le faaumatiaina o Satani ma ana galuega i le iuga o le lalolagi, ma le aso tele mulimuli o le faamasinoga, lea o le a Ou aumai i luga o tagata o e o nonofo ai, ma faamasino tagata uma taitoatasi e tusa ma ana galuega ma mea na ia faia."},{"verse":4,"text":"Ma e moni e ao i tagata uma ona salamo pe ua mafatia, ona o A’u, o le Atua, e lē gata."},{"verse":5,"text":"O le mea lea, Ou te lē tatalaina ai faamasinoga o le a Ou tuu atu, ae o le a o’o atu le oi, le tagitu’i, le tagiaue ma le lilivau o nifo, ioe, ia te i latou o e e maua i lo’u lima agavale."},{"verse":6,"text":"Ae ui i lea, ua lē tusia e faapea o le a leai se iuga i lenei mafatiaga, ae ua tusia o le mafatiaga e lē gata."},{"verse":7,"text":"O lenei foi, ua tusia o le malaia faavavau; o le mea lea, ua sili atu lea ona manino nai lo isi tusitusiga paia, ina ia mafai ona galue i loto o le fanauga a tagata nei mea uma mo le mamalu o lo’u igoa."},{"verse":8,"text":"O le mea lea, o le a Ou faamatala atu ai ia te outou lenei mealilo, ona ua tatau ai ia te outou ona outou iloa e pei lava o a’u aposetolo."},{"verse":9,"text":"Ou te tautala atu ia te outou o e ua filifilia i lenei mea, e pei o se tino e tasi, ina ia mafai ona outou ulu mai i lo’u malologa."},{"verse":10,"text":"Aua, faauta, ua matua tele lava mealilo o le faaleatua! Aua, faauta, o A’u e lē gata, ma o le faasalaga e tuu atu mai lo’u lima o le faasalaga e lē gata, ona o Lē Gata o lo’u igoa lea. O le mea lea—"},{"verse":11,"text":"O le faasalaga faavavau o le faasalaga a le Atua."},{"verse":12,"text":"O le faasalaga lē gata o le faasalaga a le Atua."},{"verse":13,"text":"O le mea lea, Ou te poloai atu ia te oe ia e salamo, ma tausi i poloaiga ua e maua mai le lima o la’u auauna o Iosefa Samita, Le Itiiti, i lo’u igoa;"},{"verse":14,"text":"Ma o lo’u mana malosi aoao na e maua ai ia poloaiga;"},{"verse":15,"text":"O lea Ou te poloai atu ai ia te oe ia e salamo—salamo, ne’i Ou taia oe i le tootoo o lo’u gutu, ma i lo’u toasa, ma i lo’u ita, ma tiga tele ai ou mafatiaga—o le ā le tetele o le tiga e te lē iloa, o le ā le malosi e te lē iloa, ioe, o le a le faigata ona onosaia e te lē iloa."},{"verse":16,"text":"Aua faauta, o A’u, o le Atua, na mafatia i nei mea mo tagata uma, ina ia latou lē mafatia pe afai latou te salamo;"},{"verse":17,"text":"Ae afai latou te lē salamo, o le a latou mafatia e pei lava o A’u;"},{"verse":18,"text":"O le mafatia lea na oo ia te a’u lava, o le Atua lava lea, o lē ua silisili i tagata uma, le gatete ona o le tiga, ma tafe toto ai i pu afu ninii uma, ma mafatia ai i le tino atoa ma le agaga—ma loto ia Ou lē inumia le ipu oona, ma teena ai—"},{"verse":19,"text":"Ae ui i lea, ia i ai i le Tamā le viiga, ma sa Ou inu ma faauma ai a’u tapenapenaga mo le fanauga a tagata."},{"verse":20,"text":"O le mea lea, Ou te toe poloai atu ai ia te oe ia e salamo, ne’i Ou faalotomaualaloina oe i lo’u mana malosi aoao, ma ia e ta’uta’u atu au agasala, ne’i e mafatia i nei faasalaga ua Ou tautala atu ai, o se vaega aupito itiiti, ioe, o se vaega itiiti lava na e tofo i ai i le taimi na Ou aveesea ai lo’u Agaga."},{"verse":21,"text":"Ma Ou te poloai atu ia te oe ia e lē talai atu se mea ae tau o le salamo, ma ia lē faaalia atu nei mea i le lalolagi seia o se poto lea ia te a’u."},{"verse":22,"text":"Ona e lē mafai ona latou gafatia aano o manu fasi i le taimi nei, ae o le susu e ao ina latou maua; o le mea lea, ua lē tatau ai ona latou iloa o nei mea, ne’i fano i latou."},{"verse":23,"text":"Aoao e uiga ia te a’u, ma faalogo mai i a’u upu; savali i le agamalu o lo’u Agaga, ma o le a e maua ai le filemu ia te a’u."},{"verse":24,"text":"O A’u o Iesu Keriso; na Ou sau i le finagalo o le Tamā, ma Ou te faia lona finagalo."},{"verse":25,"text":"O lenei foi, Ou te poloai atu ia te oe ia aua ne’i e manao i le ava a lē lua te tuaoi; pe e te saili le ola o lē lua te tuaoi."},{"verse":26,"text":"O lenei foi, Ou te toe poloai atu ia te oe ia aua ne’i e manumanu i au lava meatotino, a ia foai fua atu mo le lomiga o le Tusi a Mamona, lea ua i ai le upumoni ma le afioga a le Atua—"},{"verse":27,"text":"O la’u upu lea i Nuuese, ina ia mafai ona vave ona alu atu i tagata Iutaia, o e o sa Lamanā o so latou vaega o totoe, ina ia latou talitonu i le talalelei, ma lē vaai mo se Mesia e afio mai o lē ua uma ona afio mai."},{"verse":28,"text":"O lenei foi, Ou te toe poloai atu ia te oe ia e tatalo atu ma le leo faapea foi i lou loto; ioe, i luma o le lalolagi faapea foi i le mealilo, i luma o tagata faapea foi i le na o oe lava."},{"verse":29,"text":"Ma ia e folafola atu tala fiafia, ioe, faasalalau atu i luga o mauga, ma luga o nofoaga maualuluga uma, ma totonu o tagata uma e faatagaina oe e te vaai i ai."},{"verse":30,"text":"Ma ia e faia lena mea ma le lotomaualalo atoa, ma le faalagolago mai ia te a’u, ma lē faifai atu i e e faifai mai."},{"verse":31,"text":"Ma aua e te tautala e uiga i mataupu silisili, ae ia e folafola atu le salamo ma le faatuatua i le Faaola, ma le faamagaloga o agasala i le papatisoga, ma i le afi, ioe, o le Agaga Paia lava lea."},{"verse":32,"text":"Faauta, o se poloaiga tele ma le mulimuli lenei Ou te tuu atu ia te oe e uiga i lenei mataupu; aua ua lava lea mo lau savali i aso taitasi, e oo lava i le i’uga o lou ola."},{"verse":33,"text":"Ma o le a e maua le pagatia pe afai e te faatalalē i nei fautuaga, ioe, o le faafanoga lava lea o oe ma au meatotino."},{"verse":34,"text":"Foai atu se vaega o au meatotino, ioe, se vaega lava o ou fanua, ma mea uma vagana ai mea mo le tausiga o lou aiga."},{"verse":35,"text":"Totogi le aitalafu na e osifeagaiga ai ma le lomitusi. Faasaoloto oe lava mai le nofo pologa."},{"verse":36,"text":"Ia tu’ua lou fale ma lou aiga, se’i vagana ai pe a e manao e te fia vaai i lou aiga;"},{"verse":37,"text":"Ma tautala sa’oloto atu i tagata uma; ioe, tala’i atu, apoapoa’i atu, folafola atu le upumoni, i se leo tele lava, i se leo o le olioli, ma alaga atu—Osana, osana, ia faamanūina lava le suafa o le Alii le Atua!"},{"verse":38,"text":"Tatalo e lē aunoa, ma o le a Ou liligi ifo lo’u Agaga i ou luga, ma o le a tele lava lou faamanuiaga—ioe, e sili atu lava nai lo lou mauaina o ’oa o le lalolagi ma mea uma e pala o i ai."},{"verse":39,"text":"Faauta, pe mafai ea ona e faitauina nei mea e aunoa ma le olioli ma le sii a’e o lou loto i le fiafia?"},{"verse":40,"text":"Pe mafai ea ona e fetamo’ea’i solo faaumiumi e pei o se taitai tauaso?"},{"verse":41,"text":"Pe mafai ea ona e lotomaualalo ma agamalu, ma pulea oe lava ma le poto i o’u luma? Ioe, sau ia ia te a’u o lou Faaola. Amene."}]},{"chapter":20,"verses":[{"verse":1,"text":"O le fana’e mai o le Ekalesia a Keriso i nei aso amuli, i le tasi afe valu selau ma le tolu sefulu tausaga talu le afio mai o lo tatou Alii ma le Faaola o Iesu Keriso i la le tino, ua faatulagaina ma faatuina aloa’ia e tusa ma tulafono a lo tatou atunuu, i le finagalo ma poloaiga a le Atua, i le masina lona fa, ma i le aso lona ono o le masina ua ta’ua o Aperila—"},{"verse":2,"text":"O ia poloaiga na tuuina mai ia Iosefa Samita, Le Itiiti, o lē na valaauina e le Atua, ma faauuina o se aposetolo a Iesu Keriso, e avea ma toeaina muamua o lenei ekalesia;"},{"verse":3,"text":"Ma ia Oliva Kaotui, o lē foi na valaauina e le Atua, ma faauuina e ia o se aposetolo a Iesu Keriso, e avea ma toeaina lona lua o lenei ekalesia;"},{"verse":4,"text":"Ma ua faia lenei mea e tusa ai ma le alofa tunoa o lo tatou Alii ma le Faaola o Iesu Keriso, o lē e ōu le mamalu uma, i le taimi nei atoa ma le faavavau. Amene."},{"verse":5,"text":"Ina ua uma ona faaali moni mai i lenei toeaina muamua ua maua e ia se faamagaloga o ana agasala, sa toe lavelavea o ia i mea lē aoga o le lalolagi;"},{"verse":6,"text":"Ae ina ua uma ona salamo, ma faalotomaualaloina o ia lava ma le faamaoni, e ala i le faatuatua, sa tali mai le Atua ia te ia e ala i se agelu paia, o lē o ona fofoga sa pei o le uilaemo, ma o ona ofu sa mama ma papae silisili atu i luga o isi mea papae uma;"},{"verse":7,"text":"Ma tuu mai ia te ia poloaiga na musuia ai o ia;"},{"verse":8,"text":"Ma sa tuu mai ia te ia le mana mai i luga, e ala i auala na saunia muamua, e faaliliu ai le Tusi a Mamona;"},{"verse":9,"text":"Lea o loo i ai se talafaamaumau e uiga i se nuu pa’ū, ma le atoatoa o le talalelei a Iesu Keriso i Nuuese ma i Iutaia foi;"},{"verse":10,"text":"Lea na tuu mai e ala mai i le musumusuga, ma ua faamaonia i isi i le auaunaga a agelu, ma ua alaga atu i le lalolagi e i latou—"},{"verse":11,"text":"E faamaonia atu ai i le lalolagi ua moni tusitusiga paia, ma e musuia e le Atua tagata ma valaaulia i latou i lana galuega paia i ona po nei ma lenei tupulaga, e pei lava o tupulaga anamua;"},{"verse":12,"text":"Ua faaali mai ai o ia lava o le Atua e tasi o ananafi, i le asō, ma le faavavau. Amene."},{"verse":13,"text":"O lea, ona ua latou maua ni molimau sili faapea, o i latou o le a faamasinoina ai le lalolagi, le toatele lava lea o i latou o le a mulimuli ane o mai i se malamalama o lenei galuega."},{"verse":14,"text":"Ma i latou o e e taliaina i le faatuatua, ma faia le amiotonu, o le a latou maua se palealii o le ola e faavavau;"},{"verse":15,"text":"Ae o i latou o e e faamaaa o latou loto i le lē talitonu, ma tetee i ai, o le a liliu i lo latou lava tausalaga—"},{"verse":16,"text":"Ona o le Alii le Atua ua fetalaia; ma o i matou, o toeaina o le ekalesia, na faalogoina ma molimauina fetalaiga a le Afioga mamalu o i luga, o lē ia i ai le mamalu e faavavau ma faavavau lava. Amene."},{"verse":17,"text":"E ala i nei mea ona matou iloa o loo i ai se Atua i le lagi, o lē ua lē gata ma faavavau, mai le tumau e faavavau i le tumau e faavavau o le Atua lava lea e tasi e lē mafeliuliuai, o lē na faia le lagi ma le lalolagi, ma mea uma o i ai;"},{"verse":18,"text":"Ma o ia na foafoaina le tagata, o le tane ma le fafine, e tusa ma lona lava faatusa ma i ona lava foliga, na foafoa ai e ia i laua;"},{"verse":19,"text":"Ma sa tuu atu ia te i laua poloaiga e tatau ona laua alolofa ma auauna atu ia te ia, le Atua soifua moni e toatasi, ma ia nao ia lava le tagata o lē e tatau ona la tapuai atu i ai."},{"verse":20,"text":"Peitai o le soliga o nei tulafono paia na nautino ma faaletiapolo ai le tagata ma avea ai ma tagata pa’ū."},{"verse":21,"text":"O le mea lea, na tuuina mai ai e le Atua Malosi Aoao lona Atalii Pele e Toatasi, e pei ona tusia i tusitusiga paia na ua tuuina mai e uiga ia te ia."},{"verse":22,"text":"Sa mafatia o ia i faaosoosoga ae sa lē gauai atu i ai."},{"verse":23,"text":"Sa faasatauroina o ia, maliu, ma toetu mai i le lona tolu o aso;"},{"verse":24,"text":"Ma sa afio a’e i le lagi, e afio i le aao taumatau o le Tamā, e nofotupu ma le mana malosi aoao e tusa ai ma le finagalo o le Tamā;"},{"verse":25,"text":"Ina ia mafai ona faaolaina le toatele o i latou o e e talitonu ma papatiso i lona suafa paia, ma tumau i le faatuatua e oo i le iuga—"},{"verse":26,"text":"E lē nao i latou o e na talitonu ina ua mavae ona afio mai o ia i le vaeluaga o taimi, i la le tino, ae o i latou uma mai le amataga, e oo lava i le toatele sa i ai ae lei afio mai o ia, o e na talitonu i upu a perofeta paia, o e na tautatala atu e pei ona sa musuia ai i latou e le meaalofa a le Agaga Paia, o e na molimau moni mai e uiga ia te ia i mea uma, e ao ona latou maua le ola e faavavau,"},{"verse":27,"text":"Faapea foi i latou o e o le a mulimuli mai, o e e talitonu i meaalofa ma valaauga a le Atua e ala i le Agaga Paia, o lē e molimau e uiga i le Tamā ma e uiga i le Alo;"},{"verse":28,"text":"O le Tamā lea, ma le Alo, ma le Agaga Paia o ni Atua ua tasi, e lē gata ma faavavau, ua aunoa ma se gataaga. Amene."},{"verse":29,"text":"Ma ua matou iloa e ao i tagata uma ona salamo ma talitonu i le suafa o Iesu Keriso, ma tapuai atu i le Tamā i lona suafa, ma tumau i le faatuatua i lona suafa e oo i le iuga, a leai e lē mafai ona faaolaina i latou i le malo o le Atua."},{"verse":30,"text":"Ma ua matou iloa, o le tauamiotonuina e ala i le alofa tunoa o lo tatou Alii ma le Faaola o Iesu Keriso ua tonu ma faamaoni;"},{"verse":31,"text":"Ma ua matou iloa foi, o le faapaiaga e ala i le alofa tunoa o lo tatou Alii ma le Faaola o Iesu Keriso ua tonu ma moni, ia i latou uma o e e alolofa ma auauna atu i le Atua ma o latou manatu atoa, mafaufau atoa, ma le malosi atoa."},{"verse":32,"text":"Peitai ua i ai se avanoa e mafai ai ona pa’ū le tagata mai le alofa tunoa ma alu ese mai le Atua soifua;"},{"verse":33,"text":"O lea ia faaeteete ai le ekalesia ma tatalo e lē aunoa, ne’i pa’u’ū atu i latou i faaosoosoga;"},{"verse":34,"text":"Ioe, ma e oo lava ia te i latou o e ua faapaiaina ia faaeteete foi."},{"verse":35,"text":"Ma ua matou iloa o nei mea ua moni ma ua tusa ma faaaliga a Ioane, ua lē faaopoopo i ai, pe ua toese mai valoaga a lana tusi, o tusitusiga paia, po o faaaliga a le Atua o le a oo mai i se taimi mulimuli e ala mai i le meaalofa ma le mana o le Agaga Paia, le siufofoga o le Atua, po o i le auaunaga a agelu."},{"verse":36,"text":"Ma o le Alii le Atua na fetalaia; ma ia avatu le mamalu, mana ma le viiga i lona suafa paia, i le taimi nei atoa ma le faavavau. Amene."},{"verse":37,"text":"O lenei foi, i se poloaiga i le ekalesia e uiga i le faiga o le papatisoga—O i latou uma o e e faalotomaualaloina i latou lava i luma o le Atua, ma mananao e papatiso, ma o mai i luma ma loto momomo ma agaga salamo, ma molimau atu i luma o le ekalesia ua latou salamo moni ia latou agasala uma, ma ua loto e ave i o latou luga le suafa o Iesu Keriso, ua i ai se naunautai e auauna atu ia te ia e oo i le iuga, ma faaali moni mai ia latou galuega ua latou maua le Agaga o Keriso mo le faamagaloina o a latou agasala, ia talia i totonu o lana ekalesia e ala i le papatisoga."},{"verse":38,"text":"O le tiute o toeaina, ositaulaga, aoao, tiakono, ma tagata o le ekalesia a Keriso—O se aposetolo o se toeaina, ma o lona valaauga o le papatiso atu;"},{"verse":39,"text":"Ma faauu isi toeaina, ositaulaga, aoao, ma tiakono;"},{"verse":40,"text":"Ma faamanuia le areto ma le uaina—o faatusa o le tino ma le toto o Keriso—"},{"verse":41,"text":"Ma faamauina i latou o e ua papatiso i le ekalesia, ala i le faaee atu o lima mo le papatisoga i le afi ma le Agaga Paia, e tusa ai ma tusitusiga paia;"},{"verse":42,"text":"Ma aoao atu, faamalamalama atu, apoapoai atu, papatiso atu, ma leoleo le ekalesia;"},{"verse":43,"text":"Ma faamauina papatisoga o tagata o le ekalesia e ala i le faaee atu o lima, ma le tuuina atu o le Agaga Paia;"},{"verse":44,"text":"Ma taitai sauniga-lotu uma."},{"verse":45,"text":"O toeaina e taitaia lotu e pei ona taitaia ai i latou e le Agaga Paia, e tusa ai ma poloaiga ma faaaliga a le Atua."},{"verse":46,"text":"O le tiute o le ositaulaga o le talai atu, aoao atu, faamalamalama atu, apoapoai atu, ma papatiso atu, ma faamanuia le faamanatuga,"},{"verse":47,"text":"Ma asiasi atu i fale o tagata taitoatasi o le ekalesia, ma apoapoai atu ia te i latou ia tatalo faaleo ma faalilolilo ma auai atu i tiute uma faaleaiga."},{"verse":48,"text":"Ma e mafai foi e ia ona faauu isi ositaulaga, aoao, ma tiakono."},{"verse":49,"text":"Ma o ia e taitaia sauniga-lotu pe a leai se toeaina o auai;"},{"verse":50,"text":"Ae a i ai se toeaina o auai, e nao na ia talai atu, aoao atu, faamalamalama atu, apoapoai atu, ma papatiso atu,"},{"verse":51,"text":"Ma asiasi atu i fale o tagata taitoatasi o le ekalesia, ma apoapoai atu ia te i latou ia tatalo faaleo ma faalilolilo ma auai i tiute uma faaleaiga."},{"verse":52,"text":"I nei tiute uma, e fesoasoani le ositaulaga i le toeaina pe afai e i ai se tulaga e manaomia ai."},{"verse":53,"text":"O le tiute o le aoao o le leoleo lea o le ekalesia e lē aunoa, ma faatasi ma faamalosi i latou;"},{"verse":54,"text":"Ma vaai ia leai se amioletonu i totonu o le ekalesia, po o se feitagai o le tasi i le isi, po o se pepelo, faatuaupua, po o se taufaaleaga;"},{"verse":55,"text":"Ma vaai ia potopoto faatasi soo le ekalesia, ma vaai foi ia fai e tagata uma o le ekalesia o latou tiute."},{"verse":56,"text":"Ma o ia e taitaia sauniga-lotu pe a lē o i ai se toeaina po o se ositaulaga—"},{"verse":57,"text":"Ma e fesoasoani i ai tiakono i taimi uma, i ona tiute uma i le ekalesia, pe afai e i ai i se tulaga e manaomia ai."},{"verse":58,"text":"Peitai ua lē i ai i aoao po o tiakono le pule e papatiso atu ai, faamanuia ai le faamanatuga, pe faaee atu ai lima;"},{"verse":59,"text":"E ui i lea, latou te lapatai atu, faamalamalama atu, apoapoai atu, aoao atu, ma valaau atu i tagata uma ia o mai ia Keriso."},{"verse":60,"text":"O toeaina, ositaulaga, aoao, po o tiakono uma taitoatasi, ia faauuina e tusa ai ma meaalofa ma valaauga a le Atua ia te ia; ma ia faauu o ia e ala i le mana o le Agaga Paia, lea e i ai i le tagata e faauuina o ia."},{"verse":61,"text":"O toeaina ua tino i ai lenei ekalesia a Keriso, ia faapotopoto i le konafesi e faa-tasi i le tolu masina, pe mai lea taimi i lea taimi, e pei ona atofaina ma faatonuina e lenei konafesi;"},{"verse":62,"text":"Ma o ia konafesi ia faia ai soo se mataupu faale-ekalesia e tatau ona faia i lea taimi."},{"verse":63,"text":"E tatau i toeaina ona maua o latou laisene mai isi toeaina, e ala i le siilima a le aulotu ua latou auai, pe mai i konafesi."},{"verse":64,"text":"E mafai e ositaulaga, aoao, po o tiakono taitoatasi, o se na faauuina e se ositaulaga, ona ave se tusi faamaonia mai ia te ia i lea lava taimi, le tusi faamaonia lea, a tuu atu i se toeaina, o le a agavaa ai o ia mo se laisene, lea o le a tuu atu ai ia te ia le pule e fai ai tiute o lona valaauga, pe mafai ona maua e ia lea laisene mai i se konafesi."},{"verse":65,"text":"Ia leai se tagata e faauu i soo se tofi i le ekalesia lenei, i mea ua i ai se paranesi faatulagaina tatau o lea lava ekalesia, e aunoa ma le siilima a lena aulotu;"},{"verse":66,"text":"Ae o toeaina pulefaamalumalu, epikopo femalagaai, fautua maualuga, faitaulaga sili, ma toeaina, e mafai ona latou maua le avanoa o le faauu atu, i mea e lē o i ai se paranesi o le ekalesia e mafai ona fai ai o se siigalima."},{"verse":67,"text":"O peresitene taitoatasi o le perisitua maualuga (po o le toeaina pulefaamalumalu), epikopo, fautua maualuga, ma le faitaulaga sili, ia faauu e ala i le taitaiga a se aufono maualuga, po o le konafesi aoao."},{"verse":68,"text":"O le tiute o tagata o le ekalesia pe a uma ona talia o i latou e ala i le papatisoga—E tatau i toeaina po o ositaulaga ona maua se taimi ua lava, e faamalamalama atu ai mea uma e uiga i le ekalesia a Keriso ina ia latou malamalama, ae lei taumamafa i latou i le faamanatuga ma faamauina o latou papatisoga e ala i le faaee o lima o toeaina, ina ia faia mea uma i le faasologa tatau ai."},{"verse":69,"text":"Ma ia faaali atu e tagata o le ekalesia i luma o le ekalesia, ma i luma foi o toeaina, e ala i le savali ma le tautala amio-atua, ua latou agavaa i ai, ina ia mafai ona i ai o galuega ma le faatuatua e tusa ai ma tusitusiga paia—ma savavali ma le paia i luma o le Alii."},{"verse":70,"text":"E tatau i tagata taitoatasi o le ekalesia a Keriso ua i ai fanau, ona aumai i latou i toeaina i luma o le ekalesia, o e e tatau ona faaee o latou lima i luga o i latou i le suafa o Iesu Keriso, ma faamanuia i latou i lona suafa."},{"verse":71,"text":"E leai se tasi e mafai ona talia i le ekalesia a Keriso vagana ai ua oo o ia i tausaga agavaa e tatau ai i luma o le Atua, ma ua mafai ona salamo."},{"verse":72,"text":"O le papatisoga e tatau ona faia i le ala lea o le a sosoo ai, ia i latou uma o e ua salamo—"},{"verse":73,"text":"O le tagata ua valaaulia e le Atua ma ua i ai le pule mai ia Iesu Keriso e papatiso atu ai, ia o ifo i lalo i le vai faatasi ma le tagata ua tuuina mai o ia lava e papatiso, ma valaau o ia i lona igoa, ma fai atu: Ona ua tofia a’u e Iesu Keriso, ou te papatiso ia te oe i le suafa o le Tamā, ma le Alo, ma le Agaga Paia. Amene."},{"verse":74,"text":"Ona ia faatofu ai lea o ia i le vai, ma toe alu a’e ai mai le vai."},{"verse":75,"text":"E tatau ona potopoto soo faatasi le ekalesia e taumamafa i le areto ma le uaina i le faamanatuina o le Alii o Iesu;"},{"verse":76,"text":"Ma o le toeaina po o le ositaulaga ia faamanuiaina; ma o le ala lenei ia faamanuia ai e ia—ia tootuli o ia faatasi ma le ekalesia ma valaau atu i le Tamā i le tatalo faamaoni, fai atu:"},{"verse":77,"text":"Le Atua e, le Tamā Faavavau, matou te ole atu ia te oe i le suafa o lou Alo, o Iesu Keriso, ia e faamanuiaina ma faapaiaina lenei areto i agaga o i latou uma o e e fetagofi i ai, ina ia latou taumamafa i le faamanatuina o le tino o lou Alo, ma molimau atu ia te oe, le Atua e, le Tamā Faavavau, latou te loto ina ave i o latou luga le suafa o lou Alo, ma manatua pea o ia ma tausi i ana poloaiga ua ia tuuina mai ia te i latou; ina ia latou maua pea lona Agaga e faatasi ma i latou. Amene."},{"verse":78,"text":"O le ala e faamanuia ai le vai—ia ave foi e ia le ipu, ma fai atu:"},{"verse":79,"text":"Le Atua e, le Tamā Faavavau, matou te ole atu ia te oe i le suafa o lou Alo, o Iesu Keriso, ia e faamanuiaina ma faapaiaina lenei uaina i agaga o i latou uma o e e feinu ai, ina ia latou faia i le faamanatuina o le toto o lou Alo, sa faamaligiina mo i latou; ina ia latou molimau atu ia te oe, le Atua e, le Tamā Faavavau, latou te manatua pea o ia, ina ia latou maua lona Agaga e faatasi ma i latou. Amene."},{"verse":80,"text":"Soo se tasi o tagata o le ekalesia a Keriso ua solitulafono, pe maua ua faia se sese, ia faia ia te ia e pei ona faasino mai i tusitusiga paia."},{"verse":81,"text":"Ia fai ma tiute o aulotu eseese, ua tino ai le ekalesia a Keriso, le auina atu o se toatasi, pe sili atu o o latou aoao e auai i konafesi eseese e faia e toeaina o le ekalesia,"},{"verse":82,"text":"Faatasi ma se lisi o igoa o tagata eseese ua auai i latou lava faatasi ma le ekalesia talu mai le konafesi ua mavae; pe auina atu i le lima o se ositaulaga; ina ia mafai ona tausia o se lisi tatau ai o igoa uma o le ekalesia atoa i se tusi, e se tasi o toeaina, po o ai lava e tofia e isi toeaina mai lea taimi i lea taimi;"},{"verse":83,"text":"O lenei foi, pe afai e i ai ni isi ua faatea mai i le ekalesia, ina ia mafai ona soloia ese o latou igoa i fafo mai le talafaamaumau aoao o igoa o le ekalesia."},{"verse":84,"text":"O tagata uma o le ekalesia e o ese atu mai le aulotu ua latou nonofo ai, afai e o atu i se aulotu ua lē iloa ai i latou, e mafai ona latou ave o se tusi e faamaonia ai, o i latou o tagata auai ma tulelei o le ekalesia, ma e mafai ona saini lea tusi faamaonia e soo se toeaina po o se ositaulaga, pe afai o le tagata o le ekalesia e mauaina le tusi, e masani lelei ma le toeaina po o le ositaulaga, pe mafai foi ona saini e aoao po o tiakono o le ekalesia."}]},{"chapter":21,"verses":[{"verse":1,"text":"Faauta, ia i ai se tala faamaumau e tausia i totonu o outou; ma i totonu o lena tala faamaumau ia taua ai oe o se tagatavāai, o se faaliliutusi, o se perofeta, o se aposetolo a Iesu Keriso, o se toeaina o le ekalesia e ala i le finagalo o le Atua le Tamā, ma le alofa tunoa o lo outou Alii o Iesu Keriso,"},{"verse":2,"text":"O lē na musuia e le Agaga Paia e faataatia lona faavae, ma ati a’e i luga i le faatuatuaga silisili ona paia."},{"verse":3,"text":"Le ekalesia lea na faatulaga ma faavaeina i le tausaga o lo outou Alii e afe valu selau tolu sefulu, i le masina lona fa, ma i le aso ono o le masina lea ua taua o Aperila."},{"verse":4,"text":"O le mea lea, ia outou, o lona uiga o le ekalesia, uai atu i ana upu uma ma poloaiga o le a ia tuu atu ia te outou e pei ona maua e ia, ma savavali i le paia atoa i o’u luma;"},{"verse":5,"text":"Ona o lana upu ia outou talia, e pei lava ua mai i lo’u lava gutu, i le onosai ma le faatuatua atoa."},{"verse":6,"text":"Ona o le faia o nei mea o le a lē manumalo ai faitotoa o seoli ia te outou; ioe, ma o le a faamataa ese ai e le Alii le Atua mana o le pouliuli mai i o outou luma, ma faia ia luluina le lagi mo lo outou lelei, ma le mamalu o lona suafa."},{"verse":7,"text":"Ona ua faapea ona fetalai mai o le Alii le Atua: O ia ua Ou musuia na te uunai le faamoemoe o Siona i le mana malosi tele mo le lelei, ma ua Ou iloa lona filiga, ma ua Ou faalogoina ana tatalo."},{"verse":8,"text":"Ioe, ua Ou vaai i ana auega mo Siona, ma o le a Ou faia ina ia lē toe faanoanoa o ia mo ia; ona ua oo mai ona aso o le olioli i le faamagaloina o ana agasala, ma le faailoaina o a’u faamanuiaga i luga o ana galuega."},{"verse":9,"text":"Aua, faauta, o le a Ou faamanuiaina i latou uma o e e galulue i lo’u tovine i se faamanuiaga tele, ma o le a latou talitonu i ana upu e tuu atu ia te ia e le Fesoasoani e ala atu ia te a’u, ia e molimauina o Iesu na faasatauroina e tagata e tumu i le agasala mo agasala a le lalolagi, ioe, mo le faamagaloina o agasala a lē ua loto salamo."},{"verse":10,"text":"O le mea lea ua tatau ai ia te a’u ona faauuina o ia e oe, Oliva Kaotui la’u aposetolo;"},{"verse":11,"text":"Ona o lenei mea o se sauniga ia te oe, o oe o se toeaina i lalo o lona lima, ona e muamua o ia ia te oe, ina ia avea oe o se toeaina i le ekalesia lenei a Keriso, ua tauaveina lo’u igoa—"},{"verse":12,"text":"Ma o le failauga muamua o lenei ekalesia i le ekalesia, ma luma o le lalolagi, ioe, i luma o Nuuese; ioe, ma ua faapea ona fetalai mai o le Alii le Atua, faauta, faauta! i tagata Iutaia foi. Amene."}]},{"chapter":22,"verses":[{"verse":1,"text":"Faauta, Ou te fai atu ia te outou, ua Ou faia ia faamutaina i lenei mea feagaiga tuai uma; ma o se feagaiga fou ma tumau e faavavau lenei, lea lava sa i ai mai le amataga."},{"verse":2,"text":"O le mea lea, e ui ina papatiso faaselau se tagata e lē aoga lava ia te ia, ona e lē mafai ona outou ulu atu i le faitotoa vaapiapi e ala i le tulafono a Mose, pe ala ia outou galuega mamate."},{"verse":3,"text":"Auā ona o a outou galuega mamate ua Ou faia ai lenei feagaiga mulimuli ma lenei ekalesia ia ati a’e i luga ia te a’u, e pei lava o aso anamua."},{"verse":4,"text":"O le mea lea, ia outou ulu mai i totonu i le faitotoa, e pei ona Ou poloaiina, ma aua le saili e fautua i lo outou Atua. Amene."}]},{"chapter":23,"verses":[{"verse":1,"text":"Faauta, Ou te tautala atu ia te oe, Oliva, ni upu itiiti. Faauta, ua faamanuiaina oe, ma ua e lē o i lalo o se tausalaga. Peitai faaeteete i le faamaualuga, ne’i e gauai atu i faaosoosoga."},{"verse":2,"text":"Faailoa atu lou valaauga i le ekalesia, ma luma foi o le lalolagi, ma o le a tatalaina lou loto e talai atu le upumoni mai le taimi nei ma le faavavau. Amene."},{"verse":3,"text":"Faauta, Ou te tautala atu ia te oe, Ailama, ni upu itiiti; ona ua lē o i ai foi oe i lalo o se tausalaga, ma ua tatalaina lou loto, ma tatalaina lou laulaufaiva; ma o lou valaauga o le apoapoai atu, ma faamalosi le ekalesia e lē aunoa. O le mea lea, o lou tiute ua i ai i le ekalesia e faavavau, ma ua pogai lenei mea ona o lou aiga. Amene."},{"verse":4,"text":"Faauta, Ou te tautala atu ni upu itiiti ia te oe, Samuelu; ona ua lē o i ai foi oe i lalo o se tausalaga, ma o lou valaauga o le apoapoai atu, ma faamalosi le ekalesia; ma e lei oo ina valaaulia oe e te talai atu i le lalolagi. Amene."},{"verse":5,"text":"Faauta, Ou te tautala atu ni upu itiiti ia te oe, Iosefa; ona ua lē o i ai foi oe i lalo o se tausalaga, ma o lou valaauga foi o le apoapoai atu, ma faamalosi le ekalesia; ma o lou tiute lenei mai le taimi nei ma le faavavau. Amene."},{"verse":6,"text":"Faauta, Ou te faaali atu ia te oe, Iosefa Knight, i upu nei, e ao ina e ave i luga lau satauro, lea e ao ai ina e tatalo ai ma le leo i luma o le lalolagi faapea foi i le mea lilo, ma i lou aiga, ma i totonu o au uo, ma i nofoaga uma."},{"verse":7,"text":"Ma, faauta, o lou tiute o le aufaatasi lea ma le ekalesia moni, ma faapito lau tautala i le apoapoai atu e lē aunoa, ina ia e maua le taui o lē e galue. Amene."}]},{"chapter":24,"verses":[{"verse":1,"text":"Faauta, na valaaulia ma filifilia oe e tusi le Tusi a Mamona, ma i la’u auaunaga; ma ua Ou siitia a’e oe i luga mai ou puapuaga, ma fautuaina oe, o lea ua laveaiina ai oe mai ou fili uma, ma ua laveaiina oe mai mana o Satani ma mai le pouliuli!"},{"verse":2,"text":"Ae ui i lea, ua lē tuufaanoia oe i au solitulafono; e ui i lea, alu i lou ala ma aua le toe agasala."},{"verse":3,"text":"Faalautele lou tofi; ma a uma ona e totoina o ou fanua ma puipui malu lelei i latou, alu atu vave i le ekalesia o loo i Kolesavile, Feiete, ma Manaseta, ma o le a latou tausia oe; ma o le a Ou faamanuia i latou faaleagaga ma faaletino;"},{"verse":4,"text":"Ae afai latou te lē talia oe, o le a Ou auina atu i o latou luga se fetuu nai lo o se faamanuiaga."},{"verse":5,"text":"Ma ia faaauau pea ona e valaau atu i le Atua i lo’u igoa, ma ia tusi mea o le a tuu atu ia te oe e le Fesoasoani, ma faamalamalama atu tusitusiga paia uma i le ekalesia."},{"verse":6,"text":"Ma o le a tuu atu ia te oe i le taimi tatau mea e te tautala atu ai ma tusia, ma o le a latou faalogo i ai, po o le a Ou auina atu ia te i latou se fetuu nai lo o se faamanuiaga."},{"verse":7,"text":"Aua ia e tuu atu lau auaunaga atoa i Siona; ma o le a e maua le malosi i lenei mea."},{"verse":8,"text":"Onosai i puapuaga, ona o le a tele o le a oo mai ia te oe; ae ia e onosaia i latou, aua, faauta, ua Ou faatasi ma oe, e oo lava i le iuga o ou aso."},{"verse":9,"text":"Ma o le a e lē maua le malosi i galuega faaletino, ona e lē o lou valaauga lea. Faasaga i lou valaaulia ma o le a e maua ai mea e faalautele ai lou tofi, ma ia faamalamalama atu tusitusiga paia uma, ma faaauau pea i le faaee atu o lima ma faamauina tagata o le ekalesia."},{"verse":10,"text":"Ma ia faaauau pea lou uso o Oliva i le tautino atu o lo’u igoa i luma o le lalolagi, ma i le ekalesia foi. Ma aua ne’i manatu o ia e faapea e mafai ona lava ona ia fai atu e uiga i lo’u faamoemoe; ma faauta, ua Ou faatasi ma ia e oo i le iuga."},{"verse":11,"text":"O a’u e maua ai e ia le mamalu, ae lē o ia lava, pe i le vaivai po o le malosi, pe i le pologa po o le saoloto;"},{"verse":12,"text":"Ma ia tatala atu e ia i taimi uma, ma i nofoaga uma, lona fofoga, ma alaga atu la’u talalelei i le ao ma le po, e pei o le leo o se pu. Ma o le a Ou tuu atu ia te ia se ituaiga o malosi e lei iloa lava i totonu o tagata."},{"verse":13,"text":"Aua le mananao i vavega, vagana ai ua Ou poloaiina ai oulua, vagana ai le tutuli i fafo o tiapolo, le faamalologa o e mamai, ma e faasaga i gata uogo, ma faasaga i mea oona e oti ai;"},{"verse":14,"text":"Ma o nei mea ia oulua lē faia, vagana ua manaomia ai oulua e i latou o e e mananao i ai, ina ia faataunuuina tusitusiga paia; aua ia oulua faia e tusa ma le mea ua tusia."},{"verse":15,"text":"Ma i soo se nofoaga e te lua ulu atu i ai, ma latou lē talia oulua i lo’u igoa, ia oulua tuu ai se fetuu nai lo o se faamanuiaga, i le tutu ese lea o le pefu o o oulua vae o se molimau e faasaga ia te i latou, ma faamama o oulua vae i le ala."},{"verse":16,"text":"Ma o le a oo mai, o soo se tasi e faaoo atu o latou lima i o oulua luga i le faasaua, ia oulua poloaiina i lo’u igoa ia taiaina; ma, faauta, o le a Ou taiaina i latou e tusa ma a oulua upu, i lo’u lava taimi e tatau ai."},{"verse":17,"text":"Ma o soo se tasi na te ave oe i le tulafono, o le a fetuu e le tulafono."},{"verse":18,"text":"Ma ia e lē ave se ’ato teutupe, po o se ato malaga, po o ni tootoo, po o ni peleue se lua, ona o le a tuu atu e le ekalesia ia te oe i le itula tonu lava mea e te manaomia mo meaai ma mo lavalava, ma mo seevae ma mo tupe, ma mo ato malaga."},{"verse":19,"text":"Ona ua valaaulia oe e te teuteu lo’u tovine i se teuga tele, ioe, mo le taimi mulimuli lava; ioe, ma i latou uma foi o e ua e faauuina, ma ia latou faia e tusa ai ma lenei lava faataitaiga. Amene."}]},{"chapter":25,"verses":[{"verse":1,"text":"Faalogo mai i le siufofoga o le Alii lou Atua, a’o Ou tautala atu ia te oe, Emma Samita, lo’u afafine e; aua e moni Ou te fai atu ia te oe, o i latou uma o e e talia la’u talalelei o atalii ma afafine i lo’u malo."},{"verse":2,"text":"Ou te tuu atu ia te oe se faaaliga e faatatau i lo’u manao; ma afai e te faamaoni ma savali i o’u luma i ala o le amiomama, o le a Ou faasaoina lou ola, ma o le a e maua se tofi i Siona."},{"verse":3,"text":"Faauta, ua faamagaloina au agasala, ma o oe o se tamaitai filifilia, o lē ua Ou valaaulia."},{"verse":4,"text":"Aua le muimui ona o mea e te le’i vaai i ai, ona ua taofia ia mea mai ia te oe ma mai le lalolagi, o le poto lea ia te a’u i se taimi o le a oo mai."},{"verse":5,"text":"Ma o le tofi o lou valaauga o le avea ma se faamafanafanaga i la’u auauna, o Iosefa Samita, Le Itiiti, lau tane, i ona puapuaga, i upu faamafanafana, i le agaga o le agamalu."},{"verse":6,"text":"Ma ia e alu faatasi ma ia i le taimi e alu ai o ia, ma avea ma tusiupu mo ia, a’o lē o i ai se tasi e avea ma tusiupu mo ia, ina ia mafai ona Ou auina atu la’u auauna, o Oliva Kaotui, i soo se mea Ou te loto i ai."},{"verse":7,"text":"Ma o le a faauuina oe i lalo o lona lima e faamalamalama atu tusitusiga paia, ma apoapoai atu i le ekalesia, e tusa ma mea o le a tuuina atu ia te oe e lo’u Agaga."},{"verse":8,"text":"Aua o le a ia faaee ona lima i ou luga, ma o le a e maua ai le Agaga Paia, ma ia tuu atu lou taimi i le tusitusi, ma le aoao tele."},{"verse":9,"text":"Ma e lē tatau ona e fefe, ona o le a lagolagoina oe e lau tane i le ekalesia; ona o lona valaauga ua ia te i latou, ina ia mafai ona faaalia o mea uma ia te i latou, i soo se mea Ou te loto i ai, e tusa ai ma lo latou faatuatua."},{"verse":10,"text":"Ma e moni Ou te fai atu ia te oe, ia e tuu ese mea o lenei lalolagi, ma saili mo mea o se lalolagi sili atu ona lelei."},{"verse":11,"text":"Ma o le a tuu atu foi ia te oe, e faia se filifiliga o viiga paia, e pei ona o le a tuu atu ia te oe, ua Ou fiafia i ai, ia i ai i la’u ekalesia."},{"verse":12,"text":"Aua e fiafia lo’u agaga i le pese o le loto; ioe, o le pese a e amiotonu o se tatalo mai ia te a’u, ma o le a talia ma se faamanuiaga i luga o o latou ulu."},{"verse":13,"text":"O le mea lea, ia siitia a’e i luga lou loto ma olioli, ma pipii atu i feagaiga ua e faia."},{"verse":14,"text":"Tumau pea i le agaga o le agamalu, ma faaeteete i le faamaualuga. Tuu atu lou agaga e fiafia i lau tane, ma le mamalu o le a oo mai i ona luga."},{"verse":15,"text":"Tausi i a’u poloaiga e lē aunoa, ma o le a e maua ai se pale o le amiotonu. Ma vagana ai ua e faia lenei mea, o le mea ua Ou i ai, e lē mafai ona e sau i ai."},{"verse":16,"text":"Ma e moni, e moni, Ou te fai atu ia te oe, o lo’u leo lenei i tagata uma. Amene."}]},{"chapter":26,"verses":[{"verse":1,"text":"Faauta, Ou te fai atu ia te outou, ia outou tuu atu lo outou taimi i le suesueina o tusitusiga paia, ma i le talai atu, ma i le faamaumauina o le aulotu i Kolesavile, ma i le faia o a outou galuega i le laueleele, e pei ona manaomia ai, seia mavae ona outou o atu i sisifo e fai le konafesi e sosoo ai; ma ona faailoa atu ai lea o le mea ia outou faia."},{"verse":2,"text":"Ma o mea uma lava i le ekalesia ia faia i le finagalo autasi, e ala i le tatalo pea lava pea ma le faatuatua, ona o mea uma lava tou te maua e ala mai i le faatuatua. Amene."}]},{"chapter":27,"verses":[{"verse":1,"text":"Faalogo mai ia i le siufofoga o Iesu Keriso, lou Alii, lou Atua, ma lou Togiola, o lana afioga e vave ma mamana."},{"verse":2,"text":"Aua faauta, Ou te fai atu ia te oe, e lē afaina po o le a le mea tou te aai ai pe o le a foi le mea tou te inu ai pe a outou taumamafa i le faamanatuga, pe afai tou te faia ma le manatu tasi i lo’u mamalu—e faamanatu ai i le Tamā lo’u tino sa fai ma taulaga mo outou, ma lo’u toto sa faamaligiina mo le faamagaloina o a outou agasala."},{"verse":3,"text":"O le mea lea, Ou te tuu atu ia te outou se poloaiga, ia aua tou te faatau mai se uaina po o se ava malosi mai i o outou fili;"},{"verse":4,"text":"O le mea lea, ia leai se uaina tou te inumia vagana ai ua faia o se uaina fou i totonu ia te outou; ioe, i le malo lenei o lo’u Tamā o le a atia’e i le lalolagi."},{"verse":5,"text":"Faauta, o le poto lenei ua ia te a’u; o le mea lea, aua le ofo, ona e oo mai le itula o le a Ou inu ai le fua o le vine faatasi ma outou i le lalolagi, ma faatasi ma Moronae, o lē na Ou auina atu ia te oe e faaali atu le Tusi a Mamona, ua i ai le atoatoaga o la’u talalelei tumau e faavavau, o lē ua Ou tuu atu i ai ki o le tala faamaumau o le laau a Efaraima;"},{"verse":6,"text":"Ma faatasi foi ma Elaia, o lē ua Ou tuu i ai ki o le faataunuuga o le toefuataiga o mea uma na fetalaia e fofoga o perofeta paia uma talu mai le amataga o le lalolagi, e faatatau i aso e gata ai;"},{"verse":7,"text":"Ma Ioane foi le atalii o Sakaria, o Sakaria lea na oo mai i ai o ia (Elaia) ma tuu mai i ai se folafolaga o le a maua e ia se atalii, ma o lona igoa o le a taua o Ioane, ma o le a tumu o ia i le agaga o Elaia;"},{"verse":8,"text":"O Ioane lea na Ou auina atu ia te oulua, a’u auauna, o Iosefa Samita, Le Itiiti, ma Oliva Kaotui, e faauu oulua i le perisitua muamua ua oulua maua, ina ia mafai ona valaaulia ma faauuina oulua e pei lava o Arona;"},{"verse":9,"text":"Ma Elia foi, o lē ua Ou tuu atu i ai ki o le mana e faaliliu ai loto o tamā i fanau, ma loto o fanau i tamā, ina ia lē taiaina le lalolagi atoa i se fetuu;"},{"verse":10,"text":"Ma faatasi foi ma Iosefa ma Iakopo, ma Isaako, ma Aperaamo, o oulua tamā, o e ua ala ai ona tumau o folafolaga;"},{"verse":11,"text":"Ma faatasi foi ma Mekaeli, po o Atamu, le tamā o tagata uma, le aloalii o tagata uma, o le anamuā o aso;"},{"verse":12,"text":"Ma faatasi foi ma Peteru, ma Iakopo, ma Ioane, o e na Ou auina atu ia te oulua, ma o e na Ou faauuina ai oulua ma faamauina ai oulua e avea o ni aposetolo, ma molimau faapitoa o lo’u igoa, ma umia ki o la oulua auaunaga ma mea lava e tasi na Ou faaali atu ia te i latou;"},{"verse":13,"text":"I e ua Ou tuu atu i ai ki o lo’u malo, ma se tisipenisione o le talalelei mo taimi mulimuli; ma mo le atoaga o taimi, lea o le a Ou faapotopoto faatasi ai mea uma i le mea e tasi, o mea o i le lagi, atoa ma mea o i le lalolagi;"},{"verse":14,"text":"Ma faatasi foi ma i latou uma o e ua tuuina mai e lo’u Tamā ia te a’u mai le lalolagi."},{"verse":15,"text":"O le mea lea, ia siitia a’e i luga o outou loto ma olioli, ma fusi i o outou sulugatiti, ma ave i o outou luga lo’u ofutau atoa, ina ia mafai ona outou teena le aso leaga, ina ua uma lea ona outou faia o mea uma, ina ia mafai ona outou tutumau ai."},{"verse":16,"text":"O lea, ia tutumau ai, ua fusi faataamilo o outou sulugatiti i le ’upumoni, ma ia faamaulu le ufifatafata o le amiotonu, ma faasee o outou vae i le sauniuniga o le talalelei o le filemu, lea na Ou auina atu a’u agelu e tuu atu ia te outou;"},{"verse":17,"text":"Ma ave le talita o le faatuatua lea o le a mafai ai ona outou tineia o ufanafana mu uma a lē ua amioleaga;"},{"verse":18,"text":"Ma ave le puloutau o le olataga, ma le pelu a lo’u Agaga, lea o le a Ou liligi ifo i o outou luga, ma la’u upu lea Ou te faaali atu ia te outou, ma ia lotogatasi e faatatau i mea uma o soo se mea tou te ole mai ai ia te a’u, ma faamaoni seia Ou alu atu, ma o le a segia a’e outou i luga, ina ia outou i ai foi i le mea Ou te i ai. Amene."}]},{"chapter":28,"verses":[{"verse":1,"text":"Faauta, Ou te fai atu ia te oe, Oliva, o le a tuu atu ia te oe ia faalogo le ekalesia ia te oe i mea uma i soo se mea o le a e aoao atu ia te i latou e ala i le Fesoasoani, e faatatau i faaaliga ma poloaiga ua Ou tuuina atu."},{"verse":2,"text":"Ae, faauta, e moni, e moni, Ou te fai atu ia te oe, e leai se tasi e tofia na te mauaina poloaiga ma faaaliga i le ekalesia lenei, vagana ai la’u auauna o Iosefa Samita, Le Itiiti, ona e maua e ia poloaiga ma faaaliga e pei lava o Mose."},{"verse":3,"text":"Ma ia e usiusitai i mea o le a Ou tuu atu ia te ia, e pei lava o Arona, e alaga atu ma le faamaoni poloaiga ma faaaliga, i le mana ma le pule i le ekalesia."},{"verse":4,"text":"Ma afai e taitaia oe i soo se taimi e le Fesoasoani e te tautala atu pe e te aoao atu, po o i taimi uma i le ala faalepoloaiga i le ekalesia, e mafai ona e faia o lea."},{"verse":5,"text":"Ae aua ne’i e tusi i le ala faalepoloaiga, ae i le poto:"},{"verse":6,"text":"Ma aua ne’i e faatonuina o ia o lē ua i lou ulu, ma ua i le ao o le ekalesia;"},{"verse":7,"text":"Aua ua Ou tuu atu ia te ia ki o mealilo, ma faaaliga ua faamaufaailogaina, seia Ou tofia mo i latou se isi i lona tulaga."},{"verse":8,"text":"Ma o lenei, faauta, Ou te fai atu ia te oe, ia e alu i sa Lamanā ma talai atu la’u talalelei ia te i latou; e tusa ai ma lo latou taliaina o au aoaoga, ia e faia ia faatuina la’u ekalesia i totonu o i latou; ma o le a e maua faaaliga, ae aua ne’i tusia i latou i le ala faalepoloaiga."},{"verse":9,"text":"Ma o lenei, faauta, Ou te fai atu ia te oe, e le’i faaalia mai, ma e leai se tagata ua iloaina le mea o le a faatuina ai le aai o Siona, ae o le a tuuina mai i se taimi mulimuli mai. Faauta, Ou te fai atu ia te oe, o le a i ai i tuaoi latalata i sa Lamanā."},{"verse":10,"text":"Aua e te tuua le nofoaga lenei seia mavae le konafesi; ma o la’u auauna o Iosefa o le a tofia e pulefaamalumalu i le konafesi i le leo o le faapotopotoga, ma o mea e fai atu ai o ia ia te oe, ia e tau atu."},{"verse":11,"text":"O lenei foi, ia e ave lou uso, o Ailama Page, i le va tau lava o ia ma oe, ma tau atu ia te ia o mea na ua ia tusia mai lena maa, ua lē mai ia te a’u, ma ua faaseseina o ia e Satani;"},{"verse":12,"text":"Aua, faauta, sa le’i tofia atu ia mea ia te ia, pe o le a tofia atu foi soo se mea i soo se tasi o le ekalesia lenei, ua lē tusa ai ma feagaiga o le ekalesia."},{"verse":13,"text":"Aua e ao ina faia mea uma i le faatulagaga tatau, ma i le finagalo autasi o le ekalesia, e ala i le tatalo o le faatuatua."},{"verse":14,"text":"Ma ia e fesoasoani e foia ia mea uma, e tusa ai ma feagaiga o le ekalesia, ae lei alu lau malaga i totonu o sa Lamanā."},{"verse":15,"text":"Ma o le a tuu atu ia te oe mai le taimi e te alu atu ai, sei oo i le taimi e te foi mai ai, mea e te faia."},{"verse":16,"text":"Ma ia e tatala atu lou gutu i taimi uma, e alaga atu la’u talalelei ma le leo o le olioli. Amene."}]},{"chapter":29,"verses":[{"verse":1,"text":"Faalogo mai ia i le siufofoga o Iesu Keriso, lo outou Togiola, le O A’u Silisili, o lona aao alofa mutimutivale ua togiola mo a outou agasala;"},{"verse":2,"text":"O lē o le a faapotopotoina ona tagata e pei ona ofaofatai e se matuamoa lana toloai i lalo o ona apaau, le toatele lea o i latou o le a faalogo mai i lo’u leo ma faamaualalalo i latou lava i o’u luma, ma valaau mai ia te a’u i le tatalo faatauanau."},{"verse":3,"text":"Faauta, e moni, e moni, Ou te fai atu ia te outou, ua faamagaloina outou mai ia outou agasala i le taimi nei, o lea ua outou maua ai ia mea; a ia manatua aua le toe agasala, ne’i oo mai tugā i o outou luga."},{"verse":4,"text":"E moni, Ou te fai atu ia te outou, ua filifilia outou mai le lalolagi e alaga atu la’u talalelei ma le leo o olioliga, e pei o le leo o se pu."},{"verse":5,"text":"Ia siitia a’e i luga o outou loto ma fiafia, ona ua Ou i ai i lo outou lotolotoi, ma o A’u o lo outou fautua i le Tamā; ma o lona finagalo agalelei ia tuu atu ia te outou le malo."},{"verse":6,"text":"Ma, e pei ona tusia—Soo se mea tou te ole mai ai i le faatuatua, ma le lotogatasi i le tatalo e tusa ai ma la’u poloaiga, o le a outou maua."},{"verse":7,"text":"Ma ua valaaulia outou e faataunuu le faapotopotoina o la’u ’au filifilia; ona o la’u ’au filifilia e faalogo i lo’u leo ma lē faamaaaina o latou loto;"},{"verse":8,"text":"O le mea lea ua tuuina atu ai le poloaiga mai le Tamā ia faapotopoto mai i latou i le nofoaga e tasi i luga o lenei laueleele, e saunia o latou loto ma saunia ai i mea uma auā le aso pe a oo mai puapuaga ma faatafunaga i luga o e amioleaga."},{"verse":9,"text":"Ona ua lata mai le itula ma toeitiiti oo mai le aso e matua ai le lalolagi; ma o i latou uma o e faamaualuluga, ma i latou o e ua fai amioleaga, o le a avea faapei o tagutugutu o saito; ma o le a Ou susunuina i latou, ua fetalai mai ai le Alii o ’Au, ina ia lē i ai se amioleaga i le lalolagi;"},{"verse":10,"text":"Ona ua lata mai le itula, ma ua ao ona faataunuuina o mea na fetalaia e a’u aposetolo; auā e pei ona latou fetalai o le a faapea lava ona faataunuuina;"},{"verse":11,"text":"Ona o le a Ou faaali atu a’u lava mai le lagi i le mana ma le mamalu tele faatasi ma ona ’au uma, ma mau faatasi ma tagata i le amiotonu i luga o le lalolagi i le afe o tausaga, ma o le a lē tutu e e amioleaga."},{"verse":12,"text":"O lenei foi, e moni, e moni, Ou te fai atu ia te outou, ma ua tuuina atu i se poloaiga tumau, e ala i le finagalo o le Tamā, e faapea o a’u aposetolo, le Toasefululua lea sa faatasi ma a’u i la’u auaunaga i Ierusalema, o le a tutulai i lo’u itu taumatau i le aso ou te alu atu ai i se afi faaniutu, ua faaoofuina i ofu talaloa o le amiotonu, ma palealii i luga o o latou ulu, i le mamalu e pei foi o a’u, e faamasino le aiga atoa o Isaraelu, e tusa ma le toatele o i latou o e na alolofa mai ia te a’u ma tausi i a’u poloaiga, ma e leai lava se isi."},{"verse":13,"text":"Ona o le a ili umi mai ma leo tele se pu, e pei lava i luga o le Mauga o Sinai, ma o le a lulu le lalolagi atoa, ma o le a latou o mai—ioe, tagata oti lava ia o e na maliliu ia te a’u, e maua se palealii o le amiotonu, ma ia faaoofuina, e pei lava o A’u, e faatasi ma a’u, ina ia tasi i matou."},{"verse":14,"text":"Ae, faauta, Ou te fai atu ia te outou, ae le’i oo mai lea aso tele o le a faapouliuligia le la, ma o le a liu toto le masina, ma o le a pa’u’ū ifo fetu mai le lagi, ma o le a i ai faailoga tetele i le lagi i lugā ma i le lalolagi i lalō;"},{"verse":15,"text":"Ma o le a i ai le tagiaue ma auega i totonu o ’au o tagata;"},{"verse":16,"text":"Ma o le a i ai se timu uato’a tele e auina mai e faaumatia ai laau totō o le lalolagi."},{"verse":17,"text":"Ma o le a oo mai, ona o le amioleaga o le lalolagi, o le a Ou taui atu ai ma sui i luga o e e amioleaga, ona o le a latou lē salamo; ona ua tumu le ipu o lo’u ita; aua faauta, o le a lē faamamaina i latou e lo’u toto pe afai latou te lē faalogo mai ia te a’u."},{"verse":18,"text":"O le mea lea, o A’u o le Alii le Atua, o le a Ou auina atu lago i luga o le fogaeleele, ia o le a fepiiti i tagata e i ai, ma o le a ’aia o latou tino, ma faia ia oo mai ilo i luga o i latou;"},{"verse":19,"text":"Ma o le a taofia o latou laulaufaiva ina ia latou lē faia se upu e faasaga mai ia te a’u; ma o le a pa’u’ū ese o latou aano mai i o latou ponaivi, ma o latou mata mai o latou pogaimata;"},{"verse":20,"text":"Ma o le a oo mai o le a ’aina i latou e manu o le vao ma manu felelei o le vanimonimo."},{"verse":21,"text":"Ma o le ekalesia tele ma le inosia, le fafine talitane lea o le lalolagi uma, o le a lafo i lalo e le afi faaumatia, e pei ona fetalaia e le fofoga o Esekielu le perofeta, o lē na tautala e uiga i ia mea, ia e lei faataunuuina ae o le a faataunuuina moni lava, e pei ona Ou ola, ona o le a lē manumalo mea inosia."},{"verse":22,"text":"O lenei foi, e moni, e moni, Ou te fai atu ia te outou, a i’u le afe o tausaga, ma toe amata e tagata ona teena lo latou Atua, ona Ou faasaoina ai lea o le lalolagi ae mo nao se vaitau itiiti;"},{"verse":23,"text":"Ma o le a oo mai le iuga, ma o le a susunuina ma mavae atu le lagi ma le lalolagi, ma o le a i ai se lagi fou ma se lalolagi fou."},{"verse":24,"text":"Ona o le a mavae atu mea tuai uma, ma o le a faafouina mea uma, e oo lava i le lagi ma le lalolagi, ma le atoaga o mea uma o i ai, o tagata atoa ma manu vaefa, o manu felelei o le vanimonimo, ma i’a o le sami;"},{"verse":25,"text":"Ma e leai se lauulu e tasi, po o sina mea itiiti, o le a leiloa, ona o ia mea o le galuega a o’u lima."},{"verse":26,"text":"Ae, faauta, e moni Ou te fai atu ia te outou, ae lei mavae atu le lalolagi, o le a ili e Mekaeli, la’u agelu sili, lana pu, ona feala mai ai lea o e uma na oti, ona o le a tatalaina o latou tuugamau, ma o le a latou o mai i fafo—ioe, i latou uma lava."},{"verse":27,"text":"Ma o e ua amiotonu o le a faapotopotoina i lo’u lima taumatau mo le ola e faavavau; ma o e ua amioleaga e i lo’u lima tauagavale o le a Ou maasiasi e avea mo o’u i luma o le Tamā;"},{"verse":28,"text":"O le mea lea o le a Ou fai atu ia te i latou—O ese atu ia mai ia te a’u, outou ua fetuuina, i le afi tumau e faavavau, ua saunia mo le tiapolo ma ana agelu."},{"verse":29,"text":"Ma o lenei, faauta, Ou te fai atu ia te outou, Ou te lei fai atu i soo se taimi mai lo’u lava gutu e faapea o le a latou toe foi mai, ona o le mea Ou te i ai e lē mafai ona latou o mai i ai, ona ua leai se mana ua ia te i latou."},{"verse":30,"text":"Ae ia manatua e lē tuuina atu a’u faamasinoga uma i tagata; ma e pei o upu na tuuina atu mai lo’u gutu o le a faapea lava ona faataunuuina i latou, o lē ua muamua o le a mulimuli, ma o lē ua mulimuli o le a muamua i soo se mea o mea uma na Ou foafoaina i le upu a lo’u mana, o le mana lea o lo’u Agaga."},{"verse":31,"text":"Ona o le mana o lo’u Agaga na Ou foafoa ai mea uma; ioe, mea uma faaleagaga atoa ma faaletino—"},{"verse":32,"text":"E muamua le faaleagaga, lona lua le faaletino, o le amataga lea o la’u galuega; o lenei foi, e muamua le faaletino, ma lona lua le faaleagaga, o le mulimuli lea o la’u galuega—"},{"verse":33,"text":"I le tautala atu lea ia te outou ina ia outou malamalama e tusa ma o outou natura; ae ia te a’u lava ia, e leai se gataaga o a’u galuega, po o se amataga; ae ua Ou tuuina atu lenei mea ia te outou ina ia outou malamalama, ona ua outou ole mai ai ia te a’u ma ua outou lotogatasi."},{"verse":34,"text":"O le mea lea, e moni Ou te fai atu ia te outou, ua faaleagaga mea uma lava ia te a’u, ma Ou te lei tuuina atu lava ia te outou i soo se taimi se tulafono sa faaletino; pe i soo se tagata, po o le fanauga a tagata; pe ia Atamu, lo outou tamā, o lē na Ou foafoaina."},{"verse":35,"text":"Faauta, sa Ou tuu atu ia te ia ia avea o ia ma pule ia te ia lava; ma sa Ou tuu atu ia te ia poloaiga, peitai e leai se poloaiga faaletino na Ou tuu atu ia te ia, ona o a’u poloaiga ua faaleagaga; ua lē faalenatura i latou pe faalelalolagi, pe faaletino pe faalenautino."},{"verse":36,"text":"Ma sa oo ina ua faaosoosoina Atamu, e le tiapolo—aua, faauta, sa i ai le tiapolo muamua atu ia Atamu, ona sa fouvale o ia faasaga mai ia te a’u, fai mai, Tuu mai ia te a’u lou mamalu, o lo’u mana lea; ma sa faaliliu ese foi e ia mai ia te a’u le tasi vae tolu o ’au o le lagi ona o la latou faitalia;"},{"verse":37,"text":"Ma sa lafoina i latou i lalo, ma faapea ona i ai o le tiapolo ma ana agelu;"},{"verse":38,"text":"Ma, faauta, e i ai se nofoaga ua saunia mo i latou mai le amataga, o lea nofoaga o seoli."},{"verse":39,"text":"Ma e ao ina faaosoosoina e le tiapolo le fanauga a tagata, po o e lē mafai ona avea i latou ma pule ia te i latou lava; auā afai e lē oo lava ia te i latou le oona e lē mafai ona latou iloa le suamalie—"},{"verse":40,"text":"O le mea lea, sa oo ina faaosoosoina Atamu e le tiapolo, ma sa ’ai o ia i le fua na faasaina ma soli ai le poloaiga, lea na pulea ai o ia i le loto o le tiapolo, ona ua tuu atu e ia i le faaosoosoga."},{"verse":41,"text":"O le mea lea, o A’u, o le Alii le Atua, na Ou faia ai ia tuli ese o ia i fafo mai le Faatoaga o Etena, mai o’u luma, ona o lana solitulafono, lea na oti ai o ia faaleagaga, o le oti muamua lea, le oti lava lea o le oti mulimuli, le oti faaleagaga lea, lea o le a folafola atu i luga o e amioleaga pe a Ou fai atu: O ese atu ia, outou ua fetuuina."},{"verse":42,"text":"Ae, faauta, Ou te fai atu ia te outou, o A’u, o le Alii le Atua, na Ou tuu atu ia Atamu ma ana fanau, ia latou lē oti i le oti faaletino, seia auina atu e A’u, o le Alii le Atua, agelu e tau atu ia te i latou le salamo ma le togiolaina, e ala i le faatuatua i le suafa o lo’u Atalii Pele e Toatasi."},{"verse":43,"text":"Ma sa faapea ona tofia e A’u, o le Alii le Atua, i le tagata, aso o loo nofo vaavaaia ai—ina ia mafai i lona oti faalenatura ona faatuina mai o ia i le ola pea mo le ola e faavavau, le toatele lea o i latou o e e talitonu."},{"verse":44,"text":"Ma i le malaia e faavavau, i latou o e e lē talitonu; ona e lē mafai ona togiolaina i latou mai lo latou pa’ū faaleagaga, ona ua latou lē salamo;"},{"verse":45,"text":"Ona ua latou fiafia i le pouliuli nai lo le malamalama, ma ua leaga a latou mea ua fai, ma latou te maua o latou taui mai lē ua latou loto e usiusitai i ai."},{"verse":46,"text":"Ae faauta, Ou te fai atu ia te outou, ua togiolaina tamaiti laiti mai le faavaega o le lalolagi e ala i lo’u Atalii e Toatasi na Fanaua;"},{"verse":47,"text":"O le mea lea, e lē mafai ona agasala i latou, ona ua lē tuuina atu ia Satani le mana e faaosooso ai i tamaiti laiti, sei oo ina amata ona tali mai i latou i o’u luma."},{"verse":48,"text":"Ona e tuu atu ia te i latou e pei lava ona Ou loto i ai, e tusa ma la’u lava filifiliga, ina ia manaomia mai lima o o latou tamā mea sili."},{"verse":49,"text":"Ma, e faapea foi, Ou te fai atu ia te outou, o ai se ua i ai le malamalama, pe Ou te lei poloaiina ea ia salamo?"},{"verse":50,"text":"Ma o ia o lē ua leai se malamalama o i ai, e tumau pea ia te a’u e faia i ai e pei ona tusia. Ma o lenei Ou te lē toe tau atu ni isi mea ia te outou i le taimi nei. Amene."}]},{"chapter":30,"verses":[{"verse":1,"text":"Faauta, Ou te fai atu ia te oe, Tavita, ua e fefe i tagata ma sa e lē faalagolago mai ia te a’u mo le malosi e pei ona sa tatau ai ia te oe."},{"verse":2,"text":"Ae sa tele ona i ai o lou mafaufau i mea o le lalolagi nai lo o mea a a’u, o Lē na faia oe, ma le auaunaga na valaaulia i ai oe; ma sa e lē uai mai i lo’u Agaga, ma i latou o e sa faatutu i ou luga, ae sa faatosinaina oe e i latou o e Ou te lei poloaiina."},{"verse":3,"text":"O le mea lea, ua tuua ai oe e te ole mai mo oe lava i lo’u lima, ma mafaufau loloto e uiga i mea ua e mauaina."},{"verse":4,"text":"Ma ia fai ma ou aiga le fale o lou tamā, seia Ou tuu atu ia te oe ni isi poloaiga. Ma ia e faasaga i le auaunaga i le ekalesia, ma luma o le lalolagi, ma nofoaga o faataamilo ai. Amene."},{"verse":5,"text":"Faauta, Ou te fai atu ia te oe, Peteru, ia alu lau malaga faatasi ma lou uso o Oliva; ona ua oo mai le taimi ua tatau ai ia te a’u ona e tatala atu o lou fofoga e talai atu la’u talalelei; o lea, aua e te fefe, ae ia uai atu i upu ma fautuaga a lou uso, o le a tuu atu e ia ia te oe."},{"verse":6,"text":"Ma ia e puapuaga i ona puapuagatia uma, ma siitia a’e pea i lou loto ia te a’u i le tatalo ma le faatuatua, mo lona ma lou laveaiina; ona ua Ou tuu atu ia te ia le mana e ati a’e ai i luga la’u ekalesia i totonu o sa Lamanā;"},{"verse":7,"text":"Ma e leai se tasi ua Ou tofia e fai ma ona fautua i luga o ia i le ekalesia, e faatatau i mataupu o le ekalesia, vagana ai o lona uso, o Iosefa Samita, Le Itiiti."},{"verse":8,"text":"O le mea lea, ia uai atu ai i nei mea ma filiga i le tausiga o a’u poloaiga, ma o le a faamanuiaina ai oe i le ola e faavavau. Amene."},{"verse":9,"text":"Faauta, Ou te fai atu ia te oe, o la’u auauna o Ioane, ia e amata atu mai le taimi nei i luma ona e talai atu la’u talalelei, e faapei o le leo o se pu."},{"verse":10,"text":"Ma o lau galuega o le a i le mea o i ai lou uso o Philip Burroughs, ma i le itulagi lena e faataamilo ai, ioe, i soo se mea e mafai ona faalogoina ai oe, seia Ou poloaiina oe e te alu ese mai iina."},{"verse":11,"text":"Ma o lau galuega atoa mai le taimi nei ma le agai i luma, faatasi ma lou agaga atoa, o le a i Siona; ioe, ia e tatala atu pea lou gutu i la’u savali, ma le lē fefe i mea e mafai ona faia e tagata, aua ua Ou faatasi ma oe. Amene."}]},{"chapter":31,"verses":[{"verse":1,"text":"Tomasi, lo’u atalii e, amuia oe ona o lou faatuatua i la’u galuega."},{"verse":2,"text":"Faauta, e tele puapuaga ua oo ia te oe ona o lou aiga; ae ui i lea, o le a Ou faamanuiaina oe ma lou aiga, ioe, au fanau laiti; ma e oo mai le aso o le a latou talitonu ma iloa ai le upumoni ma faatasi ai ma oe i la’u ekalesia."},{"verse":3,"text":"Ia siitia a’e lou loto ma olioli, ona ua oo mai le itula o lau misiona; ma o le a tatala lou laulaufaiva, ma ia e folafola atu tala fiafia o le olioli tele i lenei tupulaga."},{"verse":4,"text":"Ia e folafola atu mea ua faaali atu i la’u auauna, o Iosefa Samita, Le Itiiti. Ia amata ona e talai atu mai le taimi nei e agai i luma, ioe, e selesele i le fanua ua matua ua saunia e susunuina."},{"verse":5,"text":"O lea, sasau atu lau selesaito ma lou agaga atoa, ma ua faamagaloina oe i au agasala, ma o le a faaee ia te oe fusisaito e tele i luga o lou tua, ona e agavaa lē e galue mo lona totogi. O le mea lea, o le a ola ai lou aiga."},{"verse":6,"text":"Faauta, e moni Ou te fai atu ia te oe, alu ese mai ia te i latou mo nao se taimi itiiti, ma folafola atu la’u upu, ma o le a Ou saunia se nofoaga mo i latou."},{"verse":7,"text":"Ioe, o le a Ou tatalaina loto o tagata, ma o le a latou talia oe. Ma o le a Ou faatuina se aulotu e ala i lou lima;"},{"verse":8,"text":"Ma ia e faamalosia i latou ma saunia i latou aua le taimi o le a faapotopotoina ai i latou."},{"verse":9,"text":"Onosai i puapuaga, aua le faifai atu ia te i latou o e e faifai mai. Ia pulea lou aiga i le agamalu, ma ia tumau."},{"verse":10,"text":"Faauta, Ou te fai atu ia te oe, ia avea oe ma fofo i le ekalesia, ae lē o le lalolagi, ona o le a latou lē talia oe."},{"verse":11,"text":"Alu i lou ala i soo se mea Ou te loto i ai, ma o le a tuu atu ia te oe e le Fesoasoani le mea e te faia ma le mea e te alu i ai."},{"verse":12,"text":"Tatalo e lē aunoa, ne’i e ulu atu i faaosoosoga ma aveesea ai lou taui."},{"verse":13,"text":"Ia faamaoni e oo i le iuga, ma faauta, ua Ou faatasi ma oe. O nei upu ua lē a se tagata pe a ni tagata, ae ua a a’u, o Iesu Keriso lava, lou Togiola, e ala i le finagalo o le Tamā. Amene."}]},{"chapter":32,"verses":[{"verse":1,"text":"Ma o lenei e faatatau i la’u auauna o Parley P. Pratt, faauta, Ou te fai atu ia te ia, e pei ona Ou ola, Ou te manao ia folafola atu e ia la’u talalelei ma aoao e uiga ia te a’u, ma ia agamalū ma maualalo i le loto."},{"verse":2,"text":"Ma o le mea ua Ou tofia i ai o ia o le alu atu lea o ia faatasi ma a’u auauna, o Oliva Kaotui ma Peter Uitimera, Laitiiti, i le vao, i totonu o sa Lamanā."},{"verse":3,"text":"Ma ia alu atu foi Ziba Peterson faatasi ma i latou; ma o A’u lava o le a alu atu faatasi ma i latou ma i ai i totonu o lo latou lotolotoi; ma o A’u o lo latou fautua i le Tamā, ma o le a leai se mea e faasaga ia te i latou e manumalo."},{"verse":4,"text":"Ma o le a latou uai atu i mea ua tusia, ma lē manatu i se isi lava faaaliga; ma o le a latou tatalo e lē aunoa ina ia mafai ona Ou fofola atu ia lava mea i lo latou malamalamaaga."},{"verse":5,"text":"Ma ia latou uai mai i nei upu ma lē manatu mama i ai, ma o le a Ou faamanuiaina i latou. Amene."}]},{"chapter":33,"verses":[{"verse":1,"text":"Faauta, Ou te fai atu ia te oulua, a’u auauna o Esera ma Northrop, ia tatala o oulua taliga ma faalogo mai i le siufofoga o le Alii lo oulua Atua, o lē o lana afioga ua vave ma mamana, ua sili atu le maai nai lo o se pelu mata-lua, i le vavaeina o sooga o ivi ma le su, tagata-ola ma le agaga; ma o se ua ia silafia mafaufauga ma faamoemoega o le loto."},{"verse":2,"text":"Aua e moni, e moni, Ou te fai atu ia te oulua, ua valaaulia oulua e siitia a’e o oulua leo e pei o le leo o se pu, e folafola atu la’u talalelei i se tupulaga piopio ma le faalogogata."},{"verse":3,"text":"Aua faauta, ua sinasina le fanua ua saunia e selesele ai; ma o le itula lenei e sefulutasi, ma o le taimi mulimuli lenei o le a Ou valaaulia ai e e galulue i lo’u tovine."},{"verse":4,"text":"Ma ua faaleagaina uma lo’u tovine; ma ua leai se tasi ua ia faia le lelei vagana ai se toaitiiti; ma ua latou sese i le tele o taimi ona o faitaulaga pepelo, ua eleelea uma o latou mafaufau."},{"verse":5,"text":"Ma e moni, e moni, Ou te fai atu ia te oulua, o lenei ekalesia na Ou faatuina ma valaauina atu mai le vao."},{"verse":6,"text":"Ma o le a faapea lava ona Ou faapotopotoina la’u au filifilia mai itu e fa o le lalolagi, le toatele lea o i latou o e e talitonu mai ia te a’u, ma faalogo mai i lo’u leo."},{"verse":7,"text":"Ioe, e moni, e moni, Ou te fai atu ia te oulua, ua sinasina le fanua ua saunia e selesele ai; o le mea lea, sasau atu a oulua selesaito, ma selesele ma o oulua manatu atoa, mafaufau atoa, ma le malosi atoa."},{"verse":8,"text":"Tatala o oulua gutu ma o le a faatutumuina, ma o le a avea oulua e pei lava o Nifae o anamua, o lē na malaga mai Ierusalema i le vao."},{"verse":9,"text":"Ioe, tatala o oulua gutu ma ia lē taofia, ma o le a faaee ia te oulua fusisaito i luga o o oulua tua, aua faauta, ua Ou faatasi ma oulua."},{"verse":10,"text":"Ioe, tatala o oulua gutu ma o le a faatutumuina, fai atu: Ina salamo ia, salamo ia, ma outou teuteu le ala o le Alii, ma faasa’osa’o ona ala; ona ua oo mai lava le malo o le lagi;"},{"verse":11,"text":"Ioe, ia salamo ma papatiso, outou uma taitoatasi, mo se faamagaloga o a outou agasala; ioe, ia papatiso i le vai lava, ona oo mai ai lea o le papatisoga i le afi ma i le Agaga Paia."},{"verse":12,"text":"Faauta, e moni, e moni, Ou te fai atu ia te oulua, o la’u talalelei lenei; ma ia manatua e ao ina latou faatuatua mai ia te a’u po o le a leai se ala e mafai ona faaolaina ai i latou;"},{"verse":13,"text":"Ma o luga o lenei papa o le a Ou ati a’e ai la’u ekalesia; ioe, o luga o lenei papa ua ati a’e ai oulua, ma afai lua te faaauau ai pea, o le a lē manumalo faitotoa o seoli ia te oulua."},{"verse":14,"text":"Ma ia oulua manatua mataupu faavae ma feagaiga o le ekalesia ia tausi i ai."},{"verse":15,"text":"Ma o soo se tasi ua i ai le faatuatua ia oulua faamauina i la’u ekalesia, i le faaee atu o lima, ma o le a Ou tuu atu le meaalofa o le Agaga Paia i o latou luga."},{"verse":16,"text":"Ma ua tuuina atu le Tusi a Mamona ma tusitusiga paia mai ia te a’u mo lo oulua aoaoga; ma o le mana o lo’u Agaga e faaola ai mea uma."},{"verse":17,"text":"O le mea lea, ia faamaoni, ma tatalo i taimi uma, ma teuteu ma faamumu a oulua lamepa, ma ia i ai le suauu ia te oulua, ina ia mafai ona oulua saunia i le afio mai o le Faatoafaiavā—"},{"verse":18,"text":"Aua faauta, e moni, e moni, Ou te fai atu ia te oulua, e vave ona Ou alu atu. Ua faapea lava. Amene."}]},{"chapter":34,"verses":[{"verse":1,"text":"Lo’u atalii e, Osona, uai mai ma faalogo mai ma faauta mai i mea o le a fai atu ai ia te oe A’u, o le Alii le Atua, o Iesu Keriso lea, lou Togiola;"},{"verse":2,"text":"O le malamalama ma le ola o le lalolagi, o se malamalama ua susulu i le pouliuli ma ua lē malamalama i ai le pouliuli;"},{"verse":3,"text":"O lē na alofa tele i le lalolagi na ia tuu atu ai lona lava ola, ina ia mafai e le toatele o e talitonu ona avea ma atalii o le Atua. O le mea lea, o oe o lo’u atalii;"},{"verse":4,"text":"Ma amuia oe ona ua e talitonu;"},{"verse":5,"text":"Ma ua sili lava ona amuia o oe ona ua valaauina oe e a’u e talai atu la’u talalelei—"},{"verse":6,"text":"E siitia a’e lou leo e pei o le leo o se pu, ia umi ma leotele, ma alaga atu le salamo i se tupulaga piopio ma le faalogogata, e saunia ai le ala o le Alii mo lona afio mai faalua."},{"verse":7,"text":"Aua faauta, e moni, e moni, Ou te fai atu ia te oe, ua lata mai ona oo mai le taimi o le a Ou alu atu ai i se ao faatasi ma le mana ma le mamalu tele."},{"verse":8,"text":"Ma o le a avea ma se aso tele i le taimi o lo’u alu atu, ona o le a gatete atunuu uma."},{"verse":9,"text":"Peitai, ae le’i oo mai lena aso tele, o le a faapouliuligia le la, ma o le a liu toto le masina; ma o le a le fia susulu mai fetu, ma o ni isi o le a pa’u’ū ifo, ma ua faatalitali mai faafanoga sili mo e ua amioleaga."},{"verse":10,"text":"O le mea lea, ia siitia a’e lou leo ma ia lē taofia, ona o le Alii le Atua ua fetalai mai ai; o lea ia vavalo atu, ma o le a tuu atu e ala atu i le mana o le Agaga Paia."},{"verse":11,"text":"Ma afai e te faamaoni, faauta, Ou te faatasi ma oe seia Ou alu atu—"},{"verse":12,"text":"Ma e moni, e moni, Ou te fai atu ia te oe, e vave ona Ou alu atu. O A’u o lou Alii ma lou Togiola. Ua faapea lava. Amene."}]},{"chapter":35,"verses":[{"verse":1,"text":"Faalogo mai ia i le leo o le Alii lo outou Atua, o le Alefa ma le Omeka lava lea, o le amataga ma le gataaga, o lē o lona ala o se taamilosaga faavavau e tasi, ua tutusa i le asō e pei o ananafi, ma le faavavau."},{"verse":2,"text":"O A’u o Iesu Keriso, le Atalii o le Atua, o lē na faasatauroina mo agasala a le lalolagi, o le toatele lava lea o e e talitonu i lo’u igoa, ina ia mafai ona avea i latou ma atalii o le Atua, ia tasi lava ia te a’u e pei ona Ou tasi ma le Tamā, e pei ona tasi le Tamā ma a’u, ina ia tasi i tatou."},{"verse":3,"text":"Faauta, e moni, e moni, Ou te fai atu i la’u auauna o Sini, ua Ou vaai atu ia te oe ma au galuega. Ua Ou faalogo i au tatalo, ma saunia oe mo se galuega tele."},{"verse":4,"text":"Ua faamanuiaina oe, ona o le a e faia mea sili. Faauta sa auina atu oe, e pei lava o Ioane, e saunia le ala i o’u luma, ma luma o Elia o lē o le a sau, ma sa e lē iloaina."},{"verse":5,"text":"Sa e papatiso atu i le vai i le salamo, ae sa latou lē mauaina le Agaga Paia."},{"verse":6,"text":"Ae Ou te tuu atu nei ia te oe se poloaiga, ia e papatiso atu i le vai, ma o le a latou maua le Agaga Paia e ala i le faaee atu o lima, e pei lava o aposetolo anamua."},{"verse":7,"text":"Ma o le a oo mai o le a i ai se galuega tele i le laueleele, i totonu lava o Nuuese, ona o le a faaalia lo latou sese ma a latou mea inosia i mata o tagata uma."},{"verse":8,"text":"Aua o A’u o le Atua, ma ua lē faapuupuuina lo’u lima; ma o le a Ou faaali atu vavega, faailoga, ma mea ofoofogia, ia te i latou uma o e talitonu i lo’u igoa."},{"verse":9,"text":"Ma ai se tasi e ole mai i lo’u igoa i le faatuatua, o le a latou tutuli ese tiapolo; o le a latou faamalolo i e e mamai; o le a latou faia ia faapupulaina tauaso, ma e tutuli ia faalogo, ma e gugu ia tautatala, ma e pipili ia savavali."},{"verse":10,"text":"Ma e vave ona oo mai o le taimi e faailoa atu ai mea sili i le fanauga a tagata;"},{"verse":11,"text":"Ae a aunoa ma le faatuatua e leai se mea o le a faaali atu vagana ai faatafunaga i luga o Papelonia, o ia lava lea na ia faia ia feinu atunuu uma i le uaina o le toasa o lona faitaaga."},{"verse":12,"text":"Ma ua leai ni isi ua faia le lelei vagana i latou o e ua saunia e talia le atoatoaga o la’u talalelei, lea ua Ou auina atu i lenei tupulaga."},{"verse":13,"text":"O le mea lea, Ou te valaau atu ai i mea vaivai o le lalolagi, i latou ia o e ua lē aoaoina ma inosia, e soli atunuu i le mana o lo’u Agaga;"},{"verse":14,"text":"Ma o lo latou lima o le a fai mo O’u lima, ma o le a avea a’u ma o latou talita ma o latou talipupuni; ma o le a Ou fusia i o latou sulugatiti, ma o le a latou tau faatamatane mo a’u; ma o le a i lalo o o latou vae o latou fili; ma o le a Ou faapa’ū atu le pelu mo i latou; ma o le a Ou faasaoina i latou i le afi o lo’u ita."},{"verse":15,"text":"Ma o e matitiva ma e agamalu o le a talai atu le talalelei ia te i latou, ma o le a latou tulimatai i luma mo le taimi o lo’u alu atu, ona ua lata lava ona oo mai—"},{"verse":16,"text":"Ma o le a latou malamalama i le faataoto e uiga i le laau o le mati, ona ua lata mai nei lava le taumafanafana."},{"verse":17,"text":"Ma ua ou auina atu le atoatoaga o la’u talalelei e ala i le lima o la’u auauna o Iosefa; ma ua ou faamanuiaina o ia i ona vaivai;"},{"verse":18,"text":"Ma ua Ou tuu atu ia te ia ki o mealilo o mea na ua faamaufaailogaina, o mea lava na sa mai i le faavaega o le lalolagi, ma mea o le a oo mai mai le taimi lenei seia oo i le taimi o lo’u alu atu, pe afai e tumau o ia ia te a’u, ae afai e leai, o le a Ou faatulai mai se tasi i lona tulaga."},{"verse":19,"text":"O le mea lea, leoleo i luga o ia ina ia lē vaivai lona faatuatua, ma o le a tuuina atu e ala atu i le Fesoasoani, o le Agaga Paia lea, o lē ua silafia mea uma."},{"verse":20,"text":"Ma Ou te tuu atu ia te oe se poloaiga—ia e tusi mo ia; ma o le a tuuina atu tusitusiga paia, e pei lava ona i ai i lo’u lava loto, mo le faaolataga o la’u lava ’au filifilia;"},{"verse":21,"text":"Ona o le a latou faalogo i lo’u leo, ma o le a vaai mai ia te a’u, ma o le a lē momoe, ma o le a latou gafatia le aso o lo’u alu atu; ona o le a faamamaina i latou, e pei lava ona Ou mama."},{"verse":22,"text":"Ma o lenei Ou te fai atu ia te oe, nofo faatasi ma ia, ma o le a malaga o ia faatasi ma oe; aua e te tuulafoai ia te ia, ma e moni o le a faataunuuina lava nei mea."},{"verse":23,"text":"Ma e tusa ai ma lou lē tusi ai, faauta, o le a tuu atu ai ia te ia e te vavalo atu; ma ia e talai atu la’u talalelei ma valaau atu i perofeta paia e faamaonia mai ana upu, e pei ona o le a tuuina atu ia upu ia te ia."},{"verse":24,"text":"Tausi i poloaiga ma feagaiga uma ua fusia ai oulua; ma o le a Ou faia ia luluina le lagi mo lo oulua lelei, ma o le a gatete Satani ma o le a olioli Siona i luga o mauga ma faauluuluolaina."},{"verse":25,"text":"Ma o le a faaolaina Isaraelu i la’u lava taimi e tatau ai; ma o le a taitaia i latou i ki ua Ou tuuina atu, ma lē toe fenumiai lava."},{"verse":26,"text":"Ia siitia a’e o oulua loto ma fiafia, ua lata mai lo oulua togiolaina."},{"verse":27,"text":"Aua le matatau, le lafu mamoe itiiti e, ua a outou le malo seia Ou alu atu. Faauta, e vave ona Ou alu atu. Ua faapea lava. Amene."}]},{"chapter":36,"verses":[{"verse":1,"text":"Ua faapea ona fetalai mai o le Alii le Atua, le Malosi Aoao e Toatasi o Isaraelu: Faauta, Ou te fai atu ia te oe, la’u auauna Eteuati, ua faamanuiaina oe, ma ua faamagaloina oe i au agasala, ma ua valaaulia oe e talai atu la’u talalelei ma le leo e pei o se pu;"},{"verse":2,"text":"Ma o le a faaee lo’u lima i ou luga e ala i le lima o la’u auauna o Sini Rikitone, ma o le a e maua lo’u Agaga, o le Agaga Paia lea, o le Fesoasoani lea, o lē o le a ia aoao atu ia te oe mea filemu o le malo;"},{"verse":3,"text":"Ma ia e talai atu le talalelei ma le leo tele, fai atu: Osana, ia faamanuina lava le suafa o le Atua silisili ese."},{"verse":4,"text":"Ma o le valaauga ma le poloaiga lenei Ou te tuu atu ia te oe e faatatau i tagata uma—"},{"verse":5,"text":"O le toatele o i latou e o mai i luma o a’u auauna o Sini Rikitone ma Iosefa Samita, Le Itiiti, ua latou talia lenei valaauga ma le poloaiga, ia faauuina ma auina atu e talai atu le talalelei tumau e faavavau i totonu o atunuu—"},{"verse":6,"text":"Ma alaga atu le salamo, fai atu: Ia outou laveai outou lava mai lenei tupulaga pi’opi’o, ma o mai i fafo o le afi, ma le inoino e oo lava i ofu ua pisia i le tino."},{"verse":7,"text":"Ma ia tuu atu lenei poloaiga i toeaina o la’u ekalesia, ina ia mafai ona faauuina ma auina atu tagata taitoatasi o e e taliaina lenei poloaiga ma le manatu tasi o le loto, e pei lava ona Ou tautala atu ai."},{"verse":8,"text":"O A’u o Iesu Keriso, le Atalii o le Atua; o le mea lea, ia fusi i ou sulugatiti ma o le a faafuasei ona Ou alu atu i lo’u malumalu. E faapea lava. Amene."}]},{"chapter":37,"verses":[{"verse":1,"text":"Faauta, Ou te fai atu ia te oulua ua lē tatau ia te a’u ona oulua toe faaliliu seia oulua o atu i Ohaio, ma o le pogai o lenei mea ona o le fili ma mo lo oulua lelei."},{"verse":2,"text":"O lenei foi, Ou te fai atu ia te oulua, ia oulua lē o atu seia oulua talai atu la’u talalelei i vaega na, ma ua oulua faamalosia le ekalesia i soo se mea o i ai, ma aemaise lava i Kolesavile; aua faauta, ua latou tatalo mai ia te a’u i le faatuatua tele."},{"verse":3,"text":"O lenei foi, Ou te tuu atu se poloaiga i le ekalesia, e faapea ua tatau ia te a’u ona latou potopoto faatasi i Ohaio, aua le taimi o le a toe foi atu ai la’u auauna o Oliva Kaotui ia te i latou."},{"verse":4,"text":"Faauta, o le poto lenei, ma ia tuu atu i tagata uma taitoatasi e filifili mo ia lava seia Ou alu atu. E faapea lava. Amene."}]},{"chapter":38,"verses":[{"verse":1,"text":"Ua faapea ona fetalai mai o le Alii lo outou Atua, o Iesu Keriso lava, o le O A’u Silisili, o le Alefa ma le Omeka, o le amataga ma le gataaga, o ia lava lea na silasila atu i luga o le vavaloloa lautele o le faavavau, ma ’au serafi uma o le lagi, ae lei faia le lalolagi;"},{"verse":2,"text":"O lea lava e tasi ua silafia mea uma, aua ua i luma o o’u mata mea uma;"},{"verse":3,"text":"O A’u lava lea e tasi o lē na tautala atu, ma faia ai le lalolagi, ma o mea uma na oo mai e ala mai ia te a’u."},{"verse":4,"text":"O A’u lava lea e tasi o lē na avea le Siona a Enoka i lo’u lava loto; ma e moni, Ou te fai atu, o le toatele lava lea o e na talitonu i lo’u igoa, ona o A’u o Keriso, ma o lo’u lava igoa, e ala i le mana o le toto na Ou faamasaaina, na Ou aioi atu ai i luma o le Tamā mo i latou."},{"verse":5,"text":"Ae faauta, o le toega o e ua amioleaga ua Ou taofia i filifili o le pouliuli seia oo i le faamasinoga o le aso tele, lea o le a oo mai i le iuga o le lalolagi;"},{"verse":6,"text":"Ma o le a faapea lava ona Ou faia ia taofia e ua amioleaga, o e e lē fia faalogo i lo’u leo ae faamaaa o latou loto, oi talofa, oi talofa, oi talofa, o lo latou malaia lea."},{"verse":7,"text":"Ae faauta, e moni, e moni, Ou te fai atu ia te outou o ou mata ua i o outou luga. Ua Ou i ai i totonu ia te outou ae ua lē mafai ona outou vaai mai ia te a’u;"},{"verse":8,"text":"Ae ua lata ona oo mai o le aso o le a outou vaai mai ai ia te a’u, ma outou iloa ai ua i ai A’u; ona ua lata ona saeluaina o le veli o le pouliuli, ma o ia o lē e lei faamamaina o le a lē gafatiaina le aso."},{"verse":9,"text":"O le mea lea, fusi i o outou sulugatiti ma saunia. Faauta, ua a outou le malo, ma o le a lē manumalo le fili."},{"verse":10,"text":"E moni Ou te fai atu ia te outou, ua outou mama, ae lē o outou uma; ma ua leai ni isi tagata o e ua Ou fiafia tele i ai;"},{"verse":11,"text":"Ona ua leaga tagata uma i o’u luma; ma ua sosolo le mana o le pouliuli i luga o le lalolagi, i totonu o le fanauga a tagata, i luma o ’au uma o le lagi—"},{"verse":12,"text":"O lea ua mafua ai le nofotupu o le taaligoligoa, ma ua tiga ai le faavavau atoa, ma o loo faatali e agelu le poloaiga tele ia selesele i le lalolagi, e faaputu titania ina ia susunuina; ma, faauta, ua ’au faatasi le fili."},{"verse":13,"text":"Ma o lenei Ou te faailoa atu ia te outou se mealilo, o se mea lea o loo faia i totonu o potu faalilolilo, e aumai ai lo outou faafanoga i le āluga o le taimi, ma sa outou lē iloaina;"},{"verse":14,"text":"Ae ua Ou ta’u atu nei ia te outou, ma ua faamanuiaina ai outou, ua lē ona o lo outou amioletonu, po o o outou loto lē talitonu; aua e moni e i ai ni isi o outou ua sala i o’u luma, peitai o le a Ou alofagia lo outou vaivai."},{"verse":15,"text":"O lea, ia outou faamalolosi mai le taimi nei ma le agai i luma; aua le matatau, aua ua a outou le malo."},{"verse":16,"text":"Ma Ou te tuu atu ia te outou se poloaiga mo lo outou olataga, aua ua Ou faalogoina a outou talosaga, ma ua tagi mai e ua matitiva i o’u luma, ma o e ua mauoa na Ou faia, ma o tagata uma lava e a a’u ia, ma e lē o A’u o se faailoga tagata."},{"verse":17,"text":"Ma ua Ou faia le eleele ia oa, ma faauta o lo’u tuuvae lea, o le mea lea, o le a Ou toe tu ai i ona luga."},{"verse":18,"text":"Ma Ou te tuu atu ma avatu ia te outou oa e sili atu, se laueleele lava lea o le folafolaga, o se laueleele ua tafe ai le susu ma le meli, lea o le a lē i ai i luga se mala pe a afio mai le Alii;"},{"verse":19,"text":"Ma o le a Ou tuu atu ia te outou e fai ma laueleele o lo outou tofi, pe afai tou te saili i ai ma o outou loto atoa."},{"verse":20,"text":"Ma o la’u feagaiga lenei ma outou, o le a outou mauaina lenei e fai ma laueleele o lo outou tofi, ma mo le tofi o a outou fanau e faavavau, a’o i ai pea le lalolagi, ma o le a outou toe mauaina i le faavavau, e lē toe mavae atu lava."},{"verse":21,"text":"Ae, e moni Ou te fai atu ia te outou, e oo mai le taimi o le a leai ai so outou tupu po o se pule, ona o le a avea A’u ma o outou tupu ma leoleo i luga o outou."},{"verse":22,"text":"O le mea lea, faalogo mai i lo’u leo ma mulimuli mai ia te a’u, ma o le a avea outou ma tagata saoloto, ma o le a leai ni a outou tulafono nao a’u tulafono pe a Ou alu atu, ona o A’u o lo outou faitulafono, ma o se a se mea e mafai ona taofia lo’u lima?"},{"verse":23,"text":"Peitai, e moni Ou te fai atu ia te outou, aoao le tasi i le isi e tusa ma le tofi lea na Ou tofia ai outou;"},{"verse":24,"text":"Ma ia taitasi le tagata ma manatu taua i lona uso e pei o ia lava ia te ia, ma fai le amiomama ma mea paia i o’u luma."},{"verse":25,"text":"Ma Ou te toe fai atu ia te outou, ia taitasi le tagata ma manatu taua i lona uso e pei o ia lava ia te ia."},{"verse":26,"text":"Aua o ai se tagata e i totonu o outou ua i ai ni atalii e toasefululua, ma ua lē faailoga tagata ia te i latou, ma ua latou auauna ia te ia ma le usiusitai, ae fai atu o ia i le tasi: Ia e ofu i ofu talaloa ma e nofo i i; ae fai atu i le isi: Ia e ofu i ofu masaesae ma e nofo i ’o—ma vaai atu i ona atalii ma fai mai ua ou amiotonu?"},{"verse":27,"text":"Faauta, ua Ou tuu atu ia te outou lenei mea o se faataoto, ma ua faapea lava e pei o A’u. Ou te fai atu ia te outou, ia tasi outou; ma afai tou te lē tasi e lē a a’u outou."},{"verse":28,"text":"Ma Ou te toe fai atu ia te outou, ua saili e le fili o loo i potu faalilolilo o outou ola."},{"verse":29,"text":"Tou te faalogo i taua i atunuu mamao, ma outou fai ane ua lata ona i ai o taua tetele i atunuu mamao, ae ua outou lē iloa loto o tagata o loo i lo outou lava laueleele."},{"verse":30,"text":"Ua Ou ta’u atu ia te outou nei mea ona o a outou talosaga; o le mea lea, ia teu le poto i o outou loto, ne’i faaali atu e le amioleaga o tagata nei mea ia te outou e ala i lo latou amioleaga, i se ala o le a tautala atu ai i o outou taliga i se leo e leotele atu nai lo o lena o le a luluina ai le lalolagi; ae afai ua outou saunia o le a outou lē matata’u lava."},{"verse":31,"text":"Ma ina ia mafai ona outou sao mai le mana o le fili, ma faapotopoto mai ia te a’u o se nuu amiotonu, ua aunoa ma se ila ma se pōnā—"},{"verse":32,"text":"O le mea lea, o le pogai lenei na Ou tuu atu ai ia te outou se poloaiga ia outou o atu i Ohaio; ma o iina o le a Ou tuu atu ai ia te outou la’u tulafono; ma o iina o le a faaeeina ai outou i le mana mai luga;"},{"verse":33,"text":"Ma mai iina, soo se tasi Ou te loto i ai, o le a o atu i totonu o atunuu uma, ma o le a ta’u atu ia te i latou mea latou te faia; ona ua ia te A’u se galuega tele ua teuina, ona o le a laveaia Isaraelu, ma o le a Ou taitaia i latou i soo se mea Ou te loto i ai, ma e leai se mana e taofia lo’u lima."},{"verse":34,"text":"Ma o lenei, Ou te tuu atu i le ekalesia ua i ai i vaega nei se poloaiga, e faapea i ni alii faapitoa o i totonu o i latou o le a tofia, ma o le a tofia i latou i le leo o le ekalesia;"},{"verse":35,"text":"Ma o le a latou vaaia e ua matitiva ma e ua lē tagolima, ma auauna atu mo lo latou tausiga ina ia latou lē mafatia; ma auina atu i latou i le nofoaga ua Ou poloaiina ai i latou;"},{"verse":36,"text":"Ma o le latou galuega lenei, e pulea mataupu o meatotino a lenei ekalesia."},{"verse":37,"text":"Ma o i latou ua i ai faatoaga ua lē mafai ona faatau atu, ia tuu pea i latou pe faaaoga-totogi e tusa ma le mea e lelei ia te i latou."},{"verse":38,"text":"Vaai ia faasaosaoina mea uma; ma a uma ona faaeeina o tagata i le mana mai luga ma auina atu, o le a faaputuputuina nei mea uma i totonu o le ekalesia."},{"verse":39,"text":"Ma afai tou te saili oa ua i ai i le finagalo o le Tamā e tuu atu ia te outou, o le a sili atu ona outou mauoa i tagata uma, aua o le a outou maua oa o le faavavau; ma ua tatau ai ona a a’u oa o le lalolagi e tuu atu; ae ia faaeteete i le faamaualuga, ne’i avea outou e pei o sa Nifaē anamua."},{"verse":40,"text":"Ma Ou te toe fai atu ia te outou, Ou te tuu atu ia te outou se poloaiga, ia o atu tagata taitoatasi, e aofia ai le toeaina, le ositaulaga, le aoao, ma tagata o le ekalesia, ma lona malosi, ma le galue o ona lima, e sauni ma faataunuu mea ua Ou poloaiina ai."},{"verse":41,"text":"Ma ia tuu atu a outou talaiga e avea ma leo o le lapataiga, o tagata taitoatasi i lona tuaoi, i le mālū ma i le agamalu."},{"verse":42,"text":"Ma ia outou o ese atu mai totonu o e ua amioleaga. Ia outou laveai outou lava. Ia mama outou o e e tauaaoina ipu a le Alii. E faapea lava. Amene."}]},{"chapter":39,"verses":[{"verse":1,"text":"Faalogo mai ia ma faafofoga mai i le siufofoga o ia o lē ua mai i le faavavau atoa e oo i le faavavau atoa, le O A’u Silisili, o Iesu Keriso lava—"},{"verse":2,"text":"O le malamalama ma le ola o le lalolagi; o se malamalama ua susulu i le pouliuli a ua lē malamalama i ai le pouliuli;"},{"verse":3,"text":"O ia lava lea na alu atu i le vaeluaga o taimi i lo’u lava nuu, ae sa lē talia a’u e lo’u lava nuu;"},{"verse":4,"text":"Ae i le toatele o i latou o e na talia a’u, na Ou tuu atu i ai le mana e avea ai ma o’u atalii; ma o le a faapea lava ona Ou tuu atu i le toatele o i latou o e o le a latou talia a’u, le mana e avea ai ma o’u atalii."},{"verse":5,"text":"Ma e moni, e moni, Ou te fai atu ia te oe, o ia o lē e talia la’u talalelei ua ia talia a’u; ma o ia o lē na te lē talia la’u talalelei ua ia lē talia a’u."},{"verse":6,"text":"Ma o la’u talalelei lenei—o le salamo ma le papatisoga i le vai, ona oo mai ai lea o le papatisoga i le afi ma le Agaga Paia, o le Fesoasoani lava lea, o lē na te faailoa atu mea uma, ma aoao atu mea filemu o le malo."},{"verse":7,"text":"Ma o lenei, faauta, Ou te fai atu ia te oe, la’u auauna Iakopo, ua Ou vaai i luga o au galuega ma ua Ou iloa oe."},{"verse":8,"text":"Ma e moni Ou te fai atu ia te oe, ua sa’o nei lou loto i o’u luma i le taimi lenei; ma, faauta, ua Ou faaee atu faamanuiaga sili i luga o lou ulu;"},{"verse":9,"text":"Ae ui i lea, sa e vaai i faanoanoaga tetele, ona sa e tetee ia te a’u i le tele o taimi ona o le faamaualuga ma le popole i mea o le lalolagi."},{"verse":10,"text":"Ae, faauta, ua oo mai aso o lou laveaiina, pe afai e te faalogo mai i lo’u leo, lea ua fai atu ia te oe: Tulai ia ma papatiso, ma fufulu ese au agasala, ma valaau mai i lo’u igoa, ma o le a e maua ai lo’u Agaga, ma se faamanuiaga e matua tele e te lei iloaina lava."},{"verse":11,"text":"Ma afai e te faia lenei mea, ua Ou saunia oe mo se galuega sili atu. Ia e talai atu le atoatoaga o la’u talalelei, lea ua Ou auina atu i nei aso e gata ai, o le feagaiga lea ua Ou auina atu e toe aumai o’u tagata, o e o le aiga o Isaraelu."},{"verse":12,"text":"Ma o le a oo mai o le a tumau le mana i ou luga; o le a ia te oe le faatuatua tele, ma o le a Ou faatasi ma oe, ma muamua atu i ou luma."},{"verse":13,"text":"Ua valaaulia oe e te galue i lo’u tovine, ma ati a’e i luga la’u ekalesia, ma ’aumai i luma Siona, ina ia olioli i luga o maupu’epu’e ma tupuolaola."},{"verse":14,"text":"Faauta, e moni, e moni, Ou te fai atu ia te oe, e lei valaaulia oe e te alu i itu-laueleele i sasae, ae ua valaaulia oe e te alu i Ohaio."},{"verse":15,"text":"Ma talu ai ona o le a faapotopoto e o’u tagata i latou lava i Ohaio, sa Ou faapolopoloina se faamanuiaga e lei iloa lava i totonu o le fanauga a tagata, ma o le a liligi ifo i luga o o latou ulu. Ma mai iina o le a o atu ai alii i atunuu uma."},{"verse":16,"text":"Faauta, e moni, e moni, Ou te fai atu ia te oe, ua valaau mai tagata i Ohaio ia te a’u i le faatuatua tele, i le manatu o le a Ou taofi lo’u lima mai le faamasino atu i luga o atunuu, ae e lē mafai ona Ou faafitia la’u upu."},{"verse":17,"text":"O le mea lea, faasaga atu ma lou malosi ma valaaulia tagata galulue faamaoni i lo’u tovine, ina ia teuteuina mo le taimi mulimuli."},{"verse":18,"text":"Ma e tusa ai ma lo latou salamo ma talia le atoatoaga o la’u talalelei, ma faapaiaina, o le a Ou taofi lo’u lima mai le faamasino atu."},{"verse":19,"text":"O le mea lea, alu atu, ma alaga atu ma le leo tele, fai atu: Ua oo mai le malo o le lagi; alaga atu: Osana! ia faamanuina lava le suafa o le Atua Silisili Ese."},{"verse":20,"text":"Alu ma papatiso atu i le vai, ma teuteu le ala i o’u luma mo le taimi o lo’u alu atu;"},{"verse":21,"text":"Ona ua oo mai le taimi; o le aso po o le itula e leai se tagata na te iloaina; ae ua mautinoa o le a oo mai lava."},{"verse":22,"text":"Ma o ia o lē na te talia nei mea ua ia taliaina a’u; ma o le a faapotopotoina i latou ia te a’u i le olaga nei ma i le faavavau."},{"verse":23,"text":"O lenei foi, o le a oo mai, o le toatele o i latou o e o le a e papatisoina i le vai, ia e faaee i ai ou lima, ma o le a latou maua le meaalofa o le Agaga Paia, ma o le a tulimatai mo faailoga o lo’u alu atu, ma o le a latou iloa a’u."},{"verse":24,"text":"Faauta, e vave ona Ou alu atu. E faapea lava. Amene."}]},{"chapter":40,"verses":[{"verse":1,"text":"Faauta, e moni Ou te fai atu ia te oulua, sa sa’o le loto o la’u auauna o James Covel i o’u luma, ona sa osifeagaiga o ia ma a’u o le a usiusitai o ia i la’u upu."},{"verse":2,"text":"Ma sa ia talia le afioga a le Alii ma le fiafia, peitai sa vave ona faaosoosoina o ia e Satani; ma o le fefe i sauaga ma le popole i mea o le lalolagi ua mafua ai ona ia teena le afioga."},{"verse":3,"text":"O le mea lea ua soli ai e ia la’u feagaiga, ma ua tumau pea ia te a’u e fai ia te ia e tusa ma le mea ua lelei ia te a’u. Amene."}]},{"chapter":41,"verses":[{"verse":1,"text":"Faalogo mai ia ma faafofoga mai, outou e o o’u tagata, ua fetalai mai ai le Alii ma lo outou Atua, outou o e ua ou fiafia e faamanuia i le faamanuiaga silisili o faamanuiaga uma, outou o e ua faalogo mai ia te a’u; ma o outou o e ua lē faalogo mai ia te a’u, i latou ia o e na latou ta’uta’u lo’u igoa, o le a Ou fetuuina, i le fetuu sili atu ona mamafa o fetuu uma."},{"verse":2,"text":"Faalogo mai ia, outou e toeaina o la’u ekalesia o e ua Ou valaaulia, faauta Ou te tuu atu ia te outou se poloaiga, ia outou faapotopoto faatasi outou lava ina ia outou autasi e faatatau i la’u upu;"},{"verse":3,"text":"Ma o le tatalo o lo outou faatuatua o le a outou maua ai la’u tulafono, ina ia outou iloa le ala e pulea ai la’u ekalesia ma ina ia sa’o mea uma i o’u luma."},{"verse":4,"text":"Ma o le a avea A’u ma o outou pule pe a Ou alu atu; ma faauta, e vave ona Ou alu atu, ma ia outou vaai ia tausia la’u tulafono."},{"verse":5,"text":"O ia o lē e taliaina la’u tulafono ma faia, o ia lava lea o lo’u soo; ma o ia o lē e fai mai ua ia taliaina ae ua ia lē faia, o ia lava lea e lē o so’u soo, ma ia tuli i fafo mai totonu o outou;"},{"verse":6,"text":"Ona e lē tatau ona tuu atu o mea e ou e le fanau o le malo ia te i latou o e ua lē agavaa, pe i ’ulī, pe lafo atu penina i luma o meatuaolō."},{"verse":7,"text":"O lenei foi, e tatau i la’u auauna o Iosefa Samita, Le Itiiti, ona maua se fale e fausia, e nofo ai ma faaliliu."},{"verse":8,"text":"O lenei foi, e tatau i la’u auauna o Sini Rikitone ona ola e tusa ai ma le mea e foliga mai ua lelei ia te ia, e tusa ai ma lana tausiga o a’u poloaiga."},{"verse":9,"text":"O lenei foi, ua Ou valaauina la’u auauna o Eteuati Paterika; ma Ou te tuu atu se poloaiga, e tatau ona tofia o ia i le leo o le ekalesia, ma faauu o se epikopo mo le ekalesia, e tuu ana oloa ma faaaoga lona taimi atoa i galuega a le ekalesia."},{"verse":10,"text":"E vaaia mea uma e pei ona o le a tofia ia te ia i a’u tulafono i le aso Ou te tuu atu ai i latou."},{"verse":11,"text":"Ma ua faia lenei mea ona ua mama lona loto i o’u luma, ona ua faapei o ia o Natanielu o anamua, o lē ua leai se pepelo o i ai."},{"verse":12,"text":"O nei upu ua tuu atu ia te outou, ma ua mama i latou i o’u luma; o le mea lea, ia faaeteete i le ala tou te manatu ai i ai, ona o le a tali i latou i luga o o outou agaga i le aso o le faamasinoga. E faapea lava. Amene."}]},{"chapter":42,"verses":[{"verse":1,"text":"Faalogo mai ia, outou e toeaina o la’u ekalesia, o e ua outou faapotopoto faatasi outou lava i lo’u igoa, o Iesu Keriso lava le Atalii o le Atua soifua, le Faaola o le lalolagi; e tusa ai ua outou talitonu i lo’u igoa ma tausi i a’u poloaiga."},{"verse":2,"text":"Ou te toe fai atu ia te outou, faalogo ma faafofoga ma usiusitai i le tulafono o le a Ou tuu atu ia te outou."},{"verse":3,"text":"Aua e moni Ou te fai atu, talu ai ona ua outou faapotopoto faatasi outou lava e tusa ma le poloaiga na Ou poloaiina ai outou, ma ua outou autasi e faatatau i lenei mea e tasi, ma sa outou ole atu ai i le Tamā i lo’u igoa, o le a faapea lava ona outou maua."},{"verse":4,"text":"Faauta, e moni Ou te fai atu ia te outou, Ou te tuu atu ia te outou le poloaiga muamua lenei, ia outou o atu i lo’u igoa, outou uma taitoatasi, vagana ai a’u auauna o Iosefa Samita, Le Itiiti, ma Sini Rikitone."},{"verse":5,"text":"Ma Ou te tuu atu ia te i laua se poloaiga ia laua o atu mo se vaitau itiiti, ma o le a tuu atu e le mana o le Agaga le taimi la te toe foi mai ai."},{"verse":6,"text":"Ma ia outou o atu i le mana o lo’u Agaga, ma talai atu la’u talalelei, taitoalua, i lo’u igoa, ma sii a’e o outou leo faapei o le leo o se pu, e alaga atu la’u upu e pei o agelu a le Atua."},{"verse":7,"text":"Ma ia outou o atu ma papatiso atu i le vai, fai atu: Inā outou salamo ia, inā outou salamo ia, ona ua oo mai le malo o le lagi."},{"verse":8,"text":"Ma mai i lenei nofoaga, ia outou o atu ai i nofoaga i sisifo; ma e tusa ai ma lo outou mauaina o i latou o e o le a latou taliaina outou, ia outou atia’e la’u ekalesia i itulagi uma—"},{"verse":9,"text":"Sei oo i le taimi o le a faaali atu ai ia te outou mai luga, le taimi o le a saunia ai le aai o le Ierusalema Fou, ina ia mafai ona faapotopotoina outou i se tino e tasi, ina ia mafai ona avea outou ma o’u nuu ma o le a avea A’u ma o outou Atua."},{"verse":10,"text":"O lenei foi, Ou te fai atu ia te outou, o le a tulai pea la’u auauna o Eteuati Paterika i le tofiga ua Ou tofia i ai o ia. Ma o le a oo mai, afai e solitulafono o ia, o le a tofia se tasi i lona tulaga. E faapea lava. Amene."},{"verse":11,"text":"O lenei foi Ou te toe fai atu ia te outou, o le a lē tuuina atu i soo se tasi e alu e talai atu la’u talalelei, pe ati a’e la’u ekalesia, vagana ai ua faauuina o ia e se tasi ua i ai le pule, ma ua lauiloa i le ekalesia ua ia te ia le pule ma ua faauuina o ia i le ala e tatau ai e ao o le ekalesia."},{"verse":12,"text":"O lenei foi, ia aoao atu e toeaina, ositaulaga ma aoao o lenei ekalesia, mataupu autu o la’u talalelei, ua i ai i totonu o le Tusi Paia ma le Tusi a Mamona, ua i ai le atoatoaga o le talalelei."},{"verse":13,"text":"Ma ia latou vaai ia faia feagaiga ma mataupu faavae o le ekalesia, ma o mea ia ia latou aoao atu, e pei ona o le a taitaiina ai i latou e le Agaga."},{"verse":14,"text":"Ma o le a tuu atu ia te outou le Agaga e ala i le tatalo o le faatuatua; ma afai tou te lē maua le Agaga aua tou te aoao atu."},{"verse":15,"text":"Ma o nei mea uma ia outou vaai ia faia e pei ona Ou poloaiina e faatatau ia outou aoaoga, sei oo ina tuuina atu le atoatoaga o a’u tusitusiga paia."},{"verse":16,"text":"Ma a’o siitia a’e o outou leo e ala i le Fesoasoani, o le a outou tautatala ma vavalo atu e pei ona lelei ia te a’u;"},{"verse":17,"text":"Aua, faauta, ua silafia e le Fesoasoani mea uma, ma ua molimau e uiga i le Tamā ma le Atalii."},{"verse":18,"text":"Ma o lenei, faauta, Ou te tautala atu i le ekalesia. Aua e te fasioti tagata; ma o ia o lē e fasioti tagata o le a lē maua se faamagaloga i le lalolagi lenei, po o i le lalolagi a sau."},{"verse":19,"text":"O lenei foi, Ou te fai atu, aua e te fasioti tagata; ae o ia e fasioti tagata o le a oti."},{"verse":20,"text":"Aua e te gaoi; ma o ia o lē e gaoi ma lē salamo o le a tuli i fafo."},{"verse":21,"text":"Aua e te pepelo; o ia o lē e pepelo ma lē salamo o le a tuli i fafo."},{"verse":22,"text":"Ia e alofa i lau ava ma lou loto atoa, ma ia e pipii atu ia te ia ae lē o se isi."},{"verse":23,"text":"Ma o ia o lē e vaai atu i se fafine i le manao ia te ia, o le a faafiti e ia le faatuatua, ma o le a lē maua e ia le Agaga; ma afai e lē salamo o ia o le a tuli o ia i fafo."},{"verse":24,"text":"Aua e te mulilua; ma o ia o lē e mulilua, ma lē salamo, o le a tuli i fafo."},{"verse":25,"text":"Peitai o ia o lē ua mulilua ma ua salamo ma lona loto atoa, ma lafoai i ai, ma lē toe faia, ia outou faamagaloina."},{"verse":26,"text":"Ae afai e toe faia e ia, o le a lē faamagaloina o ia, ae o le a tuli i fafo."},{"verse":27,"text":"Aua e te tautala leaga e uiga i lē lua te tuaoi, pe faatiga ia te ia."},{"verse":28,"text":"Ua outou iloa o a’u tulafono e faatatau i nei mea ua tuu atu i totonu o a’u tusitusiga paia; o o ia o lē e agasala ma lē salamo o le a tuli i fafo."},{"verse":29,"text":"Afai e te alofa mai ia te a’u, e te auauna mai ia te a’u ma tausi i a’u poloaiga uma."},{"verse":30,"text":"Ma faauta, ia e manatua e ua matitiva, ma ia faapaiaina mo lo latou tausiga ni mea mai au meatotino ua ia te oe e faasoa atu ia te i latou, faatasi ma se feagaiga ma se pepa faamaonia mo meatotino e lē mafai ona solia."},{"verse":31,"text":"Ma e tusa ai ma la outou faasoa atu o a outou mea i e ua matitiva, ia outou faia ia te a’u; ma ia folasia atu ia mea i luma o le epikopo o la’u ekalesia ma ona fesoasoani, o ni toeaina e toalua, po o ni faitaulaga sili, o i laua ia o le a ia tofia pe ua ia tofia ma vaetofia mo lena faamoemoe."},{"verse":32,"text":"Ma o le a oo mai a uma ona folasia atu o ia mea i luma o le epikopo o la’u ekalesia, ma a uma ona ia maua o ia molimau e faatatau i le faapaiaga o meatotino a la’u ekalesia, e lē mafai ona aveesea o ia mea mai le ekalesia, e tusa ai ma a’u poloaiga, ia faia ia tali mai tagata uma taitoatasi ia te a’u, o se tausimea i luga o ana lava meatotino, po o mea ua ia maua e ala mai i le faapaiaga, e tusa ma le tele ua tatau ai mo ia lava ma le aiga."},{"verse":33,"text":"O lenei foi, afai e i ai ni meatotino i lima o le ekalesia, po o ni ona tagata taitoatasi, ua sili atu nai lo mea ua tatau ai mo lo latou tausiga pe a uma lenei faapaiaga muamua, o se toega lea e faapaia atu i le epikopo, ia teuina e avatu ia te i latou o e ua leai ni mea, mai lea taimi i lea taimi, ina ia lava tuuina atu ma maua e tagata uma taitoatasi o e ua manaomia ni mea, e tusa ma ona manao."},{"verse":34,"text":"O lea, o mea e totoe ia teu i lo’u faleteuoloa, e avatu i e ua matitiva ma e ua lē tagolima, e pei ona o le a tofia ai e le aufono maualuga o le ekalesia, ma le epikopo ma lana aufono;"},{"verse":35,"text":"Ma mo le faamoemoe o le faatauina mai o fanua mo le manuia lautele o le ekalesia, ma le fausia o fale tapuai, ma le atiina’eina o le Ierusalema Fou lea o le a faaali atu mulimuli mai—"},{"verse":36,"text":"Ina ia mafai ona faapotopotoina o lo’u nuu o le feagaiga i se tino e tasi i lena aso pe a Ou alu atu i lo’u malumalu. Ma o le a Ou faia lenei mea mo le faaolataga o o’u tagata."},{"verse":37,"text":"Ma o le a oo mai, o le a tuli ese i fafo o le ekalesia o ia o lē e agasala ma lē salamo, ma o le a lē toe mauaina e ia mea na ia faapaia mai mo e ua matitiva ma lē tagolima o la’u ekalesia, po o i ni isi upu, ia te a’u—"},{"verse":38,"text":"E faapei ona outou faia o ia mea i se aupito itiiti o i latou nei, ua outou faia ia mea ia te a’u."},{"verse":39,"text":"Aua o le a oo mai le faataunuuina o mea na Ou tautala atu ai e ala i fofoga o a’u perofeta; ona o le a Ou faapaiaina ni mea mai oloa a i latou o e e taliaina la’u talalelei i totonu o Nuuese, mo e ua matitiva o lo’u nuu o e o le aiga o Isaraelu."},{"verse":40,"text":"O lenei foi, aua e te faamaualuga i lou loto; ia faafaigofie ou ofu uma, ma o lo latou matagofie ia tuu ia faia i le matagofie o galuega a ou lava lima;"},{"verse":41,"text":"Ma ia tuu atu i mea uma ia faia i le mama i o’u luma."},{"verse":42,"text":"Aua e te paie; ona o ia e paie o le a lē ’aia le areto pe ofu i ofu o lē e galue."},{"verse":43,"text":"Ma o soo se tasi e i totonu o outou ua ma’i, ma ua leai se faatuatua e faamaloloina ai, ae ua talitonu, ia tausia ma le faapelepele atoa, i laau-afu ma meaai vaivai, ae lē i le lima o se fili."},{"verse":44,"text":"Ma ia valaauina ni toeaina o le ekalesia, e toalua pe sili atu, e tatalo mo i latou ma faaee o latou lima i luga o i latou i lo’u igoa; ma afai e oti i latou e oti i latou ia te a’u, ma afai e ola i latou e ola i latou ia te a’u."},{"verse":45,"text":"Ia outou nonofo faatasi i le alofa, ia outou fetagisi ai i le toesea o i latou o e ua oti, ma aemaise lava mo i latou o e ua leai se faamoemoe mo se toetutu mamalu."},{"verse":46,"text":"Ma o le a oo mai o le a lē tofo i le oti i latou o e e oti ia te a’u, aua o le a suamalie ia te i latou;"},{"verse":47,"text":"Ma o i latou o e e lē oti ia te a’u, oi talofa ia te i latou, aua e oona lo latou oti."},{"verse":48,"text":"O lenei foi, o le a oo mai e faamaloloina o ia o lē ua faatuatua mai ia te a’u, ma ua lē tofia e oti, o le a faamaloloina."},{"verse":49,"text":"O ia o lē ua i ai le faatuatua e vaai ai o le a vaai."},{"verse":50,"text":"O ia o lē ua i ai le faatuatua e faalogo ai o le a faalogo."},{"verse":51,"text":"O le pipili o lē ua i ai le faatuatua e oso ai o le a oso."},{"verse":52,"text":"Ma o i latou o e ua lē i ai le faatuatua e faia ai nei mea, ae ua talitonu mai ia te a’u, ua i ai le mana e avea ai mo o’u atalii; ma e tusa ai ma lo latou lē solia o a’u tulafono, ia e tauaveina o latou vaivaiga."},{"verse":53,"text":"Ia e tulai i le tulaga o lau mea-tausi."},{"verse":54,"text":"Aua e te ave le ofu o lou uso; ia e totogi mo mea e te maua mai lou uso."},{"verse":55,"text":"Ma afai e te maua ni mea e sili atu nai lo mea mo lou tausiga, ia e tuu atu ia mea i lo’u faleteuoloa, ina ia mafai ona faia o mea uma e tusa ai ma mea ua Ou fai atu ai."},{"verse":56,"text":"Ia e ole mai, ma o le a tuuina atu ai a’u tusitusiga paia e pei ona Ou tofia, ma o le a faasaoina i latou i le saogalemu;"},{"verse":57,"text":"Ma ua tatau ai ia te oe ona taofi lou filemu e faatatau i ia tusitusiga paia, ma lē aoaoina atu i latou seia e mauaina i latou i le atoatoa."},{"verse":58,"text":"Ma Ou te tuu atu ia te outou se poloaiga, ona outou aoao atu ai lea o i latou i tagata uma; ona o le a aoao atu i latou i atunuu uma, ituaiga, gagana ma nuu."},{"verse":59,"text":"Ia e ave mea ua e mauaina, ia na tuu atu ia te oe i a’u tusitusiga paia mo se tulafono, e avea ma a’u tulafono e pulea ai la’u ekalesia;"},{"verse":60,"text":"Ma o ia o lē na te faia e tusa ma nei mea, o le a faaolaina, ma o ia o lē na te lē faia ia mea o le a malaia pe afai e faaauau pea o ia faapea."},{"verse":61,"text":"Afai e te ole mai, o le a e maua lea faaaliga e faaopoopo i luga o lea faaaliga, lea malamalama e faaopoopo i luga o lea malamalama, ina ia mafai ona e iloa mealilo ma mea filemu—o mea ia e maua ai le olioli, o mea ia e maua ai le ola e faavavau."},{"verse":62,"text":"Ia e ole mai, ma o le a faaali atu ia te oe i lo’u lava taimi e tatau ai le mea o le a faatuina ai le Ierusalema Fou."},{"verse":63,"text":"Ma faauta, o le a oo mai o le a auina atu a’u auauna i sasae ma sisifo, i matu ma i saute."},{"verse":64,"text":"Ma i le taimi nei lava, ia tuu atu ia te ia o lē e alu atu i sasae ia aoaoina i latou o e o le a liliu mai, ia sosola atu i sisifo, ma o le pogai o lenei mea ona o mea o le a oo mai i luga o le lalolagi, ma ona o faapotopotoga faalilolilo."},{"verse":65,"text":"Faauta, ia e tausia nei mea uma, ma o le a tele lava lou taui; ona ua tuu atu ia te outou ia outou iloaina mealilo o le malo, ae ua lē tuuina atu i le lalolagi ia latou iloaina."},{"verse":66,"text":"Ia outou tausia tulafono ua outou maua ma ia faamaoni."},{"verse":67,"text":"Ma o le a outou maua i se taimi o mulimuli mai feagaiga o le ekalesia, ia o le a lava e faatutumau ai outou iinei ma i le Ierusalema Fou."},{"verse":68,"text":"O lea, o ia o lē ua lē o i ai se poto, ia tuu atu ia te ia e ole mai ia te a’u, ma o le a Ou foai tele atu ia te ia ma lē aoaiina o ia."},{"verse":69,"text":"Ia siitia a’e o outou loto ma olioli, ona ua tuu atu ia te outou le malo, pe faapea foi, o ki o le ekalesia. Ua faapea lava. Amene."},{"verse":70,"text":"O le a maua e ositaulaga ma aoao a latou matafaioi, e pei lava o tagata o le ekalesia."},{"verse":71,"text":"Ma o toeaina po o faitaulaga sili o e ua tofia e lagolago i le epikopo o ni fesoasoani i mea uma, ia tausia o latou aiga mai meatotino ua faapaia atu i le epikopo, mo le lelei o e ua matitiva, ma mo isi faamoemoega, e pei ona ta’ua atu muamua;"},{"verse":72,"text":"Pe ia latou maua se totogi tatau ai mo a latou auaunaga uma, pe i se mea-tausi po o se isi mea, e pei ona manatu pe filifili i ai le epikopo ma ona fesoasoani ua sili ona lelei."},{"verse":73,"text":"Ma ia maua foi e le epikopo lona tausiga, po o se totogi tatau ai, mo ana auaunaga uma i le ekalesia."},{"verse":74,"text":"Faauta, e moni Ou te fai atu ia te outou, o ai lava ni tagata i totonu o outou, ua tuu ese a latou soa ona o le faitaaga, po o i ni isi upu, afai latou te molimau mai i o outou luma i le maualalo atoa o le loto o le tulaga lea ua i ai, aua tou te tutuliesea i latou mai totonu o outou;"},{"verse":75,"text":"Ae afai tou te maua ni tagata ua latou tuua a latou soa ona o le mulilua, ma o i latou lava ua solitulafono, ma o loo soifua pea a latou soa, ia tutuliese i latou mai i totonu o outou."},{"verse":76,"text":"O lenei foi, Ou te fai atu ia te outou, ia outou mataala ma faaeteete, i le suesue lelei atoa, ina ia outou lē talia ni isi faapea i totonu o outou, pe afai ua faaipoipoina i latou;"},{"verse":77,"text":"Ma afai e lei faaipoipoina i latou, ia latou salamo ia latou agasala uma, po ua outou lē taliaina i latou."},{"verse":78,"text":"O lenei foi, o tagata uma taitoatasi o e ua i ai i lenei ekalesia a Keriso, ia vaai ia latou tausia poloaiga ma feagaiga uma o le ekalesia."},{"verse":79,"text":"Ma o le a oo mai, afai e i ai ni tagata o outou e fasioti tagata, ia avatu i latou i luga ma faia ia te i latou e tusa ai ma tulafono o le laueleele; aua ia manatua ua leai se faamagaloga mo ia; ma ia faamaonia lena mea e tusa ma tulafono o le laueleele."},{"verse":80,"text":"Ma afai e faia e soo se alii po o se tamaitai le mulilua, ia faamasinoina o ia i luma o ni toeaina e toalua, pe sili atu, o le ekalesia, ma ia faamautuina upu uma e faasaga i lea alii po o le tamaitai e ni molimau e toalua o le ekalesia, ae lē o le fili; ae afai ua sili atu i le toalua ni molimau ua i ai, ua sili atu ona lelei."},{"verse":81,"text":"Peitai o fofoga o molimau e toalua e tausalaina ai lea alii po o le tamaitai; ma ia folasia atu e toeaina le moliaga i luma o le ekalesia, ma ia siitia a’e e le ekalesia o latou lima e faasaga i lea alii po o le tamaitai, ina ia mafai ona faia ia te i laua e tusa ai ma le tulafono a le Atua."},{"verse":82,"text":"Ma afai e mafai, e tatau i le epikopo ona auai foi."},{"verse":83,"text":"Ma ia faapea ona outou faia i moliaga uma e oo mai i o outou luma."},{"verse":84,"text":"Ma afai e faomea se alii po o se tamaitai, ia avatu lea alii po o le tamaitai i luma o le tulafono o le laueleele."},{"verse":85,"text":"Ma afai e gaoi se alii po o se tamaitai, ia avatu lea alii po o le tamaitai i luma o le tulafono o le laueleele."},{"verse":86,"text":"Ma afai e pepelo se alii po o se tamaitai, ia avatu lea alii po o le tamaitai i luma o le tulafono o le laueleele."},{"verse":87,"text":"Ma afai e faia e se alii po o se tamaitai soo se ituaiga o amioletonu, ia avatu lea alii po o le tamaitai i le tulafono, le tulafono lava a le Atua."},{"verse":88,"text":"Ma afai e faatausuai mai sou uso po o sou tuafafine ia te oe, ia e ave lea uso po o lea tuafafine tau lava o ia ma oe; ma afai e ta’uta’u mai e lea uso po o lea tuafafine, ia e faalelei atu i ai."},{"verse":89,"text":"Ma afai e lē ta’uta’u mai e lea alii po o lea tuafafine, ia e avatu lea alii po o le tuafafine i luma o le ekalesia, e lē i tagata o le ekalesia, ae i toeaina. Ma ia faia lea i se fono, ae lē o luma o le lalolagi."},{"verse":90,"text":"Ma afai e faatausuai sou uso po o sou tuafafine i ni tagata e toatele, ia aoaia o ia i luma o tagata e toatele."},{"verse":91,"text":"Ma afai e faatausuai aliali se tasi, ia aoaiina faaaliali lea alii po o le tamaitai, ina ia faamaasiasi lea alii po o le tamaitai. Ma afai e lē ta’uta’u mai e lea alii po o le tamaitai, ia avatu lea alii po o le tamaitai i luga i le tulafono a le Atua."},{"verse":92,"text":"Afai e i ai se e faatausuai faalilolilo, ia aoaiina faalilolilo lea alii po o le tamaitai, ina ia mafai ona maua e lea alii po o le tamaitai le avanoa e ta’uta’u faalilolilo atu ai i le alii po o le tamaitai na faatausuai i ai, ma i le Atua, ina ia lē ta’u inosia lea alii po o le tamaitai e le ekalesia."},{"verse":93,"text":"Ma ia faapea ona outou faia i mea uma."}]},{"chapter":43,"verses":[{"verse":1,"text":"Faalogo mai ia, outou toeaina o la’u ekalesia, ma uai mai o outou taliga i upu o le a Ou tautala atu ai ia te outou."},{"verse":2,"text":"Aua faauta, e moni, e moni, Ou te fai atu ia te outou, ua outou maua se poloaiga mo se tulafono i la’u ekalesia, e ala atu ia te ia o lē na Ou tofi atu ia te outou na te mauaina poloaiga ma faaaliga mai lo’u lima."},{"verse":3,"text":"Ma o le mea lenei ia outou iloa ma le mautinoa—e leai se isi e ese mai ua tofia atu ia te outou na te mauaina poloaiga ma faaaliga seia oo ina aveesea o ia, pe afai e tu mau o ia ia te a’u."},{"verse":4,"text":"Ae e moni, e moni, Ou te fai atu ia te outou, e leai se isi e tofia i lenei meaalofa vagana ai ua ala mai ia te ia; aua afai e aveesea mai ia te ia, o le a leai se mana e ia te ia nao le tofia o se isi tagata i lona tulaga."},{"verse":5,"text":"Ma ia avea lenei mea o se tulafono ia te outou, ia outou lē taliaina aoaoga a soo se tasi e sau i o outou luma, o ni faaaliga po o ni poloaiga;"},{"verse":6,"text":"Ma ua Ou tuu atu ia te outou lenei mea ina ia lē faaseseina outou, ina ia outou iloa ua lē mai ia te a’u i latou."},{"verse":7,"text":"Aua e moni Ou te fai atu ia te outou, o ia o lē ua Ou faauuina, e sau i totonu e ala mai i le faitotoa ma faauuina e pei ona Ou ta’u atu muamua ia te outou, e aoao atu faaaliga na ua outou mauaina ma o le a outou mauaina e ala atu ia te ia o lē ua Ou tofia."},{"verse":8,"text":"Ma o lenei, faauta, Ou te tuu atu ia te outou se poloaiga, a outou faapotopoto faatasi, ia outou aoao ma faagaeetia le tasi i le isi, ina ia outou iloa le ala tou te faia ma taitai ai la’u ekalesia, le ala tou te faia ai e faatatau i mataupu o la’u tulafono ma poloaiga, ia ua uma ona Ou tuuina atu."},{"verse":9,"text":"Ma o le a faapea ona aoaoina ai outou i le tulafono o la’u ekalesia, ma faapaiaina ai i mea na ua outou mauaina, ma ia outou fusia faatasi ai outou lava ia outou faia ma le paia atoatoa i o’u luma—"},{"verse":10,"text":"Ina ia tusa ai ma lo outou faia o lenei mea, o le a faaopoopo ai le mamalu i le malo ua outou maua. E tusa ai ma lo outou lē faia o lea mea, o le a ’aveesea ai, e oo lava i mea ua outou maua."},{"verse":11,"text":"Ia outou faamama ese le amioletonu ua i ai i totonu o outou; ia outou faapaia outou lava i o’u luma;"},{"verse":12,"text":"Ma afai tou te mananao i mamalu o le malo, ia outou tofia la’u auauna o Iosefa Samita, Le Itiiti, ma lagolago o ia i o’u luma e ala i le tatalo o le faatuatua."},{"verse":13,"text":"O lenei foi, Ou te fai atu ia te outou, afai tou te mananao i mealilo o le malo, tuu atu ia te ia meaai ma ofu, ma soo se mea e manaomia e ia e faataunuu ai le galuega ua Ou poloaiina ai o ia;"},{"verse":14,"text":"Ma afai tou te lē faia o le a tumau pea o ia ia te i latou o e ua latou taliaina o ia, ina ia mafai ona Ou faasaoina mo a’u lava se nuu mama i o’u luma."},{"verse":15,"text":"Ou te toe fai atu, faalogo mai ia outou toeaina o la’u ekalesia, o e ua Ou tofia: Ua lē auina atu outou ia aoaoina, ae ia aoao atu i le fanauga a tagata mea ua Ou tuu atu i o outou lima e ala i le mana o lo’u Agaga;"},{"verse":16,"text":"Ma o le a aoaoina outou mai luga. Ia outou faapaia outou lava ma o le a faaeeina outou i le mana, ina ia mafai ona outou tuuina atu e pei lava ona Ou tautala atu ai."},{"verse":17,"text":"Ia outou faalogo mai, aua, faauta, ua lata mai ona oo mai le aso tele o le Alii."},{"verse":18,"text":"Aua e oo mai le aso o le a tulei mai ai e le Alii lona siufofoga mai le lagi; o le a luluina le lagi ma o le a gatete le lalolagi, ma o le a umi ma leotele le iliga o le pu a le Atua, ma o le a fai atu i atunuu momoe: Outou le au paia e ia tutulai mai ia ma ola; outou e ua agasala ia nonofo ma momoe pea seia Ou toe valaau atu."},{"verse":19,"text":"O le mea lea ia fusi i o outou sulugatiti ne’i maua outou i totonu o e ua amioleaga."},{"verse":20,"text":"Siitia a’e i luga o outou leo ma lē taofia. Valaau atu i atunuu ia salamo, o e matutua ma e talavou, o e pologa ma e saoloto, ia fai atu: Ia outou saunia outou lava mo le aso tele o le Alii;"},{"verse":21,"text":"Aua afai e siitia a’e e a’u, o se tagata, lo’u leo i luga ma valaau atu ia te outou ia salamo, ae outou inoino mai ia te a’u, o le a se mea tou te fai mai pe a oo mai le aso o le a taalilili mai ai leo o faititili mai tuluiga o le lalolagi, e tautala mai i taliga o e uma e ola, fai mai—Ia salamo, ma sauni mo le aso tele o le Alii?"},{"verse":22,"text":"Ioe, o lenei foi, pe a feemo ane uila mai sasa’e i sisifo, ma lologo atu o latou leo i e uma e ola, ma faia ia ī taliga o e uma e faalogoina, ma fai atu upu nei—Ia outou salamo, ona ua oo mai le aso tele o le Alii?"},{"verse":23,"text":"O lenei foi, o le a tulei mai e le Alii lona siufofoga mai le lagi, fai mai: Faalogo mai ia, outou e atunuu o le lalolagi, ma faalogo mai i fetalaiga a le Atua lena o lē na faia outou."},{"verse":24,"text":"E, outou e atunuu o le lalolagi, ua faafia ona po ua Ou faapotopotoina faatasi o outou e pei ona ofaofatai e se matuamoa lana toloai i lalo o ona apaau, ae outou lē mananao i ai!"},{"verse":25,"text":"Ua faafia ona Ou valaau atu ia te outou e ala i fofoga o a’u auauna, ma i auaunaga a agelu, ma i lo’u lava leo, ma i le leo o faititili, ma i le leo o uila, ma i le leo o afā, ma i le leo o mafuie, ma uato’a tetele, ma i le leo o oge ma ituaiga o faamai eseese, ma i le leo tele o se pu, ma i le leo o le faamasinoga, ma i le leo o le alofa mutimutivale i le aso atoa, ma i le leo o le viiga ma le mamalu ma oa o le ola e faavavau, ma po ua Ou faaolaina outou i le olataga e faavavau, ae outou lē mananao i ai!"},{"verse":26,"text":"Faauta, ua oo mai le aso, ua tumu ai le ipu o le sauā o lo’u ita."},{"verse":27,"text":"Faauta, e moni Ou te fai atu ia te outou, o afioga nei a le Alii lo outou Atua."},{"verse":28,"text":"O le mea lea, ia outou galulue, ia outou galulue i lo’u tovine mo le taimi mulimuli—ona o le taimi mulimuli e valaau atu ai i e o nonofo i le lalolagi."},{"verse":29,"text":"Aua o le a Ou alu atu i lo’u lava taimi e tatau ai i luga o le lalolagi i le faamasinoga, ma o le a togiolaina lo’u nuu ma o le a nonofotupu faatasi ma a’u i luga o le lalolagi."},{"verse":30,"text":"Aua o le a oo mai le Meleniuma tele, lea na Ou fai atu ai e ala i fofoga o a’u auauna."},{"verse":31,"text":"Aua o le a noatia Satani, ma a toe tatalaina o ia, o le a nofotupu o ia mo nao se vaitau itiiti, ona oo mai ai lea o le iuga o le lalolagi."},{"verse":32,"text":"Ma o ia o lē e ola i le amiotonu o le a liua e pei o le emo o se mata, ma o le a mavae atu le lalolagi e peiseai o se afi."},{"verse":33,"text":"Ma o e e amioleaga o le a o ese atu i le afi e lē matineia, ma o lo latou iuga e leai se tasi i luga o le lalolagi ua iloaina, pe na te iloaina lava, seia latou o mai i o’u luma i le faamasinoga."},{"verse":34,"text":"Ia outou faalogo mai i nei upu. Faauta, o A’u o Iesu Keriso, o le Faaola o le lalolagi. Ia teu i o outou loto nei mea, ma ia tuu le tulaga-mamalu o le faavavau ia mau i luga o o outou mafaufau."},{"verse":35,"text":"Ia faamamalu. Tausi i au poloaiga uma. Ia faapea lava. Amene."}]},{"chapter":44,"verses":[{"verse":1,"text":"Faauta, ua faapea ona fetalai mai o le Alii ia te oulua o a’u auauna, ua tatau ai ia te a’u ona valaaulia toeaina o la’u ekalesia ia faatasi mai, mai sasae ma sisifo, ma mai matu ma saute, i se tusi po o se isi ala."},{"verse":2,"text":"Ma o le a oo mai e tusa ai ma lo latou faamaoni, ma faatino le faatuatua mai ia te a’u, o le a Ou liligi ifo lo’u Agaga i luga o i latou i le aso o le a latou faapotopoto faatasi ai i latou lava."},{"verse":3,"text":"Ma o le a oo mai o le a latou o atu i nofoaga o faataamilo ai, ma talai atu le salamo i tagata."},{"verse":4,"text":"Ma e toatele o le a liliu mai, e oo ina outou maua ai le pule tou te faatulaga ai outou lava e tusa ma tulafono a tagata;"},{"verse":5,"text":"Ina ia leai se mana o o outou fili i luga o outou; ina ia mafai ona faasaoina o outou i mea uma; ina ia mafai ona outou tausia a’u tulafono; ina ia mafai ona motusia o noanoaga uma ua saili le fili e faaumatia ai o’u tagata."},{"verse":6,"text":"Faauta, Ou te fai atu ia te oulua, e ao ina oulua asiasi atu i e ua matitiva ma e ua lē tagolima ma fesoasoani atu i lo latou toomaga, ina ia mafai ona tausia i latou seia mafai ona faia o mea uma e tusa ai ma la’u tulafono ua oulua maua. Amene."}]},{"chapter":45,"verses":[{"verse":1,"text":"Faalogo mai ia, outou e tagata o la’u ekalesia, o e ua tuu atu i ai le malo; ia outou faalogo mai ia ma uai mai o outou taliga ia te ia o lē na faataotoina le faavae o le lalolagi, o lē na faia le lagi ma ona ’au uma, ma o lē na faia mea uma e ola, ma gaoioi, ma i ai."},{"verse":2,"text":"Ma Ou te toe fai atu, faalogo mai ia i lo’u leo, ne’i manumalo le oti ia te outou; i se itula tou te lē manatunatu ai o le a mavae atu ai le taumafanafana, ma uma ai le seleselega, ma lē faaolaina ai o outou agaga."},{"verse":3,"text":"Faalogo ia ia te ia o lē o le fautua i le Tamā, o lē o loo augani lo outou faamoemoe i ona luma—"},{"verse":4,"text":"Ua fetalai atu: Le Tamā e, faauta i mafatiaga ma le oti o lē na lē faia e ia se agasala, o lē na e fiafia tele i ai; faauta i le toto o lou Atalii na faamaligiina, le toto o ia o lē na e tuu atu ina ia faamamaluina oe;"},{"verse":5,"text":"O le mea lea, le Tamā e, ia faasaoina i latou nei o o’u uso o e ua talitonu i lo’u igoa, ina ia mafai ona latou o mai ia te a’u ma maua le ola tumau e faavavau."},{"verse":6,"text":"Faalogo mai ia, outou e tagata o la’u ekalesia, ma faalogo faatasi mai outou toeaina, ma faalogo mai i lo’u leo a’o valaau atu i le aso, ma aua le faamaaaina o outou loto;"},{"verse":7,"text":"Aua e moni Ou te fai atu ia te outou, o A’u o le Alefa ma le Omeka, o le amataga ma le gataaga, o le malamalama ma le ola o le lalolagi—o se malamalama ua susulu i le pouliuli ma ua lē malamalama i ai le pouliuli."},{"verse":8,"text":"Na Ou sau i lo’u lava nuu, ma sa lē talia a’u e lo’u lava nuu; ae o le toatele o i latou o e na talia a’u na Ou tuu atu i ai le mana latou te faia ai vavega e tele, ma avea ai ma atalii o le Atua; ma o i latou na talitonu i lo’u igoa na Ou tuu atu lava i ai le mana latou te maua ai le ola e faavavau."},{"verse":9,"text":"Ma ua faapea lava ona Ou auina atu o la’u feagaiga e faavavau i le lalolagi, e avea o se malamalama i le lalolagi, ma avea o se tagavai mo lo’u nuu, ma Nuuese ia saili i ai, ma avea o se avefeau i luma o o’u mata e sauni le ala i o’u luma."},{"verse":10,"text":"O le mea lea, ia outou o mai i ai, ma o le a Ou filifili faatasi ma ia o lē e sau e pei ona Ou faia ma tagata i aso anamua, ma o le a Ou faaali atu ia te outou le malosi o lo’u manatu."},{"verse":11,"text":"O le mea lea, ia outou faalogo mai faatasi ma tuu mai ia te a’u e faailoa atu ia te outou lo’u poto lava—o le poto lea o ia o lē ua outou fai mai o le Atua o Enoka, ma ona uso,"},{"verse":12,"text":"O e na vavae ese mai le lalolagi, ma na Ou talia mo a’u lava—o se aai ua faasaoina seia oo mai se aso o le amiotonu—o se aso lea sa saili i ai tagata paia uma, ma sa latou lē mauaina ona o le amioleaga ma mea inosia;"},{"verse":13,"text":"Ma latou fai mai ai o i latou o ni tagata ese ma e ua aumau i luga o le lalolagi;"},{"verse":14,"text":"Peitai sa latou maua se folafolaga o le a latou mauaina ma vaai i ai i o latou tino."},{"verse":15,"text":"O le mea lea, faalogo mai ma o le a Ou talatala faatasi ma outou, ma o le a Ou tautala atu ia te outou ma vavalo atu, e pei ona faia i tagata i aso anamua."},{"verse":16,"text":"Ma o le a Ou faaalia manino atu e pei ona sa Ou faaalia atu i o’u soo a’o Ou tulai i o latou luma i le tino, ma tautala atu ia te i latou, ua fai atu: Ona ua outou ole mai ia te a’u e uiga i faailoga o lo’u sau, i le aso pe a Ou alu atu i lo’u mamalu i ao o le lagi, e faataunuu ai folafolaga na Ou faia i o outou tamā,"},{"verse":17,"text":"Aua e pei ona outou vaai i le umi o le o ese o o outou agaga mai i o outou tino o se nofopologa, o le a Ou faaali atu ai ia te outou le ala o le a oo mai ai le aso o le togiolaina, ma le toefuataiga foi o Isaraelu ua faataapeapeina."},{"verse":18,"text":"Ma o lenei, ua outou vaai i lenei malumalu ua i Ierusalema, lea ua outou ta’ua o le maota o le Atua, ma ua fai mai o outou fili o le a lē pa’ū lava lenei fale."},{"verse":19,"text":"Ae, e moni Ou te fai atu ia te outou, o le a oo mai faatafunaga i luga o lenei tupulaga e pei o se gaoi i le po, ma o le a faaumatia lenei nuu ma faataapeapeina i totonu o atunuu uma."},{"verse":20,"text":"Ma o lenei malumalu ua outou vaai atu nei i ai o le a soloia i lalo o le a lē tuua se tasi maa e taatia i luga o se isi maa."},{"verse":21,"text":"Ma o le a oo mai, o le a lē mavae atu lenei tupulaga o tagata Iutaia seia faataunuuina faatafunaga uma na Ou fai atu ai ia te outou e faatatau ia te i latou."},{"verse":22,"text":"Ua outou fai mai ua outou iloa o le a oo mai le iuga o le lalolagi; ua outou fai mai foi ua outou iloa o le a mavae atu le lagi ma le lalolagi;"},{"verse":23,"text":"Ma i lenei mea, ua moni la outou upu, ona ua faapea lava; ae o nei mea ua Ou ta’u atu ia te outou o le a lē mavae atu seia faataunuuina mea uma."},{"verse":24,"text":"Ma ua Ou ta’u atu ia te outou lenei mea e faatatau ia Ierusalema; ma a oo mai lena aso, o le a faataapeapeina se vaega o totoe i atunuu uma;"},{"verse":25,"text":"Peitai o le a toe faapotopoto mai i latou; ae o le a latou nonofo pea seia faataunuuina aso o Nuuese."},{"verse":26,"text":"Ma i lena aso o le a faalogoina ai taua ma tala o taua, ma o le a vāvāō le lalolagi atoa, ma o le a faavaivaia loto o tagata, ma o le a latou fai mai ua tolopo e Keriso lona afio mai seia oo i le iuga o le lalolagi."},{"verse":27,"text":"Ma o le a faasolo maluluina le alofa o tagata, ma o le a faateteleina le amioletonu."},{"verse":28,"text":"Ma a oo mai taimi o Nuuese, o le a susulu atu se malamalama i totonu o i latou o e o nonofo i le pouliuli, ma o le atoatoaga lea o la’u talalelei;"},{"verse":29,"text":"Peitai latou te lē taliaina; ona latou te lē iloaina le malamalama, ma ua latou liliu ese o latou loto mai ia te a’u ona o mataupu a tagata."},{"verse":30,"text":"Ma o le tupulaga lena o le a faataunuuina ai taimi o Nuuese."},{"verse":31,"text":"Ma o le a i ai ni tagata e tutulai i lena tupulaga o le a lē mavae atu seia latou vaai i se faasalaga tele naua; ona o le a ufitia le laueleele i se faamai faatafunaina."},{"verse":32,"text":"Ae o o’u soo o le a tutulai i nofoaga paia, ma o le a lē masii lava; ae i totonu o e e amioleaga, o le a siitia a’e i luga e tagata o latou leo ma upuleaga le Atua ma feoti ai."},{"verse":33,"text":"Ma o le a i ai foi mafuie i nofoaga eseese, ma faatafunaga e tele; peitai o le a faamaaa e tagata o latou loto faasaga mai ia te a’u, ma o le a latou siia’e i luga le pelu, o le tasi e faasaga i le isi, ma o le a latou fasioti o le tasi i le isi."},{"verse":34,"text":"Ma o lenei, ina ua tautala atu e A’u o le Alii nei upu i o’u soo, sa latou atuatuvale."},{"verse":35,"text":"Ma sa Ou fai atu ia te i latou: Aua tou te atuatuvale, aua, a faataunuuina nei mea uma, o le a mafai ona outou iloa o le a faataunuuina folafolaga na fai atu ia te outou."},{"verse":36,"text":"Ma a amata ona susulu atu o le malamalama, o le a i ai faatasi ma i latou e pei o se faataoto o le a Ou faaali atu ia te outou—"},{"verse":37,"text":"Tou te vaai ma iloa atu laau o mati, ma e tou te vaai atu ia te i latou i o outou mata, ma tou fai ane pe a amata ona latou totogo a’e, ma a’o mu’amu’a pea o latou lau, ua lata mai nei le tau mafanafana;"},{"verse":38,"text":"O le a faapea lava ona i ai i lena aso pe a latou vaai i nei mea uma, ona latou iloa ai lea ua lata mai le itula."},{"verse":39,"text":"Ma o le a oo mai o le a tulimatai i luma o ia o lē e mata’u ia te a’u mo le oo mai o le aso tele o le Alii, e oo lava i faailoga o le afio mai o le Atalii o le Tagata."},{"verse":40,"text":"Ma o le a latou vaai i faailoga ma mea e ofo ai, ona o le a faaalia i latou i le lagi i luga, ma i le lalolagi o i lalo."},{"verse":41,"text":"Ma o le a latou vaaia le toto, ma le afi, ma le puao o le asu."},{"verse":42,"text":"Ma ae lei oo mai le aso o le Alii, o le a faapouliuligia le la, ma gasetoto le masina, ma o le a pa’u’ū ifo fetu mai le lagi."},{"verse":43,"text":"Ma o le a faapotopoto mai le vaega o totoe i lenei nofoaga;"},{"verse":44,"text":"Ma ona latou vaavaai lea mo a’u, ma, faauta, o le a Ou sau; ma o le a latou vaaia a’u i ao o le lagi, ua faaofuina i le mana ma le mamalu tele; faatasi ma agelu paia uma; ma o ia o lē e lē vaavaai mo a’u o le a vavae ese."},{"verse":45,"text":"Peitai ae lei pa’ū mai le aao o le Alii, o le a ilia e se agelu lana pu, ma o le a tutulai mai le au paia o e na momoe e faafetaiai a’u i le ao."},{"verse":46,"text":"O le mea lea, afai na outou momoe i le filemu, amuia outou; ona e pei ona outou vaai mai nei ia te a’u ma iloa ua Ou i ai, o le a faapea lava ona outou o mai ia te a’u ma ola ai o outou agaga, ma o le a faaatoatoaina lo outou togiolaina; ma o le a o mai le au paia mai i itu e fa o le lalolagi."},{"verse":47,"text":"Ona pa’ū mai ai lea o le aao o le Alii i luga o atunuu."},{"verse":48,"text":"Ma ona afio a’e lea o le Alii i luga o le mauga lenei, ma o le a vaeluaina, ma o le a gatete le lalolagi, ma malualua solo, ma o le a luluina foi le lagi."},{"verse":49,"text":"Ma o le a tulei mai e le Alii lona siufofoga, ma o le a lagona e tuluiga uma o le lalolagi; ma o le a laue faavauvau atunuu uma o le lalolagi, ma o i latou o e na toē o le a vaai i lo latou valea."},{"verse":50,"text":"Ma o le a ufitia i mala lē e tauemu, ma o lē e ’amu’amu o le a faaumatia; ma o i latou o e na vaavaai mo le amioletonu o le a taia i lalo ma lafo i le afi."},{"verse":51,"text":"Ma ona vaai mai ai lea o tagata Iutaia i luga ia te a’u ma fai mai: O a ia manua ua i ou lima ma ou vae?"},{"verse":52,"text":"Ona latou iloa lea o A’u o le Alii; ona o le a Ou fai atu ia te i latou: O nei manua, o manua ia na Ou manua ai i le fale o a’u uo. O A’u o lē na siitia a’e i luga. O A’u o Iesu o lē na faasatauroina. O A’u o le Atalii o le Atua."},{"verse":53,"text":"Ma ona latou fetagisi ai lea ona o a latou amioletonu; ona latou tagiauē ai lea ona ua latou sauaina lo latou tupu."},{"verse":54,"text":"Ma ona togiolaina ai lea o atunuu faapaupau, ma o i latou o e sa latou lē iloa se tulafono o le a i ai sa latou vaega i le uluai toetutu; ma o le a gafatia e i latou."},{"verse":55,"text":"Ma o le a noatia Satani, o le a lē maua ai e ia se nofoaga i totonu o loto o le fanauga a tagata."},{"verse":56,"text":"Ma i lena aso, pe a Ou alu atu i lo’u mamalu, o le a faataunuu ai le faataoto na Ou tautala atu ai e faatatau i taupou e toasefulu."},{"verse":57,"text":"Aua o i latou o e e popoto ma ua latou talia le upumoni, ma ua latou ave le Agaga Paia mo o latou taiala, ma sa lei faaseseina—e moni Ou te fai atu ia te outou, o le a lē taia i latou ma lafo i le afi, ae o le a latou gafatia le aso."},{"verse":58,"text":"Ma o le a tuu atu ia te i latou le lalolagi e fai mo so latou tofi; ma o le a latou uluuluola ma faasolo malolosi, ma o le a tutupu a’e i le olataga a latou fanau e aunoa ma le agasala."},{"verse":59,"text":"Ona o le a i ai le Alii i lo latou lotolotoi, ma o le a i ai lona mamalu i luga o i latou, ma o le a avea o ia ma o latou tupu ma o latou faitulafono."},{"verse":60,"text":"Ma o lenei, faauta, Ou te fai atu ia te outou, o le a lē tuu atu ia te outou ia outou iloa atili ni isi mea e faatatau i lenei mataupu, seia faaliliuina le Feagaiga Fou, ma o ona totonu o le a faailoa atu ai ia mea uma;"},{"verse":61,"text":"O le mea lea Ou te tuu atu ia te oe ia mafai nei ona e faaliliuina, ina ia mafai ona outou saunia mo mea o le a oo mai."},{"verse":62,"text":"Aua e moni Ou te fai atu ia te outou, e i ai mea sili o loo faatali mai mo outou;"},{"verse":63,"text":"Ua outou faalogo i taua i laueleele ese; ae, faauta, Ou te fai atu ia te outou, ua lata mai i latou, ua i o outou faitotoa lava, ma e lē tele ni tausaga mai le taimi nei ae o le a outou faalogo i taua i o outou lava laueleele."},{"verse":64,"text":"O le mea lea o A’u, o le Alii, na Ou fai atu ai, ia outou faapotopoto i fafo mai itu- laueleele i sasae, ia outou faapotopoto faatasi outou lava o toeaina o la’u ekalesia; ia outou o atu i itu-laueleele i sisifo, valaau atu i e o nonofo ai ia salamo, ma e tusa ai ma lo latou salamo, ia atia’e ai i luga aulotu ia te a’u."},{"verse":65,"text":"Ma ia faaputuputu faatasi a outou oa ma le loto e tasi ma le mafaufau e tasi, ina ia mafai ona outou faatauina se tofi o le a tuu atu ia te outou pe a mavae le taimi nei."},{"verse":66,"text":"Ma o le a ta’ua o le Ierusalema Fou, o se laueleele o le filemu, o se aai o le sulufaiga, o se nofoaga o le saogalemu mo le au paia a le Atua Silisili Ese;"},{"verse":67,"text":"Ma o le a i ai iina le mamalu o le Alii, ma o le i ai iina le mata’u o le Alii, e oo ina lē o mai i ai o e amioleaga, ma o le a ta’ua o Siona."},{"verse":68,"text":"Ma o le a oo mai i e e amioleaga, o tagata taitoatasi e lē siia’e lana pelu e faasaga i lē la te tuaoi, e ao ina sola i Siona mo le saogalemu."},{"verse":69,"text":"Ma o iina o le a faapotopoto i ai tagata mai fafo o atunuu uma i lalo o le lagi; ma o le a nao le pau ia o tagata o le a lē tau le tasi ma le isi."},{"verse":70,"text":"Ma o le a faapea ane i totonu o e e amioleaga: Aua tatou te o a’e i luga e tau faasaga ia Siona, ona ua matua matautia lava tagata o Siona; o le mea lea e lē mafai ai ona tatou tutu."},{"verse":71,"text":"Ma o le a oo mai o le a faapotopoto mai e e amiotonu mai atunuu uma, ma o le a o mai i Siona, ma pepese i pese o le olioli e tumau e faavavau."},{"verse":72,"text":"Ma o lenei Ou te fai atu ia te outou, ia taofi nei mea mai le oo atu i le lautele o le lalolagi seia oo ina tatau ai ia te a’u, ina ia mafai ona outou faataunuuina lenei galuega i luma o mata o tagata, ma i luma o mata o o outou fili, ina ia latou lē iloa a outou galuega seia outou faataunuuina le mea ua Ou poloaiina ai outou;"},{"verse":73,"text":"Ona a oo ina latou iloaina, ia mafai ona latou manatunatu i nei mea."},{"verse":74,"text":"Ona a afio mai le Alii o le a matautia tele o ia ia te i latou, ina ia maua i latou i le mata’u, ma o le a latou tutulai mamao ese ma gatete."},{"verse":75,"text":"Ma o le a matata’u atunuu uma ona o le matautia o le Alii, ma le mana o lona malosi. E faapea lava. Amene."}]},{"chapter":46,"verses":[{"verse":1,"text":"Faalogo mai ia, outou e tagata o la’u ekalesia; aua e moni Ou te fai atu ia te outou, sa tautala atu ia te outou i nei mea mo lo outou lelei ma aoaoga."},{"verse":2,"text":"Ae e ui i na mea ua tusia, sa tuu atu pea i taimi uma i toeaina o la’u ekalesia mai le amataga, ma o le a faapea lava e faavavau, e taitai sauniga uma e pei ona faatonuina ma taialaina ai i latou e le Agaga Paia."},{"verse":3,"text":"A ui i lea ua poloaiina outou ia aua lava ne’i tulia ese soo se tasi mai ia outou sauniga faitele, e faia i luma o le lalolagi."},{"verse":4,"text":"Ua poloaiina foi outou ia lē tulia ese i fafo soo se tasi e auai i le ekalesia mai ia outou sauniga faamanatuga; ae ui i lea, afai ua agasala se tasi, ’aua ne’i taumafa o ia seia faia e ia se faaleleiga."},{"verse":5,"text":"Ma Ou te toe fai atu ia te outou, aua tou te tuli ese i fafo o a outou sauniga faamanatuga soo se tasi o e o loo saili ma le faamaoni le malo—ua Ou tautala atu lenei mea e faatatau ia i latou o e ua lē o le ekalesia."},{"verse":6,"text":"Ma Ou te toe fai atu ia te outou, e faatatau ia outou sauniga o faamauga, afai e i ai ni isi e lē o le ekalesia, o loo saili ma le faamaoni i le malo, aua tou te tutulia i latou i fafo."},{"verse":7,"text":"Ae ua poloaiina outou i mea uma ia ole atu i le Atua, o lē na te foai tele mai; ma o mea e molimau atu ai le Agaga ia te outou ua faapea lava ona ou loto ia outou faia i le paia atoatoa o le loto, ma savavali sa’o i o’u luma, ma manatunatu i le iuga o lo outou olataga, ma faia mea uma faatasi ma le tatalo ma le faafetai, ina ia lē faaseseina outou e agaga leaga, po o mataupu faavae a tiapolo, po o poloaiga a tagata; aua o ni isi e ā tagata, ma o isi e ā tiapolo."},{"verse":8,"text":"O le mea lea, ia faaeteete ne’i faaseseina outou; ma ina ia lē faaseseina outou, ia outou saili ma le faamaoni meaalofa silisili, ma manatua pea le pogai ua tuuina mai ai;"},{"verse":9,"text":"Aua e moni ou te fai atu ia te outou, ua tuuina mai ia meaalofa mo le lelei o i latou o e e alolofa mai ia te a’u ma tausi i a’u poloaiga uma, ma o ia o lē ua saili na te faia faapea; ina ia aoga ia i latou uma o e e saili pe ole mai ia te a’u, o e e ole mai ae lē mo se faailoga ina ia mafai ona latou faaaogaina i lo latou tuinanau."},{"verse":10,"text":"O lenei foi, e moni ou te fai atu ia te outou, ou te manao ia outou manatua pea, ma taofi pea i o outou mafaufau po o a ia meaalofa, ua tuuina atu i le ekalesia."},{"verse":11,"text":"Aua ua lē tu’uina atu i tagata uma meaalofa uma; ona e tele meaalofa, ma e tuuina atu e le Agaga o le Atua i tagata taitoatasi se meaalofa."},{"verse":12,"text":"I ni isi ua tuuina mai i ai se tasi, ma i isi ua tuuina atu i ai se isi, ina ia mafai ona manuia ai o tagata uma."},{"verse":13,"text":"I ni isi ua tuuina mai i ai e le Agaga Paia ia latou iloa o Iesu Keriso o le Alo o le Atua, ma sa faasatauroina o ia mo agasala a le lalolagi."},{"verse":14,"text":"I ni isi ua tuuina mai i ai ia talitonu ia latou upu, ina ia mafai foi ona latou maua o le ola e faavavau pe afai latou te faamaoni pea."},{"verse":15,"text":"O lenei foi, ua tuuina mai i ni isi e le Agaga Paia ia latou iloa le eseesega o pulega, e pei ona finagalo malie i ai le Alii lava e tasi, e tusa ai ma le finagalo o le Alii, i le faatatau o ona alofa mutimutivale e tusa ma tulaga o le fanauga a tagata."},{"verse":16,"text":"O lenei foi, ua tuuina mai e le Agaga Paia i ni isi ia latou iloa le eseesega o faiga, pe mai le Atua, ina ia mafai ona tuuina mai o faaaliga a le Agaga i tagata taitoatasi ina ia manuia ai."},{"verse":17,"text":"O lenei foi, e moni ou te fai atu ia te outou, ua tuuina mai e le Agaga o le Atua i ni isi, le upu o le poto."},{"verse":18,"text":"I se tasi ua tuuina mai i ai le upu o le malamalama, ina ia mafai ona a’oa’oina o tagata uma ia atamamai ma ia latou maua le malamalama."},{"verse":19,"text":"O lenei foi, ua tuuina mai i ni isi ia latou maua le faatuatua e faamaloloina ai;"},{"verse":20,"text":"Ma i isi ua tuuina mai i ai ia latou maua le faatuatua e faamalolo atu ai."},{"verse":21,"text":"O lenei foi, ua tuuina mai i ni isi le faia o vavega;"},{"verse":22,"text":"Ma i isi ua tuuina mai i ai e vavalo;"},{"verse":23,"text":"Ma i isi o le iloaina o agaga."},{"verse":24,"text":"O lenei foi, ua tuuina mai i ni isi e tautala i gagana;"},{"verse":25,"text":"Ma i le tasi ua tuuina mai i ai le faaliliuga o gagana."},{"verse":26,"text":"Ma o nei meaalofa uma ua mai i le Atua, mo le manuia o fanau a le Atua."},{"verse":27,"text":"Ma i le epikopo o le ekalesia, ma ia i latou faapena e tofia ma faauu e le Atua e leoleo i le ekalesia ma avea ma toeaina i le ekalesia, o le a tuuina atu ia te i latou ia latou iloa ia meaalofa uma ne’i i ai se tasi i totonu o outou e fai mai ua ia te ia ia mea ae ua lē ā le Atua."},{"verse":28,"text":"Ma o le a oo mai e faapea o lē e ole atu i le Agaga o le a maua e ia i le Agaga;"},{"verse":29,"text":"Ina ia mafai ona tuuina mai o ia meaalofa uma i ni isi, ina ia mafai ona i ai o se ulu, ina ia mafai ona manuia ai tagata uma."},{"verse":30,"text":"O ia o lē e ole atu i le Agaga, e ole atu o ia e tusa ai ma le finagalo o le Atua; o lea e faia ai e pei lava ona ole atu ai o ia."},{"verse":31,"text":"O lenei foi, ou te fai atu ia te outou, e ao ona faia o mea uma o soo se mea lava tou te faia i le Agaga, i le suafa o Keriso;"},{"verse":32,"text":"Ma e ao ina outou faafetai atu i le Atua i le Agaga mo soo se faamanuiaga ua faamanuiaina ai outou."},{"verse":33,"text":"Ma e ao ina outou faia e lē aunoa le amiomama ma le paia i o’u luma. Ia faapea lava. Amene."}]},{"chapter":47,"verses":[{"verse":1,"text":"Faauta, ua ao ia te a’u ona tusi ma tausia e la’u auauna o Ioane se talafaasolopito faia pea, ma fesoasoani ia te oe, la’u auauna, Iosefa, i le tusia o mea uma o le a tuu atu ia te oe, seia oo ina valaauina o ia i ni isi tiute."},{"verse":2,"text":"O lenei foi, e moni Ou te fai atu ia te oe, e mafai foi ona ia siitia a’e lona leo i sauniga-lotu, i soo se taimi e tatau ai."},{"verse":3,"text":"O lenei foi, Ou te fai atu ia te oe ia tofia o ia na te tausia e lē aunoa le talafaamaumau ma le talafaasolopito o le ekalesia; aua ua Ou tofia Oliva Kaotui i se isi tofi."},{"verse":4,"text":"O le mea lea, o le a tuu atu ai ia te ia, e tusa ai ma lona faamaoni, e le Fesoasoani, na te tusia nei mea. Ia faapea lava. Amene."}]},{"chapter":48,"verses":[{"verse":1,"text":"E Tatau ona outou nonofo pea i le taimi nei i o outou nofoaga ua outou nonofo ai, pe afai e talafeagai ai ma o outou tulaga."},{"verse":2,"text":"Ma e tusa ai ma lo outou maua o fanua, ia outou faasoa atu i o outou uso mai sasae;"},{"verse":3,"text":"Ma e tusa ai ma le leai o ni o outou fanua, ia tuu atu ia te i latou e faatau mai mo le taimi nei i ia nofoaga o loo faataamilo ai, e pei ona lelei ia te i latou, ona e ao ona tatau ona latou maua o ni nofoaga e nonofo ai mo le taimi nei."},{"verse":4,"text":"E tatau ona outou teu tupe uma e mafai ona outou teuina, ma ia outou maua tupe uma e mafai ona outou maua i le amiotonu, ina ia mafai ona outou faatauina i se taimi se laueleele mo se tofi, o le aai lava lea."},{"verse":5,"text":"E lei faaalia mai lava le nofoaga; ae a mavae ona o mai o outou uso mai sasae, e i ai ni tagata faapitoa o le a tofia, ma o i latou o le a tuu atu i ai ia latou iloa le nofoaga, po o i latou o le a faaali atu i ai."},{"verse":6,"text":"Ma o le a tofia i latou e faatau mai fanua, ma faia se amataga e faataatia ai le faavae o le aai; ona amata ai lea ona outou faapotopoto faatasi ma o outou aiga, o tagata taitoatasi e tusa ma lona aiga, e tusa ma ona tulaga, ma e pei ona tofia ia te ia e le au peresitene ma le epikopo o le ekalesia, e tusa ma tulafono ma poloaiga ua outou maua, ma ia o le a outou maua i se taimi o mulimuli mai. E faapea lava. Amene."}]},{"chapter":49,"verses":[{"verse":1,"text":"Faalogo mai ia i la’u upu, a’u auauna e, Sini, ma Parley, ma Limani; aua faauta, e moni Ou te fai atu ia te outou, Ou te tuu atu ia te outou se poloaiga ia outou o atu ma talai atu i le Au Sieka la’u talalelei ua outou mauaina, e pei lava ona outou mauaina."},{"verse":2,"text":"Faauta, Ou te fai atu ia te outou, ua latou mananao e fia iloa se vaega o le upu moni, ae lē o le atoa, ona e lē o sa’o i latou i o’u luma ma e ao ina salamo."},{"verse":3,"text":"O le mea lea, Ou te auina atu ai oulua, a’u auauna, o Sini ma Parley, e talai atu le talalelei ia te i latou."},{"verse":4,"text":"Ma ia faauu la’u auauna o Limani i lenei galuega, ina ia mafai ona talatala o ia faatasi ma i latou, e lē tusa ai ma mea na ia maua mai ia te i latou, ae e tusa ai ma mea e aoao atu ia te ia e oulua o a’u auauna; ma o le faia o lenei mea o le a Ou faamanuiaina ai o ia, a leai e lē manuia o ia."},{"verse":5,"text":"Ua faapea ona fetalai mai o le Alii; ona o A’u o le Atua, ma sa Ou auina atu lo’u Atalii Pele e Toatasi i le lalolagi mo le togiolaina o le lalolagi, ma ua Ou folafola atu, o ia o lē na te talia o ia o le a faaolaina, ma o ia o lē na te lē talia o ia o le a faamalaiaina—"},{"verse":6,"text":"Ma ua faapea ona latou faia i le Atalii o le Tagata e pei ona sa latou loto i ai; ma sa ave e ia lona mana i le lima taumatau o lona mamalu, ma ua nofotupu nei i le lagi, ma o le a nofotupu seia toe afio ifo i le lalolagi e tuu i lalo o ona vae fili uma, o se taimi lea ua lata lava ona oo mai—"},{"verse":7,"text":"O A’u, o le Alii le Atua, ua Ou tautala atu ai; ae o le itula ma le aso e leai se tagata na te iloaina, po o agelu i le lagi, pe latou te iloaina seia oo ina afio mai o ia."},{"verse":8,"text":"O le mea lea, ou te manao ai ia salamo tagata uma, ona ua i lalo o le agasala i latou uma, vagana ai i latou ua Ou faasaoina mo au lava, o ni tagata paia tou te lē iloa lava."},{"verse":9,"text":"O le mea lea, Ou te fai atu ai ia te outou ua Ou auina atu ia te outou la’u feagaiga tumau e faavavau, o le feagaiga lava lena ua mai i le amataga."},{"verse":10,"text":"Ma o le mea lena na Ou folafola atu ua faapea ona uma ona Ou faataunuuina, ma o le a ifo i ai atunuu o le lalolagi; ma, afai e lē faapea ona faia e i latou lava, o le a auina ifo i latou i lalo, ona o lē ua faaeaina nei ia te ia lava, o le a aveesea faamaualalo i le mana."},{"verse":11,"text":"O le mea lea, Ou te tuu atu ai ia te outou se poloaiga ia outou o atu i totonu o nei tagata, ma fai atu ia te i latou, e pei o la’u aposetolo anamua, o lē o lona igoa o Peteru:"},{"verse":12,"text":"Ia talitonu i le suafa o le Alii o Iesu, o lē sa i le lalolagi, ma o lē o le a afio mai, o le amataga ma le gataaga;"},{"verse":13,"text":"Ia salamo ma papatiso i le suafa o Iesu Keriso, e tusa ma le poloaiga paia, mo le faamagaloina o agasala;"},{"verse":14,"text":"Ma ai se na te faia lenei mea o le a maua e ia le meaalofa o le Agaga Paia, e ala i le faaeeina o lima o toeaina o le ekalesia."},{"verse":15,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ai se na te faasaina ona faaipoipo ua lē faauuina o ia e le Atua, ona o le faaipoipoga ua faauuina e le Atua mo le tagata."},{"verse":16,"text":"O le mea lea, ua tusa ai ma le tulafono le tatau ona maua e ia o se ava e toatasi, ma avea i laua e toalua ma tino e tasi, ma ua faia lenei mea atoa ina ia mafai ona faataunuu e le lalolagi le faamoemoe o lona foafoaga;"},{"verse":17,"text":"Ma ina ia mafai ona faatumuina i le fuataga o le tagata, e tusa ma lona foafoaga ae lei faia le lalolagi."},{"verse":18,"text":"Ma ai se na te faasaina le ’ai i aano o manu, ina ia lē ’ai ai le tagata, ua lē faauuina o ia e le Atua;"},{"verse":19,"text":"Aua, faauta, o manu vaefa o le fanua ma manu felelei o le vanimonimo, ma mea e sau mai i le eleele, ua faauuina mo le faaaogaina e le tagata mo meaai ma mo lavalava, ma ina ia maua tele e ia."},{"verse":20,"text":"Peitai ua lē tuuina mai ia maua e se tagata e toatasi ni mea e sili atu i le isi, o le mea lea ua taoto ai le lalolagi i le agasala."},{"verse":21,"text":"Ma oi talofa i le tagata na te faamasaa le toto pe na te faatauna aano o manu ae ua lē manaomia e ia."},{"verse":22,"text":"O lenei foi, e moni Ou te fai atu ia te outou, e lē afio mai le Atalii o le Tagata i le fuaitino o se fafine, po o se alii o femalagaa’i i le lalolagi."},{"verse":23,"text":"O le mea lea, aua nei faaseseina outou, ae ia tutu mausali pea, ma tulimatai i luma mo le luluina o le lagi, ma le faagateteina o le lalolagi ma tifatifa solo e pei o se tagata ’onā, ma mo le faaeaina o vanu, ma mo le faamaualalaloina o mauga, ma mo le faalauleleia o mea gaoā—ma o nei mea uma o le a oo mai pe a ili e le agelu lana pu."},{"verse":24,"text":"Peitai ae lei oo mai le aso tele o le Alii, o le a tupuolaola Iakopo i le vao, ma o le a fuga mai sa Lamanā e pei o le rosa."},{"verse":25,"text":"O le a tupuolaola Siona i luga o maupuepue ma olioli i luga o mauga, ma o le a faapotopoto faatasi i le nofoaga ua Ou filifilia."},{"verse":26,"text":"Faauta, Ou te fai atu ia te outou, o atu ia e pei ona Ou poloaiina ai outou; ia outou salamo mai iā outou agasala uma; ole mai ma o le a outou maua; tu’itu’i mai ma o le a tatala atu ia te outou."},{"verse":27,"text":"Faauta, o le a Ou alu atu i o outou luma ma avea foi ma o outou muli’au; ma o le a Ou i ai i lo outou lotolotoi, ma o le a lē faafememeaiina outou."},{"verse":28,"text":"Faauta, o A’u o Iesu Keriso, ma ua vave ona Ou alu atu. E faapea lava. Amene."}]},{"chapter":50,"verses":[{"verse":1,"text":"Faalogo mai ia, outou toeaina e o la’u ekalesia, ma ua’i mai o outou taliga i le siufofoga o le Atua soifua; ma auai atu i upu o le poto o le a tuuina atu ia te outou, e pei ona outou ole mai ai ma autasi i ai e faatatau i le ekalesia, ma agaga ua o atu i le salafa o le lalolagi."},{"verse":2,"text":"Faauta, e moni Ou te fai atu ia te outou, o le tele o agaga o i ai o ni agaga sese, ua o atu i le lalolagi, ua faaseseina le lalolagi."},{"verse":3,"text":"Ma ua saili foi Satani e faasese outou, ina ia mafai ona ia faatoilalo outou."},{"verse":4,"text":"Faauta, o A’u, o le Alii, ua Ou vaai ifo ia te outou, ma ua Ou iloa mea inosia i totonu o le ekalesia ua tauaveina lo’u igoa."},{"verse":5,"text":"Ae amuia lava i latou o e ua faamaoni ma tutumau, pe i le olaga nei po o i le oti, ona o le a maua e i latou le ola e faavavau."},{"verse":6,"text":"Ae oi talofa ia te i latou o e o ni taufaasese ma pepelo, aua, ua faapea ona fetalai mai o le Alii, o le a Ou aumai i latou i le faamasinoga."},{"verse":7,"text":"Faauta, e moni Ou te fai atu ia te outou, o loo i ai e e pepelo i totonu o outou, o e ua latou faaseseina ni isi, lea ua tuuina atu ai i le fili le mana; ae faauta o le a toe aumaia i latou;"},{"verse":8,"text":"Ae o e e pepelo o le a iloa i latou ma o le a vavae ese, pe i le olaga nei po o i le oti, e pei lava ona Ou loto i ai; ma oi talofa ia te i latou o e e vavae ese mai la’u ekalesia, ona o i latou lava ia ua manumalo i ai le lalolagi."},{"verse":9,"text":"O le mea lea, ia faaeteete ai tagata taitoatasi nei faia e ia se mea ua lē moni ma lē amiotonu i o’u luma."},{"verse":10,"text":"Ma o lenei o mai ia, ua fetalai mai ai le Alii, e ala i le Agaga, i toeaina o lana ekalesia, ma sei tatou talatala faatasi, ina ia outou malamalama;"},{"verse":11,"text":"Sei tatou talatala e pei lava ona talatala se tagata o le tasi ma le isi faafesagai."},{"verse":12,"text":"O lenei, a talatala se tagata e malamalama le tagata ia te ia, ona e talatala o ia e pei o se tagata; o le a faapea foi ia te A’u, o le Alii, ona talatala faatasi ma outou, ina ia outou malamalama."},{"verse":13,"text":"O le mea lea, o A’u o le Alii e fesili atu le fesili lenei ia te outou—o le a ea le mea na faauu i ai outou?"},{"verse":14,"text":"E talai atu la’u talalelei e ala i le Agaga, le Fesoasoani lea na auina atu e aoao atu le upumoni."},{"verse":15,"text":"Ma ona outou talia ai lea o agaga ua lē mafai ona outou malamalama i ai, ma talia i latou e faapea ua mai i le Atua; ma pe ta’umamaina ea outou i lenei mea?"},{"verse":16,"text":"Faauta ia outou tali lenei fesili e outou lava; ae ui i lea, o le a Ou alofa mutimutivale atu ia te outou; o ia o lē ua i totonu o outou e vaivai, o le a faamalosia mulimuli ane."},{"verse":17,"text":"E moni Ou te fai atu ia te outou, o ia o lē ua Ou faauuina ma auina atu e talai ana afioga o le upumoni e ala i le Fesoasoani, i le Agaga o le upumoni, e talai atu ea e ia i le Agaga o le upumoni po o se isi ala?"},{"verse":18,"text":"Ma afai e talai atu i se isi ala ua lē mai i le Atua lea."},{"verse":19,"text":"O lenei foi, o ia o lē e talia le afioga o le upumoni, e talia ea e ia e ala i le Agaga o le upumoni po o se isi ala?"},{"verse":20,"text":"Afai e talia i se isi ala ua lē mai i le Atua lea."},{"verse":21,"text":"O lea, aisea ua lē mafai ai ona outou malamalama ma iloa, o ia o lē e mauaina le afioga e ala i le Agaga o le upumoni e maua e ia e pei ona talai atu i le Agaga o le upumoni?"},{"verse":22,"text":"O le mea lea, o ia o lē e talai atu atoa ma ia o lē e mauaina, e malamalama le tasi i le isi, ma e faagaeetiaina ma olioli faatasi i laua uma."},{"verse":23,"text":"Ma o le mea ua lē faagaeetia ua lē mai i le Atua, ma o le pouliuli lea."},{"verse":24,"text":"O le mea e mai i le Atua o le malamalama lea; ma o ia o lē e mauaina le malamalama, ma tumau pea i le Atua, e mauaina le malamalama atili; ma o lena malamalama o le a susulu tele pea lava pea seia oo i le aso e atoatoa ai."},{"verse":25,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ma Ou te fai atu ai ina ia mafai ona outou iloa le upumoni, ina ia mafai ona outou tuli ese o le pouliuli mai i totonu o outou;"},{"verse":26,"text":"O ia o lē ua faauuina e le Atua ma auina atu, o ia lava lea ua tofia ia avea ma lē ua sili, e ui ina o ia e aupito faatauvaa ma o le auauna a tagata uma."},{"verse":27,"text":"O le mea lea, ua maua e ia mea uma; ona ua pule o ia i mea uma, o mea uma i le lagi ma i luga o le lalolagi, o le ola ma le malamalama, o le Agaga ma le mana, na auina mai i le finagalo o le Tamā, e ala mai ia Iesu Keriso, lona Alo."},{"verse":28,"text":"Ae e leai se tagata na te mauaina mea uma vagana ua ta’umamaina ma faamamaina o ia mai agasala uma."},{"verse":29,"text":"Ma afai ua ta’umamaina ma faamamaina outou mai agasala uma, soo se mea tou te ole atu ai i le suafa o Iesu o le a faia lava."},{"verse":30,"text":"Ae ia outou iloa le mea lenei, o le a tuu atu ia te outou mea tou te ole mai ai; ma talu ai ona ua tofia outou i le ulu, o le a i ai agaga i lalo o la outou pule."},{"verse":31,"text":"O le mea lea, o le a oo mai foi afai tou te vaaia se agaga e faaali mai tou te lē malamalama i ai, ma ua outou lē mauaina lena agaga, ia outou ole atu i le Tamā i le suafa o Iesu; ma afai e lē tuuina mai e ia ia te outou lena agaga, ona outou iloa lea ua lē mai i le Atua."},{"verse":32,"text":"Ma o le a tuu atu ia te outou, le mana i luga o lena agaga; ma ia outou alaga atu ma se leo tele faasaga atu i lena agaga ua lē mai i le Atua—"},{"verse":33,"text":"E lē i se tuuaiga ’ina’inā, ina ia lē lofituina outou, pe ma le mitavale po o le sagisagi, nei maua ai outou."},{"verse":34,"text":"O ia o lē na te maua se mea mai i le Atua, ia tau e ia ua mai i le Atua; ma ia tuu atu ia te ia e olioli ua tau agavaa o ia e le Atua na te maua lena mea."},{"verse":35,"text":"Ma o le gauai atu ma le faia o ia mea ua outou maua, ma mea o le a outou maua mulimuli ane—ma ua tuu atu ia te outou e le Tamā le malo, ma le mana e manumalo ai i mea uma e lei faauuina e ia—"},{"verse":36,"text":"Ma faauta, e moni Ou te fai atu ia te outou, amuia lava outou o e o loo faalogo mai i a’u upu nei mai le fofoga o la’u auauna, ona ua faamagaloina a outou agasala mai ia te outou."},{"verse":37,"text":"Tuu atu i la’u auauna o Iosefa Wakefield, o lē ua Ou fiafia lava i ai, ma la’u auauna o Parley P. Pratt, e o atu i totonu o aulotu ma faamalolosi i latou e ala i le upu apoapoai;"},{"verse":38,"text":"Ma ia tuu atu foi i la’u auauna o Ioane Corrill, po o le toatele o i latou o a’u auauna ua faauuina i lenei tofi, e galulue i le tovine; ma ia lē tuua se tagata e faalavelave ia te i latou mai le faia o le mea ua Ou tofia i ai i latou—"},{"verse":39,"text":"O le mea lea, ua lē ta’uamiotonuina la’u auauna o Eteuati Paterika i lenei mea; ae ui i lea ia tuu atu ia te ia ia salamo ma o le a faamagaloina ai o ia."},{"verse":40,"text":"Faauta, o outou o ni fanau laiti, ma e lē mafai ona outou gafatia mea uma i le taimi nei; e ao ina outou tutupu a’e i le malosi faaleagaga ma i le malamalama o le upumoni."},{"verse":41,"text":"Aua le matatau, le fanau laiti e, ona o outou o a a’u outou, ma ua Ou manumalo i le lalolagi, ma o outou o ni o i latou ua tuuina mai e lo’u Tamā ia te a’u;"},{"verse":42,"text":"Ma e leai so i latou o e ua tuuina mai e lo’u Tamā ia te a’u o le a leiloa."},{"verse":43,"text":"Ma o le Tamā ma A’u ua tasi. Ua i ai A’u i le Tamā ma ua i ai le Tamā ia te A’u; ma talu ai ona ua outou talia a’u, ua outou i ai ia te a’u ma ua Ou i ai ia te outou."},{"verse":44,"text":"O le mea lea, ua Ou i ai i lo outou lotolotoi, ma o A’u o le leoleo mamoe lelei, ma le maa faavae o Isaraelu. O ia o lē e ati a’e i luga o lenei papa o le a lē pa’ū lava."},{"verse":45,"text":"Ma e oo mai le aso o le a outou faalogo ai i lo’u leo ma vaai mai ai ia te a’u, ma iloa o au lava lea."},{"verse":46,"text":"O le mea lea, ia mataala ai, ina ia outou saunia. Ua faapea lava. Amene."}]},{"chapter":51,"verses":[{"verse":1,"text":"Faalogo mai ia ia te a’u, ua fetalai mai ai le Alii lo outou Atua, ma o le a Ou tautala atu i la’u auauna o Eteuati Paterika, ma tuu atu ia te ia ni faatonuga; aua e tatau ona maua e ia faatonuga e faatatau i le ala e faatulaga ai lenei nuu."},{"verse":2,"text":"Aua e tatau ona faatulagaina i latou e tusa ai ma a’u tulafono; afai e ese ai, o le a vavaeeseina i latou."},{"verse":3,"text":"O le mea lea, ia tuu atu i la’u auauna o Eteuati Paterika, ma i latou o e ua ia filifilia, o e ua Ou fiafia lava i ai, latou te tofi atu i lenei nuu a latou vaega, ia tutusa uma tagata taitoatasi e tusa ai ma lona aiga, e tusa ai ma ona tulaga ma ona manaoga ma mea ua tatau ai mo ia."},{"verse":4,"text":"Ma ia tuu atu i la’u auauna o Eteuati Paterika, o le a ia tuu atu i se tagata lana vaega, ia tuu atu ia te ia se pepa tusia e faamau ai ia te ia lana vaega, ia umia e ia, lea lava aiā ma lea lava tofi i le ekalesia, seia vagana ai ua solitulafono o ia ma lē faitau agavaaina e le leo o le ekalesia, e tusa ai ma tulafono ma feagaiga o le ekalesia, e auai i le ekalesia."},{"verse":5,"text":"Ma afai e solitulafono o ia ma ua lē faitau agavaa e auai i le ekalesia, o le a lē maua e ia le aiā e maua ai le vaega lena na ia faapa’ia atu i le epikopo mo e ua matitiva ma e ua lē tagolima o la’u ekalesia; o lea, o le a lē mafai e ia ona taofia le meaalofa, ae o le a nao le vaega lena na faamau atu ia te ia e aiā i ai."},{"verse":6,"text":"Ma ia faapea ona faia o mea uma ma le mautinoa, e tusa ai ma tulafono o le laueleele."},{"verse":7,"text":"Ma ia tuu mea e a lenei nuu e tofi atu i lenei nuu."},{"verse":8,"text":"Ma o le tupe e totoe mai i lenei nuu—ia tofia se sui i lenei nuu, na te ave le tupe e maua mai ai ni meaai ma lavalava, e tusa ma manaoga o lenei nuu."},{"verse":9,"text":"Ma ia tuu atu i tagata uma taitoatasi ia faamaoni i mea e fai, ma ia tutusa i totonu o lenei nuu, ma maua tutusa, ina ia tasi outou, e pei lava ona ou poloaiina ai outou."},{"verse":10,"text":"Ma ia tuu mea e a lenei nuu ia lē avea ma tuuina atu i se tasi aulotu."},{"verse":11,"text":"O le mea lea, afai e fia maua e se tasi aulotu se tupe mai i le aulotu lenei, ia tuu atu ia te i latou ia toe totogi mai i le aulotu lenei e pei ona latou malilie i ai."},{"verse":12,"text":"Ma ia faia lenei mea e ala atu i le epikopo po o le sui, lea ia tofia e ala i le leo o le aulotu."},{"verse":13,"text":"O lenei foi, ia tuu atu i le epikopo e faatuina se faleteuoloa mo lenei aulotu; ma ia tuu atu mea uma e aofia ai tupe ma meaai, ua tele atu nai lo mea ua manaomia mo manaoga o lenei nuu, ia tausia e lima o le epikopo."},{"verse":14,"text":"Ma ia tuu atu foi ia te ia e faasao mo ia lava ni mea mo ona lava manaoga, ma mo manaoga o lona aiga, ona o le a faigaluega o ia i le taulimaina o lenei mataupu."},{"verse":15,"text":"Ma ua faapea ona ou tuu atu i lenei nuu se avanoa e faatulaga ai i latou lava e tusa ai ma a’u tulafono."},{"verse":16,"text":"Ma ua ou faapaiaina mo i latou lenei laueleele mo se vaitau itiiti, seia oo ina faia e A’u, o le Alii, se isi mea mo i latou, ma poloaiina i latou e o atu i ai;"},{"verse":17,"text":"Ma o le itula ma le aso e lei tuuina atu ia te i latou, o le mea lea ia tuu atu ai ia te i latou ia galulue i luga o lenei laueleele e peiseai ua mo ni tausaga e tele, ma o le a liliu mai lenei mea ia te i latou mo lo latou lelei."},{"verse":18,"text":"Faauta, ia avea lenei mea ma se faataitaiga i la’u auauna o Eteuati Paterika, i isi nofoaga, i aulotu uma."},{"verse":19,"text":"Ma ai se e maua o ia o se tausimea faamaoni, fai mea tonu, ma atamai, o le a ulufale atu i le olioli o lona Alii, ma o le a maua e ia le ola e faavavau."},{"verse":20,"text":"E moni, Ou te fai atu ia te outou, o A’u o Iesu Keriso, o lē ua vave ona sau, i se itula tou te lē mafaufauina. E faapea lava. Amene."}]},{"chapter":52,"verses":[{"verse":1,"text":"Faauta, ua faapea ona fetalai mai o le Alii i toeaina o e ua ia valaaulia ma filifilia i aso nei e gata ai, i le siufofoga o lona Agaga—"},{"verse":2,"text":"Ua fetalai mai: O A’u, o le Alii, o le a faailoa atu ia te outou mea ua Ou loto ia outou faia mai le taimi nei seia oo atu i le konafesi e sosoo ai, lea o le a faia i Misuri, i luga o le laueleele o le a Ou faapaiaina mo lo’u nuu, o e o se vaega o totoe o Iakopo, ma i latou o e o suli e tusa ma le feagaiga."},{"verse":3,"text":"O le mea lea, e moni Ou te fai atu ia te outou, ia tuu atu i a’u auauna o Iosefa Samita, Le Itiiti, ma Sini Rikitone, e alu la laua malaga i le taimi lava e mafai ona faia ai o ni sauniuniga e tuua ai o laua aiga, ma malaga atu i le laueleele o Misuri."},{"verse":4,"text":"Ma e tusa ai ma lo la faamaoni ia te a’u, o le a faailoa atu ia te i laua mea la te faia;"},{"verse":5,"text":"Ma o le a faailoa atu foi, ia te i laua, e tusa ai ma lo la faamaoni, o le laueleele o lo laua tofi."},{"verse":6,"text":"Ma e tusa ai ma lo laua lē faamaoni, o le a vavae ese i laua, e pei lava ona Ou loto i ai, e pei ona lelei ia te a’u."},{"verse":7,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ia tuu atu i la’u auauna o Laimani Uaite ma la’u auauna o Ioane Corrill, ia alu vave la laua malaga;"},{"verse":8,"text":"Ma o la’u auauna foi o Ioane Murdock, ma la’u auauna o Ailama Samita, ia alu la laua malaga i le nofoaga lava lena e tasi e ui atu i Detroit."},{"verse":9,"text":"Ma ia tuu i laua e malaga mai iina ma talai atu le afioga i le ala, ia lē fai atu ni isi lava mea nai lo mea ua tusia e perofeta ma aposetolo, ma mea e aoao atu ia te i laua e le Fesoasoani e ala i le tatalo o le faatuatua."},{"verse":10,"text":"Ia tuu atu ia te i latou e o taitoalua, ma ia faapea ona tuu atu ia te i latou e talai atu i le ala i faapotopotoga uma, ma papatiso atu i le vai, ma le faaee atu o lima i tafatafa o le vai."},{"verse":11,"text":"Ona ua faapea ona fetalai mai o le Alii, o le a Ou faapuupuuina la’u galuega i le amiotonu, ona e oo mai aso o le a Ou auina atu ai le faamasinoga mo le manumalo."},{"verse":12,"text":"Ma tuu atu i la’u auauna o Laimani Uaite ia faaeteete, ona e manao Satani e lūlū o ia e pei o le aputi."},{"verse":13,"text":"Ma faauta, o ia o lē e faamaoni o le a faia o ia ma pule i mea e tele."},{"verse":14,"text":"O lenei foi, o le a Ou tuu atu ia te outou se ata i mea uma, ina ia lē faaseseina outou; ona ua i ai Satani i le salafa o le laueleele, ma ua fealuai o ia e faasese i atunuu—"},{"verse":15,"text":"O le mea lea, o ia o lē e tatalo, o lē ua salamo lona agaga, o ia lava lea Ou te talia pe afai e usiusitai o ia i a’u sauniga."},{"verse":16,"text":"O ia o lē e tautala atu, o lē ua salamo lona agaga, o lē o lana gagana e agamalu ma faagaeetia, o ia lava lea ua mai le Atua pe afai e usiusitai o ia i a’u sauniga."},{"verse":17,"text":"O lenei foi, o ia o lē e gatete i lalo o lo’u mana o le a faamalosia, o le a ia aumai fua o le viiga ma le poto, e tusa ma faaaliga ma upumoni ua Ou tuu atu ia te outou."},{"verse":18,"text":"O lenei foi, o ia o lē ua toilalo ma ua lē aumaia ni fua, e tusa lava ma lenei mamanu, ua lē a a’u o ia."},{"verse":19,"text":"O le mea lea, o le faatusa lenei tou te iloa ai agaga i tulaga uma i lalo o le lagi atoa."},{"verse":20,"text":"Ma ua oo mai aso; e tusa ai ma le faatuatua o tagata o le a faapea lava ona faia ia te i latou."},{"verse":21,"text":"Faauta, ua tuu atu lenei poloaiga i toeaina uma o e ua Ou filifilia."},{"verse":22,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ia tuu atu i la’u auauna o Thomas B. Marsh ma la’u auauna o Ezra Thayre, e alu foi la laua malaga, ma talai atu le upu i le ala i lea lava laueleele."},{"verse":23,"text":"O lenei foi, ia tuu atu i la’u auauna o Isaako Morley ma la’u auauna o Ezra Booth e alu la laua malaga, ma talai atu foi le afioga i le ala i lea lava laueleele."},{"verse":24,"text":"O lenei foi, ia tuu atu i a’u auauna o Eteuati Paterika ma Matini Harisi e alu la laua malaga faatasi ma a’u auauna o Sini Rikitone ma Iosefa Samita, Le Itiiti."},{"verse":25,"text":"Ia tuu atu i a’u auauna o Tavita Uitimera ma Harvey Whitlock e alu foi la laua malaga, ma talai atu i le ala i lea lava laueleele."},{"verse":26,"text":"Ma ia tuu atu i a’u auauna o Parley P. Pratt ma Orson Pratt e alu la laua malaga, ma talai atu i le ala, i lea lava laueleele."},{"verse":27,"text":"Ma ia tuu atu foi i a’u auauna o Solomona Hancock ma Simeona Kata e alu la laua malaga i lea lava laueleele, ma talai atu i le ala."},{"verse":28,"text":"Tuu atu foi i a’u auauna o Edson Fuller ma Jacob Scott e alu la laua malaga."},{"verse":29,"text":"Tuu atu foi i a’u auauna o Levi W. Hancock ma Zebedee Coltrin e alu la laua malaga."},{"verse":30,"text":"Tuu atu foi i a’u auauna o Reynolds Cahoon ma Samuelu H. Samita e alu la laua malaga."},{"verse":31,"text":"Tuu atu foi i a’u auauna o Wheeler Baldwin ma Viliamu Kata e alu la laua malaga."},{"verse":32,"text":"Ma tuu atu i a’u auauna o Newel Knight ma Selah J. Griffin ia faauuina i laua uma, ma alu foi la laua malaga."},{"verse":33,"text":"Ioe, e moni Ou te fai atu, ia tuu atu ia te i latou uma nei e o a latou malaga i le nofoaga e tasi, i o latou ala eseese, ma ia lē ati a’e le tasi tagata i luga o le faavae o le isi, pe malaga i le ala o le isi."},{"verse":34,"text":"O ia o lē e faamaoni, o ia lea o le a tausia ma faamanuiaina i fua e tele."},{"verse":35,"text":"O lenei foi, Ou te fai atu ia te outou, ia tuu atu i a’u auauna o Iosefa Wakefield ma Solomona Humphrey e alu la laua malaga i laueleele i sasae;"},{"verse":36,"text":"Ia tuu atu ia te i laua e galulue i o laua aiga, ia lē talai atu ni isi lava mea nai lo o perofeta ma aposetolo, o mea ua la vaaia ma faalogoina ma talitonu moni i ai, ina ia faataunuuina valoaga."},{"verse":37,"text":"Ona o le solitulafono, ia tuu le mea na faaee i luga o Heman Basset ia aveesea mai ia te ia, ma tuuina i luga o le ulu o Simonds Ryder."},{"verse":38,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ia faauuina Iareto Kata o se ositaulaga, ma ia faauuina foi Siaosi James o se ositaulaga."},{"verse":39,"text":"Ia tuu atu i le vaega o totoe o toeaina e leoleo i aulotu, ma talai atu ana afioga i nofoaga o faataamilo ia te i latou; ma ia tuu atu ia te i latou e galulue i o latou lava lima ina ia lē i ai se ifo i tupua po o se amioleaga e faia."},{"verse":40,"text":"Ma ia manatua i mea uma e ua matitiva ma e ua lē tagolima, e ua mama’i ma e ua puapuagatia, ona o ia o lē na te lē faia ia mea, o ia lava lea e lē o so’u soo."},{"verse":41,"text":"O lenei foi, ia tuu atu i a’u auauna o Iosefa Samita, Le Itiiti, ma Sini Rikitone ma Eteuati Paterika, ia latou ave faatasi ma i latou se tusi faamaonia mai le ekalesia. Ma ia i ai foi se tusi faamaonia e maua mo la’u auauna o Oliva Kaotui."},{"verse":42,"text":"Ma e faapea, e pei lava ona Ou fai atu ai, afai tou te faamaoni o le a outou faapotopoto faatasi outou lava e olioli i luga o le laueleele o Misuri, le laueleele lea o lo outou tofi, lea o loo avea nei ma laueleele o outou fili."},{"verse":43,"text":"Ae, faauta, o A’u, o le Alii, o le a faanatinatia le aai i lona taimi, ma o le a faapaleina ē e faamaoni i le olioli ma le fiafia."},{"verse":44,"text":"Faauta, o A’u o Iesu Keriso, le Atalii o le Atua, ma o le a Ou siitia a’e i latou i luga i le aso gataaga. E faapea lava. Amene."}]},{"chapter":53,"verses":[{"verse":1,"text":"Faauta, Ou te fai atu ia te oe, la’u auauna, o Sini Gilbert, ua Ou faalogoina au tatalo; ma sa e valaau mai ia te a’u ia faailoa atu ia te oe, e le Alii lou Atua, e uiga i lou valaauga ma lou filifiliga i le ekalesia, lea ua faatuina i luga e A’u, o le Alii, i aso nei e gata ai."},{"verse":2,"text":"Faauta, o A’u, o le Alii, o lē na faasatauroina mo agasala a le lalolagi, Ou te tuu atu ia te oe se poloaiga ia e lafoai i le lalolagi."},{"verse":3,"text":"Ia e ave i ou luga la’u faauuga, o le toeaina lea, e talai atu le faatuatua ma le salamo ma le faamagaloina o agasala, e tusa ma la’u upu, ma le mauaina o le Agaga Paia e ala i le faaee atu o lima;"},{"verse":4,"text":"Ma avea foi o se sui mo lenei ekalesia i le nofoaga lea o le a tofia e le epikopo, e tusa ma poloaiga o le a tuuina atu pe a mavae nei."},{"verse":5,"text":"O lenei foi, e moni Ou te fai atu ia te oe, ia alu lau malaga faatasi ma a’u auauna o Iosefa Samita, Le Itiiti, ma Sini Rikitone."},{"verse":6,"text":"Faauta, o sauniga muamua nei o le a e maua; ma o le toega o le a faailoa atu i se taimi o le a oo mai, e tusa ma lau galuega i lo’u tovine."},{"verse":7,"text":"O lenei foi, Ou te manao ia e iloa, e na’o ia o lē e tumau e oo i le iuga e faaolaina. E faapea lava. Amene."}]},{"chapter":54,"verses":[{"verse":1,"text":"Faauta, ua faapea ona fetalai mai o le Alii, o le Alefa ma le Omeka lava lea, o le amataga ma le gataaga, o ia lava lea o lē na faasatauroina mo agasala a le lalolagi—"},{"verse":2,"text":"Faauta, e moni, e moni, Ou te fai atu ia te oe, la’u auauna, o Newel Knight, ia e tulai mausalī i le tofi ua Ou tofia i ai oe."},{"verse":3,"text":"Ma afai e mananao ou uso ia sao mai o latou fili, ia tuu atu ia te i latou ia salamo mai ia latou agasala uma, ma lotomaualalo moni i o’u luma ma agasalamo."},{"verse":4,"text":"Ma ona ua solia le feagaiga sa latou faia mai ia te a’u, ua faapea lava ona fai ma mea noa ma ua lē aoga."},{"verse":5,"text":"Ma oi talofa ia te ia o lē na oo mai ai lenei soligafeagaiga, ona sa sili ai ona lelei mo ia pe a na lelemo o ia i le loloto o le sami."},{"verse":6,"text":"Ae amuia lava i latou o e na tausia le feagaiga ma usiusitai i le poloaiga, ona o le a latou maua le alofa mutimutivale."},{"verse":7,"text":"O le mea lea, ia o atu nei ma sosola ese mai le laueleele, ne’i o mai o outou fili i o outou luga; ma alu la outou malaga, ma tofi se tasi tou te loto i ai e avea ma o outou taitai, ma totogi tupe mo outou."},{"verse":8,"text":"Ma ia faapea ona alu o la outou malaga i itulagi i sisifo, i le laueleele o Misuri, i tuaoi o sa Lamanā."},{"verse":9,"text":"Ma a taunuu la outou malaga, faauta, Ou te fai atu ia te outou, ia outou saili se mea tou te ola ai e pei o isi tagata, seia Ou saunia se nofoaga mo outou."},{"verse":10,"text":"O lenei foi, ia outou onosai i puapuaga seia Ou alu atu, ma, faauta, Ou te vave alu atu, ma ua i ai ia te a’u lo’u taui, ma o i latou o e na vave saili mai ia te a’u o le a latou maua le malologa i o latou agaga. E faapea lava. Amene."}]},{"chapter":55,"verses":[{"verse":1,"text":"Faauta, ua faapea ona fetalai mai o le Alii, le Alii lava lea o le lalolagi atoa, ia te oe, la’u auauna, o Viliamu, ua valaaulia ma filifilia oe; ma a uma ona papatisoina o oe i le vai, o se mea afai e te faia ma le manatu tasi i lo’u mamalu, o le a e maua se faamagaloga o au agasala ma le mauaina o le Agaga Paia e ala i le faaee atu o lima."},{"verse":2,"text":"Ma ona faauu ai lea o oe i le lima o la’u auauna o Iosefa Samita, Le Itiiti, e avea o se toeaina i lenei ekalesia, e talai atu le salamo ma le faamagaloina o agasala e ala i le papatisoga i le suafa o Iesu Keriso, le Alo o le Atua soifua."},{"verse":3,"text":"Ma o soo se tasi e te faaee atu i ai ou lima, afai ua agasalamo i latou i o’u luma, o le a ia te oe le mana e tuu atu ai le Agaga Paia."},{"verse":4,"text":"O lenei foi, o le a faauuina oe e te fesoasoani i la’u auauna o Oliva Kaotui e fai le galuega o le lomitusi, ma le filifiliga ma le tusia o tusi mo a’oga i lenei ekalesia, ina ia mafai ona maua foi e fanau laiti aoaoga i o’u luma e pei ona ou fiafia i ai."},{"verse":5,"text":"O lenei foi, e moni Ou te fai atu ia te oe, o le pogai lenei ia alu ai lau malaga faatasi ma a’u auauna o Iosefa Samita, Le Itiiti, ma Sini Rikitone, ina ia faamautuina oe i le laueleele o lou tofi e fai lenei galuega."},{"verse":6,"text":"O lenei foi, tuu atu foi i la’u auauna o Iosefa Kou e alu lana malaga faatasi ma i latou. O e o totoe o le a faailoa atu i se taimi o mulimuli mai, e pei lava ona Ou loto i ai. Amene."}]},{"chapter":56,"verses":[{"verse":1,"text":"Faalogo mai ia, outou e tagata o e ua ta’ua lo’u igoa, ua fetalai mai ai le Alii lo outou Atua; aua faauta, ua mumū a’e lo’u ita e faasaga i e e fouvale, ma o le a latou iloa lo’u lima ma lo’u ita, i le aso o le oo atu ma le sauā i luga o atunuu."},{"verse":2,"text":"Ma o ia o lē na te lē ave i luga lana satauro ma mulimuli mai ia te a’u, ma tausi i a’u poloaiga, o ia lava lea o le a lē faaolaina."},{"verse":3,"text":"Faauta, o A’u, o le Alii, e poloai atu; ma o ia o lē e lē usiusitai o le a vavae ese i lo’u lava taimi e tatau ai, pe a uma ona Ou poloai atu ae ua soli le poloaiga."},{"verse":4,"text":"O le mea lea, o A’u, o le Alii, e poloaia ma aveesea, e pei ona lelei ia te a’u; ma o nei mea uma o le a pa’ū i luga o ulu o e e fouvale, ua fetalai mai ai le Alii."},{"verse":5,"text":"O le mea lea, Ou te aveesea ai le poloaiga na tuu atu i a’u auauna o Thomas B. Marsh ma Ezra Thayre, ma tuu atu se poloaiga fou i la’u auauna o Thomas, ia alu vave atu lana malaga i le laueleele o Misuri, ma ia alu atu foi la’u auauna o Selah J. Griffin faatasi ma ia."},{"verse":6,"text":"Aua faauta, ua Ou aveesea le poloaiga na tuu atu i a’u auauna o Selah J. Griffin ma Newel Knight, ona o le ua maaa o lo’u nuu o loo i Tomasone, ma a latou fouvalega."},{"verse":7,"text":"O le mea lea, ia tuu atu i la’u auauna o Newel Knight e nofo pea faatasi ma i latou; ma o le toatele o i latou o e ua agasalamo i o’u luma e fia o, e mafai ona o, ma taitai atu e ia i le laueleele ua Ou tofia."},{"verse":8,"text":"O lenei foi, e moni Ou te fai atu ia te outou, e ao i la’u auauna o Ezra Thayre ona salamo i lona faamaualuga, ma i lona manatu faapito, ma ia usiusitai i le muai poloaiga na Ou tuuina atu ia te ia e uiga i le nofoaga o loo nofo ai o ia."},{"verse":9,"text":"Ma afai e faia e ia lenei mea, ona o le a leai ni vaevaega e faia i le laueleele, o le a tofia pea o ia e alu i le laueleele o Misuri;"},{"verse":10,"text":"A lē o lea, ia tuu atu ia te ia le tupe na ia totogi mai, ma alu ese mai le nofoaga, ma ia vavae ese o ia mai la’u ekalesia, ua fetalai mai ai le Alii le Atua o ’au;"},{"verse":11,"text":"Ma e ui ina mavae atu le lagi ma le lalolagi, o le a lē mavae atu lava nei upu, ae o le a faataunuuina."},{"verse":12,"text":"Ma afai e tatau ai i la’u auauna o Iosefa Samita, Le Itiiti, ona ia totogi atu le tupe, faauta, o A’u, o le Alii, o le a Ou toe totogi atu ia te ia i le laueleele o Misuri, ina ia mafai ona toe tauia i latou o e na ia maua mai ai, e tusa ma mea ua latou faia;"},{"verse":13,"text":"Aua o le a latou maua e tusa ma mea ua latou faia, i laueleele lava ua fai mo o latou tofi."},{"verse":14,"text":"Faauta, ua faapea ona fetalai mai o le Alii i lo’u nuu—atonu e tele mea ua ia te outou e fai ma salamo ai; aua faauta, ua oo mai i luga ia te a’u a outou agasala, ma ua lē faamagaloina, ona ua outou saili e taupulepule i o outou lava ala."},{"verse":15,"text":"Ma ua lē faamalieina o outou loto. Ma ua outou lē usiusitai i le upumoni, ae ua outou fiafia i le amiolētonu."},{"verse":16,"text":"Oi talofa ia te outou tagata mauoa, o e ua outou lē tuu atu ni a outou mea i e ua matitiva, ona o le a faaeleeleaina o outou agaga ia outou oa; ma o la outou auega lenei i le aso e asiasi mai ai, ma le aso o le faamasinoga, ma le aso o le toatamai: Ua mavae le seleselega, ua iu le tautaumafanafana, ae ua lē faaolaina lo’u agaga!"},{"verse":17,"text":"Oi talofa ia te outou tagata matitiva, o e ua lē momomo o latou loto, o e ua lē agasalamo o latou agaga, ma e ua lē maoona o latou manava, ma o e ua lē taofia o latou lima mai le fetagofi atu i mea a isi tagata, o e o o latou mata ua tumu i le matape’ape’a, ma o e ua mumusu e galulue i o latou lava lima!"},{"verse":18,"text":"Ae amuia e ua matitiva ua mama i le loto, o e ua momomo o latou loto, ma e ua agasalamo o latou agaga, ona o le a latou vaai i le oo mai o le malo o le Atua i le mana ma le mamalu tele mo lo latou laveaiina; ona o le a mo i latou le tamaoaiga o le lalolagi."},{"verse":19,"text":"Aua faauta, o le a afio mai le Alii, ma o le a faatasi ma ia lana taui, ma o le a ia tauia tagata uma taitoatasi, ma o le a olioli e ua matitiva;"},{"verse":20,"text":"Ma o le a fai ma tofi o a latou tupulaga le lalolagi mai lea tupulaga i lea tupulaga, e faavavau ma faavavau lava. Ma o lenei Ou te faaiu le tautala atu ia te outou. E faapea lava. Amene."}]},{"chapter":57,"verses":[{"verse":1,"text":"Faalogo mai ia, outou e toeaina o la’u ekalesia, ua fetalai mai ai le Alii lo outou Atua, o e ua outou faapotopoto faatasi outou lava, e tusa ma a’u poloaiga, i lenei laueleele, le laueleele lea o Misuri, le laueleele lea ua Ou tofia ma faapaiaina mo le faapotopotoina o le au paia."},{"verse":2,"text":"O le mea lea, o le laueleele lea o le folafolaga, ma o le nofoaga lea mo le aai o Siona."},{"verse":3,"text":"Ma ua faapea ona fetalai mai o le Alii lo outou Atua, afai tou te fia maua le poto, o le poto lenei. Faauta, o le nofoaga ua ta’ua nei o Initipene o le nofoaga tutotonu lea; ma o le tulaga mo le malumalu o loo taoto i le itu i sisifo, i luga o se fasi fanua e lē mamao ese mai le falefaamasino."},{"verse":4,"text":"O le mea lea, o se mea poto le tatau ona faatau o le laueleele e le au paia, ma fasi fanua uma foi o taooto i le itu i sisifo, e oo atu lava i le laina tuaoi o loo sosolo tonu atu i le va o Iutaia ma Nuuese;"},{"verse":5,"text":"Ma fasi fanua uma foi e tuaoi i tafatafa ane o fanua lauvao, e tusa ai ma le gafatia e o’u soo ona faatau mai o fanua. Faauta, o le poto lenei, ina ia mafai ai ona latou maua o fanua mo se tofi e faavavau."},{"verse":6,"text":"Ma ia tuu atu i la’u auauna o Sini Gilbert ia tulai i le tofi na Ou tofia i ai o ia, e talia tupe, e avea o se sui mo le ekalesia, e faatau mai fanua i nofoaga uma o faataamilo ai, e tusa ai ma le mafai ona faia i le amiotonu, ma taitaia ai e le poto."},{"verse":7,"text":"Ma ia tuu atu i la’u auauna o Eteuati Paterika ia tulai i le tofi na Ou tofia i ai o ia, ma vaevae atu i le au paia o latou tofi, e pei lava ona Ou poloaiina; ma i latou foi o e ua ia tofia e fesoasoani ia te ia."},{"verse":8,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ia tuu atu i la’u auauna o Sini Gilbert ia faamautuina o ia lava i lenei nofoaga, ma faatuina se faleoloa, ina ia mafai ona ia faatau atu oloa e aunoa ma le faasese, ina ia mafai ona ia maua o tupe e faatau mai ai fanua mo le lelei o le au paia, ma ina ia mafai ona ia maua o soo se mea atonu e manaomia e soo e faamautu ai i latou i o latou tofi."},{"verse":9,"text":"Ma ia tuu atu foi i la’u auauna o Sini Gilbert ia maua e ia se laisene—faauta, o le poto lenei, ma ai se e faitau, ia malamalama o ia—ina ia mafai e ia ona auina atu foi oloa i tagata, e ala atu lava i e e faafaigaluegaina e ia o ni failautusi i lana auaunaga;"},{"verse":10,"text":"Ma e faapea ona faia ai o mea mo la’u au paia, ina ia mafai ona talai atu la’u talalelei ia i latou o e ua nonofo i le pouliuli ma i le itulagi ma le ata o le oti."},{"verse":11,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ia tuu atu i la’u auauna o Viliamu W. Phelps e faamautu i lenei nofoaga, ma faia o se lomitusi mo le ekalesia."},{"verse":12,"text":"Ma faauta, afai e talia e le lalolagi ana tusitusiga—faauta o le poto lenei—ia tuu atu ia te ia ia ona maua soo se mea e mafai ona ia maua i le amiotonu, mo le lelei o le au paia."},{"verse":13,"text":"Ma ia tuu atu i la’u auauna o Oliva Kaotui e fesoasoani ia te ia, e pei ona Ou poloaiina ai, i soo se mea lava Ou te tofia i ai o ia, e kopi, ma faasao, ma filifili, ina ia mafai ona sa’o o mea uma i o’u luma, e pei ona o le a faamaonia ai e le Agaga e ala atu ia te ia."},{"verse":14,"text":"Ma ia faapea ona tuu atu i e ua Ou tautala atu ai ia faamautuina i le laueleele o Siona, i le vave e mafai ai, faatasi ma o latou aiga, e fai mea na e pei lava ona Ou tautala atu ai."},{"verse":15,"text":"Ma o lenei, e faatatau i le faapotopotoina—Ia tuu atu i le epikopo ma le sui e fai sauniuniga mo aiga na poloaiina e o mai i le laueleele lenei, i le vave e mafai ai, ma faamautu i latou i o latou tofi."},{"verse":16,"text":"Ma mo e na totoe o toeaina ma tagata o le ekalesia, o le a tuuina atu i ai ni isi faatonuga i se taimi o mulimuli mai. E faapea lava. Amene."}]},{"chapter":58,"verses":[{"verse":1,"text":"Faalogo mai ia, outou e toeaina o la’u ekalesia, ma uai mai o outou taliga i la’u upu, ma iloa mai ia te a’u mea ua Ou loto i ai e faatatau ia te outou, ma e faatatau foi i lenei laueleele lea ua Ou tuuina atu ia te outou."},{"verse":2,"text":"Aua e moni Ou te fai atu ia te outou, amuia lava o ia o lē e tausi i a’u poloaiga, pe i le olaga nei po o i le oti; ma o ia o lē e faamaoni i puapuaga, ua sili atu le tele o lona taui i le malo o le lagi."},{"verse":3,"text":"E lē mafai ona outou vaaia i o outou mata faalenatura, i le taimi nei, le fuafuaga a lo outou Atua e faatatau i mea o le a oo mai pe a mavae le taimi nei, ma le mamalu e mulimuli mai pe a mavae puapuaga e tele."},{"verse":4,"text":"Aua a mavae puapuaga e tele ona oo mai ai lea o faamanuiaga. O le mea lea, e oo mai le aso o le a faapaleina ai outou i le mamalu tele; e lei oo mai le itula, ae ua lata mai lava ona oo mai."},{"verse":5,"text":"Ia manatua le mea lenei, lea ua ou muai ta’u atu, ina ia outou teuina i le loto, ma maua ai mea o le a mulimuli mai."},{"verse":6,"text":"Faauta, e moni Ou te fai atu ia te outou, o le pogai lenei na Ou auina atu ai outou—ina ia outou usiusitai, ma ina ia mafai ona saunia o o outou loto e molimau atu e uiga i mea o le a oo mai;"},{"verse":7,"text":"Ma ina ia mafai foi ona faamamaluina outou i le faataatiaina o le faavae, ma i le molimau atu e uiga i le laueleele lea o le a faatuina ai i luga le Siona a le Atua;"},{"verse":8,"text":"Ma ina ia mafai foi ona saunia o se taumafataga o mea lololo mo e ua matitiva; ioe, o se taumafataga o mea lololo, o uaina ua i ai le ’alu ua faamamaina lelei, ina ia iloa e le lalolagi o le a lē iuvale lava fofoga o perofeta;"},{"verse":9,"text":"Ioe, o se taumafataga o le maota o le Alii, ua saunia lelei, lea o le a valaaulia i ai atunuu uma."},{"verse":10,"text":"Muamua, o e ua mauoa ma e ua aoaoina, o e atamamai ma e taualoa;"},{"verse":11,"text":"Ma a mavae lena ona oo mai lea o le aso o lo’u mana; ona o mai lea o e ua matitiva, o e ua pipili, ma e ua tauaso, ma e ua tutuli, i le tausamaaga a le Tamai Mamoe, ma taumamafa i le talisuaga afiafi a le Alii, ua saunia mo le aso tele o le a oo mai."},{"verse":12,"text":"Faauta, o A’u, o le Alii, ua Ou tautala atu ai."},{"verse":13,"text":"Ma ina ia mafai ona oo atu le molimau mai Siona, ioe, mai le fofoga o le aai o le tofi o le Atua—"},{"verse":14,"text":"Ioe, o le pogai lenei na Ou auina mai ai outou iinei, ma Ou filifilia ai la’u auauna o Eteuati Paterika, ma Ou tofi atu ai ia te ia lana misiona i le laueleele lenei."},{"verse":15,"text":"Ae afai e lē salamo o ia i ana agasala, o le lē talitonu lea ma le tauaso o le loto, ia faaeteete o ia ne’i pa’ū."},{"verse":16,"text":"Faauta ua tuu atu ia te ia lana misiona, ma e lē toe tuuina atu lava."},{"verse":17,"text":"Ma ai se e tulai mai i lenei misiona, ua tofia e avea ma faamasino i Isaraelu, e pei ona sa i ai i aso anamua, e vaevae laueleele o le tofi a le Atua i ana fanau;"},{"verse":18,"text":"Ma e faamasino lona nuu i le molimau a e ua tonu, ma i le lagolago a ona fesoasoani, e tusa ma tulafono o le malo o le Atua e tuuina atu e perofeta a le Atua."},{"verse":19,"text":"Aua e moni Ou te fai atu ia te outou, ia tausia la’u tulafono i luga o lenei laueleele."},{"verse":20,"text":"Ia lē tuu atu i se tagata ia manatu ua pule o ia; ae ia tuu atu i le Atua e pulea o ia o lē ua faamasino atu, e tusa ma le faamoemoe a lona lava loto, po o ua faapea, o ia lea o lē ua faufautua atu pe ua nofo i luga o le nofoa faamasino."},{"verse":21,"text":"Ia lē tuu atu i se tagata ia soli e ia le tulafono o le laueleele, ona o ia o lē e tausia tulafono a le Atua e le manaomia ona soli o tulafono o le laueleele."},{"verse":22,"text":"O le mea lea, ia outou tuu atu outou i lalo o pule ua i ai, seia nofotupu o ia o lē e ona le aiā e nofotupu ai, ma faatoilalo fili uma i lalo o ona vae."},{"verse":23,"text":"Faauta, o tulafono ua outou maua mai lo’u lima o tulafono ia o le ekalesia, ma o le malamalama lenei ia outou umia ai. Faauta, o le poto lea."},{"verse":24,"text":"Ma o lenei, e pei ona Ou tautala atu e uiga i la’u auauna o Eteuati Paterika, o le laueleele lenei o le laueleele lea o lona alaalafaga, ma i latou o e ua ia tofia mo ona fesoasoani; ma o le laueleele foi lea o le alaalafaga o ia o lē ua Ou tofia e tausia lo’u faleteuoloa;"},{"verse":25,"text":"O le mea lea, ia tuu atu ia te i latou e aumai o latou aiga i le laueleele lenei, e pei ona latou fefautuaai ai i le va o i latou lava ma a’u."},{"verse":26,"text":"Aua faauta, e lē tatau ona Ou poloai atu i mea uma; aua o ia o lē e tau faamalosia i mea uma, o ia lava lea o se auauna paie ma lē poto; o le mea lea e lē maua ai e ia se taui."},{"verse":27,"text":"E moni Ou te fai atu, e tatau i tagata ona auai ma le naunautai i se faamoemoega lelei, ma fai mea e tele i lo latou lava loto malie, ma aumai ai le amiotonu tele;"},{"verse":28,"text":"Aua ua i totonu ia te i latou le mana, lea ua latou pule ai ia te i latou lava. Ma e tusa ai ma le faia e tagata o mea lelei, o le a leai lava se ala o le a aveesea ai lo latou taui."},{"verse":29,"text":"Ae o ia o lē e lē faia e ia se mea seia poloaiina ai o ia, ma talia se poloaiga ma le loto masalosalo, ma ia tausia ma le paie, o ia lava lea e tausalaina."},{"verse":30,"text":"O ai A’u o lē na faia le tagata, ua fetalai mai ai le Alii, o le a ia lē tausalaina o ia o lē e lē usiusitai i a’u poloaiga?"},{"verse":31,"text":"O ai A’u, ua fetalai mai ai le Alii, ua Ou folafola atu ae ua lē faataunuuina?"},{"verse":32,"text":"Ou te poloai atu a ua lē usiusitai mai tagata; ou te aveesea ma latou te lē maua ai le faamanuiaga."},{"verse":33,"text":"Ona latou fai ifo lea i o latou loto: E lē o le galuega lenei a le Alii, ona ua lē taunuu ana folafolaga. Ae oi talofa i e faapea, ona o loo faatali mai lalō lo latou taui, ae ua lē mai i lugā."},{"verse":34,"text":"Ma Ou te tuu atu nei ia te outou ni isi faatonuga e faatatau i le laueleele lenei."},{"verse":35,"text":"O le poto ia te a’u, le tatau ona avea o la’u auauna o Matini Harisi ma faataitaiga i le ekalesia, i le tuuina atu o ana tupe i luma o le epikopo o le ekalesia."},{"verse":36,"text":"E le gata i lea, o se tulafono lenei i tagata uma o e e o mai i le laueleele lenei e maua ai se tofi; ma ia faia e ia i ana tupe e pei ona faatonuina e le tulafono."},{"verse":37,"text":"Ma o le poto foi, le tatau ona faatau mai o ni laueleele i Initipene, mo le tulaga o le faleteuoloa, ma le fale lomitusi foi."},{"verse":38,"text":"Ma o isi faatonuga e faatatau i la’u auauna o Matini Harisi o le a tuu atu ia te ia e le Agaga, ina ia mafai e ia ona maua lona tofi e pei ona lelei ia te ia;"},{"verse":39,"text":"Ma ia tuu atu ia te ia ia salamo i ana agasala, ona ua saili e ia le viiga a le lalolagi."},{"verse":40,"text":"Ma ia tuu atu foi i la’u auauna o Viliamu W. Phelps ia tulai i le tofi ua Ou tofia i ai o ia, ma talia lona tofi i le laueleele;"},{"verse":41,"text":"Ma ua ia te ia foi se mea e tatau ona salamo ai, aua, o A’u, o le Alii, ua Ou lē fiafia tele ia te ia, ona ua saili o ia e fia sili, ma ua lē lava lona agamalu i o’u luma."},{"verse":42,"text":"Faauta, o ia o lē ua salamo i ana agasala, o ia lava lea ua faamagaloina, ma o A’u, o le Alii, e lē toe manatuaina lava i latou."},{"verse":43,"text":"O le mea lenei e mafai ai ona outou iloa pe afai ua salamo se tagata i ana agasala—faauta, o le a ia ta’uta’u atu ma lafoai i ai."},{"verse":44,"text":"Ma o lenei, e moni, Ou te fai atu e faatatau i le vaega o totoe o toeaina o la’u ekalesia, e lei oo mai le taimi, mo le tele o tausaga, mo i latou e maua ai lo latou tofi i le laueleele lenei, tau lava ona pei o le a tofia atu ai e le Alii ia te i latou, vagana ai ua latou mananao i ai e ala i le tatalo o le faatuatua."},{"verse":45,"text":"Aua, faauta, o le a latou tulei faatasi tagata mai tuluiga o le lalolagi."},{"verse":46,"text":"O le mea lea, ia outou faapotopoto faatasi outou lava; ma o i latou o e e lei tofia e nonofo i le laueleele lenei, ia tuu atu ia te i latou e talai atu le talalelei i nofoaga o faataamilo ai; ma a mavae lena ia tuu atu ia te i latou e foi atu i o latou aiga."},{"verse":47,"text":"Tuu atu ia te i latou e talai atu i le ala, ma molimau atu e uiga i le upumoni i nofoaga uma, ma valaau atu i e ua mauoa, e ua maualuluga ma e ua maualalalo, ma e ua matitiva, ia salamo."},{"verse":48,"text":"Ma ia tuu atu ia te i latou e atia’e aulotu, e tusa ai ma le salamo o tagata o le lalolagi."},{"verse":49,"text":"Ma ia i ai se sui e tofia i le leo o le ekalesia, mo le aulotu i Ohaio, e talia tupe e faatau mai ai laueleele i Siona."},{"verse":50,"text":"Ma Ou te tuu atu i la’u auauna o Sini Rikitone se poloaiga, ia tusi e ia se faamatalaga o le laueleele o Siona, ma se faamatalaga o le finagalo o le Atua, e pei ona o le a faailoa atu e le Agaga ia te ia;"},{"verse":51,"text":"Ma se tusi ma se pepa o le faasologa o igoa, e tuu atu i aulotu uma e maua ai tupe, e tuu atu i lima o le epikopo, o ia lava po o le sui, e pei ona lelei ia te ia, pe e pei ona ia faatonuina, e faatau mai ai laueleele mo se tofi mo le fanau a le Atua."},{"verse":52,"text":"Aua, faauta, e moni Ou te fai atu ia te outou, ua finagalo le Alii ia tatala e soo ma le fanau a tagata o latou loto, e oo lava i le faatauina mai o le itulagi atoa lenei o le atunuu, i se taimi vave e mafai ai."},{"verse":53,"text":"Faauta, o le poto lenei. Ia tuu atu ia te i latou e fai lenei mea ne’i lē maua e i latou se tofi, vagana ai i le faamasaaina o le toto."},{"verse":54,"text":"O lenei foi, e tusa ai ma le mauaina o se fanua, ia auina atu tagata faigaluega ituaiga eseese uma i le fanua lenei, e galulue mo le au paia a le Atua."},{"verse":55,"text":"Ia tuu atu nei mea uma ia faia i le faasologa tatau; ma ia tuu atu avanoa o le laueleele ia faailoa atu mai lea taimi i lea taimi, e le epikopo po o le sui o le ekalesia."},{"verse":56,"text":"Ma ia tuu atu le galuega o le faapotopotoina ia lē faanatinatia, pe i se solaaga; ae ia tuu atu e faia e pei ona o le a soalaupuleina e toeaina o le ekalesia i konafesi, e tusa ma le malamalama latou te maua mai lea taimi i lea taimi."},{"verse":57,"text":"Ma ia tuu atu i la’u auauna o Sini Rikitone na te faapaia ma faamanuia lenei laueleele, ma le tulaga mo le malumalu, mo le Alii."},{"verse":58,"text":"Ma ia tuu atu ia taloina se fonotaga o le konafesi; ma a mavae lena ia tuu atu i a’u auauna o Sini Rikitone ma Iosefa Samita, Le Itiiti, e foi atu, ma Oliva Kaotui foi faatasi ma i laua, e faauma le vaega o totoe o le galuega na Ou tofi atu ia te i latou i lo latou lava laueleele, ma le vaega o totoe e pei ona o le a faatonuina ai i konafesi."},{"verse":59,"text":"Ma ia lē tuu atu i se tagata e foi mai lenei laueleele vagana ai ia molimau atu o ia i le ala, e uiga i mea ua ia iloa ma ua talitonu moni i ai."},{"verse":60,"text":"Ia tuu mea na faaee atu i luga o Ziba Peterson ia aveesea mai ia te ia; ma ia tuu atu ia te ia e tulai o se tasi o le ekalesia, ma galue i ona lava lima, faatasi ma le au uso, seia lava ona aoaia o ia mo ana agasala uma; ona ua lē ta’uta’u mai e ia i latou, ma ua manatu o ia e nanā i latou."},{"verse":61,"text":"Ia tuu atu i le vaega o totoe o toeaina o lenei ekalesia, o e o loo o mai i le laueleele lenei, o ni isi o i latou ua faamanuiaina tele i luga atu o le tulaga fuaina, ia latou faia foi se konafesi i luga o le laueleele lenei."},{"verse":62,"text":"Ma ia tuu atu i la’u auauna o Eteuati Paterika na te taitaia le konafesi o le a latou faia."},{"verse":63,"text":"Ma ia tuu atu foi ia te i latou ia foi atu, ma talai atu le talalelei i le ala, ma molimau atu e uiga i mea ua faaali mai ia te i latou."},{"verse":64,"text":"Aua, e moni, e ao ona alu atu le leo mai lenei nofoaga i le lalolagi atoa, ma i vaega aupito mamao o le lalolagi—e ao ina talai atu le talalelei i tagata uma lava, ma faailoga e mulimuli atu ia te i latou o e e talitonu."},{"verse":65,"text":"Ma faauta ua afio mai le Atalii o le Tagata. Amene."}]},{"chapter":59,"verses":[{"verse":1,"text":"Faauta, amuia lava i latou, ua fetalai mai ai le Alii, o e ua o mai i lenei laueleele ma le manatu tasi i lo’u mamalu, e tusa ma a’u poloaiga."},{"verse":2,"text":"Aua o i latou o e e ola e fai mo o latou tofi le lalolagi, ma o e e oti o le a malolo mai ia latou galuega uma, ma o le a mulimuli atu a latou galuega ia te i latou; ma o le a latou maua se pale i maota o lo’u Tamā, ua Ou saunia mo i latou."},{"verse":3,"text":"Ioe, amuia lava i latou o e e tutu o latou vae i luga o le laueleele o Siona, o e ua usiusitai i la’u talalelei; ona o le a latou maua mo lo latou taui mea lelei o le lalolagi, ma o le a aumaia i lona malosi."},{"verse":4,"text":"Ma o le a faapaleina foi i latou i faamanuiaga mai lugā, ioe, ma poloaiga e lē itiiti, ma faaaliga i o latou taimi—i latou ia e faamaoni ma filiga i o’u luma."},{"verse":5,"text":"O le mea lea, Ou te tuu atu ai ia te i latou se poloaiga, e fai atu: Ia e alofa atu i le Alii lou Atua ma lou loto atoa, ma lou manatu atoa, mafaufau, ma le malosi; ma ia e auauna atu ia te ia i le suafa o Iesu Keriso."},{"verse":6,"text":"Ia e alofa atu i lē lua te tuaoi e pei o oe lava ia te oe. Aua e te gaoi; pe e te mulilua, pe fasioti tagata, pe e te faia soo se mea faapena."},{"verse":7,"text":"Ia e faafetai atu i le Alii lou Atua i mea uma."},{"verse":8,"text":"Ia e osi atu se taulaga i le Alii lou Atua i le amiotonu, o se taulaga lava o le loto momomo ma le agaga salamo."},{"verse":9,"text":"Ma ina ia mafai ona e tausi atili atoatoa oe lava i le lē pisia mai le lalolagi, ia e alu atu i le fale tatalo ma osi a’e au faamanatuga i lo’u aso paia;"},{"verse":10,"text":"Aua e moni o se aso lenei ua atofa mo oe e te malolo ai mai au galuega, ma avatu ai au tapuaiga i le Silisili Ese;"},{"verse":11,"text":"Ae ui i lea, ia ava’e i le amiotonu au tautoga i aso uma ma taimi uma;"},{"verse":12,"text":"Ae ia manatua i le aso lenei, le aso lea o le Alii, ia e avatu ai au taulaga ma au faamanatuga i le Silisili Ese, ma ta’uta’u atu au agasala i ou uso, ma luma o le Alii."},{"verse":13,"text":"Ma i le aso lenei, aua ne’i e faia ai se isi lava mea, tau lava o le saunia o au meaai ma le manatu tasi o le loto ina ia atoatoa lau anapogi, pe, i se isi faaupuga, ina ia atoatoa lou olioli."},{"verse":14,"text":"E moni, o le anapogi ma le tatalo lea, pe i se isi faaupuga, o le olioli ma le tatalo."},{"verse":15,"text":"Ma e tusa ai ma lo outou faia o nei mea ma le faafetai, ma loto ma mata fiafia, ae lē ma le ata leoleoā, aua o le agasala lea, ae ma le loto ma le mata fiafia—"},{"verse":16,"text":"E moni Ou te fai atu, e tusa ai ma lo outou faia o lenei mea, e a outou le atoatoa o le lalolagi, o manu vaefa o le fanua ma manu felelei o le vanimonimo, ma mea e fe’a’ei i luga o laau ma savavali i luga o le fogaeleele;"},{"verse":17,"text":"Ioe, ma laau ’aina, ma mea lelei e maua mai i le eleele, pe mo meaai pe mo lavalava, pe mo fale, pe mo fale manu, pe mo togalaau ’aina, pe mo faatoaga, pe mo tovine;"},{"verse":18,"text":"Ioe, o mea uma e maua mai i le eleele, i lona tau talafeagai, ua faia mo le lelei ma le faaaogaina e le tagata, e faafiafia ai mata ma faaolioli ai le loto;"},{"verse":19,"text":"Ioe, mo meaai ma mo lavalava, mo le tofo ma mo le sogisogi, e faamalosi ai le tino ma faaolaola ai le agaga."},{"verse":20,"text":"Ma ua fiafia le Atua ua e tuu mai nei mea uma i le tagata; ona o le faamoemoe lea na faia ai ia faaaoga, ma le faautauta, ae ia lē soonafai, pe i le faamalosi."},{"verse":21,"text":"Ma ua leai se mea e faatausuai ai le tagata i le Atua, pe ua leai ni isi e sasao faasaga i ai lona toasa, sei vagana ai i latou o e latou te lē tautinoina lona aao i mea uma, ma lē usiusitai i ana poloaiga."},{"verse":22,"text":"Faauta, ua tusa ai lenei mea ma le tulafono ma perofeta; o le mea lea, aua le toe faalavelave mai ia te a’u e uiga i lenei mataupu."},{"verse":23,"text":"Ae ia iloa o ia o lē e faia galuega o le amiotonu o le a maua lona taui, o le filemu lea i le lalolagi lenei, ma le ola e faavavau i le lalolagi a sau."},{"verse":24,"text":"O A’u, o le Alii, ua fai atu ai, ma o le Agaga ua molimauina. Amene."}]},{"chapter":60,"verses":[{"verse":1,"text":"Faauta, ua faapea ona fetalai mai o le Alii i toeaina o lana ekalesia, o e ua tatau ona vave foi atu i le laueleele na latou o mai ai: Faauta, ua Ou fiafia lava, ona ua outou o mai i luga nei;"},{"verse":2,"text":"Ae ua Ou lē fiafia i ni isi, ona ua latou lē tatalaina o latou gutu, ae ua latou natia taleni ua Ou tuu atu ia te i latou, ona o le fefefe i tagata. Oi talofa i e faapea, ona ua sasao a’e lo’u ita e faasaga ia te i latou."},{"verse":3,"text":"Ma o le a oo mai, afai latou te lē faamaoni tele mai ia te a’u, o le a aveesea mai, e oo lava i mea ia ua ia te i latou."},{"verse":4,"text":"Aua o A’u, o le Alii, ua pule i le lagi i lugā, ma i totonu o autau o le lalolagi; ma i le aso o le a ’Ou faaputuputu ai a’u maa tāua, o le a iloa ai e tagata uma mea e faaalia ai le mana o le Atua."},{"verse":5,"text":"Ae, e moni, o le a Ou tautala atu ia te outou e faatatau i la outou malaga atu i le laueleele na outou o mai ai. Ia i ai se vaa e faia, pe faatau mai, e pei ona lelei ia te outou, ua lē afaina ia te a’u, ma faavave ona alu atu o la outou malaga i le nofoaga lea ua ta’ua o Sagato Luisi."},{"verse":6,"text":"Ma mai iina, ia tuu atu i a’u auauna, o Sini Rikitone, Iosefa Samita, Le Itiiti, ma Oliva Kaotui, e alu la latou malaga i Sinisinati;"},{"verse":7,"text":"Ma i le nofoaga lenei, ia tuu atu ia te i latou e siitia a’e i luga o latou leo ma talai atu la’u upu ma leo leotetele, e aunoa ma le ita po o le masalosalo, ma siitia a’e i luga lima paia i luga o i latou. Aua e mafai ona Ou faia outou ia paia, ma ua faamagaloina a outou agasala mai ia te outou."},{"verse":8,"text":"Ma ia tuu atu ia i latou o totoe e alu atu la latou malaga mai St. Louis, taitoalua, ma talai atu le upu, e lē faanatinatia, i totonu o faapotopotoga a e ua amioleaga, seia latou toe foi atu i aulotu na latou o mai ai."},{"verse":9,"text":"Ma o nei mea uma ua mo le lelei o aulotu; ona o le faamoemoe lea ua Ou auina atu ai i latou."},{"verse":10,"text":"Ma ia tuu atu i la’u auauna o Eteuati Paterika e vavae atu se vaega o le tupe na Ou tuuina atu ia te ia, i a’u toeaina o e ua poloaiina e foi atu;"},{"verse":11,"text":"Ma o ia o lē e mafaia, ia tuu atu ia te ia e toe faafoi mai e ala mai i le sui; ae o ia o lē e lē mafaia, ua lē manaomia mai ia te ia."},{"verse":12,"text":"Ma o lenei, Ou te tautala atu e faatatau ia i latou o totoe o e e o mai i lenei laueleele."},{"verse":13,"text":"Faauta, na auina atu i latou e talai atu la’u talalelei i totonu o faapotopotoga a e ua amioleaga; o le mea lea, Ou te tuu atu ai ia te i latou se poloaiga, e faapea: Aua e te faama’umauina lou taimi, pe e te natia lau taleni ina ia lē iloa."},{"verse":14,"text":"Ma a uma ona e sau i luga i le laueleele o Siona, ma uma ona e folafola atu o la’u upu, ia vave ona e foi atu, ma folafola atu la’u upu i faapotopotoga a e ua amioleaga, ia lē faanatinatia, pe i le ita po o le fefinauai."},{"verse":15,"text":"Ma ia lulu ese le efuefu o ou vae e faasaga ia te i latou o e latou te lē talia oe, ia lē faia i o latou luma, ne’i e faaonoono ia te i latou, ae i se mea lilo; ma mulumulu ou vae, o se molimau e faasaga ia te i latou i le aso o le faamasinoga."},{"verse":16,"text":"Faauta, ua lava nei mea mo outou, ma o le finagalo lea o lē ua auina atu outou."},{"verse":17,"text":"Ma o le fofoga o la’u auauna o Iosefa Samita, Le Itiiti, o le a faailoa atu ai e faatatau ia Sini Rikitone ma Oliva Kaotui. O le vaega o totoe i se taimi o mulimuli mai. E faapea lava. Amene."}]},{"chapter":61,"verses":[{"verse":1,"text":"Faauta, ma faalogo mai i le leo o ia o lē ua i ai le mana uma, o lē ua mai le faavavau-tumau i le faavavau-tumau, o le Alefa ma le Omeka lava, o le amataga ma le gataaga."},{"verse":2,"text":"Faauta, e moni ua faapea ona fetalai mai o le Alii ia te outou, o toeaina e o la’u ekalesia, o e ua potopoto i luga o lenei laufanua, o e o a latou agasala ua faamagaloina nei, ona o A’u, o le Alii, e faamagaloina agasala, ma ua Ou alofa mutimutivale ia te i latou o e e ta’uta’u mai a latou agasala ma loto maualalalo;"},{"verse":3,"text":"Peitai e moni Ou te fai atu ia te outou, ua lē manaomia ona o atu faavavevave le vaega atoa lenei o a’u toeaina i luga o vai, ae o loo fano i le lē talitonu tagata o loo nonofo ai i le tasi itu ma le isi itu."},{"verse":4,"text":"Ae ui i lea, na Ou tuuina atu ina ia mafai ona outou molimauina; faauta, e tele mea e lamatia ai le ola o loo i ai i luga o vai, ma aemaise lava pe a mavae le taimi nei;"},{"verse":5,"text":"Aua o A’u, o le Alii, ua Ou poloaiina i lo’u ita faafanoga e tele i luga o vai; ioe, ma aemaise lava i luga o nei vai."},{"verse":6,"text":"Ae ui i lea, ua i ai tagata uma i lo’u lima, ma o lē o i totonu o outou ua faamaoni o le a lē fano i vai."},{"verse":7,"text":"O le mea lea, ua tatau ai lava i la’u auauna o Sini Gilbert ma la’u auauna o Viliamu W. Phelps ona faanatinati atu i la laua fe’au ma le misiona."},{"verse":8,"text":"Ae ui i lea, Ou te lē tuuina atu ia outou taapeape seia aoaiina outou ona o a outou agasala uma, ina ia tasi outou, ina ia outou lē fano i le amioleaga;"},{"verse":9,"text":"Ae o nei, e moni Ou te fai atu, ua Ou loto ina ia outou o atu. O lea ia tuu atu i a’u auauna o Sini Gilbert ma Viliamu W. Phelps e ave la laua aumalaga muamua, ma tuu atu ia te i latou e alu faanatinati la latou malaga ina ia mafai ona latou faataunuu la latou misiona, ma o le a latou manumalo e ala i le faatuatua;"},{"verse":10,"text":"Ma e tusa ai ma lo latou faamaoni o le a faasaoina i latou, ma o A’u, o le Alii, o le a faatasi ma i latou."},{"verse":11,"text":"Ma ia tuu atu i toeaina e totoe latou te ave mea e manaomia mo lavalava."},{"verse":12,"text":"Ia tuu atu i la’u auauna o Sini Gilbert na te ave faatasi ma ia mea e lē manaomia, e pei ona o le a outou malilie i ai."},{"verse":13,"text":"Ma o lenei, faauta, e mo lo outou lelei na Ou tuu atu ai ia te outou se poloaiga e faatatau i nei mea; ma o A’u, o le Alii, o le a talatala faatasi ma outou e pei ona sa faia ma tagata i aso anamua."},{"verse":14,"text":"Faauta, o A’u, o le Alii, na faamanuiaina vai i le amataga; ae i aso e gata ai, ua Ou fetuu ai vai, e ala i le fofoga o la’u auauna o Ioane."},{"verse":15,"text":"O le mea lea, e oo mai aso o le a lē saogalemu ai se tasi i luga o vai."},{"verse":16,"text":"Ma o le a fai ane faapea i aso e oo mai, e leai se tasi e mafai ona alu a’e i le laueleele o Siona i luga o vai, na’o ia o lē ua sa’o i le loto."},{"verse":17,"text":"Ma, e pei ona fetuu, e A’u, o le Alii, le laueleele i le amataga, ua faapea foi ona Ou faamanuiaina i aso e gata ai, i lona taimi, mo le faaaogaina e la’u au paia, ina ia latou aai i lona tamaoaiga."},{"verse":18,"text":"Ma o lenei Ou te tuu atu ia te outou se poloaiga, o mea Ou te fai atu ai i le toatasi Ou te fai atu ai i tagata uma, ia outou muai lapataia o outou uso e faatatau i vai nei, ina ia latou lē malaga mai ai i luga o nei vai, ne’i leai so o latou faatuatua ma maua ai i latou i mailei;"},{"verse":19,"text":"O A’u, o le Alii, ua Ou poloaiina, ma ua tietie lē faaumatiaina i luga o vai, ma Ou te lē aveesea le poloaiga."},{"verse":20,"text":"O A’u, o le Alii, sa Ou ita ia te outou ananafi, ae o le asō ua liliuese lo’u ita."},{"verse":21,"text":"O le mea lea, ia tuu atu ia te i latou o e na Ou tautala atu ai, e tatau ona faanatinati la latou malaga—Ou te toe fai atu ia te outou, ia tuu atu ia te i latou ia faanatinati la latou malaga."},{"verse":22,"text":"Ma e lē afaina ia te a’u, pe a mavae se taimi itiiti, pe afai latou te faataunuu la latou misiona, pe latou te malaga atu i le vai po o le laueleele; ia tuu lenei mea ia faia e pei ona faailoa atu ia te i latou e tusa ma a latou filifiliga pe a mavae le taimi nei."},{"verse":23,"text":"Ma o lenei, e faatatau i a’u auauna, o Sini Rikitone, Iosefa Samita, Le Itiiti, ma Oliva Kaotui, ia tuu atu ia te i latou ia aua ne’i toe o mai i luga o vai, vagana i luga o le alavaa vaiti, a’o malaga atu i o latou aiga; po o faapea, aua ne’i o latou o mai i luga o vai e malaga atu ai, vagana ai i luga o le alavaa vaiti."},{"verse":24,"text":"Faauta, o A’u, o le Alii, ua ’Ou tofia se ala mo le malaga a la’u au paia; ma faauta, o le ala lenei—a mavae ona latou tuua le alavaa vaiti, ia latou malaga e ala atu i le laueleele, talu ai ona ua poloaiina i latou e malaga atu ma o atu i luga i le laueleele o Siona;"},{"verse":25,"text":"Ma ia latou faia e pei ona sa faia e le fanauga a Isaraelu, e faatutu o latou faleie i tafatafa o le ala."},{"verse":26,"text":"Ma, faauta, o lenei poloaiga ia outou tuu atu i o outou uso uma."},{"verse":27,"text":"Ae ui i lea, o lē ua tuuina atu i ai le mana e poloaiina ai vai, ua tuuina atu ia te ia e le Agaga ia iloa e ia ona ala uma;"},{"verse":28,"text":"O le mea lea, ia tuu atu ia te ia e fai e pei ona poloaiina ai o ia e le Agaga o le Atua soifua, pe i luga o le laueleele po o luga o vai, e pei ona tumau ai pea ia te a’u e fai pe a mavae atu nei."},{"verse":29,"text":"Ma ua tuu atu ia te outou le ala mo le au paia, po o le ala mo le au paia o le tolauapiga a le Alii, e malaga ai."},{"verse":30,"text":"O lenei foi, e moni Ou te fai atu ia te outou, a’u auauna o Sini Rikitone, Iosefa Samita, Le Itiiti, ma Oliva Kaotui, ia aua le tatalaina o latou fofoga i faapotopotoga a e amioleaga seia latou taunuu i Sinisinati;"},{"verse":31,"text":"Ma i le nofoaga lena, ia siitia a’e i luga o latou leo i le Atua e faasaga i lena nuu, ioe, ia te Ia o lē o lona toasa ua sasao faasaga i lo latou amioleaga, o ni tagata o e ua lata ona matua mo le faafanoga."},{"verse":32,"text":"Ma mai iina, ia tuu atu ia te i latou e malaga atu i faapotopotoga a o latou uso, ona ua manaomia tele i le taimi nei lava a latou galuega i totonu o i latou, nai lo totonu o faapotopotoga a e amioleaga."},{"verse":33,"text":"Ma o lenei, e faatatau i toeaina o totoe, ia tuu atu ia te i latou e malaga atu ma talai atu le afioga i totonu o faapotopotoga a e amioleaga, e pei ona tuuina mai ai;"},{"verse":34,"text":"Ma e tusa ai ma lo latou faia o lenei mea o le a latou tafi ai o latou ofu, ma o le a latou lē pōnā ai i o’u luma."},{"verse":35,"text":"Ma ia tuu atu ia te i latou e malaga faatasi, pe taitoalua, e pei ona lelei ia te i latou, tau ina tuu atu i la’u auauna o Reynolds Cahoon, ma la’u auauna o Samuel H. Samita, o e ua Ou fiafia tele i ai, ia aua ne’i o eseese seia toe foi atu i o laua aiga, ma o lenei mea ua mo se faamoemoega poto ua ia te a’u."},{"verse":36,"text":"Ma o lenei, e moni Ou te fai atu ia te outou, ma o le mea Ou te fai atu ai i le toatasi ua Ou fai atu ai i tagata uma, ia fiafia, le fanau iti e; ona ua Ou i ai i lo outou lotolotoi, ma Ou te lei tuulafoaia outou;"},{"verse":37,"text":"Ma e tusa ai ma lo outou faamaualaloina o outou lava i o’u luma, o faamanuiaga o le malo o a outou ia."},{"verse":38,"text":"Fusi i o outou sulugatiti ma mataala ma faamamalu, ma tulimatai i luma mo le afio mai o le Atalii o le Tagata, ona e afio mai o ia i le itula tou te lē manatu i ai."},{"verse":39,"text":"Tatalo e lē aunoa ina ia outou lē ulu atu i faaosoosoga, ina ia mafai ona outou gafatia le aso o lona afio mai, pe i le ola po o le oti. E faapea lava. Amene."}]},{"chapter":62,"verses":[{"verse":1,"text":"Faauta, ma faalogo mai, outou e toeaina o la’u ekalesia, ua fetalai mai ai le Alii lo outou Atua, o Iesu Keriso lava, lo outou fautua, o lē ua silafia vaivaiga o le tagata ma le ala e fesoasoani ai ia i latou o e ua faaosoosoina."},{"verse":2,"text":"Ma e moni ua i ai o’u mata i luga o i latou o e e lei o atu i luga o le laueleele o Siona; o le mea lea e lei atoatoa la outou misiona."},{"verse":3,"text":"Ae ui i lea, ua faamanuiaina outou, ona o le molimau na outou tuu atu ua tusi faamaumau i le lagi mo agelu e vaai i ai; ma ua latou olioli i luga o outou, ma ua faamagaloina a outou agasala mai ia te outou."},{"verse":4,"text":"Ma o lenei, ia faaauau pea la outou malaga. Ia outou faapotopoto outou lava i luga o le laueleele o Siona; ma faia se sauniga ma olioli faatasi, ma osi atu se faamanatuga i le Silisili Ese."},{"verse":5,"text":"Ma ona mafai lea ona outou foi atu e molimau atu, ioe, outou uma lava faatasi, pe taitoalua, e pei ona lelei ia te outou, e lē afaina ia te a’u; tau ina ia faamaoni, ma talai atu tala fiafia i e o nonofo i le lalolagi, po o totonu o faapotopotoga a e amioleaga."},{"verse":6,"text":"Faauta, o A’u, o le Alii, na Ou aumaia faatasi outou ina ia faataunuuina le folafolaga, ina ia faasaoina ma olioli faatasi e faamaoni ua i totonu o outou, i le laueleele o Misuri. O A’u, o le Alii, Ou te folafola atu ai i e ua faamaoni ma e lē mafai ona pepelo."},{"verse":7,"text":"O A’u, o le Alii, Ou te loto, afai e i ai ni o outou e mananao e tietie i solofanua, po o miula, po o kariota, o le a maua e ia lenei faamanuiaga, pe afai e maua e ia mai le aao o le Alii ma le loto faafetai i mea uma."},{"verse":8,"text":"O nei mea ua tumau ia te outou e fai e tusa ai ma le faautauta ma taitaiga a le Agaga."},{"verse":9,"text":"Faauta, ua a outou le malo. Ma faauta, ma tagai, ua Ou faatasi pea ma ē faamaoni. E faapea lava. Amene."}]},{"chapter":63,"verses":[{"verse":1,"text":"Faalogo mai ia, outou le nuu e, ma tatala o outou loto ma ua’i mai o outou taliga mai mea mamao; ma faalogo mai, outou ua ta’ua outou lava o tagata o le Alii, ma faalogo mai i le afioga a le Alii ma lona finagalo e faatatau ia te outou."},{"verse":2,"text":"Ioe, e moni, Ou te fai atu, ia faalogo mai i le afioga a ia o lē o lona toasa ua sasao e faasaga i e e amioleaga ma e e fouvale;"},{"verse":3,"text":"O lē ua finagalo e ave i latou lava o e ua finagalo o ia e ave, ma faasao i le olaga i latou o e ua finagalo o ia e faasaoina;"},{"verse":4,"text":"O lē na te ati a’e e tusa ma lona lava loto ma lana filifiliga; ma faaumatia pe a finagalo i ai, ma mafai ona ia lafo le agaga i lalo i seoli."},{"verse":5,"text":"Faauta, o A’u, o le Alii, Ou te tuu atu lo’u leo, ma ia usiusita’ia."},{"verse":6,"text":"O le mea lea, e moni Ou te fai atu, ia tuu atu i e e amioleaga ia faaeteete, ma tuu atu i e e amioleaga ia matata’u ma gatete; ma tuu atu i e e lē talitonu ia taofi o latou laugutu, ona o le a oo mai i o latou luga le aso o le toasa e pei o se asiosio, ma o le a iloa e tagata uma o A’u o le Atua."},{"verse":7,"text":"Ma o ia o lē e sailia faailoga o le a vaai i faailoga, ae lē mo le olataga."},{"verse":8,"text":"E moni, Ou te fai atu ia te outou, e i ai ni isi o i latou o loo i totonu o outou o e ua saili i faailoga, ma sa i ai lava ni isi faapena mai le amataga;"},{"verse":9,"text":"Peitai, faauta, e lē oo mai le faatuatua e ala i faailoga, ae o faailoga e mulimuli ia te i latou o e e talitonu."},{"verse":10,"text":"Ioe, e oo mai faailoga e ala i le faatuatua, ae lē ala mai i le manao o tagata, pe ona ua loto i ai, ae e ala mai i le finagalo o le Atua."},{"verse":11,"text":"Ioe, e oo mai faailoga i le faatuatua, i galuega ofoofogia, aua a aunoa ma le faatuatua, e leai se tagata e fiafia i ai le Atua; ma o lē ua toatamai i ai le Atua ua lē fiafia i ai o ia; o le mea lea, e leai ni faailoga e faaalia e ia i e faapea, na’o le toasa e oo i lo latou ta’usalaga."},{"verse":12,"text":"O le mea lea, o A’u, o le Alii, ua Ou lē fiafia ia i latou o i totonu o outou ua saili i faailoga ma mea ofoofogia mo le faatuatua, a ua lē mo le lelei o tagata ma lo’u mamalu."},{"verse":13,"text":"Ae ui i lea, Ou te tuu atu poloaiga, ma e toatele ua liliuese mai a’u poloaiga ma ua latou lē tausia i latou."},{"verse":14,"text":"Sa i ai i totonu o outou alii mulilulua ma fafine mulilulua; o ni isi o i latou ua liliuese mai ia te outou, ma o isi o loo nonofo pea faatasi ma outou ma o le a faaalia i se taimi mulimuli mai."},{"verse":15,"text":"Ia tuu atu i e faapea ia faaeteete ma salamo vave, ne’i oo mai le faamasinoga i luga o i latou e pei o se mailei, ma o lo latou valea o le a faaalia, ma o a latou galuega o le a mulimuli atu ia te i latou i le vaaiga a tagata."},{"verse":16,"text":"Ma e moni Ou te fai atu ia te outou, e pei ona Ou fai atu muamua, o ia o lē e vaai atu i se fafine ma manao i ai, pe afai e mulilulua ni isi i o latou loto, o le a latou lē maua le Agaga, ae o le a latou faafitia le faatuatuaga ma o le a matata’u."},{"verse":17,"text":"O le mea lea, o A’u, o le Alii, ua faapea atu o e e matata’u, ma e e lē talitonu, ma tagata pepelo uma, ma o soo se tasi e fiafia i le pepelo ma faia se pepelo, ma le faitaaga ma le faataulaitu, o le a i ai lo latou taui i lena lepa ua mu i le afi ma le teiō, o le oti faalua lea."},{"verse":18,"text":"E moni Ou te fai atu, o le a latou le i ai i le uluai toetutu."},{"verse":19,"text":"Ma o lenei faauta, o A’u, o le Alii, e fai atu ia te outou ua lē ta’uamiotonuina outou, ona ua i ai nei mea i totonu o outou."},{"verse":20,"text":"Ae ui i lea, o ia o lē e tumau i le faatuatua ma faia lo’u loto, o ia lava lea o le a manumalo, ma o le a maua e ia se tofi i le lalolagi pe a oo mai le aso o le liua;"},{"verse":21,"text":"Pe a liua le lalolagi, e tusa ai ma le mamanu sa faaali atu i a’u aposetolo i luga o le mauga; o le tala o lea mea tou te lei maua le atoatoa."},{"verse":22,"text":"Ma o lenei, e moni Ou te fai atu ia te outou, e pei ona sa Ou fai atu o le a Ou faailoa atu lo’u loto ia te outou, faauta o le a Ou faailoa atu ia te outou, e lē ala atu o se poloaiga, ona o loo i ai le toatele o e ua lē tausisi e tausi i a’u poloaiga."},{"verse":23,"text":"Ae ia te ia o lē ua tausi i a’u poloaiga o le a Ou tuu atu i ai mealilo o lo’u malo, ma o ia lava lea o le a i ai ia te ia se puna o le vai ola, e puna a’e i le ola faavavau-tumau."},{"verse":24,"text":"Ma o lenei, faauta, o le finagalo lenei o le Alii lo outou Atua e faatatau i lana au paia, e tatau ona latou faapotopoto faatasi i latou lava i le laueleele o Siona, e lē faanatinatia, ne’i i ai se fenumiai, e oo mai ai puapuaga."},{"verse":25,"text":"Faauta, o le laueleele o Siona—o A’u, o le Alii, ua Ou umia i o’u lava lima;"},{"verse":26,"text":"Ae ui i lea, o A’u, o le Alii, Ou te tuu atu ia Kaisara mea e a Kaisara."},{"verse":27,"text":"O le mea lea, o A’u o le Alii Ou te loto ia outou faatau mai laueleele, ina ia mafai ona outou maua tulaga sili atu i le lalolagi, ina ia mafai ona outou maua āiā i le lalolagi, ina ia lē mafai ona faaoso a’e i latou i le ita."},{"verse":28,"text":"Aua ua tuu e Satani i totonu o o latou loto ia feitai faasaga mai ia te outou, ma i le faamaligiina o le toto."},{"verse":29,"text":"O le mea lea, o le a lē maua le laueleele o Siona vagana ai i le faatau mai po o i le toto, a lē o lea, e leai se tofi mo outou."},{"verse":30,"text":"Ma afai e maua e ala i le faatau mai, faauta ua outou manuia;"},{"verse":31,"text":"Ma afai e maua e ala i le toto, talu ai ona ua faasaina outou e faamasaa le toto, faauta, ua i o outou luga o outou fili, ma o le a sauaina outou mai lea aai i lea aai, ma mai lea sunako i lea sunako, ma e toaitiiti o le a tutulai mai e maua se tofi."},{"verse":32,"text":"O A’u, o le Alii, ua Ou ita i e amioleaga; ua Ou taofia lo’u Agaga mai tagata o le lalolagi."},{"verse":33,"text":"Ua Ou tauto i lo’u ita, ma folafola taua i luga o le fogaeleele, ma o e amioleaga o le a fasiotia e amioleaga, ma o le a oo mai le mata’u i luga o tagata uma;"},{"verse":34,"text":"Ma o le au paia foi o le a toeitiiti lē sao ai; ae ui i lea, o A’u, o le Alii, o i le lagi, ua faatasi ma i latou, ma o le a Ou alu ifo mai luma o lo’u Tamā i le lagi ma faaumatia e amioleaga i le afi e lē matineia."},{"verse":35,"text":"Ma faauta, e le’i oo mai lenei mea, ae ua lata mai lava."},{"verse":36,"text":"O le mea lea, talu ai ona o A’u, o le Alii, na folafolaina atu nei mea uma i luga o le fogaeleele, Ou te loto ia faapotopoto la’u au paia i luga o le laueleele o Siona;"},{"verse":37,"text":"Ma e tatau i tagata uma ona ave le amiotonu i ona lima ma le faamaoni i ona sulugatiti, ma siitia a’e se leo o le lapataiga i tagata o le lalolagi; ma ta’u atu e ala i le upu ma le solaese, o le a oo mai le faafanoga i luga o e amioleaga."},{"verse":38,"text":"O le mea lea, ia tuu atu i o’u soo i Katelani, o e o nonofo i luga o lenei faatoaga, ia faatulaga o latou atugaluga faaletino."},{"verse":39,"text":"Ia tuu i la’u auauna o Tito Billings, o lē ua i ai lona tausiga o le faatoaga, e faatea atu le laueleele, ina ia mafai ona saunia o ia i le tautotogo a sau, e alu a’e lana malaga i le laueleele o Siona, faatasi ma i latou o e o nonofo ai, vagana ai i latou o e o le a Ou faapolopoloina mo a’u lava, o e o le a lē o atu seia Ou poloaiina ai i latou."},{"verse":40,"text":"Ma ia tuu tupe uma e mafai ona faasaoina, e lē afaina ia te a’u pe itiiti pe tele, e auina atu i le laueleele o Siona, ia i latou o e ua Ou tofia e mauaina."},{"verse":41,"text":"Faauta, o A’u, o le Alii, o le a Ou tuu atu i la’u auauna o Iosefa Samita, Le Itiiti, le mana o le a mafai ai e ia ona iloatino e ala i le Agaga, i latou o e e o a’e i le laueleele o Siona, ma i latou o o’u soo o e o le a nonofo pea."},{"verse":42,"text":"Ia tuu atu i la’u auauna o Newel K. Whitney e faatumauina pea lona faleoloa, pe i se isi faaupuga, le faleoloa, mo se vaitau itiiti."},{"verse":43,"text":"Ae ui i lea, ia tuu atu ia te ia e faamatuu atu tupe uma e mafai ona ia faamatuu atu, e auina atu i i le laueleele o Siona."},{"verse":44,"text":"Faauta, o nei mea ua i ai i ona lava lima, ia tuu atu ia te ia e fai e tusa ai ma le faautauta."},{"verse":45,"text":"E moni Ou te fai atu, ia faauuina o ia o se sui mo soo o le a nonofo pea, ma ia faauuina o ia i lenei mana;"},{"verse":46,"text":"Ma o lenei, asiasi vave atu i aulotu, faatasi ma la’u auauna o Oliva Kaotui, ma faamalamalama atu nei mea ia te i latou. Faauta, o lo’u loto lea, i le mauaina mai o tupe e pei lava ona sa Ou faatonuina."},{"verse":47,"text":"O ia o lē e faamaoni ma tumau o le a manumalo i le lalolagi."},{"verse":48,"text":"O ia o lē na te auina atu oa i luga i le laueleele o Siona o le a maua e ia se tofi i le lalolagi lenei, ma se taui foi i le lalolagi a sau, ma o le a mulimuli atu ana galuega ia te ia."},{"verse":49,"text":"Ioe, ma amuia lava e e oti o e e oti i le Alii, mai le taimi nei ma le agai i luma, pe a afio mai le Alii, ma o le a mavae atu ai mea tuai, ma faafouina ai mea uma, o le a latou tutulai mai nai le oti ma o le a lē feoti pe a mavae, ma o le a latou maua se tofi i luma o le Alii, i le aai paia."},{"verse":50,"text":"Ma o ia o lē e ola pe a afio mai le Alii, ma sa ia tausia le faatuatuaga, amuia lava o ia; ae ui i lea, ua tofia ia te ia ia oti i tausaga o le tagata."},{"verse":51,"text":"O le mea lea, o le a tutupu a’e fanau seia oo ina latou matutua, o le a feoti toeaiina matutua; ae o le a lē momoe i latou i le efuefu, ae o le a liua i latou i le emo o le mata."},{"verse":52,"text":"O le mea lea, o le pogai lenei na talai atu ai e le au aposetolo i le lalolagi le toetutu mai o e ua oti."},{"verse":53,"text":"O nei mea o mea ia e ao ina outou tulimatai atu i ai; ma, i le tautala atu e tusa ma le ala a le Alii, ua lata mai lava ona oo mai ia mea, ma i se taimi a sau, i le aso lava lea o le afio mai o le Atalii o le Tagata."},{"verse":54,"text":"Ma seia oo i lena itula, o le a i ai taupou valelea i totonu o e popoto; ma i le itula lena e oo mai ai se tuueseesega atoa o e amiotonu ma e amioleaga; ma i le aso lena o le a ’Ou auina atu ai a’u agelu e ’oto ese e amioleaga ma lafo i latou i le afi e lē matineia."},{"verse":55,"text":"Ma o lenei faauta, e moni Ou te fai atu ia te outou, o A’u, o le Alii, ua Ou lē fiafia i la’u auauna o Sini Rikitone; ua faaea e ia o ia lava i lona loto, ma sa lē talia e ia le fautuaga, ae ua faatausuai i le Agaga;"},{"verse":56,"text":"O le mea lea ua lē talia ai ana tusitusiga i le Alii, ma ia faia e ia se isi tusitusiga; ma afai e lē taliaina e le Alii, faauta e lē toe tu o ia i le tofiga na Ou tofia i ai o ia."},{"verse":57,"text":"O lenei foi, e moni Ou te fai atu ia te outou, o i latou o e ua mananao i o latou loto, i le agamalu, e lapatai atu i e ua agasala ia salamo, ia tuu atu i latou ia faauuina i lenei mana."},{"verse":58,"text":"Aua o se aso lenei o le lapataiga, ae lē o se aso mo le tele o upu. Aua o A’u, o le Alii, ia lē ulagia i aso gataaga."},{"verse":59,"text":"Faauta, ua Ou sau mai lugā, ma ua taoto i lalo ifo lo’u mana. Ou te pule i mea uma, ma ua i ai i totonu o mea uma, ma e ala atu i mea uma, ma vailiili i mea uma, ma e oo mai le aso o le a i ai mea uma i la’u pule."},{"verse":60,"text":"Faauta, o A’u o le Alefa ma le Omeka, o Iesu Keriso lava."},{"verse":61,"text":"O le mea lea, ia tuu atu i tagata uma ia faaeteete i le ala latou te faaaoga ai lo’u igoa i o latou laugutu—"},{"verse":62,"text":"Aua faauta, e moni Ou te fai atu, e toatele e ua i ai i lalo o lenei tausalaga, o e ua latou faaaoga le suafa o le Alii, ma faaaogaina fua, e aunoa ma le pule."},{"verse":63,"text":"O le mea lea, ia tuu atu i le ekalesia ia salamo i a latou agasala, ma o A’u, o le Alii, o le a fai i latou mo A’u; a lē o lea o le a vavae ese i latou."},{"verse":64,"text":"Ia manatua o le mea e sau mai luga ua paia, ma e ao ona tautalagia ma le faaeteete, ma i le taofiofiga a le Agaga; ma ua leai se tausalaga i lenei mea, ma e tou te maua le Agaga e ala i le tatalo; o le mea lea, a aunoa ma lenei, e tumau pea le tausalaga."},{"verse":65,"text":"Ia tuu atu i a’u auauna, o Iosefa Samita, Le Itiiti, ma Sini Rikitone, e saili mo se fale mo i laua, e pei ona aoaoina ai i laua e le Agaga e ala i le tatalo."},{"verse":66,"text":"O nei mea ua tumau pea e faatoilaloina ai e ala i le onosai, ina ia mafai ona maua e e faapena se fuataga matuā tele atu ma faavavau o le mamalu, a lē o lea, o se tausalaga tele atu. Amene."}]},{"chapter":64,"verses":[{"verse":1,"text":"Faauta, ua faapea ona fetalai mai o le Alii lo outou Atua ia te outou, e outou e toeaina o la’u ekalesia, ia outou faalogo mai ma lagona, ma talia lo’u loto e faatatau ia te outou."},{"verse":2,"text":"Aua e moni Ou te fai atu ia te outou, Ou te loto ia outou manumalo i le lalolagi; o le mea lea o le a i ai lo’u agaalofa i luga o outou."},{"verse":3,"text":"E i ai ni isi o i latou o e o i totonu o outou ua agasala; ae e moni Ou te fai atu, i le taimi e tasi lenei, mo lo’u lava mamalu, ma mo le faaolataga o agaga, ua Ou faamagaloina outou ia outou agasala."},{"verse":4,"text":"O le a Ou alofa mutimutivale ia te outou, ona ua Ou tuu atu ia te outou le malo."},{"verse":5,"text":"Ma o ki o mealilo o le malo, e ala i auala ua Ou tofia, o le a lē aveesea mai la’u auauna o Iosefa Samita, Le Itiiti, a’o soifua o ia, e tusa ai ma lona usitaia o a’u sauniga."},{"verse":6,"text":"Ua i ai ni isi o i latou o e ua latou saili ni mea e faasaga ia te ia e aunoa ma se pogai;"},{"verse":7,"text":"Ae ui i lea, sa agasala o ia; ae e moni Ou te fai atu ia te outou, o A’u, o le Alii, Ou te faamagaloina agasala a i latou o e e ta’uta’u mai a latou agasala i o’u luma ma ole mai mo se faamagaloga, o e ia e lei agasala i le oti."},{"verse":8,"text":"O o’u soo, i aso anamua, sa latou saili ni mea e faasaga i le tasi ma lē faamagalo i le isi i o latou loto; ma o lenei mea leaga na faapuapuagatia ma aoai mamafa tele ai i latou."},{"verse":9,"text":"O le mea lea, Ou te fai atu ai ia te outou, e tatau ona outou faamagalo i le tasi; ona o ia o lē e lē faamagalo atu i lona uso i ana agasala, e tu ta’usalaina o ia i luma o le Alii; aua e tumau ia te ia le agasala tele atu."},{"verse":10,"text":"O A’u, o le Alii, Ou te faamagalo i lē o le a Ou faamagaloina, ae o outou ua poloaiina ia faamagalo atu i tagata uma."},{"verse":11,"text":"Ma e tatau ona outou fai ifo i o outou loto—ia tuu i le Atua e faamasino i le va o a’u ma oe, ma taui ia te oe e tusa ma au galuega."},{"verse":12,"text":"Ma o ia o lē e lē salamo i ana agasala, ma lē ta’uta’u atu i latou, ia outou aumai i luma o le ekalesia, ma fai ia te ia e pei ona fai mai tusitusiga paia ia te outou, pe ala i le poloaiga po o i le faaaliga."},{"verse":13,"text":"Ma ia outou faia lenei mea ina ia faamamaluina ai le Atua—e lē ona ua outou lē faamagalo atu, ona ua leai so outou agaalofa, ae ina ia mafai ona ta’uamiotonu ai outou e tusa ai ma le tulafono, ina ia outou lē faatausuai ai ia te ia o lē o lo outou faitulafono—"},{"verse":14,"text":"E moni Ou te fai atu, o le pogai lenei ia outou faia ai ia mea."},{"verse":15,"text":"Faauta, o A’u, o le Alii, sa Ou ita ia te ia o lē sa avea ma a’u auauna, o Ezra Booth, ma la’u auauna foi o Isaako Morley, ona sa laua lē tausia le tulafono, po o le poloaiga;"},{"verse":16,"text":"Sa laua saili le leaga i o laua loto, ma o A’u, o le Alii, na taofia lo’u Agaga. Sa laua ta’u ua leaga lena mea sa leai se leaga na i ai; ae ui i lea, ua Ou faamagaloina la’u auauna o Isaako Morley."},{"verse":17,"text":"Ma o la’u auauna foi o Eteuati Paterika, faauta, ua agasala o ia, ma ua saili Satani e faaumatia lona agaga; ae a faailoa atu nei mea ia te i latou, ma latou salamo ai i le leaga, o le a faamagaloina i latou."},{"verse":18,"text":"Ma o lenei, e moni Ou te fai atu ua tatau ai ia te a’u ona toe foi atu o la’u auauna o Sini Gilbert, pe a mavae ni nai vaiaso, i lana pisinisi, ma i lona tofi o le sui i le laueleele o Siona;"},{"verse":19,"text":"Ma o mea na vaai ma faalogo i ai o ia e mafai ona faailoa atu i o’u soo, ina ia lē fano i latou. Ma o le pogai lenei ua Ou tautala atu ai i nei mea."},{"verse":20,"text":"O lenei foi, Ou te fai atu ia te outou, ina ia lē faaosoosoina la’u auauna o Isaako Morley e sili atu i luga o le mea e mafai ona ia gafatia, ma fautua sese atu ai i mea tou te tiga ai, na Ou tuu atu ai le poloaiga e tatau ona faatau atu lana faatoaga."},{"verse":21,"text":"Ou te lē loto ia faatau atu e la’u auauna o Feterika G. Viliamu lana faatoaga, ona o A’u, o le Alii, Ou te loto ia i ai pea se taofiga malosi i le laueleele o Katelani, mo le va o le lima tausaga, lea o le a Ou lē faatoilaloina ai e ua amioleaga, ina ia mafai ona Ou faaolaina ai ni isi."},{"verse":22,"text":"Ma a mavae lena aso, o A’u, o le Alii, o le a lē ta’usalaina soo se tasi e alu a’e ma le loto matala i le laueleele o Siona; ona o A’u, o le Alii, Ou te manaomia loto o le fanauga a tagata."},{"verse":23,"text":"Faauta, ua ta’ua nei o le asō seia oo i le afio mai o le Atalii o le Tagata, ma e moni o se aso o le taulaga, ma o se aso mo le totogiina o le sefuluai e lo’u nuu; ona o ia o lē ua totogi le sefuluai o le a lē mu i lona afio mai."},{"verse":24,"text":"Aua a mavae le aso o le a oo mai le mu—o le faamatalaga lenei e tusa ma le ala a le Alii—aua e moni Ou te fai atu, o taeao, o le a faapei o tagutugutu o saito i latou uma ua faamaualuluga ma i latou o e ua fai amioleaga; ma o le a Ou susunuina i latou, aua o A’u o le Alii o ‘Au; ma o le a Ou lē faasaoina soo se tasi e tumau i Papelonia."},{"verse":25,"text":"O le mea lea, afai tou te talitonu mai ia te A’u, o le a outou galulue manū o ta’ua o le asō."},{"verse":26,"text":"Ma ua lē o se mea tatau i a’u auauna, o Newel K. Whitney ma Sini Gilbert, ona faatau atu lo la’ua faleoloa ma a la’ua mea ua maua, iinei; ona ua lē poto lena mea seia o a’e i le laueleele o Siona e o totoe o le ekalesia, o loo tumau pea i le nofoaga lenei."},{"verse":27,"text":"Faauta, ua fai mai i a’u tulafono, pe ua faasaina, le ’aitalafu i o outou fili;"},{"verse":28,"text":"Ae faauta, ua lē o fai mai i soo se taimi e faapea e lē tatau i le Alii ona ia ave pe a ia finagalo i ai, ma totogi atu e pei ona lelei ia te ia."},{"verse":29,"text":"O le mea lea, ona o oulua o sui, ua oulua o atu i le feau a le Alii; ma o soo se mea lua te faia e tusa ma le finagalo o le Alii o le matafaioi lea a le Alii."},{"verse":30,"text":"Ma ua ia faatutuina oulua e saunia mea mo lana au paia i aso nei e gata ai, ina ia mafai ona latou maua se tofi i le laueleele o Siona."},{"verse":31,"text":"Ma faauta, o A’u, o le Alii, Ou te tautino atu ia te oulua, ma o a’u upu e mautinoa ma e lē i’uvale, o le a latou maua lava."},{"verse":32,"text":"Peitai o le a oo mai mea uma i lo latou taimi."},{"verse":33,"text":"O le mea lea, aua le faavaivai i le faia o mea lelei, ona o lo o oulua faataatiaina le faavae o se galuega tele. Ma e maimea iti e tutupu mai ai mea tetele."},{"verse":34,"text":"Faauta, e manaomia e le Alii le loto ma le mafaufau malie; ma o e e loto malilie ma usiusitai o le a aai i le lelei o le laueleele o Siona i aso nei e gata ai."},{"verse":35,"text":"Ma o e e fouvale o le a vavae ese mai le laueleele o Siona, ma o le a auina ese atu, ma o le a lē mautofi i le laueleele."},{"verse":36,"text":"Aua, e moni Ou te fai atu o e e fouvale ua lē mai le toto o Efaraima, o le mea lea o le a aveeseina ai i latou."},{"verse":37,"text":"Faauta, o A’u, o le Alii, ua Ou faia la’u ekalesia i aso nei e gata ai e faapei o se faamasino o loo nofo i luga o se mauga, po o se nofoaga maualuga, e faamasino atunuu."},{"verse":38,"text":"Aua o le a oo mai o e o aumau i Siona o le a faamasino i mea uma e faatatau ia Siona."},{"verse":39,"text":"Ma o e e pepelo ma faatagālelei o le a faamaonia e i latou, ma o i latou o e e lē o ni aposetolo ma perofeta o le a iloa."},{"verse":40,"text":"Ma e oo i le epikopo, o lē o se faamasino, ma ona fesoasoani, afai latou te lē faamaoni ia latou matafaioi o le a tausalaina, ma o le a tuu isi i o latou tulaga."},{"verse":41,"text":"Aua, faauta, Ou te fai atu ia te outou o le a tupu olaola Siona, ma o le a i ona luga le mamalu o le Alii;"},{"verse":42,"text":"Ma o le a avea o ia o se tagavai i le nuu, ma o le a o mai ia te ia tagata mai atunuu uma o i lalo o le lagi."},{"verse":43,"text":"Ma e oo mai le aso o le a gatete ai atunuu uma o le lalolagi ona o ia, ma o le a matata’u ona o ona tagata matautia. Ua fetalai mai ai le Alii. Amene."}]},{"chapter":65,"verses":[{"verse":1,"text":"Faalogo mai ia, ma faauta, o se leo o le toatasi na auina ifo mai luga, o lē ua malosi silisili ma mamana, o lē o lona afio atu e oo atu i tuluiga o le lalolagi, ioe, o lē o lona siufofoga e oo atu i tagata—Ia outou teuteu le auala o le Alii, ma faasa’osa’o ona ala."},{"verse":2,"text":"O ki o le malo o le Atua ua tuu atu i tagata i luga o le lalolagi, ma mai iina o le a taavale atu ai i luma le talalelei i tuluiga o le lalolagi, e pei ona o le a taavale atu le maa na tofi mai le mauga e aunoa ma lima, seia faa tumuina ai le lalolagi atoa."},{"verse":3,"text":"Ioe, o se leo o alaga atu—Ia outou teuteu le auala o le Alii, ia outou saunia le talisuaga a le Tamai Mamoe, ia sauniuni mo le Faatoafaiavā."},{"verse":4,"text":"Tatalo atu i le Alii, valaau atu i lona suafa paia, faailoa atu ana galuega ofoofogia i totonu o tagata."},{"verse":5,"text":"Valaau atu i le Alii, ina ia aga’i i luma lona malo i le lalolagi, ina ia maua e e o nonofo ai, ma ia saunia mo aso o le a oo mai, lea o le a afio mai ai le Atalii o le Tagata o i le lagi, ua laei i le pupula o lona mamalu, e fetaia’i ma le malo o le Atua ua faatuina i le lalolagi."},{"verse":6,"text":"O le mea lea, ia alu i luma le malo o le Atua, ina ia oo mai le malo o le lagi, ina ia faamamaluina oe, le Atua e, i le lagi faapea foi i le lalolagi, ina ia faatoilaloina ou fili; ona e a oe le mamalu, mana ma le viiga, e faavavau faavavau lava. Amene."}]},{"chapter":66,"verses":[{"verse":1,"text":"Faauta, ua faapea ona fetalai mai o le Alii i la’u auauna o Viliamu E. McLellin—Amuia oe, talu ai ona ua e liliu ese mai au amioletonu, ma ua e talia a’u upumoni, ua fetalai mai ai le Alii lou Togiola, le Faaola o le lalolagi, po o le toatele lea o e e talitonu i lo’u igoa."},{"verse":2,"text":"E moni Ou te fai atu ia te oe, amuia oe i le talia o la’u feagaiga tumau e faavavau, le atoatoa lea o la’u talalelei, ua auina atu i le fanauga a tagata, ina ia mafai ona latou maua o le ola ma avea ma e e mauaina mamalu o le a faaalia i aso e gata ai, e pei ona sa tusia e perofeta ma aposetolo i aso anamua."},{"verse":3,"text":"E moni Ou te fai atu ia te oe, la’u auauna o Viliamu, ua e mamā, ae ua lē mamā atoa; o le mea lea, ia e salamo, i mea na ua lē lelei i la’u vaai, ua fetalai mai ai le Alii, ona o le a faaali atu i latou e le Alii ia te oe."},{"verse":4,"text":"Ma o lenei, e moni, o A’u, o le Alii, o le a Ou faailoa atu ia te oe mea Ou te manao i ai e faatatau ia te oe, po o lo’u loto e faatatau ia te oe."},{"verse":5,"text":"Faauta, e moni Ou te fai atu ia te oe, o lo’u loto lenei, e tatau ona e folafola atu la’u talalelei mai lea laueleele i lea laueleele, ma mai lea aai i lea aai, ioe, i nofoaga o faataamilo ai i mea e lei folafolaina ai."},{"verse":6,"text":"Aua le tele ni aso e te nofo ai i le nofoaga lenei; aua e te alu a’e nei i le laueleele o Siona; ae tusa ai ma lou mafai ona auina atu, auina atu; a lē o lea, aua le mafaufau i au meatotino."},{"verse":7,"text":"Alu i laueleele i sasa’e, molimau atu i nofoaga uma, i tagata uma ma i o latou sunako, ma feutaga’i ma tagata."},{"verse":8,"text":"Tuu atu i la’u auauna o Samuelu H. Samita e o atu faatasi ma oe, ma aua le tuulafoaia o ia, ma tuu atu ia te ia au faatonuga; ma o ia o lē e faamaoni o le a faamalosia i nofoaga uma; ma o A’u, o le Alii, o le a Ou alu faatasi ma oulua."},{"verse":9,"text":"Faaee atu ou lima i luga o e e mama’i, ma o le a toe faamaloloina i latou. Aua le foi mai seia auina atu oe e A’u, le Alii. Onosai i puapuaga. Ole atu, ma o le a e maua ai; tu’itu’i atu, ma o le a tatalaina mai ia te oe."},{"verse":10,"text":"Aua le saili e faalavelavea oe. Lafoa’i i amioletonu uma. Aua le mulilua—o se faaosoosoga lea na faalavelavea ai oe."},{"verse":11,"text":"Tausi i upu nei, ona ua moni ma faamaoni i latou; ma ia e faalauteleina lou tofi, ma uunai atu tagata e toatele i Siona faatasi ma pese o le olioli tumau e faavavau i luga o o latou ulu."},{"verse":12,"text":"Ia tumau pea i nei mea e oo lava i le iuga, ma o le a e maua ai se pale o le ola faavavau i le aao taumatau o lo’u Tamā, o lē ua tumu i le alofa tunoa ma le upumoni."},{"verse":13,"text":"E moni, ua faapea ona fetalai mai o le Alii lou Atua, lou Togiola, o Iesu Keriso lava lea. Amene."}]},{"chapter":67,"verses":[{"verse":1,"text":"Faauta ma faalogo mai, outou e toeaina o la’u ekalesia, o e ua outou faapotopoto faatasi outou lava, o ē o a latou tatalo ua Ou faalogoina, ma o ē ua Ou iloa o latou loto, ma o ē o o latou manao ua oo mai i o’u luma."},{"verse":2,"text":"Faauta ma tagai, ua i luga o outou o’u mata, ma o le lagi ma le lalolagi ua i o’u lima, ma o ’oa o le faavavau ua a a’u e tuu atu."},{"verse":3,"text":"Sa outou taumafai e talitonu e faapea e tatau ona outou maua le faamanuiaga lea sa ofo atu ia te outou; ae faauta, e moni Ou te fai atu ia te outou, sa i ai le fefe i o outou loto, ma e moni o le pogai lea na outou lē mauaina ai."},{"verse":4,"text":"Ma o lenei, o A’u, o le Alii, e tuuina atu ia te outou se molimau o le moni o nei poloaiga ua tuuina atu i o outou luma."},{"verse":5,"text":"Sa taula’i la outou vaai i la’u auauna o Iosefa Samita, Le Itiiti, ma o lana gagana ua outou iloa, ma o ona lē atoatoa ua outou iloa; ma ua outou saili i o outou loto le poto ina ia mafai ona outou faaupu ai ia sili atu i lana gagana; o lenei mea ua outou iloa foi."},{"verse":6,"text":"O lenei, ia outou saili mai i totonu o le Tusi o Poloaiga, se faaaliga aupito itiiti lava o i ai i totonu o ia faaaliga, ma tofi o ia o lē ua sili ona atamai i totonu o outou;"},{"verse":7,"text":"Pe, afai e i ai se tasi i totonu o outou e mafai ona faia se tasi e pei o lena faaaliga, ona ta’uamiotonuina lea o outou i le fai mai e faapea ua outou lē iloa ua moni i latou;"},{"verse":8,"text":"Ae afai e lē mafai ona outou faia se tasi e pei o lena faaaliga, ua i ai outou i le ta’usalaga pe afai tou te lē molimau atu ua moni i latou."},{"verse":9,"text":"Ona ua outou iloa ua leai se amioletonu ua i ai i totonu o i latou, ma o le mea e amiotonu e alu ifo mai lugā, mai le Tamā o malamalama."},{"verse":10,"text":"O lenei foi, e moni Ou te fai atu ia te outou, o lo outou avanoa, ma Ou te tuu atu ia te outou o e ua faauuina i lenei auaunaga se folafolaga, e tusa ai ma lo outou tafi esea mai ia outou lava le fuā ma atuatuvalega, ma faamaualalo outou lava i o’u luma, ona ua lē lava lo outou lotomaualalo, o le a saeluaina le veli ma o le a outou vaai mai ia te a’u ma iloa A’u—e lē i le mafaufau faaletino pe faalenatura, ae i le faaleagaga."},{"verse":11,"text":"Aua e leai se tagata na vaai i le Atua i soo se taimi i la le tino, vagana ai na liuaina e le Agaga o le Atua."},{"verse":12,"text":"Pe mafai foi e se tagata natura ona ola ai i le mamalu o le Atua, pe i le mafaufau faaletino."},{"verse":13,"text":"E lē mafai ona outou tumau ai i le mamalu o le Atua i le taimi nei, po o le auaunaga a agelu; o le mea lea, ia outou faaauau pea i le onosai seia faaatoatoaina outou."},{"verse":14,"text":"Aua le tuua o outou mafaufau e fuli i tua; ma a outou agavaa, o le a outou vaai ma iloa, i la’u lava taimi e tatau ai, le mea na faaee i o outou luga e lima o la’u auauna o Iosefa Samita, Le Itiiti. Amene."}]},{"chapter":68,"verses":[{"verse":1,"text":"O La’u auauna, o Orson Hyde, na valaaulia i lona faauuga e folafola atu le talalelei tumau e faavavau, e ala i le Agaga o le Atua soifua, mai lea nuu i lea nuu, ma mai lea laueleele i lea laueleele, i faapotopotoga a e amioleaga, i o latou sunako, ma talatala faatasi ma i latou ma faamatala atu tusitusiga paia uma ia te i latou."},{"verse":2,"text":"Ma, faauta, ma tagai, o se faataitaiga lenei ia i latou uma o e sa faauu i lenei perisitua, o e o la latou misiona ua tofia ia te i latou e o atu—"},{"verse":3,"text":"Ma o le faataitaiga lenei ia te i latou, ia latou tautala atu e pei ona uunaia ai i latou e le Agaga Paia."},{"verse":4,"text":"Ma o soo se mea o le a latou tautatala atu ai pe a uunaia ai e le Agaga Paia, o tusitusiga paia ia, o le finagalo lea o le Alii, o le mafaufau lea o le Alii, o le afioga lea a le Alii, o le siufofoga lea o le Alii, ma o le mana lea o le Atua mo le faaolataga."},{"verse":5,"text":"Faauta, o le folafolaga lenei a le Alii ia te outou, E outou e o a’u auauna."},{"verse":6,"text":"O le mea lea, ia fiafia, ma aua le fefefe, aua o A’u o le Alii ua Ou faatasi ma outou, ma o le a tulai i tafatafa o outou; ma o le a outou molimau atu ia te au, o Iesu Keriso lava, o A’u o le Atalii o le Atua soifua, ma sa Ou i ai, ma o loo Ou i ai, ma o le a Ou alu atu."},{"verse":7,"text":"O le afioga lenei a le Alii ia te oe, la’u auauna, Orson Hyde, ma i la’u auauna foi o Luka Johnson, ma i la’u auauna o Laimani Johnson, ma i la’u auauna o Viliamu E. McLellin, ma toeaina faamaoni uma o la’u ekalesia—"},{"verse":8,"text":"Ia outou o atu i le lalolagi atoa, talai atu le talalelei i tagata uma, ma faia i le pule ua Ou tuuina atu ia te outou, ma papatiso atu i le suafa o le Tamā, ma le Alo, ma le Agaga Paia."},{"verse":9,"text":"Ma o ia o lē e talitonu ma papatisoina o le a faaolaina, ma o ia o lē e lē talitonu o le a faamalaiaina."},{"verse":10,"text":"Ma o ia o lē e talitonu o le a faamanuiaina i faailoga e mulimuli mai, e pei lava ona tusia."},{"verse":11,"text":"Ma o le a tuu atu ia te outou ia outou iloa faailoga o taimi, ma faailoga o le afio mai o le Atalii o le Tagata;"},{"verse":12,"text":"Ma o le toatele o le a faapea ona molimau i ai le Tamā, o le a tuu atu ia te outou le mana e faamau ai i latou mo le ola faavavau. Amene."},{"verse":13,"text":"Ma o lenei, e faatatau i mataupu e faaopoopo i feagaiga ma poloaiga, o mataupu nei—"},{"verse":14,"text":"O loo i ai pe a mavae atu nei, i le taimi tatau ai a le Alii, isi epikopo e tatau ona vaetofia i le ekalesia, e auauna atu e tusa lava ma le na muamua;"},{"verse":15,"text":"O le mea lea, ia avea i latou ma ni faitaulaga sili o e ua agavaa, ma ia tofia i latou e le Au Peresitene Sili o le Perisitua Mekisateko, vagana ai i latou o ni suli moni o Arona."},{"verse":16,"text":"Ma afai o i latou o ni suli moni o Arona, ua i ai ia i latou se aia faaletulafono i le au epikopo, pe afai o ni ulumatua i latou i totonu o atalii o Arona;"},{"verse":17,"text":"Aua o le ulumatua e umia le aia o le pulefaamalumalu ai i luga o lenei perisitua, ma ki po o le pule o lea lava perisitua."},{"verse":18,"text":"E leai se tagata ua i ai se aia faaletulafono i lenei tofi, e umia ki o lenei perisitua, vagana o ia o sē suli moni ma se ulumatua o Arona."},{"verse":19,"text":"Peitai, ona ua i ai i se faitaulaga sili o le Perisitua Mekisateko le pule e galue ai i tofi maualalo uma lava, e mafai e ia ona galue i le tofi o le epikopo pe a leai se suli moni o Arona e mafai ona maua, pe a faapea e valaaulia ma vaetofia ma faauuina o ia i lenei mana, i lalo o aao o le Au Peresitene Sili o le Perisitua Mekisateko."},{"verse":20,"text":"Ma o sē suli moni foi o Arona, e ao ina tofiaina e lenei Au Peresitene, ma faamaonia ua agavaa, ma faauuina, ma faaeeina i ai le perisitua i lalo o aao o lenei Au Peresitene, a lē o lea e lē faatagaina faaletulafono i latou e galulue i lo latou perisitua."},{"verse":21,"text":"Ae, ona o le folafolaga e faatatau i la latou aia i le perisitua e faasolo mai le tamā i le atalii, e mafai ona latou maua ai lo latou faauuga i soo se taimi pe afai e mafai ona latou faamaonia lo latou gafa, pe iloa ai e ala i se faaaliga mai le Alii, i lalo o aao o le Au Peresitene ua ta’ua i luga."},{"verse":22,"text":"O lenei foi, ia leai se epikopo po o se faitaulaga sili e vaetofia mo lenei auaunaga e faamasinoina pe ta’usalaina i soo se soligatulafono, vagana ai i luma o le Au Peresitene Sili o le ekalesia;"},{"verse":23,"text":"Ma e tusa ai ma le mauaina ua sala o ia, e le pulega o lenei Au Peresitene, e ala i molimau e lē mafai ona faafitia, o le a ta’usalaina o ia;"},{"verse":24,"text":"Ma afai e salamo o le a faamagaloina o ia, e tusa ai ma feagaiga ma poloaiga o le ekalesia."},{"verse":25,"text":"Ma lenei foi, e tusa ai o le i ai o fanau a matua i Siona, po o i soo se tasi o ona siteki ua faatulagaina, ae latou te lē aoaoina i latou ia malamalama i le mataupu faavae o le salamo, faatuatua ia Keriso le Alo o le Atua soifua, ma e uiga i le papatisoga ma le meaalofa o le Agaga Paia e ala i le faaee atu o lima, pe a valu tausaga le matutua, ia i ai le agasala i luga o ulu o matua."},{"verse":26,"text":"Aua o le a avea lenei mea o se tulafono i e nonofo i Siona, po o soo se tasi o ona siteki ua faatulagaina."},{"verse":27,"text":"Ma ia papatisoina a latou fanau mo le faamagaloina o a latou agasala pe a valu tausaga le matutua, ma maua le faaeega o lima."},{"verse":28,"text":"Ma ia latou aoao foi a latou fanau ia tatalo, ma savavali tonu i luma o le Alii."},{"verse":29,"text":"Ma ia faamamalu foi e e nonofo i Siona le aso Sapati ia tausia i le paia."},{"verse":30,"text":"Ma ia manatua foi e ua nonofo i Siona a latou galuega, e tusa ai ma le tofia o i latou e galulue, i le faamaoni atoa; ona o le a manatua le paie i luma o le Alii."},{"verse":31,"text":"O lenei, o A’u, o le Alii, ua Ou lē fiafia i e ua nonofo i Siona, ona o loo i ai le paie i totonu o i latou; ma ua tutupu a’e foi a latou fanau i le amioleaga; ua latou lē saili foi ma le naunautai ’oa o le faavavau, ae ua tumu o latou mata i le matape’ape’a."},{"verse":32,"text":"O nei mea ua lē tatau ona i ai, ma e ao ina aveese mai totonu o i latou; o le mea lea, ia tuu atu i la’u auauna o Oliva Kaotui e tuuina atu nei upu i le laueleele o Siona."},{"verse":33,"text":"Ma Ou te tuu atu ia te i latou se poloaiga—o ia o lē e lē faia ana tatalo i luma o le Alii i lona vaitau, ia tuu atu o ia ia manatua i luma o le faamasino o lo’u nuu."},{"verse":34,"text":"O nei upu ua moni ma faamaoni; o le mea lea, aua ne’i solia i latou, pe aveese mai ai."},{"verse":35,"text":"Faauta, o A’u o le Alefa ma le Omeka, ma Ou te vave alu atu lava. Amene."}]},{"chapter":69,"verses":[{"verse":1,"text":"Faalogo mai ia te a’u, ua fetalai mai ai le Alii lo outou Atua, mo le lelei o la’u auauna o Oliva Kaotui. Ua lē o se mea poto ia te a’u le tatau ona faatuatua atu ia te ia o poloaiga ma tupe o le a alu o ia ma ave i le laueleele o Siona, vagana ai ua o faatasi ma se tasi o se o le a faamaoni ma faatuatuaina."},{"verse":2,"text":"O le mea lea, ua loto ai A’u, o le Alii, e tatau ona o o la’u auauna, o Ioane Uitimera, faatasi ma la’u auauna o Oliva Kaotui;"},{"verse":3,"text":"O lenei foi ia faaauau pea e ia ona tusitusi ma faia se talafaasolopito o mea tāua uma o le a ia vaaia ma iloaina e uiga i la’u ekalesia;"},{"verse":4,"text":"O lenei foi ina ia maua e ia fautuaga ma le fesoasoani mai la’u auauna o Oliva Kaotui ma isi."},{"verse":5,"text":"O lenei foi, e tatau i a’u auauna o e o loo i fafo i le lalolagi ona auina atu tala o a latou matafaioi i le laueleele o Siona;"},{"verse":6,"text":"Aua o le laueleele o Siona o le a avea ma laumua ma nofoaga e talia ma fai ai nei mea uma."},{"verse":7,"text":"Ae ui i lea, ia tuu atu i la’u auauna o Ioane Uitimera e malaga i le tele o taimi mai lea nofoaga i lea nofoaga, ma mai lea aulotu i lea aulotu, ina ia faigofie ia te ia ona maua le poto—"},{"verse":8,"text":"Ma talai ma faamalamalama atu, tusitusi, kopi, filifili, ma maua mai mea uma o le a avea mo le lelei o le ekalesia, mo tupulaga fai a’e o le a tutupu mai i luga o le laueleele o Siona, ia latou mauaina mai lea tupulaga i lea tupulaga, e faavavau ma faavavau lava. Amene."}]},{"chapter":70,"verses":[{"verse":1,"text":"Faauta, ma faalogo mai, E outou e ua aumau i Siona, ma outou uma o tagata o la’u ekalesia o e ua mamao ese atu, ma faalogo mai i le afioga a le Alii lea Ou te tuu atu i la’u auauna o Iosefa Samita, Le Itiiti, ma i la’u auauna foi o Matini Harisi, ma i la’u auauna foi o Oliva Kaotui, ma i la’u auauna foi o Ioane Uitimera, ma i la’u auauna foi o Sini Rikitone, ma i la’u auauna foi o Viliamu V. Phelps, e ala atu i se poloaiga ia te i latou."},{"verse":2,"text":"Aua Ou te tuu atu ia te i latou se poloaiga; o le mea lea ia faalogo mai ma lagona, aua ua faapea ona fetalai mai o le Alii ia te i latou—"},{"verse":3,"text":"O A’u, o le Alii, na tofia i latou, ma faauu i latou e avea ma tausimea o faaaliga ma poloaiga ua Ou tuu atu ia te i latou, ma ia o le a Ou tuu atu ia te i latou i taimi o mulimuli mai;"},{"verse":4,"text":"Ma o le a Ou manaomia mai ia te i latou se tala o lenei mea-tausi i le aso o le faamasinoga."},{"verse":5,"text":"O le mea lea, ua Ou tofia i latou, ma o la latou valaauga lenei i le ekalesia a le Atua, e pulea ia faaaliga ma poloaiga ma mea e tau i ai, ioe, o manuia mai ai."},{"verse":6,"text":"O le mea lea, Ou te tuu atu se poloaiga ia te i latou, ia latou lē tuuina atu nei mea i le ekalesia, pe i le lalolagi;"},{"verse":7,"text":"Ae ui i lea, e tusa ai ma lo latou mauaina o ni mea e sili atu i mea e manaomia mo mea e tatau ai mo i latou ma o latou manaoga, ia tuu atu i lo’u faleteuoloa;"},{"verse":8,"text":"Ma o ia manuia ia faapaiaina mo e e nonofo i Siona, ma mo a latou tupulaga, e tusa ai ma le avea o i latou ma suli e tusa ai ma tulafono o le malo o le Atua."},{"verse":9,"text":"Faauta, o le mea lenei e manaomia e le Alii mai tagata taitoatasi o ia o se tausimea, e pei ona uma ona tofia ai pe o le a tofia ai e A’u lava, o le Alii, i soo se tagata, pe o le a tofia i ai."},{"verse":10,"text":"Ma faauta, e leai se tasi o e auai i le ekalesia a le Atua soifua e tuusaoloto mai i lenei tulafono;"},{"verse":11,"text":"Ioe, po o le epikopo, po o le sui o lē e tausia le faleteuoloa o le Alii, po o ia o lē ua tofia o se tausimea faaletino."},{"verse":12,"text":"O ia o lē ua tofia e faatautaia mea faaleagaga, o ia lava lea ua agavaa mo lona totogi, e pei lava o i latou o e e tofia o ni tausimea efaatautaia mea faaletino;"},{"verse":13,"text":"Ioe, e sili atu lava ona tele, o lea tele e faatele atu ia te i latou e ala i faaaliga a le Agaga."},{"verse":14,"text":"Ae ui i lea, ia outou tutusa ia outou mea faaletino, ma o lenei mea ia faia ma le lē lototoa’i, a lē o lea o le a taofia le tele o faaaliga a le Agaga."},{"verse":15,"text":"O lenei, Ou te tuu atu lenei poloaiga i a’u auauna mo lo latou lelei a’o latou soifua, mo se faaaliga o a’u faamanuiaga i luga o o latou ulu, ma mo se taui o lo latou filiga ma mo lo latou saogalemu;"},{"verse":16,"text":"Mo meaai ma mo lavalava; mo se tofi; mo fale ma mo fanua, i soo se tulaga lava e tuu i ai i latou e A’u, o le Alii, ma soo se mea lava e auina atu i ai i latou e A’u, o le Alii."},{"verse":17,"text":"Aua sa latou faamaoni i mea e tele, ma lelei ona latou faia e tusa ai ma lo latou lē agasala."},{"verse":18,"text":"Faauta, o A’u, o le Alii, Ou te alofa mutimutivale ma o le a Ou faamanuia ia te i latou, ma o le a latou ulu atu i le olioli o ia mea. E faapea lava. Amene."}]},{"chapter":71,"verses":[{"verse":1,"text":"Faauta, ua faapea ona fetalai mai o le Alii ia te oulua, a’u auauna, o Iosefa Samita, Le Itiiti, ma Sini Rikitone, ua oo moni mai lava le taimi ua tatau ma ao ai ia te a’u ona tatala atu o oulua fofoga i le folafolaina atu o la’u talalelei, o mea o le malo, ma faamalamalama atu ona mealilo mai totonu o tusitusiga paia, e tusa ai ma lena vaega o le Agaga ma le mana o le a tuu atu ia te oulua, e pei lava ona Ou loto i ai."},{"verse":2,"text":"E moni Ou te fai atu ia te oulua, folafola atu i le lalolagi i nofoaga o faataamilo ai, ma i le ekalesia foi, mo le va o se vaitau, seia oo ina faailoa atu ia te oulua."},{"verse":3,"text":"E moni o se misiona lenei mo se vaitau, lea ua Ou tuu atu ia te oulua."},{"verse":4,"text":"O le mea lea, ia oulua galulue i lo’u tovine. Valaau atu i e o nonofo i le lalolagi, ma molimau atu, ma saunia le ala mo poloaiga ma faaaliga o le a oo mai."},{"verse":5,"text":"O lenei, faauta o le poto lenei; ai se e faitau, ia tuu atu ia te ia ia malamalama i ai ma taliaina foi;"},{"verse":6,"text":"Aua o ia o lē e taliaina o le a tuu tele atu i ai, le mana lava."},{"verse":7,"text":"O le mea lea, faafememeai o oulua fili; valaau atu ia te i latou ia latou feiloa’i ma oulua i nofoaga faitele po o nofoaga patino; ma e tusa ai ma lo oulua faamaoni, o le a faaalia lo latou maasiasi."},{"verse":8,"text":"O le mea lea, tuu atu ia te i latou e aumai o latou manatu malolosi e faasaga i le Alii."},{"verse":9,"text":"E moni, ua faapea ona fetalai mai o le Alii ia te oulua—e leai se ’auupega ua faia e faasaga ia te oulua e manumalo;"},{"verse":10,"text":"Ma afai e i ai soo se tagata e siitia a’e lona leo e faasaga mai ia te oulua o le a faafememeaiina o ia i lo’u lava taimi e tatau ai."},{"verse":11,"text":"O le mea lea, ia tausi i a’u poloaiga; ua moni ma faamaoni i latou. Ua faapea lava. Amene."}]},{"chapter":72,"verses":[{"verse":1,"text":"Faalogo mai ia, ma lagona le siufofoga o le Alii, E, outou e o e ua faapotopoto faatasi outou lava, o e o faitaulaga sili o la’u ekalesia, o e ua tuuina atu i ai le malo ma le mana."},{"verse":2,"text":"Aua e moni ua faapea ona fetalai mai o le Alii, ua tatau ia te a’u ona tofia se epikopo mo outou, pe mai ia te outou, mo le ekalesia i lenei vaega o le tovine o le Alii."},{"verse":3,"text":"Ma e moni ua poto ona outou faia i lenei mea, ona ua faatulafonoina e le Alii, mai lima o tausimea taitoatasi, ia tuu atu se tala o lana mea-tausi, i le olaga nei ma i le faavavau."},{"verse":4,"text":"Aua o ia o lē e faamaoni ma atamai i le olaga nei e faitau agavaa e mautofi i maota ua saunia mo ia e lo’u Tamā."},{"verse":5,"text":"E moni Ou te fai atu ia te outou, ia tuu atu e toeaina o le ekalesia o loo i lenei vaega o lo’u tovine se tala o la latou mea-tausi i le epikopo, o lē o le a Ou tofia i le vaega lenei o lo’u tovine."},{"verse":6,"text":"O nei mea ia tuu i talafaamaumau, e tuu atu i le epikopo i Siona."},{"verse":7,"text":"Ma o le tiute o le epikopo o le a faailoa atu i poloaiga ua uma ona tuu atu ma le leo o le konafesi."},{"verse":8,"text":"Ma o lenei, e moni Ou te fai atu ia te outou, o la’u auauna o Newel K. Whitney o le tagata lea ia tofia ma faauuina i lenei valaauga. O le finagalo lea o le Alii lo outou Atua, lo outou Togiola. Ia faapea lava. Amene."},{"verse":9,"text":"O le afioga a le Alii, e faaopoopo i le tulafono ua uma ona tuuina atu, e faailoa atu ai le tiute o le epikopo o lē ua uma ona faauuina mo le aulotu i le vaega lenei o le tovine, o lenei moni lava—"},{"verse":10,"text":"Ia tausi le faleteuoloa o le Alii; taulimaina tupe a le ekalesia i le vaega lenei o le tovine;"},{"verse":11,"text":"Ia tusia se tala o toeaina e pei ona poloaiina muamua; ma faatautaia mea latou te mananao ai, o e ia latou totogi mo mea latou te maua, e tusa ai ma mea latou te maua e totogi ai;"},{"verse":12,"text":"Ina ia mafai foi ona faapaiaina o lenei mea mo le lelei o le ekalesia, mo e ua matitiva ma e ua lē tagolima."},{"verse":13,"text":"Ma o ia o lē ua lē i ai se mea na te totogi ai, ia faia se tala ma tuulima atu i le epikopo o Siona, o lē o le a totogiina le aitalafu mai mea o le a tuu atu e le Alii i ona lima."},{"verse":14,"text":"Ma o galuega a e faamaoni o e e galulue i mea faaleagaga, i le taulimaina o le talalelei ma mea o le malo mo le ekalesia, ma i le lalolagi, o le a totogi a’i le aitalafu i le epikopo i Siona;"},{"verse":15,"text":"O lea o le totogi o le aitalafu e sau mai le ekalesia, ona e tusa ma le tulafono, o tagata taitoatasi uma o e e o mai i Siona, e ao ina latou fofola atu mea uma i luma o le epikopo i Siona."},{"verse":16,"text":"Ma o lenei, e moni Ou te fai atu ia te outou, aua e tatau i toeaina taitoatasi i lenei vaega o le tovine ona tuu atu se tala o lana mea-tausi i le epikopo i le vaega lenei o le tovine—"},{"verse":17,"text":"O se tusi faamaonia mai le faamasino po o le epikopo i le vaega lenei o le tovine, i le epikopo i Siona, e faia ia talia ai tagata taitoatasi, ma tali ai mea uma, mo se tofi, ma talia ai o ia o se tausimea poto ma se tagata faigaluega faamaoni;"},{"verse":18,"text":"A lē o lea o le a lē talia o ia e le epikopo o Siona."},{"verse":19,"text":"Ma o lenei, e moni Ou te fai atu ia te outou, ia tuu atu i toeaina taitoatasi o e o le a tuu atu se tala i le epikopo o le aulotu i le vaega lenei o le tovine, ia faamaonia atu e le aulotu po o aulotu, o loo galue ai o ia, ina ia mafai ona ia faamaonia o ia lava ma ana tala i mea uma."},{"verse":20,"text":"O lenei foi, ia tuu atu i a’u auauna o e ua tofia o ni tausimea i mea tau tusi o la’u ekalesia, ia latou maua le aiā mo se fesoasoani mai le epikopo po o epikopo, i mea uma—"},{"verse":21,"text":"Ina ia mafai ona lomia o faaaliga, ma o atu i tuluiga o le lalolagi; ina ia mafai foi ona latou maua o tupe o le a manuia ai le ekalesia i mea uma;"},{"verse":22,"text":"Ina ia mafai ai foi ona latou faamaonia i latou lava i mea uma, ma faitauina o ni tausimea popoto."},{"verse":23,"text":"Ma o lenei, faauta, o le a avea lenei mea o se faataitaiga mo paranesi salalau uma o la’u ekalesia, i soo se laueleele lava o le a faatutuina ai i latou. Ma o lenei Ou te faaiu a’u upu. Amene."},{"verse":24,"text":"O ni upu itiiti e faaopoopo i tulafono o le malo, e faatatau i tagata o le ekalesia—i latou ia e tofia i le Agaga Paia e o a’e i Siona, ma i latou o e ua maua le avanoa e o atu ai i Siona—"},{"verse":25,"text":"Ia tuu atu ia te i latou e o ma ave i le epikopo se tusi faamaonia mai ni toeaina se toatolu o le ekalesia, po o se tusi faamaonia mai le epikopo;"},{"verse":26,"text":"A lē o lea, o ia o lē e alu a’e i le laueleele o Siona o le a lē faitauina o se tausimea poto. O se faataitaiga foi lenei. Amene."}]},{"chapter":73,"verses":[{"verse":1,"text":"Aua e moni, ua faapea ona fetalai mai o le Alii, ua tatau ia te a’u ona latou talai atu pea o le talalelei, ma i le apoapoai atu i aulotu i nofoaga o faataamilo ai, sei oo i le konafesi;"},{"verse":2,"text":"Ma ona, faauta lea, o le a faailoa atu ia te i latou, i le leo o le konafesi, a latou misiona eseese."},{"verse":3,"text":"O lenei, e moni Ou te fai atu ia te oulua a’u auauna, o Iosefa Samita, Le Itiiti, ma Sini Rikitone, ua fetalai mai le Alii, ua tatau ona toe faaliliu;"},{"verse":4,"text":"Ma, e tusa ai ma le mafai, ia talai atu i nofoaga o faataamilo ai sei oo i le konafesi; ma a mavae lena ona tatau lea ona faaauau o le galuega o le faaliliuga seia mae’a."},{"verse":5,"text":"Ma ia tuu lenei mea e avea ma faataitaiga i toeaina seia maua se malamalama atili, e pei lava ona tusia."},{"verse":6,"text":"O lenei Ou te lē tuuina atu ni isi mea ia te outou i le taimi nei. Ia fusi i o outou sulugatiti ma faamamalu. Ua faapea lava. Amene."}]},{"chapter":74,"verses":[{"verse":1,"text":"Auā o le tane lē talitonu e faapaiaina i le avā, ma o le avā lē talitonu e faapaiaina i le tane; a na lē o lea po ua lē mamā a outou fanau, a’o lenei ua paia i latou."},{"verse":2,"text":"O lenei, i aso o aposetolo sa i ai le tulafono o le peritomeina i totonu o tagata Iutaia uma o e sa lē talitonu i le talalelei a Iesu Keriso."},{"verse":3,"text":"Ma sa oo ina tula’i mai se finauga tele i totonu o tagata e uiga i le tulafono o le peritomeina, ona sa manao le tane lē talitonu ia peritomeina lana fanau ma pulea i lalo o le tulafono a Mose, o se tulafono ua faataunuuina."},{"verse":4,"text":"Ma sa oo ina o fanau, sa tausi a’e i latou i lalo o le tulafono a Mose, sa gaua’i atu i tu masani a o latou tamā ma lē talitonu ai i le talalelei a Iesu Keriso, lea na lē paia ai i latou."},{"verse":5,"text":"O le mea lea, o le pogai lenei na tusi atu ai le aposetolo i le ekalesia, ma tuu atu ia te i latou se poloaiga, e lē mai le Alii, ae mai ia te ia lava, e faapea e lē tatau i se ua talitonu ona faatasia ma se ua lē talitonu; vaganā ai ua aveese le tulafono a Mose mai ia te i la’ua,"},{"verse":6,"text":"Ina ia mafai ona tumau pea a la’ua fanau e aunoa ma le peritomeina; ma ina ia mafai ona aveesea le tu, lea ua fai mai e faapea ua lē paia fanau laiti; ona sa i ai lea tu i totonu o tagata Iutaia;"},{"verse":7,"text":"Peitai ua paia fanau laiti, ona ua faapaiaina i latou e ala i le togiola a Iesu Keriso; ma o le uiga lea o tusitusiga paia."}]},{"chapter":75,"verses":[{"verse":1,"text":"E Moni, e moni, Ou te fai atu ia te outou, o A’u o lē o tautala atu e ala lava i le leo o lo’u Agaga, o le Alefa ma le Omeka lava lea, lo outou Alii ma lo outou Atua—"},{"verse":2,"text":"Faalogo mai ia, E outou e o ē ua tuuina mai o outou igoa tou te o atu e tala’i atu la’u talalelei, ma teu lo’u tovine."},{"verse":3,"text":"Faauta, Ou te fai atu ia te outou, o lo’u loto e tatau ona outou o atu ma aua le faatuai, pe faapaie, ae galulue ma lo outou malosi—"},{"verse":4,"text":"Ma siitia a’e i luga o outou leo e pei o le leo o se pu, ma tala’i atu le upumoni e tusa ma faaaliga ma poloaiga ua Ou tuuina atu ia te outou."},{"verse":5,"text":"Ma o lea, afai tou te faamaoni, o le a faaee ia outou fusisaito e tele, ma faapaleina i le viiga, ma le mamalu, ma le tino ola pea, ma le ola e faavavau."},{"verse":6,"text":"O lea, e moni Ou te fai atu i la’u auauna o Viliamu E. McLellin, ua Ou toesea le tofiga na Ou tuu atu ia te ia e alu i itu-laueleele i sasa’e;"},{"verse":7,"text":"Ma Ou te tuu atu ia te ia se tofiga fou ma se poloaiga fou, lea ua a’oa’i ai o ia e A’u, o le Alii, ona o muimuiga o lona loto;"},{"verse":8,"text":"Ma sa agasala o ia; ae ui i lea, Ou te faamagalo atu ia te ia ma toe fai atu ia te ia, Ia e alu i laueleele i saute."},{"verse":9,"text":"Ma tuu atu i la’u auauna o Luka Johnson e o faatasi ma ia, ma folafola atu mea ua Ou poloaiina ai i la’ua—"},{"verse":10,"text":"Ma valaau atu i le suafa o le Alii mo le Fesoasoani, lea o le a a’oa’o atu i la’ua i mea uma e tatau ai mo i la’ua—"},{"verse":11,"text":"Ma tatalo e lē aunoa ina ia la’ua lē vaivai; ma e tusa ai ma lo la faia o lenei mea, o le a Ou faatasi ma i la’ua e oo lava i le iuga."},{"verse":12,"text":"Faauta, o le finagalo lenei o le Alii lo oulua Atua e faatatau ia te oulua. Ua faapea lava. Amene."},{"verse":13,"text":"O lenei foi, e moni ua faapea ona fetalai mai o le Alii, ia tuu atu i la’u auauna o Orson Hyde ma la’u auauna o Samuel H. Samita, e alu la la’ua malaga i laueleele i sasa’e, ma folafola atu mea ua Ou poloaiina ai i la’ua; ma e tusa ai ma lo la’ua faamaoni, faauta, o le a Ou faatasi ma i la’ua e oo lava i le iuga."},{"verse":14,"text":"O lenei foi, e moni Ou te fai atu i la’u auauna o Lyman Johnson, ma i la’u auauna o Orson Pratt, ia alu foi la la’ua malaga i laueleele i sasa’e; ma faauta, ma tagai, ua Ou faatasi foi ma i la’ua, e oo lava i le iuga."},{"verse":15,"text":"O lenei foi, Ou te fai atu i la’u auauna o Asa Dodds, ma i la’u auauna o Calves Wilson, ia alu foi la la’ua malaga i laueleele i sisifo, ma folafola atu la’u talalelei, e pei lava ona Ou poloaiina ai i la’ua."},{"verse":16,"text":"Ma o ia o lē e faamaoni o le a manumalo i mea uma, ma o le a siitia a’e i luga i le aso gataaga."},{"verse":17,"text":"O lenei foi, Ou te fai atu i la’u auauna o Major N. Ashley, ma la’u auauna o Burr Riggs, ia tuu atu ia te i la’ua e alu foi la la’ua malaga i laueleele i saute."},{"verse":18,"text":"Ioe, ia tuu atu ia te i latou uma na, e o a latou malaga, e pei ona Ou poloaiina ai i latou, ma o atu mai lea fale i lea fale, ma mai lea nuu i lea nuu, ma mai lea aai i lea aai."},{"verse":19,"text":"Ma i soo se fale tou te ulu atu i ai, ma latou talia outou, ia tuu atu la outou faamanuiaga i luga o lena fale."},{"verse":20,"text":"Ma i soo se fale tou te ulu atu i ai, ma latou lē talia outou, ia faataalise ona outou o ese mai lena fale, ma tūtū ese le efuefu o o outou vae o se molimau e faasaga ia te i latou."},{"verse":21,"text":"Ma o le a faatutumulia outou i le olioli ma le fiafia; ma ia outou iloa le mea lenei, i le aso o le faamasinoga, o le a avea outou ma faamasino o lena fale, ma ta’usalaina i latou;"},{"verse":22,"text":"Ma o le a sili ona gafatiaina e tagata faapaupau i le aso o le faamasinoga, nai lo lena fale; o lea, ia fusi o outou sulugatiti ma faamaoni, ma o le a outou manumalo i mea uma, ma siitia a’e i luga i le aso gataaga. E faapea lava. Amene."},{"verse":23,"text":"O lenei foi, ua faapea ona fetalai mai o le Alii ia te outou, Eoutou e toeaina o la’u ekalesia, o e ua tuuina mai o outou igoa ina ia outou iloa lona finagalo e faatatau ia te outou—"},{"verse":24,"text":"Faauta, Ou te fai atu ia te outou, o le tiute o le ekalesia le fesoasoani i le tausiga o aiga o i latou na, ma le tausia foi o aiga o i latou o e ua valaaulia ma tatau ona auina atu i le lalolagi e folafola atu le talalelei i le lalolagi."},{"verse":25,"text":"O le mea lea, o A’u, o le Alii, Ou te tuu atu ia te outou le poloaiga lenei, ia outou maua ni nofoaga mo o outou aiga, e tusa ai ma le malilie o outou uso e tatala o latou loto."},{"verse":26,"text":"Ma ia tuu atu ia te i latou uma faapena o e e mafai ona maua ni nofoaga mo o latou aiga, ma le lagolago a le ekalesia mo i latou, ia aua ne’i lē o atu i le lalolagi, pe i sasa’e po o sisifo, po o matu, po o saute."},{"verse":27,"text":"Ia tuu atu ia te i latou e ole mai ma o le a latou maua, tu’itu’i mai ma o le a tatala atu ia te i latou, ma faailoa atu mai lugā, e le Fesoasoani lava, le mea latou te o i ai."},{"verse":28,"text":"O lenei foi, e moni Ou te fai atu ia te outou, o alii taitoatasi ua ia te ia le tiute e fai mea mo lona lava aiga, ia tuu atu ia te ia e fai, ma o le a leai se ala o le a lē maua ai e ia lona pale; ma ia tuu atu ia te ia e galue i le ekalesia."},{"verse":29,"text":"Tuu atu i tagata taitoatasi ia filigā i mea uma. Ma o lē e paiē o le a leai sona tulaga i le ekalesia, vaganā ai ua salamo o ia ma suia ona ala."},{"verse":30,"text":"O le mea lea, ia tuu atu i la’u auauna o Simeon Carter ma la’u auauna o Emer Harisi ia faatasia i le galuega;"},{"verse":31,"text":"Ma la’u auauna foi o Ezra Thayre ma la’u auauna o Thomas B. Marsh;"},{"verse":32,"text":"Ma la’u auauna foi o Ailama Samita ma la’u auauna o Reynolds Cahoon;"},{"verse":33,"text":"Ma la’u auauna foi o Daniel Stanton ma la’u auauna o Seymour Brunson;"},{"verse":34,"text":"Ma la’u auauna foi o Sylvester Samita ma la’u auauna o Kitiona Kata;"},{"verse":35,"text":"Ma la’u auauna foi o Ruggles Eames ma la’u auauna o Stephen Burnett;"},{"verse":36,"text":"Ma la’u auauna foi o Micah B. Welton ma la’u auauna foi o Eden Samita. Ia faapea lava. Amene."}]},{"chapter":76,"verses":[{"verse":1,"text":"Faalogo maia, E outou le lagi e, ma ua’i mai taliga, E le lalolagi e, ma olioli outou o e ua aumau ai, ona o le Alii o le Atua, ma e ese mai ai o ia ua leai se Faaola."},{"verse":2,"text":"Ua tele lava lona poto, ua ofoofogia lava ona ala, ma o le lautele o ana mea e fai e leai sē e mafai ona iloaina."},{"verse":3,"text":"E lē mafai ona i’uvale ona faamoemoe, pe i ai se tasi e mafai ona taofia lona aao."},{"verse":4,"text":"Ua tutusa o ia mai le faavavau i le faavavau, ma e lē i’u lava ona tausaga."},{"verse":5,"text":"Auā ua faapea ona fetalai mai o le Alii—o A’u, o le Alii, ou te alofa mutimutivale ma agalelei ia te i latou o e e matata’u mai ia te a’u, ma fiafia e faamamalu i latou o e e auauna mai ia te a’u i le amiotonu ma le upumoni e oo i le iuga."},{"verse":6,"text":"O le a tele lava lo latou taui ma o le a faavavau lo latou mamalu."},{"verse":7,"text":"Ma o i latou o le a Ou faaali atu i ai mealilo uma, ioe, mealilo natia uma o lo’u malo mai aso anamua, ma tausaga e oo mai, o le a Ou faailoa atu ia te i latou le fiafia lelei o lo’u loto e uiga i mea uma e faatatau i lo’u malo."},{"verse":8,"text":"Ioe, e oo i mea ofoofogia o le faavavau o le a latou iloa, ma o mea o le a oo mai o le a Ou faaali atu ia te i latou, o mea lava ia o tupulaga e tele."},{"verse":9,"text":"Ma o le a tele lava lo latou poto, ma tau i le lagi lo latou malamalama; ma o le a fano i o latou luma le poto o e e atamamai, ma o le malamalama o e e faautauta o le a avea ma meanoa."},{"verse":10,"text":"Auā o lo’u Agaga o le a Ou faamalamalamaina ai i latou, ma o lo’u mana o le a Ou faailoa atu ai ia te i latou mealilo o lo’u loto—ioe, e oo lava i mea e lei vaaia e mata, pe ua faalogoina e taliga, pe ua ulu ifo i totonu o le loto o le tagata."},{"verse":11,"text":"O ma’ua, o Iosefa Samita, Le Itiiti, ma Sini Rikitone, ina o ma i ai i le Agaga i le aso sefulu ono o Fepuari, i le tausaga o lo tatou Alii e tasi le afe valu selau ma le tolusefulu-lua—"},{"verse":12,"text":"Sa tatalaina o ma’ua mata ma faapupulaina o ma’ua malamalamaaga e le mana o le Agaga, ina ia mafai ona vaai ma malamalama i mea a le Atua—"},{"verse":13,"text":"O mea lava ia sa mai i le amataga ae le’i i ai le lalolagi, o mea sa faauuina e le Tamā, e ala i lona Atalii Pele e Toatasi, o lē sa i le finagalo o le Tamā, mai lava i le amataga;"},{"verse":14,"text":"O lē ma te molimau atu ai; ma o le mau ma te molimau atu o le atoatoaga lea o le talalelei a Iesu Keriso, o lē o le Alo, o lē na ma vaai i ai ma lē na matou fetautalatalaa’i i le faaaliga vaaia faalelagi."},{"verse":15,"text":"Auā a’o ma faia le galuega o le faaliliuga, lea na tofia mai e le Alii ia te i ma’ua, sa ma oo mai i le fuaiupu luasefulu-iva o le mataupu e lima o le Ioane, lea sa tuuina mai ia te i ma’ua e faapea—"},{"verse":16,"text":"O loo tautala e uiga i le toetutu mai o e ua oti, e faatatau ia te i latou o e o le a faalogo i le siufofoga o le Atalii o le Tagata:"},{"verse":17,"text":"Ma o le a tutula’i mai; o i latou o e na faia mea lelei, i le toetutu mai o e amiotonu; ma o i latou o e na faia mea leaga, i le toetutu mai o e amioletonu."},{"verse":18,"text":"O lenei mea na oo mai ai ia te i ma’ua le ofo, auā sa tuuina mai ia te i ma’ua e le Agaga."},{"verse":19,"text":"Ma a’o ma manatunatu loloto i nei mea, sa pa’i mai le Alii i mata o o ma’ua malamalamaaga ma sa tatalaina, ma sa susulu faataamilo mai le mamalu o le Alii."},{"verse":20,"text":"Ma sa ma vaaia le mamalu o le Alo, i le aao taumatau o le Tamā, ma sa maua lona atoatoa;"},{"verse":21,"text":"Ma sa ma vaai I agelu paia, ma I latou o e ua faapaiaina I luma o lona nofoaalii, o loo tapuai atu I le Atua, ma le Tamai Mamoe, o e ua tapuai atu ia te ia e faavavau, faavavau lava."},{"verse":22,"text":"Ma o lenei, ina ua mavae le tele o molimau ua tuuina mai e uiga ia te ia, o le molimau mulimuli lenei, I molimau uma, ma te tuu atu e uiga ia te ia: O loo soifua o ia!"},{"verse":23,"text":"Auā sa ma vaai ia te ia, I le lima taumatau lava o le Atua; ma sa ma faalogo I le leo o molimau mai o ia o le Toatasi na Fanaua e le Tamā—"},{"verse":24,"text":"E faapea e mai ia te ia, ma ala mai ia te ia, ma o ia, ua I ai lalolagi ma na foafoaina, ma o e ua nonofo ai o atalii ma afafine fanauina I le Atua."},{"verse":25,"text":"Ma sa ma vaai foi I le mea lenei, ma molimau ai, e I ai se agelu a le Atua o lē sa I le pule I luma o le Atua, o lē sa fouvale I le Atalii Pele e Toatasi o lē sa pele I le Tamā ma o lē sa I le finagalo o le Tamā, sa lafo ifo I lalo mai luma o le Atua ma le Alo,"},{"verse":26,"text":"Ma sa ta’ua o le Malaia, aua sa tutulu le lagi ona o ia—o ia o Lusifelo, o se atalii o le taeao."},{"verse":27,"text":"Ma sa ma vaaia, ma faauta, ua pa’ū o ia! Ua pa’ū, o se atalii lava o le taeao!"},{"verse":28,"text":"Ma a’o ma I ai pea I le Agaga, sa poloaiina I ma’ua e le Alii e tatau ona ma tusi le faaaliga vaaia; auā na ma vaaia Satani, le gata tuai lena, le tiapolo lava, o lē na fouvale faasaga I le Atua, ma saili e aveese le malo o lo tatou Atua ma lana Keriso—"},{"verse":29,"text":"O le mea lea, ua sii taua ai o ia i le au paia a le Atua, ma si’o faataamilo i latou."},{"verse":30,"text":"Ma sa ma vaai I se faaaliga vaaia I mafatiaga o I latou o e na sii taua I ai o ia ma faatoilaloina, auā sa faapea ona oo mai o le siufofoga o le Alii ia te I ma’ua:"},{"verse":31,"text":"Ua faapea ona fetalai mai o le Alii e faatatau ia te I latou uma o e ua latou iloa lo’u mana, ma sa faia ia latou mauaina, ma ua latou tuu I latou lava ia faatoilaloina e ala I le mana o le tiapolo, ma faafitia le upumoni ma tetee I lo’u mana—"},{"verse":32,"text":"O I latou ia o I latou o e o atalii o le malaia, o e Ou te fai atu ai sa sili atu mo I latou pe a na lē fananau mai;"},{"verse":33,"text":"Auā o I latou o ni ipu o le toasa, ua tuu-malaia e mafatia I le toasa o le Atua, faatasi ma le tiapolo ma ana agelu I le faavavau;"},{"verse":34,"text":"E faatatau lea I e na Ou fai atu ai ua leai se faamagalogaina I le lalolagi lenei po o le lalolagi a sau—"},{"verse":35,"text":"Ona ua latou faafitia le Agaga Paia ina ua uma ona latou mauaina, ma ona ua latou faafitia le Atalii Pele e Toatasi o le Tamā, ona ua latou faasatauroina o ia ia te I latou lava ma tuu o ia e faamaasiasia I luma o tagata."},{"verse":36,"text":"O I latou ia o e o le a o ese atu I le lepa afi ma le teiō, faatasi ma le tiapolo ma ana agelu—"},{"verse":37,"text":"Ma na’o I latou ia o e o le a oo I ai I luga le mana o le oti faalua;"},{"verse":38,"text":"Ioe, e moni, na’o I latou lava ia o e o le a lē togiolaina I le taimi tatau ai a le Alii, pe a mavae mafatiaga o lona toasa."},{"verse":39,"text":"Auā o I latou uma e totoe o le a faatutula’I mai I le toetutū mai o e ua oti, e ala I le manumalo ma le mamalu o le Tamai Mamoe, o lē na fasia, o lē na I ai I le loto o le Tamā ae lei faia lalolagi."},{"verse":40,"text":"Ma o le talalelei lenei, o tala fiafia ia, na molimau mai e le siufofoga mai le lagi ia te i ma’ua—"},{"verse":41,"text":"E faapea na afio mai o ia I le lalolagi, o Iesu lava, e faasatauroina mo le lalolagi, ma tauave agasala a le lalolagi, ma faapaia le lalolagi, ma faamamā mai amioletonu uma;"},{"verse":42,"text":"Ina ia mafai ona faaolaina e ala ia te ia i latou uma o e na tuu e le Tamā i lona mana ma faia e ia;"},{"verse":43,"text":"O lē ua faamamaluina le Tamā, ma laveai galuega uma a ona aao, vaganā ai atalii na o le malaia o e ua faafitia le Alo ina ua uma ona faaali mai o ia e le Tamā."},{"verse":44,"text":"O le mea lea, e laveai e ia tagata uma vaganā ai I latou na—o le a latou o ese atu I le faasalaga tumau e faavavau, o le faasalaga lea e lē gata, o le faasalaga faavavau lea, e pule faatasi ma le tiapolo ma ana agelu I le faavavau, I le mea e lē mamate ai o latou īlo, ma lē mate ai le afi, o lo latou mafatiaga lea—"},{"verse":45,"text":"Ma o lona iuga, po o lona nofoaga, po o lo latou mafatiaga, e leai se tagata na te iloaina;"},{"verse":46,"text":"Pe na faaali mai, pe ua faaali mai, pe o le a faaalia mai I tagata, vaganā ai ia te I latou o e o le a fai mo I latou;"},{"verse":47,"text":"Ae ui I lea, o A’u, o le Alii, Ou te faaalia atu I le toatele I se faaaliga vaaia, ae vave ona toe tapunia;"},{"verse":48,"text":"O le mea lea, o le i’uga, o le lautele, o le maualuga, o le loloto, ma lona pagatia, latou te lē malamalama I ai, po o soo se tagata foi vaganā ai I latou o e ua faauuina mo lenei ta’usalaga."},{"verse":49,"text":"Ma sa ma faalogoina le siufofoga, ua fetalai mai: Ia tusi le faaaliga vaaia, auā faauta, o lei’uga lenei o le faaaliga vaaia e uiga I mafatiaga o e e lē amioatua."},{"verse":50,"text":"O lenei foi ma te molimau atu—ona sa ma vaai ma faalogoina, ma o le molimau lenei o le talalelei a Keriso e faatatau ia te I latou o e o le a tutula’I mai I le toetutu mai o e amiotonu—"},{"verse":51,"text":"O I latou ia o e na taliaina le molimau ia Iesu, ma talitonu I lona suafa ma papatiso e tusa ma le ala o lona tanuga, I le tanumia lea I totonu o le vai I lona suafa, ma e tusa lenei ma le poloaiga na tuuina mai e ia—"},{"verse":52,"text":"Ina ia mafai, e ala I le tausia o poloaiga, ona fufuluina ma faamamāina I latou mai ia latou agasala uma, ma maua le Agaga Paia e ala I le faaee atu o lima o ia o lē ua faauuina ma faamauina I lenei mana;"},{"verse":53,"text":"Ma e e manumalo e ala I le faatuatua, ma ua faamauina e le Agaga Paia o le folafolaga, lea e liligi mai e le Tamā I luga o I latou uma o e amiotonu ma faamaoni."},{"verse":54,"text":"O I latou ia o e o le ekalesia a le Ulumatua."},{"verse":55,"text":"O i latou ia ua tuuina atu i ai e le Tamā mea uma i o latou lima—"},{"verse":56,"text":"O i latou ia o e o faitaulaga ma tupu, o e ua mauaina lona atoatoa, ma lona mamalu;"},{"verse":57,"text":"Ma o faitaulaga a le Silisili Ese, e tusa ma le faatulagaga a Mekisateko, lea sa tusa ma le faatulagaga a Enoka, lea sa tusa ma le faatulagaga a le Atalii Pele e Toatasi."},{"verse":58,"text":"O le mea lea, e pei ona tusia, o i latou o ni atua, o atalii lava o le Atua—"},{"verse":59,"text":"O le mea lea, o mea uma e a I latou, pe o le ola po o le oti, po o mea o I ai nei, po o mea o le a oo mai, o mea uma e a I latou, ma o I latou e a Keriso, ma o Keriso e a le Atua."},{"verse":60,"text":"Ma o le a latou manumalo I mea uma."},{"verse":61,"text":"O le mea lea, ia lē tuu ai I se tagata e vivii ona o le tagata, ae ia tuu atu ia te ia e vivii ona o le Atua, o lē o le a faatoilaloina fili uma I lalo o ona aao."},{"verse":62,"text":"O I latou ia o le a nonofo I luma o le Atua ma lana Keriso e faavavau faavavau lava."},{"verse":63,"text":"O I latou ia o e o le a ia aumai faatasi ma ia, pe a afio mai o ia I ao o le lagi e nofotupu I le lalolagi I luga o lona nuu."},{"verse":64,"text":"O i latou ia o e o le a mauaina se vaega i le uluai toetutu."},{"verse":65,"text":"O I latou ia o e o le a tutula’I mai I le toetutu mai o e amiotonu."},{"verse":66,"text":"O I latou ia o e e o mai I le Mauga o Siona, ma I le aai o le Atua soifua, le nofoaga faalelagi, e sili ona paia I aai uma."},{"verse":67,"text":"O I latou ia o e na o mai I se ’au o agelu e lē mafaitaulia, I le faapotopotoga ma le ekalesia aoao a Enoka, ma a le Ulumatua."},{"verse":68,"text":"O I latou ia o e o o latou igoa ua tusia I le lagi, I le mea o afifio ai le Atua ma Keriso o le faamasino o tagata uma."},{"verse":69,"text":"O I latou ia o e o tagata amiotonu ua faaatoatoaina e ala ia Iesu le puluvaga o le feagaiga fou, o lē na faia lenei togiola ua atoatoa e ala I le faamaligiina o lona lava toto."},{"verse":70,"text":"O I latou ia o e o o latou tino ua selesitila, o e o lo latou mamalu o lena o le la, le mamalu lava lea o le Atua, le silisili I tagata uma, o lē o lona mamalu ua tusia e faapea ua faatusa I le la o le vanimonimo."},{"verse":71,"text":"O lenei foi, sa ma vaai I le lalolagi terasitila, ma faauta ma tagai, o I latou ia o e ua o le terasitila, o e o lo latou mamalu ua ese mai le mamalu o le ekalesia a le Ulumatua o e ua mauaina le atoatoa o le Tamā, e pei lava ona ese le mamalu o le masina mai le la I le vanimonimo."},{"verse":72,"text":"Faauta, o i latou ia o e na oti e aunoa ma le tulafono;"},{"verse":73,"text":"Ma o I latou foi o e o agaga o tagata sa taofia I le falepuipui, o e na asia e le Alo, ma tala’I atu le talalelei ia te I latou, ina ia mafai ona faamasinoina I latou e tusa ma tagata I la le tino;"},{"verse":74,"text":"O e sa lē taliaina le molimau ia Iesu i la le tino, ae mulimuli ane taliaina."},{"verse":75,"text":"O I latou ia o tagata mamalu o le lalolagi, o e na faatauasoina I le faitogafiti o tagata."},{"verse":76,"text":"O I latou ia o e e maua I lona mamalu, ae lē o lona atoatoa."},{"verse":77,"text":"O I latou ia o e e mauaina mamalu o le Alo, ae lē o le atoatoa o le Tamā."},{"verse":78,"text":"O le mea lea, o i latou o ni tagata tino terasitila, ae lē o ni tagata tino selesitila, ma e ese i le mamalu e pei ona ese le masina mai le la."},{"verse":79,"text":"O I latou ia o e sa le’I totoa I le molimau ia Iesu; o le mea lea, latou te lē maua ai le pale I luga o le malo o lo tatou Atua."},{"verse":80,"text":"Ma o lenei, o le faaiuga lenei o le faaaliga vaaia o le terasitila na ma vaai I ai, lea na poloaiina I ma’ua e le Alii e tusi a’o ma’ua I ai pea I le Agaga."},{"verse":81,"text":"O lenei foi, sa ma vaai i le mamalu o le telesitila, le mamalu lea o le maualalo, e pei lava ona ese le mamalu o fetu mai le mamalu o le masina i le vanimonimo."},{"verse":82,"text":"O i latou ia o e sa lē taliaina le talalelei a Keriso, po o le molimau ia Iesu."},{"verse":83,"text":"O I latou ia o e ua lē faafitia le Agaga Paia."},{"verse":84,"text":"O I latou ia o e ua lafo I lalo I seoli."},{"verse":85,"text":"O I latou ia o e o le a lē togiolaina mai le tiapolo seia oo mai le toetutu mulimuli, seia mae’a ona faia e le Alii, o Keriso lava le Tamai Mamoe, lana galuega."},{"verse":86,"text":"O I latou ia o e e lē mauaina lona atoatoa I le lalolagi faavavau, ae o le Agaga Paia e ala atu I le auaunaga a le terasitila;"},{"verse":87,"text":"Ma le terasitila e ala i le auaunaga a le selesitila."},{"verse":88,"text":"Ma e maua foi e le telesitila mai asiasiga a agelu o e ua tofia e auauna mo I latou, po o e ua tofia e avea ma agaga auauna mo I latou; ona o le a avea I latou ma suli o le faaolataga."},{"verse":89,"text":"Ma sa faapea ona ma vaai, i le faaaliga vaaia faalelagi, i le mamalu o le telesitila, lea ua sili mamao atu i malamalamaaga uma;"},{"verse":90,"text":"Ma e leai se tagata ua iloaina vaganā o ia o lē ua faaali i ai e le Atua."},{"verse":91,"text":"Ma sa faapea ona ma vaai i le mamalu o le terasitila lea ua silisili atu i mea uma i le mamalu o le telesitila, i le mamalu lava, ma i le mana, ma i le malosi, ma i le pule’aga."},{"verse":92,"text":"Ma sa faapea ona ma vaai I le mamalu o le selesitila, lea ua silisili atu I mea uma—le mea ua nofotupu ai le Atua, le Tamā lava lea, I luga o lona nofoalii e faavavau faavavau lava;"},{"verse":93,"text":"O lē o luma o lona nofoalii e ifo atu ai mea uma I le faaaloalo lotomaualalo, ma avatu ia te ia le mamalu e faavavau faavavau lava."},{"verse":94,"text":"O I latou o e e nonofo I ona luma o le ekalesia lea a le Ulumatua; ma latou te vaai e pei ona vaaia I latou, ma iloa e pei ona iloa I latou, ona ua latou maua lona atoatoa ma lona alofa tunoa;"},{"verse":95,"text":"Ma na te faia I latou ia tutusa I le mana, ma I le malosi, ma I pule’aga."},{"verse":96,"text":"Ma o le mamalu o le selesitila ua tasi, e pei lava ona tasi le mamalu o le la."},{"verse":97,"text":"Ma o le mamalu o le terasitila ua tasi, e pei lava ona tasi le mamalu o le masina."},{"verse":98,"text":"Ma o le mamalu o le telesitila ua tasi, e pei lava ona tasi le mamalu o fetu; ona e pei ona ese le tasi fetu mai le isi fetu i le mamalu, ua faapea foi ona ese le tasi mai le isi i le mamalu i le lalolagi telesitila;"},{"verse":99,"text":"Ona o i latou ia o e o lo Paulo, ma lo Apolo, ma lo Kefa."},{"verse":100,"text":"O I latou ia o e ua fai mai o I latou o ni isi o le tasi ma ni isi o le isi—o ni isi o Keriso, ma ni isi o Ioane, ma ni isi o Mose, ma ni isi o Elaia, ma ni isi o Esaia, ma ni isi o Isaia, ma ni isi o Enoka;"},{"verse":101,"text":"Ae sa lē taliaina le talalelei, po o le molimau ia Iesu, po o perofeta, po o le feagaiga tumau e faavavau."},{"verse":102,"text":"Mulimuli lava I mea uma, o I latou uma ia o e o le a lē faapotopotoina faatasi ma le au paia, e aveina a’e I luga I le ekalesia a le Ulumatua, ma taliaina I totonu o le ao."},{"verse":103,"text":"O I latou ia o e o pepelo, ma faataulaitu, ma mulilulua, ma faitaaga, ma soo se tasi e fiafia I le pepelo ma fai le pepelo."},{"verse":104,"text":"O I latou ia o e e mafatia I le toasa o le Atua I le lalolagi."},{"verse":105,"text":"O I latou ia o e e mafatia I le tauimasui o le afi e faavavau."},{"verse":106,"text":"O I latou ia o e e lafo I lalo I seoli ma mafatia I le toasa o le Atua Malosi Aoao, seia oo I le atoatoaga o taimi, pe a uma ona faatoilaloina e Keriso fili uma I lalo o ona aao, ma ua uma ona faaatoatoaina e ia lana galuega;"},{"verse":107,"text":"Pe a ava’e e ia le malo, ma tuu atu I le Tamā, ua lē ponā, ma fetalai atu: Ua Ou manumalo ma ua Ou solia toatasi le soliga-vine, le soligavine lava lea o le mata’utia tele o le toasa o le Atua Malosi Aoao."},{"verse":108,"text":"Ona faapaleina ai lea o ia I le pale o lona mamalu, e afio I luga I le nofoalii o lona mana e nofotupu ai e faavavau faavavau lava."},{"verse":109,"text":"Ae faauta, ma tagai, sa ma vaai I le mamalu ma e e nonofo I le lalolagi telesitila, sa pei ona lē mafaitaulia I latou e pei o fetu I le vanimonimo o le lagi, po o le oneone I luga o le matafaga;"},{"verse":110,"text":"Ma sa faalogoina le siufofoga o le Alii ua fetalai mai: O I latou uma nei o le a tootutuli tulivae, ma o le a tautino atu e laulaufaiva uma ia te ia o lē ua afio I luga o le nofoalii e faavavau ma faavavau lava;"},{"verse":111,"text":"Ona o le a faamasinoina i latou e tusa ma a latou galuega, ma o le a maua e tagata taitoatasi e tusa ma ana lava galuega, lana lava pule’aga, i maota ua saunia;"},{"verse":112,"text":"Ma o le a avea I latou ma auauna a le Silisili Ese; ae o le mea e afio ai le Atua ma Keriso, e lē mafai ona latou o atu I ai, o lalolagi e leai se iuga."},{"verse":113,"text":"O le faaiuga lenei o le faaaliga vaaia na ma vaai I ai, lea na poloaiina I ma’ua e tusi a’o ma I ai pea I le Agaga."},{"verse":114,"text":"Ae ua maoa’e lava ma ofoofogia galuega a le Alii, ma mealilo o lona malo na faaali mai e ia ia te I ma’ua, ua silisili mamao atu I malamalamaaga uma I le mamalu, ma I le malosi, ma I le pule’aga;"},{"verse":115,"text":"Ia na ia poloaiina I ma’ua e lē tatau ona ma tusia a’o ma I ai pea I le Agaga, ma ua lē faatagaina mo se tagata ia tautala I ai;"},{"verse":116,"text":"Pe mafai foi e le tagata ona faailoa atu I latou, aua ua na’o le mana lava o le Agaga Paia, lea e faaee e le Atua I luga o I latou o e e alolofa ia te ia, ma faamamā I latou lava I ona luma, e vaaia ma malamalama ai;"},{"verse":117,"text":"Ia i latou e tuu atu i ai e ia lenei avanoa o le vaai ma le iloaina mo i latou lava;"},{"verse":118,"text":"Ina ia mafai ona latou gafatia ona luma I le lalolagi o le mamalu, e ala I le mana ma faaaliga a le Agaga, a’o I ai I la le tino."},{"verse":119,"text":"Ma ia i ai i le Atua ma le Tamai Mamoe le mamalu, ma le viiga, ma le pule’aga e faavavau ma faavavau lava. Amene."}]},{"chapter":77,"verses":[{"verse":1,"text":"F. O le a le sami tioata na tautala I ai Ioane, I le mataupu 4, ma le fuaiupu 6 o le Faaaliga?T. O le lalolagi lea, i lona tulaga faapaiaina, ola pea, ma le faavavau."},{"verse":2,"text":"F. O le a le mea ia tatou malamalama i ai e uiga i manu e fa, ua tautala i ai i lena lava fuaiupu?T. O ni upu faatusa ia, na faaaoga e le Talifaaaliga, o Ioane, I le faamatalaina o le lagi, le parataiso o le Atua, le fiafia o tagata, ma manu, ma mea fetolofi, ma manu felelei o le ’ea; o mea faaleagaga ua foliga I faatusa o mea faaletino; ma o mea faaletino ua foliga I mea faaleagaga; o le agaga o le tagata ua foliga I lona lava tagata, faapea foi le agaga o le manu, ma isi meaola uma ua foafoaina e le Atua."},{"verse":3,"text":"F. Ua faasinotonu ea manu e fa I na’o manu taitasi, pe ua fai I latou ma faatusa o vasega po o ituaiga o manu?T. Ua faasinotonu I latou I manu taitasi, ia na faaalia ia Ioane, e faatusa I ai le mamalu o vasega o meaola I lo latou tulaga faamoemoeina po o le li’o o le foafoaga, I le mauaina o lo latou fiafia e faavavau."},{"verse":4,"text":"F. O le a le mea ia tatou malamalama i ai e uiga i mata ma apaau, ia sa i ai i manu?T. O o latou mata o se faatusa o le malamalama ma le poto, o lona uiga, ua tumu I latou I le poto; ma o o latou apaau o se faatusa o le mana, e feoa’i, e gaoioi ai, ma isi mea faapena."},{"verse":5,"text":"F. O le a le mea ia tatou malamalama I ai e uiga I le fa ma le luasefulu o toeaina, ua tautala I ai Ioane?T. Ia tatou malamalama o toeaina nei na vaai I ai Ioane, o toeaina o e na faamaoni I le galuega o le auaunaga ma ua maliliu; o e na I ai I ekalesia e fitu, ma sa I ai I le taimi lena I le parataiso o le Atua."},{"verse":6,"text":"F. O le a le mea ia tatou malamalama I ai e uiga I le tusi na vaai I ai Ioane, lea na faamauina I le tua I faamaufaailoga e fitu?T. Ia tatou malamalama o lea tusi ua I ai le finagalo faaalia, mealilo, ma galuega a le Atua; o mea natia o lana faautaga e faatatau I le lalolagi lenei I le afe lona fitu o tausaga o lona faaauauga, po o lona olaga faaletino."},{"verse":7,"text":"F. O le a le mea ia tatou malamalama I ai e uiga I faamaufaailoga e fitu ia na faamauina ai?T. Ia tatou malamalama o le faamaufaailoga muamua ua I ai mea o le uluai afe tausaga, ma le lona lua foi o mea o le afe tausaga lona lua, ma ua faapena lava seia oo mai i le lona fitu."},{"verse":8,"text":"F. O le a le mea ia tatou malamalama i ai e uiga i agelu e toafa, ua ta’ua mai i le mataupu 7 ma le fuaiupu 1 o le Faaaliga?T. Ia tatou malamalama o i latou o agelu e toafa na auina mai mai le Atua, o e ua tuu atu i ai le mana i luga o vaega e fa o le lalolagi, e faasao ai le ola ma faaumatia ai; o i latou ia o e ua i ai le talalelei tumau e faavavau e tuu atu i atunuu uma, ituaiga, gagana, ma nuu; ua i ai le mana e pupuni ai le lagi, e faamau ai mo le ola, pe lafo ifo ai i lalo i itulagi o le pogisa."},{"verse":9,"text":"F. O le a le mea ia tatou malamalama i ai e uiga i le agelu na alu a’e mai sasa’e, Faaaliga mataupu 7 ma le fuaiupu lona 2?T. Ia tatou malamalama o le agelu na alu a’e mai sasa’e o ia lea ua tuu atu i ai le faamaufaailoga a le Atua soifua i luga o ituaiga e sefululua o Isaraelu; o le mea lea, ua alaga atu o ia i agelu e toafa ua i ai le talalelei tumau e faavavau, ua faapea atu: Aua le faamanu’aina le lalolagi, po o le sami, po o laau, seia uma ona tatou faamaufaailogaina auauna a lo tatou Atua i o latou muaulu. Ma, afai tou te taliaina, o Elaia lea, lea sa tuu e sau e faapotopoto faatasi ituaiga o Isaraelu ma toefuatai mai mea uma."},{"verse":10,"text":"F. O le a le taimi e faataunuu ai mea ua tautalagia i lenei mataupu?T. E faataunuuina i latou i le afe lona ono o tausaga, pe i le tatalaina o le faamaufaailoga lona ono."},{"verse":11,"text":"F. O le a le mea ia tatou malamalama i ai e uiga i le faamaufaailogaina o le tasi le selau fasefulu-fa afe mai ituaiga uma o Isaraelu—e sefululua afe mai ituaiga taitasi?T. Ia tatou malamalama o i latou o e e faamauina o faitaulaga sili ia, ua faauuina i le faatulagaga paia a le Atua, e tauaaoina le talalelei tumau e faavavau; ona o i latou ia o i latou o e e faauuina mai atunuu taitasi uma, ituaiga, gagana, ma nuu, e agelu o e ua tuuina atu i ai le mana i luga o atunuu o le lalolagi, e aumai le toatele o e e fia o mai i le ekalesia a le Ulumatua."},{"verse":12,"text":"F. O le a le mea ia tatou malamalama i ai e uiga i le ilia o pu, ua ta’ua mai i le mataupu 8 o le Faaaliga?T. Ia tatou malamalama, e pei ona sa faia e le Atua le lalolagi i aso e ono, ma o le aso lona fitu na ia faauma ai lana galuega, ma faapaia ai, ma faia foi le tagata mai le efuefu o le eleele, o le a faapea lava, i le amataga o le afe lona fitu o tausaga, ona faapaia e le Alii le Atua le lalolagi, ma faauma ai le faaolataga o tagata, ma faamasino mea uma, ma togiola mea uma, se’i vagana ai mea ia na te le’i tuuina i lona mana, pe a ia faamauina mea uma, i le iuga o mea uma; ma o le ilia o pu a agelu e toafitu o le sauniaina ma le faaumaina lea o lana galuega, i le amataga o le afe lona fitu o tausaga—o le teuteuina lea o le ala ae le’i oo i le taimi o lona afio mai."},{"verse":13,"text":"F. O afea e faataunuu ai mea ua tusia i le mataupu 9 o le Faaaliga?T. E faataunuuina i latou pe a uma ona tatala o le faamaufaailoga lona fitu, ae le’i oo i le afio mai o Keriso."},{"verse":14,"text":"F. O le a se mea ia tatou malamalama i ai e uiga i le tusi laitiiti lea na ’ai e Ioane, e pei ona ta’ua i le mataupu 10 o le Faaaliga?T. Ia tatou malamalama o se misiona lea, ma se sauniga, mo ia, e faapotopoto ituaiga o Isaraelu; faauta, o Elaia lea, o lē, e pei ona tusia, e ao ina sau ma toefuatai mai mea uma."},{"verse":15,"text":"F. O le a le mea ia malamalama i ai e uiga i molimau e toalua, i le mataupu lona sefulutasi o le Faaaliga?T. O i la’ua ia o perofeta e toalua o le a faatutuina mai e o atu i le atunuu o tagata Iutaia i aso e gata ai, i le taimi o le toefuataiga, ma vavalo atu i tagata Iutaia pe a uma ona faapotopotoina i latou ma uma ona latou fausia le aai o Ierusalema i le laueleele o o latou tamā."}]},{"chapter":78,"verses":[{"verse":1,"text":"Sa fetalai mai le Alii ia Iosefa Samita, Le Itiiti, ua faapea mai: Faalogo mai ia te a’u, ua fetalai mai ai le Alii lo outou Atua, o e ua faauuina i le perisitua maualuga o la’u ekalesia, o e ua outou faapotopoto faatasi outou lava;"},{"verse":2,"text":"Ma faalogo mai i le fautuaga a lē na faauuina outou mai luga, o lē o le a tautala atu i o outou taliga upu o le poto, ina ia oo mai ia te outou le faaolataga i lena mea ua outou tuuina mai i o’u luma, ua fetalai mai ai le Alii le Atua."},{"verse":3,"text":"Auā e moni Ou te fai atu ia te outou, ua oo mai le taimi, ma ua oo mai nei lava; ma faauta, ma tagai, e tatau ona i ai se faatulagaga o lo’u nuu, i le puleaina ma le faatuina o mataupu o le faleteuoloa mo e ua matitiva o lo’u nuu, i le nofoaga lenei ma i le laueleele o Siona—"},{"verse":4,"text":"Mo se faapotopotoga ma se faatulagaga mau ma le tumau e faavavau i la’u ekalesia, e faaalualu ai i luma le faamoemoe, lea ua outou tautino i ai, mo le faaolataga o tagata, ma mo le mamalu o lo outou Tamā o i le lagi;"},{"verse":5,"text":"Ina ia mafai ona outou tutusa i maliega o mea faalelagi, ioe, ma mea faaletino foi, mo le mauaina o mea faalelagi."},{"verse":6,"text":"Auā afai tou te lē tutusa i mea faaletino, e lē mafai ona outou tutusa i le mauaina o mea faalelagi;"},{"verse":7,"text":"Auā afai tou te mananao Ou te tuu atu ia te outou se nofoaga i le lalolagi selesitila, e ao ina outou saunia outou lava i le faia o mea ua Ou poloaiina ai outou ma manaomia mai ia te outou."},{"verse":8,"text":"Ma o lenei, e moni ua faapea ona fetalai mai o le Alii, e tatau ona faia o mea uma mo lo’u mamalu, e outou o e ua au faatasi i lenei faatulagaga;"},{"verse":9,"text":"Pe, i ni isi faaupuga, ia tuu atu i la’u auauna o Newel K. Whitney ma la’u auauna o Iosefa Samita, Le Itiiti, ma la’u auauna o Sini Rikitone, e fono faatasi ma le au paia o e o i Siona;"},{"verse":10,"text":"A lē o lea, ua saili Satani e liliu ese o latou loto mai le upumoni, ina ia faatauasoina i latou ma lē malamalama ai i mea ua saunia mo i latou."},{"verse":11,"text":"O le mea lea, Ou te tuu atu ai ia te outou se poloaiga, ia outou saunia ma faatulaga outou lava i se maliega po o se feagaiga tumau e faavavau e lē mafai ona motusia."},{"verse":12,"text":"Ma o ia o lē na te solia o le a aveesea lona tofi ma lona tulaga i le ekalesia, ma o le a tuu atu i tu’iga a Satani sei oo i le aso o le togiolaina."},{"verse":13,"text":"Faauta, o le sauniuniga lenei ua Ou saunia ai outou, ma le faavae, ma le ata Ou te tuu atu ia te outou, tou te mafai ai ona faataunuu o poloaiga ua tuu atu ia te outou;"},{"verse":14,"text":"Ina ia mafai e ala i la’u tausiga alofa, e ui i puapuaga o le a oo mai i o outou luga, ona mafai ona tutoatasi le ekalesia i luga a’e o isi tagata uma i lalo o le lalolagi selesitila;"},{"verse":15,"text":"Ina ia mafai ona outou o mai i luga i le pale ua saunia mo outou, ma avea o ni pule i luga o malo e tele, ua fetalai mai ai le Alii le Atua, o le Paia e Toatasi o Siona, o lē na faatuina faavae o Atamu-onai-Amani;"},{"verse":16,"text":"O lē na tofia Mekaeli lo outou aloalii, ma faatutumau ona vae, ma faatu maualuga o ia, ma tuu atu ia te ia ki o le faaolataga i lalo o le fautuaga ma le taitaiga a le Paia e Toatasi, o lē ua leai se amataga o ona aso po o se gataaga o le soifua."},{"verse":17,"text":"E moni, e moni, Ou te fai atu ia te outou, o outou o ni fanau iti, ma tou te lei malamalama lava i le tetele o faamanuiaga o i ai i le Tamā i ona lava aao ma ua saunia mo outou;"},{"verse":18,"text":"Ma e lē mafai ona outou gafatia mea uma i le taimi nei; ae ui i lea, ia fiafia, ona o le a Ou ta’ita’ia outou i le ala. O le malo o la outou ia, ma o ona faamanuiaga o a outou ia, ma o ’oa o le faavavau o a outou foi ia."},{"verse":19,"text":"Ma o ia o lē e taliaina mea uma ma le faafetai o le a faamamaluina; ma o mea o le lalolagi lenei o le a faaopoopoina ia te ia, i le sautuaselau lava, ioe, e sili atu."},{"verse":20,"text":"O le mea lea, ia fai mea ua Ou poloaiina ai outou, ua fetalai mai ai lo outou Togiola, o Amani lava le Atalii, o lē e sauniaina mea uma ae le’i avea outou e ia;"},{"verse":21,"text":"Ona o outou o le ekalesia a le Ulumatua, ma o le a aveina a’e outou e ia i luga i se ao, ma tofia i tagata taitoatasi lana vaega."},{"verse":22,"text":"Ma o ia o lē o se tausimea atamai ma le faamaoni, o le a maua e ia mea uma mo ona tofi. Amene."}]},{"chapter":79,"verses":[{"verse":1,"text":"E moni Ou te fai atu ia te oe, o lo’u loto e tatau i la’u auauna o Jared Carter ona toe foi atu i laueleele i sasa’e, mai lea nofoaga i lea nofoaga, ma mai lea aai i lea aai, i le mana o le faauuga na faauu ai o ia, e folafola atu tala fiafia o le olioli tele, le talalelei lava lea tumau e faavavau."},{"verse":2,"text":"Ma o le a Ou auina atu i ona luga le Fesoasoani, lea o le a a’oa’o atu ai ia te ia le upumoni ma le ala e alu atu ai o ia;"},{"verse":3,"text":"Ma e tusa ai ma lona faamaoni, o le a Ou toe faapaleina o ia i fusisaito."},{"verse":4,"text":"O le mea lea, ia fiafia ai lou loto, la’u auauna e, Jared Carter, ma ia lē fefe, ua fetalai mai ai lou Alii, o Iesu Keriso lava. Amene."}]},{"chapter":80,"verses":[{"verse":1,"text":"E moni, ua faapea ona fetalai mai o le Alii ia te oe la’u auauna, o Stephen Burnett: Ia e alu atu ia, ia e alu atu ia i le lalolagi ma tala’i atu le talalelei i tagata uma e oo atu i ai lou leo."},{"verse":2,"text":"Ma talu ai ona ua e manao i se soa, o le a Ou tuu atu ia te oe la’u auauna o Eden Samita."},{"verse":3,"text":"O le mea lea, ia oulua o atu ma tala’i atu la’u talalelei, pe i matu po o saute, i sasa’e po o sisifo, e lē afaina, ona e lē mafai ona oulua sesē ai."},{"verse":4,"text":"O lea, alaga atu mea na oulua faalogo i ai, ma talitonu moni i ai, ma oulua iloa ua moni."},{"verse":5,"text":"Faauta, o le finagalo lenei o ia o lē na valaauina oulua, o lo oulua Togiola, o Iesu Keriso lava. Amene."}]},{"chapter":81,"verses":[{"verse":1,"text":"E moni, e moni, Ou te fai atu ia te oe la’u auauna, Frederick G. Williams: Faalogo mai i le leo o ia o lē o tautala atu, i le afioga a le Alii lou Atua, ma uai atu i le valaauga ua valaaulia i ai oe, o le avea lea ma se faitaulaga sili i la’u ekalesia, ma se fesoasoani i la’u auauna o Iosefa Samita, Le Itiiti;"},{"verse":2,"text":"O lē ua Ou tuuina atu i ai ki o le malo, ia e i ai i taimi uma i le Au Peresitene o le Perisitua Maualuga:"},{"verse":3,"text":"O lea, e moni ua Ou aloa’ia o ia ma o le a Ou faamanuiaina o ia, ma oe foi, e tusa ai ma lou faamaoni i le faufautua, i le tofi ua Ou tofia i ai oe, i le tatalo e lē aunoa, i le leo ma i lou loto, i luma o tagata ma i le na’o oe, ma i lau auaunaga foi i le folafolaina atu o le talalelei i le laueleele o e o lo o ola, ma i totonu o ou uso."},{"verse":4,"text":"Ma o le faia o ia mea o le a e faia ai mea lelei silisili atu mo ou uso a tagata, ma o le a e siitia a’e ai le mamalu o ia o lē o lou Alii."},{"verse":5,"text":"O le mea lea, ia e faamaoni; tulai i le tofi ua Ou tofia i ai oe; fesoasoani i e vaivai, siitia a’e i luga lima ua tautau i lalo, ma faamalolosi tulivae ua vaivai."},{"verse":6,"text":"Ma afai e te faamaoni e oo i le iuga o le a e maua se pale o le ola pea, ma le ola e faavavau i maota ua Ou saunia i le fale o lo’u Tamā."},{"verse":7,"text":"Faauta, ma tagai, o afioga ia a le Alefa ma le Omeka, o Iesu Keriso lava. Amene."}]},{"chapter":82,"verses":[{"verse":1,"text":"E moni, e moni, Ou te fai atu ia te outou, a’u auauna e, e tusa ai ma lo outou faamagalo atu o le tasi i le isi i o outou sesē, ua faapea lava ona faamagaloina o outou e A’u, o le Alii."},{"verse":2,"text":"Ae ui i lea, e i ai ni isi i totonu o outou o e ua agasala tele lava; ioe, ua outou agasala uma lava; ae e moni Ou te fai atu ia te outou, ia outou faaeteete mai le taimi nei ma le agai i luma, ma taofi mai le agasala, ne’i pa’u’ū mai faamasinoga tiga i luga o o outou ulu."},{"verse":3,"text":"Aua o ia o lē ua tuu atu i ai mea e tele, e tele mea ua manaomia mai ai; ma o ia o lē e agasala faasaga i le malamalama sili atu, o le a maua e ia le ta’usalaga sili atu."},{"verse":4,"text":"Tou te valaau mai i lo’u igoa mo faaaliga, ma Ou te tuu atu ia te outou faaaliga; ma e tusa ai ma le lē tausia o a’u upu, ia Ou te tuu atu ia te outou, e avea outou ma ē solitulafono; ma o le faamasinotonu ma le faamasinoga o faasalaga ia ua o faatasi ma la’u tulafono."},{"verse":5,"text":"O lea, o le mea Ou te fai atu ai i le toatasi Ou te fai atu ai i tagata uma: Ia mataala, ona ua faasalalau atu e le tiapolo ana pule’aga, ma ua pule le pouliuli;"},{"verse":6,"text":"Ma ua sasao a’e le toasa o le Atua e faasaga i e ua nonofo i le lalolagi; ma ua leai se tasi ua faia se mea lelei, ona ua o ese atu tagata uma mai le ala."},{"verse":7,"text":"Ma o lenei, e moni Ou te fai atu ia te outou, o A’u, o le Alii, o le a lē ta’usalaina outou i se agasala; ō atu ia i o outou ala ma ia lē toe agasala; ae o le tagata lena o lē e agasala o le a toe foi mai i ai agasala muamua, ua fetalai mai ai le Alii lo outou Atua."},{"verse":8,"text":"O lenei foi, Ou te fai atu ia te outou, Ou te tuu atu ia te outou se poloaiga fou, ina ia outou malamalama i lo’u loto e faatatau ia te outou;"},{"verse":9,"text":"Pe, i ni isi faaupuga, Ou te tuu atu ia te outou ni faatonuga i le ala e mafai ona outou amio ai i o’u luma, ina ia liliu mai ia te outou mo lo outou faaolataga."},{"verse":10,"text":"O A’u, o le Alii, e noatia a’u pe a outou faia mea Ou te fai atu ai; ae a outou lē faia mea Ou te fai atu ai, e leai se folafolaga mo outou."},{"verse":11,"text":"O lea, e moni Ou te fai atu ia te outou, ua tatau i a’u auauna o Edward Partridge ma Newel K. Whitney, A. Sini Gilbert ma Sini Rikitone, ma la’u auauna o Iosefa Samita, ma Ioane Uitimera ma Oliva Kaotui, ma V. V. Phelps ma Matini Harisi, ona fusia faatasi i se ioega ma se feagaiga e lē mafai ona lepetia i le solitulafono, vagana ai le mulimuli vave mai ai o le faamasinoga, i a outou mea-tausi eseese—"},{"verse":12,"text":"Ina ia faafoe ai mataupu tau i e matitiva, ma mea uma e faatatau i le au epikopo i le laueleele o Siona ma le laueleele o Katelani;"},{"verse":13,"text":"Auā ua Ou faapaiaina le laueleele o Katelani i lo’u lava taimi e tatau ai mo le manuia o le au paia a le Silisili Ese, ma mo se siteki i Siona."},{"verse":14,"text":"Auā e ao ina faateleina Siona i le matagofie, ma i le paia; o ona tuaoi e ao ina faalauteteleina; o ona siteki e ao ina faamalolosia; ioe, e moni Ou te fai atu ia te outou, e ao ina tula’i Siona ma ofu i ona ofu matagofie."},{"verse":15,"text":"O lea, Ou te tuu atu ia te outou le poloaiga lenei, ia outou fusia outou lava i lenei feagaiga, ma ia faia e tusa ai ma tulafono a le Alii."},{"verse":16,"text":"Faauta, o le poto foi lea ua ia te a’u mo lo outou lelei."},{"verse":17,"text":"Ma ia outou tutusa, po o ua faapea, ia outou maua āiā tutusa i meatotino, mo le lelei o le puleaina o atugaluga o a outou mea-tausi, i tagata taitoatasi e tusa ma ona manaoga ma mea na te manaomia, e tusa ai ma le tonu o ona manao—"},{"verse":18,"text":"Ma o nei mea uma ua mo le manuia o le ekalesia a le Atua soifua, ina ia mafai e tagata taitoatasi ona faaleleia atili ana taleni, ina ia mafai e tagata taitoatasi ona maua ni isi taleni, ioe, e sautuaselau lava, e lafo i le faleteuoloa o le Alii, e avea ma meatotino faitele a le ekalesia atoa—"},{"verse":19,"text":"E saili ai e tagata taitoatasi le lelei o lē la te tuaoi, ma faia mea uma ma le manatu tasi i le mamalu o le Atua."},{"verse":20,"text":"O lenei faatulagaga ua Ou tofia e avea ma se faatulagaga tumau e faavavau ia te outou, ma i o outou sui, e tusa ai ma lo outou lē agasala."},{"verse":21,"text":"Ma o le tagata e agasala faasaga i lenei feagaiga, ma faamaaa lona loto faasaga i ai, ia faia i ai e tusa ma tulafono o la’u ekalesia, ma o le a tuu atu i tu’iga a Satani seia oo i le aso o le togiolaina."},{"verse":22,"text":"Ma o lenei, e moni Ou te fai atu ia te outou, ma o le poto lea, ia outou faia mo outou lava ni uo faatasi ma mamone o le amioletonu, ma o le a latou lē faaumatia ai outou."},{"verse":23,"text":"Ia tuu tasi mai ia te a’u le faamasinoga, aua e a a’u ia ma o le a Ou toe totogi atu. Ia i ai ia te outou le filemu; ua i ai pea a’u faamanuiaga ia te outou."},{"verse":24,"text":"Auā e a outou lava pea le malo, ma o le a faapea lava e faavavau, pe afai tou te lē pa’u’ū ese mai i lo outou tutumaumausalī. E faapea lava. Amene."}]},{"chapter":83,"verses":[{"verse":1,"text":"E moni, ua faapea ona fetalai mai o le Alii, e faaopoopo i tulafono a le ekalesia e faatatau i fafine ma fanau, i latou ia o e o le ekalesia, o e ua oti a latou tane po o tamā:"},{"verse":2,"text":"Ua i ai i fafine le āiā i luga o a latou tane mo lo latou tausiga, seia aveesea a latou tane; ma afai e lē maua i latou o ni ē solitulafono, latou te maua le faaaumeaina i le ekalesia."},{"verse":3,"text":"Ma afai latou te lē faamaoni, latou te lē maua le faaaumeaina i le ekalesia; peitai e mafai ona latou nonofo pea i luga o o latou tofi e tusa ai ma tulafono o le laueleele."},{"verse":4,"text":"Ua i ai i fanau uma le āiā i luga o o latou matua mo lo latou tausiga seia oo ina ina matutua i latou."},{"verse":5,"text":"Ma a mavae lena, ua i ai ia te i latou le āiā i luga o le ekalesia, po o ua faapea, i luga o le faleteuoloa o le Alii, pe afai ua lē maua e o latou matua ni mea e tuu atu ai ia te i latou ni tofi."},{"verse":6,"text":"Ma ia tausia le faleteuoloa i faapaiaga a le ekalesia; ma ia tausia fafine ua oti a latou tane ma fanau mātua-oti, faapea foi e ua matitiva. Amene."}]},{"chapter":84,"verses":[{"verse":1,"text":"O se faaaliga a Iesu Keriso i lana auauna o Iosefa Samita, Le Itiiti, ma toeaina e toaono, a’o latou tuufaatasi o latou loto ma siitia a’e o latou leo i lugā."},{"verse":2,"text":"Ioe, o le afioga a le Alii e faatatau i lana ekalesia, ua faatuina i aso e gata ai mo le toefuataiga o ona tagata, e pei ona sa ia fetalaia e ala mai i fofoga o ana perofeta, ma mo le faapotopotoina o lana au paia e tutulai i luga o le Mauga o Siona, lea o le a avea ma aai o Ierusalema Fou."},{"verse":3,"text":"O le aai lea o le a fausia, e amata mai i le fanua o le malumalu, lea ua tofia e le tamatama’iaao o le Alii, i tuaoi i sisifo o le Setete o Misuri, ma ua faapaiaina e le lima o Iosefa Samita, Le Itiiti, ma isi o e na fiafia tele i ai le Alii."},{"verse":4,"text":"E moni o le afioga lenei a le Alii, ia fausia le aai o Ierusalema Fou i le faapotopotoina o le au paia, e amata atu i le nofoaga lenei, le nofoaga lea o le malumalu, le malumalu lea o le a faatuina i le tupulaga lenei."},{"verse":5,"text":"Auā e moni e lē mavae uma atu le tupulaga lenei seia fausia se maota mo le Alii, ma o le a faamalumalu ai se ao i ona luga, le ao lea o le mamalu lava o le Alii, lea o le a faatumulia ai le maota."},{"verse":6,"text":"Ma atalii o Mose, e tusa ma le Perisitua Paia na ia maua i lalo o le lima o Ietero le tamā-o-lana-avā."},{"verse":7,"text":"Ma na maua e Ietero i lalo o le lima o Kalepo;"},{"verse":8,"text":"Ma na maua e Kalepo i lalo o le lima o Eliu;"},{"verse":9,"text":"Ma na maua e Eliu i lalo o le lima o Ieremai;"},{"verse":10,"text":"Ma Ieremai i lalo o le lima o Kato;"},{"verse":11,"text":"Ma Kato i lalo o le lima o Esaia;"},{"verse":12,"text":"Ma na maua e Esaia i lalo o le aao o le Atua."},{"verse":13,"text":"Na ola foi Esaia i aso o Aperaamo, ma sa faamanuiaina e ia—"},{"verse":14,"text":"O Aperaamo lea na ia maua le perisitua mai ia Mekisateko, o lē na mauaina le perisitua e ala i le gafa o ona tamā, seia oo lava ia Noa;"},{"verse":15,"text":"Ma mai ia Noa seia oo ia Enoka, e ala i le gafa o o la’ua tamā;"},{"verse":16,"text":"Ma mai ia Enoka ia Apelu, o lē na fasiotia i le taupulepulega faalilolilo a lona uso, o lē na mauaina le perisitua i poloaiga a le Atua, i le lima o lona tamā, o Atamu, o lē o le uluai tagata—"},{"verse":17,"text":"O le perisitua lea sa i ai pea i le ekalesia a le Atua i tupulaga uma, ma ua aunoa ma se amataga o aso po o se iuga o tausaga."},{"verse":18,"text":"Ma sa faamau foi e le Alii se perisitua i luga o Arona ma ana fanau, i a latou tupulaga uma, le perisitua lea ua i ai pea lava foi ma tumau e faavavau faatasi ma le perisitua lea ua tusa ma le faatulagaga sili ona paia a le Atua."},{"verse":19,"text":"Ma o le perisitua tele lea e pulea le talalelei ma umia le ki o mealilo o le malo, o le ki lava lea o le malamalama e uiga i le Atua."},{"verse":20,"text":"O lea, o ona sauniga, ua faaalia ai le mana o le faale-atua."},{"verse":21,"text":"Ma a aunoa ma ona sauniga, ma le pule o le perisitua, e lē faaalia mai le mana o le faale-atua i tagata i la le tino;"},{"verse":22,"text":"Auā a aunoa ma lea, e leai se tagata e mafai ona vaai i fofoga o le Atua, le Tamā lava, ma ola."},{"verse":23,"text":"O lenei, o lenei mea sa aoao manino atu e Mose i le fanauga a Isaraelu i le vao, ma saili ma le filiga e faapaia lona nuu ina ia mafai ona latou vaai i fofoga o le Atua;"},{"verse":24,"text":"Peitai sa latou faamaaa o latou loto ma lē mafai ai ona latou tumau i ona luma; o lea, o le Alii i lona toasa, ona sa sasao a’e lona toatamai e faasaga ia te i latou, na tauto ai e lē tatau ona latou ulu atu i lona malologa, o le malologa lea o le atoatoaga o lona mamalu, a’o latou i ai i le vao."},{"verse":25,"text":"O lea, na ave ai e ia Mose i fafo mai totonu o i latou, ma le Perisitua Paia foi;"},{"verse":26,"text":"Ae sa i ai pea le perisitua maualalo, le perisitua lea ua umia le ki o le ’auaunaga a agelu ma le talalelei sauniuni;"},{"verse":27,"text":"O le talalelei lea o le talalelei o le salamo ma le papatisoga, ma le faamagaloina o agasala, ma le tulafono o poloaiga faaletino, ia na faia e le Alii i lona toasa ia tumau pea i le aiga o Arona i totonu o le fanauga a Isaraelu seia oo mai ia Ioane, o lē na saunia e le Atua, ua faatumuina i le Agaga Paia mai le manava o lona tinā."},{"verse":28,"text":"Auā sa papatisoina o ia a’o i ai lava o ia i lona tamaitiiti, ma sa faauuina e le agelu a le Atua i lenei mana i le taimi na valu ai aso o lona matua, e faatoilalo le malo o Iutaia, ma fai faasa’osa’o le ala o le Alii i luma o mata o lona nuu, e saunia ai i latou mo le afio mai o le Alii, o lē ua tuu atu i ona lima le mana uma."},{"verse":29,"text":"O lenei foi, o tofi o le toeaina ma le epikopo, o ni faaopoopoga tatau ai i le perisitua maualuga."},{"verse":30,"text":"O lenei foi, o tofi o le a’oa’o ma le tiakono, o ni faaopoopoga tatau e a le perisitua maualalo, o le perisitua lea na faamauina i luga o Arona ma ona atalii."},{"verse":31,"text":"O lea, e pei ona Ou fai atu e uiga i atalii o Mose—ona o atalii o Mose ma atalii foi o Arona o le a osia se taulaga mu ma se taulaga e taliaina i le maota o le Alii, le maota lea o le a fausia mo le Alii i le tupulaga lenei, i luga o le fasifanua faapaiaina e pei ona Ou tofia—"},{"verse":32,"text":"Ma o atalii o Mose ma Arona o le a faatumulia i le mamalu o le Alii i luga o le Mauga o Siona, i le maota o le Alii, o e o o la’ua atalii o outou ia; ma le toatele foi o e ua ou valaaulia ma auina atu e atia’e la’u ekalesia."},{"verse":33,"text":"Auā ’ai se tasi e faamaoni i le mauaina o ia perisitua e lua ua Ou tautala atu ai, ma le faalauteleina o o latou valaauga, e faapaiaina e le Agaga i le faafouina o o latou tino."},{"verse":34,"text":"E avea i latou ma atalii o Mose ma Arona ma fanau a Aperaamo, ma le ekalesia ma le malo, ma le ’au filifilia a le Atua."},{"verse":35,"text":"O lenei foi o i latou uma o e e talia lenei perisitua ua latou talia a’u, ua fetalai mai ai le Alii;"},{"verse":36,"text":"Auā o ia o lē e talia a’u auauna ua ia talia a’u;"},{"verse":37,"text":"Ma o ia o lē e talia a’u ua ia talia lo’u Tamā;"},{"verse":38,"text":"Ma o ia o lē e talia lo’u Tamā e maua e ia le malo o lo’u Tamā; o lea, o mea uma ua i ai i lo’u Tamā o le a tuu atu ia te ia."},{"verse":39,"text":"Ma o lenei mea ua tusa ai ma le tautoga ma le feagaiga e a le perisitua ia."},{"verse":40,"text":"O le mea lea, o i latou uma o e e mauaina le perisitua, e mauaina lenei tautoga ma le feagaiga a lo’u Tamā, e lē mafai ona solia e ia, pe mafai ona aveesea."},{"verse":41,"text":"Peitai ’ai se e solia lenei feagaiga ina ua uma ona maua e ia, ma liliu ese atoa mai ai, o le a lē maua e ia se faamagaloga o agasala i le lalolagi lenei po o le lalolagi a sau."},{"verse":42,"text":"Ma oi talofa ia te i latou uma o e e lē o mai i lenei perisitua ua outou maua, lea ua Ou faamauina nei i luga o outou o e ua auai i lenei aso, i lo’u lava leo mai le lagi; ma ua ’Ou tuu atu foi i ’au o le lagi ma a’u agelu le tiute e faatatau ia te outou."},{"verse":43,"text":"Ma Ou te tuu atu nei ia te outou se poloaiga ia outou faaeteete e faatatau ia te outou lava, ia outou gaua’i ma le filiga i upu o le ola e faavavau."},{"verse":44,"text":"Ona ia outou ola i afioga uma e tulei mai le fofoga o le Atua."},{"verse":45,"text":"Auā o le afioga a le Alii o le upumoni lea, ma o soo se mea ua moni, o le malamalama lea, ma o soo se mea ua malamalama, o le Agaga lea, o le Agaga lava lea o Iesu Keriso."},{"verse":46,"text":"Ma o le Agaga na te tuuina mai le malamalama i tagata taitoatasi e sau i le lalolagi; ma o le Agaga e faamalamalamaina tagata taitoatasi i le lalolagi atoa, o e e faalogo i le siufofoga o le Agaga."},{"verse":47,"text":"Ma o tagata uma taitoatasi o e e faalogo i le siufofoga o le Agaga, e o mai i le Atua, le Tamā lava."},{"verse":48,"text":"Ma e a’oa’o o ia e le Tamā e uiga i le feagaiga ua faafouina ma faamauina e ia i luga o outou, lea ua faamauina i luga o outou i le manatu ia te outou, ma ua lē mo na’o outou, ae mo le lalolagi atoa."},{"verse":49,"text":"Ma ua taoto le lalolagi atoa i le agasala, ma ua ōi i lalo o le pouliuli ma lalo o le pologa o le agasala."},{"verse":50,"text":"Ma o lenei mea o le a mafai ona outou iloa ai ua i ai i latou i lalo o le pologa o le agasala, ona ua latou lē o mai ia te a’u."},{"verse":51,"text":"Auā ’ai se tasi e lē sau ia te a’u, ua i ai i lalo o le pologa o le agasala."},{"verse":52,"text":"Ma ’ai se tasi e lē taliaina lo’u leo, ua lē masani i lo’u leo, ma ua lē a a’u ia."},{"verse":53,"text":"Ma o lenei mea o le a mafai ai ona outou iloa o le amiotonu mai le amioleaga, ma ua ōi le lalolagi atoa i lalo o le agasala ma le pouliuli i le taimi nei lava."},{"verse":54,"text":"Ma sa faapouliuligia o outou mafaufau i taimi ua mavae ona o le lē talitonu, ma ona sa outou manatu māmā i mea ua outou maua—"},{"verse":55,"text":"O le faafiasili lea ma le lē talitonu ua aumai ai le ekalesia atoa i lalo o le tausalaga."},{"verse":56,"text":"Ma o lenei ta’usalaga ua tauaveina i luga o le fanauga a Siona, i latou uma lava."},{"verse":57,"text":"Ma o le a latou tumau pea i lalo o lenei ta’usalaga, seia latou salamo ma manatua le feagaiga fou, o le Tusi a Mamona lava lea ma poloaiga muamua ia na Ou tuuina atu ia te i latou, ia lē na’o le fai atu, ae ia faia e tusa ai ma mea ua Ou tusia—"},{"verse":58,"text":"Ina ia mafai ona latou aumai o ni fua e tatau ai mo le malo o lo latou Tamā; a lē o lea o le a tumau pea le sasa ma le faamasinoga e liligi mai i luga o le fanauga a Siona."},{"verse":59,"text":"Auā pe faaeleelea ea e fanau o le malo lo’u laueleele paia? E moni, Ou te fai atu ia te outou, e Leai."},{"verse":60,"text":"E moni, e moni, Ou te fai atu ia te outou o e o faalogo mai nei i a’u upu, o lo’u leo lea, amuia outou e tusa ai ma lo outou taliaina o nei mea;"},{"verse":61,"text":"Auā o le a Ou faamagaloina outou ia outou agasala e ala i le poloaiga lenei—ia outou tutumau-mausalī i o outou mafaufau i le mamalu ma le agaga o le tatalo, i le tuuina atu o le molimau i le lalolagi atoa e uiga i mea ia ua ta’u atu ia te outou."},{"verse":62,"text":"O lea, ia outou o atu i le lalolagi atoa; ma i soo se mea e lē mafai ona outou o atu i ai, ia outou auina atu i ai, ina ia mafai ona alu atu o le molimau mai ia te outou i le lalolagi atoa i tagata uma."},{"verse":63,"text":"Ma e pei ona sa Ou fai atu i a’u aposetolo, e faapea lava ona Ou fai atu ia te outou, ona o outou o a’u aposetolo, o faitaulaga sili lava a le Atua; o outou ia o i latou o e na tuuina mai e lo’u Tamā ia te a’u; o outou o a’u uo;"},{"verse":64,"text":"O lea, e pei ona Ou fai atu i a’u aposetolo Ou te toe fai atu ia te outou, o tagata uma taitoatasi o e e talitonu ia outou upu, ma papatiso i le vai mo le faamagaloina o agasala, o le a mauaina le Agaga Paia."},{"verse":65,"text":"Ma o faailoga nei e mulimuli ia te i latou o e e talitonu—"},{"verse":66,"text":"O lo’u igoa o le a latou faia ai galuega ofoofogia e tele;"},{"verse":67,"text":"O lo’u igoa o le a latou tutuli ese ai tiapolo;"},{"verse":68,"text":"O lo’u igoa o le a latou faamalolo ai e mama’i;"},{"verse":69,"text":"O lo’u igoa o le a latou faapupula ai mata o e tauaso, ma tatala ai taliga o e tutuli;"},{"verse":70,"text":"Ma o le a faatautatala ai laulaufaiva o e ua gūgū;"},{"verse":71,"text":"Ma afai e tuu atu e se tagata ia te i latou se mea ’oona o le a lē afaina ai i latou;"},{"verse":72,"text":"Ma o le a leai se malosi o le ’ona o se gata e afaina ai i latou."},{"verse":73,"text":"Ae Ou te tuu atu ia te i latou se poloaiga, ia aua ne’i mitamitavale i latou lava i nei mea, pe tautala atu ai i luma o le lalolagi; auā o nei mea ua tuuina atu ia te outou mo lo outou manuia ma lo outou faaolataga."},{"verse":74,"text":"E moni, e moni, Ou te fai atu ia te outou, o i latou o e e lē talitonu ia outou upu, ma lē papatisoina i le vai i lo’u igoa, mo le faamagaloina o a latou agasala, ina ia mafai ona latou maua o le Agaga Paia, o le a ta’usalaina, ma o le a lē o mai i le malo o lo’u Tamā, i le mea o i ai lo’u Tamā ma A’u."},{"verse":75,"text":"Ma o lenei faaaliga, ma le poloaiga, ia te outou, ua faamamaluina nei mai lenei lava itula i luga o le lalolagi atoa, ma ua i ai le talalelei ia oo atu i tagata uma o e latou te le’i mauaina."},{"verse":76,"text":"Peitai, e moni Ou te fai atu ia te i latou uma o e ua tuuina atu i ai le malo—e ao ina tala’i atu mai ia te outou ia te i latou, ina ia latou salamo ia latou galuega leaga muamua; aua e tatau ona a’oa’iina i latou i o latou loto leaga o le lē talitonu, ma o outou uso i Siona ona o lo latou fouvale faasaga mai ia te outou i le taimi na Ou auina atu ai outou."},{"verse":77,"text":"Ma Ou te toe fai atu ia te outou, a’u uo e, auā o le a amata atu nei ma le agai i luma ona Ou ta’ua outou o uo, ua tatau ai ona Ou tuu atu ia te outou le poloaiga lenei, ia avea outou ma a’u uo e pei lava i aso na Ou faatasi ai ma i latou, i le malaga atu e tala’i atu le talalelei i lo’u mana;"},{"verse":78,"text":"Auā sa Ou lē tuuina atu ia te i latou ia i ai ni a latou atotupe po o ni ato malaga, po o ni peleue se lua."},{"verse":79,"text":"Faauta, Ou te auina atu outou e tofotofo le lalolagi, ma e agavaa lē e galue i lona taui."},{"verse":80,"text":"Ma o soo se tagata e alu atu ma tala’i atu lenei talalelei o le malo, ma lē vaivai e tumau pea i le faamaoni i mea uma, o le a lē vaivai i le mafaufau, pe faapouliuligia, pe i le tino, itutino, po o soogaivi; ma o le a lē pa’ū se lauulu o lona ulu i le eleele e aunoa ma le lē iloa. Ma o le a latou lē fia aai, pe fia feinu."},{"verse":81,"text":"O lea, ia outou lē mafaufau mo a taeao, mo mea o le a outou ’ai, po o mea o le a outou inu, po o mea o le a outou oofu ai."},{"verse":82,"text":"Auā, ia mafaufau i lili o le fanua, i le ala ua latou tutupu a’e ai, latou te lē galulue, pe latou te milo foi; ae o malo o le lalolagi, i o latou mamalu atoa, ua lē faala’eiina e pei o se tasi o i latou nei."},{"verse":83,"text":"Auā o lo outou Tamā, o lē o i le lagi, ua silafia e ia ua outou manaomia nei mea uma."},{"verse":84,"text":"O lea, ia tuu taeao e manatu i ona lava mea."},{"verse":85,"text":"Pe tou te mafaufau muamua foi po o a tou te fai atu ai; ae ia teu i o outou mafaufau e lē aunoa afioga o le ola, ma o le a tuuina atu ia te outou i lea lava itula le vaega lena o le a fuaina atu i tagata taitoatasi."},{"verse":86,"text":"O lea, ia lē tuu atu i se tagata e i totonu o outou, ona o le poloaiga lenei ua mo tagata faamaoni uma o e ua valaaulia e le Atua i le ekalesia mo le auaunaga, e o atu e folafola atu le talalelei lenei o le malo, e ave, mai le itula lenei, se atotupe po o se ato malaga."},{"verse":87,"text":"Faauta, ua Ou auina atu outou e a’oa’i le lalolagi i a latou galuega amioletonu uma, ma a’oa’o atu ia te i latou e uiga i se faamasinoga o le a oo mai."},{"verse":88,"text":"Ma ai se na te talia outou, o iina o le a Ou i ai foi, ona o le a Ou alu muamua atu i o outou luma. O le a Ou i ai i lo outou lima taumatau ma lo outou agavale, ma o le a i ai lo’u Agaga i o outou loto, ma si’o faataamilo outou e a’u agelu, e sapasapai outou i luga."},{"verse":89,"text":"Ai se na te talia outou ua ia talia a’u; ma o ia lava lea o le a fafagaina outou, ma faalavalava outou, ma avatu tupe ia te outou."},{"verse":90,"text":"Ma o ia o lē e fafaga ia te outou, pe faalavalava outou, pe avatu ia te outou tupe, o le a leai se ala o le a lē maua ai lona taui."},{"verse":91,"text":"Ma o ia o lē na te lē faia ia mea ua lē o so’u soo o ia; o le mea lenei e mafai ona outou iloa ai o’u soo."},{"verse":92,"text":"O ia o lē na te lē talia outou, o ese mai ia te ia na’o outou lava, ma mulumulu o outou vae i vai, vai mamā ia, pe vevela pe malulu, ma molimau atu lena mea i lo outou Tamā o i le lagi, ma ia outou lē toe foi atu i lena tagata."},{"verse":93,"text":"Ma i soo se nuu po o se aai tou te ulu atu i ai, ia faapena lava ona outou faia."},{"verse":94,"text":"Ae ui i lea, ia outou saili ma le filigā ma ia lē taofia; ma oi talofa i lena fale, po o lena nuu po o le aai e teena outou, po o a outou upu, po o a outou molimau e uiga ia te a’u."},{"verse":95,"text":"Ou te toe fai atu, oi talofa i lena fale, po o lena nuu po o lena aai e teena outou, po o a outou upu, po o a outou molimau e uiga ia te a’u;"},{"verse":96,"text":"Aua o A’u, o lē Malosi Aoao, ua faaee atu o’u lima i luga o atunuu e sasa ia te i latou ona o a latou amioleaga."},{"verse":97,"text":"Ma o le a oo atu mala ma o le a lē aveeseina ia mala mai le lalolagi se’ia uma la’u galuega, lea o le a faapuupuuina i le amiotonu—"},{"verse":98,"text":"Se’ia oo ina iloa A’u e tagata uma, o e e totoe, mai lava i lē ua aupito itiiti e oo atu i lē aupito sili, ma o le a faatumulia i le malamalama o le Alii, ma o le a vaai mata i le mata, ma o le a siitia a’e o latou leo, ma o le a latou pepese faatasi ma le leo le pese fou lenei, fai mai:"},{"verse":99,"text":"Ua toe aumai e le Alii Siona;Ua togiolaina e le Alii lona nuu, o Isaraelu,E tusa ma le filifiliga o le alofa tunoa,Lea na faataunuuina i le faatuatuaMa le feagaiga a o latou tamā."},{"verse":100,"text":"Ua togiola e le Alii lona nuu;Ma ua noatia Satani ma ua lē toe i ai se taimi.Ua faapotopoto e le Alii mea uma i le tasi.Ua aumai Siona e le Aliii lalo mai lugā.Ua ava’e i luga Siona e le Alii mai lalō."},{"verse":101,"text":"Ua mapuitiga le lalolagi ma ua aumai lona malosi;Ma ua faatuina le upumoni i lona loto;Ma ua fiafia mai le lagi i ona luga;Ma ua faaofuina o ia i le mamalu o lona Atua;Ona ua tulai o ia i totonu o ona tagata."},{"verse":102,"text":"O le mamalu, ma le viiga, ma le mana, ma le malosi,Ia tuu atu i lo tatou Atua; ona ua tumu o ia i le alofa mutimutivale,Amiotonu, alofa tunoa ma le faamaoni, ma le filemu,E faavavau, faavavau lava, Amene."},{"verse":103,"text":"O lenei foi, e moni, e moni, Ou te fai atu ia te outou, e tatau i tagata taitoatasi o e e o atu e folafola atu la’u talalelei tumau e faavavau, e tusa ai ma le ia i o ni o latou aiga, ma latou maua ni tupe e ala i meaalofa, e tatau ona latou auina atu ia tupe ia te i latou pe faaaoga mo lo latou lelei, e pei ona faatonuina ai i latou e le Alii, ona ua faapea ona foliga lelei lena mea ia te a’u."},{"verse":104,"text":"Ma ia tuu atu ia te i latou uma o e ua leai ni aiga, o e e maua tupe, e auina atu ia tupe i le epikopo i Siona, po o le epikopo i Ohaio, ina ia faapaiaina mo le aumaia o faaaliga ma lo latou lomiga, ma mo le faatuina o Siona."},{"verse":105,"text":"Ma afai e tuu atu e se tagata i soo se tasi o outou se peleue, po o se suti, ia ave ofu tuai ma tuu atu i e matitiva, ma o i o outou ala ma le olioli."},{"verse":106,"text":"Ma afai e i ai se tagata i totonu o outou ua malosi i le Agaga, ia tuu atu ia te ia na te ave faatasi ma ia lē ua vaivai, ina ia faagaeetiaina o ia i le agamalu atoa, ina ia faamalosia foi o ia."},{"verse":107,"text":"O lea, ia outou ave faatasi ma outou e ua faauuina i le perisitua maualalo, ma auina atu i latou e muamua atu ia te outou e fai tuutuuga, ma saunia le ala, ma faataunuu tuutuuga ua lē mafai e outou lava ona faataunuu."},{"verse":108,"text":"Faauta, o le ala lenei na ati a’e ai e a’u aposetolo, i aso anamua, la’u ekalesia ia te a’u."},{"verse":109,"text":"O lea, ia tuu atu i tagata taitoatasi ia tu i lona lava tofi, ma galue i lona lava valaaulia, ma ia lē tuu atu i le ulu e fai atu i vae ua lē manaomia e ia vae; aua a aunoa ma vae o le a mafai faapefea e le tino ona tu?"},{"verse":110,"text":"E faapea foi le manaomia e le tino ia itutino taitasi uma, ina ia mafai ona faagaeetia uma faatasi, ina ia mafai ona tausi i le atoatoa le faatulagaga."},{"verse":111,"text":"Ma faauta, e tatau i faitaulaga sili ona malaga, ma toeaina foi, ma ositaulaga maualalo foi; ae o tiakono ma a’oa’o e tatau ona tofia e leoleo i luga o le ekalesia, e avea ma auauna nonofo mau mo le ekalesia."},{"verse":112,"text":"Ma e tatau foi i le epikopo, o Newel K. Whitney, ona malaga faataamilo ma i totonu o aulotu uma, e saili e matitiva e fesoasoani i o latou manaoga i le faalotomaualaloina o e mau’oa ma e faamaualuluga."},{"verse":113,"text":"E tatau foi ia te ia ona fai sona sui e galue totogi e pulea ma faia lana pisinisi faaletino e pei ona o le a faatonu ai e ia."},{"verse":114,"text":"Ae ui i lea, ia tuu atu i le epikopo e alu i le aai o Niu Ioka, ma i le aai foi o Albany, ma i le aai foi o Boston, ma lapatai atu i tagata o aai na i le leo o le talalelei, ma se leo tele, e uiga i le faatafunaga ma le faafanoga atoa ua faatalitali mai ia te i latou pe afai latou te teena nei mea."},{"verse":115,"text":"Auā afai latou te teena nei mea, ua lata mai lava le itula o lo latou faamasinoga, ma o lo latou fale o le a tuua tuufua ia te i latou."},{"verse":116,"text":"Ia tuu atu ia te ia e faalagolago mai ia te a’u ma o le a lē faafememea’iina ai o ia; ma o le a lē pa’ū se lauulu o lona ao i le eleele e aunoa ma le iloa."},{"verse":117,"text":"Ma e moni Ou te fai atu ia te outou, a’u auauna o totoe, ia outou o atu pe a mafai ai e tusa ma tulaga ua outou i ai, i o outou valaauga eseese, i aai ma nuu tetele ma ta’uta’ua, ma a’oa’i i le amiotonu le lalolagi e uiga ia latou amioletonu ma galuega uma e lē faale-atua, ma faamatala manino atu ma le malamalama lelei le faatafunaga o mea inosia i aso e gata ai."},{"verse":118,"text":"Auā, o le a ala atu ia te outou, ua fetalai mai ai le Alii Malosi Aoao, ona Ou saeia o latou malo; o le a lē gata ina Ou luluina le lalolagi, ae o le a gatete le lagi ua tumu i fetu."},{"verse":119,"text":"Auā o A’u, o le Alii, ua tuu atu lo’u lima e faagaoioi mana o le lagi; e lē mafai ona outou vaai nei i ai, ae ua toeitiiti ona outou vaai lea i ai, ma iloa ai ua Ou i ai, ma o le a Ou alu atu ma nonofotupu faatasi ma lo’u nuu."},{"verse":120,"text":"O A’u o le Alefa ma le Omeka, o le amataga ma le gataaga. Amene."}]},{"chapter":85,"verses":[{"verse":1,"text":"O le tiute o le failautusi a le Alii, o lē ua tofia e ia, o le tausi o se talafaasolopito, ma se talafaamaumau aoao o le ekalesia o mea uma e tutupu i Siona, ma i latou uma o e ua faapaiaina meatotino, ma maua ni tofi mai le epikopo, e tusa ma tulafono;"},{"verse":2,"text":"Ma o latou olaga foi, o latou faatuatua, ma galuega; ma e uiga foi i tagata liliuese o e e liliuese ua uma ona maua o latou tofi."},{"verse":3,"text":"Ua lē tusa ai ma le finagalo ma le poloaiga a le Atua, le tatau ai ia i latou o e lē mauaina o latou tofi e ala i le faapaiaga, e tusa ai ma lana tulafono, lea ua tuuina mai e ia, ina ia mafai ona totogi sefulua’i a lona nuu, e saunia ai i latou auā le aso o le tauimasui ma le susunuina, ona tusia o latou igoa faatasi ma le nuu o le Atua."},{"verse":4,"text":"Pe ia tausia foi lo latou gafa, pe tuu i se mea e mafai ona maua ai i soo se talafaamaumau po o le talafaasolopito o le ekalesia."},{"verse":5,"text":"O le a lē i ai o latou igoa, po o igoa o o latou tamā, pe tusia igoa o a latou fanau i totonu o le tusi o le tulafono a le Atua, ua fetalai mai ai le Alii o ’Au."},{"verse":6,"text":"Ioe, ua faapea ona fetalai mai o le leo filemu ma le itiiti, lea e musumusu mai ma ati i mea uma, ma o le tele o taimi e faia ai o’u ivi ia luluina a’o faaali mai, ua fetalai mai:"},{"verse":7,"text":"Ma o le a oo mai foi o A’u, o le Alii le Atua, o le a Ou auina atu se ua silisili ma le malosi, ua umia le tootoo o le mana i lona lima, ua la’ei i le malamalama e fai ma ofu, o se o lona fofoga o le a fetalaia afioga, o afioga e faavavau; a’o ona lagona o le a avea o se vaipuna o le upumoni, e faatulaga tatau ai le maota o le Atua, ma fuafua i fasi fanua tofi o le au paia o e ua maua o latou igoa, ma igoa o o latou tamā, ma igoa o a latou fanau, ua tusia i le tusi o le tulafono a le Atua;"},{"verse":8,"text":"A’o le tagata lena, o lē na valaaulia e le Atua ma tofia, e tuu atu lona lima e faasagatonu le ’atolaau a le Atua, o le a pa’ū i le ufanafana o le oti, e pei o se laau e taia i le emo malamalama o le uila."},{"verse":9,"text":"Ma o i latou uma o e e lē maua o latou igoa o tusia i le tusi faamanatu o le a latou lē maua se tofi i lena aso, ae o le a vavae ese i latou, ma o la latou vaega o le a tofi atu ia te i latou i totonu o e e lē talitonu, i le mea ua i ai le tagiaue ma le lilivau o nifo."},{"verse":10,"text":"O nei mea ou te lē fai atu ai a’u lava ia; o lea, e pei ona fetalai mai le Alii, o le a faapea foi ona faataunuuina e ia."},{"verse":11,"text":"Ma o i latou o e o le Perisitua Maualuga, faapea foi ma le perisitua maualalo, po o tagata o le ekalesia, o e o o latou igoa e lē maua o tusia i totonu o le tusi o le tulafono, pe maua ua liliuese, pe ua vavae ese mai le ekalesia, o le a latou lē maua i lena aso se tofi i totonu o le au paia a le Silisili Ese;"},{"verse":12,"text":"O lea, o le a faia ia te i latou e pei ona faia i fanau a le faitaulaga, e pei ona tusia i le mataupu e lua ma le fuaiupu e onosefulu ma le tasi ma le onosefulu ma le lua o le Esera."}]},{"chapter":86,"verses":[{"verse":1,"text":"E moni, ua faapea ona fetalai mai o le Alii ia te outou o a’u auauna, e uiga i le faataoto i saito ma titania:"},{"verse":2,"text":"Faauta, e moni Ou te fai atu, o le fanua o le lalolagi lea, ma o aposetolo o i latou ia o e na luluina fatu;"},{"verse":3,"text":"Ma ina ua uma ona latou momoe, o lē ua faasauā tele i le ekalesia, o lē ua liliuese, o lē o le fafine talitane, o Papelonia lava lea, o lē ua faia atunuu uma ia feinu i lana ipu, o e o o latou loto, ua nofo ai le fili, o Satani lava, e pule ai—faauta, ua lulu e ia titania; o le mea lea, ua tineia ai e le titania le saito ma tuli le ekalesia i le vao."},{"verse":4,"text":"Ae faauta, i aso e gata ai, i le taimi nei lava a’o amata ona aumai e le Alii le upu, ma ua totogo a’e le lau saito ma o loo mu’amu’a lava—"},{"verse":5,"text":"Faauta, e moni Ou te fai atu ia te outou, o loo fetagisi atu agelu i le Alii i le ao ma le po, o e ua sauni ma faatalitali e auina atu e selesele i lalo fanua;"},{"verse":6,"text":"Peitai ua fetalai atu le Alii ia te i latou, aua le lia’iina i luga titania a’o mu’amu’a le lau (aua e moni o loo vaivai lo outou faatuatua), ne’i outou faaumatia ai foi le saito."},{"verse":7,"text":"O lea, ia tuu pea le saito ma le titania e tutupu faatasi seia matua atoa le seleselega; ona outou faaputu ese muamua lea o le saito mai totonu o titania, ma a uma ona faaputuina o le saito, faauta ma tagai, ia fusifusi titania i fusi, ma tuu ai le fanua e susunuina."},{"verse":8,"text":"O lea, ua faapea ona fetalai mai o le Alii ia te outou, o e ua faaauau ai pea le perisitua e ala i le gafa o o outou tamā—"},{"verse":9,"text":"Aua o outou o suli faaletulafono, e tusa ma la le tino, ma na natia mai le lalolagi faatasi ma Keriso i le Atua—"},{"verse":10,"text":"O lea ua tumau ai pea lo outou ola ma le perisitua, ma e tatau lava ona tumau pea e ala atu ia te outou ma lo outou gafa seia oo i le toefuataiga o mea uma na fetalaia mai e fofoga o perofeta paia uma talu mai le amataga o le lalolagi."},{"verse":11,"text":"O lea, amuia lava outou pe afai tou te tumau pea i lo’u agalelei, o se malamalama i Nuuese, ma o se faaola i lo’u nuu o Isaraelu, e ala atu i lenei perisitua. Na fetalai mai ai le Alii. Amene."}]},{"chapter":87,"verses":[{"verse":1,"text":"E Moni, ua faapea ona fetalai mai o le Alii e uiga i taua o le a vave ona oo mai, e amata mai i le fouvalega a Karolaina i Saute, lea e oo ina i’u i le oti ma le pagatia o tagata e toatele;"},{"verse":2,"text":"Ma e oo mai le taimi o le a oo mai ai taua i luga o atunuu uma, e amata mai i le lenei nofoaga."},{"verse":3,"text":"Auā faauta, o le a vavae ese Setete i Saute e faasaga i Setete i Matu, ma o le a valaau atu Setete i Saute i isi atunuu, e oo lava i le atunuu o Peretania Tele, e pei ona ta’ua, ma o le a latou valaau atu foi i isi atunuu, ina ia puipuia i latou lava e faasaga i isi atunuu; ma ona sasao atu ai lea o taua i luga o atunuu uma."},{"verse":4,"text":"Ma o le a oo mai, a mavae aso e tele, o le a tutula’i a’e pologa e faasaga i o latou matai, o e o le a faatulaga ma a’oa’oina mo taua."},{"verse":5,"text":"Ma o le a oo mai foi o vaega o totoe o e o i ai i le laueleele, o le a latou faatulaga i latou lava, ma o le a matuā feita lava, ma o le a latou faatigaina Nuuese i se faatigā tele."},{"verse":6,"text":"Ma o le a faapea, e ala i le pelu ma le faamasaatoto, ona faanoanoa e o nonofo i le lalolagi; ma o le a faia ia lagona e e o nonofo i le lalolagi, e ala i oge, ma mala, ma mafui’e, ma faititili o le lagi, ma uila mata’utia ma le malama foi, le toasa, ma le toatama’i, ma le aao a’oa’i o le Atua Malosi Aoao, seia oo ina uma ona faia e le faafanoga ua faatonuina se i’uga atoatoa o atunuu uma;"},{"verse":7,"text":"Ina ia utu le tagi a le au paia, ma le toto o le au paia, mai le alu a’e i fofoga o le Alii o Sapaota, mai le eleele, ia tauimasui i o latou fili."},{"verse":8,"text":"O le mea lea, ia outou tutula’i ai i nofoaga paia, ma aua le masi’i ese, seia oo mai le aso o le Alii; auā faauta, e vave lava ona oo mai, ua fetalai mai ai le Alii. Amene."}]},{"chapter":88,"verses":[{"verse":1,"text":"E moni, ua faapea ona fetalai mai o le Alii ia te outou o e ua faapotopoto faatasi outou lava ia maua lona finagalo e faatatau ia te outou:"},{"verse":2,"text":"Faauta, ua logomalie lenei mea i lo outou Alii, ma ua olioli agelu i o outou luga; ua oo mai taulaga o a outou talosaga i luga i fofoga o le Alii o Sapaota, ma ua tusifaamaumauina i le tusi o igoa o e ua faapaiaina, i latou ia o le lalolagi selesitila."},{"verse":3,"text":"O le mea lea, Ou te auina atu nei i o outou luga, i luga lava lea o outou o a’u uo, se isi Fesoasoani, o le Agaga Paia lea o le folafolaga, ia mau i o outou loto; o le isi Fesoasoani lea, o lea lava e tasi na Ou folafola atu i o’u soo, e pei ona tusifaamaumauina i le molimau a Ioane."},{"verse":4,"text":"O lenei Fesoasoani o le folafolaga lea o le ola e faavavau Ou te tuu atu ia te outou, o le mamalu lava lea o le malo selesitila;"},{"verse":5,"text":"O le mamalu lena o le ekalesia a le Ulumatua, o le mamalu lava lea o le Atua, o lē ua silisili ona paia i tagata uma, e ala ia Iesu Keriso lona Alo—"},{"verse":6,"text":"O Ia o lē na afio a’e i lugā, e pei foi ona afio ifo o ia i lalo o mea uma, lea na malamalama ai o ia i mea uma, ina ia mafai ona i ai o ia, o le malamalama o le upumoni, i mea uma ma ala atu i mea uma;"},{"verse":7,"text":"O le upumoni lea ua susulu atu. O le malamalama lea o Keriso. E pei foi ona i ai o ia i le la, ma le susulu o le la, ma le mana o i ai, lea na faia ai."},{"verse":8,"text":"E pei foi ona i ai o ia i le masina, ma o le susulu o ia o le masina, ma le mana o i ai, lea na faia ai;"},{"verse":9,"text":"E pei foi o le susulu o fetu, ma le mana o i ai, lea na faia ai;"},{"verse":10,"text":"Ma le lalolagi foi, le lalolagi lava lea o loo outou tutu ai, ma le mana o i ai."},{"verse":11,"text":"Ma o le sulu lea o loo susulu atu, lea ua tuu atu ai ia te outou le malamalama, ua ala mai ia te ia o lē ua faamalamalamaina o outou mata, o le malamalama lava lea e tasi ua faapupulaina o outou malamalamaaga;"},{"verse":12,"text":"O le malamalama lea ua susulu atu mai luma o le Atua e faatumulia ai le loaloa o le vateatea—"},{"verse":13,"text":"O le malamalama lea ua i totonu o mea uma, lea ua tuuina le ola i mea uma, o le tulafono lea ua pulea ai mea uma, o le mana lava lea o le Atua o lē o loo afio i luga o lona nofoalii, o lē o loo i le loto o le faavavau, o lē ua i ai i le totonugalemu o mea uma."},{"verse":14,"text":"O lenei, e moni Ou te fai atu ia te outou, o le togiola ua faia mo outou ua ala mai ai le faataunuuina o le toetutu mai le oti."},{"verse":15,"text":"Ma o le agaga ma le tino o le tagata lea."},{"verse":16,"text":"Ma o le toetu mai le oti o le togiolaina lea o le tagata."},{"verse":17,"text":"Ma o le togiolaina o le tagata ua ala mai lea i lē na te faaolaina mea uma, o lē ua ia folafola i lona loto o le a fai le lalolagi ma tofi o e matitiva ma e agamalu."},{"verse":18,"text":"O lea, e tatau ai ona faapaia le lalolagi mai amioletonu uma, ina ia saunia mo le mamalu selesitila;"},{"verse":19,"text":"Auā a uma ona faataunuu e le lalolagi le faamoemoe o lona foafoaga, o le a faapaleina i le mamalu, i le afio ai lava lea o le Atua le Tamā:"},{"verse":20,"text":"Ina ia mafai e tino o e o le malo selesitila ona mauaina e faavavau faavavau lava; auā, o le faamoemoe lea na faia ma foafoa ai le lalolagi, ma o le faamoemoe lea ua faapaiaina ai i latou."},{"verse":21,"text":"Ma o i latou o e e lē faapaiaina i le tulafono lea na Ou tuu atu ia te outou, le tulafono lava lea a Keriso, e ao ina mautofi i se isi malo, po o lena o se malo terasitila, po o se malo telesitila."},{"verse":22,"text":"Ona o ia o lē e lē mafai ona ola i le tulafono o se malo selesitila e lē mafai ona ia gafatia se mamalu selesitila."},{"verse":23,"text":"Ma o ia o lē e lē mafai ona ola i le tulafono o se malo terasitila e lē mafai ona ia gafatia se mamalu terasitila."},{"verse":24,"text":"Ma o ia o lē e lē mafai ona ola i le tulafono o se malo telesitila e lē mafai ona ia gafatia se mamalu telesitila; o lea ua lē agavaa o ia mo se malo o le mamalu. O lea e ao ai ina mau o ia i se malo e lē o se malo o le mamalu."},{"verse":25,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ua i ai le lalolagi i le tulafono o se malo selesitila, ona ua faataunuu ai le faamoemoega o lona foafoaga, ma lē solia ai le tulafono—"},{"verse":26,"text":"O le mea lea, o le a faapaiaina le lalolagi; ioe, e ui o le a mate, o le a toe faaolaina, ma o le a gafatia le mana lea e faaola ai, ma o le a fai ma tofi o e amiotonu."},{"verse":27,"text":"Auā e ui ina oti i latou, o le a latou toe tutu mai foi, o se tino faaleagaga."},{"verse":28,"text":"O i latou o e o se agaga selesitila o le a latou maua le tino lava e tasi sa o se tino natura; o le a outou maua lava o outou tino, ma o lo outou mamalu o le a o lena mamalu e faaola ai o outou tino."},{"verse":29,"text":"O outou o e e faaolaina e se vaega o le mamalu selesitila o le a outou maua i lena taimi lea lava mamalu e tasi, o se atoatoaga lava."},{"verse":30,"text":"Ma o i latou o e e faaolaina e se vaega o le mamalu terasitila o le a latou maua i lena taimi lea lava mamalu e tasi, o se atoatoaga lava."},{"verse":31,"text":"Ma o i latou foi o e e faaolaina e se vaega o le mamalu telesitila o le a latou maua i le taimi lena lea lava mamalu e tasi, o se atoatoaga lava."},{"verse":32,"text":"Ma o i latou o e e totoe o le a faaolaina foi; ae ui i lea, o le a toe foi atu i latou i lo latou lava nofoaga, e olioli i mea ua latou loto e talia, aua sa latou lē loto e olioli i mea semanū latou te maua."},{"verse":33,"text":"Auā se a le aoga i se tagata pe a tuu atu se meaalofa i ona luga, ae na te lē taliaina le meaalofa? Faauta, e lē olioli o ia i le mea ua tuuina atu ia te ia, pe olioli foi ia te ia o lē na tuuina mai le meaalofa."},{"verse":34,"text":"O lenei foi, e moni ou te fai atu ia te outou, o le mea ua pulea i le tulafono ua faasaoina foi i le tulafono ma ua faaatoatoa ma faapaiaina i lea lava tulafono e tasi."},{"verse":35,"text":"O ia o lē e solia se tulafono, ma lē ola i le tulafono, ae saili e avea ma se tulafono ia te ia lava, ma loto e ola i le agasala, ma ola atoa i le agasala, e lē mafai ona faapaiaina i le tulafono, pe i le alofa mutimutivale, faamasinotonu, po o le faamasinoga. O lea, o le a tumau pea i latou i le eleelea."},{"verse":36,"text":"O malo uma ua i ai se tulafono ua tuuina atu i ai;"},{"verse":37,"text":"Ma e tele malo ua i ai; ona ua leai se avanoa ua lē o i ai se malo; ma ua leai se malo ua lē o i ai se avanoa, pe o se malo tele po o se malo itiiti."},{"verse":38,"text":"Ma ua tuuina atu i malo taitasi se tulafono; ma ua i ai foi i tulafono taitasi ni tuaoi ma ni tuutuuga faapitoa."},{"verse":39,"text":"O tagata uma o e e lē ola i ia tuutuuga e lē ta’uamiotonuina."},{"verse":40,"text":"Ona o le atamai e pipii i le atamai; o le poto e talia le poto; o le upu moni e fusia le upu moni; o le amiomamā e fiafia i le amiomamā; o le malamalama e pipii i le malamalama; o le alofa mutimutivale e agaalofa i le alofa mutimutivale ma aiā i ana lava; o le faamasinotonu e alu pea i lona ala ma aiā i ana lava; e alu atu le faamasinoga i luma o fofoga o ia o lē ua afio i luga o le nofoalii ma pulea ma faia mea uma."},{"verse":41,"text":"Ua malamalama o ia i mea uma, ma ua i ai mea uma i ona luma, ma ua siomia o ia i mea uma; ma ua i ai o ia i luga o mea uma, ma i totonu o mea uma, ma i ai e ala atu i mea uma, ma ua faataamilo i mea uma; ma o mea uma ua ala mai ia te ia, ma e a ia, o le Atua lea, e faavavau faavavau lava."},{"verse":42,"text":"O lenei foi, e moni ou te fai atu ia te outou, ua tuuina mai e ia se tulafono i mea uma, lea ua latou gaoioi ai i o latou taimi ma o latou tau;"},{"verse":43,"text":"Ma o o latou ala ua faia tumau, e oo lava i ala o le lagi ma le lalolagi, lea ua aofia ai le lalolagi ma paneta uma."},{"verse":44,"text":"Ma latou te tuu atu le malamalama i le tasi i o latou taimi ma o latou tau, i o latou minute, i o latou itula, i o latou aso, i o latou vaiaso, i o latou masina, i o latou tausaga—o nei mea uma o se tausaga e tasi i le Atua, ae lē i le tagata."},{"verse":45,"text":"E taavale le lalolagi i luga o ona apaau, ma e tuu mai e le la lona malamalama i le ao, ma e tuu mai e le masina lona malamalama i le po, ma e tuu mai foi e fetu o latou malamalama, a’o taavavale i luga o o latou apaau i lo latou mamalu, i le lotolotoi o le mana o le Atua."},{"verse":46,"text":"O se a se mea Ou te faatusa i ai nei malo, ina ia mafai ona outou malamalama ai?"},{"verse":47,"text":"Faauta, o nei mea uma o malo, ma o soo se tagata ua vaai i soo se tasi po o le aupito itiiti o ia malo, ua vaai i le Atua o femaliua’i i lona mamalu ma lona mana."},{"verse":48,"text":"Ou te fai atu ia te outou, sa vaai o ia ia te ia; ae ui i lea, o ia o lē na afio mai i ona lava, sa lē malamalama i ai."},{"verse":49,"text":"Ua susulu atu le malamalama i le pouliuli, a ua lē malamalama i ai le pouliuli; ae ui i lea, e oo mai le aso o le a outou malamalama ai i le Atua lava, i le faaolaina o outou ia te ia, ma e ia."},{"verse":50,"text":"Ona outou iloa lea ua outou vaai ia te a’u, ua Ou i ai, ma o A’u lea o le malamalama moni ua i totonu ia te outou, ma ua outou i ai i totonu ia te a’u; a lē o lea e lē mafai ona outou uluuluola."},{"verse":51,"text":"Faauta, o le a Ou faatusaina ia malo i se tagata ua i ai se fanua, ma ua ia auina atu ana auauna i le fanua e eli i le fanua."},{"verse":52,"text":"Ma ua fai atu o ia i lē ua muamua: Inā alu atu ia oe ma galue i le fanua, ma o le a ou alu atu ia te oe i le itula muamua, ma o le a e vaai i le olioli o o’u foliga."},{"verse":53,"text":"Ma ua fai atu o ia i lē e lona lua: Inā alu atu ia foi oe i le fanua, ma o le a ou asiasi atu ia te oe i le itula lona lua ma o le a e vaai i le olioli o o’u foliga."},{"verse":54,"text":"Ma i lē e lona tolu foi, ua fai atu i ai: O le a ou asiasi atu ia te oe;"},{"verse":55,"text":"Ma i lē e lona fa, ma faapea lava e oo i lē e lona sefululua."},{"verse":56,"text":"Ma sa alu atu le alii o le fanua i lē na muamua i le itula muamua, ma nonofo faatasi ma ia i le itula atoa lena, ma sa faafiafiaina o ia i le susulu o fofoga o lona alii."},{"verse":57,"text":"Ma ona tuumuli ese ai lea o ia mai lē na muamua ina ia mafai e ia ona asiasi atu foi i lē e lona lua, ma lē e lona tolu, ma lē e lona fa, ma faapea lava e oo atu i lē e lona sefululua."},{"verse":58,"text":"Ma sa faapea ona latou maua uma le susulu o fofoga o lo latou alii, o tagata taitoatasi i lona itula, ma i lona taimi, ma i lona tau—"},{"verse":59,"text":"E amata mai i lē na muamua, ma faapea lava e oo atu i lē e mulimuli, ma mai lē e mulimuli e oo mai i lē na muamua, ma mai i lē na muamua e oo atu i lē e mulimuli;"},{"verse":60,"text":"O tagata taitoatasi i lona lava faasologa, seia uma lona itula, e pei lava ona sa poloaiina ai o ia e lona alii, ina ia faamamaluina lona alii ia te ia, ma ia i lona alii, ina ia mafai ona faamamaluina i latou uma."},{"verse":61,"text":"O lea, Ou te faatusaina nei malo uma i lenei faataoto, ma e o nonofo ai—o malo taitasi i lona itula, ma i lona taimi, ma i lona tau, e tusa lava ma le folafolaga na faia e le Atua."},{"verse":62,"text":"O lenei foi, e moni Ou te fai atu ia te outou, o a’u uo, Ou te tuu atu nei upu ia te outou tou te mafaufau i ai i o outou loto, faatasi ma le poloaiga lenei Ou te tuu atu ia te outou, ia outou valaau mai ia te a’u manū o Ou latalata atu—"},{"verse":63,"text":"Faalatalata mai ia te a’u ma o le a Ou faalatalata atu ai ia te outou; saili mai ia te a’u ma le filiga ma o le a outou maua ai a’u; ole mai, ma o le a outou maua ai; tu’itu’i mai, ma o le a tatala atu ai ia te outou."},{"verse":64,"text":"Soo se mea tou te ole atu ai i le Tamā i lo’u igoa ua tatau ai mo outou, o le a tuuina mai ia te outou;"},{"verse":65,"text":"Ma afai tou te ole atu mo se mea ua lē tatau ai mo outou, o le a liua mo lo outou ta’usalaga."},{"verse":66,"text":"Faauta, o le mea ua outou faalogo mai i ai ua pei o le leo o lē ua alaga i le vao—i le vao, auā ua lē mafai ona outou vaai atu ia te ia—o lo’u leo, auā o lo’u leo o le Agaga lea; o lo’u Agaga o le upumoni lea; e tumau le upumoni ma ua leai sona iuga; ma afai e i ai i totonu o outou o le a uluola."},{"verse":67,"text":"Ma afai e tau-tasi o outou mata i lo’u mamalu, o le a faatumulia o outou tino atoa i le malamalama, ma o le a leai se pouliuli e ia te outou; ma o lena tino ua faatumulia i le malamalama e malamalama i mea uma."},{"verse":68,"text":"O lea, ia outou faapaia outou lava ina ia tau-tasi o outou mafaufau i le Atua, ma e oo mai aso o le a outou vaai ai ia te ia; ona o le a afe ese e ia le veli mai ona fofoga ia te outou, ma o le a faia lena mea i lona lava taimi, ma i lana lava ala, ma e tusa ai ma lona lava finagalo."},{"verse":69,"text":"Ia manatua le folafolaga tele ma le mulimuli lea na Ou fai atu ia te outou; ia lafo mamao ese mai ia te outou o mafaufauga lē aoga ma lo outou ’ata leoleoā."},{"verse":70,"text":"Ia outou nonofo, ia outou nonofo i le nofoaga lenei, ma talo se faapotopotoga paia, e mo i latou lava o e ua muai galulue i le malo mulimuli lenei."},{"verse":71,"text":"Ma ia tuu atu ia te i latou o e na latou lapata’iina ia latou malaga e valaau atu i le Alii, ma mafaufau i o latou loto i le lapataiga ua latou maua, mo se vaitau itiiti."},{"verse":72,"text":"Faauta, ma tagai, o le a Ou tausia a outou lafu, ma o le a Ou faatutuina a’e toeaina ma auina atu ia te i latou."},{"verse":73,"text":"Faauta, o le a Ou faanatinati la’u galuega i lona taimi."},{"verse":74,"text":"Ma Ou te tuu atu ia te outou, o e o tagata galulue muamua i le malo mulimuli lenei, se poloaiga ia outou faapotopoto faatasi outou lava, ma faatulaga outou lava, ma saunia outou lava, ma faapaia outou lava; ioe, ia faamamā o outou loto, ma faamamā o outou lima ma o outou vae i o’u luma, ina ia mafai ona Ou faamamāina outou;"},{"verse":75,"text":"Ina ia mafai ona Ou molimau atu i lo outou Tamā, ma lo outou Atua, ma lo’u Atua, ua outou mamā mai le toto o lenei tupulaga amioleaga; ina ia mafai ona Ou faataunuuina lenei folafolaga, lenei folafolaga tele ma le mulimuli, lea na Ou fai atu ia te outou, pe a Ou loto i ai."},{"verse":76,"text":"O lenei foi, Ou te tuu atu ia te outou se poloaiga ia outou faaauau pea i le tatalo ma le anapogi mai le taimi nei ma le agai i luma."},{"verse":77,"text":"Ma Ou te tuu atu ia te outou se poloaiga ia outou a’oa’o atu le tasi i le isi aoaoga faavae o le malo."},{"verse":78,"text":"Ia outou a’oa’o atu ma le filiga ma o le a i ai lo’u alofa tunoa ia te outou, ina ia mafai ona a’oa’oina atoatoa atili outou i teori, i mataupu faavae, i aoaoga faavae, i le tulafono o le talalelei, i mea uma tau i le malo o le Atua, ua tatau mo outou ona malamalama i ai;"},{"verse":79,"text":"O mea o i le lagi ma o i le lalolagi, ma o i lalo o le lalolagi; o mea sa i ai, o mea o i ai, o mea ua vave ona oo mai; o mea o loo i le atunuu, o mea o i isi atunuu; o taua ma faafatiatama’i o atunuu, ma faamasinoga o loo i luga o le laueleele; ma se malamalama foi i atunuu ma malo—"},{"verse":80,"text":"Ina ia mafai ona outou saunia i mea uma pe a Ou toe auina atu outou e faalautele le valaauga lea ua Ou valaaulia i ai outou, ma le misiona lea ua Ou tofia ai outou."},{"verse":81,"text":"Faauta, na Ou auina atu outou e molimau ma lapatai atu i tagata, ma ua tatau i tagata taitoatasi o e ua uma ona lapata’ia ona lapatai atu i lē la te tuaoi."},{"verse":82,"text":"O lea, e tuu ai i latou e aunoa ma se ’alofaga, ma ua i luga o o latou lava ulu a latou agasala."},{"verse":83,"text":"O ia o lē e saili vave mai ia te a’u o le a ia maua a’u, ma o le a lē tuulafoaiina."},{"verse":84,"text":"O lea, ia outou nonofo ai, ma galulue ma le filiga, ina ia mafai ona faaatoatoaina outou i la outou auaunaga e o atu i totonu o Nuuese i le taimi mulimuli, e tusa ma le toatele e ta’u mai e le fofoga o le Alii, e fusifaamau le tulafono ma faamau le molimau, ma saunia le au paia mo le itula o le faamasinoga o le a oo mai;"},{"verse":85,"text":"Ina ia mafai ona sao o o latou agaga mai le toasa o le Atua, o le faatafunaga lea o mea inosia o loo faatali mai mo e amioleaga, i le lalolagi lenei ma le lalolagi a sau. E moni, Ou te fai atu ia te outou, ia tuu atu ia te i latou o e e lē o toeaina muamua, e faaauau pea i le tovine seia fetalai mai le fofoga o le Alii ia te i latou, ona e le’i oo mai lo latou taimi; e le’i mamā o latou ofu mai le toto o lenei tupulaga."},{"verse":86,"text":"Ia outou ola i le saolotoga ua faasaolotoina ai outou; aua tou te faalavelaveaina outou lava i le agasala, ae ia tausi o outou lima ia mamā, seia afio mai le Alii."},{"verse":87,"text":"Auā ua lē toe tele ni aso mai le taimi nei, o le a luluina ma taumālua solo ai le eleele e pei o se tagata ’onā; ma o le a pupuni ai e le la lona pupula, ma o le a musu ai e tuu mai le malamalama; ma o le a gasetoto le masina; ma o le a feitai tele fetu, o le a latou faapa’u’ū ifo i latou lava i lalo e pei o se fua o se mati e pa’ū ifo mai se laau o le mati."},{"verse":88,"text":"Ma a mavae la outou molimau o le a oo mai le toasa ma le toatama’i i luga o tagata."},{"verse":89,"text":"Auā a mavae la outou molimau o le a oo mai le molimau a mafui’e, lea o le a tupu mai ai le oi i totonu o ia, ma o le a pa’u’ū ifo tagata i luga o le eleele ma o le a lē mafai ona tutū."},{"verse":90,"text":"Ma o le a oo mai foi le molimau a le leo o faititili, ma le leo o uila, ma le leo o ta’uta’u, ma le leo o galu o le sami e fafati mai i latou lava e tia’ina o latou tuaoi."},{"verse":91,"text":"Ma o le a vāvāō mea uma; ma e moni lava, o le a pepē fatu o tagata; ona o le a oo mai le mata’u i luga o tagata uma."},{"verse":92,"text":"Ma o le a felelei agelu i le taulotoa’iga o le lagi, ma alalaga atu i se leo tele, ma ili atu le pu a le Atua, e fai atu: Ia outou saunia ia, ia outou saunia ia, outou e ua nonofo i le lalolagi; ona ua oo mai le faamasinoga a lo tatou Atua. Faauta, ma tagai, ua afio mai le Faatoafaiavā; inā outou o atu ia e fetaia’i ma ia."},{"verse":93,"text":"Ma e lē pine ae o le a faailoa mai se faailoga tele i le lagi, ma o le a vaai faatasi i ai tagata uma."},{"verse":94,"text":"Ma o le a ili e le tasi agelu lana pu, fai mai: O lena ekalesia tele, o le tinā o mea inosia, o lē na faia i atunuu uma ia feinu i le uaina o le toasa o lona faitaaga, o lē ua sauaina le au paia a le Atua, o lē ua faamasaaina o latou toto—o ia o lē ua nofo i luga o vai e tele, ma i luga o motu o le sami—faauta, o ia lea o titania o le lalolagi; ua fusifusia o ia i ni fusi, ua faamalosia ona nonoa, e leai se tagata e mafai ona tatalaina; o lea, ua saunia o ia e susunuina. Ma o le a ili umi ma leo tele e le agelu lana pu, ma o le a lagona e atunuu uma."},{"verse":95,"text":"Ma o le a i ai se taaligoligoa i le lagi mo le va o le afa itula; ma e lē pine lava ona mavae, ae o le a tatalaina le pupuni o le lagi, e pei ona tatalaina se tusitaai pe a uma ona taai, ma o le a afe ese le veli mai fofoga o le Alii;"},{"verse":96,"text":"Ma o le au paia e i ai i luga o le lalolagi, o e o ola, o le a liua ma segia i luga e feitaia’i ma ia."},{"verse":97,"text":"Ma o i latou o e na momoe i o latou tuugamau, o le a tutulai mai, ona o le a tatalaina o latou tuugamau; ma o le a segia foi i latou i luga e fetaia’i ma ia i le taulotoa’iga o le poutu o le lagi—"},{"verse":98,"text":"O i latou ia o a Keriso, o faapolopolo muamua, o i latou ia o e o le a o ifo muamua faatasi ma ia, ma i latou o e o i luga o le lalolagi ma o i totonu o o latou tuugamau, o e e muamua ona segia i luga e feitaia’i ma ia; ma o lenei mea atoa e faia i le leo o le ili mai o le pu a le agelu a le Atua."},{"verse":99,"text":"Ma a mavae lea, o le a ili mai se tasi agelu, o le pu lona lua lea; ma ona oo mai ai lea o le togiolaina o i latou o e ua a Keriso i lona afio mai; o e ua latou maua la latou vaega i le falepuipui lena ua saunia mo i latou, ina ia mafai ona latou maua o le talalelei, ma faamasinoina e tusa ma tagata i la le tino."},{"verse":100,"text":"O lenei foi, o le a ili mai se tasi pu, o le pu lona tolu lea; ma ona o mai ai lea o agaga o tagata o e o le a faamasinoina, ma ua maua i lalo o le ta’usalaga;"},{"verse":101,"text":"Ma o i latou ia o totoe o e ua oti; ma e lē toe ola mai i latou seia uma le afe o tausaga, e lē toe ola mai lava, seia oo i le iuga o le lalolagi."},{"verse":102,"text":"Ma o le a ilia se tasi pu, o le pu lona fa lea, fai mai: Ua i ai i totonu o i latou o e ia tuu pea seia oo i lena aso tele ma le gataaga, o le iuga lea, o e o le a tumau pea i le eleelea."},{"verse":103,"text":"Ma o le a ilia se tasi pu, o le pu lona lima lea, o le agelu lona lima lea o lē ua ia tuuina atu le talalelei tumau e faavavau—ua lele atu i le taulotoa’iga o le lagi, i atunuu uma, ituaiga, gagana, ma nuu;"},{"verse":104,"text":"Ma o le leo lenei o lana pu, e fetalai atu i tagata uma, i e o i le lagi ma e o i le lalolagi, ma e o i lalo o le lalolagi—ona o le a lagona e taliga uma, ma o le a tootutuli tulivae uma, ma o le a ta’uta’u atu e laulaufaiva uma, a’o latou faalogoina le leo o le pu, ua fai mai: Ia matata’u i le Atua, ma avatu le mamalu ia te ia o lē o afio i luga o le nofoalii, e faavavau faavavau lava; ona ua oo mai le itula o lana faamasinoga."},{"verse":105,"text":"O lenei foi, o le a ilia e se tasi agelu lana pu, o le agelu lona ono lea, ua fai mai: Ua pa’ū le fafine o lē na ia faia ia inu atunuu uma i le uaina o le toasa o lona faitaaga; ua pa’ū o ia, ua pa’ū lava!"},{"verse":106,"text":"O lenei foi, o le a ilia e se tasi agelu lana pu, o le agelu lona fitu lea, ua fetalai mai: Ua mae’a; ua mae’a! Ua manumalo le Tamai Mamoe a le Atua ma ua soli toatasi e ia le soligāvine, o le soligāvine lava lea o le mata’utia o le toasa o le Atua Malosi Aoao."},{"verse":107,"text":"Ma ona faapaleina ai lea o agelu i le mamalu o lona malosi, ma o le a faatumuina le au paia i lona mamalu, ma maua lo latou tofi ma faia i latou ia tutusa ma ia."},{"verse":108,"text":"Ma ona toe ili lea e le agelu muamua lana pu i taliga o tagata ola uma, ma faaalia galuega lilo a tagata, ma galuega ofoofogia a le Atua i le uluai afe o tausaga."},{"verse":109,"text":"Ma ona ili ai lea e le agelu lona lua lana pu, ma faaalia galuega lilo a tagata, ma mafaufauga ma faamoemoega o o latou loto, ma galuega ofoofogia a le Atua i le afe lona lua o tausaga—"},{"verse":110,"text":"Ma faapea lava ona faasolo, seia oo ina ili e le agelu lona fitu lana pu; ma o le a tu atu o ia i luga o le laueleele ma luga o le sami, ma tauto atu i le suafa o ia o lē ua afio i luga o le nofoalii, ua lē toe i ai se taimi; ma o le a noatia Satani, le gata tuai lena, o lē ua ta’ua o le tiapolo, ma o le a lē tatalaina mo le va o se afe o tausaga."},{"verse":111,"text":"Ma ona tatala ai lea o ia mo se vaitau itiiti, ina ia mafai ona faapotopoto faatasi e ia ana autau."},{"verse":112,"text":"Ma o Mekaeli, le agelu lona fitu, le agelu silisili lea, o le a faapotopoto faatasi e ia ana autau, o ’au lava ia o le lagi."},{"verse":113,"text":"Ma o le a faapotopoto faatasi e le tiapolo ana autau; o ’au lava ia o seoli, ma o le a o mai i luga e tau faasaga ia Mekaeli ma ana autau."},{"verse":114,"text":"Ma ona oo mai ai lea o le taua a le Atua silisili; ma o le a lafo ese le tiapolo ma ana autau i lo latou lava nofoaga, o le a latou lē toe maua se mana i luga o le au paia."},{"verse":115,"text":"Auā o le a tau e Mekaeli a latou taua, ma o le a manumalo ia te ia o lē ua saili i le nofoalii o ia o lē ua afio i luga o le nofoalii, o le Tamai Mamoe lava lea."},{"verse":116,"text":"O le mamalu lava lea o le Atua, ma e ua faapaiaina; ma o le a latou lē toe vaai i le oti."},{"verse":117,"text":"O lea, e moni Ou te fai atu ia te outou, a’u uo, ia talo sa outou faapotopotoga paia, e pei ona Ou poloaiina ai outou."},{"verse":118,"text":"Ma talu ona ua lē i ai i tagata uma le faatuatua, ia outou saili ma le filiga ma aoao atu e le tasi i le isi upu o le poto; ioe, ia outou saili mai totonu o tusi sili ona lelei upu o le poto; saili i le aoaoina, e ala lava lea i le suesue ma le faatuatua foi."},{"verse":119,"text":"Ia outou faatulaga tatau outou lava; ia saunia mea manaomia uma; ma faatuina se fale, o se fale tatalo lea, o se fale o le anapogi, o se fale o le faatuatua, o se fale o le a’oa’oga, o se fale o le mamalu, o se fale maopoopo, o se fale o le Atua;"},{"verse":120,"text":"Ina ia faia a outou ulufale mai i le suafa o le Alii; ina ia faia a outou ulufafo atu i le suafa o le Alii; ina ia faia a outou feofoofoa’iga i le suafa o le Alii, ma lima ua sii atu i le Silisili Ese."},{"verse":121,"text":"O lea, ia taofi mai ia outou upu faatauvaa uma, mai toēēga uma, mai o outou manao tuinanau uma, mai lo outou faamaualuga ma manatu-māmā uma, ma mai ia outou amioleaga uma o fai."},{"verse":122,"text":"Tofi se faiaoga i totonu o outou lava, ma ia lē tuu atu i tagata uma e tāutatala i le taimi e tasi; ae tuu atu i tagata e tautala taitoatasi mai ae tuu i isi tagata uma e faalogologo i ana upu, ina a uma ai ona tautala mai o tagata uma, o le a faapea ona mafai ona faagaeetia ai o tagata uma, ma ina ia mafai ona maua ai e tagata taitoatasi le avanoa tutusa."},{"verse":123,"text":"Vaai ia outou alofa o le tasi i le isi; tuu le losilosivale; a’oa’o e fetufaai o le tasi ma le isi e pei ona manaomia i le talalelei."},{"verse":124,"text":"Tuu le faapaiē; tuu le lē mamā, tuu le fai pona o le tasi i le isi; tuu le moe umi nai lo le mea e tatau ai; vave momoe, ina ia outou lē vaivai; alapo a’e, ina ia olaola o outou tino ma o outou mafaufau."},{"verse":125,"text":"Ma silisili i luga o mea uma, ia outou faaoofu outou lava i le fusi o le alofa mama, e pei o se ofutalaloa, o le fusi lea o le atoatoa ma le filemu."},{"verse":126,"text":"Ia tatalo e lē aunoa, ina ia outou lē vaivai, seia Ou alu atu. Faauta, ma tagai, e vave ona Ou alu atu, ma ave outou mo a’u lava. Amene."},{"verse":127,"text":"O lenei foi, o le faatulagaga o le fale ua saunia mo le au peresitene o le a’oga a perofeta, ua faatuina mo lo latou a’oa’oina i mea uma e tatau ai mo i latou, e oo lava mo le au mautofi uma o le ekalesia, po o ua faapea, o i latou ia o e ua valaaulia i le auaunaga i le ekalesia, e amata mai i faitaulaga sili, e oo atu lava i lalo i tiakono—"},{"verse":128,"text":"Ma o le faatulagaga lenei o le fale o le au peresitene o le a’oga: O ia o lē e tofia e avea ma peresitene, po o le faiaoga, ia tu i lona tulaga, i le fale o le a saunia mo ia."},{"verse":129,"text":"O lea, ia muamua o ia i le maota o le Atua, i se mea e mafai ai e le faapotopotoga ona lagona lelei mai ma le manino ana upu, e lē o le leo tele."},{"verse":130,"text":"Ma a sau o ia i le maota o le Atua, ona o ia e tatau ona muamua i totonu o le maota—faauta, ua matagofie lenei mea, ina ia avea o ia o se faataitaiga—"},{"verse":131,"text":"Ia tuu atu ia te ia e ofo atu o ia lava i le tatalo i luga o ona tulivae i luma o le Atua, i le faailoga po o le faatusa o le feagaiga tumau e faavavau."},{"verse":132,"text":"Ma a i ai se tasi e sau i totonu mulimuli mai ia te ia, ia tuu atu i le faiaoga e tulai, ma, faatasi ma lima ua sii i luga i le lagi, ioe, faasasa’o lava, faafeiloa’i lona uso po o uso, i upu nei:"},{"verse":133,"text":"O oe ea o se uso po o ni uso? Ou te faafeiloa’i ia te oe i le suafa o le Alii o Iesu Keriso, i le faailoga po o le faatusa o le feagaiga tumau e faavavau, le feagaiga lea ou te talia ai oe i le usoga, i se tautinoga e tumau, e lē maluelue, ma lē masuia, e avea ma au uo ma ou uso e ala i le alofa tunoa o le Atua i fusi o le alofa, e savavali i poloaiga uma a le Atua ma le lē ponā, i le faafetai, e faavavau faavavau lava. Amene."},{"verse":134,"text":"Ma o ia o lē e maua ua lē agavaa i lenei faafeiloaiga ia lē i ai se nofoaga i totonu o outou; auā e le tatau ona outou faatagaina lo’u fale ia faaeleeleaina e ia."},{"verse":135,"text":"Ma o ia o lē e sau i totonu ma ua faamaoni i o’u luma, ma o ia o se uso, po o i latou o ni uso, ia latou faafeiloa’i le peresitene po o le faiaoga i lima ua sisii i le lagi, faatasi ma lenei lava tatalo ma le feagaiga, po o le fai atu Amene, i le faailoga o lea lava tatalo ma le feagaiga."},{"verse":136,"text":"Faauta, e moni, Ou te fai atu ia te outou, o se faataitaiga lenei mo outou mo se faafeiloa’iga o le tasi i le isi i totonu o le maota o le Atua, i le a’oga a perofeta."},{"verse":137,"text":"Ma ua valaauina outou e fai lenei mea i le tatalo ma le faafetai, e pei ona o le a fetalai atu ai le Agaga ia outou i mea uma e fai i totonu o le maota o le Alii, i le a’oga a perofeta, ina ia avea ma maluapapa, o se fale fetafa’i o le Agaga Paia mo lo outou faagaeetiaga."},{"verse":138,"text":"Ma ia outou lē taliaina i lenei a’oga se tasi i totonu o outou vagana ai ua mamā o ia mai le toto o lenei tupulaga;"},{"verse":139,"text":"Ma ia taliaina o ia e ala i le sauniga o le mulumuluga o vae, ona o le faamoemoe lea na faatuina ai le sauniga o le mulumuluga o vae."},{"verse":140,"text":"O lenei foi, o le sauniga o le mulumuluga o vae ia faia e le peresitene, po o le toeaina pulefaamalumalu o le ekalesia."},{"verse":141,"text":"Ia amata i le tatalo; ma a uma ona taumafa o le areto ma le uaina, ia faaofu e ia o ia lava e tusa ma le ala ua tuuina mai i le mataupu e sefulutolu o le molimau a Ioane e uiga ia te a’u. Amene."}]},{"chapter":89,"verses":[{"verse":1,"text":"O Se Upu o le Poto, mo le lelei o le fono a faitaulaga sili, na faapotopoto i Katelani, ma le ekalesia, ma le au paia foi i Siona—"},{"verse":2,"text":"E auina atu i le faafeiloai atu; e lē i se poloaiga po o se faamalosiga, ae ala i le faaaliga ma le upu o le poto, e faailoa atu ai le faatonuga ma le finagalo o le Atua i le faaolataga faaletino o le au paia uma i aso e gata ai—"},{"verse":3,"text":"Ua tuuina mai o se mataupu faavae faatasi ai ma se folafolaga, ua fuafua i le malosi o lē ua vaivai ma lē ua sili atu ona vaivai o le au paia atoa, o e ua ta’ua pe mafai ona ta’ua o le au paia."},{"verse":4,"text":"Faauta, e moni, ua faapea ona fetalai mai le Alii ia te outou: Ona o mea leaga ma fuafuaga ua i ai ma o le a i ai i loto o tagata faufau leaga i aso e gata ai, ua Ou lapata’ia ai outou, ma muai lapata’ia ai outou, i le tuuina atu ia te outou o le upu o le poto lenei e ala i se faaaliga—"},{"verse":5,"text":"E faapea, e tusa ai ma le inu o se tagata i le uaina po o le ava malosi, faauta ua lē lelei lea, pe ua tatau ai foi i le silafaga a lo outou Tamā, tau lava i le faapotopotoina faatasi o outou e osi a’e a outou faamanatuga i ona luma."},{"verse":6,"text":"Ma, faauta, e tatau ai i lea le uaina, ioe, le uaina mama lea o le fua o le vine, o la outou lava faiga."},{"verse":7,"text":"Ma faapea foi, o ava malolosi ua lē mo le manava, ae ua mo le fufuluina o o outou tino."},{"verse":8,"text":"O lenei foi, o le tapaa ua lē mo le tino, pe mo le manava, ma ua lē lelei mo le tagata, ae o se laau-afu mo uno’oa ma povi mama’i uma, ia faaaoga ma le faautauta ma le atamai."},{"verse":9,"text":"O lenei foi, o mea inu vevela ua lē mo le tino po o le manava."},{"verse":10,"text":"O lenei foi, e moni Ou te fai atu ia te outou, o laau-afu lelei uma ua faauuina e le Atua mo le uiga, natura, ma le faaaogaina e le tagata—"},{"verse":11,"text":"O laau-afu taitasi i lona lava tau, ma fualaau’aina taitasi i lona lava tau; o nei mea uma ia faaaoga ma le faautauta ma le faafetai."},{"verse":12,"text":"Ioe, o aano foi o manu ma manufelelei o le ea, o A’u, o le Alii, ua Ou faauuina mo le faaaogaina e le tagata ma le faafetai; ae ui i lea, ia itiiti ona faaaoga o ia mea;"},{"verse":13,"text":"Ma ua lelei ia te a’u le lē tatau ona faaaogaina o ia mea, tau lava na o taimi o le kiona, po o le malulu, po o le oge."},{"verse":14,"text":"O saito uma ua faauuina mo le faaaogaina e le tagata atoa ma manu, e fai ma matai’ai o le ola, ua lē na o mo le tagata ae ua mo manu foi o le fanua, ma manufelelei o le lagi, ma manu aivao uma e taufetuli pe fetolofi i luga o le lalolagi;"},{"verse":15,"text":"Ma o nei mea ua faia e le Atua mo le faaaogaina e le tagata i na o taimi o oge ma le mafatia i le fia ’ai."},{"verse":16,"text":"O saito uma ua lelei mo meaai a le tagata; e faapea foi fua o le vine; o mea uma e fua mai, pe e i totonu o le eleele po o luga o le eleele—"},{"verse":17,"text":"Ae ui i lea, o le saito mo le tagata, ma le sana mo le povi, ma ’ate mo le solofanua, ma le kaseme mo manufelelei ma meatuaolō, ma mo manu uma o le fanua, ma le karite mo manu aoga uma, ma mo mea inu vaivai, e pei foi o isi saito."},{"verse":18,"text":"Ma o le au paia uma o e e manatua e tausi ma faia nei upu, ma savavali i le usiusitai i poloaiga, o le a latou maua le maloloina i o latou pute ma le su i o latou ivi;"},{"verse":19,"text":"Ma o le a latou maua le poto ma ’oa silisili o le malamalama, o ’oa natia lava;"},{"verse":20,"text":"Ma o le a taufetuli ae lē vaivai, ma o le a savavali ae lē matapogia."},{"verse":21,"text":"Ma o A’u, o le Alii, Ou te tuu atu ia te i latou se folafolaga, e faapea o le a laaloa le agelu o le faafanoga ia te i latou, e pei o le fanauga a Isaraelu, ma lē fasiotia i latou. Amene."}]},{"chapter":90,"verses":[{"verse":1,"text":"Ua faapea ona fetalai mai o le Alii, e moni, e moni Ou te fai atu ia te oe lo’u atalii, ua faamagaloina oe i au agasala, e tusa ma lau olega, ona ua oo mai i o’u luma au tatalo ma tatalo a ou uso."},{"verse":2,"text":"O lea, ua faamanuiaina oe mai le taimi nei ma le agai i luma o lē ua umia ki o le malo ua tuu atu ia te oe; o le malo lea ua oo mai mo le taimi mulimuli."},{"verse":3,"text":"E moni Ou te fai atu ia te oe, o ki o lenei malo o le a lē aveesea lava mai ia te oe, a’o e i ai i le lalolagi, pe i le lalolagi a sau;"},{"verse":4,"text":"Ae ui i lea, o le a ala atu ia te oe ona tuuina atu o faaaliga i se tasi, ioe, i le ekalesia lava."},{"verse":5,"text":"Ma o i latou uma o e e mauaina faaaliga a le Atua, ia tuu atu ia te i latou ia faaeteete i le ala latou te umia ai i latou, ne’i o latou manatu i ai e pei o se mea māmā, ma faapea ona aumai ai i latou i lalo o le ta’usalaga, ma tautevateva ma pa’u’ū ai pe a oo mai afā, ma agi mai matagi, ma to mai uaga, ma taia i luga o o latou fale."},{"verse":6,"text":"O lenei foi, e moni Ou te fai atu i ou uso, o Sini Rikitone ma Frederick G. Williams, ua faamagaloina foi a la’ua agasala mai ia te i la’ua, ma ua faitau tutusa i la’ua ma oe i le umiaina o ki o le malo mulimuli lenei;"},{"verse":7,"text":"Ma e ala atu foi i lau taitaiga ki o le a’oga a perofeta, lea na Ou poloaiina ia faatulagaina;"},{"verse":8,"text":"Ina ia faapea ona mafai ai ona faaatoatoaina o i la’ua i la la’ua auaunaga mo le faaolataga o Siona, ma atunuu o Isaraelu, ma Nuuese, e tusa ma le toatele e talitonu;"},{"verse":9,"text":"Ina ia mafai, e ala atu i lau taitaiga, ona la’ua maua le afioga, ma ina ia mafai, e ala i la la’ua taitaiga, ona alu atu o le afioga i tuluiga o le lalolagi, e muamua i Nuuese, ma, faauta ma tagai, ona la’ua liliu atu ai lea i tagata Iutaia."},{"verse":10,"text":"Ma ona oo mai lea o le aso o le a faaali mai ai le aao o le Alii i le mana, i le faatalitonuina o atunuu, o atunuu faapaupau, o le aiga o Iosefa, e uiga i le talalelei o lo latou faaolataga."},{"verse":11,"text":"Auā o le a oo mai, i lena aso, o le a faalogo ai tagata taitoatasi i le atoatoaga o le talalelei i lana lava tautala, ma i lana lava gagana, e ala mai ia te i latou ua faauuina i lenei mana, e ala i le taitaiga a le Fesoasoani, e liligi ifo i luga o i latou mo le faaaliga o Iesu Keriso."},{"verse":12,"text":"Ma o lenei, e moni Ou te fai atu ia te oe, Ou te tuu atu ia te outou se poloaiga, ia outou faaauau pea i le auaunaga faapea ma le au peresitene."},{"verse":13,"text":"Ma a uma ona e faamae’aina o le faaliliuga o tusi a perofeta, ona e pulefaamalumalu lea mai le taimi lena i luga o mataupu o le ekalesia ma le a’oga;"},{"verse":14,"text":"Ma e maua mai lea taimi i lea taimi, e pei ona o le a faaali atu e le Fesoasoani, faaaliga e tatala atu ai mealilo o le malo;"},{"verse":15,"text":"Ma faatulaga tatau aulotu, ma suesue ma a’oa’o, ma faamasani i tusi lelei uma, ma gagana, tautala, ma tagata."},{"verse":16,"text":"Ma ia avea lea ma o outou valaauga ma misiona i o outou olaga atoa, e pulefaamalumalu i fono, ma faatulaga tatau mataupu uma o lenei ekalesia ma le malo."},{"verse":17,"text":"Aua le maasiasi, pe matamuli; ae ia tima’ia outou i lo outou faasausili ma le faamaualuga, auā e aumai ai se mailei i luga o o outou agaga."},{"verse":18,"text":"Faatulaga tatau o outou fale; tuu mamao ese atu mai ia te outou le faapaiē ma le lē tu mamā."},{"verse":19,"text":"O lenei, e moni Ou te fai atu ia te oe, ia i ai se nofoaga e saunia, i le vave e mafai ai, mo le aiga o lou fesoasoani ma lau tusiupu, o Frederick G. Williams lea."},{"verse":20,"text":"Ma ia tuu i la’u auauna matua, o Iosefa Samita, Matua, e nonofo pea ma lona aiga i le nofoaga o loo nofo ai nei o ia; ma ia lē tuuina atu e faatau atu se’i ta’u atu e le fofoga o le Alii."},{"verse":21,"text":"Ma ia tuu i lo’u fesoasoani, o Sini Rikitone lea, e nofo pea i le nofoaga o loo alaala ai nei o ia, sei ta’u atu e le fofoga o le Alii."},{"verse":22,"text":"Ma ia tuu atu i le epikopo e saili ma le filiga ia maua se sui, ma ’ia fai o ia o se tagata o sē ua i ai ni ’oa ua teuina—o se tagata o le Atua, ma le faatuatua malosi—"},{"verse":23,"text":"Ina ia mafai ai ona ia totogiina o aitalafu uma; ina ia lē mafai ona aumai o le faleteuoloa o le Alii ia ta’uleagaina i luma o mata o tagata."},{"verse":24,"text":"Saili ma le filiga, tatalo e lē aunoa, ma ia talitonu, ma o le a galulue faatasi mea uma mo lo outou lelei, pe afai tou te savavali sa’o ma manatua le feagaiga na outou osifeagaiga ai o le tasi ma le isi."},{"verse":25,"text":"Ia faatoaitiitia o outou aiga, aemaise lava la’u auauna matua o Iosefa Samita, Matua, e faatatau ia te i latou o e e lē o ni o outou aiga;"},{"verse":26,"text":"Ina ia lē aveesea mai ia te outou, mea na ua saunia mo outou, e faataunuu ai la’u galuega, ma tuu atu ia te i latou o e ua lē agavaa—"},{"verse":27,"text":"Ma faapea ona ponatia ai o outou mai le faataunuuina o mea na ua Ou poloaiina ai outou."},{"verse":28,"text":"O lenei foi, e moni Ou te fai atu ia te outou, o lo’u loto e tatau i la’u auauna-fafine o Vienna Jaques ona maua tupe e totogi ai ana mea e faatau, ma alu a’e i luga i le laueleele o Siona;"},{"verse":29,"text":"Ma o tupe e totoe ia faapaia mai ia te a’u, ma o le a tauia o ia i lo’u lava taimi e tatau ai."},{"verse":30,"text":"E moni Ou te fai atu ia te outou, ua talafeagai i la’u vaai le tatau ai ona alu atu o ia i luga i le laueleele o Siona, ma maua se tofi mai le lima o le epikopo;"},{"verse":31,"text":"Ina ia mafai ona nofo lelei o ia i le filemu e tusa ai ma lona faamaoni, ma lē faapaiē i ona aso mai le taimi nei ma le agai i luma."},{"verse":32,"text":"Ma faauta, e moni Ou te fai atu ia te outou, ia outou tusia lenei poloaiga, ma fai atu i o outou uso i Siona, i le faafeiloa’i atu i le alofa, ua Ou valaaulia foi outou e pulefaamalumalu i luga o Siona i lo’u lava taimi e tatau ai."},{"verse":33,"text":"O lea, ia tuu atu ia te i latou ia tuu le faalavelave mai ia te a’u e faatatau i lenei mataupu."},{"verse":34,"text":"Faauta, Ou te fai atu ia te outou ua amata ona salamo o outou uso i Siona, ma ua olioli agelu i luga o i latou."},{"verse":35,"text":"Ae ui i lea, e tele mea ua Ou lē fiafia i ai; ma ua Ou lē fiafia i la’u auauna o William E. McLellin, pe i la’u auauna o Sini Gilbert; ma ua i ai foi i le epikopo, ma isi, le tele o mea ia salamo ai."},{"verse":36,"text":"Peitai e moni Ou te fai atu ia te outou, o A’u, o le Alii, o le a Ou finau ma Siona, ma aioi atu i ona tagata malolosi, ma a’oa’i o ia seia manumalo ma faamamāina i o’u luma."},{"verse":37,"text":"Ona o le a lē aveesea o ia mai lona nofoaga. O A’u, o le Alii, ua tautala atu ai. Amene."}]},{"chapter":91,"verses":[{"verse":1,"text":"E moni, ua faapea ona fetalai mai o le Alii ia te outou e uiga i le Apokarifa—E tele mea ua i ai i totonu ua moni, ma o le tele ua sa’o ona faaliliuina;"},{"verse":2,"text":"E tele mea ua i ai i totonu ua lē moni, o ni faaopoopoga na faia e lima o tagata."},{"verse":3,"text":"E moni, Ou te fai atu ia te outou, ua lē manaomia le tau faaliliuina o le Apokarifa."},{"verse":4,"text":"O lea, ai se e faitau i ai, ia tuu atu ia te ia ia malamalama i ai, ona o le Agaga e faaalia mai le moni;"},{"verse":5,"text":"Ma ai se e faapupulaina e le Agaga o le a maua mai ai e ia le aogā;"},{"verse":6,"text":"Ma ai se na te lē mauaina e ala i le Agaga, e lē mafai ona aogā i ai. O lea ua lē manaomia ai ona tau faaliliuina. Amene."}]},{"chapter":92,"verses":[{"verse":1,"text":"E moni, ua faapea ona fetalai mai o le Alii, Ou te tuu atu i le faatulagaga autasi, ua faatulagaina e tusa ma le poloaiga na tuuina atu muamua, se faaaliga ma se poloaiga e faatatau i la’u auauna o Frederick G. Williams, ia outou talia o ia i totonu o le faatulagaga. O le mea Ou te fai atu ai i le toatasi Ou te fai atu ai i tagata uma."},{"verse":2,"text":"O lenei foi, Ou te fai atu ia te oe la’u auauna o Frederick G. Williams, ia avea oe ma se uso toaga i lenei faatulagaga; ma e tusa ai ma lou faamaoni i le tausiga o poloaiga uma na tuu atu muamua, o le a faamanuiaina oe e faavavau. Amene."}]},{"chapter":93,"verses":[{"verse":1,"text":"E moni, ua faapea ona fetalai mai le Alii: O le a oo mai, o tagata taitoatasi e lafoai ana agasala ma sau ia te a’u, ma valaau mai i lo’u igoa, ma usiusitai i lo’u leo, ma tausi i a’u poloaiga, o le a vaai i o’u mata ma iloa o i ai a’u;"},{"verse":2,"text":"Ma o A’u o le malamalama moni ua faamalamalama ai tagata uma e o mai i le lalolagi;"},{"verse":3,"text":"Ma ua Ou i ai i totonu o le Tamā, ma le Tamā i totonu ia te a’u, ma o le Tamā ma A’u ua tasi—"},{"verse":4,"text":"O le Tamā ona ua ia tuuina mai ia te a’u lona atoatoaga, ma o le Atalii ona sa Ou i ai i le lalolagi ma fai i la le tino lo’u fale apitaga, ma mau ai i totonu o atalii o tagata."},{"verse":5,"text":"Sa Ou i ai i le lalolagi ma maua mai lo’u Tamā, ma o ana galuega sa manino ona faaalia mai."},{"verse":6,"text":"Ma sa vaai ma molimau Ioane i le atoatoaga o lo’u mamalu, ma o le a faaalia i se taimi o mulimuli mai le atoatoaga o le talafaamaumau a Ioane."},{"verse":7,"text":"Ma sa molimau mai o ia, fai mai: Sa ou vaai i lona mamalu, sa i ai o ia i le amataga, ae le’i i ai le lalolagi;"},{"verse":8,"text":"O le mea lea, sa i ai i le amataga le Lokou, ona o ia o le Lokou, le avefeau lava lea o le faaolataga—"},{"verse":9,"text":"O le malamalama ma le Togiola lea o le lalolagi; o le Agaga o le upumoni, o lē na afio mai i le lalolagi, ona o le lalolagi na faia e ia, ma sa i totonu ia te ia le ola o tagata ma le malamalama o tagata."},{"verse":10,"text":"O ia na faia lalolagi; o ia na faia tagata; o ia na faia mea uma, ma ala mai ia te ia, ma mai ia te ia."},{"verse":11,"text":"Ma o a’u, o Ioane, ou te molimau sa ou vaai i lona mamalu, o le mamalu lea o le Toatasi na Fanaua e le Tamā, ua tumu i le alofa tunoa ma le upumoni, le Agaga lava lea o le upumoni, lea na afio mai ma mau i la le tino, ma mau i totonu o i tatou."},{"verse":12,"text":"Ma o a’u, o Ioane, sa ou vaai, sa le’i maua e ia le atoatoaga i le amataga, ae sa maua e ia le alofa tunoa mo le alofa tunoa;"},{"verse":13,"text":"Ma sa le’i maua e ia le atoatoaga i le amataga, ae sa faaauau pea mai lea alofa tunoa i lea alofa tunoa, seia oo ina maua e ia le atoatoaga;"},{"verse":14,"text":"Ma sa faapea ona ta’ua ai o ia o le Atalii o le Atua, ona sa le’i maua e ia le atoatoaga i le amataga."},{"verse":15,"text":"Ma o a’u, o Ioane, ou te molimau atu, ma faauta, sa avanoa le lagi, ma sa afio ifo le Agaga Paia i ona luga e peiseai o se lupe, ma afio i ona luga, ma sa oo mai se siufofoga mai le lagi ua fetalai mai: O lo’u Atalii pele lenei."},{"verse":16,"text":"Ma o a’u, o Ioane, ou te molimau atu, sa maua e ia se atoatoaga o le mamalu o le Tamā;"},{"verse":17,"text":"Ma sa maua e ia le mana uma, i le lagi ma i le lalolagi, ma sa faatasi ma ia le mamalu o le Tamā, ona sa afio o ia i totonu o ia."},{"verse":18,"text":"Ma o le a oo mai, afai tou te faamaoni, o le a outou maua le atoatoaga o le talafaamaumau a Ioane."},{"verse":19,"text":"Ou te tuu atu ia te outou nei upu, ina ia outou malamalama ma iloa ai le ala e tapuai ai, ma iloa ai le mea tou te tapuai i ai, ina ia mafai ona outou o mai i le Tamā i lo’u igoa, ma maua lona atoatoaga i le taimi e tatau ai."},{"verse":20,"text":"Aua afai tou te tausi i a’u poloaiga, o le a outou maua lona atoatoaga, ma faamamaluina ia te a’u e pei o a’u i le Tamā; o lea, Ou te fai atu ia te outou, o le a outou maua le alofa tunoa mo le alofa tunoa."},{"verse":21,"text":"Ma o lenei, e moni Ou te fai atu ia te outou, sa Ou i ai i le amataga faatasi ma le Tamā, ma o A’u o le Ulumatua na Fanaua;"},{"verse":22,"text":"Ma o i latou uma o e e fananauina e ala mai ia te a’u ua faatofutofusia i le mamalu o lea lava e tasi, ma o le ekalesia a le Ulumatua na Fanaua."},{"verse":23,"text":"Sa outou i ai foi i le amataga faatasi ma le Tamā; o lena o le Agaga, o le Agaga lava lea o le upumoni;"},{"verse":24,"text":"Ma o le upumoni o le iloa lea o mea e pei ona i ai, ma e pei ona sa i ai, ma e pei ona o le a oo mai;"},{"verse":25,"text":"Ma o soo se mea lava e tele atu pe itiiti ifo nai lo lenei, o le agaga lea o lena amioleaga e toatasi, o lē o se pepelo mai le amataga."},{"verse":26,"text":"O le Agaga o le upumoni ua mai le Atua. O A’u o le Agaga o le upumoni, ma sa molimau Ioane e uiga ia te a’u, fai mai: Sa maua e ia se atoatoaga o le upumoni, ioe, upumoni uma lava;"},{"verse":27,"text":"Ma e leai se tagata na te mauaina se atoatoaga vagana ai ua tausi e ia ana poloaiga."},{"verse":28,"text":"O ia o lē e tausia ana poloaiga, e maua e ia le upumoni ma le malamalama, seia oo ina faamamaluina o ia i le upumoni ma iloa e ia mea uma."},{"verse":29,"text":"Sa i ai foi le tagata i le amataga faatasi ma le Atua. O le atamai, po o le malamalama o le upumoni, sa le’i foafoaina pe na gaosia, pe mafai moni lava ona foafoaina pe gaosia."},{"verse":30,"text":"O upumoni uma lava ua tu lē faalagolago i le tulaga ua tuu i ai e le Atua, e gaoioi mo ia lava, e pei foi o atamai uma; a na lē faapea, ua leai se olaga."},{"verse":31,"text":"Faauta, o le faitalia lenei a le tagata, ma o le ta’usalaga lenei o le tagata; ona ua manino ona faaali atu ia te i latou o lena mea sa i ai mai le amataga, ae ua latou lē taliaina le malamalama."},{"verse":32,"text":"Ma o tagata uma o e e lē talia e o latou agaga le malamalama, ua saisaitia e le ta’usalaga."},{"verse":33,"text":"Auā o le tagata o le agaga. O elemene ua faavavau, ma o le agaga ma le elemene, ua soofaatasi e lē matuu’eseeseina, e mauaina se atoatoaga o le olioli;"},{"verse":34,"text":"Ma a tuu’eseese, e lē mafai e le tagata ona maua se atoatoaga o le olioli."},{"verse":35,"text":"O elemene o fale apitaga a le Atua; ioe, o le tagata o le fale apitaga o le Atua, o ni malumalu lava; ma o soo se malumalu e faaleagaina, o lena malumalu o le a faaumatiaina e le Atua."},{"verse":36,"text":"O le mamalu o le Atua o le atamai lea, pe faapea, o le malamalama ma le upumoni."},{"verse":37,"text":"O le malamalama ma le upumoni e lafoa’i i lena toatasi leaga."},{"verse":38,"text":"O agaga uma o tagata sa mamā i le amataga; ma ona ua togiolaina e le Atua le tagata mai le pa’ū, o lea na toe mamā ai tagata, i lo latou tulaga tamameamea, i luma o le Atua."},{"verse":39,"text":"Ma ona sau lea o le amioleaga e toatasi lena, ma aveese mai le fanauga a tagata le malamalama ma le upumoni, e ala i le lē usiusitai, ma ona o le uputuu a o latou tamā."},{"verse":40,"text":"Ae ua Ou poloaiina outou ia tausi a’e a outou fanau i le malamalama ma le upumoni."},{"verse":41,"text":"Peitai e moni Ou te fai atu ia te oe, la’u auauna, o Frederick G. Williams, ua e i ai pea i lalo o lenei tausalaga;"},{"verse":42,"text":"E te le’i a’oa’o atua lau fanau i le malamalama ma le upumoni, e tusa ma poloaiga; ma ua i ai pea i lena amioleaga e toatasi le mana, i luga o oe, ma o le pogai lea o lou puapuagatia."},{"verse":43,"text":"Ma o lenei Ou te tuu atu ia te oe se poloaiga—afai e te manao ia laveaiina oe, ia e faatulaga tatau lou lava fale, ona e tele mea ua lē sa’o i lou fale."},{"verse":44,"text":"E moni, Ou te fai atu i la’u auauna o Sini Rikitone, e i ai ni isi mea e lei tausia ai e ia poloaiga e faatatau i lana fanau; o lea, ia muamua ona faatulaga tatau lou fale."},{"verse":45,"text":"E moni, Ou te fai atu i la’u auauna o Iosefa Samita, Le Itiiti, po o i ni isi upu, o le a Ou ta’ua outou o ni uo, ona o outou o a’u uo, ma o le a outou maua se tofi faatasi ma a’u—"},{"verse":46,"text":"Sa Ou ta’ua outou o auauna ona o le lalolagi, ma o outou o a latou auauna mo a’u—"},{"verse":47,"text":"Ma o lenei, e moni Ou te fai atu ia Iosefa Samita, Le Itiiti—E te le’i tausia poloaiga, ma ua ao ai ona e tulai a’oa’iina i luma o le Alii;"},{"verse":48,"text":"E ao ina salamo lou aiga ma lafoai ni isi o mea, ma gauai atili mai ma le filiga i a’u upu, po o le a aveesea i latou mai lo latou tulaga."},{"verse":49,"text":"O le mea Ou te fai atu ai i le toatasi Ou te fai atu ai i tagata uma; ia tatalo e lē aunoa ne’i maua e le leaga e toatasi lena le mana i totonu o outou, ma aveese outou i fafo mai lo outou tulaga."},{"verse":50,"text":"O la’u auauna foi o Newel K. Whitney, o se epikopo o la’u ekalesia, ua manaomia foi ona a’oa’iina, ma faatulaga tatau lona aiga, ma vaai ia latou filiga atili ma popole i le aiga, ma tatalo e lē aunoa, po o le a aveesea i latou mai lo latou tulaga."},{"verse":51,"text":"O lenei, Ou te fai atu ia te outou, a’u uo, ia tuu atu i la’u auauna o Sini Rikitone e alu lana malaga, ma ia faia faavave, ma tala’i atu foi le tausaga talileleia o le Alii, ma le talalelei o le faaolataga, e pei o le a Ou tuu atu ai ia te ia le manavaga; ma o le a Ou lagolagoina o ia e ala i la outou tatalo i le faatuatua ma le autasi."},{"verse":52,"text":"Ma ia tuu atu i a’u auauna o Iosefa Samita, Le Itiiti, ma Frederick G. Williams, e fai faavave atu foi, ma o le a tuu atu ia te i la’ua e tusa lava ma le tatalo o le faatuatua; ma e tusa ai ma lo outou tausia o a’u upu o le a lē mafai ona faafememea’iina outou i le lalolagi lenei, po o le lalolagi a sau."},{"verse":53,"text":"Ma, e moni Ou te fai atu ia te outou, o lo’u loto ia faataalise ona outou faaliliu o a’u tusitusiga paia, ma maua se malamalama o talafaasolopito, ma atunuu, ma malo, o tulafono a le Atua ma tagata, ma nei mea uma mo le faaolataga o Siona. Amene."}]},{"chapter":94,"verses":[{"verse":1,"text":"O lenei foi, e moni Ou te fai atu ia te outou, o a’u uo, Ou te tuu atu ia te outou se poloaiga, ia outou amata se galuega o le faataatia ma le saunia o se amataga ma le faavae o le aai o le siteki o Siona, iinei i le laueleele o Katelani, e amata i lo’u fale."},{"verse":2,"text":"Ma faauta, e ao ina faia e tusa ma le ata ua Ou tuuina atu ia te outou."},{"verse":3,"text":"Ma ia tuu le fasi fanua muamua i le itu i saute e faapaia mo a’u mo le fausia ai o se fale mo le au peresitene, mo le galuega a le au peresitene, i le mauaina o faaaliga; ma mo le galuega o le auaunaga a le au peresitene, i mea uma e faatatau i le ekalesia ma le malo."},{"verse":4,"text":"E moni Ou te fai atu ia te outou, ia fausia i le limasefulu-lima i le onosefulu-lima futu lona lautele ma lona umi, i le lotoifale i totonu."},{"verse":5,"text":"Ma ia i ai se fogafale alalo ma se fogafale aluga, e tusa ma le ata o le a tuu atu ia te outou i se taimi o i luma."},{"verse":6,"text":"Ma ia faapaia mo le Alii mai lona faavae, e tusa ma le faatulagaga o le perisitua, e tusa ma le ata o le a tuu atu ia te outou i se taimi o i luma."},{"verse":7,"text":"Ma ia faapaia atoa i le Alii mo le galuega a le au peresitene."},{"verse":8,"text":"Ma ia outou lē tuu se mea lē mamā e sau i ai i totonu; ma o le a i ai iina lo’u mamalu, ma o le a ou i ai iina."},{"verse":9,"text":"Ae afai e alu atu i ai i totonu se mea lē mamā, o le a lē i ai iina lo’u mamalu; ma o le a ou lē alu atu i ai."},{"verse":10,"text":"O lenei foi, e moni Ou te fai atu ia te outou, o le fasi fanua lona lua i le itu i saute ia faapaia mo a’u mo le fausiaina o se fale mo a’u, mo le galuega o le lomiga o le faaliliuga o a’u tusitusiga paia, ma mea uma o soo se mea o le a Ou poloaiina ai outou."},{"verse":11,"text":"Ma ia limasefulu-lima i le onosefulu-lima futu lona lautele ma lona umi, i le lotoifale i totonu; ma ia i ai se fogafale alalo ma se fogafale aluga."},{"verse":12,"text":"Ma o lenei fale ia faapaia atoa i le Alii mai lona faavae, mo le galuega o le lomiga, i mea uma o soo se mea o le a Ou poloaiina ai outou, ia paia, ma lē faaeleeleaina, e tusa ma le ata i mea uma e pei o le a tuuina atu ia te outou."},{"verse":13,"text":"Ma o le fasi fanua lona tolu ia maua e la’u auauna o Ailama Samita mo ona tofi."},{"verse":14,"text":"Ma o le fasi fanua muamua ma lona lua i le itu i matu, ia maua e a’u auauna o Reynolds Cahoon ma Iareto Kata mo o laua tofi—"},{"verse":15,"text":"Ina ia mafai ona latou faia o le galuega ua Ou tofia i ai i latou, e avea ma se komiti e fausia o’u fale, e tusa ma le poloaiga, lea ua tuuina atu e A’u, le Alii le Atua, ia te outou."},{"verse":16,"text":"O fale ia e lua, ia lē fausia se’i Ou tuu atu ia te outou se poloaiga e faatatau i ai."},{"verse":17,"text":"Ma o lenei, e leai se isi mea Ou te tuu atu ia te outou i le taimi nei. Amene."}]},{"chapter":95,"verses":[{"verse":1,"text":"E moni, ua faapea ona fetalai mai o le Alii ia te outou o e ua Ou alofa i ai, ma o e Ou te alofa i ai Ou te a’oa’iina foi ina ia mafai ona faamagaloina a latou agasala, auā Ou te saunia, faatasi ma le a’oa’iga, se ala mo le laveaiina o i latou mai le faaosoosoga, i mea uma, ma sa Ou alofa ia te outou—"},{"verse":2,"text":"O le mea lea, e ao ai ina a’oa’iina outou ma tutulai ua a’oa’iina i o’u luma;"},{"verse":3,"text":"Ona ua outou faia mai ia te a’u se agasala mamafa tele, i lo outou lē manatu i le poloaiga sili i mea uma, lea na Ou tuuina atu ia te outou e faatatau i le fausiga o lo’u fale;"},{"verse":4,"text":"Mo le sauniuniga lea ua Ou fuafuaina e saunia ai a’u aposetolo e teu lo’u tovine mo le taimi mulimuli, ina ia mafai ona Ou faataunuu o la’u galuega uiga ese, ina ia mafai ona Ou liligi atu lo’u Agaga i luga o tagata uma—"},{"verse":5,"text":"Ae faauta, e moni Ou te fai atu ia te outou, o loo i ai se toatele o e ua uma ona faauuina i totonu o outou, o e na Ou valaaulia ae toaitiiti i latou ua filifilia."},{"verse":6,"text":"O i latou o e ua lē filifilia ua latou faia se agasala mamafa, lea ua latou savavali ai i le pouliuli i le aoauli."},{"verse":7,"text":"Ma o le pogai lenei na Ou tuu atu ai ia te outou se poloaiga e tatau ona talo sa outou faapotopotoga paia, ina ia mafai ona oo a’e a outou anapogi ma a outou faanoanoaga i fofoga o le Alii o Sapaota, o lona uiga pe a faaliliuina, o le foafoa lea o le uluai aso, o le amataga ma le gataaga."},{"verse":8,"text":"Ioe, e moni Ou te fai atu ia te outou, na Ou tuu atu ia te outou se poloaiga e tatau ona outou fausia se fale, o se fale lea ua Ou fuafuaina e faaeeina ai i latou o e ua Ou filifilia, i le mana mai lugā;"},{"verse":9,"text":"Ona o le folafolaga lenei a le Tamā ia te outou; o lea Ou te poloai atu ai ia te outou ia nonofo pea, e pei lava o a’u aposetolo i Ierusalema."},{"verse":10,"text":"Ae ui i lea, na faia e a’u auauna se agasala mamafa; ma sa tutupu mai ni finauga i le a’oga a perofeta; o se mea na mamafa ia te a’u, ua fetalai mai ai lo outou Alii; o lea na ’Ou auina atu ai i latou ia a’oa’iina."},{"verse":11,"text":"E moni Ou te fai atu ia te outou, o lo’u manao ia outou fausia se fale. Afai tou te tausia a’u poloaiga o le a outou maua le mana e fausia ai."},{"verse":12,"text":"Afai tou te lē tausia a’u poloaiga, o le a lē tumau pea le alofa o le Tamā e faatasi ma outou, o lea o le a outou savavali ai i le pouliuli."},{"verse":13,"text":"O lenei o le poto lenei, ma le mafaufau o le Alii—ia fausia le fale, e lē tusa ma le ala a le lalolagi, aua Ou te lē tuu atu ia te outou ia outou ola e tusa ma le ala a le lalolagi;"},{"verse":14,"text":"O lea, ia fausia e tusa ma le ala lea o le a Ou faaali atu i se toatolu o outou, o e ia outou tofia ma faauu i lenei mana."},{"verse":15,"text":"Ma o lona telē ia limasefulu ma le lima futu le lautele, ma ia onosefulu-lima futu le umi, i lona lotoifale i totonu."},{"verse":16,"text":"Ma ia tuu le vaega alalo o le lotoifale i totonu ia faapaia mo a’u mo a outou taulaga faamanatuga, ma mo a outou talaiga, ma a outou anapogi, ma a outou talosaga, ma le tuuina mai ia te a’u o o outou manaoga silisili ona paia, ua fetalai mai ai lo outou Alii."},{"verse":17,"text":"Ma ia tuu le vaega aluga o le lotoifale i totonu e faapaia mo a’u mo le a’oga a a’u aposetolo, ua fetalai mai ai Atalii o Amani; pe, faapea, o Alefasa; pe, faapea foi, o Omekasi; o Iesu Keriso lava lo outou Alii. Amene."}]},{"chapter":96,"verses":[{"verse":1,"text":"Faauta, Ou te fai atu ia te outou, o le poto lenei, ia mafai ona outou iloa ai le ala e fai e faatatau i lenei mataupu, ona ua tatau ia te a’u ona faamalosia lenei siteki ua ’Ou faatuina mo le malosi o Siona."},{"verse":2,"text":"O lea, ia tuu atu i la’u auauna o Newel K. Whitney e pulea le fanua lea ua ta’ua i totonu o outou, lea ua Ou fuafuaina e fausia ai i luga lo’u fale paia."},{"verse":3,"text":"O lenei foi, ia vaevaeina i ni fasi fanua, e tusa ma le poto, mo le manuia o i latou o e o saili ni tofi, ma o le a iloilo i se fono i totonu o outou."},{"verse":4,"text":"O lea, ia faaeteete ia outou tagai i lenei mataupu, ma le vaega lena ua tatau ai mo le manuia o la’u faatulagaga, mo le faamoemoe o le aumaia o la’u upu i le fanauga a tagata."},{"verse":5,"text":"Auā faauta, e moni Ou te fai atu ia te outou, o le mea lenei ua silisili ona tatau ia te a’u, ina ia mafai ona alu atu o la’u upu i le fanauga a tagata, mo le faamoemoe o le faamaluluina o loto o le fanauga a tagata mo lo outou lelei. Ua faapea lava. Amene."},{"verse":6,"text":"O lenei foi, e moni Ou te fai atu ia te outou, o le poto ma se mea ua tatau ai lenei ia te a’u, le tatau i la’u auauna o John Johnson, o lē ua Ou talia lana taulaga, ma o lē ua Ou faalogoina ana talosaga, o lē Ou te tuu atu i ai se folafolaga o le ola e faavavau e tusa ai ma lona tausia o a’u poloaiga mai le taimi nei ma le agai i luma—"},{"verse":7,"text":"Ona o ia o se e tupuga mai ia Iosefa ma o se ua tofusia i faamanuiaga o le folafolaga na faia i ona tamā—"},{"verse":8,"text":"E moni Ou te fai atu ia te outou, ua tatau ia te a’u ona avea o ia o se uso i le faatulagaga, ina ia mafai ona fesoasoani o ia i le aumaia o la’u upu i le fanauga a tagata."},{"verse":9,"text":"O lea ia outou faauu o ia i lenei faamanuiaga, ma ia saili o ia ma le filiga e aveese faalavelave o loo i luga o le fale ua ta’ua i totonu o outou, ina ia nofo ai o ia i totonu. Ua faapea lava. Amene."}]},{"chapter":97,"verses":[{"verse":1,"text":"E moni Ou te fai atu ia te outou o a’u uo, Ou te tautala atu ia te outou i lo’u leo, o le leo lava lea o lo’u Agaga, ina ia mafai ona Ou faailoa atu ia te outou lo’u loto e faatatau i o outou uso i le laueleele o Siona, o le toatele o i latou ua lotomaualalo moni ma o loo saili ma le filiga e a’oa’o le poto ma maua le upumoni."},{"verse":2,"text":"E moni, e moni Ou te fai atu ia te outou, amuia e faapena, ona o le a latou maua; auā o A’u, o le Alii, e faaali atu le alofa mutimutivale ia te i latou uma o e agamalu, ma i luga o i latou uma o soo se tasi Ou te loto i ai, ina ia mafai ona ta’uamiotonuina A’u pe a Ou aumai i latou i le faamasinoga."},{"verse":3,"text":"Faauta, Ou te fai atu ia te outou, e faatatau i le a’oga i Siona, o A’u, o le Alii, ua fiafia i le tatau ona i ai o se a’oga i Siona, ma i la’u auauna foi o Parley P. Pratt, ona ua mau o ia ia te a’u."},{"verse":4,"text":"Ma e tusa ai ma lona faaauau pea ona mau o ia ia te a’u, o le a faaauau pea ona pulefaamalumalu o ia i le a’oga o i le laueleele o Siona, seia Ou tuu atu ia te ia ni isi poloaiga."},{"verse":5,"text":"Ma o le a Ou faamanuiaina o ia i le tele o faamanuiaga, i le faamalamalamaina o tusitusiga paia uma ma mealilo mo le faagaeetiaina o le aoga, ma le ekalesia i Siona."},{"verse":6,"text":"Ma i e o totoe o le a’oga, o A’u, o le Alii, Ou te loto e faaali atu i ai le alofa mutimutivale; ae ui i lea, o loo i ai i latou o e e ao ina a’oa’iina, ma o le a faaalia a latou galuega."},{"verse":7,"text":"Ua faataatia le matau i le tafu’e o laau; o laau uma e lē fua mai i fua lelei o le a tatuu i lalo ma lafo i le afi. O A’u, o le Alii, ua fai atu ai."},{"verse":8,"text":"E moni Ou te fai atu ia te outou, o e uma o i totonu o i latou ua iloa ua faamaoni o latou loto, ma ua momomo, ma ua salamo o latou agaga, ma ua loto e tausi a latou feagaiga e ala i le taulaga—ioe, o taulaga uma e poloaiina e A’u, o le Alii—e taliaina i latou e a’u."},{"verse":9,"text":"Auā o A’u, o le Alii, o le a faia i latou ia fua mai e pei o se laau fua tele ua totoina i se fanua lelei, i tafatafa o se vaitafe mamā, e fua mai ai ni fua pele e tele."},{"verse":10,"text":"E moni Ou te fai atu ia te outou, o lo’u loto, ia tatau ona fausia se fale mo a’u i le laueleele o Siona, e pei o le ata na Ou tuuina atu ia te outou."},{"verse":11,"text":"Ioe, ia tuu atu ia fausia vave, i le sefuluai a lo’u nuu."},{"verse":12,"text":"Faauta, o le sefuluai ma le taulaga lenei ua manaomia e A’u, o le Alii, mai o latou lima, ina ia i ai se fale e fausia mo a’u, mo le faaolataga o Siona—"},{"verse":13,"text":"Mo se nofoaga o le faafetai mo le au paia uma, ma o se nofoaga o le a’oa’oga mo i latou uma o e ua valaaulia i le galuega o le auaunaga i o latou valaauga ma tofi eseese uma;"},{"verse":14,"text":"Ina ia mafai ona faaatoatoaina i latou i le malamalamaaga o la latou auaunaga, i teori, i le mataupu faavae, ma i le aoaoga faavae, i mea uma e faatatau i le malo o le Atua i le lalolagi, le malo lea o ona ki ua faaee atu i o outou luga."},{"verse":15,"text":"Ma e tusa ai o le fausia e o’u tagata o se fale mo a’u i le suafa o le Alii, ma latou lē tuua se mea eleelea e ulufale iai, ina ia lē faaeleeleaina, o le a iai lo’u mamalu i ona luga;"},{"verse":16,"text":"Ioe, ma o le a i ai lo’u afioaga iina, ona o le a Ou alu atu i ai i totonu, ma o i latou uma e loto mamā e o mai i ai i totonu, o le a vaai i le Atua."},{"verse":17,"text":"Ae afai e faaeleeleaina Ou te lē alu atu i ai i totonu, ma o le a lē i ai foi lo’u mamalu iina; aua Ou te lē alu atu i totonu o ni malumalu ua lē paia."},{"verse":18,"text":"Ma, o lenei, faauta, afai e fai e Siona nei mea, o le a uluuluola o ia ma faalauteleina o ia lava ma avea ma nuu mamalu tele, malosi tele, ma mata’utia tele."},{"verse":19,"text":"Ma o le a faamamaluina o ia e atunuu o le lalolagi, ma o le a fai ane: E moni lava o Siona o le aai lea o lo tatou Atua, ma e moni lava e lē mafai ona pa’ū Siona, pe aveesea mai lona tulaga, auā ua i ai le Atua iina, ma ua i ai iina le aao o le Alii;"},{"verse":20,"text":"Ma ua tauto o ia i le mana o lona malosi e avea ma ona faaolataga ma ona ’olo maualuga."},{"verse":21,"text":"O lea, e moni, ua faapea ona fetalai mai o le Alii, ia olioli Siona, auā o Siona lenei—O e Ua Loto Mamā; o lea, ia tuu atu ia Siona e olioli, a’o e uma ua amioleaga, o le a faanoanoa."},{"verse":22,"text":"Auā faauta, ma tagai, ua vave ona oo mai o le tauimasui i luga o e ua lē amioatua e pei o le asiosio; ma o ai e sao mai ai?"},{"verse":23,"text":"O le a oo mai le sasa a le Alii i le po ma le ao, ma o le tala o lea sasa o le a faaatuatuvale ai tagata uma; ioe, o le a lē taofia seia afio mai le Alii;"},{"verse":24,"text":"Auā ua sasao a’e le toasa o le Alii e faasaga ia latou mea inosia ma a latou galuega amioleaga uma."},{"verse":25,"text":"Ae ui i lea, e sao Siona pe afai e vaai o ia ia fai mea uma o soo se mea ua Ou poloaiina ai o ia."},{"verse":26,"text":"Ae afai e lē vaai o ia ia faia soo se mea ua Ou poloaiina ai o ia, o le a Ou asiasi atu ia te ia e tusa ma ana galuega uma, i se puapuaga tiga, ma faama’i, ma mala, ma le pelu, ma le tauimasui, ma le afi faaumatia."},{"verse":27,"text":"Ae ui i lea, ia tuu atu ia toe faitau tasi atu lenei mea i ona taliga, o A’u, o le Alii, ua talia lana taulaga; ma afai e lē toe agasala o ia, o le a leai se tasi o nei mea e oo mai i ona luga;"},{"verse":28,"text":"Ma o le a Ou faamanuiaina o ia i manuia, ma faateleina se faatelega o manuia i ona luga, ma luga o ona tupulaga e faavavau faavavau lava, ua fetalai mai ai le Alii lo outou Atua. Amene."}]},{"chapter":98,"verses":[{"verse":1,"text":"E moni Ou te fai atu ia te outou a’u uo, aua le matatau, ia faamafanafanaina o outou loto; ioe, ia saga olioli pea, ma ia avatu le faafetai i mea uma;"},{"verse":2,"text":"Ma faatalitali ma le onosai i le Alii, ona ua ulu atu a outou tatalo i fofoga-faafofoga o le Alii o Sapaota, ma ua tusifaamaumau ma le faamaufaailoga lenei ma le molimau—ua tauto le Alii ma folafola o le a talia i latou."},{"verse":3,"text":"O lea, ua tuuina mai e ia le folafolaga lenei ia te outou, ma se feagaiga e lē masuia o le a faataunuuina i latou; ma o mea uma sa outou puapuagatia ai o le a galulue faatasi mo lo outou lelei, ma le mamalu o lo’u igoa, ua fetalai mai ai le Alii."},{"verse":4,"text":"Ma o lenei, e moni Ou te fai atu ia te outou e faatatau i tulafono o le laueleele, o lo’u loto, e tatau i lo’u nuu ona vaai ia faia mea uma o soo se mea Ou te poloaiina ai i latou."},{"verse":5,"text":"Ma o lena tulafono o le laueleele ua tusa ma le tulafono faavae, ua lagolagoina le mataupu autu lena o le saolotoga i le faatumauina o aiā ma avanoa, e a tagata uma, ma ua ta’uamiotonuina i o’u luma."},{"verse":6,"text":"O lea, o A’u, o le Alii, ua ta’uamiotonuina outou, ma o outou uso o la’u ekalesia, i le lagolagoina o le tulafono lena o le tulafono faavae lea o le laueleele;"},{"verse":7,"text":"Ma e faatatau i tulafono a tagata, soo se mea lava e faapei o lenei, ua sau mai le leaga."},{"verse":8,"text":"O A’u, o le Alii le Atua, ua faasa’olotoina outou, o lea ua outou saoloto moni ai; ma ua faasa’olotoina foi outou e le tulafono."},{"verse":9,"text":"Ae ui i lea, a pule e amioleaga e faanoanoa le nuu."},{"verse":10,"text":"O le mea lea, e tatau ai ona saili ma le filiga tagata faamaoni, ma o tagata lelei ma tagata atamamai e tatau ona outou vaai ia sapasapaia; a lē o lea, soo se mea e itiiti mai lo ia mea, ua sau mai le leaga."},{"verse":11,"text":"Ma Ou te tuu atu ia te outou se poloaiga, ia outou lafoai i mea leaga uma ma pipii atu i mea lelei uma, ma ia outou ola i afioga uma e tulei mai le fofoga o le Atua."},{"verse":12,"text":"Auā o le a tuu atu e ia i e faamaoni lea fasifuaitau ma lea fasifuaitau, o lea mataupu i lea mataupu; ma o le a Ou faata’ita’ia ma tofotofoina outou i lenei mea."},{"verse":13,"text":"Ma ’ai se tasi e tuuina atu lona ola ona o a’u, mo lo’u igoa, o le a toe maua e ia, o le ola lava lea e faavavau."},{"verse":14,"text":"O lea, aua le fefefe i o outou fili, auā ua Ou folafola i lo’u loto, ua fetalai mai ai le Alii, o le a Ou tofotofoina outou i mea uma, pe tou te tumau ai i la’u feagaiga, e oo lava i le oti, ina ia mafai ona maua e outou le agavaa."},{"verse":15,"text":"Auā afai tou te lē tumau i la’u feagaiga, ua outou lē agavaa mo a’u."},{"verse":16,"text":"O lea, ia tetee ai i taua ma folafola atu le filemu, ma saili ma le filiga e liliu loto o fanau i o latou tamā, ma loto o tamā i fanau;"},{"verse":17,"text":"O lenei foi, o loto o tagata Iutaia i perofeta, ma perofeta i tagata Iutaia; ne’i Ou alu atu ma taia le lalolagi atoa i se fetuu, ma mu ai tagata uma i o’u luma."},{"verse":18,"text":"Aua le atuatuvale o outou loto; auā e tele maota o i ai i le fale o lo’u Tamā, ma ua Ou saunia se nofoaga mo outou; ma o le mea e i ai lo’u Tamā ma A’u, o iina foi o le a outou i ai."},{"verse":19,"text":"Faauta, o A’u, o le Alii, ua Ou lē fiafia tele i le toatele o e o i ai i le ekalesia i Katelani;"},{"verse":20,"text":"Auā ua latou lē lafoaia a latou agasala, ma o latou ala amioleaga, le faamaualuluga o o latou loto, ma lo latou matape’ape’a, ma a latou mea inosia uma, ma tausi i upu o le poto ma le ola e faavavau na Ou tuu atu ia te i latou."},{"verse":21,"text":"E moni Ou te fai atu ia te outou, o A’u, o le Alii, o le a Ou a’oa’iina i latou ma o le a Ou faia soo se mea Ou te loto i ai, pe afai latou te lē salamo ma tausi mea uma o soo se mea na Ou fai atu ai ia te i latou."},{"verse":22,"text":"Ma Ou te toe fai atu ia te outou, afai tou te vaai ia faia soo se mea Ou te poloaiina ai outou, o A’u, o le Alii, o le a Ou liliu ese le ita ma le toasa uma mai ia te outou, ma o le a lē manumalo faitotoa o seoli ia te outou."},{"verse":23,"text":"O lenei, Ou te tautala atu ia te outou e faatatau i o outou aiga—afai e faa-tasi ona taia o outou, po o o outou aiga, e tagata, ma outou talia ma le onosai ma lē upuleaga faasaga atu ia te i latou, pe saili e tauimasui, o le a tauia outou."},{"verse":24,"text":"Ae afai tou te lē taliaina ma le onosai, o le a faitauina ia te outou o se mea ua tonu ona fua atu ia te outou."},{"verse":25,"text":"O lenei foi, afai e faa-lua ona taia o outou e lo outou fili, ma outou lē upuleaga faasaga atu i lo outou fili, ma talia ma le onosai, o le a sautua-selau lo outou taui."},{"verse":26,"text":"O lenei foi, afai e faa-tolu ona taia o outou e ia, ma outou talia ma le onosai, o le a faaluaina lo outou taui ia te outou ia sautuafā;"},{"verse":27,"text":"Ma o nei molimau e tolu o le a tutu e faasaga i lo outou fili pe afai e lē salamo o ia, ma o le a lē soloiesea lava."},{"verse":28,"text":"Ma o lenei, e moni Ou te fai atu ia te outou, afai e sao lena fili mai la’u tauimasui, o le a lē aumai ai o ia i le faamasinoga i o’u luma, ona outou vaai ai lea ia outou lapata’ia o ia i lo’u igoa, ia lē toe sau o ia i luga ia te oe, po o luga o lou aiga, e oo lava i fanau a au fanau e oo atu i le tupulaga e tolu ma le fa."},{"verse":29,"text":"Ma ona faapea lea, afai e sau o ia i luga ia te oe po o lau fanau, po o le fanau a lau fanau e oo atu i le tupulaga e tolu ma le fa, ua Ou tuu atu lou fili i ou lima;"},{"verse":30,"text":"Ma afai e te faasaoina o ia i le taimi lea, o le a tauia oe mo lou amiotonu; ma au fanau foi ma fanau a au fanau e oo i le tupulaga e tolu ma le fa."},{"verse":31,"text":"Ae ui i lea, ua i ai ou fili i ou lima; ma afai e te tauia o ia e tusa ma ana galuega, ua ta’uamiotonuina oe; afai sa saili e ia lou ola, ma ua lamatia lou ola e ia, ua i ai lou fili i ou lima ma ua ta’uamiotonuina oe."},{"verse":32,"text":"Faauta, o le tulafono lenei na Ou tuu atu i la’u auauna o Nifae, ma ou tamā, o Iosefa, ma Iakopo, ma Isaako, ma Aperaamo, ma a’u perofeta ma aposetolo uma anamua."},{"verse":33,"text":"O lenei foi, o le tulafono lenei na Ou tuu atu i o’u tagata anamua, e faapea e lē tatau ona latou o atu e tau faasaga i se atunuu, ituaiga, gagana, po o se nuu, vagana ai ua poloaiina ai i latou, e A’u, le Alii."},{"verse":34,"text":"Ma afai e i ai se atunuu, gagana, po o se nuu e alagaina se taua faasaga mai ia te i latou, e tatau ona muamua o latou sisi atu se tagavai o le filemu i lena nuu, atunuu, po o le gagana;"},{"verse":35,"text":"Ma afai sa lē talia e lena nuu le ofo o le filemu, po o le taimi lona lua po o le taimi lona tolu, e tatau ona latou aumai na molimau i luma o le Alii;"},{"verse":36,"text":"Ona tuu atu ai lea e A’u, o le Alii, se poloaiga ia te i latou, ma ta’uamiotonuina i latou i le o atu e tau faasaga i lena atunuu, gagana, po o le nuu."},{"verse":37,"text":"Ma o A’u, o le Alii, e tauina a latou taua, ma taua a a latou fanau, ma fanau a a latou fanau, seia oo ina latou tauimasui mo i latou lava i o latou fili uma, e oo i le tupulaga e tolu ma le fa."},{"verse":38,"text":"Faauta, o se faataitaiga lenei i tagata uma, ua fetalai mai ai le Alii lo outou Atua, mo le ta’uamiotonuina i o’u luma."},{"verse":39,"text":"O lenei foi, e moni Ou te fai atu ia te outou, afai e sau lou fili ia te oe ina ua mavae le taimi muamua, ua salamo o ia ma ua sau ia te oe ma aioi mai mo lau faamagaloga, ia e faamagalo atu ia te ia, ma ia e lē toe taofia o se molimau e faasaga i lou fili—"},{"verse":40,"text":"Ma ia faapea lava ona fai e oo atu i le taimi lona lua ma le lona tolu; ma o le tele o taimi e salamo ai lou fili i se agasala na ia faia e faasaga mai ia te oe, ia e faamagalo atu ia te ia, seia faafitugafulu ni fitu."},{"verse":41,"text":"Ma afai e agasala o ia faasaga mai ia te oe i le taimi muamua ma ua lē salamo ai, ae ui i lea ia e faamagalo atu ia te ia."},{"verse":42,"text":"Ma afai e agasala o ia faasaga mai ia te oe i le taimi lona lua, ma ua lē salamo ai, ae ui i lea ia e faamagalo atu ia te ia."},{"verse":43,"text":"Ma afai e agasala o ia faasaga mai ia te oe i le taimi lona tolu, ma ua lē salamo ai, ia e faamagalo atu foi ia te ia."},{"verse":44,"text":"Ae afai e agasala o ia faasaga mai ia te oe i le taimi lona fa, ia e lē faamagalo atu ia te ia, ae ia e aumai na molimau i luma o le Alii; ma o le a lē soloiesea i latou seia salamo o ia ma tauia oe sautuafā i mea uma na agasala ai o ia e faasaga mai ia te oe."},{"verse":45,"text":"Ma afai e faia e ia lenei mea, ia e faamagalo atu ia te ia ma lou loto atoa; ae afai e lē faia e ia lenei mea, o A’u, o le Alii, o le a Ou tauimasui i lou fili mo oe i le sautuaselau;"},{"verse":46,"text":"Ma i luga o ana fanau, ma luga o fanau a ana fanau o i latou uma o e e inoino mai ia te a’u, e oo atu i le tupulaga e tolu ma le fa."},{"verse":47,"text":"Ae afai e salamo le fanau, po o le fanau a fanau, ma liliu mai i le Alii lo latou Atua, ma o latou loto atoa, ma o latou manatu atoa, mafaufau atoa, ma le malosi atoa, ma sautuafā ona latou toefuatai atu mo a latou agasala uma na latou agasala ai, po o agasala na faia e o latou tamā, po o tamā o o latou tamā, ona liliu ese ai lea o lou ita;"},{"verse":48,"text":"Ma o le a lē toe oo atu le tauimasui i luga o i latou, ua fetalai mai ai le Alii lou Atua, ma o le a lē toe aumaia a latou agasala o se molimau i luma o le Alii e faasaga ia te i latou. Amene."}]},{"chapter":99,"verses":[{"verse":1,"text":"Faauta, ua faapea ona fetalai mai o le Alii i la’u auauna o Ioane Murdock—ua valaaulia oe e te alu atu i itu-laueleele i sasa’e mai lea fale i lea fale, mai lea nuu i lea nuu, ma mai lea aai i lea aai, e folafola atu la’u talalelei tumau e faavavau i e o nonofo ai, i le lotolotoi o sauaga ma le amioleaga."},{"verse":2,"text":"Ma o lē na te talia oe ua ia talia a’u; ma o le a e maua le mana e alaga atu ai la’u upu i le faaaliga a lo’u Agaga Paia."},{"verse":3,"text":"Ma o lē na te talia oe e pei o se tamaitiiti, e maua e ia lo’u malo; ma amuia lava i latou, ona o le a latou maua le alofa mutimutivale."},{"verse":4,"text":"Ma ai se na te teena oe o le a teena e lo’u Tamā ma lona fale; ma ia outou tafi o outou vae i mea lilo i le ala mo se molimau e faasaga ia te i latou."},{"verse":5,"text":"Ma faauta, ma tagai, Ou te vave alu atu i le faamasinoga, e faatalitonu tagata uma ia latou galuega lē amioatua ua latou faia faasaga mai ia te a’u, e pei ona tusia e uiga ia te a’u i le tusi o tusitusiga paia."},{"verse":6,"text":"Ma o lenei, e moni Ou te fai atu ia te oe, e lē tatau ona e alu atu seia saunia ni mea mo le tausiga o lau fanau, ma auina lelei atu i le epikopo o Siona."},{"verse":7,"text":"Ma a mavae ni nai tausaga, afai e te manao mai ai ia te a’u, e mafai foi ona e alu a’e i luga i le laueleele lelei, e maua ai lou tofi;"},{"verse":8,"text":"A lē o lea, ia e folafola atu pea la’u talalelei seia aveina a’e oe. Amene."}]},{"chapter":100,"verses":[{"verse":1,"text":"E moni, ua faapea ona fetalai mai o le Alii ia te oulua, a’u uo, o Sini ma Iosefa, o loo manuia o oulua aiga; ua i ai i latou i o’u lima, ma o le a Ou faia ia te i latou e pei ona lelei ia te a’u; ona ua i ai ia te a’u le mana uma."},{"verse":2,"text":"O lea, mulimuli mai ia te a’u, ma faalogo mai i le fautuaga o le a Ou tuu atu ia te oulua."},{"verse":3,"text":"Faauta, ma tagai, ua ia te a’u ni tagata e toatele i lenei mea, i nofoaga o faataamilo ai; ma o le a tatalaina se faitotoa aoga i nofoaga o faataamilo ai i le laueleele lenei i sasa’e."},{"verse":4,"text":"O lea, na tuu atu ai e A’u, o le Alii, oulua, ia oulua o mai i le nofoaga lenei, ona ua faapea ona tatau ai ia te a’u mo le faaolataga o agaga."},{"verse":5,"text":"O lea, e moni Ou te fai atu ia te oulua, ia siitia a’e o oulua leo i lenei nuu; tautala atu mafaufauga o le a Ou tuu i o oulua loto, ma o le a lē faafememeaiina oulua i luma o tagata;"},{"verse":6,"text":"Auā o le a tuu atu ia te oulua i le itula tonu lava, ioe, i le minute tonu lava, mea e te lua fai atu ai."},{"verse":7,"text":"Ae Ou te tuu atu ia te oulua se poloaiga, ia oulua alaga atu soo se mea lua te alaga atu i lo’u igoa, i le mamalu o le loto, i le agaga o le agamalu, i mea uma."},{"verse":8,"text":"Ma Ou te tuu atu ia te oulua le folafolaga lenei, e tusa ai ma lo oulua faia o lenei mea, o le a liligi atu le Agaga Paia e molimau i mea uma o soo se mea lua te fai atu ai."},{"verse":9,"text":"Ma ua tatau ia te a’u ona avea oe, la’u auauna, o Sini, ma failauga i lenei nuu; ioe, e moni, o le a Ou faauuina oe i lenei valaauga, e avea lava ma failauga mo la’u auauna o Iosefa."},{"verse":10,"text":"Ma o le a Ou tuu atu ia te ia le mana ia malosi ai i le molimau."},{"verse":11,"text":"Ma o le a Ou tuu atu ia te oe le mana e te malosi ai i le faamalamalamaina o tusitusiga paia uma, ina ia mafai ona avea oe ma failauga mo ia, ma o le a avea o ia ma talifaaaliga mo oe, ina ia mafai ona e iloa le moni o mea uma e faatatau i mea o lo’u malo i le lalolagi."},{"verse":12,"text":"O lea, ia faaauau pea la oulua malaga ma ia olioli o oulua loto; auā faauta, ma tagai, Ou te faatasi ma oulua e oo lava i le iuga."},{"verse":13,"text":"Ma o lenei, Ou te tuu atu ia te oulua se upu e uiga ia Siona. O le a laveaiina Siona, e ui ina a’oa’ina o ia mo se vaitau itiiti."},{"verse":14,"text":"O o oulua uso, o a’u auauna o Orson Hyde ma John Gould, ua i ai i o’u lima; ma e tusa ai ma lo la tausia o a’u poloaiga, o le a faaolaina i la’ua."},{"verse":15,"text":"O lea, ia faamafanafanaina o oulua loto; ona o le a galulue faatasi mea uma mo le lelei o e e savavali sa’o, ma mo le faapaiaina o le ekalesia."},{"verse":16,"text":"Auā o le a Ou faatuina mai mo a’u se nuu mamā, o e e auauna mai ia te a’u i le amiotonu;"},{"verse":17,"text":"Ma o i latou uma o e e valaau atu i le suafa o le Alii, ma tausi i ana poloaiga, o le a faaolaina. E faapea lava. Amene."}]},{"chapter":101,"verses":[{"verse":1,"text":"E moni Ou te fai atu ia te outou, e uiga i o outou uso o e ua puapuagatia, ma ua sauaina, ma ua tutuliese mai le laueleele o lo latou tofi—"},{"verse":2,"text":"O A’u, o le Alii, na Ou tuu le puapuaga ia oo mai i o latou luga, lea ua latou puapuagatia ai, ona o a latou soligatulafono;"},{"verse":3,"text":"Peitai o le a A’u i latou, ma o le a avea i latou mo’u i lena aso o le a Ou alu atu ai e faaputuputu a’u maa tāua."},{"verse":4,"text":"O lea, e tatau ai ona aoa’iina ma tofotofoina i latou, e pei lava o Aperaamo, o lē na poloaiina e tuu atu lona atalii e toatasi."},{"verse":5,"text":"Aua o i latou uma o e e lē onosaia le aoa’iga, ae teena a’u, e lē mafai ona faapaiaina."},{"verse":6,"text":"Faauta, Ou te fai atu ia te outou, sa i ai misa, ma finauga, ma losilosivalega, ma fetauaiga, ma tuinanauga ma manaoga matape’ape’a i totonu o i latou; o lea na latou faaeleelea ai o latou tofi i ia mea."},{"verse":7,"text":"Sa gese ona latou faalogo i le siufofoga o le Alii lo latou Atua; o lea, ua gese ai ona faafofoga mai o le Alii lo latou Atua ia latou tatalo, e tali mai i latou i le aso o lo latou faalavelave."},{"verse":8,"text":"I le aso o lo latou filemu sa latou manatu māmā ai i la’u fautuaga; ae, i le aso o lo latou faalavelave, latou te saili e aapa mai ia te a’u ona ua tatau ai."},{"verse":9,"text":"E moni ou te fai atu ia te outou, e ui i a latou agasala, ua tumu o’u lagona i le agaalofa ia te i latou. O le a Ou lē lafoaia ese atoatoa i latou; ma o le a Ou manatua le alofa mutimutivale i le aso o le toasa."},{"verse":10,"text":"Ua Ou tauto, ma ua tuuina atu le folafolaga e ala i se uluai poloaiga na Ou tuuina atu ia te outou, o le a Ou faatoilaloina i le pelu o lo’u ita mo lo’u nuu; ma e pei ona Ou fai atu, o le a faapea lava ona faataunuuina."},{"verse":11,"text":"Ua lata ona faalautele atu lo’u ita lē faatapulaaina i luga o atunuu uma; ma o le a Ou faia lenei mea pe a tumu le ipu o lo latou amioletonu."},{"verse":12,"text":"Ma i lena aso, o i latou uma o e e maua i luga o le ’olo-vaai, po o i ni isi upu, o la’u Isaraelu uma, o le a faaolaina."},{"verse":13,"text":"Ma o i latou o e sa faataapeapeina o le a faapotopotoina."},{"verse":14,"text":"Ma o i latou uma o e sa faanoanoa o le a faamafanafanaina."},{"verse":15,"text":"Ma o i latou uma o e sa tuu atu o latou ola ona o lo’u igoa o le a faapaleina."},{"verse":16,"text":"O lea, ia faamafanafanaina o outou loto e faatatau ia Siona; aua ua i ai tagata uma i o’u lima; ia filemu ma iloa o A’u o le Atua."},{"verse":17,"text":"O le a lē aveesea Siona i fafo mai lona nofoaga, e ui ina faataapeapeina ana fanau."},{"verse":18,"text":"O i latou o e e totoe, ma ua mamā i loto, o le a toe foi mai, ma toe maua o latou tofi, o i latou ma a latou fanau, faatasi ma pese o le olioli tumau e faavavau, e atia’e nofoaga tuufua o Siona—"},{"verse":19,"text":"Ma o le a oo mai nei mea uma ina ia mafai ona faataunuuina valoaga a perofeta."},{"verse":20,"text":"Ma, faauta, e leai se isi nofoaga ua tofia nai lo lena ua Ou tofia; pe o le a i ai se isi nofoaga e tofia nai lo lena ua Ou tofia, mo le galuega o le faapotopotoina o la’u au paia—"},{"verse":21,"text":"Seia oo mai le aso e lē toe maua ai se avanoa mo i latou; ma ona i ai lea ia te A’u isi nofoaga o le a Ou tofi atu ia te i latou, ma o le a ta’ua i latou o siteki, mo pupuni po o le malosi o Siona."},{"verse":22,"text":"Faauta, o lo’u lava loto, o i latou uma o e e valaau mai i lo’u igoa, ma tapuai mai ia te a’u e tusa ma la’u talalelei tumau e faavavau, e tatau ona faapotopoto faatasi, ma tutulai i nofoaga paia;"},{"verse":23,"text":"Ma sauni mo le faaaliga o le a oo mai, pe a to ese le veli o le ufiufi o lo’u malumalu, i totonu o lo’u fale fetafai, lea ua natia ai le lalolagi, ma o le a vaai faatasi ai tagata uma ia te a’u."},{"verse":24,"text":"Ma o mea uma e pala, po o a tagata, po o a manu o le fanua, po o a manufelelei o le lagi, po o a ī’a o le sami, e mau i luga o le lalolagi atoa, o le a susunuina;"},{"verse":25,"text":"Ma o mea foi o le elemene o le a liusuavai i le vevela tele; ma o mea uma o le a faafouina, ina ia mafai ona mau o lo’u poto ma lo’u mamalu i le lalolagi uma."},{"verse":26,"text":"Ma i lena aso o le feitaga’i o tagata, ma le feitaga’i o manu, ioe, o le feitaga’i o meaola ma tagata uma, o le a taofia mai o’u luma."},{"verse":27,"text":"Ma i lena aso soo se mea e ole atu ai soo se tagata, o le a tuu mai ia te ia."},{"verse":28,"text":"Ma i lena aso o le a leai se mana ia Satani e faaosooso ai soo se tagata."},{"verse":29,"text":"Ma o le a leai se faanoanoa aua o le a leai se oti."},{"verse":30,"text":"I lena aso o le a lē oti se tamameamea seia matua o ia; ma o lona ola o le a pei o tausaga o se laau;"},{"verse":31,"text":"Ma pe a oti o ia o le a lē moe o ia, o lona uiga i le eleele, ae o le a liua i le emo o le mata, ma o le a segia i luga, ma o le a mamalu lava lona malologa."},{"verse":32,"text":"Ioe, e moni Ou te fai atu ia te outou, i lena aso pe a afio mai le Alii, o le a faaali mai e ia mea uma—"},{"verse":33,"text":"O mea ua mavae atu, ma mea natia sa lei iloa e se tagata, o mea o le lalolagi, o mea na faia ai, ma lona faamoemoega ma lona iuga—"},{"verse":34,"text":"O mea sili ona pele, o mea o i lugā, ma mea o i lalō, o mea o i totonu o le lalolagi, ma luga o le lalolagi, ma i le lagi."},{"verse":35,"text":"Ma o i latou uma o e e mafatia i sauaga ona o lo’u igoa, ma tumau i le faatuatua, e ui ina valaauina i latou e tuu atu o latou ola mo a’u ae o le a tofusia i latou i lenei mamalu."},{"verse":36,"text":"O le mea lea, aua le fefefe e oo lava i le oti; ona e lē atoatoa lo outou olioli i le lalolagi lenei, ae o a’u e atoatoa ai lo outou olioli."},{"verse":37,"text":"O le mea lea, aua le popole i le tino, po o le ola o le tino; ae ia popole i le agaga, ma le ola o le agaga."},{"verse":38,"text":"Ma ia saili fofoga o le Alii i taimi uma, ina ia mafai ona outou maua o outou agaga i le onosai, ma o le a outou maua ai le ola e faavavau."},{"verse":39,"text":"A valaaulia tagata i la’u talalelei tumau e faavavau, ma osifeagaiga i se feagaiga tumau e faavavau, e faitauina i latou o le masima o le lalolagi ma le faaola o tagata;"},{"verse":40,"text":"Ua valaaulia i latou e avea ma faaola o tagata; o lea, afai e toesea le malosi faaola o le masima o le lalolagi, faauta, e mai i lena taimi ona lē toe aoga ai mo se mea, na’o le lafoa’iina i fafo ma soli i lalo i vae o tagata."},{"verse":41,"text":"Faauta, o le poto lenei e faatatau i fanau a Siona, le toatele lea, ae lē o i latou uma; na maua i latou o ni tagata solitulafono, o lea e tatau ai ona aoa’iina i latou—"},{"verse":42,"text":"O ia o lē na te faaeaina o ia lava o le a faamaualaloina, ma o ia o lē na te faamaualalo o ia lava o le a faaeaina."},{"verse":43,"text":"Ma o lenei, o le a Ou faaali atu ia te outou se faataoto, ina ia mafai ona outou iloa lo’u loto e faatatau i le laveaiina o Siona."},{"verse":44,"text":"E i ai se tasi alii sili sa i ai se fasi fanua, sa silisili lava ona lelei; ma sa fai atu o ia i ana auauna: Ia outou o atu i lo’u tovine, i luga o lenei lava fasi fanua silisili ona lelei, ma totō ai ni laau olive e sefulu ma le lua;"},{"verse":45,"text":"Ma faatutu ni leoleo faataamilo ia i latou, ma fausia se olo, ina ia mafai e se toatasi ona vaavaai atu i le fanua faataamilo, e avea o se leoleo i luga o le olo, ina ia lē gauia i lalo o’u laau olive pe a sau le fili e faaleaga ma ave mo i latou lava le fua o lo’u tovine."},{"verse":46,"text":"O lenei, sa o atu auauna a le alii sili ma faia e pei ona sa poloaiina ai i latou e lo latou alii, ma toto laau olive, ma fausia se pa faataamilo, ma faatutu ni leoleo, ma amata ona fausia se olo."},{"verse":47,"text":"Ma a’o latou faataatia lona faavae i lea lava taimi, sa amata ona latou fai ane i totonu o i latou lava: Ma o se a se mea ua manaomia ai e lo’u alii lenei olo?"},{"verse":48,"text":"Ma sa talanoa mo se taimi umi lava, ua fai ane i totonu o i latou lava: O le a se mea ua manaomia ai e lo’u alii lenei olo, talu ai o le taimi lenei o le filemu?"},{"verse":49,"text":"E lē mafai ea ona avatu lenei tupe i e suitupe? Ona ua leai se manaomia o nei mea."},{"verse":50,"text":"Ma a’o latou fefinaua’i o le tasi ma le isi sa oo ina latou faapaie tele, ma sa latou lē faalogo i poloaiga a lo latou alii."},{"verse":51,"text":"Ma sa sau le fili i le po, ma lepeti i lalo le pa; ma sa tutu i luga auauna a le alii sili ma sa fefefe, ma ua sosola; ma sa faaleaga e le fili a latou galuega, ma gaui i lalo laau olive."},{"verse":52,"text":"O lenei, faauta, sa valaau e le alii sili, le pule o le tovine, ana auauna, ma fai atu ia te i latou, Aisea! o le a le pogai o lenei leaga tele?"},{"verse":53,"text":"Sa lē tatau ea ona outou faia e pei ona Ou poloaiina ai outou, ma—ina ua uma ona outou toto le tovine, ma fai le pa faataamilo ai, ma faatutu ni leoleo i luga o ona puipui—fausia foi le olo, ma faatutu ni leoleo i luga o le olo, ma leoleo i lo’u tovine, ma lē momoe lava, ne’i sau i o outou luga le fili?"},{"verse":54,"text":"Ma faauta, semanu e iloa atu e le leoleo i luga o le olo le fili a’o mamao atu o ia; ma semanu na mafai ai ona outou sauni ma taofi le fili mai le lepetia i lalo o lona pa, ma faasao ai lo’u tovine mai lima o lē faaumatia."},{"verse":55,"text":"Ma sa fai atu le alii o le tovine i se tasi o ana auauna: Alu ma faapotopoto mai faatasi e o totoe o a’u auauna, ma ave le malosi uma o lo’u fale, o a’u tagata tau ia, o a’u alii talavou, ma i latou o faamatuā tagata foi o i totonu o a’u auauna uma, o e o le malosi o lo’u fale, vagana ai i latou o e ua ou tofia e nonofo;"},{"verse":56,"text":"Ma ia outou o atu vave i le fanua o lo’u tovine, ma toe faaola mai lo’u tovine; ona e a a’u; sa ou faatauina i tupe."},{"verse":57,"text":"O lea, ia outou o atu vave i lo’u fanua; lepeti i lalo pa o o’u fili; lafo i lalo lo latou olo, ma faataapeape o latou leoleo."},{"verse":58,"text":"Ma e tusa ai ma lo latou potopoto faatasi e faasaga mai ia te outou, ia tauimasui a’u i o’u fili, ina ia vave ona ou alu atu faatasi ma e o totoe o lo’u fale ma nonofo i le fanua."},{"verse":59,"text":"Ma sa fai atu le auauna i lona alii: O afea o le a i ai ia mea?"},{"verse":60,"text":"Ma sa fai atu o ia i lana auauna: Pe a ou loto i ai; alu atu vave ia oe, ma fai mea uma ua ou poloaiina ai oe;"},{"verse":61,"text":"Ma o le a avea lenei ma a’u faamaufaailoga ma faamanuiaga i ou luga—o se tausimea faamaoni ma le atamai i totonu o lo’u fale, o se pule i lo’u malo."},{"verse":62,"text":"Ma sa alu atu vave lana auauna, ma faia mea uma o soo se mea na poloaiina ai o ia e lona alii; ma ina ua mavae aso e tele sa faataunuuina mea uma."},{"verse":63,"text":"O lenei foi, e moni Ou te fai atu ia te outou, o le a Ou faaali atu ia te outou le poto o ia te a’u e faatatau i aulotu uma, e tusa ai ma lo latou loto ia taitaiina i latou i se ala sa’o ma tatau ai mo lo latou faaolataga—"},{"verse":64,"text":"Ina ia mafai ona faaauau o le galuega o le faapotopotoina faatasi o la’u au paia, ina ia mafai ona Ou atia’e o i latou i lo’u igoa i luga o nofoaga paia; ona ua oo mai le taimi o le seleselega, ma ua tatau ona faataunuuina o la’u upu."},{"verse":65,"text":"O lea, e ao ina Ou faapotopoto faatasi lo’u nuu, e tusa ma le faataoto i le saito ma titania, ina ia mafai ona faasaoina o saito i le faleteusaito ia maua le ola e faavavau, ma faapaleina i le mamalu selesitila, pe a Ou alu atu i le malo o lo’u Tamā e taui i tagata taitoatasi e tusa ma ana galuega e pei o le a i ai;"},{"verse":66,"text":"A’o titania o le a noatia i fusi, ma o le a faamalolosi o latou noanoa, ina ia susunuina i latou i le afi e lē matineia."},{"verse":67,"text":"O lea, Ou te tuu atu se poloaiga i aulotu uma, ia faaauau pea ona latou faapotopoto faatasi i nofoaga ua Ou tofia i ai."},{"verse":68,"text":"Ae ui i lea, e pei ona Ou fai atu ia te outou i se poloaiga muamua, aua le faanatinatia lo outou faapotopotoina, pe i se sola’aga; ae ia mua’i saunia mea uma i o outou luma."},{"verse":69,"text":"Ma ina ia mafai ona mua’i saunia mea uma i o outou luma, ia tausi i le poloaiga ua Ou tuuina atu e faatatau i nei mea—"},{"verse":70,"text":"Lea ua fai mai, pe ua aoao mai, ia faatau mai fanua uma i tupe, e mafai ona faatauina i tupe, i le itulagi faataamilo i le laueleele ua Ou tofia e avea ma laueleele o Siona, mo le amataga o le faapotopotoina o la’u au paia;"},{"verse":71,"text":"O laueleele uma e mafai ona faatau mai i le itumalo o Siakisone, ma itumalo faataamilo ai, ma tuu mai le vaega e totoe i lo’u lima."},{"verse":72,"text":"O lenei, e moni Ou te fai atu ia te outou, ia tuu atu i aulotu uma e faaputuputu faatasi a latou tupe uma; ia tuu atu ia mea ia faia i o latou taimi, ae lē i le faanatinati; ma vaai ia mua’i saunia mea uma i o outou luma."},{"verse":73,"text":"Ma ia tuu atu e tofia ni alii mamalu, o ni tagata atamamai lava, ma auina atu i latou e faatau mai ia laueleele."},{"verse":74,"text":"Ma o aulotu i itu-laueleele i sasa’e, a atia’e i luga i latou, afai latou te faalogo i lenei fautuaga e mafai ona latou faatau mai laueleele ma faapotopoto faatasi ai i luga; ma i lenei ala e mafai ona faamautuina ai i latou i Siona."},{"verse":75,"text":"Ua i ai i le taimi nei lava ni mea ua uma ona teuina, ioe, ua tele lava, e toe faaola mai ai Siona, ma faamaumaututu ai ona nofoaga tuufua, e lē toe lafoina i lalo, pe a na loto aulotu, o e ua ta’ua i latou lava i lo’u igoa, e faalogo mai i lo’u leo."},{"verse":76,"text":"Ma Ou te toe fai atu ia te outou, o i latou o e na faataapeapeina e o latou fili, o lo’u loto e tatau ona latou faaauau pea ona tagi atu mo le toe totogi mai, ma le toe faaola mai, e ala i lima o i latou o e ua tuu e avea ma pule ma ua i ai le pule i luga o outou—"},{"verse":77,"text":"E tusa ma tulafono ma le tulafono faavae a le atunuu, lea na Ou tuu ia faatuina, ma e tatau ona tausia mo aiā tatau ma le puipuiga o tagata uma, e tusa ma mataupu autu tonu ma paia;"},{"verse":78,"text":"Ina ia mafai e tagata taitoatasi ona faia e tusa ma mataupu faavae ma mataupu autu e faatatau i le lumanai, e tusa ma le faitalia ua Ou tuu atu ia te ia, ina ia mafai e tagata taitoatasi ona tali mo ana lava agasala i le aso o le faamasinoga."},{"verse":79,"text":"O lea, e lē sa’o ona tatau ona nofo pologa soo se tagata o le tasi i le isi."},{"verse":80,"text":"Ma o le faamoemoega lenei na Ou faatuina ai le Tulafono Faavae o le laueleele lenei, e ala i lima o alii atamamai o e na Ou faatutuina mai i luga mo lenei lava faamoemoe, ma toe maua mai le laueleele e ala i le faamasaaina o le toto."},{"verse":81,"text":"O lenei, o se a se mea a Ou faatusa i ai fanau a Siona? O le a Ou faatusaina i latou i le faataoto e uiga i le fafine ma le faamasino amioletonu, aua e tatau i tagata ona tatalo e lē aunoa ma ia lē vaivai, ua fai mai—"},{"verse":82,"text":"Sa i ai i se aai se faamasino sa lē mata’u i le Atua, pe sa ava i tagata."},{"verse":83,"text":"Ma sa i ai i lena aai se fafine ua oti lana tane, ma sa alu atu le fafine i le faamasino, ua fai atu: Ia e tauimasui i lo’u fili."},{"verse":84,"text":"Ma sa lē faia e le faamasino mo se taimi, ae mulimuli ane ua fai ifo o ia i totonu o ia lava: E ui ina ou lē mata’u i le Atua, pe ava i tagata, ae ona o le faalavelave mai ia te a’u o lenei fafine ua oti lana tane o le a ou tauimasui atu ai mo ia, ne’i ou fiu i lona sau soo."},{"verse":85,"text":"O le a faapea ona Ou faatusaina o fanau a Siona."},{"verse":86,"text":"Ia tuu atu i latou e tagi atu i vae o le faamasino;"},{"verse":87,"text":"Ma afai e lē amanaia i latou e ia, ia tuu atu ia te i latou e tagi atu i vae o le kovana;"},{"verse":88,"text":"Ma afai e lē amanaia i latou e le kovana, ia tuu atu ia te i latou e tagi atu i vae o le peresitene;"},{"verse":89,"text":"Ma afai e lē amanaia i latou e le peresitene, ona tulai lea o le Alii ma afio mai lona afioaga lilo, ma i lona toasa ua lutia ai le atunuu;"},{"verse":90,"text":"Ma o le a ia vavae ese i le aasa o lona lē fiafia, ma i lona toasa tele, i lona taimi, i latou na o tausimea amioleaga, lē faamaoni, ma lē tonu, ma tofi atu ia te i latou la latou vaega i totonu o tagata pepelo, ma e e lē talitonu;"},{"verse":91,"text":"I le pogisa lava i fafo, i le mea e i ai le tagi, ma le auē, ma le lilivau o nifo."},{"verse":92,"text":"O lea, ia outou tatalo ai, ina ia tatala mai o latou taliga ia outou tagi, ina ia Ou alofa mutimutivale ia te i latou, ina ia lē oo mai ia mea i luga o i latou."},{"verse":93,"text":"O mea ua Ou fai atu ai ia te outou e tatau ona i ai, ina ia tuua tagata uma e aunoa ma se ’alofaga."},{"verse":94,"text":"Ina ia mafai e tagata atamamai ma pule ona faalogo ma iloa mea latou te lei manatu lava i ai;"},{"verse":95,"text":"Ina ia mafai ona Ou faagasolo e faataunuu la’u faiga, o la’u faiga uiga ese, ma fai la’u galuega, o la’u galuega uiga ese, ina ia mafai ona iloatino e tagata le eseesega o le amiotonu ma le amioleaga, ua fetalai mai ai lo outou Atua."},{"verse":96,"text":"O lenei foi, Ou te fai atu ia te outou, ua lē tusa ai ma la’u poloaiga ma lo’u loto ona tatau ona faatau atu e la’u auauna o Sini Gilbert i lima o o’u fili, lo’u faleteuoloa, lea na Ou tofia mo lo’u nuu."},{"verse":97,"text":"Ia lē tuuina atu mea ua Ou tofia ia faaeleeleaina e o’u fili, i se maliega a i latou o e ua valaauina i latou lava i lo’u igoa;"},{"verse":98,"text":"Ona o se agasala tiga tele lenei ma mamafa e faasaga mai ia te a’u, ma faasaga i lo’u nuu, ona o mea na ua Ou folafola atu ma ua lata ona pa’u’ū mai i atunuu."},{"verse":99,"text":"O lea, o lo’u loto e tatau i lo’u nuu ona aiā, ma taofi le aiā i luga o mea na Ou tofia ia te i latou, e ui ina lē faatagaina i latou e nonofo ai iina."},{"verse":100,"text":"Ae ui i lea, Ou te lē o fai atu ia latou lē nonofo iina; ona e tusa ai ma le latou aumaia o fua ma galuega tatau ai mo lo’u malo o le a latou nonofo ai iina."},{"verse":101,"text":"O le a latou atia’e, ma o le a lē avea ma tofi o se tasi e ese mai; o le a latou totō tovine, ma o le a latou ’ai ona fua. E faapea lava. Amene."}]},{"chapter":102,"verses":[{"verse":1,"text":"O Le aso nei na potopoto ai se aufono aoao o faitaulaga sili e toaluasefulufa i le fale o Iosefa Samita, Le Itiiti, e ala i le faaaliga, ma aga e faatulaga le aufono maualuga o le Ekalesia a Keriso, lea e tatau ona i ai ni faitaulaga sili e toasefululua, ma se toatasi po o le toatolu o peresitene e pei atonu e manaomia ai mo le mataupu."},{"verse":2,"text":"Sa tofia le aufono maualuga i le faaaliga mo le faamoemoe o le foiaina o faafitauli taua atonu e tulai mai i le ekalesia, ia e lē mafai ona foia e le ekalesia po o le aufono a le epikopo i le lotomalilie o vaega uma."},{"verse":3,"text":"Sa talia Iosefa Samita, Le Itiiti, Sini Rikitone ma Feterika G. Viliamu o peresitene i le leo o le aufono; ma o Iosefa Samita, Matua, Ioane Samita, Iosefa Kou, Ioane Ioanesone, Matini Harisi, Ioane S. Kata, Iareto Kata, Oliva Kaotui, Samuel H. Samita, Orson Hyde, Sylvester Samita, ma Luka Ioanesone, o faitaulaga sili, sa filifilia e avea o se aufono tumau mo le ekalesia, i le leo autasi o le aufono."},{"verse":4,"text":"Ona fesiligia lea o ia fautua ua ta’ua i luga pe latou te taliaina o latou tofiga, ma pe o le a latou galulue i lena tofiga e tusa ma le tulafono a le lagi, lea sa latou tali atu uma i ai ua latou talia o latou tofiga, ma o le a faia o latou tofi e tusa ma le alofa tunoa o le Atua ua faaee mai i luga o i latou."},{"verse":5,"text":"O le aofai na aofia i le aufono, o e na palota i le igoa ma mo le ekalesia i le tofiaina o fautua ua ta’ua i luga e toafasefulu-tolu, e pei ona sosoo ai: toaiva faitaulaga sili, toasefulufitu toeaina, toafa ositaulaga, ma tagata o le ekalesia e toasefulutolu."},{"verse":6,"text":"Palotaina: e lē mafai e le aufono maualuga ona maua se pule e fai ai se mea e aunoa ma se toafitu o fautua ua ta’ua i luga, po o le auai o ni o latou sui tofia tatau ai."},{"verse":7,"text":"Ua i ai i lenei toafitu le pule e tofia ai isi faitaulaga sili, o e ua latou manatu ua agavaa ma agatonu e galue i le tulaga o fautua ua lē auai."},{"verse":8,"text":"Palotaina: soo se taimi e tupu mai ai se avanoa i le maliu, aveesea mai le tofi ona o le solitulafono, po o le alu ese atu mai tuaoi o le pulega lenei o le ekalesia, o soo se tasi o fautua ua ta’ua i luga, ia faatumuina i le filifiliga a le peresitene po o peresitene, ma faamaonia i le leo o le aufono aoao o faitaulaga sili, e potopoto mo lena faamoemoe, e galulue i le igoa o le ekalesia."},{"verse":9,"text":"O le peresitene o le ekalesia, o lē o le peresitene foi o le aufono, e tofia i le faaaliga, ma lagolagoina i lana pulega i le leo o le ekalesia."},{"verse":10,"text":"Ma ua tusa ai ma le mamalu o lona tofi le tatau ai ona pulefaamalumalu o ia i luga o le aufono a le ekalesia; ma o lana aiā tatau le fesoasoani ia te ia o ni isi peresitene e toalua, e tofia i le ala e tasi na tofia ai o ia."},{"verse":11,"text":"Ma i le tulaga o le toesea o se toatasi po o i laua uma o e ua tofia e fesoasoani ia te ia, ua i ai ia te ia le pule e pulefaamalumalu ai i luga o le aufono e aunoa ma se fesoasoani; ma i le tulaga e toesea ai o ia lava, ua i ai i isi peresitene le pule e pulefaamalumalu ai i lona tulaga, i laua uma po o soo se tasi o i laua."},{"verse":12,"text":"Soo se taimi e faatulaga tatau ai se aufono maualuga o le Ekalesia a Keriso, e tusa ma le ata ua mavae atu nei, o le tiute o fautua e toasefululua le faia o se vili i fuainumera, ma iloa ai i lena mea po o ai o le toasefululua e saunoa muamua, e amata mai le numera tasi ma faasolo atu ai faapena i le numera e sefululua."},{"verse":13,"text":"Soo se taimi e potopoto ai lenei aufono e soalaupule soo se mataupu, e iloilo e fautua e toasefululua pe o se mataupu faigata pe leai; afai e lē faigata, nao le toalua fautua e saunoa i ai, e tusa ma le ala ua tusia i luga."},{"verse":14,"text":"Ae afai e manatu ua faigata, ia tofia se toafa; ma afai ua sili atu ona faigata, e toaono; ae e leai se tulaga ia sili atu ai i le ono e e tofia e saunoa."},{"verse":15,"text":"O lē ua molia, i mataupu uma lava, ua i ai se aiā i le afa o le aufono, e puipuia ai mai le faalumaina po o le faamasinoletonu."},{"verse":16,"text":"Ma o fautua ua tofia e saunoa i luma o le aufono e tuuina atu le mataupu, pe a uma ona iloiloina faamaoniga, i lona malamalama moni i luma o le aufono; ma ia saunoa tagata taitoatasi e tusa ma le lē faaituau ma le faamasinotonu."},{"verse":17,"text":"O fautua o e na seia numera soagia, o lona uiga, o le 2, 4, 6, 8, 10, ma le 12, o tagata ia o e ia tutu atu mo lē ua molia, ma puipui mai ai i le faalumaina ma le faamasinoletonu."},{"verse":18,"text":"I mataupu uma lava, ia maua e lē ua tagi ma lē ua molia se avanoa e saunoa ai mo i laua lava i luma o le aufono, pe a uma ona fofogaina o faamaoniga ma pe a uma saunoaga a fautua o e na tofia e saunoa i le mataupu."},{"verse":19,"text":"A uma ona fofogaina o faamaoniga, ma saunoa fautua, ma lē ua tagi ma lē ua molia, ona tuu atu lea e le peresitene se faaiuga e tusa ma le malamalamaaga ua ia te ia e uiga i le mataupu, ma talosaga atu i fautua e toasefululua e faamaonia lea faaiuga e tasi i lo latou siilima."},{"verse":20,"text":"Ae a iloa e le vaega o fautua o totoe, o e sa lei saunoa, po o soo se tasi o i latou, se sese i le faaiuga a le peresitene, ina ua uma ona faalogo ma le lē faailoga tagata i faamaoniga ma aioiga, e mafai ona latou faaali mai lena sese, ma ia toe faia ai se iloiloga."},{"verse":21,"text":"Ma afai, e faaalia se malamalama faaopoopo e uiga i le mataupu, ina ua mavae le toe iloiloga toto’a ma le faaeteete, ia suia le faaiuga e faatatau i ai."},{"verse":22,"text":"Ae i le tulaga e leai ai se malamalama faaopoopo e tuuina mai, e tumau le faaiuga muamua, ma ua i ai i le toatele o le aufono le pule e fai ai lena lava faaiuga."},{"verse":23,"text":"I le tulaga o se faigata e faatatau i se aoaoga faavae po o se mataupu autu, afai ua lē lava mea ua tusia e faamanino ai le mataupu i mafaufau o le aufono, e mafai e le peresitene ona ole atu ma maua le mafaufau o le Alii e ala i le faaaliga."},{"verse":24,"text":"Ua i ai i faitaulaga sili, pe a i ai i fafo, le pule e talo ma faatulaga ai se aufono e tusa ma le ala ua mavae ona ta’ua nei, e fo’ia ai faafitauli, pe a talosagaina e ni vaega po o soo se tasi o i latou."},{"verse":25,"text":"Ma ua i ai i lea aufono o faitaulaga sili ua ta’ua le pule e tofia ai se tasi o i latou e pulefaamalumalu i se aufono faapena mo lena taimi."},{"verse":26,"text":"Ia avea ma tiute o le aufono ua ta’ua le auina atu, i le taimi lava lea, se kopi o a latou taualumaga, ma se faamatalaga atoa o le molimau e o faatasi ma la latou faaiuga, i le aufono maualuga i le nofoaga tutotonu o le Au Peresitene Sili o le Ekalesia."},{"verse":27,"text":"Afai e lē malilie vaega po o se tasi o i latou i le faaiuga a le aufono ua ta’ua, e mafai e i latou ona apili atu i le aufono maualuga o le nofoa o le Au Peresitene Sili o le Ekalesia, ma maua se toe iloiloga, ma o lea mataupu ia faia, e tusa ma le ala muamua ua tusia, e faapei e leai lava se faaiuga na faia."},{"verse":28,"text":"O lenei aufono o faitaulaga sili e i fafo, ia nao tulaga silisili ona faigata o mataupu tau i le ekalesia e talo ai; ma ua leai se mataupu masani pe taatele ua alagatatau ai ona talo se aufono faapena."},{"verse":29,"text":"Ua i ai i faitaulaga sili femalagaai po ua nonofo i fafo le pule e fai mai ai pe ua tatau ona talo se aufono faapena pe leai."},{"verse":30,"text":"Ua i ai se eseesega i le va o le aufono maualuga po o faitaulaga sili femalagaai i fafo, ma le ’aufono maualuga femalagaai ua i ai aposetolo e toasefululua, ia latou faaiuga."},{"verse":31,"text":"O le faaiuga a le aufono muamua atu e mafai ona apili; ae o le faaiuga a le aufono mulimuli e lē mafai."},{"verse":32,"text":"Na’o pulega aoao o le ekalesia e mafai ona fesiligia faaiuga a le aufono mulimuli lea i le tulaga o le solitulafono."},{"verse":33,"text":"Autasia: Ua i ai i le nofoa o le peresitene po o peresitene o le Au Peresitene Sili o le Ekalesia le pule e filifili ai pe ua agatonu tatau ai soo se mataupu faapena atonu e apili atu, mo se toe iloiloga, pe a uma lea ona suesueina o le apili ma faamaoniga ma faamatalaga ua tuuina atu faatasi ma le apili."},{"verse":34,"text":"Ona aga atu lea o fautua e toasefululua i le vili po o le palota, e iloa ai po o ai e tatau ona saunoa muamua, ma o le iuga lenei, sa faapea: 1. Oliva Kaotui; 2. Iosefa Kou; 3. Samuel H. Samita; 4. Luka Ioanesone; 5. Ioane S. Kata; 6. Sylvester Samita; 7. Ioane Ioanesone; 8. Orson Hyde; 9. Iareto Kata; 10. Iosefa Samita, Matua; 11. Ioane Samita; 12. Matini Harisi.Ina ua uma le tatalo sa tuua le konafesi."},{"verse":35,"text":"Oliva Kaotui,"},{"verse":36,"text":"Orson Hyde,"},{"verse":37,"text":"Failautusi"}]},{"chapter":103,"verses":[{"verse":1,"text":"E Moni Ou te fai atu ia te outou, a’u uo e, faauta, o le a Ou tuu atu ia te outou se faaaliga ma se poloaiga, ina ia outou iloa le ala e amio ai i le faataunuuina o o outou tiute e faatatau i le faaolataga ma le togiolaina o o outou uso, o e ua faataapeapeina i luga o le laueleele o Siona;"},{"verse":2,"text":"Aua ua tulia ma taia i lima o o’u fili, o e o le a Ou sasaa atu i ai i luga lo’u ita e lē mafuatia i lo’u lava taimi e tatau ai."},{"verse":3,"text":"Aua ua faapea ona Ou tuu atu ia te i latou e oo mai i lenei taimi, ina ia latou faatumuina le fuataga o a latou amioletonu, ina ia tumu la latou ipu;"},{"verse":4,"text":"Ma ina ia mafai ona aoaiina i latou o e ua ta’ua i latou lava i lo’u igoa mo se vaitau itiiti i se aoaiga tiga ma mamafa, aua sa latou lē faalogo atoa mai i faatonuga ma poloaiga na Ou tuu atu ia te i latou."},{"verse":5,"text":"Peitai e moni Ou te fai atu ia te outou, ua Ou folafolaina se folafolaga, lea o le a maua e lo’u nuu, pe afai latou te faalogo mai i lenei lava itula i le fautuaga o le a tuu atu e A’u, o le Alii lo latou Atua, ia te i latou."},{"verse":6,"text":"Faauta, ona ua Ou folafolaina, o le a amata atu mai lenei lava itula ona latou manumalo e faasaga i o’u fili."},{"verse":7,"text":"Ma o le faaeteete e tausi i upu uma o le a tautala atu ai A’u, o le Alii lo latou Atua, ia te i latou, o le a lē taofia ai lava ona latou manumalo seia oo ina faatoilaloina malo o le lalolagi i lalo o o’u vae, ma tuuina atu le lalolagi i le au paia, e fai mo i latou e faavavau ma faavavau lava."},{"verse":8,"text":"Ae afai latou te lē tausia a’u poloaiga, ma lē faalogo e tausi i a’u upu uma, o le a manumalo malo o le lalolagi e faasaga ia te i latou."},{"verse":9,"text":"Aua sa faatutu mai i latou e avea ma malamalama i le lalolagi, ma avea ma faaola o tagata;"},{"verse":10,"text":"Ma e tusa ai ma le lē avea o i latou ma faaola o tagata, e pei i latou o le masima ua magalo, ma e leai se mea e toe aoga i ai mai lena taimi ma le agai i luma, ae nao le lafoaiina i fafo ma solia i lalo o vae o tagata."},{"verse":11,"text":"Peitai e moni Ou te fai atu ia te outou, ua Ou folafola o le a toe foi mai o outou uso ua faataapeapeina i laueleele o o latou tofi, ma o le a latou atia’e nofoaga tuufua o Siona."},{"verse":12,"text":"Aua a mavae puapuaga e tele, e pei ona Ou fai atu ai ia te outou i se poloaiga ua mavae, ona oo mai lea o le faamanuiaga."},{"verse":13,"text":"Faauta, o le faamanuiaga lenei na Ou folafola atu pe a mavae o outou puapuaga, ma puapuaga o o outou uso—o le laveaiina lea o outou, ma le laveaiina o o outou uso, o lo latou toefuataiga lava lea i le laueleele o Siona, e faamautuina, e lē toe lafoina i lalo."},{"verse":14,"text":"Ae ui i lea, afai latou te faaeleelea o latou tofi, o le a lafoina i latou i lalo; ona o le a Ou lē faasaoina i latou pe afai latou te faaeleelea o latou tofi."},{"verse":15,"text":"Faauta, Ou te fai atu ia te outou, o le laveaiina o Siona e ao ina oo mai e ala i le mana;"},{"verse":16,"text":"O lea, o le a Ou faatuina a’e i lo’u nuu se tagata, o lē o le a taitaia i latou e pei ona sa taitaia e Mose le fanauga a Isaraelu."},{"verse":17,"text":"Aua o outou o fanau a Isaraelu, ma o le fanau a Aperaamo, ma e ao ina taitai ese outou mai le nofo pologa i le mana, ma le aao faaloaloa atu."},{"verse":18,"text":"Ma e pei ona sa taitaiina muamua o outou tamā, o le a faapea lava le laveaiina o Siona."},{"verse":19,"text":"O lea, ia lē tuu atu o outou loto ia faavaivai, aua Ou te lē fai atu ia te outou e pei ona sa Ou fai atu i o outou tamā: O le a alu atu la’u agelu e muamua atu ia te outou, ae lē o lo’u mamalu."},{"verse":20,"text":"Ae Ou te fai atu ia te outou: O le a o atu a’u agelu e muamua atu ia te outou, ma lo’u mamalu foi, ma o le a outou maua le laueleele lelei i se taimi."},{"verse":21,"text":"E moni, e moni Ou te fai atu ia te outou, o la’u auauna o Iosefa Samita, Le Itiiti, o le tagata lea ua Ou faatusa i ai le auauna o lē na fetalai atu i ai le Alii o le tovine i le faataoto lea na Ou tuu atu ia te outou."},{"verse":22,"text":"O lea ia tuu atu ai i la’u auauna o Iosefa Samita, Le Itiiti, e fai atu i le malosi o lo’u fale, o a’u alii talavou ma faamatuā-tagata—Ia outou faapotopoto faatasi outou lava i le laueleele o Siona, i luga o le laueleele lea na Ou faatau mai i tupe na faapaia mai ia te a’u."},{"verse":23,"text":"Ma ia tuu atu i aulotu uma e auina atu i luga tagata atamamai ma a latou tupe, ma faatau mai laueleele e pei ona sa Ou poloaiina ai i latou."},{"verse":24,"text":"Ma e tusa ai ma le o mai o o’u fili e faasaga mai ia te outou e tutuli ese outou mai lo’u laueleele lelei, lea ua Ou faapaiaina e avea ma laueleele o Siona, e mai i o outou lava laueleele ina ua mavae ia molimau, ia na outou aumai i o’u luma e faasaga ia te i latou, ia outou fetuu i latou;"},{"verse":25,"text":"Ma o soo se tasi tou te fetuu, o le a Ou fetuuina, ma ia outou taui ma sui atu i o’u fili."},{"verse":26,"text":"Ma o le a faatasi lo’u mamalu ma outou i le taui ma sui atu i o’u fili, e oo atu i le tupulaga e tolu ma le fa o i latou o e e inoino mai ia te a’u."},{"verse":27,"text":"Ia leai se tagata e fefe e tuu atu lona ola ona o a’u; aua o lē e tuu atu lona ola ona o a’u o le a toe maua e ia."},{"verse":28,"text":"Ma ’ai se e lē loto e tuu atu lona ola ona o a’u e lē o so’u soo o ia."},{"verse":29,"text":"O lo’u loto ia siitia a’e e la’u auauna o Sini Rikitone lona leo i faapotopotoga i itu-laueleele i sasa’e, i le sauniuniga o aulotu e tausi i poloaiga ua Ou tuuina atu ia te i latou e faatatau i le toefuataiga ma le laveaiina o Siona."},{"verse":30,"text":"O lo’u loto o la’u auauna o Parley P. Pratt ma la’u auauna o Laimani Uaite e lē tatau ona foi atu i le laueleele o o la uso, seia la maua ni vaega o tagata e o atu i luga i le laueleele o Siona, e taitoasefulu, pe taitoaluasefulu, pe taitoalimagafulu, pe taitoaselau, seia la maua le aofai e lima selau o le malosi o lo’u fale."},{"verse":31,"text":"Faauta o lo’u loto lea; ole mai ma o le a outou maua ai; peitai e lē faia e tagata lo’u loto i taimi uma."},{"verse":32,"text":"O lea, afai e lē mafai ona outou maua le lima selau, ia saili ma le filiga atonu e mafai ona outou maua se tolu selau."},{"verse":33,"text":"Ma afai e lē mafai ona outou maua le tolu selau, ia saili ma le filiga atonu e mafai ona outou maua se tasi selau."},{"verse":34,"text":"Peitai e moni Ou te fai atu ia te outou, Ou te tuu atu ia te outou se poloaiga, ia outou lē o a’e i le laueleele o Siona seia outou maua se toaselau o le malosi o lo’u fale, e o atu faatasi ma outou i le laueleele o Siona."},{"verse":35,"text":"O lea, e pei ona Ou fai atu ia te outou, ole mai ma o le a outou maua ai, tatalo ma le faatauanau atonu e mafai e la’u auauna o Iosefa Samita, Le Itiiti, ona alu atu faatasi ma outou, ma pulefaamalumalu i totonu o lo’u nuu, ma faatulaga lo’u malo i luga o le laueleele ua faapaiaina, ma faamautu fanau a Siona i luga o tulafono ma poloaiga ua tuu atu ma o le a tuuina atu ia te outou."},{"verse":36,"text":"O manumalo ma le mamalu uma e aumai ia te outou e ala i lo outou filiga, faamaoni, ma tatalo o le faatuatua."},{"verse":37,"text":"Ia tuu atu i la’u auauna o Parley P. Pratt e malaga atu faatasi ma la’u auauna o Iosefa Samita, Le Itiiti."},{"verse":38,"text":"Ia tuu atu i la’u auauna o Lyman Wight e malaga atu faatasi ma la’u auauna o Sini Rikitone."},{"verse":39,"text":"Ia tuu atu i la’u auauna o Ailama Samita e malaga atu faatasi ma la’u auauna o Frederick G. Williams."},{"verse":40,"text":"Ia tuu atu i la’u auauna o Orson Hyde e malaga atu faatasi ma la’u auauna o Orson Pratt, i soo se mea e fautuaina ai i laua e la’u auauna o Iosefa Samita, Le Itiiti, i le mauaina o le faataunuuga o nei poloaiga ua Ou tuuina atu ia te outou, ma taatia mai mea o totoe i o’u lima. E faapea lava. Amene."}]},{"chapter":104,"verses":[{"verse":1,"text":"E Moni Ou te fai atu ia te outou, a’u uo e, Ou te tuu atu ia te outou le fautuaga, ma se poloaiga, e uiga i meatotino uma a le faatulagaga na Ou poloaiina ia faatulaga ma faatuina, e avea o se faatulagaga autasi, ma o se faatulagaga tumau e faavavau mo le manuia o la’u ekalesia, ma mo le faaolataga o tagata seia Ou alu atu—"},{"verse":2,"text":"Faatasi ma se folafolaga lē motusia ma lē masuia, e faapea, e tusa ai ma le faamaoni o i latou o e na Ou poloaiina o le a faamanuiaina ai i latou i faamanuiaga e tele;"},{"verse":3,"text":"Ae e tusa ai ma lo latou lē faamaoni sa toetoe a fetuuina ai i latou."},{"verse":4,"text":"O lea, e tusa ai ma le lē tausia e ni isi o a’u auauna le poloaiga, ae ua latou solia le feagaiga e ala i le matape’ape’a, ma upu faatagāfai, ua Ou fetuu ai i latou i se fetuu tiga tele ma mamafa."},{"verse":5,"text":"Aua o A’u, o le Alii, ua folafola i lo’u loto, e faapea, e tusa ai ma le maua o soo se tagata e auai i le faatulagaga o se solitulafono, pe, faapea, ua soli e ia le feagaiga ua fusia ai outou, o le a fetuuina o ia i lona olaga, ma o le a solia i lalo e e Ou te loto i ai;"},{"verse":6,"text":"Aua o A’u, o le Alii, ia lē ulagia i nei mea—"},{"verse":7,"text":"Ma o lenei mea atoa ina ia lē tausalaina e ua mamā i totonu o outou faatasi ma e amioletonu; ma ina ia lē sao e ua sala o i totonu o outou; aua o A’u, o le Alii, na folafola atu ia te outou se pale o le mamalu i lo’u lima taumatau."},{"verse":8,"text":"O lea, e tusa ai ma le mauaina o outou o ni solitulafono, e lē mafai ona outou sao mai lo’u ita i o outou olaga."},{"verse":9,"text":"E tusa ai ma le vavae eseina o outou ona o le solitulafono, e lē mafai ona outou sao i tu’iga a Satani seia oo i le aso o le togiolaina."},{"verse":10,"text":"Ma Ou te tuu atu nei ia te outou le mana mai lenei lava itula, e faapea afai e i ai se tagata, o le faatulagaga, i totonu o outou, e maua o se solitulafono ma ua lē salamo i le leaga, ia outou tuu atu o ia i tu’iga a Satani; ma o le a lē maua e ia le mana e ’aumai ai le leaga i luga o outou."},{"verse":11,"text":"O le poto lea ua ia te a’u; o lea, Ou te tuu atu ia te outou se poloaiga, ia outou faatulaga outou lava ma tofi i tagata taitoatasi lana mea-tausi;"},{"verse":12,"text":"Ina ia mafai e tagata taitoatasi ona tuu mai ia te a’u se tala o le mea-tausi ua tofi atu ia te ia."},{"verse":13,"text":"Aua e tatau ia te A’u, o le Alii, ona faia tagata taitoatasi ia tali, o se tausimea i luga o faamanuiaga faaletino, ua Ou faia ma saunia mo o’u tagata."},{"verse":14,"text":"O A’u, o le Alii, na fofolaina le lagi, ma fausia le lalolagi, o a’u galuega-taulima lava; o mea uma ua i ai i totonu e a a’u ia."},{"verse":15,"text":"Ma o lo’u faamoemoe o le faia lea o mea mo la’u au paia, aua o mea uma e a a’u ia."},{"verse":16,"text":"Peitai e tatau ona faia i la’u lava ala; ma faauta o le ala lenei ua folafola e A’u, o le Alii, e faia ai mea mo la’u au paia, e faaea ai e matitiva, ina ia faamaulaloina e mau’oa."},{"verse":17,"text":"Aua ua tumu le lalolagi, ma ua lava ma totoe mea o i ai; ioe, na Ou saunia mea uma, ma ua tuu atu i le fanauga a tagata ia avea ma pule ia te i latou lava."},{"verse":18,"text":"O lea, afai e ave e se tagata se mea mai le tele o mea ua Ou faia, ma lē tuu atu lana vaega, i e matitiva ma e ua lē tagolima, e tusa ma le tulafono o la’u talalelei, o le a siitia a’e e ia ona mata faatasi ma e amioleaga i seoli, ua maua i le mafatia."},{"verse":19,"text":"Ma o lenei, e moni Ou te fai atu ia te outou, e faatatau i meatotino a le faatulagaga—"},{"verse":20,"text":"Ia tuu atu i la’u auauna o Sini Rikitone ia tofi atu ia te ia le nofoaga o loo nofo ai nei o ia, ma le fasi fanua o le fale pa’u o manu, ma ana mea-tausi, mo lona tausiga a’o galue o ia i lo’u tovine, e pei lava ona Ou loto i ai, pe a Ou poloaiina o ia."},{"verse":21,"text":"Ma ia faia mea uma e tusa ai ma le fautuaga a le faatulagaga, ma le maliega aufaatasi po o le leo o le faatulagaga, o loo nonofo i le laueleele o Katelani."},{"verse":22,"text":"Ma o lenei mea-tausi ma le faamanuiaga, ua faaee atu e A’u, o le Alii, i luga o la’u auauna o Sini Rikitone mo se faamanuiaga i luga o ia, ma ana fanau e mulimuli mai ia te ia;"},{"verse":23,"text":"Ma o le a Ou faateleina faamanuiaga i luga o ia, e tusa ai ma le faamaualalo o ia i o’u luma."},{"verse":24,"text":"O lenei foi, ia tuu atu i la’u auauna o Matini Harisi ia tofi atu ia te ia, mo ana mea-tausi le fasi fanua lea na maua e la’u auauna o Ioane Ioanesone e fesuia’i ma lona tofi muamua, mo ia ma ana fanau e mulimuli mai ia te ia;"},{"verse":25,"text":"Ma e tusa ai ma lona faamaoni, o le a Ou faateleina faamanuiaga i luga o ia ma ana fanau e mulimuli mai ia te ia."},{"verse":26,"text":"Ma ia tuu atu i la’u auauna o Matini Harisi e tuuto atu ana tupe mo le folafolaina atu o a’u upu, e pei ona o le a faatonuina ai e la’u auauna o Iosefa Samita, Le Itiiti."},{"verse":27,"text":"O lenei foi, ia tuu atu i la’u auauna o Frederick G. Williams ia maua e ia le nofoaga o loo nofo ai nei o ia."},{"verse":28,"text":"Ma ia tuu atu i la’u auauna o Oliva Kaotui ia maua e ia le fasi fanua lea ua tuu ese e sosoo atu ma le fale, lea o le a avea ma ofisa lomitusi, o le fasi fanua numera muamua lea, ma le fasi fanua foi o loo nofo ai lona tamā."},{"verse":29,"text":"Ma ia tuu atu i a’u auauna o Frederick G. Williams ma Oliva Kaotui le ofisa lomitusi ma mea uma e faatatau i ai."},{"verse":30,"text":"Ma o nei mea o le a avea ma a laua mea-tausi ia tofia atu ia te i laua."},{"verse":31,"text":"Ma e tusa ai ma lo laua faamaoni, faauta o le a Ou faamanuia, ma faateleina faamanuiaga i o laua luga."},{"verse":32,"text":"Ma o le amataga lenei o le mea-tausi ua Ou tofia ia te i laua, mo i laua ma a laua fanau e mulimuli mai ia te i laua."},{"verse":33,"text":"Ma, e tusa ai ma lo laua faamaoni, o le a Ou faateleina faamanuiaga i o laua luga ma a laua fanau e mulimuli mai ia te i laua, o faamanuiaga faateleina lava."},{"verse":34,"text":"O lenei foi, ia tuu atu i la’u auauna o Ioane Ioanesone ia maua e ia le fale o loo nofo ai o ia, ma le tofi, o mea uma vagana ai le fanua ua faapolopolo mo le fausia o o’u fale, e faatatau i lena tofi, ma fasi fanua na ua ta’ua mo la’u auauna o Oliva Kaotui."},{"verse":35,"text":"Ma e tusa ai ma lona faamaoni, o le a Ou faateleina faamanuiaga i ona luga."},{"verse":36,"text":"Ma o lo’u loto ia faatau atu e ia fasi fanua ua faataatitia ese mo le faatuina i luga o le aai o la’u au paia, e pei o le a faailoa atu ai ia te ia e le leo o le Agaga, ma e tusa ai ma le fautuaga a le faatulagaga, ma le leo o le faatulagaga."},{"verse":37,"text":"Ma o le amataga lenei o le mea-tausi ua Ou tofia ia te ia, mo se faamanuiaga ia te ia ma ana fanau e mulimuli mai ia te ia."},{"verse":38,"text":"Ma e tusa ai ma lona faamaoni, o le a Ou faateleina faamanuiaga faateleina i ona luga."},{"verse":39,"text":"O lenei foi, ia tuu atu i la’u auauna o Newel K. Whitney fale ma le fasi fanua o loo nofo ai nei o ia, ma le fasi fanua ma le fale o loo tu ai le faleoloa, ma le fasi fanua foi lea o loo i le tulimanu i saute o le faleoloa, ma le fasi fanua foi lea o loo i ai le aseru."},{"verse":40,"text":"Ma o nei mea uma ua Ou tofia i la’u auauna o Newel K. Whitney mo ana mea-tausi, mo se faamanuiaga i ona luga ma ana fanau e mulimuli mai ia te ia, mo le manuia o le faleoloa o la’u faatulagaga lea ua Ou faatuina mo la’u siteki i le laueleele o Katelani."},{"verse":41,"text":"Ioe, e moni, o le mea-tausi lea, le faleoloa atoa lava lenei, ua Ou tofia ia te ia o la’u auauna o N. K. Whitney ma lona sui, ma ana fanau e mulimuli mai ia te ia."},{"verse":42,"text":"Ma e tusa ai ma lona faamaoni i le tausiga o a’u poloaiga, ua Ou tuu atu ia te ia, o le a Ou faateleina faamanuiaga i ona luga ma ana fanau e mulimuli mai ia te ia, o se faatelega lava o faamanuiaga."},{"verse":43,"text":"O lenei foi, ia tuu atu i la’u auauna o Iosefa Samita, Le Itiiti, e tofi ia te ia le fasi fanua lea ua faataatia ese mo le fausiaina o lo’u fale, lea e fasefulu rota le umi ma e sefululua le lautele, ma le tofi foi o loo nofo ai nei lona tamā;"},{"verse":44,"text":"Ma o le amataga lenei o le mea-tausi ua Ou tofia ia te ia, mo se faamanuiaga i ona luga, ma i luga o lona tamā."},{"verse":45,"text":"Aua faauta, ua Ou faapolopoloina se tofi mo lona tamā, mo lona tausiga; o lea o le a faitauina o ia i le aiga o la’u auauna o Iosefa Samita, Le Itiiti."},{"verse":46,"text":"Ma o le a Ou faateleina faamanuiaga i luga o le fale o la’u auauna o Iosefa Samita, Le Itiiti, e tusa ai ma lona faamaoni, o se faatelega lava o faamanuiaga."},{"verse":47,"text":"Ma lenei, Ou te tuu atu ia te outou se poloaiga e faatatau ia Siona, ia lē toe fusia outou o se faatulagaga autasi ma o outou uso i Siona, tau lava i le faapenei—"},{"verse":48,"text":"A uma ona faatulagaina o outou, ia ta’ua outou o le Faatulagaga Autasi o le Siteki o Siona, o le Aai o Katelani. Ma o o outou uso, a uma ona faatulagaina o i latou, ia ta’ua o le Faatulagaga Autasi o le Aai o Siona."},{"verse":49,"text":"Ma ia faatulaga i latou i o latou lava igoa, ma i lo latou lava igoa; ma ia latou faia a latou auaunaga i lo latou lava igoa, ma i o latou lava igoa;"},{"verse":50,"text":"Ma ia outou faia a outou auaunaga i lo outou lava igoa, ma i o outou lava igoa."},{"verse":51,"text":"Ma ua Ou poloaiina lenei mea ina ia faia mo lo outou faaolataga, ma mo lo latou faaolataga foi, ona o le tutuliesea o i latou ma le mea o le a oo mai."},{"verse":52,"text":"Ona ua motusia le feagaiga e ala i le solitulafono, e ala i le matape’ape’a ma upu faatagāfai—"},{"verse":53,"text":"O lea, ua soloia ai outou o se faatulagaga autasi ma o outou uso, ua lē toe fusia ai outou ia te i latou vagana ai e oo mai i le itula nei, tau lava i le faapenei, e pei ona Ou fai atu, i nonogatupe e pei ona o le a malilie i ai lenei faatulagaga i le fono, e pei ona mafai e tusa ma o outou tulaga ma le mea e faatonuina e le leo o le aufono."},{"verse":54,"text":"O lenei foi, Ou te tuu atu ia te outou se poloaiga e faatatau i la outou mea-tausi ua Ou tofi atu ia te outou."},{"verse":55,"text":"Faauta, o nei meatotino uma e a a’u ia, a lē o lea ua lē aoga lo outou faatuatua, ma ua fai outou o ni tagata faagutugutulua, ma ua motusia feagaiga na outou faia mai ia te a’u;"},{"verse":56,"text":"Ma afai o meatotino e a a’u ia, o lona uiga o outou o tausimea; a lē o lea e lē o outou o ni tausimea."},{"verse":57,"text":"Peitai, e moni Ou te fai atu ia te outou, ua Ou tofia outou e avea o ni tausimea i lo’u fale, o tausimea moni lava."},{"verse":58,"text":"Ma o le faamoemoe lenei na Ou poloaiina ai outou e faatulaga outou lava, e lomia lava a’u upu, le atoatoaga o a’u tusitusiga paia, o faaaliga ua Ou tuuina atu ia te outou, ma ia o le a Ou tuu atu, mulimuli ane, ia te outou, mai lea taimi i lea taimi—"},{"verse":59,"text":"Mo le faamoemoe o le atia’eina o la’u ekalesia ma le malo i luga o le lalolagi, ma saunia ai lo’u nuu mo le taimi o le a Ou mau faatasi ai ma i latou, ua lata lava ona oo mai."},{"verse":60,"text":"Ma ia outou saunia mo outou lava se nofoaga mo se faleteuoloa, ma faapaia mo lo’u igoa."},{"verse":61,"text":"Ma ia outou tofia se tasi i totonu o outou e tausia le faleteuoloa, ma ia faauuina o ia i lenei faamanuiaga."},{"verse":62,"text":"Ma ia i ai se faamaufaailoga i luga o le faleteuoloa, ma ia avatu mea paia uma i le faleteuoloa; ma ia leai se tagata i totonu o outou na te ta’ua o lana lava, po o se vaega o lena mea, ona o le a ou e outou uma ma le agaga autasi."},{"verse":63,"text":"Ma Ou te tuu atu le faleteuoloa ia te outou mai lenei lava itula; ma o lenei ia vaai, ia outou o atu ma faaaoga le mea-tausi ua Ou tofi atu ia te outou, vagana ai mea paia, mo le faamoemoe o le lomia o nei mea paia e pei ona Ou fai atu ai."},{"verse":64,"text":"Ma o tupe o mea paia ia teuina i le faleteuoloa, ma ia tuu i ai i ona luga se faamaufaailoga; ma ia lē faaaogaina pe aveesea i fafo o le faleteuoloa e soo se tasi, pe tatalaina le faamaufaailoga e tuu i ai i ona luga, tau lava i le leo o le faatulagaga, po o se poloaiga."},{"verse":65,"text":"Ma ia faapea ona outou tausi o tupe o mea paia i le faleteuoloa, mo faamoemoega sa ma paia."},{"verse":66,"text":"Ma ia ta’ua lenei mea o le faleteuoloa paia o le Alii; ma ia tuu i ai i ona luga se faamaufaailoga ina ia paia ma faapaiaina mo le Alii."},{"verse":67,"text":"O lenei foi, ia i ai se isi faleteuoloa e saunia, ma se teuoloa e tofi e tausia le faleteuoloa, ma ia tuu i ai i ona luga se faamaufaailoga;"},{"verse":68,"text":"Ma o tupe uma tou te maua ia outou mea-tausi, i le faaleleia atili o meatotino na Ou tofi atu ia te outou, i fale, po o i laueleele, po o i faatoaga manu, po o i mea uma lava vagana ai tusitusiga sa ma paia, ia ua Ou faapolopoloina mo a’u lava mo faamoemoega sa ma paia, ia lafo atu i le faleteuoloa i le vave lava tou te maua ai tupe, i le taiselau, po o le tailimasefulu, po o le tailuasefulu, po o le taisefulu, po o le tailima."},{"verse":69,"text":"Pe faapea, afai e maua e se tagata i totonu o outou se lima tālā, ia tuu atu ia te ia e lafo atu i le faleteuoloa; pe afai e maua e ia le sefulu, po o le luasefulu, po o le limasefulu, po o le selau, ia tuu atu ia te ia ia faapea ona faia;"},{"verse":70,"text":"Ma ia lē tuu atu i se tasi i totonu o outou e fai mai o lea mea o lana lava; ona o le a lē ta’ua lea mea o sana, po o se vaega o lea mea."},{"verse":71,"text":"Ma ia leai se vaega o lea mea e faaaogaina, pe aveeseina mai le faleteuoloa, tau lava i le leo ma le finagalo autasi o le faatulagaga."},{"verse":72,"text":"Ma o le leo lenei ma le finagalo autasi o le faatulagaga—soo se tagata o i totonu o outou e fai atu i le teuoloa: Ua ou manaomia le mea lenei e fesoasoani ia te a’u i la’u mea-tausi—"},{"verse":73,"text":"Afai o le mea ua manaomia o le lima tālā, po o le sefulu tālā, po o le luasefulu, po o le limasefulu, po o se selau, ia tuu atu e le teuoloa ia te ia le aofai ua manaomia e ia e fesoasoani ia te ia i lana mea-tausi—"},{"verse":74,"text":"Sei vagana ua maua o ia o se solitulafono, ma ua faaalia manino i luma o le aufono a le faatulagaga o ia o se tausimea lē faamaoni ma lē atamai."},{"verse":75,"text":"Ae a o i ai pea o ia i le faaaumeaga atoa, ma o faamaoni ma atamai i lana mea-tausi, o lana faailoga lea i le teuoloa ia lē taofia ai e le teuoloa."},{"verse":76,"text":"Ae i le tulaga o le solitulafono, e pulea le teuoloa e le aufono ma le leo o le faatulagaga."},{"verse":77,"text":"Ma afai e maua o le teuoloa o se tausimea lē faamaoni ma lē atamai, e pulea o ia e le aufono ma le leo o le faatulagaga, ma aveese o ia mai lona nofoaga, ma tofia se isi i lona tulaga."},{"verse":78,"text":"O lenei foi, e moni Ou te fai atu ia te outou, e faatatau ia outou aitalafu—faauta o lo’u loto e tatau ona outou totogi a outou aitalafu uma."},{"verse":79,"text":"Ma o lo’u loto e tatau ona outou faamaualaloina outou lava i o’u luma, ma maua lenei faamanuiaga i lo outou filiga ma le lotomaualalo ma le tatalo o le faatuatua."},{"verse":80,"text":"Ma e tusa ai ma lo outou filiga ma le lotomaualalo, ma faaaoga le tatalo o le faatuatua, faauta, o le a Ou faamaluluina loto o i latou o e ua outou aitalafu ai, seia Ou auina atu mea ia te outou mo lo outou laveaiina."},{"verse":81,"text":"O lea ia tusi vave atu i Niu Ioka ma tusi atu e tusa ma mea o le a faatonuina e lo’u Agaga; ma o le a Ou faamaluluina loto o i latou o e ua outou aitalafu ai, o le a aveesea ai mai o latou mafaufau le aumaia o puapuaga i o outou luga."},{"verse":82,"text":"Ma e tusa ai ma lo outou lotomaualalo ma faamaoni ma valaau mai i lo’u igoa, faauta, o le a Ou tuu atu ia te outou le manumalo."},{"verse":83,"text":"Ou te tuu atu ia te outou se folafolaga, o le a laveaiina outou i le taimi e tasi lenei i fafo mai lo outou nofo pologa."},{"verse":84,"text":"E tusa ai ma lo outou maua o se avanoa e nonō ai tupe taiselau, po o le taiafe, seia oo ina lava tupe tou te nonōina e laveai ai outou mai le nofo pologa, o lo outou avanoa lena."},{"verse":85,"text":"Ma folafola atu meatotino ua Ou tuuina atu i o outou lima, i le taimi lenei e tasi, i le tuu atu o o outou igoa i le finagalo autasi po o se isi ala, e pei ona foliga lelei ia te outou."},{"verse":86,"text":"Ou te tuu atu ia te outou lenei avanoa, i le taimi lenei e tasi; ma faauta, afai tou te aga atu e fai mea ua Ou tuuina atu i o outou luma, e tusa ma a’u poloaiga, o nei mea uma e a a’u ia, ma o outou o a’u tausimea, ma e lē tuua e le matai lona fale ia lepetia. E faapea lava. Amene."}]},{"chapter":105,"verses":[{"verse":1,"text":"E moni Ou te fai atu ia te outou o e ua faapotopoto faatasi outou lava ina ia outou iloa lo’u loto e faatatau i le laveaiina o lo’u nuu puapuagatia—"},{"verse":2,"text":"Faauta, Ou te fai atu ia te outou, a na leai soligatulafono a lo’u nuu, i le tautala atu lea e faatatau i le ekalesia ae lē o tagata taitoatasi, po ua laveaiina i latou i le taimi nei lava."},{"verse":3,"text":"Ae faauta, ua latou lē aoao e usiusitai i mea na Ou manaomia mai i o latou lima, ae ua tumu i ituaiga o leaga uma, ma ua lē faasoa atu a latou mea, e pei ona tatau ai i se au paia, i e matitiva ma e puapuagatia o i totonu o i latou;"},{"verse":4,"text":"Ma ua lē lotogatasi e tusa ma le tuufaatasiga ua manaomia e le tulafono o le malo selesitila;"},{"verse":5,"text":"Ma e lē mafai ona ati a’e Siona vagana ua ati a’e i mataupu autu o le tulafono o le malo selesitila, a lē o lea e lē mafai ona Ou talia o ia mo a’u."},{"verse":6,"text":"Ma e tatau ona aoaiina lo’u nuu, pe afai e tatau ai, e ala i mea latou te mafatia ai, seia latou aoao le usiusitai."},{"verse":7,"text":"Ou te lē o tautala atu e faatatau ia te i latou o e ua tofia e taitaia lo’u nuu, o e o toeaina muamua o la’u ekalesia, aua ua lē i ai i latou uma i lalo o lenei tausalaga;"},{"verse":8,"text":"Ae ua Ou tautala atu e faatatau i a’u aulotu salalau—ua i ai le toatele o e o le a fai mai: O fea lo latou Atua? Faauta, o le a laveai e ia i latou i taimi o faalavelave, a lē o lea matou te lē o atu i Siona, ma o le a taofi a matou tupe."},{"verse":9,"text":"O lea, ona o soligatulafono a lo’u nuu, ua tatau ai ia te a’u ona faatali a’u toeaina mo se vaitau itiiti mo le laveaiina o Siona—"},{"verse":10,"text":"Ina ia mafai ona saunia i latou lava, ma ia mafai ona aoaoina atili atoatoa lo’u nuu, ma maua le poto masani, ma iloa atili atoatoa e faatatau i lo latou tiute, ma mea ua Ou manaomia mai i o latou lima."},{"verse":11,"text":"Ma e lē mafai ona faataunuuina lenei mea seia faaeeina a’u toeaina i le mana mai luga."},{"verse":12,"text":"Aua faauta, ua Ou saunia se faaeega ma se faamanuiaga tele ia liligi ifo i luga o i latou, e tusa ai ma lo latou faamaoni ma faaauau pea i le lotomaualalo i o’u luma."},{"verse":13,"text":"O lea ua ao ai ia te a’u le tatau ona faatali o a’u toeaina mo se vaitau itiiti, mo le laveaiina o Siona."},{"verse":14,"text":"Aua faauta, Ou te lē manaomia mai i o latou lima le tau o taua a Siona; aua, e pei ona Ou fai atu i se poloaiga muamua atu, o le a faapea lava ona Ou faataunuuina—o le a Ou tauina a outou taua."},{"verse":15,"text":"Faauta, ua Ou auina atu lē faaumatia e faatamaia ma faatafuna o’u fili; ma e lē tele ni tausaga mai le taimi nei ae o le a lē tuua i latou e faaeleeleaina lo’u tofi, ma upuleagaina lo’u igoa i luga o laueleele ua Ou faapaiaina mo le faapotopotoina faatasi o la’u au paia."},{"verse":16,"text":"Faauta, ua Ou poloaiina la’u auauna o Iosefa Samita, Le Itiiti, e fai atu i le malosi o lo’u fale, o o’u tagata tau lava, o o’u alii talavou, ma faamatuā tagata, ia faapotopoto faatasi mo le laveaiina o lo’u nuu, ma lafo i lalo olo o o’u fili, ma faataapeape o latou leoleo;"},{"verse":17,"text":"Ae ua lē faalogo mai le malosi o lo’u fale i a’u upu."},{"verse":18,"text":"Ae afai e i ai i latou o e na faalogo i a’u upu, ua Ou saunia se faamanuiaga ma se faaeega mo i latou, pe afai latou te tumau pea i le faamaoni."},{"verse":19,"text":"Ua Ou faalogoina a latou tatalo, ma o le a Ou talia la latou taulaga; ma ua tatau ai ia te a’u ona aumai i latou seia oo mai iinei mo se tofotofoga o lo latou faatuatua."},{"verse":20,"text":"Ma o lenei, e moni Ou te fai atu ia te outou, Ou te tuu atu ia te outou se poloaiga, o le toatele o i latou ua o mai iinei, e mafai ona nonofo i itulagi faataamilo ai, ia tuu ia te i latou e nonofo;"},{"verse":21,"text":"Ma o i latou e lē mafai ona nonofo, o e o i ai aiga i sasa’e, ia tuu atu ia te i latou e nonofo mo se vaitau itiiti, pe a tofia ai i latou e la’u auauna o Iosefa;"},{"verse":22,"text":"Aua o le a Ou fautuaina o ia e faatatau i lenei mataupu, ma o mea uma po o le a lava o le a ia tofia ai i latou o le a faataunuuina lava."},{"verse":23,"text":"Ma ia tuu atu i o’u tagata uma o e o nonofo i nofoaga o faataamilo ai ina ia matua faamaoni, ma tatalo, ma faamaualalo i o’u luma, ma lē faaali atu mea ua Ou faaali atu ia te i latou, seia poto ia te a’u le tatau ona faaali atu o ia mea."},{"verse":24,"text":"Aua le tautala e uiga i faamasinoga, pe mitamita i le faatuatua po o galuega tetele, ae ia faapotopoto faatasi ma le faaeteete, i se itulagi e tasi pe a mafai, e tusa ai ma lagona o tagata;"},{"verse":25,"text":"Ma faauta, o le a Ou tuu atu ia te outou le mata fiafia ma le mata alofa mai ia te i latou, ina ia outou mapu i le filemu ma le saogalemu, a’o outou fai atu i tagata: Ia faia faamasinoga ma le faamasinotonu mo i matou e tusa ma le tulafono, ma toe totogi mai ia te i matou e tusa ma sese na faia ia te i matou."},{"verse":26,"text":"O lenei, faauta, Ou te fai atu ia te outou, o a’u uo, o le ala lenei o le a mafai ona outou maua ai le mata fiafia mai o tagata, seia oo ina matua toatele le ’autau a Isaraelu."},{"verse":27,"text":"Ma o le a Ou faamaluluina loto o tagata, e pei ona sa Ou faia i le loto o Farao, mai lea taimi i lea taimi, seia maua e la’u auauna o Iosefa Samita, Le Itiiti, ma a’u toeaina, o e ua Ou tofia, se taimi e faapotopoto ai le malosi o lo’u fale,"},{"verse":28,"text":"Ma auina atu ni alii atamamai, e faataunuu le mea na Ou poloaiina e faatatau i le faatauina mai o laueleele uma i le itumalo o Siakisone e mafai ona faatau mai, ma i itumalo sosoo ane faataamilo ai."},{"verse":29,"text":"Aua o lo’u loto e tatau ona faatau mai ia laueleele; ma a uma ona faatau mai i latou e tatau ona maua i latou e la’u au paia e tusa ma tulafono o le faapaiaga ua Ou tuu atu."},{"verse":30,"text":"Ma a uma ona faatau mai o ia laueleele, o le a Ou lē ta’usalaina autau a Isaraelu i le ave o o latou lava laueleele, ia sa latou faatau muamua mai ia latou lava tupe, ma le lafoaiina i lalo o olo o o’u fili atonu o i ai i luga o i latou, ma le faataapeapeina o o latou leoleo, ma le tauimasui i o’u fili mo a’u e oo atu i le tupulaga e tolu ma le fa o e inoino mai ia te a’u."},{"verse":31,"text":"Peitai ia muamua ona tuu atu i la’u autau ia matua faatoateleina, ma ia tuu atu ia faapaiaina i o’u luma, ina mafai ona lalelei e pei o le la, ma manino e pei o le masina, ma mafai ona mata’utia ona tagavai i atunuu uma;"},{"verse":32,"text":"Ina ia uunaia malo o le lalolagi lenei e tautino mai o le malo o Siona o le malo moni lava lea o lo tatou Atua ma lana Keriso; o lea, ia tatou tuu atu i tatou e pulea i ana tulafono."},{"verse":33,"text":"E moni Ou te fai atu ia te outou, ua tatau ia te a’u ona tatau ona maua e toeaina muamua o la’u ekalesia o latou faaeega mai lugā i lo’u fale, lea ua Ou poloaiina ia fausia i lo’u igoa i le laueleele o Katelani."},{"verse":34,"text":"Ma ia tuu atu poloaiga ia na Ou tuuina atu e faatatau ia Siona ma lana tulafono ia faia ma faataunuuina, pe a mavae lona laveaiina."},{"verse":35,"text":"Sa i ai se aso o le valaaulia, ae ua oo mai le taimi mo se aso o le filifilia; ma ia tuu atu ia te i latou o e ua agavaa ia filifilia."},{"verse":36,"text":"Ma o le a faaali atu i la’u auauna, i le leo o le Agaga, i latou ua filifilia; ma o le a faapaiaina i latou;"},{"verse":37,"text":"Ma e tusa ai ma lo latou mulimuli i fautuaga latou te maua, o le a latou maua le mana pe a mavae aso e tele, e faataunuu ai mea uma e faatatau ia Siona."},{"verse":38,"text":"Ma Ou te toe fai atu ia te outou, aioi atu mo le filemu, ia lē na’o tagata o e na latou fasia outou, ae o tagata uma foi;"},{"verse":39,"text":"Ma ia siitia a’e i luga se tagavai o le filemu, ma fai se folafolaga o le filemu i tulu’iga o le lalolagi;"},{"verse":40,"text":"Ma fai atu ni manatu faatu mo le filemu ia te i latou o e na fasia outou, e tusa ma le siufofoga o le Agaga ua i totonu o outou, ma o le a galulue faatasi mea uma mo lo outou lelei."},{"verse":41,"text":"O lea, ia faamaoni; ma faauta, ma tagai, ua Ou faatasi ma outou e oo lava i le iuga. E faapea lava. Amene."}]},{"chapter":106,"verses":[{"verse":1,"text":"O Lo’u loto ia tatau ona tofia ma faauuina la’u auauna o Warren A. Kaotui o se faitaulaga sili pulefaamalumalu i la’u ekalesia, i le laueleele o Freedom ma nofoaga o faataamilo ai;"},{"verse":2,"text":"Ma e tatau ona talai atu la’u talalelei tumau e faavavau, ma si’itia a’e lona leo ma lapatai atu i tagata, e lē gata i lona lava nuu, ae faapea i itumalo o tuaoi ai;"},{"verse":3,"text":"Ma ia tuu atu lona taimi atoa i lenei valaauga maualuga ma paia, ua Ou tuu atu nei ia te ia, e saili ma le filiga i le malo o le lagi ma lona amiotonu, ma o mea uma e tatau ai o le a faaopoopo i ai; ona e agavaa lē e galue i lona totogi."},{"verse":4,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ua latalata le afio mai o le Alii, ma o le a faate’ia ai le lalolagi e pei o se gaoi i le po—"},{"verse":5,"text":"O lea, ia fusi i o outou sulugatiti, ina ia mafai ona avea o outou ma fanau o le malamalama, ma o le a lē faate’ia outou e lena aso e pei o se gaoi."},{"verse":6,"text":"O lenei foi, e moni Ou te fai atu ia te outou, sa i ai le olioli i le lagi ina ua ifo mai la’u auauna o Warren i lo’u tootoo, ma vavae ese o ia lava mai amioletonu o tagata;"},{"verse":7,"text":"O lea, amuia lava la’u auauna o Warren, ona o le a Ou alofa mutimutivale ia te ia; ma, e ui i le fiafaalialia o lona loto, o le a Ou siitia a’e o ia i luga, pe a tusa ai ma lona faamaualalo o ia lava i o’u luma."},{"verse":8,"text":"Ma o le a Ou tuu atu ia te ia le alofa tunoa ma le faamautinoaga e mafai ona tulai ai o ia; ma afai e tumau pea o ia o se molimau faamaoni ma se malamalama i le ekalesia, ua Ou saunia se pale mo ia i maota o lo’u Tamā. E faapea lava. Amene."}]},{"chapter":107,"verses":[{"verse":1,"text":"Ua i ai i le ekalesia ni perisitua e lua, ua igoa, o le Mekisateko ma le Arona, e aofia ai le Perisitua faa-Levi."},{"verse":2,"text":"O le pogai ua ta’ua ai le muamua o le Perisitua Mekisateko ona o Mekisateko sa avea o se faitaulaga sili lona iloga."},{"verse":3,"text":"Ao lei oo mai i ona aso sa ta’ua o le Perisitua Paia, e tusa ma le Faatulagaga a le Alo o le Atua."},{"verse":4,"text":"Ae ona o le faaaloalo po o le ava i le suafa o Lē Silisili, e aloese ai mai le ta’ua soo o lona suafa, o lea na faaigoa ai e i latou, o le ekalesia, i aso anamua, lena perisitua ia Mekisateko, po o le Perisitua Mekisateko."},{"verse":5,"text":"O isi pule uma po o tofi i le ekalesia o ni faaopoopoga i lenei perisitua."},{"verse":6,"text":"Ae ua i ai ni vaega se lua po o ni ao tetele—o le tasi o le Perisitua Mekisateko, ma le isi o le Perisitua Arona po o le Perisitua faa-Levi."},{"verse":7,"text":"O le tofi o se toeaina e i lalo o le perisitua o Mekisateko."},{"verse":8,"text":"O le Perisitua Mekisateko e umia le aiā o le pulefaamalumalu, ma ua i ai le mana ma le pule i luga o tofi uma i le ekalesia i tupulaga uma o le lalolagi, e taitai ai i mea faaleagaga."},{"verse":9,"text":"O le Au Peresitene o le Perisitua Maualuga, e tusa ma le faatulagaga a Mekisateko, ua i ai le aiā e galue ai i tofi uma i le ekalesia."},{"verse":10,"text":"O faitaulaga sili e tusa ma le faatulagaga o le Perisitua Mekisateko ua i ai se aiā e galulue ai i o latou lava tulaga, i lalo o le taitaiga a le au peresitene, i le taulimaina o mea faaleagaga, ma i le tofi foi o se toeaina, ositaulaga (o le faatulagaga faa-Levi), aoao, tiakono, ma tagata o le ekalesia."},{"verse":11,"text":"O se toeaina ua i ai le aiā e galue ai i lona tulaga pe a lē o i ai le faitaulaga sili."},{"verse":12,"text":"O le faitaulaga sili ma le toeaina ia taitai i mea faaleagaga, e tusa ma feagaiga ma poloaiga o le ekalesia; ma ua i ai ia i laua se aiā e galulue ai i ia tofi uma o le ekalesia pe a lē o i ai ni isi pule maualuluga atu."},{"verse":13,"text":"O le perisitua lona lua ua ta’ua o le Perisitua o Arona, ona sa faaee lenei perisitua i luga o Arona ma lana fanau, i o latou tupulaga uma."},{"verse":14,"text":"O le pogai ua ta’ua ai lenei perisitua o le perisitua maualalo ona o lenei perisitua o se faaopoopoga i le perisitua maualuga, po o le Perisitua Mekisateko, ma ua i ai le mana e taulimaina ai sauniga faaletino."},{"verse":15,"text":"O le au epikopo o le au peresitene o lenei perisitua, ma e umia ki po o le pule o lea lava perisitua."},{"verse":16,"text":"E leai se alii ua i ai se aiā faaletulafono i lenei tofi, e umia ai ki o lenei perisitua, vagana ai o ia o se e tupuga moni mai ia Arona."},{"verse":17,"text":"Ae ona ua i ai i se faitaulaga sili o le Perisitua Mekisateko le pule e galue ai i tofi maualalo uma, e mafai ona galue o ia i le tofi o le epikopo pe a lē mafai ona maua se e tupuga moni mai ia Arona, pe a faapea e valaaulia ma vaetofia ma faauu o ia i lenei mana e ala i aao o le Au Peresitene o le Perisitua Mekisateko."},{"verse":18,"text":"O le mana ma le pule o le perisitua maualuga, po o le Perisitua Mekisateko, o le umia lea o ki o faamanuiaga uma faaleagaga o le ekalesia—"},{"verse":19,"text":"O le mauaina o le avanoa e maua ai mealilo o le malo o le lagi, e tatala mai ai le lagi ia te i latou, e mafuta ai ma le faapotopotoga aoao ma le ekalesia a le Ulumatua, ma olioli i le mafutaga ma le afio ai o le Atua le Tamā, ma Iesu le puluvaga o le feagaiga fou."},{"verse":20,"text":"O le mana ma le pule o le perisitua maualalo, po o le Perisitua Arona, o le umia lea o ki o le auaunaga a agelu, ma fai sauniga faaletino, le sauniga lea o le talalelei, o le papatisoga o le salamo mo le faamagaloina o agasala, e tusa ai ma feagaiga ma poloaiga."},{"verse":21,"text":"Ona e tatau ai, e i ai peresitene, po o mautofi pulefaamalumalu, e afua mai pe tofia mai i totonu o i latou o e ua faauuina i tofi eseese i nei perisitua e lua."},{"verse":22,"text":"Mai i le Perisitua Mekisateko, e toatolu Faitaulaga Sili Pulefaamalumalu, e filifili e le tino potopoto, e tofia ma faauu i lena tofi, ma e lagolagoina e le talitonuga, faatuatua, ma tatalo a le ekalesia, e faia ai se korama o le Au Peresitene o le Ekalesia."},{"verse":23,"text":"O fautua femalagaai e toasefululua ua valaaulia e avea ma Aposetolo e Toasefululua, po o molimau faapitoa o le suafa o Keriso i le lalolagi atoa—ua faapea ona ese ai mai i isi mautofi i le ekalesia i tiute o lo latou valaauga."},{"verse":24,"text":"Ma ua avea i latou o se korama, e tutusa i le pule ma le mana ma peresitene e toatolu na ta’ua muamua."},{"verse":25,"text":"O le Toafitugafulu ua valaaulia foi e talai atu le talalelei, ma avea ma molimau faapitoa i Nuuese ma i le lalolagi atoa—ua faapea ona ese ai mai isi mautofi i le ekalesia i tiute o lo latou valaauga."},{"verse":26,"text":"Ma ua avea i latou o se korama, e tutusa i le pule ma lena molimau faapitoa e Toasefululua po o Aposetolo na faatoa mavae atu nei lava ona ta’ua."},{"verse":27,"text":"Ma o faaiuga uma e faia e soo se tasi o nei korama e ao lava ina faia i le leo autasi o ia lava korama; o lona uiga, e ao i uso taitoatasi o korama taitasi ona ioe i faaiuga a le korama, ina ia faia a latou faaiuga i le mana po o le pule lava lea o le tasi ma le isi—"},{"verse":28,"text":"E mafai ona avea le vaega toatele ma korama pe a i ai ni tulaga e lē mafai ai ona faia ai—"},{"verse":29,"text":"Vagana ai o le tulaga lea, e lē aiā a latou faaiuga i faamanuiaga tutusa sa i ai i faaiuga a se korama a peresitene e toatolu anamua, o e na faauuina e tusa ma le faatulagaga a Mekisateko, ma o ni alii amiotonu ma paia."},{"verse":30,"text":"O faaiuga a ia korama, po o se tasi o ia korama, ia faia i le amiotonu atoa, i le paia, ma le maualalo o le loto, agamalu ma le tali-tiga, ma i le faatuatua, ma le amiomama, ma le poto, faautauta, onosai, amioatua, agalelei faaleuso ma le alofa mama;"},{"verse":31,"text":"Auā o le folafolaga e faapea, afai e faateleina ia mea ia te i latou o le a lē aunoa i latou ona fua tele mai i le malamalama o le Alii."},{"verse":32,"text":"Ma i le tulaga e faia ai se faaiuga a nei korama i le amioletonu, e mafai ona aumai lena faaiuga i luma o se faapotopotoga aoao a korama eseese, lea ua faia ma pule faaleagaga o le ekalesia; a lē o lea e leai se apili e mafai ona faia mai la latou faaiuga."},{"verse":33,"text":"O le Toasefululua o se Aufono Maualuga Femalagaai Pulefaamalumalu, e galulue i le suafa o le Alii, i lalo o le taitaiga a le Au Peresitene o le Ekalesia, e tusa ai ma le faatulagaga a le lagi; e ati a’e le ekalesia, ma pulea mataupu uma o lea lava ekalesia i atunuu uma, muamua i Nuuese ma lona lua i tagata Iutaia."},{"verse":34,"text":"O le Toafitugafulu e galulue i le suafa o le Alii, i lalo o le taitaiga a le Toasefululua po o le aufono maualuga femalagaai, i le atiina a’e o le ekalesia ma le pulea o mataupu uma o lea lava ekalesia i atunuu uma, muamua i Nuuese ona oo atu ai lea i tagata Iutaia—"},{"verse":35,"text":"Aua ua auina atu le Toasefululua, ua umia ki, e tatala le faitotoa e ala i le folafola atu o le talalelei a Iesu Keriso, ma e muamua i Nuuese ma ona oo atu ai lea i tagata Iutaia."},{"verse":36,"text":"O ’aufono maualuga tumau, i siteki o Siona, ua avea o se korama e tutusa i le pule i mataupu o le ekalesia, ma le korama a le au peresitene, pe ma le aufono maualuga femalagaai, i a latou faaiuga uma."},{"verse":37,"text":"O le aufono maualuga i Siona ua avea o se korama e tutusa i le pule i mataupu o le ekalesia, i a latou faaiuga uma, ma aufono a le Toasefululua i siteki o Siona."},{"verse":38,"text":"O le tiute o le aufono maualuga femalagaai o le valaau atu i le Toafitugafulu, pe a latou manaomia se fesoasoani, e faatutumu valaauga eseese mo le talaiga ma le taulimaina o le talalelei, nai lo soo se isi lava."},{"verse":39,"text":"O le tiute o le Toasefululua, i paranesi tetele uma o le ekalesia, le faauu o faifeau faaevagelia, e pei ona o le a faasino mai ia te i latou i faaaliga—"},{"verse":40,"text":"O le faatulagaga o lenei perisitua sa faamauina e tuulima faasolo mai i lalo mai le tamā i le atalii, ma ua tatau tonu i fanau moni o le fanau filifilia, o e na faia i ai folafolaga."},{"verse":41,"text":"O lenei faatulagaga sa faatuina i aso o Atamu, ma sa faasolo mai i lalo e ala mai i le gafa i le ala lenei:"},{"verse":42,"text":"Mai ia Atamu ia Setu, o lē na faauu e Atamu i le ono-sefulu-iva o tausaga, ma sa faamanuia e ia i le tolu tausaga i luma mai o lona (Atamu) maliu, ma maua le folafolaga a le Atua e ala mai i lona tamā, e faapea o le a avea ana fanau ma e filifilia o le Alii, ma o le a faasaoina i latou e oo i le iuga o le lalolagi;"},{"verse":43,"text":"Aua o ia (Setu) o se tagata sa atoatoa, ma o ona foliga o foliga tonu lava o lona tamā, sa tele ina foliga mai ai o ia e pei o lona tamā i mea uma, ma nao ona tausaga na mafai ona iloa ese ai o ia mai ia te ia."},{"verse":44,"text":"Sa faauu Enosa i le selau tolu-sefulu ma le fa tausaga ma le fa masina, e le lima o Atamu."},{"verse":45,"text":"Sa oo ifo le Atua ia Kainano i le vao i le fasefulu o ona tausaga; ma sa fetaia’i o ia ma Atamu i le malaga atu i le nofoaga o Shedolamak. O ia na valusefulu-fitu tausaga o le matua i le taimi na maua ai e ia lona faauuga."},{"verse":46,"text":"O Maalaelu na fa selau ivasefulu-ono tausaga ma le fitu aso le matua i le taimi na faauu ai o ia e le lima o Atamu, o lē na faamanuiaina foi o ia."},{"verse":47,"text":"O Iareto na lua selau tausaga le matua i le taimi na faauu ai o ia i lalo o le lima o Atamu, o lē na faamanuiaina foi o ia."},{"verse":48,"text":"O Enoka na luasefulu-lima tausaga le matua i le taimi na faauu ai o ia i lalo o le lima o Atamu; ma na onosefulu-lima o ia ae faamanuia o ia e Atamu."},{"verse":49,"text":"Ma sa vaai o ia i le Alii, ma sa savali o ia faatasi ma ia, ma sa i ai i luma o ona fofoga e lē aunoa; ma sa savali o ia faatasi ma le Atua i le tolu selau ma le onosefulu-lima tausaga, na maua ai e ia le fa selau tolusefulu tausaga le matua i le taimi na liua ai o ia."},{"verse":50,"text":"O Metusela na selau tausaga le matua i le taimi na faauu ai o ia i lalo o le lima o Atamu."},{"verse":51,"text":"O Lameko na tolusefulu-lua tausaga le matua i le taimi na faauu ai o ia i lalo o le lima o Setu."},{"verse":52,"text":"O Noa na sefulu tausaga le matua i le taimi na faauu ai o ia i lalo o le lima o Metusela."},{"verse":53,"text":"E tolu tausaga ae lei maliu Atamu, na valaaulia ai e ia Setu, Enosa, Kainano, Maalaelu, Iareto, Enoka, ma Metusela, o e sa faitaulaga sili uma, faatasi ma e na totoe o ana fanau o e na amiotonu, i le vanu o Atamu-onai-Amani, ma o iina na faaee atu ai e ia ia te i latou lana faamanuiaga mulimuli."},{"verse":54,"text":"Ma sa afio mai le Alii ia te i latou, ma sa latou tutulai i luga ma faamanuia atu ia Atamu, ma ta’ua o ia o Mekaeli, le aloalii, le agelu sili."},{"verse":55,"text":"Ma sa tuu mai e le Alii le faamafanafanaga ia Atamu, ma fetalai mai ia te ia: Ua Ou faatuina oe ia avea ma ulu; o le a tutupu mai ia te oe atunuu e tele, ma o le a avea oe o se aloalii i luga o i latou e faavavau."},{"verse":56,"text":"Ma sa tulai i luga Atamu i le lotolotoi o le faapotopotoga; ma, e ui ina sa faano’uno’u o ia i le matua, ua tumu o ia i le Agaga Paia, ma valoia soo se mea o le a oo mai i ana fanau e oo lava i le tupulaga mulimuli."},{"verse":57,"text":"O nei mea uma sa tusia i le tusi a Enoka, ma o le a molimauina i le taimi tatau ai."},{"verse":58,"text":"O le tiute foi o le Toasefululua, le faauuina ma faatulagaina tatau o isi mautofi uma o le ekalesia, e tusa ma le faaaliga ua fai mai:"},{"verse":59,"text":"I le ekalesia a Keriso o i le laueleele o Siona, e faaopoopo i tulafono a le ekalesia e faatatau i mataupu a le ekalesia—"},{"verse":60,"text":"E moni, Ou te fai atu ia te outou, ua fetalai mai ai le Alii o ’Au, e tatau ona i ai ni toeaina pulefaamalumalu e pulefaamalumalu i luga o i latou o e o le tofi o le toeaina;"},{"verse":61,"text":"Ma ni ositaulaga foi e pulefaamalumalu i luga o i latou o e o le tofi o le ositaulaga;"},{"verse":62,"text":"Ma ni aoao foi e pulefaamalumalu i luga o i latou o e o le tofi o le aoao, i le ala lava faapea, ma tiakono foi—"},{"verse":63,"text":"O le mea lea, mai le tiakono i le aoao, ma mai le aoao i le ositaulaga, ma mai ositaulaga i le toeaina, e pei ona tofia ai i latou taitoatasi, e tusa ma feagaiga ma poloaiga o le ekalesia."},{"verse":64,"text":"Ona oo mai ai lea o le Perisitua Maualuga, le silisili lea o perisitua uma."},{"verse":65,"text":"O le mea lea, e tatau ona i ai se tasi o le Perisitua Maualuga e tofia e pulefaamalumalu i luga o le perisitua, ma ia ta’ua o ia o le Peresitene o le Perisitua Maualuga o le Ekalesia;"},{"verse":66,"text":"Pe faapea foi, o le Faitaulaga Sili Pulefaamalumalu i luga o le Perisitua Maualuga o le Ekalesia."},{"verse":67,"text":"E mai lea lava e sau ai le faia o sauniga ma faamanuiaga i luga o le ekalesia, e ala i le faaee atu o lima."},{"verse":68,"text":"O le mea lea, o le tofi o le epikopo e lē tutusa ma lea; ona o le tofi o le epikopo e i ai lea i le faatautaiga o mea uma faaletino;"},{"verse":69,"text":"Ae ui i lea o se epikopo e ao ina filifilia mai le Perisitua Maualuga, vagana ai o ia o se e tupuga moni mai ia Arona;"},{"verse":70,"text":"Aua vagana ai o ia o se e tupuga moni mai ia Arona e lē mafai ona umia e ia ki o lena perisitua."},{"verse":71,"text":"Ae ui i lea, o se faitaulaga sili, o lona uiga, e tusa ma le faatulagaga a Mekisateko, e mafai ona vaetofia i le faatautaiga o mea faaletino, ma maua se malamalama e uiga i ia mea e ala i le Agaga o le upumoni;"},{"verse":72,"text":"Ma avea foi o se faamasino i Isaraelu, e fai tiute o le ekalesia, e nofo e faamasino i luga o e solitulafono e tusa ma molimau e pei ona o le a tuu mai i ona luma e tusa ma tulafono, e ala i le fesoasoani a ona fesoasoani, o e ua filifili e ia pe o le a filifili e ia mai totonu o toeaina o le ekalesia."},{"verse":73,"text":"O le tiute lea o se epikopo e lē o se e tupuga moni mai ia Arona, ae ua faauu i le Perisitua Maualuga e tusa ma le faatulagaga a Mekisateko."},{"verse":74,"text":"O le a faapea ona avea o ia o se faamasino, o se faamasino lautele lava i totonu o e nonofo i Siona, po o i se siteki o Siona, po o i soo se paranesi o le ekalesia e vaetofia i ai o ia i lenei galuega, sei oo ina faalauteleina tuaoi o Siona ma tatau ai ona i ai o ni isi epikopo po o faamasino i Siona po o isi mea."},{"verse":75,"text":"Ma e tusa ai ma le tofiaina o isi epikopo latou te galulue i lea lava tofi."},{"verse":76,"text":"Ae o se e tupuga moni mai ia Arona ua i ai le aiā faaletulafono i le tulaga peresitene o lenei perisitua, i ki o lea auaunaga, e galue ai i le tofi o le epikopo nao ia, e aunoa ma ni fesoasoani, vagana ai i se tulaga e faamasino ai se Peresitene o le Perisitua Maualuga, e tusa ma le faatulagaga a Mekisateko, e nofo ai o se faamasino i Isaraelu."},{"verse":77,"text":"Ma o le faaiuga a soo se tasi o ia aufono, e tusa ai ma le poloaiga ua fai mai:"},{"verse":78,"text":"O lenei foi, e moni, Ou te toe fai atu ia te outou, o tiute sili ona taua o le ekalesia, ma faamasinoga sili ona faigata o le ekalesia, e tusa ai ma le lē maua o se maliega i le faaiuga a le epikopo po o faamasino, ia tuu atu ma tauaveina i luga i le aufono a le ekalesia, i luma o le Au Peresitene o le Perisitua Maualuga."},{"verse":79,"text":"Ma o le Au Peresitene o le aufono o le Perisitua Maualuga o le a i ai le mana e valaaulia ai isi faitaulaga sili, e toasefululua lava, e fesoasoani o ni fesoasoani; ma o le a faapea ona i ai i le Au Peresitene o le Perisitua Maualuga ma ona fesoasoani, le mana e filifili ai i molimau e tusa ma tulafono o le ekalesia."},{"verse":80,"text":"Ma a uma lenei faaiuga o le a lē toe manatuaina lea mea i luma o le Alii; ona o le aufono aupito maualuga lenei o le ekalesia a le Atua, ma o se faaiuga faaiu lea i luga o feteena’iga i mataupu faaleagaga."},{"verse":81,"text":"E leai se tagata e auai i le ekalesia e tu’usaunoaina mai lenei aufono a le ekalesia."},{"verse":82,"text":"Ma e tusa ai ma le solitulafono o se Peresitene o le Perisitua Maualuga, ia manatua o ia i luma o le aufono lautele o le ekalesia, e fesoasoani i ai fautua e toasefululua o le Perisitua Maualuga;"},{"verse":83,"text":"Ma o la latou faaiuga i luga o lona ulu ia fai ma iuga o le feteena’iga e faatatau ia te ia."},{"verse":84,"text":"O le mea lea, e leai se tasi e faaesea mai le faamasinotonu ma tulafono a le Atua, ina ia mafai ona faia o mea uma i le faatulagaga tatau ma le mamalu i ona luma, e tusa ma le upumoni ma le amiotonu."},{"verse":85,"text":"O lenei foi, e moni Ou te fai atu ia te outou, o le tiute o se peresitene e i luga o le tofi o le tiakono, o le pulefaamalumalu i luga o tiakono e toasefululua, o le fono faatasi ma i latou, ma aoao atu ia te i latou o latou tiute, e faagaeetia ai e le tasi le isi, e pei ona tuuina mai e tusa ma feagaiga."},{"verse":86,"text":"O lenei foi o le tiute o le peresitene e i luga o le tofi o aoao o le pulefaamalumalu i luga o aoao e luasefulu-fa, ma fono faatasi ma i latou, ma aoao atu ia te i latou tiute o lo latou tofi, e pei ona tuuina mai i feagaiga."},{"verse":87,"text":"O lenei foi o le tiute o le peresitene e i luga o le Perisitua o Arona o le pulefaamalumalu i luga o ositaulaga e fasefulu-valu, ma fono faatasi ma i latou, e aoao atu ia te i latou tiute o lo latou tofi, e pei ona tuuina mai i feagaiga—"},{"verse":88,"text":"O lenei peresitene o se epikopo; aua o se tasi lea o tiute o lenei perisitua."},{"verse":89,"text":"O lenei foi, o le tiute o le peresitene e i luga o le tofi o toeaina o le pulefaamalumalu i luga o toeaina e ivasefulu-ono, ma fono faatasi ma i latou, ma aoao i latou e tusa ma feagaiga."},{"verse":90,"text":"O lenei au peresitene o se tasi e tulaga ese mai le au peresitene o le fitugafulu, ma ua faia mo i latou o e e lē malaga atu i le lalolagi atoa."},{"verse":91,"text":"O lenei foi, o le tiute o le Peresitene o le tofi o le Perisitua Maualuga o le pulefaamalumalu i le ekalesia atoa, ma ia avea e pei o Mose—"},{"verse":92,"text":"Faauta, o le poto lenei; ioe, ia avea o se tagatavāai, o se talifaaaliga, o se faaliliu-upu, ma se perofeta, ua i ai meaalofa uma a le Atua e faaee mai e ia i luga o le ulu o le ekalesia."},{"verse":93,"text":"Ma ua tusa ai ma le faaaliga vaaia ua faaali mai ai le faatulagaga o le Toafitugafulu, e tatau ona i ai ia te i latou ni peresitene e toafitu e pulefaamalumalu i luga o i latou, e filifili mai i le aofai o le toafitugafulu;"},{"verse":94,"text":"Ma o le lona fitu o peresitene o nei peresitene e toafitu e pulefaamalumalu i luga o le toaono;"},{"verse":95,"text":"Ma o ia peresitene e toafitu e filifilia isi fitugafulu e ese mai fitugafulu muamua ua aofia ai i latou, ma ia pulefaamalumalu i o latou luga;"},{"verse":96,"text":"Ma isi foi fitugafulu, seia faateleina faafitu le fitugafulu, pe afai e manaomia tatau ai i le galuega i le tovine."},{"verse":97,"text":"Ma o ia fitugafulu ia avea ma faifeau femalagaai, e muamua i Nuuese ma i tagata Iutaia foi."},{"verse":98,"text":"A’o isi mautofi o le ekalesia, o e e lē i ai i le Toasefululua, po o le Toafitugafulu, ua lē i lalo o le tiutetauave e malaga atu i atunuu uma, ae e malaga pe a faatagaina ai e o latou tulaga, e ui atonu ua latou umia ni tofi e tutusa le maualuluga ma le taua i le ekalesia."},{"verse":99,"text":"O le mea lea, ia tuu atu nei i tagata taitoatasi e aoao lona tiute, ma galue i le tofi ua tofia i ai o ia, i le filiga atoa."},{"verse":100,"text":"O ia o lē e paie o le a lē faitauina e agavaa e tulai, ma o ia o lē e lē aoaoina lona tiute ma faaali mai ua lē faamaonia o ia lava, o le a lē faitauina e agavaa e tulai. E faapea lava. Amene."}]},{"chapter":108,"verses":[{"verse":1,"text":"E moni ua faapea ona fetalai mai o le Alii ia te oe, la’u auauna Lyman: Ua faamagaloina oe i au agasala, ona ua e usiusitai i lou sau i luga nei i le taeao nei e maua atu fautuaga mai ia te ia o lē ua Ou tofia."},{"verse":2,"text":"O lea, ia tuu atu i lou agaga ia mapu e faatatau i lou tulaga faaleagaga, ma aua le toe tetee i lo’u leo."},{"verse":3,"text":"Ma ia tulai i luga ma faaeteete atili atu mai lenei taimi ma le agai i luma i le tausiga o au tautoga, ia ua uma ona e faia ma faia, ma o le a faamanuiaina oe i faamanuiaga e matua silisili lava."},{"verse":4,"text":"Faatalitali ma le onosai seia talo le faapotopotoga paia o a’u auauna, ona manatua lea o oe faatasi ma a’u toeaina muamua, ma maua le aiā e ala i le faauuga faatasi ma le vaega e totoe o a’u toeaina o e ua Ou filifilia."},{"verse":5,"text":"Faauta, o le folafolaga lenei a le Tamā ia te oe pe afai e te faamaoni pea."},{"verse":6,"text":"Ma o le a faataunuuina i ou luga i le aso lena o le a e maua ai le aiā e talai atu ai la’u talalelei i soo se mea o le a Ou auina atu i ai oe, mai le taimi nei mai lena taimi."},{"verse":7,"text":"O lea, ia faamalosi atu i ou uso i au talanoaga uma, i au tatalo uma, i au apoapoaiga uma, ma i au mea uma e fai."},{"verse":8,"text":"Ma faauta, ma tagai, ua Ou faatasi ma oe e faamanuia oe ma laveai oe e faavavau. Amene."}]},{"chapter":109,"verses":[{"verse":1,"text":"Faafetai i lou suafa, Le Alii e le Atua o Isaraelu, o lē e tausia feagaiga ma faailoa mai le alofa mutimutivale i au auauna o e savavali sa’o i ou luma, ma o latou loto atoa—"},{"verse":2,"text":"O oe o le na poloaiina au auauna e fausia se fale i lou suafa i lenei nofoaga [o Katelani]."},{"verse":3,"text":"Ma o lenei ua e silasila mai, Le Alii e, ua faia e au auauna e tusa ma lau poloaiga."},{"verse":4,"text":"Ma o lenei matou te ole atu ia te oe, Le Tamā Paia e, i le suafa o Iesu Keriso, le Alo o lou loto, o lē ua na o lona suafa lava e mafai ona tuuina mai ai le faaolataga i le fanauga a tagata, matou te ole atu ia te oe, Le Alii e, ia e talia lenei fale, o le galuega a o matou lima, o au auauna, lea na e poloaiina i matou e fausia."},{"verse":5,"text":"Aua ua e silafia na matou faia lenei galuega i le puapuaga tele; ma ua matou tuuina atu mai lo matou mativa ni a matou mea e fausia ai se fale i lou suafa, ina ia i ai se nofoaga e mafai e le Atalii o le Tagata ona faaali mai ai o ia lava i lona nuu."},{"verse":6,"text":"Ma e pei ona sa e fetalai mai i se faaaliga, na tuuina mai ia te i matou, na ta’ua ai i matou o au uo, ua fetalai mai—Ia talo la outou faapotopotoga paia, e pei ona Ou poloaiina ai outou;"},{"verse":7,"text":"Ma ona e lē i ai i tagata uma le faatuatua, ia outou saili ma le filiga ma aoao e le tasi le isi upu o le poto; ioe, ia outou saili mai tusi sili ona lelei upu o le poto, ia saili aoaoga e ala lava i le suesue ma le faatuatua foi;"},{"verse":8,"text":"Ia faatulaga tatau outou lava; ia saunia mea manaomia uma, ma faatuina se fale, o se fale lava o le tatalo, o se fale o le anapogi, o se fale o le faatuatua, o se fale o le aoaoga, o se fale o le mamalu, o se fale o le faatulagaga tatau, o se maota o le Atua;"},{"verse":9,"text":"Ina ia faia i le suafa o le Alii a outou ulufale mai, ina ia faia i le suafa o le Alii a outou ulufafo atu, ina ia faia a outou faafeiloaiga uma i le suafa o le Alii, ma lima ua siitia a’e i le Silisili Ese—"},{"verse":10,"text":"Ma o lenei, Le Tamā Paia e, matou te ole atu ia te oe ia fesoasoani mai ia te i matou, o lou nuu, i lou alofa tunoa, i le taloina o la matou faapotopotoga paia, ina ia faia mo lou mamalu ma mo lou taliaina i le paia;"},{"verse":11,"text":"Ma i se ala e mafai ai ona maua i matou ua agavaa, i lau silafaga, e maua ai se faataunuuga o folafolaga na e faia mai ia te i matou, o lou nuu, i faaaliga ua tuuina mai ia te i matou;"},{"verse":12,"text":"Ina ia to’a mai i luga o lou nuu lou mamalu, ma i luga o lou maota nei, lea ua matou tuu atu nei i lau afio, ina ia faapaiaina ma faamanuiaina ia paia, ma ia i ai pea le paia o lau afio i lenei fale;"},{"verse":13,"text":"Ma ina ia mafai e tagata uma e ulufale mai i le faitotoa o le maota o le Alii ona lagona lou mana, ma lagona uunaia ai e tautino atu ua e faapaiaina lenei fale, ma o lou maota lava, o se afioaga mo lou paia."},{"verse":14,"text":"Ma ia e tuuina mai, Le Tamā Paia e, ia aoaoina e i latou uma o e e tapuai atu i lenei fale upu o le poto mai tusi sili ona lelei, ma ina ia latou saili le aoaoina e ala lava i le suesue, ma ala foi i le faatuatua, e pei ona e fetalai mai;"},{"verse":15,"text":"Ma ina ia latou tutupu a’e ia te oe, ma maua le atoatoaga o le Agaga Paia, ma faatulagaina e tusa ma au tulafono, ma saunia e maua mea manaomia uma;"},{"verse":16,"text":"Ma ina ia avea lenei fale o se fale o le tatalo, o se fale o le anapogi, o se fale o le faatuatua, o se fale o le mamalu ma o le Atua, o lou maota lava;"},{"verse":17,"text":"Ina ia faia i le suafa o le Alii le ulufale mai uma o lou nuu, i totonu o lenei fale;"},{"verse":18,"text":"Ina ia faia i le suafa o le Alii a latou ulufafo atu uma mai lenei fale;"},{"verse":19,"text":"Ma ina ia faia i le suafa o le Alii a latou fefaafeiloaiga uma, ma lima paia, ua siitia a’e i le Silisili Ese;"},{"verse":20,"text":"Ma ia leai se mea ’eleelea e faatagaina e oo mai i totonu o lou maota e faaeleeleaina ai;"},{"verse":21,"text":"Ma a solitulafono lou nuu, soo se tasi o i latou, ia vave ona latou salamo ma toe foi mai ia te oe, ma talia i lau silafaga, ma toefuatai i faamanuiaga ua e faauuina e liligi ifo i luga o i latou o e migao i lau afio i lou maota."},{"verse":22,"text":"Ma e matou te ole atu ia te oe, Le Tamā Paia e, ina ia o atu au auauna mai lenei fale ua faaauupegaina i lou mana, ma ina ia i ai lou suafa i luga o i latou, ma i ai lou mamalu e siosiomia i latou, ma i ai i au agelu le tausiga i o latou luga;"},{"verse":23,"text":"Ma ina ia mafai ona latou tauaao atu mai lenei nofoaga tala silisili ma mamalu naua, i le upumoni, i tuluiga o le lalolagi, ina ia latou iloa o lau galuega lenei, ma ua e tuu mai lou aao, e faataunuu le mea na e fetalai mai e ala mai i fofoga o perofeta, e faatatau i aso e gata ai."},{"verse":24,"text":"Matou te ole atu i lau afio, Le Tamā Paia e, ia e faatumauina tagata o le a tapuai atu, ma umia i le mamalu se igoa ma se tulaga i lou maota nei, i tupulaga uma ma mo le faavavau;"},{"verse":25,"text":"Ina ia leai se auupega e gaosia e faasaga mai ia te i latou e manumalo; ina ia pa’ū i le lua o ia lava o lē e elia se lua mo i latou;"},{"verse":26,"text":"Ina ia leai se pulega o le amioleaga na te maua le mana e tulai a’e ai ma manumalo i luga o lou nuu o e o le a tuuina i ai lou suafa i lenei fale;"},{"verse":27,"text":"Ma afai e tulai mai soo se nuu e faasaga mai i lenei nuu, ia faamumūina lou toasa e faasaga ia te i latou;"},{"verse":28,"text":"Ma afai latou te taiaina lenei nuu ia e taiaina i latou; ia e tau mo lou nuu e pei ona e faia i le aso o le taua, ina ia laveaiina i latou mai lima o o latou fili uma."},{"verse":29,"text":"Matou te ole atu i lau afio, Le Tamā Paia e, ia faafememea’i, ma faameia, ma faamaasiasi ma faafenumia’i i latou uma o e ua faasalalauina tala pepelo i le lautele, i luga o le lalolagi, e faasaga i lau auauna po o au auauna, pe afai latou te lē salamo, pe a folafola atu le talalelei tumau e faavavau i o latou taliga;"},{"verse":30,"text":"Ma ina ia aumai a latou galuega uma ia ma faameanoaina, ma tafi ese e le uato’a, ma le faamasinoga o le a e auina atu i o latou luga i lou toasa, ina ia i ai se iuga i pepelo ma upu taufaaleaga e faasaga i lou nuu."},{"verse":31,"text":"Aua ua e silafia, Le Alii e, ua mamā lava au auauna i ou luma i le molimau atu o lou suafa, lea ua latou mafatia ai i nei mea."},{"verse":32,"text":"O lea matou te aioi atu ai i ou luma mo se lavea’iga atoa ma o’oo’o mai le mafatia o lenei avega;"},{"verse":33,"text":"Ia gauia ese, le Alii e; ia gauia ese mai ūa o au auauna, i lou mana, ina ia mafai ona matou tutulai atu i luga i le lotolotoi o lenei tupulaga ma fai lau galuega."},{"verse":34,"text":"E, Ieova e, ia e alofa mutimutivale mai i lenei nuu, ma ona e agasala tagata uma, ia faamagalo mai soligatulafono a lou nuu, ma ia tuu ia solitulafono ia soloiesea e faavavau."},{"verse":35,"text":"Ia tuu i le faauuga o au auauna ia faamauina i o latou luga i le mana mai lugā."},{"verse":36,"text":"Ia tuu atu ia faataunuuina i luga o i latou, e pei o i o latou luga i le aso o le Penetekoso; ia tuu le meaalofa o gagana ia liligi ifo i luga o lou nuu, o laulaufaiva ua vaeluaina lava e pei o le afi, ma lona faaliliuga."},{"verse":37,"text":"Ma ia tuu i lou maota ia faatumuina, i lou mamalu, e peiseai o se matagi malosi ua agi tele mai."},{"verse":38,"text":"Tuu i luga o au auauna le molimau o le feagaiga, ina a latou o atu ma folafola atu lau afioga ia mafai ona latou faamauina le tulafono, ma saunia loto o lau au paia mo faamasinoga uma ua toetoe ona e auina mai, i lou toasa, i luga o e o nonofo i le lalolagi, ona o a latou solitulafono, ina ia lē lotovaivai lou nuu i le aso o faalavelave."},{"verse":39,"text":"Ma o soo se aai e ulufale atu i ai au auauna, ma talia e tagata o lena aai la latou molimau, ia tuu lou filemu ma lau faaolataga ia i ai i luga o lena aai, ina ia mafai ona latou faapotopotoina mai lena aai e amiotonu, ina ia mafai ona latou o mai i Siona, po o i ona siteki, o nofoaga ua e tofia, ma viiga o le olioli tumau e faavavau;"},{"verse":40,"text":"Ma ia lē tuuina atu au faamasinoga ia pa’u’ū ifo i luga o lena aai, seia faataunuuina lenei mea."},{"verse":41,"text":"Ma o soo se aai e ulu atu i ai au auauna, ma lē talia e tagata o lena aai le molimau a au auauna, ma ua lapataiina i latou e au auauna ina ia latou faasaoina i latou lava mai lenei tupulaga faapi’opi’o, ia tuu ia oo mai i luga o lena aai e tusa ma lena na e fetalaia i fofoga o au perofeta."},{"verse":42,"text":"Ae ia e laveaiina, Ieova e, matou te aioi atu ai ia te oe, au auauna mai o latou lima, ma faamamā i latou mai lo latou toto."},{"verse":43,"text":"E, le Alii e, matou te lē fiafia i le faaumatiaina o o matou uso-a-tagata; ua pele lava o latou agaga i ou luma;"},{"verse":44,"text":"Ae e ao lava ona faataunuuina o lau afioga. Fesoasoani i au auauna e fai atu, faatasi ma le fesoasoani o lou alofa tunoa ia te i latou: Ia faia lou finagalo, le Alii e, ae lē o matou loto."},{"verse":45,"text":"Ua matou iloa ua e fetalai mai e ala i fofoga o au auauna i mea mata’utia e faatatau i e amioleaga, i aso e gata ai—o le a e faamatuu mai au faamasinoga, e aunoa ma se fuaina;"},{"verse":46,"text":"O lea, le Alii e, laveai lou nuu mai le mala o e amioleaga; fai ia mafai e au auauna ona faamau le tulafono, ma fusimau le molimau, ina ia mafai ona saunia i latou mo le aso o le susunuina."},{"verse":47,"text":"Matou te ole atu ia te oe, Le Tamā Paia e, ia e manatua i latou o e ua tulia e tagata o le itumalo o Siakisone, Misuri, mai laueleele o o latou tofi, ma ia gausia ese, le Alii e, lenei amo o le puapuaga ua tuu i o latou luga."},{"verse":48,"text":"Ua e silafia, le Alii e, ua matua sauaina ma faapuapuagatiaina tele i latou e tagata amioleaga; ma ua masuasua atu o matou loto i le faanoanoa ona o a latou avega mamafa."},{"verse":49,"text":"Le Alii e, o le a ea le umi e te tuu ai lenei nuu e tauave lenei puapuaga, ma tagi a o latou tagata mamā e o a’e i luga i ou fofoga faalogo, ma alu a’e i luga lo latou toto o se molimau i ou luma, ma ’e lē faia se faaaliga o lau molimau mo i latou?"},{"verse":50,"text":"Ia e alofa mutimutivale, le Alii e, i luga o le vaega o tagata amioleaga, o e ua tulia ou tagata, ina ia latou taofi le faomea, ina ia latou salamo ia latou agasala pe afai e mafai ona maua le salamo;"},{"verse":51,"text":"Ae afai latou te lē fia salamo, ia faaalia lou aao, le Alii e, ma laveai le mea lena na e tofia o se Siona mo lou nuu."},{"verse":52,"text":"Ma afai e lē mafai i se isi ala, ina ia lē mafai ona iuvale o le faamoemoe o lou nuu i ou luma, ia faamumūina lou toatamai, ma pa’ū ifo lou toasa i luga o i latou, ina ia faaumatia ese i latou, o a’a atoa ma lala, mai i lalo o le lagi;"},{"verse":53,"text":"Ae e tusa ai ma lo latou salamo, ua e agalelei ma alofa mutimutivale, ma liliu ese lou toasa pe a e silasila mai i luga o fofoga o lē ua e Faauuina."},{"verse":54,"text":"Ia e alofa mutimutivale, le Alii e, i luga o atunuu uma o le lalolagi; ia e alofa mutimutivale i luga o pule o lo matou atunuu; ia faatumauina e faavavau mataupu autu na, ua ta’ua, o le Tulafono Faavae a lo matou atunuu, ia puipuia lava i le mamalu ma le tamalii e o matou tamā."},{"verse":55,"text":"Ia e manatua tupu, aloalii, tamalii, ma tagata silisili o le lalolagi, ma tagata uma, ma ekalesia, tagata matitiva uma, ma e ua lē tagolima, ma e puapuagatia o le lalolagi;"},{"verse":56,"text":"Ina ia faamaluluina o latou loto pe a o atu au auauna mai lou maota, Ieova e, e molimau atu lou suafa; ina ia aveesea o latou manatu faapito e le upumoni, ma ina ia mafai e lou nuu ona maua le fiafia mai le vaaiga a tagata uma;"},{"verse":57,"text":"Ina ia iloa ai e tuluiga uma o le lalolagi, o i matou, o au auauna, na matou faalogo i lou siufofoga, ma ua e auina atu i matou;"},{"verse":58,"text":"Ina ia mafai ai e au auauna, o atalii o Iakopo, ona faapotopoto e amiotonu mai totonu o i latou uma ia, e faatuina se aai paia i lou suafa, e pei ona e poloaiina ai i latou."},{"verse":59,"text":"Matou te ole atu ia te oe ia tofia ia Siona ni isi siteki e ese mai le tasi lenei ua e tofia, ina ia mafai ona taavale atu pea i luma i le mana ma le mamalu tele le faapotopotoina o lou nuu, ina ia mafai ona faapuupuu o lau galuega i le amiotonu."},{"verse":60,"text":"O lenei o nei upu, le Alii e, ua matou tautala atu ai i ou luma, e faatatau i faaaliga ma poloaiga na e tuuina mai ia te i matou, o e ua faailogaina faatasi ma Nuuese."},{"verse":61,"text":"Ae ua e silafia ua i ai ia te oe se alofa tele mo le fanau a Iakopo, o e ua faataapeapeina i luga o mauga mo se taimi umi lava, i se aso auaoa ma le pouliuli."},{"verse":62,"text":"O lea matou te ole atu ai ia te oe ia e alofa mutimutivale i luga o le fanau a Iakopo, ina ia mafai, mai le itula lenei, ona amata ona laveaiina o Ierusalema;"},{"verse":63,"text":"Ma ia mafai ona amata ona gausia o le amo o le pologa mai le fale o Tavita;"},{"verse":64,"text":"Ma ia mafai ona amata e le fanau a Iuta ona toe foi atu i laueleele na e tuuina mai ia Aperaamo, lo latou tamā."},{"verse":65,"text":"Ma faia ia faaliliuina vaega o totoe o Iakopo, o e na fetuuina ma taia ona o lo latou solitulafono, mai lo latou tulaga lē taupulea ma lē aoaoina, i le atoatoaga o le talalelei tumau e faavavau;"},{"verse":66,"text":"Ina ia mafai ona latou tuu i lalo a latou auupega o le faamasaatoto, ma tuu a latou fouvalega."},{"verse":67,"text":"Ma talosia ia o mai vaega uma o totoe o Isaraelu ua faataapeapeina, o e na tulia i tuluiga o le lalolagi, i se malamalama o le upumoni, ma talitonu i le Mesia, ma laveai mai le sauā, ma olioli i ou luma."},{"verse":68,"text":"E, le Alii e, ia e manatua lau auauna, o Iosefa Samita, Le Itiiti, ma ona puapuaga ma sauaga uma—le ala na osifeagaiga ai o ia ma Ieova, ma tauto atu ai ia te oe, le Atua Malosi Aoao e o Iakopo—ma poloaiga ua e tuuina mai ia te ia, ma ua taumafai lava o ia ma le faamaoni e fai lou finagalo."},{"verse":69,"text":"Ia e alofa mutimutivale mai, le Alii e, i lana avā ma lana fanau, ina ia mafai ona faaeaina i latou i ou luma, ma faasaoina e lou aao tausi."},{"verse":70,"text":"Ia e alofa mutimutivale i o latou aiga valalata uma, ina ia fatia o latou manatu faapito ma tafi ese e faapei ona faia i se lolo; ina ia mafai ona faaliliu mai ma togiola i latou faatasi ma Isaraelu, ma iloa o oe lava o le Atua."},{"verse":71,"text":"Ia e manatua, le Alii e, peresitene, peresitene uma lava o lau ekalesia, ina ia mafai e lou aao taumatau ona faaeaina i latou, faatasi ma o latou aiga uma, ma o latou aiga valalata, ina ia mafai ona faatumauina ma manatua pea o latou igoa e faavavau mai lea tupulaga i lea tupulaga."},{"verse":72,"text":"Ia e manatua lau ekalesia atoa, le Alii e, ma o latou aiga uma, ma o latou aiga valalata uma, faatasi ma o latou tagata mamai ma puapuagatia uma, faatasi ma e matitiva ma agamalu uma o le lalolagi; ina ia mafai ona avea o le malo, lea ua e faatuina e aunoa ma lima, o se mauga tele ma faatumu ai le lalolagi atoa;"},{"verse":73,"text":"Ina ia mafai ona sau o lau ekalesia nai le vao o le pouliuli, ma susulu malamalama atu e pei o le masina, manino e pei o le la, ma mata’utia e pei o se autau ma tagavai;"},{"verse":74,"text":"Ma teuteuina e pei o se faatoanofotane mo lena aso pe a e afe le veli o le lagi, ma faia mauga ia soloi i lalo i ou luma, ma vanu ia siitia, ma faalauleleia mea gaoā; ina ia faatumuina le lalolagi i lou mamalu;"},{"verse":75,"text":"Ina a oo ina ilia le pu mo e ua oti, ia segia a’e ai i matou i luga i le ao e fetaia’i ma oe, ina ia matou faatasi e faavavau ma le Alii;"},{"verse":76,"text":"Ina ia mamā o matou ofu, ina ia mafai ona faaofuina o i matou i ofu talaloa o le amiotonu, ma laupama i o matou lima, ma pale o le mamalu i luga o o matou ulu, ma selesele le olioli e faavavau mo o matou puapuaga uma."},{"verse":77,"text":"E, le Alii e le Atua Malosi Aoao, faafofoga mai ia te i matou ia matou nei olega, ma tali mai ia i matou mai le lagi, lou afioaga paia, i le mea o loo e afio ai i lou nofoalii, ma le mamalu, viiga, mana, malualii, malosi, puleaga, upumoni, faimeatonu, faamasinotonu, alofa mutimutivale, ma se āoāo lē gata o le atoatoaga, mai le faavavaue tumau i le faavavau e tumau."},{"verse":78,"text":"E, faafofoga mai ia, E, faafofoga mai ia, E, faafofoga mai ia ia te i matou, le Alii e! Ma tali mai i nei olega, ma talia le faapaiaga o lenei fale mo oe, o le galuega a o matou lima, lea na matou fausia i lou suafa;"},{"verse":79,"text":"Ma lenei foi ekalesia, ia tuu i ai i luga lou suafa. Ma fesoasoani mai ia te i matou i le mana o lou Agaga, ina ia matou tuufaatasi o matou leo ma i latou o serafi pupula ma susulu na o loo siomia ai lou nofoalii, ma alaga o viiga, o pepese atu Osana i le Atua ma le Tamai Mamoe!"},{"verse":80,"text":"Ma ia tuu mai ia i latou nei, o ou tagata faauuina, ia faaoofuina i le olataga, ma alalaga leotetele lau au paia i le olioli. Amene, ma Amene."}]},{"chapter":110,"verses":[{"verse":1,"text":"Sa aveesea le veli mai i o ma’ua mafaufau, ma sa tatalaina mata o o ma’ua malamalama."},{"verse":2,"text":"Sa ma vaai i le Alii o tulai mai i luga o le si’ofatafata o le pulelaa, i o maua luma; ma o lalo ifo o ona aao sa teuteuina i le auro mao’i, i le lanu e pei e mūmū sesega."},{"verse":3,"text":"O ona fofoga sa pei o se afi mumū; o lauao o lona ao sa papa’e e pei o le kiona mamā; o ona fofoga sa susulu e sili atu i lo le pupula o le la; ma o lona siufofoga sa pei o le leo o le tafe-taalili o vai tetele, o le siufofoga lava o Ieova, ua fetalai mai:"},{"verse":4,"text":"O A’u o lē muamua ma lē mulimuli; o A’u o lē o ola, o A’u o lē na fasia; o A’u o lo oulua fautua i le Tamā."},{"verse":5,"text":"Faauta, ua faamagaloina a oulua agasala mai ia te oulua; ua oulua mamā i o’u luma; o lea, ia siitia a’e i luga o oulua ulu ma olioli."},{"verse":6,"text":"Ia olioli loto o o oulua uso, ma ia olioli loto o lo’u nuu uma, o e na latou fausia lenei fale i lo’u igoa, ma lo latou malosi."},{"verse":7,"text":"Aua faauta, ua Ou talia lenei fale, ma o le a i ai iinei lo’u igoa; ma o le a Ou faaali atu a’u lava i lo’u nuu i lenei fale i le alofa mutimutivale."},{"verse":8,"text":"Ioe, o le a Ou oo atu i a’u auauna, ma tautala atu ia te i latou i lo’u lava leo, pe afai e tausi lo’u nuu i a’u poloaiga, ma ia lē faaeleeleaina lenei fale paia."},{"verse":9,"text":"Ioe o le a matua olioli tele lava loto o afe ma sefulu o afe ona o faamanuiaga o le a liligi atu, ma le faaeega ua faaeeina ai a’u auauna i lenei fale."},{"verse":10,"text":"Ma o le a salalau atu le ta’uta’ua o lenei fale i atunuu ese; ma o le amataga lenei o le faamanuiaga o le a liligi mai i luga o ulu o lo’u nuu. E faapea lava. Amene."},{"verse":11,"text":"Ina ua tapunia lenei faaaliga vaaia, sa toe tatala mai le lagi ia i ma’ua; ma sa oo mai Mose i o ma’ua luma, ma tuu mai ia i ma’ua ki o le faapotopotoina o Isaraelu mai vaega e fa o le lalolagi, ma le taitaiga mai o ituaiga e sefulu mai le laueleele i matu."},{"verse":12,"text":"Ina ua mavae lea, sa oo mai Elaia, ma tuu mai le tisipenisione o le talalelei a Aperaamo, fai mai o le a faamanuiaina i ma’ua ma a ma’ua fanau, tupulaga uma mulimuli mai pe a mavae atu i ma’ua."},{"verse":13,"text":"Ina ua tapunia lenei faaaliga vaaia, sa oo mai i o ma’ua luga se isi faaaliga vaaia tele ma le mamalu; ona sa tulai mai i o ma’ua luma Elia le perofeta, o lē na aveina i le lagi e aunoa ma le tofo i le oti, ma fetalai mai:"},{"verse":14,"text":"Faauta, ua oo atoa mai le taimi, lea na fetalaia e le fofoga o Malaki—na molimau mai e tatau ona auina mai o ia [Elia], ae lei oo mai le aso tele ma le mata’utia o le Alii—"},{"verse":15,"text":"E liliu loto o tamā i fanau, ma fanau i tamā, ne’i taia le lalolagi atoa i se fetuu—"},{"verse":16,"text":"O lea, ua tuu atu i o oulua lima ki o lenei tisipenisione; ma o lenei mea o le a mafai ona outou iloa ai ua lata mai lava le aso tele ma le mata’utia o le Alii, ua i faitotoa lava."}]},{"chapter":111,"verses":[{"verse":1,"text":"O A’U, o le Alii lo outou Atua, ou te lē o lē fiafia i lo outou o mai i lenei malaga, e ui i o outou uiga le manuia."},{"verse":2,"text":"Ua ia te A’u ’oa e tele i lenei aai mo outou, mo le manuia o Siona, ma le toatele o tagata o i lenei aai, o e o le a Ou faapotopoto mai i le taimi e tatau ai mo le manuia o Siona, e ala ia te outou."},{"verse":3,"text":"O lea, e tatau ona outou faia se faamasaniga ma tagata i lenei aai, e pei ona o le a taitaiina ai outou, ma e pei ona o le a tuuina atu ia te outou."},{"verse":4,"text":"Ma o le a oo mai, o le a Ou tuu atu i o outou lima lenei aai i le taimi e tatau ai, o le a outou maua ai le mana i ona luga, e oo ina latou lē iloa ai o outou vaega lilo; ma o ona ’oa e faatatau i auro ma ario o le a ā outou."},{"verse":5,"text":"Aua tou te popole e uiga ia outou aitalafu, aua o le a Ou tuu atu ia te outou le mana e totogi ai."},{"verse":6,"text":"Aua tou te popole e uiga ia Siona, aua o le a Ou faia ia te ia ma le alofa mutimutivale."},{"verse":7,"text":"Nonofo i le nofoaga lenei, ma nofoaga o faataamilo ai;"},{"verse":8,"text":"Ma o le nofoaga ua i ai lo’u loto e tatau ona outou nonofo ai, mo le tele, o le a faasino atu ia te outou i le filemu ma le mana o lo’u Agaga, o le a tafe atu ia te outou."},{"verse":9,"text":"E mafai ona outou maua lenei nofoaga i le mautotogi. Ma ole ma le filiga e uiga i e sa nonofo ai i aso anamua ma faavaeina lenei aai;"},{"verse":10,"text":"Aua ua i ai ’oa e tele atu nai le tasi mo outou i lenei aai."},{"verse":11,"text":"O lea, ia outou atamamai e pei o gata ma ia aunoa ma le agasala; ma o le a Ou faatulagaina mea uma mo lo outou lelei, i le vave e mafai ona outou talia ai i latou. Amene."}]},{"chapter":112,"verses":[{"verse":1,"text":"E moni ua faapea ona fetalai mai o le Alii ia te oe la’u auauna Thomas: Ua Ou faalogoina au tatalo; ma ua matauina au galuega alofa mama o se faamanatuga i o’u luma, e fai mo i latou na, o ou uso, o e ua filifilia e molimau atu lo’u igoa ma auina atu i fafo i atunuu uma, ituaiga, gagana, ma nuu, ma ua faauuina e ala i agavaa o a’u auauna."},{"verse":2,"text":"E moni Ou te fai atu ia te oe, sa i ai ni mea itiiti i lou loto ma faapea foi ia te oe sa lē fiafia i ai A’u, o le Alii."},{"verse":3,"text":"Ae ui i lea, talu ai ona ua e faamaualaloina oe lava o le a faaeaina oe; o lea, ua faamagaloina au agasala uma mai ia te oe."},{"verse":4,"text":"Ia fiafia lou loto i luma o o’u mata; ma ia e molimau atu lo’u igoa, e lē na’o i Nuuese, ae i tagata Iutaia foi; ma ia e auina atu la’u upu i tuluiga o le lalolagi."},{"verse":5,"text":"O lea, ia e finafinau, i lea taeao i lea taeao; ma ia tuu atu lou leo lapatai e alu atu i lea aso ma lea aso; ma a oo mai le po, aua ne’i tuua o e nonofo i le lalolagi ia momoe, ona o lou tautala atu."},{"verse":6,"text":"Ia faailoa atu le mea e te nofo ai i Siona, ma aua ne’i aveesea lou fale; ona ua i ai ia te A’u, o le Alii, se galuega tele mo oe e te faia, i le faasalalauina atu o lo’u igoa i totonu o le fanauga a tagata."},{"verse":7,"text":"O lea, ia fusi i ou sulugatiti mo le galuega. Ia faasee foi ou vae, ona ua filiilia oe, ma ua taatia lou ala i totonu o mauga, ma i totonu o atunuu e tele."},{"verse":8,"text":"Ma o lau upu o le a faamaualalo ai le toatele o tagata maualuluga, ma o lau upu o le a faaea ai le toatele o e maualalalo."},{"verse":9,"text":"O le a avea lou leo o se aoaiga i lē ua solitulafono; ma o lau aoaiga ia tuu ai le laulaufaiva o le taufaaleaga ia taofi lona faapi’opi’o."},{"verse":10,"text":"Ia e lotomaualalo; ma o le a taitai ai oe e le Alii lou Atua i le lima, ma tuu mai ia te oe tali i au tatalo."},{"verse":11,"text":"Ua Ou iloa lou loto, ma ua Ou faalogo i au tatalo e faatatau i ou uso. Aua le faapito’au ia te i latou i le alofa sili atu i lo le toatele o isi, ae ia tuu atu lou alofa mo i latou e faapei foi mo oe lava; ma ia faateleina lou alofa i tagata uma, ma ia i latou uma o e alolofa i lo’u igoa."},{"verse":12,"text":"Ma tatalo mo ou uso o le Toasefululua. Apoapoai malosi atu ia te i latou ona o lo’u igoa, ma ia apoapoaiina i latou ia latou agasala uma, ma ia e faamaoni i lo’u igoa i o’u luma."},{"verse":13,"text":"Ma a mavae atu o latou faaosoosoga, ma puapuaga e tele, faauta, o A’u, o le Alii, o le a Ou aapa atu ia i latou, ma afai latou te lē faamaaa o latou loto, ma lē faamalō o latou ūa e faasaga mai ia te a’u, o le a liua mai i latou, ma o le a Ou faamaloloina i latou."},{"verse":14,"text":"O lenei, Ou te fai atu ia te oe, ma o le mea Ou te fai atu ai ia te oe, Ou te fai atu ai i le Toasefululua uma: Tutulai ia ma fusi i o outou sulugatiti, ma ave i luga a outou satauro, mulimuli mai ia te a’u, ma fafaga a’u mamoe."},{"verse":15,"text":"Aua le faaeaeaina outou lava; aua le fouvale i la’u auauna o Iosefa; aua e moni Ou te fai atu ia te outou, ua Ou faatasi ma ia, ma o le a i luga o ia lo’u lima; ma o ki ua Ou tuu atu ia te ia, ma ia te outou foi, o le a lē aveesea mai ia te ia seia Ou alu atu."},{"verse":16,"text":"E moni Ou te fai atu ia te oe, la’u auauna e Thomas, o oe o le tagata ua Ou filifilia e umia ki o lo’u malo, e faatatau i le Toasefululua, i le lautele i totonu o atunuu uma—"},{"verse":17,"text":"Ina ia mafai ona avea oe ma a’u auauna e tatala le faitotoa o le malo i nofoaga uma e lē mafai ona o atu i ai la’u auauna o Iosefa, ma la’u auauna o Sini, ma la’u auauna o Ailama;"},{"verse":18,"text":"Aua o luga o i latou ua Ou faataatia ai le avega a aulotu uma mo se vaitau itiiti."},{"verse":19,"text":"O le mea lea, soo se mea latou te auina atu i ai oe, ia e alu, ma o le a Ou faatasi ma oe; ma o soo se mea e te folafola atu ai lo’u igoa o le a tatala mai ai se faitotoa aoga ia te oe, ina ia latou maua la’u upu."},{"verse":20,"text":"Soo se tasi e talia la’u upu ua talia a’u, ma o soo se tasi e talia a’u, ua talia e ia i latou na, o le Au Peresitene Sili, o e ua Ou auina atu, o e ua Ou faia o fautua ia te outou, mo lo’u igoa."},{"verse":21,"text":"O lenei foi, Ou te fai atu ia te outou, soo se tasi tou te auina atu i lo’u igoa, e ala i le leo o outou uso, o le Toasefululua, ua fautuaina mai ma ua faamaonia e outou i le ala e tatau ai, o le a i ai le mana e tatala ai le faitotoa o lo’u malo i soo se atunuu i soo se mea tou te auina atu i ai i latou—"},{"verse":22,"text":"E tusa ai ma lo latou faamaualalo o i latou lava i o’u luma, ma tumau i la’u upu, ma faalogo i le leo o lo’u Agaga."},{"verse":23,"text":"E moni, e moni, Ou te fai atu ia te outou, ua ufitia le lalolagi i le pouliuli, ma le pouliuli mafiafia tele i mafaufau o tagata, ma ua leaga ai tagata uma i o’u luma."},{"verse":24,"text":"Faauta, ua vave ona oo mai o le tauimasui i luga o e o nonofo i le lalolagi, o se aso o le toasa, o se aso o le susunuina, o se aso o le faatafunaga, o le tagitu’i, o le faanoanoa, ma o le auega; ma o le a oo mai i luga o le lalolagi atoa e pei o se asiosio, ua fetalai mai ai le Alii."},{"verse":25,"text":"Ma o le a amata i luga o lo’u fale, ma o le a alu atu mai lo’u fale, ua fetalai mai ai le Alii;"},{"verse":26,"text":"E muamua i totonu o i latou o i totonu o outou, ua fetalai mai ai le Alii, o e ua fai mai ua latou iloa lo’u igoa ae sa latou lē iloa a’u, ma ua upuleaga faasaga mai ia te a’u i le totonugalemu o lo’u fale, ua fetalai mai ai le Alii."},{"verse":27,"text":"O lea, vaai ia outou lē faapopoleina outou lava e faatatau i mataupu o la’u ekalesia i le nofoaga lenei, ua fetalai mai ai le Alii."},{"verse":28,"text":"Ae ia faamamā o outou loto i o’u luma; ma, ona outou o atu ai lea i le lalolagi atoa, ma talai atu la’u talalelei i tagata uma o e e lei mauaina;"},{"verse":29,"text":"Ma o ia o lē e talitonu ma papatiso o le a faaolaina, ma o ia o lē e lē talitonu, ma lē papatisoina, o le a faasalaina."},{"verse":30,"text":"Aua o outou, o le Toasefululua, ma i latou, o le Au Peresitene Sili, o e ua tofia faatasi ma outou e avea ma o outou fautua ma o outou taitai, ua tuuina atu i ai le mana o lenei perisitua, mo aso e gata ai ma mo le taimi mulimuli, lea ua i ai le tisipenisione o le atoaga o taimi,"},{"verse":31,"text":"O se mana lea ua outou umia, faatasi ma i latou uma o e na mauaina se tisipenisione i soo lava se taimi mai le amataga o le foafoaga;"},{"verse":32,"text":"Aua e moni Ou te fai atu ia te outou, o ki o lenei tisipenisione, ia ua outou maua, na tuuina ifo mai tamā, ma mulimuli lava i mea uma, na auina mai ia te outou mai le lagi."},{"verse":33,"text":"E moni Ou te fai atu ia te outou, faauta i le tele o lo outou valaauga. Faamamā o outou loto ma o outou ofu, ne’i manaomia mai o outou lima le toto o lenei tupulaga."},{"verse":34,"text":"Ia faamaoni se’i Ou alu atu, aua ua vave ona Ou alu atu; ma ua ia te a’u la’u taui e taui atu i tagata taitoatasi e tusa ai i ana galuega. O A’u o le Alefa ma le Omeka. Amene."}]},{"chapter":113,"verses":[{"verse":1,"text":"O ai le Pogai o Iese ua ta’u mai i fuaiupu 1, 2, 3, 4, ma le 5 o le mataupu 11 o le Isaia?"},{"verse":2,"text":"E moni ua faapea ona fetalai mai le Alii: O Keriso lea."},{"verse":3,"text":"O le a le tatupu ua ta’ua i le fuaiupu muamua o le mataupu 11 o le Isaia, lea o le a tupu mai le Pogai o Iese?"},{"verse":4,"text":"Faauta, ua faapea ona fetalai mai o le Alii: O se auauna i aao o Keriso, o lē o se vaega o lona tupuga mai e mai ia Iese faapea foi mai ia Efaraima, po o le aiga o Iosefa, o lē ua tuuina i ai le mana tele."},{"verse":5,"text":"O le a le a’a o Iese ua ta’u mai i le fuaiupu 10 o le mataupu 11?"},{"verse":6,"text":"Faauta, ua faapea ona fetalai mai o le Alii, o se tasi lea e tupuga mai ia Iese, faapea foi ma Iosefa, o lē e ā tonu le perisitua, ma ki o le malo, e avea ma tagavai, ma mo le faapotopotoina o lo’u nuu i aso e gata ai."},{"verse":7,"text":"O fesili mai ia Elias Higbee: O le a le uiga o le poloaiga o loo i le Isaia, mataupu 52, fuaiupu 1, ua fai mai: Ia ofu i lou malosi, Siona e—ma o ai tagata ua faatatau i ai le tala a Isaia?"},{"verse":8,"text":"Sa faatatau o ia ia te i latou o e o le a valaaulia e le Atua i aso e gata ai, o e o le a umia le mana o le perisitua e toe aumai ai Siona, ma le lavea’iga o Isaraelu; ma o le ofu i lona malosi o le ofu lea i le pule o le perisitua, lea ua ia te ia, o Siona, le aiā i ai, e ala i le gafa; ma le tasi foi, ia toe foi atu i lena mana na aveesea mai ia te ia."},{"verse":9,"text":"O le a se mea ia tatou malamalama i ai e uiga i le tatalaina e Siona o ia lava mai noataga o lona ūa; fuaiupu 2?"},{"verse":10,"text":"Ia tatou malamalama ua apoapoaiina vaega o totoe ua faataapeapeina ia toe foi mai i le Alii mai mea na latou pa’u’ū ese mai ai; o se mea afai latou te faia, o le folafolaga a le Alii e faapea o le a fetalai mai o ia ia te i latou, pe tuu mai ia te i latou faaaliga. Tagai i le fuaiupu 6, 7, ma le 8. O noataga o lona ūa, o fetuu ia a le Atua i ona luga, po o vaega o totoe o Isaraelu i lo latou tulaga faataapeapeina i totonu o Nuuese."}]},{"chapter":114,"verses":[{"verse":1,"text":"E moni ua faapea ona fetalai mai o le Alii: O le poto i la’u auauna o Tavita W. Patten, ia faamautu e ia ana pisinisi uma i le vave e mafai ai e ia, ma faia se faamatuuga atu o ana oloa, ina ia mafai ona faia e ia se misiona mo a’u i le tau totogo a sau, e faatasi ma isi, e oo lava i le toasefululua e aofia ai ma ia, e molimau atu i lo’u igoa ma folafola atu tala fiafia i le lalolagi atoa."},{"verse":2,"text":"Aua e moni ua faapea ona fetalai mai o le Alii, e tusa ai ma le iai o ni isi o i latou o lo’o filogia ma outou o e e faafitia lo’u igoa, e i ai isi o le a faatutuina i o latou tulaga ma maua lo latou pulega faa-epikopo. Amene."}]},{"chapter":115,"verses":[{"verse":1,"text":"E moni ua faapea ona fetalai mai o le Alii ia te oe, la’u auauna, o Iosefa Samita, Le Itiiti, ma la’u auauna foi o Sini Rikitone, ma la’u auauna foi o Ailama Samita, ma ou fesoasoani o e ua i ai ma e o le a tofia i le lumanai;"},{"verse":2,"text":"Ma ia te oe foi la’u auauna, o Edward Partridge, ma ona fesoasoani;"},{"verse":3,"text":"Ma i a’u auauna faamaoni foi o e o le aufono maualuga o la’u ekalesia i Siona, ona o le a faapea ona ta’ua o i latou, ma toeaina ma tagata uma o la’u Ekalesia a Iesu Keriso o le Au Paia o Aso e Gata Ai, ua salalau lautele i le lalolagi atoa;"},{"verse":4,"text":"Aua o le a faapea ona ta’ua o la’u ekalesia i aso e gata ai, O Le Ekalesia a Iesu Keriso o le Au Paia o Aso e Gata Ai."},{"verse":5,"text":"E moni Ou te fai atu ia te outou uma: Tutulai ia ma susulu atu, ina ia avea lo outou malamalama ma tagavai mo atunuu;"},{"verse":6,"text":"Ma ina ia avea le faapotopotoina faatasi i luga o le laueleele o Siona, ma i luga o ona siteki, mo se puipuiga, ma mo se sulufaiga mai le afā, ma mai le toasa pe a sasaa mai e aunoa ma le suia i luga o le lalolagi atoa."},{"verse":7,"text":"Ia tuu le aai, o Far West, ia avea o se laueleele paia ma faapaiaina mo a’u; ma o le a ta’ua o se aai sili ona paia, ona ua paia le laueleele ua e tu ai i ona luga."},{"verse":8,"text":"O lea, Ou te poloai atu ai ia te outou ia fausia se fale mo a’u, mo le faapotopotoina faatasi o la’u au paia, ina ia mafai ona latou tapuai mai ia te a’u."},{"verse":9,"text":"Ma ia tuu atu ia faia se amataga o lenei galuega, ma se faavae, ma se galuega sauniuni, i le taumafanafana a sau;"},{"verse":10,"text":"Ma ia tuu le amataga ia faia i le aso fa o Iulai e sosoo ai; ma ia tuu atu i lo’u nuu mai lena taimi ma agai atu i le lumanai, ia galulue ma le filiga e fausia se fale i lo’u igoa;"},{"verse":11,"text":"Ma i le tausaga e tasi mai le aso lenei, ia tuu atu ia te i latou e toe amata ona faataatia o le faavae o lo’u fale."},{"verse":12,"text":"Ia faapea ona tuu atu ia te i latou mai lena taimi ma agai atu i le lumanai, e galulue filiga seia oo ina mae’a, mai lona maatulimanu e oo atu i lona tumutumu, seia oo ina leai se mea e totoe e lei uma."},{"verse":13,"text":"E moni Ou te fai atu ia te outou, ia lē tuu atu i la’u auauna o Iosefa, po o la’u auauna o Sini, po o la’u auauna o Ailama, e toe aitalafu mo le fausiaina o se fale mo lo’u igoa;"},{"verse":14,"text":"Ae ia tuu atu ia fausia se fale i lo’u igoa e tusa ma le ata o le a Ou faaali atu ia te i latou."},{"verse":15,"text":"Ma afai e lē fausia e lo’u nuu e tusa ma le ata o le a Ou faailoa atu i lo latou au peresitene, o le a Ou lē taliaina mai o latou lima."},{"verse":16,"text":"Ae afai e fausia ai e lo’u nuu le fale e tusa ma le ata o le a Ou faailoa atu i lo latou au peresitene, o la’u auauna lava o Iosefa ma ona fesoasoani, ona Ou talia lea o le fale mai lima o lo’u nuu."},{"verse":17,"text":"O lenei foi, e moni Ou te fai atu ia te outou, o lo’u loto ia tatau ona fausia faavave le aai o Fa Uesi e ala i le faapotopotoina o la’u au paia;"},{"verse":18,"text":"Ma ia tofia foi ni isi nofoaga mo siteki i nofoaga o faataamilo ai, e pei ona o le a faaali atu ai i latou i la’u auauna o Iosefa, mai lea taimi i lea taimi."},{"verse":19,"text":"Aua faauta, o le a Ou faatasi ma ia, ma o le a Ou faapaiaina o ia i luma o le nuu; aua o ia ua Ou tuu atu i ai ki o lenei malo ma le auaunaga. E faapea lava. Amene."}]},{"chapter":116,"verses":[{"verse":1,"text":"O le Spring Hill ua faaigoa e le Alii ia Atamu-onai-Amani, aua, na fetalai mai o ia, o le nofoaga lea o le a sau i ai Atamu e asiasi mai i ona tagata, pe o le a nofo ai le Anamuā ona Aso, e pei ona fetalaia e Tanielu le perofeta."}]},{"chapter":117,"verses":[{"verse":1,"text":"E Moni ua faapea ona fetalai mai o le Alii i la’u auauna o Viliamu Mareko, ma la’u auauna foi o Newel K. Whitney, ia tuu atu ia te i laua e vave ona faamautu a laua pisinisi ma malaga atu mai le laueleele o Katelani, ae lei toe auina atu e A’u, o le Alii, le kiona i luga o le lalolagi."},{"verse":2,"text":"Ia tuu atu ia i laua ia ala mai, ma tutulai, ma o mai, ma lē faatuai, aua o A’u, o le Alii, ua poloai atu ai."},{"verse":3,"text":"O lea, afai la te faatuai o le a lē lelei ia i laua."},{"verse":4,"text":"Ia tuu atu ia te i laua ia salamo ia laua agasala uma, ma o laua naunauga faaletu’inanau uma, i o’u luma, ua fetalai mai ai le Alii; aua o a ea meatotino ia te a’u? ua fetalai mai ai le Alii."},{"verse":5,"text":"Ia tuu atu meatotino a Katelani ia faaliliu atu mo ’aitalafu, ua fetalai mai ai le Alii. Ia tuu atu ia mea, ua fetalai mai ai le Alii, ma o soo se mea e totoe, ia tuu pea i o oulua lima, ua fetalai mai ai le Alii."},{"verse":6,"text":"Aua, pe ua lē a a’u ea manu felelei o le lagi, ma i’a foi o le sami, ma manu vaefa o mauga? Ou te lei faia ea le lalolagi? Ua Ou lē umia ea taunuuga o autau uma a atunuu o le lalolagi?"},{"verse":7,"text":"O lea, Ou te lē faia ea nofoaga tuufua ia fotu ma fuga mai, ma fua tele mai? ua fetalai mai ai le Alii."},{"verse":8,"text":"Ua lē lava ea se avanoa i luga o mauga o Atamu-onai-Amani, ma i luga o fanua laugatasi o Olaha Shinehah, po o le laueleele sa nofo ai Atamu, ua tatau ai ona oulua mananao i lena mea ua na o se matāua, ma faatalalē ai i mataupu sili atu ona mamafa?"},{"verse":9,"text":"O lea, o mai i luga nei i le laueleele o lo’u nuu, o Siona."},{"verse":10,"text":"Ia tuu atu i la’u auauna o William Marks ia faamaoni i mea iti, ma o le a avea ai o ia ma pule i mea e tele. Ia tuu atu ia te ia e pulefaamalumalu i totonu o lo’u nuu i le aai o Fa Uesi, ma ia tuu atu ia te ia ia faamanuiaina i faamanuiaga o lo’u nuu."},{"verse":11,"text":"Ia tuu atu i la’u auauna o Newel K. Whitney ia maasiasi i le au Nikalaitai ma a latou mea inosia faalilolilo uma, ma lona faatauvaa atoa o le agaga i o’u luma, ua fetalai mai ai le Alii, ma sau i luga i le laueleele o Atamu-onai-Amani, ma avea o se epikopo i lo’u nuu, ua fetalai mai ai le Alii, e lē i le igoa ae i galuega, ua fetalai mai ai le Alii."},{"verse":12,"text":"O lenei foi, Ou te fai atu ia te outou, Ou te manatua la’u auauna o Oliver Granger; faauta, e moni Ou te fai atu ia te ia o le a paia le manatua o lona igoa mai lea tupulaga i lea tupulaga, e faavavau faavavau lava, ua fetalai mai ai le Alii."},{"verse":13,"text":"O lea, ia tuu atu ia te ia e finafinau faamaoni mo le laveaiina o le Au Peresitene Sili o la’u Ekalesia, ua fetalai mai ai le Alii; ma a pa’ū o ia o le a toe tulai mai o ia, ona o le a sili atu le paia o lana taulaga ia te a’u nai lo ana oloa e tele, ua fetalai mai ai le Alii."},{"verse":14,"text":"O lea, ia tuu atu ia te ia ia sau vave iinei, i le laueleele o Siona; ma o le a faia o ia ma faatauoloa mo lo’u igoa i le taimi e tatau ai, ua fetalai mai ai le Alii, mo le manuia o lo’u nuu."},{"verse":15,"text":"O lea ia leai se tagata e inoino i la’u auauna o Oliver Granger, ae ia tuu atu faamanuiaga o lo’u nuu ia i ona luga e faavavau faavavau lava."},{"verse":16,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ia tuu atu i a’u auauna uma i le laueleele o Katelani ia manatua le Alii lo latou Atua, ma lo’u fale foi, ia teuina ma tausia i le paia, ma faatoilalo e faatau-tupe i lo’u lava taimi e tatau ai, ua fetalai mai ai le Alii. E faapea lava. Amene."}]},{"chapter":118,"verses":[{"verse":1,"text":"E Moni, ua faapea ona fetalai mai o le Alii: Ia tuu atu ia faia faavave se konafesi; ia tuu atu ia faatulaga le Toasefululua; ma ia tuu atu ia tofia ni alii e sui i tulaga o i latou ua pa’uū."},{"verse":2,"text":"Ia tuu atu i la’u auauna o Thomas e nofo pea mo se vaitau i le laueleele o Siona, e faasalalau atu la’u upu."},{"verse":3,"text":"Ia tuu atu i e o totoe e faaauau pea ona talai atu mai lena itula, ma afai latou te faia lenei mea i le maualalo atoa o le loto, i le agamalu ma le lotomaualalo, ma le tali-tiga, o A’u, o le Alii, Ou te tuu atu ia i latou se folafolaga o le a Ou tuu atu mea mo o latou aiga; ma o le a tatalaina se faitotoa aoga mo i latou, mai le taimi lena ma le agai i luma."},{"verse":4,"text":"Ma o le tautotogo a sau, ia tuu atu i latou e o atu i luga o vai tetele, ma folafola atu iina la’u talalelei, o lona atoatoaga, ma molimau atu i lo’u igoa."},{"verse":5,"text":"Ia tuu atu ia te i latou e o ese atu mai la’u au paia i le aai o Fa Uesi, i le aso luasefulu-ono o Aperila e sosoo ai, i le fasi fanua o le a fausia ai lo’u fale, ua fetalai mai ai le Alii."},{"verse":6,"text":"Ia tuu atu i la’u auauna o Ioane Taylor, ma la’u auauna foi o John E. Page, ma la’u auauna foi o Wilford Woodruff, ma la’u auauna foi o Willard Richards, ia tofia e faatutumu tulaga o i latou o e ua pa’u’ū, ma ia faafesootai aloaia i latou e uiga i o latou tofiga."}]},{"chapter":119,"verses":[{"verse":1,"text":"E moni, ua faapea ona fetalai mai o le Alii, Ou te manaomia a latou mea faasili uma o meatotino uma ua lē manaomia ia tuu atu i lima o le epikopo o la’u ekalesia i Siona,"},{"verse":2,"text":"Mo le fausiaina o lo’u fale, ma le faataatiaina o le faavae o Siona ma mo le perisitua, ma mo aitalafu a le Au Peresitene o la’u Ekalesia."},{"verse":3,"text":"Ma o le a avea lenei ma amataga o le sefuluai a lo’u nuu."},{"verse":4,"text":"Ma a mavae lena, o i latou o e ua faapea ona faasefuluaiina, ia totogi atu le tasi-vaesefulu o a latou faasiliga uma i tausaga taitasi; ma ia avea lenei ma tulafono tumau ia te i latou e faavavau, mo la’u perisitua paia, ua faapea ona fetalai mai ai le Alii."},{"verse":5,"text":"E moni Ou te fai atu ia te outou, o le a oo mai o i latou uma o e potopoto atu i le laueleele o Siona, ia faasefuluaiina a latou meatotino faasili, ma ia latou tausia lenei tulafono, po ua le agavaa i latou e mau i totonu o outou."},{"verse":6,"text":"Ma Ou te fai atu ia te outou, afai e lē tausia e lo’u nuu lenei tulafono, ia tausia le paia, ma faapaia le laueleele o Siona mo a’u e ala i lenei tulafono, ina ia tausia ai i ona luga a’u tulafono ma a’u faamasinoga, ina ia silisili ona paia, faauta, e moni Ou te fai atu ia te outou, o le a lē avea ma laueleele o Siona ia te outou."},{"verse":7,"text":"Ma o le a avea lenei o se faataitaiga i siteki uma o Siona. E faapea lava. Amene."}]},{"chapter":120,"verses":[{"verse":1,"text":"E Moni, ua faapea ona fetalai mai o le Alii, ua oo mai nei le taimi, ia taulimaina ia mea e se aufono, e aofia ai le Au Peresitene Sili o la’u Ekalesia, ma le epikopo ma lana aufono, ma la’u aufono maualuga; ma i lo’u lava leo ia te i latou, ua fetalai mai ai le Alii. E faapea lava. Amene."}]},{"chapter":121,"verses":[{"verse":1,"text":"Le Atua e, o fea ea lau afio? Ma o fea o i ai le faapaologa ua ufitia ai lou lafitaga?"},{"verse":2,"text":"O le a le umi e taofia ai lou aao, ma silasila mai ai mai le lagi faavavau lou fofoga, ioe, lou fofoga manino, i sese ua faia i lou nuu ma au auauna, ma oo atu ai i ou fofoga o a latou tagi?"},{"verse":3,"text":"Ioe, le Alii e, o le a le umi latou te mafatia ai i nei sese ma sauaga e lē tusa ai ma le tulafono, ae lei faamalūlūina lou finagalo ia te i latou, ma uunaia ai lou finagalo i le agaalofa ia te i latou?"},{"verse":4,"text":"E, le Alii e le Atua Malosi Aoao, o Lē na faia le lagi, lalolagi, ma sami, ma mea uma o i ai, o lē na te taofiofi ma pulea le tiapolo, ma le malo pogisa ma faapouliuligia o Seoli—faaloaloa mai ia lou aao; sei ati mai ia lou fofoga-silasila; sei to a’e ia i luga lou faapaologa; ia lē toe punia lou lafitaga; sei uai mai ia ou fofoga; sei faamalūlūina lou finagalo, ma liuliu mai ia lou finagalo agaalofa ia te i matou."},{"verse":5,"text":"Ia tuu atu lou toasa e sasao faasaga i o matou fili; ma, ia e tauimasui i matou i le toasa tele o lou finagalo ma lau pelu, mo sese ua faia ia te i matou."},{"verse":6,"text":"Ia manatua lau au paia mafatia, lo matou Atua e; ma o le a olioli ai au auauna i lou suafa e faavavau."},{"verse":7,"text":"Lo’u atalii e, ia filemu lou agaga; o lou tiga ma ou puapuaga o le a na o sina taimi laitiiti;"},{"verse":8,"text":"Ma ona oo lea, afai e te gafatia lelei, o le a faaeaina oe e le Atua i lugā; o le a e manumalo i ou fili uma."},{"verse":9,"text":"O loo tutulai au uo i ou tafatafa, ma o le a latou toe faafeiloa’i ia te oe ma loto mafana ma lima faauo."},{"verse":10,"text":"E lei avea lava oe e pei o Iopu; e lē o finau au uo faasaga mai ia te oe, pe tuua’i oe i se solitulafono, e pei ona latou faia ia Iopu."},{"verse":11,"text":"Ma o i latou o e ua tuua’ia oe i le solitulafono, o le a lepetiaina lo latou faamoemoe, ma o o latou faamoeme o le a liusuavai ese e pei ona liusuavai le sau to’a i luma o ave mumū o le la oso;"},{"verse":12,"text":"O lenei foi ua faatuina e le Atua lona aao ma le faamaufaailoga e sui ai taimi ma tau, ma faatauaso o latou mafaufau, ina ia lē mafai ona latou malamalama i ana galuega ofoofogia; ina ia mafai ona faamaonia ai foi e ia i latou ma maua ai i latou ia latou lava togafiti;"},{"verse":13,"text":"O lenei foi, ona ua eleelea o latou loto, o mea foi ua latou naunau ia aumaia i luga o isi, ma fiafia ia mafatia ai isi, e mafai ona oo mai i o latou lava luga i le atoatoa a’ia’i;"},{"verse":14,"text":"Ina ia latou faanoanoa ai foi, ma ia vavae ese ai o latou faamoemoe;"},{"verse":15,"text":"Ma e lē tele ni tausaga mai le taimi nei, ae o le a tafia ese i latou ma a latou fanau mai i lalo o le lagi, ua fetalai mai ai le Atua, ina seia leai se toatasi o i latou e totoe e tulai i tafatafa o le pa."},{"verse":16,"text":"Ia fetuuina lava i latou uma o e e siia’e i luga le mulivae e faasaga i a’u ’au faauuina, ua fetalai mai ai le Alii, ma alaga ua latou agasala ae ua lē agasala i latou i o’u luma, ua fetalai mai ai le Alii, ae ua latou faia mea na tatau ai i o’u mata, ma na Ou poloaiina ai i latou."},{"verse":17,"text":"Ae o i latou o e ua alalaga ua solitulafono, ua latou faia lea mea ona o i latou o auauna a le agasala, ma o fanau i latou lava o le lē usiusitai."},{"verse":18,"text":"Ma o i latou o e e tauto pepelo e faasaga i a’u auauna, ina ia latou aumai i latou i le pologa ma le oti—"},{"verse":19,"text":"Oi talofa ia te i latou; ona ua latou faatausuai i a’u fanau iti, o le a vavae ese i latou mai sauniga o lo’u fale."},{"verse":20,"text":"O le a lē tumu la latou ato, o le a fano o latou fale ma a latou falemanu, ma o le a inosia i latou lava e i latou o e na faaseeina i latou."},{"verse":21,"text":"O le a latou lē maua le aiā i le perisitua, po o a latou fanau pe a mavae atu i latou mai lea tupulaga i lea tupulaga."},{"verse":22,"text":"Sa sili ona lelei mo i latou pe a na nonoa se maaolo i o latou ūa, ma malelemo ai i latou i le loloto o le sami."},{"verse":23,"text":"Oi talofa ia i latou uma o e ua faaatuatuvaleina o’u tagata, ma tulia, ma fasiotia, ma molimau faasaga ia te i latou, ua fetalai mai ai le Alii o ’Au; o le a lē sao lava se tupulaga o gata feai mai le malaia o seoli."},{"verse":24,"text":"Faauta, ua vaai o’u mata ma iloa a latou galuega uma, ma ua Ou faaagagaina se faamasinoga vave i lona tau, mo i latou uma;"},{"verse":25,"text":"Aua ua i ai se taimi atofaina mo tagata taitoatasi, e tusa ai ma ana galuega."},{"verse":26,"text":"O le a tuu atu e le Atua ia te outou le poto e ala i lona Agaga Paia, ioe, e ala i le meaalofa lē mafaamatalaina a le Agaga Paia, sa lei faaalia lava talu ona i ai le lalolagi sei oo mai i le taimi nei;"},{"verse":27,"text":"Lea sa faatalitali i ai tua’ā o o tatou tua’ā ma le faamoemoe naunautai e faaali mai i taimi mulimuli, lea sa faasino atu i ai o latou mafaufau e agelu, e pei ona taofia faaagaga mo le atoatoaga o lo latou mamalu;"},{"verse":28,"text":"E oo mai se taimi o le a leai ai se mea o le a taofia, pe toatasi se Atua o i ai pe toatele ni atua, o le a faaali mai lava i latou."},{"verse":29,"text":"O nofoalii ma malo, itumalo ma mana uma, o le a faaali ma tuu mai i luga o i latou uma o e na tumau ma le lototoa mo le talalelei a Iesu Keriso."},{"verse":30,"text":"O lenei foi, afai e i ai ni tuaoi ua faatutuina i le lagi po o le sami, po o i le laueleele matutu, po o i le la, masina, po o fetu—"},{"verse":31,"text":"O taimi uma o a latou taamilosaga, o aso atofaina uma, masina, ma tausaga, ma aso uma o o latou aso, masina, ma tausaga, ma o latou mamalu uma, tulafono, ma taimi faatutuina, o le a faaali mai i aso o le tisipenisione o le atoaga o taimi—"},{"verse":32,"text":"E tusa ma lena na faauuina i totonu o le Aufono a le Atua Faavavau o isi atua uma ae lei i ai le lalolagi lenei, e tatau ona faaagaga mo le faamae’aina ma lona iuga, pe a ulu atu tagata taitoatasi i lona afioaga faavavau ma i lona malologa ola pea."},{"verse":33,"text":"O le a le umi e mafai ona tumau ai vai e tafe i le eleelea? O le a le mana e taofia ai le lagi? E pei ona lē mafai e le tagata ona faaloaloa atu lona lima faatauvaa e taofi ai le vaitafe o le Misuri i lona ala faatonuina, pe toe liliu ai i tua lona tafe, ua faapena ona lē mafai ona taofia le Malosi Aoao mai le liligi ifo o le malamalama mai le lagi i luga o ulu o le Au Paia o Aso e Gata Ai."},{"verse":34,"text":"Faauta, e toatele e e valaaulia, ae toaitiiti e ua filifilia. Ma, pe aisea e lē filifilia ai i latou?"},{"verse":35,"text":"Aua ua pupū tele o latou loto i mea o lenei lalolagi, ma saili i viiga a tagata, ua latou lē aoaoina ai le lesona lenei e tasi—"},{"verse":36,"text":"O aiā a le perisitua ua fesootai e lē mavavaeeseina ma mana o le lagi, ma o mana o le lagi e lē mafai ona pulea pe faaaogaina tau lava i mataupu autu o le amiotonu."},{"verse":37,"text":"Atonu e mafai ona faaee mai i latou i luga o i tatou, e moni; ae a tatou taumafai e ufiufi a tatou agasala, pe faamalie lo tatou faamaualuga, lo tatou fiasili lē aoga, pe faaaoga ai le pule po o le puleaga po o le faamalosi i luga o agaga o le fanauga a tagata, i soo se tikeri o le amioletonu, faauta, e aveese e le lagi i latou lava; e faanoanoa le Agaga o le Alii; ma a aveesea, Amene i le perisitua po o le pule a lena tagata."},{"verse":38,"text":"Faauta, ae lei iloa e ia, ua tuua o ia ia te ia lava, e a’a i tui, e faasaua i le au paia, ma tau faasaga i le Atua."},{"verse":39,"text":"Ua tatou aoao e ala i mea faanoanoa e tutupu mai e faapea o le natura ma le uiga o le toeitiitii lava o tagata uma, o le vave lava latou te maua ai sina pule itiiti, e pei ona latou manatu i ai, e vave lava ona latou amata le faaaogaina o le puleaga amioletonu."},{"verse":40,"text":"O lena e toatele ai e e valaaulia, ae toaitiiti e ua filifilia."},{"verse":41,"text":"E leai se mana po o se aafiaga e mafai pe tatau ona faatumauina ona o le perisitua, nao i le faatauanau, i le tali-tiga, i le agamaualalo ma le agamalu, ma le alofa faamaoni;"},{"verse":42,"text":"I le agalelei, ma le malamalama manino, lea o le a faalautele sili ai le agaga e aunoa ma le faagutugutulua, ma aunoa ma le faa’ole’ole—"},{"verse":43,"text":"E aoai atu i taimi e tatau ai ma le tuusao, pe a uunaia ai e le Agaga Paia; ma ona faaali atu ai lea pe a mavae, o se alofa faateleina ia te ia o lē na e aoaiina, ne’i manatu o ia ia te oe o sona fili;"},{"verse":44,"text":"Ina ia iloa ai e ia e sili atu le malosi o lou faamaoni i lo fusi o le oti."},{"verse":45,"text":"Ia tuu foi lou loto ia tumu i le alofa mama i tagata uma, ma i le auaiga o le faatuatua, ma ia tuu le amiomamā e teuteuina ai ou mafaufauga e lē aunoa; ona faasolo malosi ai lea o lou lototele i luma o le Atua; ma o le a to ifo i luga o lou agaga le mataupu faavae o le perisitua e pei o le sau mai le lagi."},{"verse":46,"text":"O le a avea le Agaga Paia ma āu soa e lē aunoa, ma o lou tootoo o le a avea ma se tootoo lē feliuliua’i o le amiotonu ma le upumoni; ma o lau puleaga o le a avea ma se puleaga tumau e faavavau, ma e aunoa ma ni ala faamalosia, o le a tafe mai ia te oe e faavavau faavavau lava."}]},{"chapter":122,"verses":[{"verse":1,"text":"O le a fesilisili tuluiga o le lalolagi i lou igoa, ma o le a fai oe ma tauemuga a tagata valelea, ma o le a tete’e malosi seoli e faasaga ia te oe;"},{"verse":2,"text":"A’o e loto mamā ma e atamamai, ma e malualii, ma e amiomama, o le a saili fautuaga, ma le pule, ma faamanuiaga mai lalo o lou lima e lē aunoa."},{"verse":3,"text":"Ma o le a lē liliu lava faasaga mai ia te oe lou nuu i le molimau a tagata faalata."},{"verse":4,"text":"Ma e ui lava o a latou uunaiga o le a lafo atu ai oe i faalavelave, ma i pa ma puipui, o le a faamamaluina oe; ma ua nao mo sina taimi itiiti, ona sili atu ai lea o le matautia o lou leo i totonu o ou fili nai lo le leona fe’ai, ona o lou amiotonu; ma o le a tu i tafatafa o oe lou Atua e faavavau ma faavavau lava."},{"verse":5,"text":"Afai e valaauina oe e te ala atu i puapuaga; afai e faalavelavea oe i totonu o uso pepelo; afai e faalavelavea oe i totonu o faomea; afai e faalavelavea oe i le laueleele po o le sami;"},{"verse":6,"text":"Afai e tuua’ia oe i ituaiga o tuua’iga pepelo uma; afai e pa’u’ū mai ou fili i luga o oe; afai latou te vavae ese oe mai le mafutaga ma lou tamā ma lou tinā ma uso ma tuafafine; ma afai e toso ese oe e ou fili i le pelu faalālā mai le loto o lau avā, ma lau fanau, ma lou atalii matua, e ui ina na o le ono tausaga, o le a piimau i ou ofu, ma fai mai, Lo’u tamā e, lo’u tamā e, aisea e lē mafai ai ona e nofo ma i matou? E, lo’u tamā e, o le a le mea o le a fai e tagata ia te oe? ma afai o le a tulei ese o ia mai ia te oe i le pelu i le taimi lena, ma toso atu oe i le falepuipui, ma taulamalama ou fili ia te oe e pei o luko mo le toto o le tamai mamoe;"},{"verse":7,"text":"Ma afai e lafo oe i totonu o le lua, po o lima o e fasioti tagata, ma tuu mai le faaiuga o le oti i ou luga; afai e lafo oe i le loloto; afai e taupulepule galulolo o le sami e faasaga mai ia te oe; afai e avea matagi malolosi ma ou fili; afai e faapotopoto e le lagi le pogisa, ma aufaatasi elemene uma e pupuni le ala; ma i luga o mea uma, afai e tatala faamaga lautele mai e auvae lava o seoli le gutu ia te oe, ia e iloa, lo’u atalii e, o nei mea uma e te maua ai le poto masani, ma o le a avea mo ou lelei."},{"verse":8,"text":"Na afio ifo le Atalii o le Tagata i lalo o i latou uma. Ua sili atu ea oe ia te ia?"},{"verse":9,"text":"O lea, piimau i lou ala, ma o le a tumau le perisitua ia te oe; ona ua faatulagaina o latou tuaoi, e le mafai ona latou sopo’ia. Ua iloa ou aso, ma o ou tausaga o le a lē faitauina itiiti mai; o lea, aua le mata’u i mea e mafai ona fai e tagata, aua o le a faatasi le Atua ma oe e faavavau faavavau lava."}]},{"chapter":123,"verses":[{"verse":1,"text":"O lenei foi, matou te fautua atu mo lo outou manatunatu i ai, le tatau i le au paia uma ona faaputuputu o se malamalama e uiga i mea moni uma, ma mafatiaga ma sese na faia ia i latou e tagata o le Setete lenei;"},{"verse":2,"text":"Ma meatotino uma foi ma le aofai o faatama’iga na latou mafatia ai, i le loto atoa ma manu’a faaletagata lava ia, faapea foi ma meatotino moni;"},{"verse":3,"text":"Ma igoa foi o tagata uma na i ai se lima e fesoasoani i o latou sauaga, se’i oo ina mafai ona latou maua ai i latou ma iloa ai i latou."},{"verse":4,"text":"Ma atonu e mafai ona tofia se komiti e sailia ia mea, ma maua mai faamatalaga ma tautinoga tusitusia; ma faaputuputu mai foi lomiga taufaaleaga pepelo ua feavea’i;"},{"verse":5,"text":"Ma mea uma o i ai i mekasini, ma tusi o auiliiliga moni, ma talafaasolopito taufaaleaga pepelo uma ua lomia, ma o loo tusia, ma o ai foi na tusia, ma tuu atu se faasologa atoa o faiga faatiapolo ma faamalosiga amioleaga ma fasioti tagata na faia i luga o lenei nuu—"},{"verse":6,"text":"Ina ia lē gata ina tatou faasalalau atu i le lalolagi atoa, ae tuu atu i latou i ao o le malo i lo latou tulaga pouliuli uma ma faaseoli, o se taumafaiga mulimuli ua faatonuina ai i tatou e lo tatou Tamā Faalelagi, ae lei mafai ona tatou maua uma ma atoatoa o lena folafolaga lea o le a valaauina ai o ia mai lona lafitaga; ma ina ia tuua le atunuu atoa e aunoa ma se ’alofaga ae lei auina mai e ia le mana o lona aao malosi."},{"verse":7,"text":"O se tiute lē ma’alofia ua tatou nofo aitalafu ai i le Atua, i agelu, o e o le a aumaia i tatou e tutulai faatasi, ma ia i tatou lava, ia tatou avā ma fanau, o e ua faia ia ifo i lalo i le faavauvau, faanoanoa, ma le atuatuvale, i lalo o le lima e sili ona tausalaina o le fasioti tagata, pule malosi, ma le faasauā, ua lagolago ma uunaia ma sapasapaia e uunaiga a lena agaga lea na tu’ifaomauina taofi o tamā, o e ua fai mo latou tofi le pepelo, i loto o fanau, ma faatumuina le lalolagi i le fenumia’i, ma ua tupu malosi pea lava, ma ua avea nei ma puna-autu o mea eleelea uma, ma ua ōi le lalolagi atoa i lalo o le mamafa o lona amioletonu."},{"verse":8,"text":"O se amo u’amea, o se maea malosi; o taofi-lima lava ia, ma filifili, ma tauvae, ma nonoa o seoli."},{"verse":9,"text":"O lea o se tiute lē ma’alofia ua tatou aitalafu ai, e lē nao ia tatou lava avā ma fanau, ae i fafine foi ua oti a latou tane ma e ua aunoa ma tamā, o e o a latou tane ma tamā na fasiotia i lalo o lona lima u’amea;"},{"verse":10,"text":"O galuega pouliuli ma pogisa ua fai ma mea e gatete ai o seoli lava ia, ma tulai faate’ia ma sesega ai, ma galulu ma le mafai ai ona taofia le gatete o lima o le tiapolo lava ia."},{"verse":11,"text":"Ma o se tiute lē ma’alofia foi ua tatou aitalafu ai i tupulaga fana’e uma, ma i e uma ua loto mamā—"},{"verse":12,"text":"Aua o loo i ai nei tagata e toatele i luga o le lalolagi i totonu o lotu uma, vaega, ma tapuaiga, o e ua faatauasoina i le taufaasese poto o tagata, lea ua latou taooto faapupuna ai e faasese, ma o e ua nao na taofia mai le upumoni ona ua latou lē iloa le mea e maua ai—"},{"verse":13,"text":"O lea, e tatau ona tatou faama’umau ai ma faaaoga ia uma o tatou ola i le aumaia i le malamalama o mea natia uma a le pogisa, i mea ua tatou iloa ai; ma ua faaalia moni mai i latou mai le lagi—"},{"verse":14,"text":"Ona o lea e tatau ai ona faasaga atu i le faia o ia mea ma le filiga tele."},{"verse":15,"text":"Ia lē tuu atu i se tagata ia manatu i ia mea o ni mea faatauvaa; aua e tele mea o i lumanai, e faatatau i le au paia, o e ua faalagolago i luga o ia mea."},{"verse":16,"text":"Ua outou silafia, uso e, e aoga tele i se vaa tele se foeuli laitiiti i le taimi o se afa, e faatautaia faasagatonu ai le folauga i le matagi ma galu."},{"verse":17,"text":"O lea, le au uso pele e, ia tatou faia ai ma le fiafia mea uma ua i ai i lo tatou mana; ona mafai lea ona tatou tutulai e faatali, ma le mautinoa atoatoa, e vaai i le faaolataga a le Atua, ma lona aao o le a faaali mai."}]},{"chapter":124,"verses":[{"verse":1,"text":"E moni, ua faapea ona fetalai mai o le Alii ia te oe, la’u auauna o Iosefa Samita, ua Ou fiafia lava i lau taulaga ma au tautinoga, ua e faia; ona o le faamoemoe lea na Ou faatuina mai ai oe, ina ia Ou faailoa atu lo’u poto e ala i mea vaivai o le lalolagi."},{"verse":2,"text":"Ua talia au tatalo i o’u luma; ma i le tali atu i au tatalo Ou te fai atu ai ia te oe, ua valaaulia vave nei oe e faia se folafolaga aloaia o la’u talalelei, ma o le siteki lenei ua Ou faatuina e avea ma maatulimanu o Siona, lea o le a faaiila i teuga matagofie e tusa ma foliga o se maota o se tupu."},{"verse":3,"text":"Ia fai atu lenei folafolaga i tupu uma o le lalolagi, i ona tulimanu e fa, i le peresitene mamalu filifilia, ma kovana faitōfā o le atunuu ua e nofo ai, ma i atunuu uma ua salalau i le lalolagi."},{"verse":4,"text":"Ia tusia i le agaga o le agamalu ma i le mana o le Agaga Paia, lea o le a ia te oe i le taimi e tusia ai lea lava folafolaga;"},{"verse":5,"text":"Aua o le a tuuina atu ia te oe e le Agaga Paia ia e iloa lo’u loto e uiga i tupu ma pule na, e oo lava i mea o le a pa’u’ū ai i latou i se taimi o le a oo mai."},{"verse":6,"text":"Aua, faauta, ua lata ona Ou valaau atu ia i latou ia ua’i mai i le malamalama ma le mamalu o Siona, aua ua oo mai le taimi atofaina e faapitoa ai Siona."},{"verse":7,"text":"O lea, ia e valaau atu ai, ia te i latou i le folafolaga leotele, faatasi ma lau molimau, ma ia e lē mata’u ia i latou, ona ua pei i latou o le vao, ma o lo latou mamalu atoa ua faapei o lona fuga ua lata ona pa’ū, ma ina ia tuua ai foi i latou e aunoa ma se ’alofaga—"},{"verse":8,"text":"Ma ia mafai ona Ou asiasi atu ia te i latou i le aso o le asiasiga, pe a Ou afe le ufiufi o o’u mata, e tofi atu le vaega a le faasauā faatasi ma e pepelo, i le mea e i ai le lilivau o nifo, pe afai latou te teena a’u auauna ma la’u molimau ua Ou faaalia atu ia te i latou."},{"verse":9,"text":"O lenei foi, o le a Ou asiasi atu ma faamalulu o latou loto, le toatele lea o i latou, mo lo outou lelei, ina ia outou maua le alofa tunoa i la latou vaai, ina ia mafai ona latou o mai i le malamalama o le upumoni, ma Nuuese i le faaeaga po o le siitiaina a’e i luga o Siona."},{"verse":10,"text":"Ona ua vave ona oo mai o le aso o la’u asiasiga, i se itula tou te lē mafaufau i ai; ma o fea o le a i ai le saogalemu o lo’u nuu, ma le sulufaiga mo i latou o e o le a tuua?"},{"verse":11,"text":"Ala mai ia, E, tupu e o le lalolagi! Ia outou o mai ia, E, ia outou o mai ia, ma a outou auro ma a outou ario, e fesoasoani i lo’u nuu, i le fale o afafine o Siona."},{"verse":12,"text":"O lenei foi, e moni Ou te fai atu ia te oe, tuu atu i la’u auauna o Robert B. Thompson e fesoasoani ia te oe e tusi lenei folafolaga, ona ua Ou fiafia lava ia te ia, ma e tatau ona faatasi o ia ma oe;"},{"verse":13,"text":"O lea, ia tuu atu ia te ia ’ia faalogo i lau fautuaga, ma o le a Ou faamanuiaina o ia i faamanuiaga e tele; ia tuu atu ia te ia ’ia faamaoni ma tonu i mea uma mai le taimi nei ma le agai i luma, ma o le a sili o ia i la’u vaai;"},{"verse":14,"text":"Ae ia tuu atu ia te ia ’ia manatua e ia o le a Ou manaomia mai lona lima lana mea-tausi."},{"verse":15,"text":"O lenei foi, e moni Ou te fai atu ia te oe, amuia lava la’u auauna o Ailama Samita; aua o A’u, o le Alii, ua alofa ia te ia ona o le faamaoni o lona loto, ma ona e fiafia o ia i mea ua sa’o i o’u luma, ua fetalai mai ai le Alii."},{"verse":16,"text":"O lenei foi, tuu atu i la’u auauna o John C. Bennett e fesoasoani ia te oe i lau galuega i le auina atu o la’u upu i tupu ma tagata o le lalolagi, ma tulai i ou tafatafa, la’u auauna lava lea o Iosefa Samita, i le itula o le puapuaga; ma o le a lē i’uvale lona taui pe afai e talia e ia fautuaga."},{"verse":17,"text":"Ma o le a sili tele atu o ia ona o lona alofa, aua o le a avea o ia mo’u pe afai e faia e ia lenei mea, ua fetalai mai ai le Alii. Ua Ou vaai i le galuega na ia faia, lea Ou te talia pe afai e faaauau pea o ia, ma faapaleina o ia i faamanuiaga ma le mamalu tele."},{"verse":18,"text":"O lenei foi, Ou te fai atu ia te oe, o lo’u loto e tatau i la’u auauna o Lyman Wight ona faaauau pea ona talai atu mo Siona, i le agaga o le agamalu, ma ta’uta’u atu a’u i luma o le lalolagi; ma o le a Ou sapasapaia o ia i luga e pei o i luga o apaau o aeto; ma o le a aumai e ia le mamalu ma le viiga ia te ia lava ma i lo’u igoa."},{"verse":19,"text":"Ina ia mafai ona Ou avea o ia mo a’u lava pe a faai’uina e ia lana galuega, e pei ona Ou faia i la’u auauna o David Patten, lē ua faatasi nei ma a’u, ma la’u auauna foi o Edward Partridge, ma la’u auauna matua foi o Iosefa Samitale Matua, lē ua nonofo faatasi ma Aperaamo i lona lima taumatau, ma ua faamanuiaina lava ma paia o ia, ona ua ā a’u o ia."},{"verse":20,"text":"O lenei foi, e moni Ou te fai atu ia te oe, o la’u auauna o George Miller, ua aunoa ma le faa’ole’ole; e mafai ona faalagolagoina o ia ona o le faamaoni o lona loto; ma ona o le alofa ua ia te ia i la’u molimau, o A’u, o le Alii, ua alofa ia te ia."},{"verse":21,"text":"O lea Ou te fai atu ai ia te oe, Ou te faamauina i luga o lona ulu le tofi o se au epikopo, e pei o la’u auauna o Edward Partridge, ina ia maua e ia faapaiaga o lo’u fale, ina ia mafai e ia ona tuu atu faamanuiaga i luga o ulu o e matitiva o lo’u nuu, ua fetalai mai ai le Alii. Ia lē tuu atu i se tagata ia inoino i la’u auauna o George, ona o le a faamamaluina a’u e ia."},{"verse":22,"text":"Ia tuu atu i la’u auauna o George, ma la’u auauna o Lyman, ma la’u auauna o John Snider, ma isi, e fausia se fale i lo’u igoa, ia pei o le fale o le a faaali atu e la’u auauna o Iosefa ia te i latou, i luga o le nofoaga o le a faaali atu foi e ia ia te i latou."},{"verse":23,"text":"Ma o le a avea lea fale o se fale e tali ai tagata, o se fale e mafai ona o mai i ai tagata ese mai mea mamao e nonofo ai; o lea ia avea ma se fale lelei, e agavaa mo le talia atoatoa, ina ia maua e le tagata malaga vaivai le maloloina ma le saogalemu a’o manatunatu loloto o ia i le afioga a le Alii; ma o le maatulimanu ua Ou tofia mo Siona."},{"verse":24,"text":"O lenei fale o le a avea ma nofoaga o le maloloina pe afai e fausia i lo’u igoa, ma pe afai e lē tuua e le pule o le a tofia i ai se mea eleelea e oo mai i ona luga. O le a paia, po ua lē afio ai le Alii lo outou Atua."},{"verse":25,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ia tuu atu i la’u au paia uma e o mai i mea mamao."},{"verse":26,"text":"Ma ia outou auina atu ni avefeau televavave, ioe, ni avefeau filifilia, ma fai atu ia te i latou: Ia outou o mai ia, ma a outou auro uma, ma a outou ario, ma a outou maa taua, ma a outou mea anamua uma, ma faatasi ma i latou uma o e ua i ai le malamalama e uiga i mea anamua, o e e fia o mai, ia o mai, ma aumai le laau tasura, ma le laau perosi, ma le laau kitara, faatasi ma laau taua uma o le lalolagi;"},{"verse":27,"text":"Ma faatasi ma le uamea, ma le kopa, ma le apamemea, ma le metala pa’epa’e, faatasi ma a outou mea taua uma o le lalolagi; ma fausia se fale i lo’u igoa, mo le Silisili Ese e afio ai."},{"verse":28,"text":"Aua ua leai se mea e maua i le lalolagi e mafai e ia ona afio mai i ai ma toefuatai mai mea na leiloa mai ia te outou, po o mea na aveesea e ia, o le atoatoaga lava o le perisitua."},{"verse":29,"text":"Aua ua lē o i ai se faatanoa faipapatisoga i le lalolagi, e mafai ai e i latou, o la’u au paia, ona papatisoina ai mo i latou o e ua maliliu—"},{"verse":30,"text":"Aua o lenei sauniga e ā lo’u fale, ma e lē mafai ona Ou taliaina, tau lava i aso o lo outou mativa, ia e lē mafai ai ona outou fausia o se fale mo a’u."},{"verse":31,"text":"Ae ’Ou te poloai atu ia te outou, outou uma o la’u au paia, ia fausia se fale mo a’u; ma ’Ou te tuu atu ia te outou se taimi ua lava e fausia ai se fale mo a’u; ma o le taimi lea o le a talia ai a outou papatisoga ia te a’u."},{"verse":32,"text":"Ae faauta, i le faaiuga o lenei taimi tuupoina o le a lē talia ia te a’u a outou papatisoga mo o outou tagata maliliu; ma afai tou te lē faia nei mea i le faaiuga o le taimi tuupoina, o le a teena outou o se ekalesia, faatasi ma o outou tagata maliliu, ua fetalai mai ai le Alii lo outou Atua."},{"verse":33,"text":"Aua e moni ’Ou te fai atu ia te outou, a uma ona outou maua se taimi ua lava e fausia ai se fale mo a’u, o ona totonu e i ai le sauniga o le papatisoga mo e ua maliliu, ma o mea lava ia na faatuina a o le i faavaeina le lalolagi, o le a lē mafai ona talia ia te a’u a outou papatisoga mo o outou tagata maliliu;"},{"verse":34,"text":"Aua o totonu iinā e faauuina ai ki o le perisitua paia, ina ia outou maua le viiga ma le mamalu."},{"verse":35,"text":"Ma a mavae lenei taimi, o a outou papatisoga mo e ua maliliu, e faia e i latou o e ua salalau lautele, e lē talia ia te a’u, ua fetalai mai ai le Alii."},{"verse":36,"text":"Aua ua faauuina o Siona, ma i ona siteki, ma i Ierusalema, nofoaga na ua ’Ou tofia mo sulufaiga, o nofoaga na ia avea mo a outou papatisoga mo o outou tagata maliliu."},{"verse":37,"text":"O lenei foi, e moni ’Ou te fai atu ia te outou, pe faapefea ona talia ia te a’u a outou mulumuluga, vagana ai ua outou faia i latou i totonu o se fale ua outou fausia mo lo’u igoa?"},{"verse":38,"text":"Aua, o le pogai lea na ’Ou poloaiina ai Mose e tatau ia te ia ona fausia se fale fetafai, e tatau ona latou tauave faatasi ma i latou i le vao, ma ia fausia se fale i le laueleele o le folafolaga, ina ia mafai ona faaali mai ai sauniga ia na natia mai le taimi ae lei i ai le lalolagi."},{"verse":39,"text":"O lea, e moni ’Ou te fai atu ia te outou, o a outou faauuga, ma a outou mulumuluga, ma a outou papatisoga mo e ua maliliu, ma a outou faapotopotoga paia, ma a outou faamanatuga mo a outou taulaga e faia e atalii o Levi, ma mo a outou faaaliga i o outou nofoaga sili ona paia ia tou te maua ai i totonu talatalaga, ma a outou tulafono ma faamasinoga, mo le amataga o faaaliga ma le faavaega o Siona, ma mo le mamalu, viiga, ma le faaeega o ona tagata uma, ua faauuina i sauniga o lo’u fale paia, lea ua poloaiina lo’u nuu i taimi uma ia fausia i lo’u igoa paia."},{"verse":40,"text":"Ma e moni ’Ou te fai atu ia te outou, ia tuu atu ia fausia lenei fale mo lo’u igoa, ina ia mafai ona ’Ou faaali atu ai i totonu a’u sauniga i lo’u nuu;"},{"verse":41,"text":"Aua ua ’Ou manatu ua tatau ona faaali atu i la’u ekalesia mea sa taofi natia a o le i faavaeina le lalolagi, o mea e faatatau i le tisipenisione o le ’atoaga o taimi."},{"verse":42,"text":"Ma o le a ’Ou faaali atu i la’u auauna o Iosefa mea uma e faatatau i lenei fale, ma lona perisitua, ma le nofoaga o le a fausia ai i luga."},{"verse":43,"text":"Ma ia outou fausia i luga o le nofoaga i le mea ua outou mafaufau e fausia ai, aua o le fasi fanua lena ua Ou filifilia mo outou e fausia ai."},{"verse":44,"text":"Afai tou te galulue ma lo outou malosi atoa, o le a Ou faapaiaina lena fasi eleele ina ia faia ia paia."},{"verse":45,"text":"Ma afai e faalogo mai lo’u nuu i lo’u leo, ma le leo o a’u auauna o e ua Ou tofia e taitaia lo’u nuu, faauta, e moni Ou te fai atu ia te outou, o le a lē aveesea i latou mai lo latou nofoaga."},{"verse":46,"text":"Ae afai latou te lē faalogo mai i lo’u leo, po o le leo o nei alii o e ua Ou tofia, o le a lē faamanuiaina i latou, aua ua latou faaeleeleaina o’u eleele paia, ma a’u sauniga paia, ma tusi faavae, ma a’u upu paia Ou te tuu atu ia te i latou."},{"verse":47,"text":"Ma o le a oo mai, afai tou te fausia se fale i lo’u igoa, ma lē faia mea Ou te fai atu ai, o le a Ou lē faia le tautoga ua Ou faia atu ia te outou, pe faataunuu folafolaga ua outou faamoemoe i ai mai lo’u lima, ua fetalai mai ai le Alii."},{"verse":48,"text":"Aua nai lo faamanuiaga, o outou, ia outou lava galuega, tou te aumaia fetuu, le toasa, le toatamai, ma faamasinoga i luga o o outou lava ulu, e ala i o outou sese, ma ala ia outou mea inosia uma, ua outou faia i o’u luma, ua fetalai mai ai le Alii."},{"verse":49,"text":"E moni, e moni, Ou te fai atu ia te outou, a Ou tuuina atu se poloaiga i soo se tasi o atalii o tagata, e fai se galuega i lo’u igoa, ma o atu ia atalii o tagata ma lo latou malosi atoa ma mea uma ua ia te i latou e fai lena galuega, ma lē tuua lo latou filiga, ae o mai o latou fili ia i latou ma taofi i latou mai le faia o lena galuega, faauta, ona tatau ai lea ia te a’u ona lē toe manaomia lena galuega mai i lima o ia atalii o tagata, ae talia a latou taulaga."},{"verse":50,"text":"Ma o le amioletonu ma le soliga o a’u tulafono ma poloaiga paia o le a Ou asiasi atu ai i luga o ulu o i latou o e ua ponatia ai la’u galuega, e oo atu i le tupulaga lona tolu ma le fa, i le umi latou te lē salamo ai, ma inoino mai ai ia te a’u, ua fetalai mai ai le Alii le Atua."},{"verse":51,"text":"O lea, o le pogai lenei ua Ou taliaina ai taulaga a i latou o e na Ou poloaiina e fausia se aai ma se fale i lo’u igoa, i le itumalo o Jackson, Misuri, ma sa taofia e o latou fili, ua fetalai mai ai le Alii lo outou Atua."},{"verse":52,"text":"Ma o le a Ou tali atu i le faamasinoga, ita, ma le toasa, le tagiaue, faavauvau, ma le lilivau o nifo i luga o o latou ulu, e oo atu i le tupulaga lona tolu ma le fa, i le umi latou te lē salamo ai, ma inoino mai ia te a’u, ua fetalai mai ai le Alii lo outou Atua."},{"verse":53,"text":"Ma Ou te faia lenei mea ma faataitaiga ia te outou, mo lo outou toafilemu e faatatau ia i latou uma o e na poloaiina e faia se galuega a ua ponatia e lima o o latou fili, ma i sauaga, ua fetalai mai ai le Alii lo outou Atua."},{"verse":54,"text":"Aua o A’u o le Alii lo outou Atua, ma o le a Ou laveaiina i latou uma o o outou uso o e na loto mamā, ma sa fasiotia i le laueleele o Misuri, ua fetalai mai ai le Alii."},{"verse":55,"text":"O lenei foi, e moni Ou te fai atu ia te outou, Ou te toe poloai atu ia te outou ia fausia se fale i lo’u igoa, i le nofoaga lava lenei, ina ia outou faamaonia mai outou lava ia te a’u tou te faamaoni i mea uma Ou te poloaiina ai outou, ina ia Ou faamanuiaina outou, ma faapaleina outou i le mamalu, ola pea, ma le ola e faavavau."},{"verse":56,"text":"Ma o lenei Ou te fai atu ia te outou, e faatatau i lo’u fale talimalo na Ou poloaiina outou ia fausia mo le taliga o tagata ese, ia tuu atu ia fausia i lo’u igoa, ma ia tuu atu lo’u igoa e faaigoa ai, ma ia tuu atu i ai i totonu se mea e nonofo ai la’u auauna o Iosefa ma lona aiga, mai lea tupulaga i lea tupulaga."},{"verse":57,"text":"Aua ua Ou tuuina lenei faauuga i luga o lona ulu, ina ia tuuina foi lona faamanuiaga i luga o ulu o ana fanau mulimuli mai pe a mavae atu o ia."},{"verse":58,"text":"Ma e pei ona Ou fai atu ia Aperaamo e faatatau i ituaiga o le lalolagi, e faapea foi ona Ou fai atu i la’u auauna o Iosefa: O le a faamanuiaina ia te oe ma au fanau ituaiga o le lalolagi."},{"verse":59,"text":"O lea, ia tuu atu ai i la’u auauna o Iosefa ma ana fanau e mulimuli mai pe a mavae atu o ia ia nonofo i lena fale, mai lea tupulaga i lea tupulaga, e faavavau ma faavavau lava, ua fetalai mai ai le Alii."},{"verse":60,"text":"Ma ia tuu atu le igoa o lena fale ia ta’ua o le Maota i Navu; ma ia tuu atu ia avea ma malutaga matagofie mo tagata, ma se nofoaga mapu mo le tagata malaga ua vaivai, ina ia mafai e ia ona mafaufau ai i le mamalu o Siona, ma le mamalu o lenei aai, lona maatulimanu;"},{"verse":61,"text":"Ina ia mafai ai foi e ia ona maua le fautuaga mai ia te i latou o e ua Ou faatutuina e avea e pei o ni laau totō lauiloa, ma o ni leoleo i luga o ona pa."},{"verse":62,"text":"Faauta, e moni Ou te fai atu ia te outou, ia tuu atu i la’u auauna o George Miller, ma la’u auauna o Lyman Wight, ma la’u auauna o John Snider, ma la’u auauna o Peter Haws, e faatulaga i latou lava, ma tofia se tasi o i latou e avea ma peresitene i luga o la latou korama mo le faamoemoe o le fausiaina o lena fale."},{"verse":63,"text":"Ma ia latou faia se tulafono faavae, e mafai ai ona latou maua ni vaega fa’asoa mo le fausiaina o lena fale."},{"verse":64,"text":"Ma ia latou lē taliaina se mea maualalo ifo i lo le limasefulu tālā mo se vaega fa’asoa i lena fale, ma ia faatagaina i latou e talia le sefululima afe tālā mai i soo se tagata e toatasi mo vaega fa’asoa o lena fale."},{"verse":65,"text":"Ae ia lē faatagaina i latou e talia mai i soo se tagata e toatasi le sili atu i le sefululima afe tālā mo se vaega fa’asoa."},{"verse":66,"text":"Ma ia lē faatagaina i latou e talia mai i soo se tagata e toatasi le itiiti ifo mai i le limasefulu tālā mo se vaega fa’asoa i lena fale."},{"verse":67,"text":"Ma ia lē faatagaina i latou e talia soo se tagata e avea o se ua i ai vaega fa’asoa i lenei fale, vagana ua totogi mai e lea lava tagata lana vaega i o latou lima i le taimi e maua ai e ia lana fa’asoa;"},{"verse":68,"text":"Ma o le a maua e ia le vaega fa’asoa i lena fale e tusa ma le aofai o vaega fa’asoa e totogi mai e ia i o latou lima; ae afai e leai se mea e totogi mai e ia i o latou lima o le a lē maua e ia ni vaega fa’asoa i lena fale."},{"verse":69,"text":"Ma ai se e totogi mai se vaega fa’asoa i o latou lima ia avea ma vaega fa’asoa i lena lava fale, mo ia lava, ma mo ana tupulaga mulimuli mai pe a mavae atu o ia, mai lea tupulaga i lea tupulaga, i le umi e umia ai e ia ma ona suli lena vaega fa’asoa, ma lē faatau atu ai pe tuu ese atu ai le vaega fa’asoa mai i o latou lima i la latou filifiliga saoloto ma mea e fai, pe afai tou te faia lo’u loto, ua fetalai mai ai le Alii lo outou Atua."},{"verse":70,"text":"O lenei foi, e moni Ou te fai atu ia te outou, afai e talia e la’u auauna o George Miller, ma la’u auauna o Lyman Wight, ma la’u auauna o John Snider, ma la’u auauna o Peter Haws, soo se vaega fa’asoa i o latou lima, i tupe, po o i meatotino latou te maua ai le aofai moni i tupe, ia latou lē tuu ese soo se vaega o lena fa’asoa mo soo se isi lava faamoemoe, tau lava mo lena fale."},{"verse":71,"text":"Ma afai latou te tuu ese soo se vaega o lena fa’asoa mo soo se isi lava mea, tau lava mo lena fale, e aunoa ma le ioe a le ’au fai fa’asoa, ma latou lē toe totogi mai faa-sautuafā mo le vaega fa’asoa na latou tuu ese mo soo se isi mea, tau lava i lena fale, o le a fetuuina i latou, ma o le a aveesea mai lo latou tulaga, ua fetalai mai ai le Alii le Atua; ona o A’u, le Alii, o le Atua, ma e lē mafai ona ulagia i soo se tasi o ia mea."},{"verse":72,"text":"E moni Ou te fai atu ia te outou, ia tuu atu i la’u auauna o Iosefa e totogi atu vaega fa’asoa i o latou lima mo le fausiaina o lena fale, pe pei ona talafegai lelei ia te ia; ae e lē mafai e la’u auauna o Iosefa ona totogi e sili atu i le sefululima afe tālā o vaega fa’asoa i lena fale, pe i lalo o le limasefulu tālā; pe mafai foi e se isi lava tagata, ua fetalai mai ai le Alii."},{"verse":73,"text":"Ma o loo i ai foi isi o e ua fia iloa lo’u loto e faatatau ia te i latou, ona ua latou ole mai ai i o’u lima."},{"verse":74,"text":"O lea, Ou te fai atu ai ia te outou e uiga i la’u auauna o Vinson Knight, afai e fia faia e ia lo’u loto ia tuu atu ia te ia e fai saofaga i lena fale mo ia lava, ma mo ana fanau pe a mavae o ia, mai lea tupulaga i lea tupulaga."},{"verse":75,"text":"Ma ia tuu atu ia te ia e siitia a’e i luga lona leo ia umi ma leotele, i totonu o tagata, e aioi le tagi a e matitiva ma lē tagolima; ma ia tuu atu ia te ia ia lē faavaivai, pe ia vaivai lona loto; ma o le a Ou talia ana taulaga, ona o le a lē avea i latou ia te a’u e pei o taulaga a Kaino, aua o le a avea o ia mo a’u, ua fetalai mai ai le Alii."},{"verse":76,"text":"Ia tuu atu i lona aiga ia olioli ma liliu ese o latou loto mai puapuaga; ona ua Ou filifilia o ia ma faauuina o ia, ma o le a faamamaluina o ia i totonu o lona aiga, aua o le a Ou faamagaloina ana agasala uma, ua fetalai mai ai le Alii. Amene."},{"verse":77,"text":"E moni Ou te fai atu ia te outou, ia tuu atu i la’u auauna o Ailama ia fai saofaga i lena fale i le mea e talafeagai lelei ia te ia, mo ia lava ma ana fanau pe a mavae atu o ia, mai lea tupulaga i lea tupulaga."},{"verse":78,"text":"Ia tuu atu i la’u auauna o Isaac Galland e fai saofaga i lena fale; aua o A’u, o le Alii, ua alofa ia te ia mo galuega na ia faia, ma o le a Ou faamagaloina ana agasala uma; o lea, ia tuu atu ia manatua o ia mo se sao i lena fale mai lea tupulaga i lea tupulaga."},{"verse":79,"text":"Ia tuu atu i la’u auauna o Isaac Galland ia tofia i totonu o outou, ma ia faauu e la’u auauna o William Marks, ma faamanuia e ia, e o ma la’u auauna o Ailama e faataunuu le galuega o le a faasino atu e la’u auauna o Iosefa ia te i laua, ma o le a faamanuiaina tele i laua."},{"verse":80,"text":"Ia tuu atu i la’u auauna o William Marks e totogi se saofaga i lena fale, e pei ona talafegai lelei ia te ia, mo ia lava ma ana fanau, mai lea tupulaga i lea tupulaga."},{"verse":81,"text":"Ia tu’u atu i la’u auauna o Enele G. Sherwood e totogi se saofaga i lena fale, e pei ona talafeagai lelei ia te ia, mo ia lava ma lana fanau pe a mavae atu o ia, mai lea tupulaga i lea tupulaga."},{"verse":82,"text":"Ia tuu atu i la’u auauna o William Law e totogi se saofaga i lena fale, mo ia lava ma lana fanau pe a mavae atu o ia, mai lea tupulaga i lea tupulaga."},{"verse":83,"text":"Afai e fia faia e ia lo’u loto ia lē tuu atu ia te ia e ave lona aiga i laueleele i sasa’e, i Katelani lea; ae ui i lea, o A’u, o le Alii, o le a Ou ati a’e i luga Katelani, peitai, o A’u, o le Alii, ua saunia se sasa mo i latou o e o nonofo ai."},{"verse":84,"text":"Ma i la’u auauna o Almon Babbit, e tele mea ua Ou lē fiafia ai i ai; faauta, ua saili o ia e faia lana fautuaga nai lo le fautuaga ua Ou faauuina, le fautuaga lava lea a le Au Peresitene o la’u Ekalesia; ma ua faatuina e ia se tamai povi auro e tapuai i ai lo’u nuu."},{"verse":85,"text":"Ia lē tuua se tagata o lē ua sau iinei e saili e tausi i a’u poloaiga, e alu ese atu mai lenei nofoaga."},{"verse":86,"text":"Afai latou te ola iinei ia tuu atu ia te i latou ia ola ia te a’u; ma afai e maliliu i latou ia tuu atu ia latou maliliu ia te a’u; auā o le a latou malolo mai ia latou galuega uma iinei, ma o le a faaauau pea a latou galuega."},{"verse":87,"text":"O lea, ia tuu atu i la’u auauna o William ia tuu mai lona faatuatuaga ia te a’u, ma tuu le fefe e faatatau i lona aiga, ona o le faama’i o le laueleele. Afai tou te alolofa mai ia te a’u, tausi i a’u poloaiga; ma o le a liua ai le faama’i o le laueleele mo lo outou mamalu."},{"verse":88,"text":"Ia tu’u atu i la’u auauna o William e alu ma folafola atu la’u talalelei tumau e faavavau ma le leo tele, ma le olioli tele, e pei ona o le a musuia ai o ia e lo’u Agaga, i e o nonofo i Warsaw, ma e foi o nonofo i Karefasi, ma e foi o nonofo i Burlington, ma e foi o nonofo i Madison, ma faatalitali ma le onosai ma le filiga mo ni isi faatonuga i la’u konafesi aoao, ua fetalai mai ai le Alii."},{"verse":89,"text":"Afai e faia e ia lo’u loto ia tuu atu ia te ia ia amata atu nei ona faalogo i le fautuaga a la’u auauna o Iosefa, ma lagolago ma ana mea i le tagi a e matitiva, ma faasalalau atu le faaliliuga fou o la’u upu paia i e o nonofo i le lalolagi."},{"verse":90,"text":"Afai e faia e ia lenei mea o le a Ou faamanuiaina o ia i se faatelega o faamanuiaga, o le a lē tuulafoaiina ai o ia, pe maua ai ana fanau i le ’aisi meaai."},{"verse":91,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ia tuu atu i la’u auauna o William ia tofia, faaee i ai le tofi, ma faauu e avea ma fesoasoani i la’u auauna o Iosefa, i le tulaga o la’u auauna o Ailama, ina ia mafai e la’u auauna o Ailama ona ave o le tofi o le Perisitua ma le Peteriaka, lea na tofia ia te ia e lona tamā, e ala i le faamanuiaga ma i le aiā tatau foi;"},{"verse":92,"text":"Ina ia umia e ia mai le taimi nei ki o faamanuiaga faapeteriaka i luga o ulu o lo’u nuu uma,"},{"verse":93,"text":"Ina ia faamanuiaina soo se tasi e faamanuia e ia, ma fetuuina soo se tasi e fetuu e ia; ina ia faamauina i le lagi soo se mea lava e faamauina e ia i le lalolagi; ma o soo se mea lava e tatala e ia i le lalolagi o le a tatalaina i le lagi."},{"verse":94,"text":"Ma ua Ou tofia o ia mai le taimi nei ia avea o ia o se perofeta, ma se tagatavāai, ma se talifaaaliga i la’u ekalesia, faapea foi la’u auauna o Iosefa;"},{"verse":95,"text":"Ina ia galue gatasi foi o ia ma la’u auauna o Iosefa; ma ina ia maua e ia fautuaga mai la’u auauna o Iosefa, o lē o le a ia faaali atu ia te ia ki e mafai ona ole mai ai o ia ma maua ai, ma faapaleina ai i lea lava faamanuiaga, ma le mamalu, ma le viiga, ma le perisitua, ma meaalofa o le perisitua, ia sa tuu atu i se taimi i luga o ia o lē sa avea ma a’u auauna o Oliva Kaotui;"},{"verse":96,"text":"Ina ia mafai e la’u auauna o Ailama ona molimau e uiga i mea o le a Ou faaali atu ia te ia, ina ia manatua lona igoa i le mamalu mai lea tupulaga i lea tupulaga, e faavavau ma faavavau lava."},{"verse":97,"text":"Ia tuu atu foi ia maua e la’u auauna o William Law ki e mafai ona ole mai ai o ia ma maua faamanuiaga; ia tuu atu ia te ia ia faamaualalo i o’u luma, ma ia aunoa ma se faa’ole’ole, ma o le a maua e ia lo’u Agaga, o le Fesoasoani lava, lea o le a faaalia atu ia te ia le moni o mea uma, ma tuu atu ia te ia, i le taimi tonu lava, mea e fai atu ai o ia."},{"verse":98,"text":"Ma o faailoga nei e mulimuli atu ia te ia—o le a faamalolo e ia e mama’i, o le a tutuli i fafo e ia tiapolo, ma o le a laveaiina o ia mai ia i latou o e e tuu atu ia te ia mea oona e oti ai;"},{"verse":99,"text":"Ma o le a taitaia o ia i ala e lē mafai ai e gata uogo ona utia lona mulivae, ma o le a faatupuina ia te ia manatunatuga o ona mafaufauga e pei ua i luga o apaau o aeto."},{"verse":100,"text":"Ma afai Ou te loto e faatu mai e ia sē ua oti, ia tuu atu ia te ia ia lē taofia lona leo."},{"verse":101,"text":"O lea, ia tuu atu i la’u auauna o William e alaga leotele atu ma ia lē taofia, i le olioli ma le fiafia, ma osana ia te ia o lē ua afio i luga o le nofoalii e faavavau faavavau lava, ua fetalai mai ai le Alii lo outou Atua."},{"verse":102,"text":"Faauta, Ou te fai atu ia te outou, ua ia te a’u se misiona o loo faapolopolo mo la’u auauna o William, ma la’u auauna o Ailama, ma mo na o laua lava; ma ia tuu atu i la’u auauna o Iosefa e nofo pea i le aiga, ona ua manaomia o ia. O le vaega o totoe o le a Ou faaali atu ia te outou i se taimi o mulimuli mai. E faapea lava. Amene."},{"verse":103,"text":"O lenei foi, e moni Ou te fai atu ia te outou, afai e fia auauna mai la’u auauna o Sini ia te a’u ma avea ma fesoasoani i la’u auauna o Iosefa, ia tuu atu ia te ia e tulai ma sau i luga ma tu i le tofi o lona valaauga, ma faamaulalo o ia lava i o’u luma."},{"verse":104,"text":"Ma afai e osi mai e ia ia te a’u se taulaga e talia, ma tautinoga, ma nonofo faatasi pea ma lo’u nuu, faauta, o A’u, o le Alii lo outou Atua, o le a Ou faamaloloina o ia o le a malolo ai o ia; ma o le a toe si’itia a’e e ia lona leo i luga o mauga, ma avea o se failauga i luma o o’u mata."},{"verse":105,"text":"Ia tuu atu ia te ia e sau ma faatuina lona aiga i le pitonuu lea ua alaala ai la’u auauna o Iosefa."},{"verse":106,"text":"Ma i ana malaga uma, ia tuu atu ia te ia e siitia a’e i luga lona leo e pei o le leo o se pu, ma lapatai atu i tagata o le lalolagi ia sosola ese mai le toasa o le a oo mai."},{"verse":107,"text":"Ia tuu atu ia te ia e fesoasoani i la’u auauna o Iosefa, ma ia tuu atu foi i la’u auauna o William Law e fesoasoani i la’u auauna o Iosefa, i le faia o se folafolaga aloaia i tupu o le lalolagi, e pei lava ona Ou fai atu ai muamua ia te outou."},{"verse":108,"text":"Afai e fia faia e la’u auauna o Sini lo’u loto, ia lē tuu atu ia te ia e aveese atu lona aiga i laueleele i sasa’e, ae tuu atu ia te ia e sui lo latou nofoaga, e pei lava ona Ou fai atu ai."},{"verse":109,"text":"Faauta, e lē o lo’u loto le saili e ia ia maua le saogalemu ma le malutaga i fafo atu o le aai lea ua Ou tofia atu ia te outou, o le aai lava lea o Navu."},{"verse":110,"text":"E moni Ou te fai atu ia te outou, e oo i le taimi nei, afai e faalogo mai o ia i lo’u leo, o le a lelei o ia. E faapea lava. Amene."},{"verse":111,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ia tuu atu i la’u auauna o Amosa Davies e totogi se saofaga i lima o e ua Ou tofia e fausia se fale e tali ai malo, o le Maota lava lea i Navu."},{"verse":112,"text":"Ia tuu atu ia te ia e fai lenei mea pe afai e manao iai; ma ia tuu atu ia te ia e faalogo i le fautuaga a la’u auauna o Iosefa, ma galue i ona lava lima ina ia maua e ia le faatuatuaga o tagata."},{"verse":113,"text":"Ma a faamaonia e ia o ia lava i le faamaoni i mea uma o le a faatuatua atu i lana tausiga, ioe, o mea itiiti lava, o le a avea o ia ma pule i mea e tele;"},{"verse":114,"text":"O lea ia tuu atu ai ia te ia ia faamaualalo o ia lava ina ia mafai ona faaeaina o ia. E faapea lava. Amene."},{"verse":115,"text":"O lenei foi, e moni Ou te fai atu ia te outou, afai e fia usiusitai la’u auauna o Robert D. Foster i lo’u leo, ia tuu atu ia te ia e fausia se fale mo la’u auauna o Iosefa, e tusa ma le konekarate na faia e ia faatasi ma ia, pe a tatala atu ia te ia le faitotoa mai lea taimi i lea taimi."},{"verse":116,"text":"Ma ia tuu atu ia te ia ia salamo mai ona sese uma, ma faaofu o ia lava i le alofa mama; ma tuu le faia o le mea leaga, ma ia faataatitia ese ana upu faatautala mamafa uma;"},{"verse":117,"text":"Ma ia totogi siea atu foi i lima o le korama o le Maota i Navu, mo ia lava ma ana fanau pe a mavae atu o ia, mai lea tupulaga i lea tupulaga;"},{"verse":118,"text":"Ma faalogo i le fautuaga a a’u auauna o Iosefa, ma Ailama, ma William Law, ma pule ua Ou valaauina e faataatia le faavae o Siona; ma o le a lelei ia te ia e faavavau faavavau lava. E faapea lava. Amene."},{"verse":119,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ia lē tuuina atu i se tagata e totogi siea i le korama o le Maota i Navu vagana ai o ia o se ua talitonu i le Tusi a Mamona, ma faaaliga ua Ou tuu atu ia te outou, ua fetalai mai ai le Alii lo outou Atua;"},{"verse":120,"text":"Ona o se mea e faapei o lenei e sau mai le leaga, ma o le a o mai faatasi ma fetuu ae lē o faamanuiaga, ua fetalai mai ai le Alii lo outou Atua. E faapea lava. Amene."},{"verse":121,"text":"O lenei foi, e moni Ou te fai atu ia te outou, ia tuu atu i le korama o le Maota i Navu ia maua se totogi tatau ai mo a latou galuega uma ua latou faia i le fausiaina o le Maota i Navu; ma ia tuu atu ia faia o latou totogi e tusa ma le mea latou te malilie i ai i totonu o i latou lava, e tusa ma lona tau talafeagai."},{"verse":122,"text":"Ma ia tuu atu i tagata taitoatasi o e e totogi saofaga e ave lana vaega o o latou totogi, pe afai e tatau ai, mo lo latou tausiga, ua fetalai mai ai le Alii; a lē o lea, ia faitauina a latou galuega mo a latou saofaga i lena fale. E faapea lava. Amene."},{"verse":123,"text":"E moni Ou te fai atu ia te outou, Ou te tuu atu nei ia te outou o e mautofi ua i ai i la’u Perisitua, ina ia mafai ona outou umia ona ki, le Perisitua lava lea e tusa ma le faatulagaga a Mekisateko, lea ua tusa ma le faatulagaga a lo’u Atalii Pele e Toatasi."},{"verse":124,"text":"Muamua, Ou te tuu atu ia te outou Ailama Samita e avea o se peteriaka mo outou, e umia faamanuiaga faamau o la’u ekalesia, o le Agaga Paia lava o le folafolaga, lea e faamau ai outou mo le aso o le togiolaina, ina ia outou lē pa’u’ū e ui i le itula o le faaosoosoga atonu e oo mai i o outou luga."},{"verse":125,"text":"Ou te tuu atu ia te outou la’u auauna o Iosefa e avea ma se toeaina pulefaamalumalu i luga o la’u ekalesia atoa, e avea o se faaliliu-upu, o se talifaaaliga, o se tagatavāai, ma se perofeta."},{"verse":126,"text":"Ou te tuu atu ia te ia mo ni fesoasoani o la’u auauna o Sini Rikitone ma la’u auauna o William Law, ina ia avea i latou nei o se korama ma Au Peresitene Sili, e talia faaaliga mo le ekalesia atoa."},{"verse":127,"text":"Ou te tuu atu ia te outou la’u auauna o Brigham Young e avea o se peresitene i luga o le aufono femalagaa’i o le Toasefululua;"},{"verse":128,"text":"O le Toasefululua lea e umia ki e tatala ai le pule o lo’u malo i luga o tulimanu e fa o le lalolagi, ma a mavae lena e auina atu ai la’u upu i tagata taitoatasi."},{"verse":129,"text":"O i latou ia o Heber C. Kimball, Parley P. Pratt, Orson Pratt, Orson Hyde, Viliamu Samita, Ioane Teila, John E. Page, Wilford Woodruff, Willard Richards, Siaosi A. Samita;"},{"verse":130,"text":"O David Patten ua Ou avea mo a’u lava; faauta, o lona perisitua e leai se tagata e avea mai ia te ia; ae, e moni Ou te fai atu ia te outou, e mafai ona tofia se isi i lena lava valaauga."},{"verse":131,"text":"O lenei foi, Ou te fai atu ia te outou, Ou te tuu atu ia te outou se aufono maualuga, mo le maatulimanu o Siona—"},{"verse":132,"text":"O o latou igoa, o Samuel Bent, Henry G. Sherwood, George W. Harris, Charles C. Rich, Thomas Grover, Newel Knight, David Dort, Dunbar Wilson—o Seymour Brunson ua Ou avea mo a’u lava; e leai se tagata e avea lona perisitua, ae e mafai ona tofia se isi i lea lava perisitua i lona tulaga; ma e moni Ou te fai atu ia te outou, ia tuu atu i la’u auauna o Aaron Ioanesone ia faauu i lenei valaauga i lona tulaga—o David Fullmer, Alpheus Cutler, William Huntington."},{"verse":133,"text":"O lenei foi, Ou te tuu ia te outou Don C. Samita e avea o se peresitene i luga o le korama a faitaulaga sili;"},{"verse":134,"text":"O se sauniga lea ua faavaeina mo le faamoemoe o le faaagavaaina o i latou o e o le a tofia e avea ma peresitene nofomau po o ni auauna i luga o siteki eseese ua salalau lautele;"},{"verse":135,"text":"E mafai foi ona latou malaga atu pe a latou filifili i ai, ae ia faauuina mo peresitene nonofomau; o le tofi lea o lo latou valaauga, ua fetalai mai ai le Alii lo outou Atua."},{"verse":136,"text":"Ou te tuu atu ia te ia Amasa Lyman ma Noah Packard mo ni fesoasoani, ina ia latou pulefaamalumalu i luga o le korama a faitaulaga sili o la’u ekalesia, ua fetalai mai ai le Alii."},{"verse":137,"text":"O lenei foi, Ou te fai atu ia te outou, Ou te tuu atu ia te outou o John A. Hicks, Samuel Williams, ma Jesse Baker, o le perisitua lea e pulefaamalumalu i luga o le korama a toeaina, o se korama lea ua faatuina mo faifeau nonofomau; ae ui i lea e mafai ona latou malaga, peitai ua faauuina i latou e avea ma faifeau nonofomau i la’u ekalesia, ua fetalai mai ai le Alii."},{"verse":138,"text":"O lenei foi, Ou te tuu atu ia te outou o Iosefa Young, Josiah Butterfield, Daniel Miles, Henry Herriman, Zera Pulsipher, Levi Hancock, James Foster, e pulefaamalumalu i luga o le korama a fitugafulu;"},{"verse":139,"text":"O se korama lea ua faatuina mo toeaina femalagaai e molimau atu lo’u igoa i le lalolagi atoa, i soo se mea e auina atu i ai i latou e le aufono maualuga femalagaa’i, o a’u aposetolo ia, e saunia se ala i luma o o’u mata."},{"verse":140,"text":"O le eseesega i le va o lenei korama ma le korama a toeaina o le tasi e femalagaa’i e lē aunoa, a’o le isi e pulefaamalumalu i luga o aulotu mai lea taimi i lea taimi; o le tasi ua i ai le tiutetauave o le pulefaamalumalu mai lea taimi i lea taimi, a’o le isi ua leai se tiutetauave ua i ai e pulefaamalumalu ai, ua fetalai mai ai le Alii lo outou Atua."},{"verse":141,"text":"O lenei foi, Ou te fai atu ia te outou, Ou te tuu atu ia te outou Vinson Knight, Samuel H. Samita, ma Shadrach Roundy, pe afai e talia e ia, e pulefaamalumalu i luga o le au epikopo; o se malamalama o lea au epikopo ua ta’ua ua tuu atu ia te outou i le tusi o Mataupu Faavae ma Feagaiga."},{"verse":142,"text":"O lenei foi, Ou te fai atu ia te outou, o Samuel Rolfe ma ona fesoasoani mo ositaulaga, ma le peresitene o aoao ma ona fesoasoani, ma le peresitene foi o tiakono ma ona fesoasoani, ma le peresitene foi o le siteki ma ona fesoasoani."},{"verse":143,"text":"O tofiga o i luga a’e ua Ou tuu ia te outou, ma o latou ki, mo fesoasoani ma mo pulega, mo le galuega o le auaunaga ma le faaatoatoaina o la’u au paia."},{"verse":144,"text":"Ma Ou te tuu atu ia te outou se poloaiga, ia outou faatumuina ia tofiga uma ma pasia igoa na ua Ou tau atu, pe a lē o lea ia lē pasia i latou i la’u konafesi aoao;"},{"verse":145,"text":"Ma e tatau ona outou saunia ni potu mo ia tofi i lo’u fale pe a outou fausiaina i lo’u igoa, ua fetalai mai ai le Alii lo outou Atua. E faapea lava. Amene."}]},{"chapter":125,"verses":[{"verse":1,"text":"O le a le finagalo o le Alii e faatatau i le au paia i le Teritori o Iowa?"},{"verse":2,"text":"E moni, ua faapea ona fetalai mai o le Alii, Ou te fai atu ia te outou, afai e fia faia e i latou o e ua ta’ua i latou e i latou lava i lo’u igoa ma o loo taumafai e avea ma a’u au paia, afai latou te fia faia lo’u loto ma tausi i a’u poloaiga e faatatau ia te i latou, ia tuu atu ia te i latou e faapotopoto faatasi i latou lava i nofoaga o le a Ou tofia mo i latou e ala atu i la’u auauna o Iosefa, ma ati a’e aai i lo’u igoa, ina ia latou saunia mo mea ua faapolopoloina mo se taimi o le a oo mai."},{"verse":3,"text":"Ia tuu atu ia te i latou e fausia se aai i lo’u igoa i luga o le laueleele fesaga’i ma le aai o Navu, ma ia tuu atu le igoa o Sara’emila e faaigoa ai."},{"verse":4,"text":"Ma ia tuu atu ia i latou uma o e e o mai mai sasa’e, ma sisifo, ma matu, ma saute, o e e mananao e nonofo ai i totonu, e ave o latou tofi i lena lava aai, faapea foi i le aai o Nashville, po o i le aai o Navu, ma i siteki uma ua Ou tofia, ua fetalai mai ai le Alii."}]},{"chapter":126,"verses":[{"verse":1,"text":"Le uso pele e ma alofagia tele, o Brigham Young, e moni ua faapea ona fetalai mai o le Alii ia te oe: La’u auauna e Brigham, ua lē toe manaomia mai i lou lima le tuua o lou aiga e pei o taimi ua mavae, ona ua talia ia te a’u lau taulaga."},{"verse":2,"text":"Ua Ou vaai i au galuega ma taumafaiga i malaga mo lo’u igoa."},{"verse":3,"text":"O lea Ou te poloaiina ai oe ia auina atu la’u upu i le lautele mamao, ma tausi faapitoa lelei lou aiga mai le taimi nei, ma le agai i luma ma le faavavau. Amene."}]},{"chapter":127,"verses":[{"verse":1,"text":"Talu ai ona ua faaali mai e le Alii ia te a’u e faatatau i o’u fili, i Misuri ma le Setete lenei, ua latou toe tuli mai ia te a’u; ma talu ai ona ua latou tuli mai ia te a’u e aunoa ma se pogai, ma ua lē i ai sina ata po o se lanu itiiti o le faamasinotonu po o se aiā i la latou itu i le faaosoina o a latou sauaga e faasaga mai ia te a’u; ma talu ai ona o a latou tuua’iga ua faavae uma i le pepelo o le lama silisili ona uliuli, ua ou manatu ai ua tatau ma ua poto ia te a’u ona tuua le alaalafaga mo se vaitau puupuu, mo lo’u lava saogalemu ma le saogalemu o lenei nuu. Ou te fia fai atu ia i latou o e ua ou fai pisinisi faatasi ma i latou, ua ou tuua a’u mea tau pisinisi i sui ma failautusi o e o le a taulimaina pisinisi uma i se ala vave ma tatau, ma o le a vaai ia soloia a’u aitalafu uma i le taimi e tatau ai, i le faamatuu atu lea o meatotino, po o se isi ala, e pei ona tatau ai i se tulaga, pe tusa ai ma tulaga e mafai ai. A oo ina ou iloa ua uma atu le afā, ona ou toe foi mai ai lea ia te outou."},{"verse":2,"text":"Ma o tugā ua valaaulia a’u ou te ala atu ai, e peiseai ua nao se mea faatauvaa ia mea ia te a’u, ona o le lotovale ma le ita o tagata ua avea ma o’u tulaga masani i aso uma o lo’u olaga; ma o le a se pogai e foliga mai ai o se mealilo lea, vagana ai na faauuina a’u a o le’i faavaeina le lalolagi mo se faamoemoe lelei, pe leaga, e pei ona outou filifili e ta’u ai. Ia outou faamasino mo outou lava. Ua silafia e le Atua ia mea uma, pe lelei pe leaga. Ae e ui i lea, o le vai loloto o le mea lea ua masani ona ou aau ai. Ua avea ia mea uma ma uiga masani ia te a’u; ma ua ou lagona, e pei o Paulo, e olioli i puapuaga; ona ua laveaiina a’u i fafo e le Atua o o’u tamā mai nei puapuaga uma e oo mai i le aso nei, ma o le a ia laveaiina a’u mai le taimi nei ma le agai i luma; aua faauta, ma taga’i, o le a ou manumalo i o’u fili uma, aua ua fetalai mai ai le Alii le Atua."},{"verse":3,"text":"O lea, ia tuu atu i le au paia uma ia olioli, ma fiafia tele; aua o le Atua o Isaraelu o lo latou Atua, ma o le a tuuina mai e ia se taui totogi faamasinotonu i luga o ulu o tagata uma ua faasauā ia te i latou."},{"verse":4,"text":"O lenei foi, e moni ua faapea ona fetalai mai o le Alii: Ia tuu atu le galuega o lo’u malumalu, ma galuega uma ua Ou tofia ia te outou, ia faia pea ma lē taofia; ma ia tuu atu lo outou filiga, ma lo outou maelega, ma le onosai, ma a outou galuega ia toe faaluaina, ma o le a leai se ala e aveesea ai lo outou taui, ua fetalai mai ai le Alii o ’Au. Ma afai latou te sauaina outou, sa faapea foi ona latou sauaina perofeta ma tagata amiotonu o e na muamua ia te outou. Ua i ai se taui mo nei mea uma i le lagi."},{"verse":5,"text":"O lenei foi, Ou te tuu atu ia te outou se upu e faatatau i le papatisoga mo o outou tagata maliliu."},{"verse":6,"text":"E moni, ua faapea ona fetalai mai o le Alii ia te outou e faatatau i o outou tagata maliliu: A papatiso soo se tasi o outou mo o outou tagata maliliu, ia tuu atu ia i ai se tusitalafaamaumau, ma ia tuu atu ia avea o ia o se molimau-vaai o a outou papatisoga; ia tuu atu ia te ia e faalogo i ona taliga, ina ia mafai ona molimau o ia i le moni, ua fetalai mai ai le Alii;"},{"verse":7,"text":"Ina ia tusifaamaumauina i le lagi a outou faamaumauga uma; soo se mea tou te faamauina i le lalolagi, e mafai ona faamauina i le lagi; soo se mea tou te tatalaina i le lalolagi, e mafai ona tatalaina i le lagi;"},{"verse":8,"text":"Aua ua lata ona Ou toefuatai atu mea e tele i le lalolagi, e faatatau i le perisitua, ua fetalai mai ai le Alii o ’Au."},{"verse":9,"text":"O lenei foi, ia tuu atu ia faatulaga tatau talafaamaumau uma, ina ia mafai ona tuu o i latou i potutusi faamaumau o lo’u malumalu paia, e taofi ai ia manatua mai lea tupulaga i lea tupulaga, ua fetalai mai ai le Alii o ’Au."},{"verse":10,"text":"Ou te fia fai atu i le au paia uma, sa ou manao, ma le naunau tele lava, e tautala atu ia te i latou mai le pulelaa e faatatau i le mataupu o le papatisoga mo e ua maliliu, i le Sapati e sosoo ai. Ae talu ai ona ua lē i ai i la’u pule le faia o lena mea, o le a ou tusia le afioga a le Alii e faatatau i lena mataupu, mai lea taimi i lea taimi, ma auina atu ia te outou i le meli, faapea foi ma le tele o isi mea."},{"verse":11,"text":"Ou te faai’u nei la’u tusi mo le taimi nei, ona ua leai se taimi tele; aua ua lamalama vaavaai le fili, ma e pei ona fetalai le Faaola, ua sau le alii o lenei lalolagi, ae ua leai sana mea o i totonu ia te a’u."},{"verse":12,"text":"Faauta, o la’u tatalo i le Atua, ia faaolaina outou uma. Ma ou te saini a’u lava o la outou auauna i le Alii, o le perofeta ma le tagatavāai O Le Ekalesia a Iesu Keriso o le Au Paia o Aso e Gata Ai."},{"verse":13,"text":"Iosefa Samita."}]},{"chapter":128,"verses":[{"verse":1,"text":"E pei ona ou fai atu ia te outou i la’u tusi ae ou te lei tuua lo’u fale, o le a ou tusi atu ia te outou mai lea taimi i lea taimi ma tuu atu ia te outou faamatalaga e faatatau i mataupu e tele, o lea ou te toe faaauau ai le mataupu o le papatisoga mo e ua maliliu, ona e peiseai ua i ai pea lena mataupu i lo’u mafaufau, ma uuna’i malosi mai e sili atu i o’u lagona, talu mai ona tuli o a’u e o’u fili."},{"verse":2,"text":"Sa ou tusi atu ia te outou ni upu itiiti o le faaaliga e faatatau i se tusitalafaamaumau. Ua ou maua ni nai vaaiga faaopoopo e faatatau i lenei mataupu, ia o le a ou faamaonia nei. O lena mea, sa ta’u atu i la’u tusi muamua e tatau ona i ai se tusitalafaamaumau, o lē e tatau ona molimau-vaai, ma faalogo foi i ona taliga, ina ia mafai ona faia e ia se talafaamaumau moni i luma o le Alii."},{"verse":3,"text":"O lenei, e faatatau i lenei mataupu, e faigata tele i se tusitalafaamaumau e toatasi ona i ai i taimi uma, ma faia le galuega uma. Ina ia fo’ia lenei faigata, e mafai ona tofia se tusitalafaamaumau i uarota taitasi o le aai, o sē ua agavaa lelei i le tusiga sa’o o tala; ma ia tuu atu ia te ia ia matua auiliili ma sa’o tonu i le tusiga o taualumaga atoa, ma faamaonia i lana talafaamaumau sa vaai o ia i ona mata, ma faalogo i ona taliga, ma tusia le aso, ma igoa, ma isi mea faapena, ma le talafaasolopito o le mea atoa na fai; ma ta’u mai foi igoa o ni tagata se toatolu e i ai, pe afai e i ai ni isi, o e e mafai ona faamaonia lea lava mea i soo se taimi pe a valaau atu i ai, ina ia mafai ona faamautuina o upu uma e ala i fofoga o ni molimau e toalua pe toatolu."},{"verse":4,"text":"Ona, tuu atu lea i ai o se tusitalafaamaumau aoao, o lē e mafai ona tuulima atu i ai isi talafaamaumau ia, ua o faatasi ma tusifaamaonia i luga o a latou lava saini, e faamaonia ai o le talafaamaumau ua latou faia ua moni. Ona mafai lea e le tusitalafaamaumau aoao o le ekalesia ona tusia le talafaamaumau i le tusi aoao a le ekalesia, faatasi ma tusifaamaonia ma molimau uma na auai, faatasi ma lana lava faamatalaga ua talitonu moni lava o ia o faamatalaga ma talafaamaumau ua ta’ua i luga, ua moni, mai lona malamalama i le uiga lautele ma le tofiga o ia alii e le ekalesia. Ma a uma ona faia o lenei mea i le tusi aoao a le ekalesia, o le a faapea lava ona paia o le talafaamaumau, ma tali ai le sauniga e pei lava na vaai i ai o ia i ona mata ma faalogo i ai i ona taliga, ma fai se talafaamaumau o lea lava sauniga i le tusi aoao o le ekalesia."},{"verse":5,"text":"Atonu tou te manatu ua auiliili tele lenei faatulagaga o mea; ae tuu mai ou te ta’u atu ia te outou ua na o se mea e tali atu ai i le finagalo o le Atua, i le mulimuli lea i le sauniga ma le sauniuniga na faauu ma saunia e le Alii a o le’i faavaeina le lalolagi, mo le faaolataga o e ua maliliu, o e e maliliu e aunoa ma se malamalama o le talalelei."},{"verse":6,"text":"O lenei foi, ou te manao ia outou manatua sa mafaufauina e Ioane le Talifaaaliga lenei lava mataupu e faatatau i e ua maliliu; ina ua fetalai mai o ia, e pei o le a outou maua ua tusifaamaumauina i le Faaaliga 20:12: Ma na ou vaai i e na oti, o e faatauvaa ma e ta’uta’ua, o tutulai i luma o le Atua; ma sa fofola tusi; ma sa fofola se tasi tusi, o le tusi lea o le ola; ma sa faamasinoina e na oti i mea na tusia i tusi, e tusa ma a latou galuega."},{"verse":7,"text":"O le a outou iloa i lenei upusii sa tatalaina tusi; ma sa tatalaina se isi tusi, o le tusi o le ola lea; ae sa faamasinoina e ua maliliu i mea sa tusia i tusi, e tusa ma a latou galuega; o lea, o tusi ua ta’ua atonu o tusi ia ua i ai talafaamaumau o a latou galuega, ma ua faasino i talafaamaumau ua tausia i le lalolagi. Ma o le tusi sa ta’ua o le tusi o le ola o le talafaamaumau lea ua tausia i le lagi; o le mataupu autu lea ua o gatasi tonu ma le mataupu faavae ua poloaiina ai outou i le faaaliga o loo i ai i le tusi na ou tusi atu ia te outou ae ou te lei tuua lo’u fale—ina ia mafai ia outou faamaumauga uma ona tusifaamaumauina i le lagi."},{"verse":8,"text":"O lenei, o le uiga o lenei sauniga, ua i ai i le mana o le perisitua, e ala i le faaaliga a Iesu Keriso, lea ua tuu mai ai i totonu e faapea o soo se mea tou te faamauina i le lalolagi o le a faamauina foi lea i le lagi, ma o soo se mea tou te tatalaina i le lalolagi o le a tatalaina foi lea i le lagi. Po o, le faapea, i le ave lea o se vaaiga ese mai o le faaliliuga, o soo se mea tou te tusifaamaumauina i le lalolagi o le a tusifaamaumauina i le lagi, ma o soo se mea tou te lē tusifaamaumauina i le lalolagi o le a lē tusifaamaumauina foi i le lagi; aua o le a faamasino ai o outou tagata maliliu mai i tusi, e tusa ma a latou lava galuega, pe na faia e i latou lava sauniga i o latou lava propria persona, pe ala i ni o latou lava sui, e tusa ma le sauniga na saunia e le Atua mo lo latou faaolataga a o le i faavaeina le lalolagi, e tusa ma talafaamaumau sa latou tausia e faatatau i o latou tagata maliliu."},{"verse":9,"text":"Atonu e foliga i ni isi o se mataupu faavae faasausili tele ua tatou tautala i ai—o se mana lea e faamaumau pe fusia ai i le lalolagi ma fusia ai i le lagi. Ae ui i lea, i vaitausaga uma o le lalolagi, soo se taimi na tuu mai ai e le Alii se tisipenisione o le perisitua i soo se alii e ala i faaaliga moni, po o i soo se vaega o alii, sa tuuina mai lenei mana i taimi uma. O lea, soo se mea na faia e na alii i le pule, i le suafa o le Alii, ma faia tonu ma le faamaoni, ma tausia se talafaamaumau tatau ai ma faamaoni o lea lava mea, sa avea o se tulafono i le lalolagi ma i le lagi, ma sa lē mafai ona solofuaina, e tusa ma poloaiga a le Ieova silisili. O se upu faamaoni lenei. O ai e mafai ona faalogo i ai?"},{"verse":10,"text":"O lenei foi, mo se faataitaiga, le Mataio 16:18, 19: Ma Ou te fai atu foi ia te oe, o Peteru oe, ma Ou te ati a’e la’u ekalesia i luga o lenei papa, ma e lē mafai e faitotoa o seoli ona manumalo faasaga i ai. Ma Ou te tuu atu ia te oe ki o le malo o le lagi: ma o soo se mea e te faamauina i le lalolagi, o le a faamauina foi lea i le lagi; ma o soo se mea e te tālā i le lalolagi, o le a tatalaina foi lea i le lagi."},{"verse":11,"text":"O lenei o le mealilo tele ma sili o le mataupu atoa, ma le summum bonum o le mataupu atoa ua taatia nei i o tatou luma, ua i ai lea i le mauaina o mana o le Perisitua Paia. Ona o ia e tuu atu i ai ia ki e leai se faigata e i ai i le mauaina o le malamalama o mea moni e faatatau i le faaolataga o le fanauga a tagata, e faatatau uma mo e ua maliliu faapea ma mo e o ola."},{"verse":12,"text":"O totonu o iinei ua i ai le mamalu ma le viiga, ma le tino ola pea ma le ola e faavavau—O le sauniga o le papatisoga i le vai, ia faatofuina ai ina ia o gatasi ma le faatusa o le maliu, ina ia o gatasi le tasi mataupu autu ma le isi; o le faatofuina i le vai ma le alu a’e mai le vai ua faatusa i le toetutu mai o e ua maliliu i le o mai i fafo mai o latou tuugamau; o lea na faatuina ai lenei sauniga e fai ai se sootaga ma le sauniga o le papatisoga mo e ua maliliu, aua ua faatusa lea i e ua maliliu."},{"verse":13,"text":"O lea, na faatuina ai le faatanoa o le vai papatisoga o se faatusa o le tuugamau, ma na poloaiina ai ia tuu i se mea i lalo i le mea e masani ona potopoto ai e o ola, e faailoa atu ai e o ola ma e ua oti, ma ina ia i ai i mea uma so latou faatusa, ma ina ia o gatasi ma le tasi—o mea faalelalolagi ua o gatasi ma mea faalelagi, e pei ona ta’u mai e Paulo, i le 1 Korinito 15:46, 47, ma le 48:"},{"verse":14,"text":"Ae peitai e le muamua le faaleagaga, a o le faaletino; ona mulimuli ai lea o le faaleagaga. E faaleeleele le uluai tagata, na fua mai i le eleele; a o le tagata mulimuli, o le Alii lea mai le lagi. Pei o lē faaleeleele, e faapea lava o e faaleeleele; pei o lē faalelagi, e faapea lava o e faalelagi. Ma e faapei o talafaamaumau ua i ai i le lalolagi e faatatau i o outou tagata maliliu, ua tonu ona faia, ua faapea foi ona i ai o talafaamaumau i le lagi. O lenei, la, o le mana faamau ma faamauina lea, ma, i se tasi uiga o le upu, o ki ia o le malo, ia ua i ai le ki o le malamalama."},{"verse":15,"text":"Ma o lenei, o’u uso e, ma tuafafine pele e ma alofaina, tuu mai ia te a’u e tauina atu ia te outou o mataupu autu nei e faatatau i e ua maliliu ma e o ola e lē mafai ona tatou manatu māmā i ai, e faatatau i lo tatou olataga. Ona o lo latou faaolataga ua tatau ma taua tele mo lo tatou olataga, e pei ona faimai Paulo e faatatau i tamā—e faapea e lē mafai ona faaatoatoaina o i latou e aunoa ma i tatou—pe mafai foi ona faaatoatoaina i tatou e aunoa ma o tatou tagata maliliu."},{"verse":16,"text":"Ma o lenei, e faatatau i le papatisoga mo e ua maliliu, o le a ou tuu atu ia te outou ni isi upusii a Paulo, i le 1 Korinito 15:29: A faapea, pe faapefea e ua papatisoina ma sui o e ua oti? Afai e moni, e le toe tutu e ua oti, ona o le a ea ua papatisoina ai i latou ma sui o e ua oti?"},{"verse":17,"text":"O lenei foi, e faaopoopo i lenei upusii ou te tuu atu ai ia te outou se upusii mai se tasi o perofeta, o lē sa silasila toto’a lona fofoga i le toefuataiga o le perisitua, mamalu o le a faaali mai i aso e gata ai, ma i se ala faapitoa i lenei mataupu sili ona mamalu o mataupu uma o le talalelei tumau e faavavau, ua ta’ua, o le papatisoga mo e ua maliliu; aua ua fai mai Malaki, mataupu mulimuli, fuaiupu 5 ma le 6: Faauta, Ou te auina atu ia te outou Elia le perofeta ae lei oo mai le aso tele ma le mata’utia o le Alii. Ma o le a liliu e ia le loto o tamā i fanau, ma le loto o fanau i o latou tamā, ne’i Ou alu atu ma taia le lalolagi i se fetuu."},{"verse":18,"text":"Atonu e mafai ona ou faia se faaliliuga e sili atu ona manino i lo lea, ae ua lava le manino ua i ai i le tulaga ua i ai nei e talafeagai ma lo’u faamoemoe. Ua lava ona iloa, i le tulaga lenei, o le a taia le lalolagi i se fetuu vagana ua i ai se ituaiga o sooga mau po o se isi mea i le va o tamā ma fanau, i luga o se mataupu po o se isi mea—ma faauta o le a lena mataupu? O le papatisoga lea mo e ua oti. Ona o i tatou e aunoa ma i latou e lē mafai ona faaatoatoaina; pe mafai foi ona faaatoatoaina i latou e aunoa ma i tatou. Pe mafai foi ona faaatoatoaina i latou po o i tatou e aunoa ma i latou o e na maliliu foi i le talalelei; aua e tatau i le aumaia o le tisipenisione o le atoatoaga o taimi, le tisipenisione lea ua amata nei ona aumai, ona faia o se tuufaatasiga atoa ma o’oo’o ma atoatoa, ma se sooga mau faatasi o tisipenisione, ma ki, ma mana, ma mamalu, ma faaali mai e amata mai i aso o Atamu e oo mai lava i le taimi nei. Ma ua lē gata i lenei, ae o mea na sa lei faaalia mai lava mai le faavaega o le lalolagi, ae sa tausi natia mai i e popoto ma mafaufau, o le a faaalia i tamameamea ma fesusui, i le tisipenisione lenei o le atoaga o taimi."},{"verse":19,"text":"O lenei, o le a le mea ua tatou faalogo i ai i le talalelei ua tatou maua? O se leo o le fiafia! O se leo o le alofa mutimutivale mai le lagi; ma o se leo o le ’upumoni mai le eleele; o tala fiafia mo e ua oti; o se leo o le fiafia mo e o ola ma e ua oti; o tala fiafia o le olioli tele. E matua matagofie i luga o mauga vae o i latou o e e aumaia tala fiafia o mea lelei, ma fai mai ia Siona: Faauta, ua nofotupu lou Atua! E pei o le sau o Karamelu, o le a faapena ona alu ifo o le malamalama o le Atua i o latou luga!"},{"verse":20,"text":"O lenei foi, o le a le mea ua tatou faalogoina? O tala fiafia mai Kumora! O Moronae, o se agelu mai le lagi, ua folafola mai le faataunuuga o perofeta—o le tusi o le a faaali mai. O le siufofoga o le Alii i le vao o Feiete, itumalo o Seneka, ua folafola mai molimau e toatolu e molimau i le tusi! O le siufofoga o Mekaeli i auvai o le Susquehanna, na iloa ai le tiapolo ina ua faali mai o ia e pei o se agelu o le malamalama! O le siufofoga o Peteru, Iakopo, ma Ioane i le vao i le va o Haramoni, i le itumalo o Susquehanna, ma Colesville, i le itumalo o Broome, i luga o le vaitafe o Susquehanna, ua ta’u mai o i latou lava ua i ai ki o le malo, ma le tisipenisione o le atoaga o taimi!"},{"verse":21,"text":"O lenei foi, o le siufofoga o le Atua i le potu o le Tamā matua o Uitimera, i Feiete, i le itumalo o Seneka, ma i taimi eseese, ma i nofoaga eseese i malaga ma puapuagatia uma o lenei Ekalesia a Iesu Keriso o le Au Paia o Aso e Gata Ai! Ma le siufofoga o Mekaeli, le agelu sili; o le siufofoga o Kaperielu, ma Refaelu, ma agelu eseese, mai ia Mekaeli po o Atamu e oo mai i le taimi nei, ua latou tautino uma mai a latou tisipenisione, a latou aiā, a latou ki, o latou mamalu, o latou maluali’i ma viiga, ma le mana o lo latou perisitua; ua tuu mai lea fasifuaitau i lea fasifuatau, o lea mataupu i lea mataupu; o si mea itiiti i ’i, ma si mea itiiti i ’o; ua tuu mai ai ia te i tatou le faamafanafanaga i le folafola atu o mea o le a oo mai, ua faamautu ai lo tatou faamoemoe!"},{"verse":22,"text":"Uso e, tatou te lē o atu pea ea i lenei savali sili? O atu i luma ae lē o le solomuli. Lototetele, uso e; o atu pea, o atu pea i le manumalo! Ia olioli o outou loto, ma ia fiafia tele. Tuu atu i le lalolagi e alalaga i pesega. Tuu atu i e ua oti e tautala mai i viiga e faavavau i le Tupu o Emanuelu, o lē na faauuina, ae lei i ai le lalolagi, le mea e mafai ai e i tatou ona togiolaina i latou i fafo mai lo latou falepuipui; ona o le a faasaolotoina pagota."},{"verse":23,"text":"Ia tuu atu i mauga e alalaga i le olioli, ma o outou o vanu uma ia alalaga leo tetele; ma outou o sami ma laueleele matutu uma ia ta’uta’u atu mea ofoofogia a lo outou Tupu Faavavau! Ma o outou o vaitafe, ma alia, ma vai iti, ia tafe atu i lalo ma le fiafia. Ia tuu atu i vao ma laau uma o le fanua ia viia le Alii; ma outou o papa ’alā ia fetagisi i le olioli! Ma ia tuu atu i le la, le masina, ma fetu o le taeao ia pepese faatasi, ma ia tuu atu i atalii uma o le Atua ia alalaga i le olioli! Ma ia tuu atu i foafoaga faavavau e tautino atu lona suafa e faavavau ma faavavau lava! Ma ou te toe fai atu, ua matua mamalu lava le siufofoga ua tatou faalogoina mai le lagi, ua folafola mai i o tatou taliga, le mamalu, ma le faaolataga, ma le viiga, ma le tino ola pea, ma le ola e faavavau; o malo, ma itumalo, ma mana!"},{"verse":24,"text":"Faauta, ua oo mai lava le aso tele o le Alii; ma o ai e mafai ona gafatiaina le aso o lona afio mai, o ai e mafai ona tulai pe a afio mai o ia? Aua ua pei o ia o le afi a le tunu auro, ma pei o le moli a le ta’ofu; ma o le a nofo o ia e pei o se faalelei ma faamamā ario, ma o le a faamamā e ia atalii o Levi, ma faamamā i latou e pei o le auro ma le ario, ina ia mafai ona latou osi atu i le Alii se taulaga i le amiotonu. O lea, ia tatou osi atu, o se ekalesia ma se nuu, ma se Au Paia o Aso e Gata Ai, se taulaga i le Alii i le amiotonu; ma ia tatou tuu atu i lona malumalu paia, pe a uma, se tusi ua i ai talafaamaumau o o tatou tagata maliliu, lea o le a agavaa mo le taliaina atoatoa."},{"verse":25,"text":"Uso e, ua ia te a’u ni mea e tele e fai atu ia te outou e uiga i le mataupu; ae o le a faai’u mo le taimi nei, ma faaauau le mataupu i se isi taimi. O a’u, e pei lava o taimi uma, o la outou auauna lotomaualalo ma se uo e lē masuia lava."},{"verse":26,"text":"Iosefa Samita."}]},{"chapter":129,"verses":[{"verse":1,"text":"E i ai ni ituaiga e lua o tagata i le lagi, ua ta’ua: O agelu, o e o ni peresona toetutu, ua i ai ni tino o aano ma ivi—"},{"verse":2,"text":"Mo se faataitaiga, na fetalai Iesu: Tagotago mai ia te a’u ma vaai, ona o se agaga e leai ni aano ma ni ivi, e pei ona outou vaai mai ua ia te a’u."},{"verse":3,"text":"Lua: O agaga o tagata amiotonu ua faaatoatoaina, i latou ia o e e le’i toetutu mai, ae ua mauaina lea lava mamalu e tasi."},{"verse":4,"text":"A sau se avefeau ma fai mai ua ia te ia se savali mai le Atua, tuu atu ia te ia lou lima ma talosaga atu ia te ia e faatalofa ma oe."},{"verse":5,"text":"Afai o ia o se agelu o le a faia faapea e ia, ma o le a e lagona lona lima."},{"verse":6,"text":"Ae afai o ia o le agaga o se tagata amiotonu ua faaatoatoaina o le a sau o ia i lona mamalu; ona ua pau lena o le ala e mafai ona faaali mai ai o ia—"},{"verse":7,"text":"Fesili atu ia te ia e faatalofa ma oe, ae o le a lē gaioi, ona ua lē tusa ai ma le tulafono o le lagi mo se tagata amiotonu ia taufaasese; ae o le a tuu mai pea e ia lana savali."},{"verse":8,"text":"Ae afai o le tiapolo ua pei o se agelu o le malamalama, a e fesili atu ia te ia e faatalofa o le a tuu mai e ia lona lima ia te oe, ae o le a e lē lagonaina se mea; o lea o le a mafai ai ona e iloa o ia."},{"verse":9,"text":"O ki autu ia e tolu e mafai ai ona outou iloa pe ua mai le Atua soo se auaunaga."}]},{"chapter":130,"verses":[{"verse":1,"text":"A afio mai le Faaola o le a tatou vaai ia te ia e pei ona i ai o ia. O le a tatou vaai o ia o se tagata e pei o i tatou lava."},{"verse":2,"text":"Ma o lea lava mafutaga ua i ai ia te i tatou iinei o le a i ai ia te i tatou iina, ae o le a na’o na faatasia ma le mamalu e faavavau, o se mamalu e lē o ia i tatou i le taimi nei."},{"verse":3,"text":"Ioane 14:23—O le faaali mai o le Tamā ma le Alo, i le fuaiupu lena, o se afifio patino mai lava lea; ma o le manatu e faapea e mau le Tamā ma le Alo i le loto o le tagata, o se manatu tuai faalelotu, ma ua sese."},{"verse":4,"text":"I le tali atu i le fesili—Ua lē tusa ea le faitauga o le taimi a le Atua, taimi a le agelu, taimi a le perofeta, ma le taimi a le tagata ma le paneta ua latou nonofo ai?"},{"verse":5,"text":"Ou te tali atu, Ioe. Peitai e leai ni agelu e auauna mai i le lalolagi lenei vagana ai i latou o e e i ai pe na i ai i le lalolagi lenei."},{"verse":6,"text":"E lē nonofo agelu i se paneta e pei o le lalolagi lenei;"},{"verse":7,"text":"Ae ua nonofo i latou i le afioaga o le Atua, i luga o se kelope ua pei o se sami tioata ma le afi, i le mea o loo faaalia ai mea uma mo lo latou mamalu, o le tuanai, taimi nei, ma le lumanai, ma ua i ai pea lava i luma o le Alii."},{"verse":8,"text":"O le nofoaga ua afio ai le Atua o se Urima ma se Tumena tele lava."},{"verse":9,"text":"O le lalolagi lenei, i lona tulaga faapaiaina ma ola pea, o le a faia e pei o se maatioata ma o le a avea o se Urima ma se Tumena ia te i latou o e e nonofo ai, lea o le a faaalia ai mea uma tau i se malo maualalo, po o malo uma o se faatulagaga maualalo, ia te i latou o e e nonofo ai; ma o le lalolagi lenei o le a ā Keriso ia."},{"verse":10,"text":"Ona avea ai lea o le maa sinasina ua ta’ua i le Faaaliga 2:17, o se Urima ma se Tumena i tagata taitoatasi e mauaina se tasi, lea o le a faailoa mai ai mea uma e faatatau i se faatulagaga o malo maualuluga;"},{"verse":11,"text":"Ma o le a tuuina atu se maa sinasina i tagata taitoatasi o e e o mai i le malo selesitila, lea ua tusia ai i luga se igoa fou, lea e leai se tagata na te iloa vagana ai o ia ua mauaina. O le igoa fou o le upu tatala."},{"verse":12,"text":"Ou te vavalo atu, i le suafa o le Alii le Atua, o le amataga o faigata ia o le a mafua ai le faamasaatoto tele ae lei afio mai le Atalii o le Tagata o le a i Karolaina i Saute."},{"verse":13,"text":"Atonu e tupu mai i le fesili e faatatau i tagata pologa. O lenei mea sa tautino mai e se leo ia te a’u, a’o ou tatalo faatauanau atu e uiga i le mataupu, ia Tesema 25, 1832."},{"verse":14,"text":"Sa ou tatalo faatauanau malosi atu i se tasi taimi e fia iloa le taimi o le afio mai o le Atalii o le Tagata, ae ou faalogoina ai se leo ua toe fetalai mai i upu nei:"},{"verse":15,"text":"Iosefa e, lo’u atalii, afai e te ola seia valusefulu-lima ou tausaga, o le a e vaai i foliga o le Atalii o le Tagata; o lea ia lava ai lea, ma aua le toe faalavelave mai ia te a’u i lenei mataupu."},{"verse":16,"text":"Sa faapea ona tuua ai a’u, e aunoa ma le mafai ona filifili pe ua faasino lenei afio mai i le amataga o le meleniuma po o i se isi afio mai ua mavae atu, pe sei ou oti ma faapea ona vaai ai i ona fofoga."},{"verse":17,"text":"Ou te talitonu o le afio mai o le Atalii o le Tagata o le a lē vave mai nai lo le taimi lena."},{"verse":18,"text":"Soo se mataupu autu o le atamai tatou te maua i le olaga lenei, o le a tutu mai faatasi ma i tatou i le toetutu."},{"verse":19,"text":"Ma afai e maua e se tagata le poto ma le tomai sili atu i le olaga lenei i lo se isi tagata e ala i lona filiga ma le usiusitai, o le a maua e ia le avanoa tele atu i le lalolagi a sau."},{"verse":20,"text":"E i ai se tulafono, na folafola lē maaveesea i le lagi a o le i faavaeina le lalolagi lenei ua faavae ai i luga faamanuiaga uma—"},{"verse":21,"text":"Ma a tatou maua se faamanuiaga mai le Atua, e maua lea i le usiusitai i lena tulafono ua faavae ai i luga."},{"verse":22,"text":"Ua i ai i le Tamā se tino o aano ma ivi e mafai ona pa’i i ai e pei o le tagata; ua faapea foi le Alo; ae o le Agaga Paia e leai se tino o aano ma ivi, ae o se peresona Agaga. A na le faapea, e le mafai e le Agaga Paia ona mau i totonu o i tatou."},{"verse":23,"text":"E mafai e se tagata ona maua le Agaga Paia, ma atonu e mafai ona oo ifo i luga o ia ma lē tumau ia te ia."}]},{"chapter":131,"verses":[{"verse":1,"text":"I le mamalu selesitila o loo i ai ni lagi po o ni tikeri e tolu;"},{"verse":2,"text":"Ma ina ia maua le tikeri aupito maualuga, e ao i se tagata ona ulu atu i le faatulagaga lenei o le perisitua [o lona uiga o le feagaiga fou ma tumau e faavavau o le faaipoipoga];"},{"verse":3,"text":"Ma afai e lē ulu atu i ai o ia, e lē mafai ona maua e ia."},{"verse":4,"text":"E mafai ona ulu atu o ia i le isi malo, ae o le mutaaga lena o lona malo; e lē mafai ona maua e ia se faatelega."},{"verse":5,"text":"(Aso 17 Me, 1843.) O le upu sili atu ona mautinoa o le valoaga o lona uiga o le iloa lea e se tagata ua faamauina o ia mo le ola e faavavau, e ala i faaaliga ma le agaga o valoaga, e ala i le mana o le Perisitua Paia."},{"verse":6,"text":"E lē mafai lava ona faaolaina se tagata i le lē malamalama."},{"verse":7,"text":"E leai se mea e faapea e lē faitino. O le agaga atoa o se mea e faitino, ae ua sili atu ona faaeteete gata pe mamā, ma e na’o mata e sili le mamā e mafai ona vaai i ai;"},{"verse":8,"text":"E lē mafai ona tatou vaai atu i ai; ae a faamamāina o tatou tino o le a tatou vaai o se mea atoa e faitino."}]},{"chapter":132,"verses":[{"verse":1,"text":"E moni, ua faapea ona fetalai mai o le Alii ia te oe la’u auauna, Iosefa, talu ai ona ua e ole mai i lo’u lima ia e iloa ma malamalama pe na faapefea ona ta’uamiotonuina e A’u, o le Alii, a’u auauna o Aperaamo, Isaako, ma Iakopo, e pei foi o a’u auauna o Mose, Tavita ma Solomona, e faatatau i le mataupu autu ma le mataupu faavae o lo latou faia o avā ma palake e toatele—"},{"verse":2,"text":"Faauta, ma tagai, o A’u o le Alii lou Atua, ma o le a ou tali atu ia te oe e uiga i lenei mataupu."},{"verse":3,"text":"O lea, ia saunia lou loto e talia ma usiusitai i faatonuga o le a Ou tuu atu ia te oe; ona o i latou uma o e e faaali atu ia te i latou lenei tulafono e ao ina usiusitai i lea lava."},{"verse":4,"text":"Aua faauta, Ou te faaali atu ia te outou se feagaiga fou ma tumau e faavavau; afai tou te lē ola ai i lena feagaiga, ona tausalaina lea o outou; aua e leai se tasi e mafai ona teena lenei feagaiga ma faatagaina e ulu mai i lo’u mamalu."},{"verse":5,"text":"Aua o i latou uma o e e fia mauaina se faamanuiaga i lo’u lima ia ola ai i le tulafono na tofia mo lena faamanuiaga, ma ona tulaga, e pei ona sa faatutuina mai a o le i faavaeina le lalolagi."},{"verse":6,"text":"Ma e faatatau i le feagaiga fou ma tumau e faavavau, sa faatuina mo le atoatoaga o lo’u mamalu; ma o ia o lē e mauaina lona atoatoaga e ao ma tatau ona ola ai i le tulafono, po o le a tausalaina o ia, ua fetalai mai ai le Alii le Atua."},{"verse":7,"text":"Ma e moni Ou te fai atu ia te outou, o tuutuuga o lenei tulafono e faapea: O feagaiga, maliega, ioega, tautinoga, tautoga, folafolaga, tu, sootaga, mafutaga, po o faamoemoega uma, e lē faia ma osia ma faamauina i le Agaga Paia o le folafolaga, e ia o lē ua faauuina, mo le taimi nei ma mo le faavavau atoa, ma lena foi ua sili ona paia, i le faaaliga ma le poloaiga e ala i lē ua ou faauuina, o lē ua Ou tofia i le lalolagi e umia lenei mana (ma ua Ou tofia i la’u auauna o Iosefa e umia lenei mana i aso e gata ai, ma e lē sili atu lava i le toatasi lē e i le lalolagi e faaee atu i ai lenei mana ma ki o le perisitua i le taimi e tasi), e leai se aoga, āuga, po o se malosi i le toetutu mai ma pe a mavae le toetutu mai le oti; ona o maliega uma e lē faia mo lenei faamoemoe e i ai se iuga pe a oti tagata."},{"verse":8,"text":"Faauta, o lo’u fale o se fale o le maopoopo, ua fetalai mai ai le Alii le Atua, ae lē o se fale o le fenumia’i."},{"verse":9,"text":"Ou te talia ea se taulaga, ua fetalai mai ai le Alii, ua lē faia i lo’u igoa?"},{"verse":10,"text":"Pe Ou te talia mai i o outou lima se mea Ou te lei tofiaina?"},{"verse":11,"text":"Ma Ou te tofi atu ea ia te outou se mea, ua fetalai mai ai le Alii, vagana ai ua ala atu i se tulafono, e pei lava ona faauu atu e A’u ma lo’u Tamā ia te outou, a’o lei i ai le lalolagi?"},{"verse":12,"text":"O A’u o le Alii lou Atua; ma Ou te tuu atu ia te outou le poloaiga lenei—e leai se tagata e sau i le Tamā vagana e ala atu ia te a’u po o i la’u upu, o la’u tulafono lea, ua fetalai mai ai le Alii."},{"verse":13,"text":"Ma o mea uma o i le lalolagi, pe na faauuina e tagata, i nofoalii, po o itumalo, po o mana, po o mea ta’uta’ua, po o a lava na mea, ua lē ala atu ia te a’u po o i la’u upu, ua fetalai mai ai le Alii, o le a lafo i lalo, ma o le a lē tumau pe a mavae ona oti o tagata, pe i le toetutu mai po o le mavae o le toetutu mai, ua fetalai mai ai le Alii lou Atua."},{"verse":14,"text":"Aua soo se mea e tumau e ala atu ia te a’u; ma o soo se mea e lē ala atu ia te a’u o le a luluina ma faaumatia."},{"verse":15,"text":"O lea, afai e faaipoipo e se tane se avā ia te ia i le lalolagi, ma lē faaipoipoina e ia o ia e a’u po o i la’u upu, ma osifeagaiga o ia ma ia a’o i ai pea o ia i le lalolagi ma ia foi faatasi ma ia, e lē aoga la laua feagaiga ma le faaipoipoga pe a oti i laua, ma pe a o ese i laua mai le lalolagi; o lea, e lē noatia i laua i se tulafono pe a o ese i laua mai le lalolagi."},{"verse":16,"text":"O lea, pe a o ese i laua mai le lalolagi, e lē faaipoipo i laua pe tuuina atu i le faaipoipoga; ae o ni agelu tofia i le lagi, o agelu ia o ni auauna galulue, e auauna atu ia te i latou o e ua agavaa mo se fuataga mamao tele atu, ma silisli atu na’uā, ma faavavau, o le mamalu."},{"verse":17,"text":"Ona o nei agelu sa lē ola i la’u tulafono; o lea, e lē mafai ai ona faateleina i latou, ae tumau eseese ma nonofo taitoatasi, e aunoa ma le faaeaga, i lo latou tulaga faaolaina, i le faavavau atoa; ma e mai le taimi lena ma le agai i luma, e lē o ni atua, ae o ni agelu a le Atua e faavavau ma faavavau lava."},{"verse":18,"text":"O lenei foi, e moni Ou te fai atu ia te outou, afai e faaipoipo e se tane se avā, ma osia se feagaiga ma ia mo le taimi nei ma mo le faavavau, afai e lē faia lena feagaiga e a’u po o i la’u upu, o la’u tulafono lea, ma lē faamauina e le Agaga Paia o le folafolaga, e ala atu ia te ia o lē ua Ou faauuina ma tofia i lenei mana, e lē aoga pe taulia pe a o ese i laua mai le lalolagi, ona ua lē faatasia i laua e a’u, ua fetalai mai ai le Alii, pe i la’u upu; a o ese i laua mai le lalolagi e lē mafai ona talia iina, ona ua tofia agelu ma atua iina, o e e lē mafai ona laua pasia; o lea, e lē mafai ona laua maua lo’u mamalu; aua o lo’u fale o se fale o le maopoopo, ua fetalai mai ai le Alii le Atua."},{"verse":19,"text":"O lenei foi, e moni Ou te fai atu ia te outou, afai e faaipoipo se tane i se avā i la’u upu, o la’u tulafono lea, ma i le feagaiga fou ma le tumau e faavavau, ma ua faamauina ia te i laua e le Agaga Paia o le folafolaga, e ia o lē ua faauuina, o lē ua Ou tofia i ai lenei mana ma ki o lenei perisitua; ma o le a fai atu ia te i laua—O le a oulua tutulai mai i le uluai toetutu; ma afai pe a mavae le uluai toetutu, i le toetutu mai e sosoo ai; ma o le a mautofi i nofoalii, malo, itumalo, ma mana, ma puleaga, o mea maualuluga uma ma loloto—ona tusia lea i le Tusi o le Ola a le Tamai Mamoe, e faapea o le a lē faia e ia se fasioti tagata e faamasaa ai le toto lē sala, ma afai e ola i laua i la’u feagaiga, ma lē faia se fasioti tagata e faamasaa ai le toto lē sala, o le a faia ia te i laua i mea uma i soo se mea e tuu atu e la’u auauna i luga o i laua, i le taimi nei, ma i le faavavau atoa; ma o le a taulia atoatoa pe a i ai i laua i fafo o le lalolagi; ma o le a laua pasi atu i agelu ma atua, o e ua faatutu iina, i lo laua faaeaga ma mamalu i mea uma, e pei ona faamauina i luga o o laua ulu, o le mamalu lea o le atoatoaga ma le faaauauina o fanau e faavavau ma faavavau lava."},{"verse":20,"text":"Ona avea ai lea o i laua ma atua, aua ua leai so laua gataaga; o lea o le a i ai i laua mai le faavavau-tumau i le faavavau-tumau, ona ua i ai pea lava i laua; ona avea ai lea o i laua i luga o mea uma, aua ua pule i laua i mea uma. Ona avea ai lea o i laua ma atua, aua ua ia i laua le mana uma, ma o agelu e i lalo o la laua puleaga."},{"verse":21,"text":"E moni, e moni, Ou te fai atu ia te outou, vagana ua outou ola i la’u tulafono e lē mafai ona outou maua lenei mamalu."},{"verse":22,"text":"Aua e vaapiapi le faitotoa, ma lauitiiti le ala e tau i le faaeaga ma le faaauauga o ola, ma e toaitiiti e e i ai e mauaina, ona ua outou lē talia a’u i le lalolagi pe tou te iloa a’u."},{"verse":23,"text":"Ae afai tou te talia a’u i le lalolagi, ona outou iloa lea o a’u, ma maua lo outou faaeaga; ina ia outou i ai foi i le mea Ou te i ai."},{"verse":24,"text":"O ola nei e faavavau—o le iloa lea o le Atua poto ma moni e toatasi, ma Iesu Keriso, o lē na auina mai e ia. O A’u o ia. O lea, ia outou talia la’u tulafono."},{"verse":25,"text":"E vatele le faitotoa, ma lautele le ala e tau i le oti; ma e toatele o i ai e o atu iina, ona ua latou lē talia a’u, pe ua latou ola i la’u tulafono."},{"verse":26,"text":"E moni, e moni, Ou te fai atu ia te outou, afai e faaipoipo e se tane se avā e tusa ma la’u upu, ma ua faamauina i laua e le Agaga Paia o le folafolaga, e tusa ma la’u tofiga, ma faia e le tane po o le avā soo se agasala lava po o se solitulafono e faasaga i le feagaiga fou ma tumau e faavavau, ma ituaiga uma o upuleaga, ma afai la te lē faia se fasioti tagata la te faamasaa ai le toto lē sala, o le a la tutulai mai lava i le uluai toetutu, ma ulu atu i lo laua faaeaga; ae o le a faaumatia i laua i la le tino, ma o le a tuu atu i laua i tu’iga a Satani seia oo i le aso o le togiolaina, ua fetalai mai ai le Alii le Atua."},{"verse":27,"text":"O le upuleaga e faasaga i le Agaga Paia, lea e lē faamagaloina i le lalolagi po o i fafo o le lalolagi, o lo outou faia lea o le fasioti tagata tou te faamasaa ai le toto lē sala, ma outou ioe ai i lo’u oti, ina ua uma ona outou talia o la’u feagaiga fou ma tumau e faavavau, ua fetalai mai ai le Alii le Atua; ma o ia o lē e lē ola i lenei tulafono e leai se ala e mafai ona ulu mai ai i lo’u mamalu, ae o le a tausalaina, ua fetalai mai ai le Alii."},{"verse":28,"text":"O A’u o le Alii lou Atua, ma o le a Ou tuu atu ia te oe le tulafono o la’u Perisitua Paia, e pei ona faauuina e A’u ma lo’u Tamā a’o lei i ai le lalolagi."},{"verse":29,"text":"Na maua e Aperaamo mea uma, soo se mea lava na maua e ia, e ala i le faaaliga ma le poloaiga, i la’u upu, ua fetalai mai ai le Alii, ma ua ulu atu i lona faaeaga ma ua nofo i luga o lona nofoalii."},{"verse":30,"text":"Na maua e Aperaamo folafolaga e faatatau i ana fanau, ma e faatatau i le fua o ona sulugatiti—o lē o ona sulugatiti ua e sau ai, o lona uiga, o la’u auauna o Iosefa—ia sa faamoemoe ia faaauau pea i le umi latou te i ai i le lalolagi; ma e faatatau ia Aperaamo ma ana fanau, o le a faaauau pea ia te i latou i fafo o le lalolagi; o le a faaauau pea i le lalolagi ma i fafo o le lalolagi ona lē mafaitaulia i latou e pei o fetu; pe, afai tou te faitauina le oneone o i luga o le matafaga tou te lē mafai ona faitaulia i latou."},{"verse":31,"text":"O lenei folafolaga ua a outou foi, aua o outou e tupuga mai ia Aperaamo, ma sa faia le folafolaga ia Aperaamo; ma o lenei tulafono ua i ai le faaauauga o galuega a lo’u Tamā, ia ua faamamaluina ai e ia o ia lava."},{"verse":32,"text":"O lea, ia outou o atu, ma fai galuega a Aperaamo; ia outou ulu mai i la’u tulafono ma o le a faaolaina ai outou."},{"verse":33,"text":"Ae afai tou te lē ulu mai i la’u tulafono e lē mafai ona outou maua le folafolaga a lo’u Tamā, lea na faia e ia ia Aperaamo."},{"verse":34,"text":"Sa poloaiina Aperaamo e le Atua, ma sa tuu atu Akara e Sara ia Aperaamo e avea ma ana avā. Ma aisea na fai ai e Sara lena mea? Aua o le tulafono lea; ma sa tutupu mai ia Akara tagata e toatele. O lea, o lenei mea, na faataunuu ai folafolaga, faatasi ma isi mea."},{"verse":35,"text":"O lea, sa i ai ea Aperaamo i lalo o le ta’usalaga? E moni Ou te fai atu ia te outou, E leai; aua o A’u, o le Alii, na poloaiina."},{"verse":36,"text":"Sa poloaiina Aperaamo e osi atu lona atalii o Isaako; ae ui i lea, sa tusia: Aua e te fasioti tagata. E ui i lea, sa lē musu Aperaamo, ma sa faitauina lea mea ia te ia mo le amiotonu."},{"verse":37,"text":"Sa maua e Aperaamo ni palake, ma sa latou fanauina ia te ia ni fanau; ma sa faitauina lea mea ia te ia mo le amiotonu, ona sa tuu atu i latou ia te ia, ma sa ola o ia i la’u tulafono; e pei foi ona sa lei faia e Isaako ma Iakopo ni isi lava mea nai lo mea na poloaiina ai i laua; ma ona sa laua lē faia ni isi lava mea nai lo mea na poloaiina ai i laua, ua ulu atu i laua i a laua faaeaga, e tusa ma folafolaga, ma ua nonofo i luga o nofoalii, ma ua lē o ni agelu ae o ni atua."},{"verse":38,"text":"Sa maua foi e Tavita avā e toatele ma palake, ma a’u auauna foi o Solomona ma Mose, e pei foi o le toatele o isi o a’u auauna, mai le amataga o le foafoaga e oo mai i le taimi nei; ma e leai se mea sa latou agasala ai vagana ai i mea na sa latou lē maua mai ia te a’u."},{"verse":39,"text":"O avā ma palake a Tavita sa tuu atu ia te ia e a’u, i le lima o Natano, la’u auauna, ma isi o perofeta o e na i ai ki o lenei mana; ma sa leai se tasi o ia mea na agasala ai o ia faasaga mai ia te a’u vagana i le tulaga e uiga ia Uria ma lana avā; ma, o lea ua pa’ū ai o ia mai lona faaeaga, ma maua lana vaega; ma o le a lē fai mona tofi i latou i fafo o le lalolagi, ona ua Ou tuuina atu i latou i se isi, ua fetalai mai ai le Alii."},{"verse":40,"text":"O A’u o le Alii lou Atua, ma ua Ou tuu atu ia te oe, la’u auauna, Iosefa, se tofiga, ma toefuatai mea uma. Ole mai i mea e te manao i ai, ma o le a tuu atu ia te oe e tusa ma la’u upu."},{"verse":41,"text":"Ma ona ua e ole mai e uiga i le mulilua, e moni, e moni Ou te fai atu ia te oe, afai e talia e se tane se avā i le feagaiga fou ma tumau e faavavau, ma afai e faatasi le tamaitai ma se isi alii, ma Ou te lei tofiaina ia te ia e ala i le faauuga paia, ua faia e le tamaitai le mulilua ma o le a faaumatia."},{"verse":42,"text":"Afai ua lē i ai le tamaitai i le feagaiga fou ma le tumau e faavavau, ma ua faatasi o ia ma se isi alii, ua faia e le tamaitai le mulilua."},{"verse":43,"text":"Ma afai e faatasi lana tane ma se isi fafine, ma ua i ai le tane i lalo o se folafolaga, ua soli e le tane lana folafolaga ma ua faia e ia le mulilua."},{"verse":44,"text":"Ma afai e lei faia e le tamaitai le mulilua, ae ua mamā ma e lei solia e ia lana folafolaga, ma ua iloa e ia lena mea, ma Ou faaali atu ia te oe, o la’u auauna o Iosefa, lena mea, ona i ai lea ia te oe le mana, e ala i le mana o la’u Perisitua Paia, e ave ai o ia ma tuu atu o ia i le tane e lei mulilua ae ua faamaoni; ona o le a fai lea tane ma pule i mea e tele."},{"verse":45,"text":"Aua ua Ou faaee i luga o oe ki ma le mana o le perisitua, lea ua Ou toefuatai ai mea uma, ma faailoa atu ai ia te oe mea uma i le taimi e tatau ai."},{"verse":46,"text":"Ma e moni, e moni, Ou te fai atu ia te oe, o soo se mea e te faamaufaailogaina i le lalolagi o le a faamaufaailogaina i le lagi; ma o soo se mea e te faamauina i le lalolagi, i lo’u igoa ma i la’u upu, ua fetalai mai ai le Alii, o le a faamauina e faavavau i le lagi; ma o soo se agasala a soo se tasi e te faamagaloina i le lalolagi o le a faamagaloina foi e faavavau i le lagi; ma o soo se agasala a soo se tasi e te taofia pea i le lalolagi o le a taofia pea foi i le lagi."},{"verse":47,"text":"O lenei foi, e moni Ou te fai atu, o soo se tasi e te faamanuiaina o le a Ou faamanuiaina foi, ma o soo se tasi e te fetuuina o le a Ou fetuuina, ua fetalai mai ai le Alii; aua o A’u, o le Alii, o lou Atua."},{"verse":48,"text":"O lenei foi, e moni Ou te fai atu ia te oe, la’u auauna Iosefa, soo se mea e te foai atu i le lalolagi, ma o soo se tasi e te foai atu i ai, soo se isi lava i luga o le lalolagi, e ala i la’u upu ma tusa ai ma la’u tulafono, o le a asia i faamanuiaga ae lē o fetuu, ma faatasi ma lo’u mana, ua fetalai mai ai le Alii, ma o le a aunoa ma le tausalaga i le lalolagi ma i le lagi."},{"verse":49,"text":"Aua o A’u o le Alii lou Atua, ma o le a faatasi ma oe e oo lava i le gataaga o le lalolagi, ma i le faavavau atoa; aua e moni Ou te faamauina i luga o oe lou faaeaga, ma saunia se nofoalii mo oe i le malo o lo’u Tama, faatasi ma Aperaamo lou tamā."},{"verse":50,"text":"Faauta, ua Ou vaai i au taulaga, ma o le a faamagaloina au agasala uma; ua Ou vaai i au taulaga i le usiusitai i mea na Ou ta’u atu ia te oe. O lea, inā alu ia, ma Ou te saunia se ala mo lou sao atu, e pei ona Ou taliaina le taulaga a Aperaamo i lona atalii o Isaako."},{"verse":51,"text":"E moni, Ou te fai atu ia te oe: Ou te tuu atu se poloaiga i la’u auauna tamaitai o Emma Samita, lau avā, o lē na Ou tuu atu ia te oe, ia taofi e ia o ia lava ma ia lē auai i le mea na Ou poloaiina oe e tuu atu ia te ia; aua sa Ou faia lena mea, ua fetalai mai ai le Alii, e tofotofo ai oulua uma, e pei ona sa Ou faia ia Aperaamo, ma ina ia mafai ona Ou tapaina ai se taulaga-mu mai o oulua lima i se feagaiga ma se taulaga-osi."},{"verse":52,"text":"Ma ia tuu atu i la’u auauna tamaitai, o Emma Samita, ia talia i latou uma o e ua tuu atu i la’u auauna o Iosefa, ma o e ua amiomamā ma mamā i o’u luma; ma o e ua lē mamā, ae ua fai mai ua mamā i latou, o le a faaumatia, ua fetalai mai ai le Alii le Atua."},{"verse":53,"text":"Aua o A’u o le Alii lou Atua, ma ia outou usiusitai mai i lo’u leo; ma Ou te tuu atu i la’u auauna o Iosefa ia faia o ia ma pule i mea e tele; ona ua faamaoni o ia i luga o mea itiiti; ma o le a Ou faamalosia o ia mai le taimi nei ma le agai i luma."},{"verse":54,"text":"Ma Ou te poloai atu i la’u auauna tamaitai, o Emma Samita, ia nofo ma pipii atu i la’u auauna o Iosefa, ae lē i se isi lava. Ae afai e lē ola o ia i lenei poloaiga o le a faaumatiaina o ia, ua fetalai mai ai le Alii; aua o A’u o le Alii lou Atua, ma o le a faaumatiaina o ia pe afai e lē ola o ia i la’u tulafono."},{"verse":55,"text":"Ae afai e lē ola o ia i lenei poloaiga, ona faia lea e la’u auauna o Iosefa o mea uma mo ia, e pei lava ona fai mai o ia; ma o le a Ou faamanuiaina o ia ma faateleina o ia ma tuu atu ia te ia taisautua-selau i lenei lalolagi, o tamā ma tinā, o uso ma tuafafine, o fale ma laueleele, o avā ma fanau, ma palealii o ola e faavavau i lalolagi e faavavau."},{"verse":56,"text":"O lenei foi, e moni Ou te fai atu, ia tuu atu i la’u auauna-tamaitai ia faamagalo atu i la’u auauna o Iosefa i ana solitulafono; ona faamagaloina ai lea o ia i ana solitulafono, ia sa solitulafono ai o ia faasaga mai ia te a’u; ma o A’u o le Alii lou Atua, o le a faamanuiaina o ia, ma faateleina o ia, ma faia ia olioli lona loto."},{"verse":57,"text":"O lenei foi, Ou te fai atu, ia lē tuu atu i la’u auauna o Iosefa e tuu ese atu ana meatotino mai ona lima, ne’i sau se fili ma faaumatia o ia; aua ua saili Satani e faaumatia; aua o A’u o le Alii lou Atua, ma o ia o la’u auauna; ma faauta, ma taga’i, ua Ou faatasi ma ia, e pei ona sa Ou i ai ia Aperaamo, lou tamā, e oo lava i lona faaeaga ma lona mamalu."},{"verse":58,"text":"O lenei, e faatatau i le tulafono o le perisitua, e tele mea e faatatau i ai."},{"verse":59,"text":"E moni, afai e valaaulia se tagata e lo’u Tamā, e pei o Arona, i lo’u lava leo, ma ala i le leo o ia o lē na auina mai a’u, ma ua Ou faaeeina o ia i ki o le mana o lenei perisitua, afai e fai e ia se mea i lo’u igoa, ma e tusa ai ma la’u tulafono ma i la’u upu, ma o le a lē faia e ia se agasala, o le a Ou ta’uamiotonuina o ia."},{"verse":60,"text":"O lea, ia lē tuu atu i se tasi, e faitio i la’u auauna o Iosefa; aua o le a Ou tauamiotonuina o ia; ona o le a faia e ia le taulaga ua Ou tapaina mai i ona lima mo ana solitulafono, ua fetalai mai ai le Alii lo outou Atua."},{"verse":61,"text":"O lenei foi, e faatatau i le tulafono o le perisitua—afai e faaipoipo e soo se alii se taupou, ma ua manao e faaipoipo i se isi foi, ma tuu mai e lē na muamua lana faatagaga, ma afai e faaipoipo le alii i le avā lona lua, ma o i laua uma o ni taupou, ma e lei folafola atu i se isi lava alii, ona tauamiotonuina lea o lea alii; e lē mafai ona mulilua lenei alii ona ua tuuina atu i laua ia te ia; ona e lē mafai ona mulilua o ia ma lē ua ā ia ae lē a se isi lava."},{"verse":62,"text":"Ma afai e tuu atu ia te ia ni taupou e toasefulu i lenei tulafono, e lē mafai ona mulilua ai o ia, ona ua ā ia i latou, ma ua tuuina atu i latou ia te ia; o lea ua tauamiotonuina ai o ia."},{"verse":63,"text":"Ae afai e faatasi se tasi po o se isi o taupou e toasefulu ma se isi alii ina ua uma ona faaipoipoina o ia, ua faia e lea taupou le mulilua, ma o le a faaumatia o ia; ona ua tuu atu i latou ia te ia e faateleina ma faatumuina le lalolagi, e tusa ma la’u poloaiga, ma faataunuu le folafolaga na tuuina mai e lo’u Tamā a o le i faavaeina le lalolagi, ma mo lo latou faaeaga i lalolagi e faavavau, ina ia latou fanauina agaga o tagata; ona o totonu o lenei mea e faaauau ai pea le galuega a lo’u Tamā, ina ia faamamaluina o ia."},{"verse":64,"text":"O lenei foi, e moni, e moni, Ou te fai atu ia te outou, afai e i ai se avā i se alii, o lē ua umia ki o lenei mana, ma aoao atu e ia i lana avā le tulafono o la’u perisitua, e faatatau i ia mea, ia talitonu le avā ma auauna ia te ia, po o le a faaumatia o ia, ua fetalai mai ai le Alii lo outou Atua; ona o le a Ou faaumatia o ia; aua o le a Ou faalauteleina lo’u igoa i luga o i latou uma o e talia ma ola i la’u tulafono."},{"verse":65,"text":"O lea, o le a tusa ai ma le tulafono ia te a’u, pe afai e lē talia e le fafine lenei tulafono, le mauaina e le tane o soo se mea o mea uma e tuu atu e A’u, o le Alii lona Atua, ia te ia, ona sa lē talitonu le fafine ma auauna atu i le tane e tusa ai ma la’u upu; ma ona avea ai lea o le fafine ma solitulafono; ma tatala ai le tane mai le tulafono a Sara, o lē sa auauna atu ia Aperaamo e tusa ai ma le tulafono i le taimi ina ua Ou poloaiina Aperaamo e ave Akara e fai ma ana avā."},{"verse":66,"text":"Ma o lenei, e faatatau i lenei tulafono, e moni, e moni, Ou te fai atu ia te oe, o le a Ou faaali atu ni isi mea e tele ia te oe, i se taimi o mulimuli mai; o lea, ia lava ai lea mo le taimi nei. Faauta, o A’u o le Alefa ma le Omeka. Amene."}]},{"chapter":133,"verses":[{"verse":1,"text":"Faalogo mai ia, E outou e tagata o la’u ekalesia, ua fetalai mai ai le Alii lo outou Atua, ma faalogo mai i le afioga a le Alii e faatatau ia te outou—"},{"verse":2,"text":"O le Alii o lē o le a faafuasei ona afio mai i lona malumalu; o le Alii o lē o le a afio ifo i le lalolagi ma se fetuu e faamasino; ioe, i luga o atunuu uma ua faagalo le Atua, ma i luga o tagata lē amioatua uma o i totonu o outou."},{"verse":3,"text":"Auā o le a faaali e ia lona aao paia i mata o atunuu uma, ma o le a vaai tuluiga uma o le lalolagi i le faaolataga a lo latou Atua."},{"verse":4,"text":"O le mea lea, ia outou saunia, ia outou saunia, E lo’u nuu e; ia outou faapaia outou lava; ia outou faapotopoto faatasi, E outou e tagata o la’u ekalesia, i luga o le laueleele o Siona, outou uma ia e lei poloaiina e nonofo pea."},{"verse":5,"text":"Ia outou o ese mai Papelonia. Ia mamā outou o e e tauaveina ipu a le Alii."},{"verse":6,"text":"Talo a outou faapotopotoga mamalu, ma tautala pea lava pea le tasi i le isi. Ma ia tuu atu i tagata taitoatasi e valaau atu i le suafa o le Alii."},{"verse":7,"text":"Ioe, e moni Ou te toe fai atu ia te outou, ua oo mai le taimi ua oo mai ai le siufofoga o le Alii ia te outou: Ia outou o ese mai Papelonia; ia outou faapotopoto i fafo mai atunuu, mai matagi e fa, mai le tasi tuluiga o le lagi i le isi."},{"verse":8,"text":"Auina atu toeaina o la’u ekalesia i atunuu mamao; i motu o le sami; auina atu i laueleele ese; valaau atu i atunuu uma, muamua i Nuuese, ona sosoo lea ma tagata Iutaia."},{"verse":9,"text":"Ma faauta, ma taga’i, o la latou alaga atu lenei, ma le siufofoga o le Alii i tagata uma: Inā outou o atu ia i le laueleele o Siona, ina ia mafai ona faalauteleina tuaoi o lo’u nuu, ma ina ia faamalolosia ona siteki, ma ina ia mafai ona alu atu o Siona i nofoaga o faataamilo ai."},{"verse":10,"text":"Ioe, ia tuu atu le alaga ia alu atu i totonu o tagata uma: Ala mai ia ma tutulai mai ma o atu e faafetaia’i i le Faatoafaiavā; faauta ma taga’i, ua afio mai le Faatoafaiavā; ia outou o atu ia e faafetaia’i ia te ia. Ia saunia outou lava mo le aso tele o le Alii."},{"verse":11,"text":"O lea, ia mataala, aua tou te lē iloa le aso po o le itula."},{"verse":12,"text":"O lea, ia tuu atu ia te i latou, o e o i totonu o Nuuese ia sosola i Siona."},{"verse":13,"text":"Ma ia tuu atu ia te i latou o e o Iuta ia sosola i Ierusalema, i mauga o le maota o le Alii."},{"verse":14,"text":"Ia outou o ese mai totonu o atunuu, mai Papelonia lava, mai le lotolotoi o le amioleaga, o Papelonia faaleagaga lea."},{"verse":15,"text":"Ae e moni, ua faapea ona fetalai mai o le Alii, ia lē faanatinatia la outou solaaga, ae ia tuu atu ia mua’i saunia mea uma i o outou luma; ma o ia o lē e alu, ia lē tuu atu ia te ia e tepa i tua ne’i faafuase’i ona oo mai o le faafanoga i ona luga."},{"verse":16,"text":"Uai mai ia ma faalogo mai, E outou e ua nonofo i le lalolagi. Faalogo mai faatasi, outou toeaina o la’u ekalesia, ma faafofoga i le siufofoga o le Alii; aua ua valaau atu o ia i tagata uma, ma ua poloaiina e ia tagata uma o i soo se mea ia salamo."},{"verse":17,"text":"Aua faauta, ua auina atu e le Alii le Atua le agelu ua alaga atu i le taulotoaiga o le lagi, ua fetalai atu; Ia outou saunia le ala o le Alii, ma faasa’osa’o ona ala, aua ua lata mai le itula o lona afio mai—"},{"verse":18,"text":"Pe a tulai le Tamai Mamoe i luga o le Mauga o Siona, ma se selau ma le fasefulu-fa afe faatasi ma ia, ua tusia i o latou muaulu le suafa o lona Tamā."},{"verse":19,"text":"O le mea lea, ia outou saunia mo le afio mai o le Faatoafaiavā; ia outou o atu ia, ia outou o atu ia e faafetaia’i ia te ia."},{"verse":20,"text":"Aua faauta, o le a tulai o ia i luga o le mauga o Olive, ma i luga o le vasa tele, le loloto tele lea, ma i luga o motu o le sami, ma i luga o le laueleele o Siona."},{"verse":21,"text":"Ma o le a tulei atu e ia lona siufofoga i fafo mai Siona, ma o le a fetalai o ia mai Ierusalema, ma o le a faalogoina lona siufofoga i totonu o tagata uma;"},{"verse":22,"text":"Ma o le a avea o se siufofoga e pei o se leo o vai e tele, ma e pei o le leo o se faititili tele, o le a soloia ai i lalo mauga, ma o le a lē toe maua vanu."},{"verse":23,"text":"O le a poloaiina e ia le loloto tele, ma o le a toe tulia i tua i itu-laueleele i matu, ma o le a avea motu ma laueleele e tasi;"},{"verse":24,"text":"Ma o le laueleele o Ierusalema ma le laueleele o Siona o le a toe faafoi i tua i o laua lava nofoaga, ma o le a avea lava le lalolagi e pei ona sa i ai i aso a’o lei vaevaeina."},{"verse":25,"text":"Ma o le a tulai le Alii, le Faaola lava ia, i le lotolotoi o lona nuu, ma o le a nofotupu i luga o tagata uma."},{"verse":26,"text":"Ma o i latou o e o loo i itu-laueleele i matu o le a manatua i luma o le Alii; ma o le a faalogo o latou perofeta i lona siufofoga, ma o le a latou lē toe taofi i latou lava; ma o le a latou taia papa, ma o le a tafe ifo i lalo le aisa i o latou luma."},{"verse":27,"text":"Ma o le a lafoia se alatele i le totonugalemu o le loloto tele."},{"verse":28,"text":"O o latou fili o le a avea o se vete ia te i latou,"},{"verse":29,"text":"Ma i totonu o toafa naumati o le a sau ai lepa o vai ola; ma o eleele maveve o le a lē toe avea o se laueleele matutu."},{"verse":30,"text":"Ma o le a latou aumai a latou ’oa taua i fanau a Efaraima, o a’u auauna."},{"verse":31,"text":"Ma o le a gatete tuaoi o mauga tumau e faavavau i o latou luma."},{"verse":32,"text":"Ma o iina o le a latou faapa’u’ū ai i lalo ma faapaleina i le mamalu, i Siona lava, e lima o auauna a le Alii, le fanau lava a Efaraima."},{"verse":33,"text":"Ma o le a faatumuina i latou i pese o le olioli tumau e faavavau."},{"verse":34,"text":"Faauta, o le faamanuiaga lea a le Atua tumau e faavavau i luga o ituaiga o Isaraelu, ma le faamanuiaga ’oa tele atu i luga o le ulu o Efaraima ma ana aumea."},{"verse":35,"text":"Ma o i latou foi o le ituaiga o Iuta, pe a mavae lo latou tiga, o le a faapaiaina i le paia i luma o le Alii, e nonofo i ona luma i le ao ma le po, e faavavau ma faavavau lava."},{"verse":36,"text":"Ma o lenei, e moni ua fetalai mai le Alii, ina ia mafai ona iloa ia mea i totonu o outou, E outou e ua nonofo i le lalolagi, na Ou auina atu ai la’u agelu e lele atu i le taulotoaiga o le lagi, ua i ai le talalelei tumau e faavavau, o lē na faaali atu i ni isi ma tuu atu lea talalelei i tagata, o lē o le a faaali atu i le toatele o e ua nonofo i le lalolagi."},{"verse":37,"text":"Ma o lenei talalelei o le a talai atu i atunuu uma, ma ituaiga, ma gagana, ma nuu."},{"verse":38,"text":"Ma o le a o atu auauna a le Atua, ma fai atu ma le leo tele: Ia matata’u i le Atua ma avatu le viiga ia te ia, aua ua oo mai le itula o lana faamasinoga;"},{"verse":39,"text":"Ma ia tapuai atu ia te ia o lē na faia le lagi, ma le lalolagi, ma le sami, ma puna o vai—"},{"verse":40,"text":"Ma valaau atu i le suafa o le Alii i le ao ma le po, fai atu: E, pe a na e saeia le lagi, ma e afio mai i lalo, ina ia solo mai i lalo mauga i ou luma."},{"verse":41,"text":"Ma o le a tali i luga o o latou ulu; ona o luma o le Alii o le a pei o le afi faaliusuavai e mumū, ma e pei o le afi e faapupuna ai le vai."},{"verse":42,"text":"E, le Alii e, o le a e afio ifo e faailoa atu lou suafa i ou fili, ma o le a gatete atunuu uma i ou luma—"},{"verse":43,"text":"A e faia mea mata’utia, o mea latou te lei manatu i ai;"},{"verse":44,"text":"Ioe, a e afio mai i lalo, ma solo i lalo mauga i ou luma, o le a e faafetaia’i ia te ia o lē ua olioli ma faia le amiotonu, o lē ua manatuaina oe i ou ala."},{"verse":45,"text":"Aua talu mai le amataga o le lalolagi e lei faalogo lava tagata pe na lagona i le taliga, pe na vaaia foi e se mata, e ese mai ia te oe, E le Atua e, le silisili o mea ua e saunia mo ia o lē e faatalitali ia te oe."},{"verse":46,"text":"Ma o le a fai ane: O ai lenei ua afio ifo mai le Atua o i le lagi ma la’ei mumu; ioe, mai mea e lei faaalia, ua ofu i ona laei mamalu, ua afio mai i le silisiliese o lona malosi?"},{"verse":47,"text":"Ma o le a fai mai o ia: O A’u o lē e tautala i le amiotonu, ua malosi e faaola."},{"verse":48,"text":"Ma o le Alii o le a mūmū ona ofu, ma o ona la’ei o le a pei o ia o lē e solia le tanoa-vine."},{"verse":49,"text":"Ma o le a matua tele lava le mamalu i ona luma o le a natia ai e le la ona mata i le maasiasi, ma o le a taofi e le masina lona malamalama, ma o le a lia’i ese fetu mai i o latou nofoaga."},{"verse":50,"text":"Ma o le a faalogoina lona siufofoga: Ua Ou solia toatasi le soliga-vine, ma Ou aumai le faamasinoga i luga o lo’u nuu atoa; ma sa leai ni isi sa faatasi ma a’u;"},{"verse":51,"text":"Ma sa Ou solia i latou i lo’u aasa, ma sa Ou soli i luga o i latou i lo’u ita, ma ua Ou sausau o’u ofu i lo latou toto, ma faapisipisia o’u ofu uma; ona o le aso lea o le tauimasui sa i ai i lo’u loto."},{"verse":52,"text":"Ma o lenei ua oo mai le tausaga o a’u togiolaina; ma o le a latou ta’uta’ua le alofa agalelei o lo latou Alii, ma mea uma ua ia faaeeina i o latou luga e tusa ma lona lelei, ma e tusa ma lona alofa agalelei, e faavavau ma faavavau lava."},{"verse":53,"text":"Sa puapuaga o ia i o latou puapuagatia uma. Ma o le agelu mai ona luma na laveaiina i latou; ma o lona alofa, ma o lona loto mafatia, na ia togiolaina ai i latou, ma amo ai i latou, ma tauave ai i latou i aso uma anamua;"},{"verse":54,"text":"Ioe, ma Enoka foi, ma i latou o e na faatasi ma ia; o perofeta o e na muamua ia te ia; ma Noa foi, ma i latou o e na muamua ia te ia; ma Mose foi, ma i latou o e na muamua ia te ia;"},{"verse":55,"text":"Ma e mai ia Mose ia Elia, ma mai ia Elia ia Ioane, o e na faatasi ma Keriso i lona toetu mai, ma le au aposetolo paia, faatasi ma Aperaamo, Isaako ma Iakopo, o le a i ai i luma o le Tamai Mamoe."},{"verse":56,"text":"Ma o le a tatalaina tuugamau o le au paia; ma o le a latou o mai ma tutulai i le itu taumatau o le Tamai Mamoe, pe a tulai o ia i luga o le Mauga o Siona, ma i luga o le aai paia, o le Ierusalema Fou; ma o le a latou lagi le viiga o le Tamai Mamoe, i le ao ma le po e faavavau ma faavavau lava."},{"verse":57,"text":"Ma o le pogai lenei, ina ia mafai ona maua e tagata mamalu sa faamoemoe e faaali mai, na auina mai ai e le Alii le atoatoaga o lana talalelei, lana feagaiga tumau e faavavau, ua talatala atu i le manino ma le faigofie—"},{"verse":58,"text":"E saunia ai e ua vaivai mo mea na o le a oo mai i le lalolagi, ma mo le feau a le Alii i le aso pe a faafememeaiina e e vaivai le au popoto, ma avea ai lē ua laitiiti ma atunuu malosi, ma faia ai e le toalua a laua sefulu o afe o fili ia sosola ese."},{"verse":59,"text":"Ma i mea vaivai o le lalolagi o le a vaevaeesea ai e le Alii atunuu i le mana o lona Agaga."},{"verse":60,"text":"Ma o le pogai lenei na tuu atu ai nei poloaiga; sa poloa’ia ia taofia i latou mai le lalolagi i le aso na tuu atu ai i latou, ae o lenei ia tuuina atu nei i tagata uma—"},{"verse":61,"text":"Ma ua tusa lenei ma le mafaufau ma le finagalo o le Alii, o lē ua pule i tagata uma."},{"verse":62,"text":"Ma o ia o lē e salamo ma faapaiaina o ia lava i luma o le Alii o le a tuuina atu i ai le ola e faavavau."},{"verse":63,"text":"Ma o i latou o e e lē faalogo i le siufofoga o le Alii, o le a faataunuuina i luga o i latou le mea na tusia e le perofeta o Mose, e tatau ona vavae ese i latou mai le nuu."},{"verse":64,"text":"Ma le mea foi na tusia e le perofeta o Malaki: Aua, faauta, e oo mai le aso o le a mu ai e pei o se ogaumu, ma o e uma ua faamaualuluga, ioe, ma e uma ua faia amioleaga, o le a avea ma tagutugutu o saito; ma o le a oo mai le aso o le a susunuina i latou, ua fetalai mai ai le Alii o ’au, o le a lē tuua ai mo i latou se a’a po o se lala."},{"verse":65,"text":"O le mea lea, o le a avea lenei ma tali a le Alii ia te i latou:"},{"verse":66,"text":"I lena aso na Ou alu atu ai i o’u lava, sa leai se tagata sa i totonu o outou sa taliaina a’u, ma sa tulia outou i fafo."},{"verse":67,"text":"Ina ua Ou toe valaau atu sa leai se isi o outou e tali mai; e ui i lea sa lei faapuupuuina lava lo’u lima sa lē mafai ai ona Ou togiola atu, po o lo’u mana e laveai ai."},{"verse":68,"text":"Faauta, o la’u aoaiga Ou te faapa’umātu ai le sami. Ou te faia vaitafe ia avea ma vaomatua; e manogi o latou i’a, ma mamate i le fia inu."},{"verse":69,"text":"Ou te faaofuina le lagi i le pouliuli, ma faia ie talatala mo o latou ufiufi."},{"verse":70,"text":"Ma o lenei mea o le a outou maua mai i lo’u lima—o le a outou taooto i lalo i le faanoanoa."},{"verse":71,"text":"Faauta, ma taga’i, ua leai se tasi e laveaiina outou; aua sa outou lē usiusitai i lo’u leo ina ua Ou valaau atu ia te outou mai le lagi; sa outou lē talitonu i a’u auauna, ma ina ua auina atu i latou ia te outou sa outou lē taliaina i latou."},{"verse":72,"text":"O le mea lea, ua latou faamaufaailogaina ai le molimau ma fusifusia ai le tulafono, ma sa tuuina atu outou i le pouliuli."},{"verse":73,"text":"O i latou nei o le a o ese atu i le pouliuli i fafo, i le mea o i ai le tagitu’i, ma le tagiauē, ma le lilivau o nifo."},{"verse":74,"text":"Faauta o le Alii lo outou Atua ua fetalai mai ai. Amene."}]},{"chapter":134,"verses":[{"verse":1,"text":"Matou te talitonu sa faatutuina e le Atua malo mo le lelei o tagata; ma ua tuu e ia e tali tagata mo a latou mea e fai e faatatau i malo, i le faia o tulafono ma lo latou faatinoga, mo le lelei ma le saogalemu o tagata."},{"verse":2,"text":"Matou te talitonu e leai se malo e mafai ona ola i le fīlemu, vagana ua faia ma faamalosia ituaiga tulafono e mautinoa ai le maua e tagata taitoatasi o le faaaoga saoloto o le lotofuatiaifo, le aiā ma le pulea o meatotino, ma le puipuiga o le ola."},{"verse":3,"text":"Matou te talitonu e tatau ona manaomia e malo uma ni ‘au mautofi ma ni taitai faalemalo e faamalosia tulafono o ia malo; ma e tatau ona sailia ma lagolagoina i le leo o le nuu ituaiga o tagata o le a faatinoina le tulafono, i le tutusa ma le faamasinotonu pe afai o se malo faitele, e sailia ai ma lagolagoina e le leo o tagata, po o le finagalo o le tupu."},{"verse":4,"text":"Matou te talitonu na faatutuina e le Atua mea tau lotu; ma e tali atu tagata ia te ia, ma na’o ia lava, mo lona faaaogaina, vagana ai ua uunaia i latou e o latou manatu faalelotu e faalavelave i aiā ma saolotoga o isi; ae ua matou lē talitonu ua i ai i tulafono faaletagata se aiā e faalavelave ai i le faia o tulafono faaletapuaiga e saisaitia ai le lotofuatiaifo o tagata, pe faatonu ai ala e fai ai tapuaiga faitele pe faaletagata lava ia; ma e faapea e tatau i le taitai faalemalo ona taofi le solitulafono, ae lē pulea le lotofuatiaifo; e tatau ona faasala le tausalaina, ae lē taofia le saolotoga o le agaga."},{"verse":5,"text":"Matou te talitonu ua fusia tagata uma e lagolago ma talisapaia malo eseese ua latou nonofo ai, a’o puipuia i tulafono a ia malo ia latou aiā na soifua mai ma i latou ma lē ma’aveeseina; ma o le faatuiese ma le fouvale e lē tatau ai i tagatanuu taitoatasi ua faapea ona puipuia ai, ma e tatau ona faasalaina e pei ona tatau ai; ma e faapea ua i ai i malo uma se aiā e faia ai ituaiga o tulafono ua tusa ai ma a latou lava faautaga silisili ona lelei e mautinoa ai le manuia o tagata lautele; e ui i lea, e faamamaluina pea i lea lava taimi e tasi, le saolotoga o le mafaufau fetalai."},{"verse":6,"text":"Matou te talitonu e tatau ona faamamaluina tagata uma taitoatasi i lona lava tulaga, e pei o pule ma faipule, ua faatutuina mo le puipuiga o e ua lē sala ma le faasalaina o e ua sala; ma e faapea e tatau i tagata uma ona ava ma faaaloalo i tulafono, aua a aunoa ma ia tulafono o le a suia le filemu ma le lotogatasi i le pule faamalosi ma le mata’u; ona ua faatutuina tulafono faaletagata mo le faamoemoe tonu o le faafoeina o o tatou faamoemoega o ni tagata taitoatasi ma atunuu, i le va o le tagata ma le tagata; ma ua tuu mai tulafono paia mai le lagi, ua tuu mai ai tulafono e faatatau i atugaluga faaleagaga, mo le faatuatua ma le tapua’i, o ni mea uma e tali atu ai le tagata i Lē na faia o ia."},{"verse":7,"text":"Matou te talitonu ua i ai i pule, setete, ma malo se aiā, ma ua fusia e faia ni tulafono mo le puipuiga o tagatanuu uma i le faaaogaina saoloto o o latou talitonuga faalelotu; ae ua matou lē talitonu ua i ai ia te i latou se aiā faamasinotonu e aveesea ai mai tagatanuu lenei aiā, pe faasa i latou mai o latou manatu, pe a faapea o loo faaalia le ava ma le migao i tulafono ma e lē o ta’uamiotonuina i ia manatu faalelotu le faatuiese po o le fouvale."},{"verse":8,"text":"Matou te talitonu e tatau ona faasalaina le solia o le tulafono e tusa ma le uiga o le solitulafono; ma e faapea o le fasioti tagata, faalata malo, faomea, gaoi, ma le lepeti o le filemu lautele, i itu uma, e tatau ona faasalaina e tusa ma lo latou ituaiga ma lo latou uiga leaga i tagata, i tulafono a lena malo na faia ai le solitulafono; ma e tatau i tagata uma ona laa i luma ma faaaoga lo latou malosi i le aumaia i le faasalaga e ua solitulafono e faasaga i tulafono lelei, mo le filemu ma le to’a o tagata lautele."},{"verse":9,"text":"Matou te lē talitonu o se mea tonu le tuufaatasi o aafiaga faalelotu ma malo faaleatunuu, lea e lagolago ai le tasi faapotopotoga faalelotu ae faasa le isi i ana aiā faaleagaga, ma faafitia ai aiā faaletagata lava ia a ona tagata, o ni tagatanuu."},{"verse":10,"text":"Matou te talitonu ua i ai i faalapotopotoga faalelotu uma se aiā e faia ai i o latou lava tagata mo amioga ua lē tatau, e tusa ma tulafono ma faatonuga a ia lava faalapotopotoga; pe a faapea o ia mea e faia mo le faaaumeaina ma le tulaga lelei; ae matou te lē talitonu ua i ai i se faalapotopotoga faalelotu se pule e faamasino ai tagata e uiga i meatotino po o le ola, e aveese ai mai ia te i latou oloa o le lalolagi lenei, pe tuu lamatia ai o latou ola po o tino, pe faaoo atu ai ni faasalaga faaletino i luga o i latou. Pau le mea e mafai ona latou faia o le faate’a o i latou mai i la latou faalapotopotoga, ma aveese la latou faaaumea mai ia te i latou."},{"verse":11,"text":"Matou te talitonu e tatau i tagata ona tagi atu i le tulafono faalemalo mo le toe totogi mai o sese ma tiga uma, i mea na faia ai le sauā i le tagata pe na solia ai le aiā i meatotino po o le ta’uleleia, i mea ua i ai ituaiga tulafono e puipui ai ia aiā; ae matou te talitonu e ta’uamiotonuina tagata uma i le puipuiga o i latou lava, a latou uo, ma meatotino, ma le malo, mai osofaiga ma soliga lē tusa ai ma le tulafono a tagata uma i taimi o faalavelave faafuasei, i tulaga e lē mafai ona fai vave atu ai se tagi i le tulafono, ma lē maua ai se fesoasoani."},{"verse":12,"text":"Matou te talitonu o se mea tonu le talai atu o le talalelei i atunuu uma o le lalolagi, ma lapatai atu i e amiotonu e lavea’i i latou lava mai mea eleelea o le lalolagi; ae matou te lē talitonu o se mea sa’o le faalavelave fua atu i auauna-pologa, pe talai atu i ai le talalelei, pe papatisoina i latou e lē tusa ai ma le finagalo malie ma le manao i ai o o latou matai, pe faalavelave i ai pe uunai i latou i sina mea itiiti e faaoso ai i latou ia lē fiafia i o latou tulaga i le olaga nei, ma faapea ona faamata’uina ai ola o tagata; o ia faalavefau matou te talitonu ua lē tusa ai ma le tulafono ma ua lē tonu, ma e lamatia ai le filemu o malo uma e faatagaina le taofi o tagata i le pologa."}]},{"chapter":135,"verses":[{"verse":1,"text":"Ina ia faamauina le molimau a lenei tusi ma le Tusi a Mamona, matou te faasilasila atu le faamaturoina o Iosefa Samita le Perofeta, ma Ailama Samita le Peteriaka. Sa tafanaina i laua i le falepuipui i Karefasi, i le aso 27 o Iuni, 1844, pe tusa o le itula e lima i le afiafi, e se vaega o tagata leaga faaauupegaina—na vali uli o latou mata—e tusa ma le 150 i le 200 tagata. Sa muamua ona fanaina o Ailama ma pa’ū filemu ai i lalo, ma alaga: O a’u o se tagata oti! Sa oso Iosefa mai le faamalama, ma sa fana ma oti ai i le taumafaiga, ma alaga: E, le Alii e, lo’u Atua! Sa toe fanaina i laua uma, i se ala sauā lava, ina ua mavae ona maliliu i laua, ma e ta’ifa pulu na tafana ai i laua uma."},{"verse":2,"text":"O Ioane Taylor ma Willard Richards, se toalua o le Toasefululua, na pau lea o tagata sa i ai i totonu o le potu i le taimi lea; sa manu’a Ioane Taylor i se ala sauā lava i pulu e fa, ae ua toe malosi mai talu mai lea taimi; o Willard Richards, na sao mai, e ala i le tausiga a le Atua, e aunoa ma se pu i lona ofu."},{"verse":3,"text":"O Iosefa Samita, le Perofeta ma le Tagatavāai a le Alii, e tele atu mea na ia faia, vagana ai lava Iesu, mo le faaolataga o tagata i lenei lalolagi, nai lo se isi lava tagata na ola ai. I le va puupuu o le luasefulu tausaga, na ia aumaia le Tusi a Mamona, lea na faaliliuina e ia i le meaalofa ma le mana o le Atua, ma sa avea ma ala na faasalalau atu ai i konetineta e lua; auina atu le ’atoatoaga o le talalelei tumau e faavavau, ua i ai i totonu, i itu e fa o le lalolagi; aumai faaaliga ma poloaiga ua i ai i le tusi lenei o Mataupu Faavae ma Feagaiga, ma le tele o isi tusi ma aoaoga poto mo le manuia o le fanauga a tagata; faapotopoto le tele o afe o le Au Paia o Aso e Gata Ai, faavae se aai tele, ma tuua se ta’uta’ua ma se igoa e lē mafai ona faaumatia. Sa soifua maualuga o ia, ma sa maliu maualuga o ia i luma o fofoga o le Atua ma lona nuu; ma e pei o le toatele o le ’au faauuina a le Alii i taimi anamua, ua faamau faailogaina lana misiona ma lana galuega i lona lava toto; ma ua faapea foi lona uso o Ailama. Sa lei fevaevaea’i i laua i le soifuaga, ma sa lei tuueseeseina foi i laua i le oti!"},{"verse":4,"text":"Ina ua alu atu Iosefa i Karefasi e tuu atu o ia lava i manaoga faatagāfai o le tulafono, i le lua po o le tolu aso a o lumanai ai lona tagatavaleina, sa saunoa mai o ia: “Ua ’ou alu atu e pei o se tamai mamoe e fasia; ae ua ’ou toafilemu e pei o se taeao o le tau mafanafana; ua ia te a’u se lotofuatiaifo ua aunoa ma se faatausuai e faasaga i le Atua, ma faasaga i tagata uma. O le a ’ou oti lē sala ma o le a faapea ona fai ane e uiga ia te a’u—sa fasiotia o ia ma le faufau i ai.”—I le taeao lava lea, ina ua uma ona sauni o Ailama e alu—e mafai ona tatou faapea ane i le fasiga? ioe, aua sa faapea lava—sa faitauina e ia le palakalafa lenei, e latalata i le faaiuga o le mataupu e sefululua o le tusi a Eteru, i le Tusi a Mamona, ma afe i lalo le itulau i ona luga:"},{"verse":5,"text":"Ma sa oo ina ou tatalo atu i le Alii ina ia avatu e ia le alofa tunoa i Nuuese, ina ia latou maua le alofa mama. Ma sa oo ina fetalai mai le Alii ia te a’u: Afai e lē i ai ia te i latou le alofa mama, e lē afaina lea mea ia te oe, ua e faamaoni; o le mea lea, o le a faamamāina ou ofu. Ma ona ua e vaai i lou vaivai, o le a faamalosia ai oe, e oo lava i le nofo i lalo i le nofoaga ua Ou saunia i maota o lo’u Tamā. Ma o lenei ou te … faatofa atu i Nuuese; ioe, ma i o’u uso foi o e ua ou alofa i ai, seia oo ina tatou feiloai i luma o le nofoa-faamasino o Keriso, lea o le a iloa ai e tagata uma ua lē pisia o’u ofu i o outou toto. Ua maliliu nei le ’au molimau, ma ua tu nei la laua mau."},{"verse":6,"text":"O Ailama Samita na fasefulu-fa tausaga o le matua ia Fepuari, 1844, ma o Iosefa Samita sa tolusefulu-valu ia Tesema, 1843; ma mai i le taimi ma le agai i luma o le a tusia o laua igoa i totonu o le ’au maturo o tapuaiga faalelotu; ma o le a faamanatuina i lē e faitau i atunuu uma, o le Tusi a Mamona, ma le tusi lenei o Mataupu Faavae ma Feagaiga o le ekalesia, na faatauina i toto e sili ona lelei o le seneturi sefuluiva, e aumai ia tusi mo le faaolataga o se lalolagi ua faaleagaina; ma e faapea afai e mafai e le afi ona faamū se laau mata mo le mamalu o le Atua, o le a faigofie lava ona susunuina o laau mamago e faamamā ai le tovine mai le faaleagaina. Sa soifua i laua mo le mamalu; sa maliliu i laua mo le mamalu; ma o le mamalu o lo laua taui lea e faavavau. E mai lea vaitausaga i lea vaitausaga o le a oo atu o laua igoa i lalo i tupulaga o ni maa taua i e ua faapaiaina."},{"verse":7,"text":"Na mamā i laua mai se solitulafono, e pei ona sa faamaonia ai soo i laua muamua, ae sa na’o taupulepulega leaga a tagata faalata ma amioleaga na falepuipui ai i laua; ma o o laua toto lē sala ua i luga o le fola o le falepuipui i Karefasi o se faamaufaailoga lautele ua faapipii i le lotu “Mamona” e lē mafai ona faafitia e soo se faamasinoga i le lalolagi, ma o o laua toto lē sala i luga o le faailoga o le Setete o Ilinoi, faatasi ma le folafolaga solia a le Setete e pei ona sa folafolaina e le kovana, o se molimau i le moni o le talalelei tumau e faavavau e lē mafai e le lalolagi atoa ona faafitia; ma o o laua toto lē sala i luga o le fu’a o le saolotoga, ma i luga o le faavae o le saolotoga o le Iunaite Setete, o se amupasa mo le tapuaiga a Iesu Keriso, o le a ootia ai loto o tagata faamaoni i atunuu uma; ma o o laua toto lē sala, faatasi ma toto lē sala o le ’au maturo uma i lalo o le fatafaitaulaga na vaai i ai Ioane, o le a tagi a’e i le Alii o ’Au seia oo ina tauia lena toto i luga o le lalolagi. Amene."}]},{"chapter":136,"verses":[{"verse":1,"text":"O Le Afioga ma le Finagalo o le Alii e faatatau i le tolauapiga a Isaraelu ia latou malaga i Sisifo:"},{"verse":2,"text":"Ia tuu atu i tagata uma O Le Ekalesia a Iesu Keriso o le Au Paia o Aso e Gata Ai, ma i latou o e e malaga faatasi ma i latou, ia faatulagaina i ni vaega, faatasi ma se feagaiga ma se folafolaga e tausi i poloaiga ma tulafono uma a le Alii lo tatou Atua."},{"verse":3,"text":"Ia tuu atu i vaega e faatulaga ma ni kapeteni o taitoaselau, kapeteni o taitoalimagafulu, ma kapeteni o taitoasefulu, ma se peresitene ma ni ona fesoasoani e toalua i o latou ulu, i lalo o le taitaiga a Aposetolo e Toasefululua."},{"verse":4,"text":"Ma o le a avea lenei ma a tatou feagaiga—o le a tatou savavali i sauniga uma a le Alii."},{"verse":5,"text":"Ia tuu atu i vaega taitasi e saunia mo i latou lava ni soā manu, taavaletoso, mea manaomia, lavalava, ma isi mea e tatau ai mo le malaga, e mafai ona latou saunia."},{"verse":6,"text":"A uma ona faatulaga o vaega ia tuu atu ia te i latou e o atu ma lo latou malosi, e sauniuni mo i latou o e o le a faamuli."},{"verse":7,"text":"Ia tuu atu i vaega taitasi, faatasi ma o latou kapeteni ma peresitene, e filifilia pe toafia e mafai ona o i le tautotogo e sosoo ai; ona filifilia lea o se aofai e lava o tagata tino-malolosi ma popoto, e ave soā manu, fatu, ma mea fai faatoaga, e o atu o ni paionia e sauni mo le totoina o to’aga o le tautotogo."},{"verse":8,"text":"Ia tuu atu i vaega taitasi e ave se vaega tutusa, e tusa ma le vaevaega o a latou meatotino, i le aveina o e matitiva, fafine ua oti a latou tane, e ua leai ni tamā, ma aiga o i latou o e na o i le autau, ina ia lē alu a’e le tagi a fafine ua oti a latou tane ma e ua leai ni tamā i fofoga o le Alii e faasaga i lenei nuu."},{"verse":9,"text":"Ia tuu atu i vaega taitasi e sauni ni fale, ma ni fanua mo le totoina o saito, mo i latou o e o le a faamuli atu i le vaitau lenei; ma o le finagalo lenei o le Alii e faatatau i lona nuu."},{"verse":10,"text":"Ia tuu atu i tagata taitoatasi e faaaoga lona malosi ma ana meatotino uma e siitia atu ai lenei nuu i le nofoaga o le a faatuina ai e le Alii se siteki o Siona."},{"verse":11,"text":"Ma afai tou te faia lenei mea ma le loto mamā, i le faamaoni atoa, o le a faamanuiaina outou; o le a faamanuiaina outou ia outou lafu manu, ma a outou fagaga, ma o outou fanua, ma o outou fale, ma o outou aiga."},{"verse":12,"text":"Ia tuu atu i a’u auauna o Ezra T. Benson ma Erastus Snow e faatulaga se vaega."},{"verse":13,"text":"Ma ia tuu atu i a’u auauna o Orson Pratt ma Wilford Woodruff e faatulaga se vaega."},{"verse":14,"text":"O lenei foi, ia tuu atu i a’u auauna o Amasa Lyman i ma Siaosi A. Samita e faatulaga se vaega."},{"verse":15,"text":"Ma ia tofia ni peresitene, ma ni kapeteni o taitoaselau, ma taitoalimagafulu, ma taitoasefulu."},{"verse":16,"text":"Ma ia tuu atu i a’u auauna o e ua tofia e o atu ma aoao atu lo’u loto lenei i le au paia, ina ia latou saunia e o atu i se laueleele o le filemu."},{"verse":17,"text":"O atu loa i lo outou ala ma faia e pei ona Ou fai atu ai ia te outou, ma aua le matata’u i o outou fili; aua o le a latou lē maua le mana e taofia ai la’u galuega."},{"verse":18,"text":"O le a laveaiina Siona i lo’u lava taimi e tatau ai."},{"verse":19,"text":"Ma afai e saili soo se tasi e ati a’e o ia lava, ma lē saili mai i la’u fautuaga, o le a lē maua e ia le mana, ma o le a faaalia lona valea."},{"verse":20,"text":"Ia outou saili; ma tausi a outou folafolaga uma o le tasi ma le isi; ma aua le manao i mea a so outou uso."},{"verse":21,"text":"Ia outou tausi outou lava mai le leaga o le ta’u fua o le suafa o le Alii, aua o A’u o le Alii lo outou Atua, o le Atua lava o o outou tamā, o le Atua o Aperaamo ma Isaako ma Iakopo."},{"verse":22,"text":"O A’u o lē na taitaiina ese le fanauga a Isaraelu mai le laueleele o Aikupito; ma ua faaloaloa atu lo’u lima i aso e gata ai, e lavea’i lo’u nuu o Isaraelu."},{"verse":23,"text":"Tuu le fefinaua’i o le tasi ma le isi; tuu le tautala leaga o le tasi i le isi."},{"verse":24,"text":"Tuu le ’onā; ma tuu atu a outou upu e fesoasoani e faagaeetia ai e le tasi le isi."},{"verse":25,"text":"Afai e te nonō mai i lē lua te tuaoi, ia e toe faafoi atu le mea na e nonō mai; ma afai ua lē mafai ona e toe totogi atu, ona e alu atu sa’o lea ma ta’u atu i lē lua te tuaoi, ina ne’i tausalaina oe e ia."},{"verse":26,"text":"Afai e te maua le mea na leiloa a lē lua te tuaoi, ia e sailia ma le filiga seia e toe avatu ia te ia."},{"verse":27,"text":"Ia e filiga i le faasaoina o mea ua e maua, ina ia avea oe ma se tausimea atamai; ona o lea mea o se meaalofa foaifua mai le Alii lou Atua, ma o oe o sana tausimea."},{"verse":28,"text":"Afai ua e fiafia, vivii atu i le Alii i pesega, ma musika, ma siva, faatasi ma se tatalo o le viiga ma le faafetai."},{"verse":29,"text":"Afai ua e faanoanoa, ole atu i le Alii lou Atua i le loto maualalo, ina ia olioli o outou agaga."},{"verse":30,"text":"Aua le matata’u i o outou fili, ona ua i ai i latou i o’u lima ma o le a Ou faia ia te i latou le mea Ou te loto i ai."},{"verse":31,"text":"E ao ina tofotofoina lo’u nuu i mea uma, ina ia latou saunia e maua le mamalu ua ia te A’u mo i latou, o le mamalu lava lea o Siona; ma o ia o lē e lē onosaia le aoaiga e lē agavaa mo lo’u malo."},{"verse":32,"text":"Ia tuu atu ia te ia o lē ua valea e aoao le poto i le faamaualaloina o ia lava ma le ole atu i le Alii lona Atua, ina ia tatalaina ona mata ina ia mafai ona vaai o ia, ma tatalaina ona taliga ina ia mafai ona faalogo o ia;"},{"verse":33,"text":"Aua ua auina atu lo’u Agaga i le lalolagi e faamalamalama e ua lotomaualalo ma loto salamo, ma mo le ta’usalaina o e ua lē amioatua."},{"verse":34,"text":"Ua teena outou ma la outou molimau e o outou uso, le atunuu lea ua tutulieseina outou i fafo;"},{"verse":35,"text":"Ma ua oo mai nei le aso o lo latou mala, o aso lava o le faanoanoa, e pei o se fafine ua faatiga; ma o le a matua tele lava lo latou faanoanoa vagana ai ua vave ona latou salamo, ioe, ia vave lava."},{"verse":36,"text":"Aua ua latou fasioti perofeta, ma i latou o e na auina atu ia te i latou; ma ua latou faamasaaina toto lē sala, ua tagi mai le eleele e faasaga ia te i latou."},{"verse":37,"text":"O lea, aua le ofo i nei mea, ona tou te lei mamā lava; e lei mafai lava ona outou lavatia lo’u mamalu; ae o le a outou vaaia pe afai tou te faamaoni i le tausiga o a’u upu uma ua Ou tuu atu ia te outou, mai aso o Atamu ia Aperaamo, mai ia Aperaamo ia Mose, mai ia Mose ia Iesu ma ana aposetolo, ma mai ia Iesu ma ana aposetolo ia Iosefa Samita, o lē na Ou valaau atu i ai e ala i a’u agelu, a’u auauna galulue, ma i lo’u lava leo mai le lagi, e aumai la’u galuega;"},{"verse":38,"text":"O lona faavae na faataatia e ia, ma sa faamaoni; ma ua Ou ave o ia ia te a’u lava."},{"verse":39,"text":"Sa ofo le toatele i lona maliu; ae sa manaomia ona tatau ona faamau faailoga e ia lana molimau i lona toto, ina ia faamamaluina o ia ma ina ia tausalaina ai e ua amioleaga."},{"verse":40,"text":"Pe Ou te lei laveaiina ea outou mai i o outou fili, i se ala lava na Ou tuua ai se molimau o lo’u igoa?"},{"verse":41,"text":"O lea, o lenei, uai mai ia, E outou e tagata o la’u ekalesia; ma o outou toeaina ia faalogo mai faatasi; ua outou mauaina lo’u malo."},{"verse":42,"text":"Ia outou filiga i le tausiga o a’u poloaiga uma, ne’i oo mai faamasinoga i o outou luga, ma vaivai ai lo outou faatuatua, ma manumalo ai o outou fili ia te outou. O lea ua leai ni isi mea i le taimi nei. Amene ma Amene."}]},{"chapter":137,"verses":[{"verse":1,"text":"Sa tatalaina le lagi i luga o i matou, ma sa ou vaaia le malo selesitila o le Atua, ma lona mamalu, pe i le tino po o i fafo o le tino sa lē mafai ona ou iloaina."},{"verse":2,"text":"Sa ou vaaia le matagofie silisili o le faitotoa o le a ulu atu ai suli o lena malo, sa foliga mai e pei o le sasao faataaliolio o se afi;"},{"verse":3,"text":"Ma le nofoalii pupula foi o le Atua, sa afifio ai le Tamā ma le Alo."},{"verse":4,"text":"Sa ou vaai i auala matagofie o lena malo, sa foliga mai ua paeina i auro."},{"verse":5,"text":"Sa ou vaai i le Tama o Atamu ma Aperaamo; ma lo’u tamā ma lo’u tinā; lo’u uso o Alevini, o lē ua leva ona moe;"},{"verse":6,"text":"Ma sa ou ofo pe na faapefea ona maua e ia se tofi i lena malo, talu ai ona sa tuua e ia lenei olaga ae lei faatuina e le Alii lona aao e faapotopoto Isaraelu i le taimi lona lua, ma sa lei papatisoina o ia mo le faamagaloina o agasala."},{"verse":7,"text":"Sa faapea ona oo mai o le siufofoga o le Alii ia te a’u, ua fetalai mai: O i latou uma o e na maliliu e aunoa ma se malamalama e uiga i lenei talalelei, o e semanū latou te taliaina pe a na faatagaina i latou e ola, o le a avea ma suli o le malo selesitila o le Atua;"},{"verse":8,"text":"O lenei foi o i latou uma o e e maliliu mai le taimi nei ma le agai i luma e aunoa ma se malamalama e uiga i le talalelei, o e semanū latou te taliaina ma o latou loto atoa, o le a avea ma suli o lena malo;"},{"verse":9,"text":"Aua o A’u, o le Alii, o le a faamasinoina tagata uma e tusa ma a latou galuega, e tusa ma le manaoga o o latou loto."},{"verse":10,"text":"Ma sa ou vaai foi o tamaiti uma o e e maliliu a’o lei oo i latou i tausaga e tali mai ai ua faaolaina i le malo selesitila o le lagi."}]},{"chapter":138,"verses":[{"verse":1,"text":"I Le aso tolu o Oketopa, i le tausaga e afe ivaselau sefuluvalu, sa ou nofo ai i lo’u potu ma mafaufau loloto i tusitusiga paia;"},{"verse":2,"text":"Ma manatunatu i le taulaga togiola tele na faia e le Alo o le Atua, mo le togiolaina o le lalolagi;"},{"verse":3,"text":"Ma le alofa tele ma le ofoofogia na faaali mai e le Tamā ma le Alo i le afio mai o le Togiola i le lalolagi;"},{"verse":4,"text":"Ma e ala i lana togiola, ma le usiusitai i mataupu faavae o le talalelei, e mafai ona faaolaina ai o tagata."},{"verse":5,"text":"A’o faapea ona ou mafaufau, sa foi i tua lo’u mafaufau i tusitusiga a le aposetolo o Peteru, i le au paia anamua na salalau lautele i Pono, Kalatia, Kapatokia, ma isi vaega o Asia, sa talai ai le talalelei ina ua mavae le faasatauroga o le Alii."},{"verse":6,"text":"Sa ou susue le Tusi Paia ma faitau le mataupu e tolu ma le fa o le tusi muamua a Peteru, ma a’o ou faitauina sa matua uunaia lava a’u, e sili atu nai lo se isi lava taimi na uunaia muamua ai a’u, i le mau lenei:"},{"verse":7,"text":"“Ona na mafatia i se taimi Keriso mo agasala, o le amiotonu mo le amioletonu, ina ia mafai ona ia aumai i tatou i le Atua, ina ua fasiotia i le tino, ae faaolaina i le Agaga:"},{"verse":8,"text":"“Lea na maliu atu ai foi o ia ma talai atu i agaga i le falepuipui;"},{"verse":9,"text":"“O e na lē faalogo i nisi o taimi, i le taimi na faatalitali ai le talitiga o le Atua i ona po o Noa, a’o saunia le vaa, lea na faasaoina ai se toaitiiti, e toavalu, i le vai.” (1 Peteru 3:18–20.)"},{"verse":10,"text":"“Ona o le pogai lenei na talai atu ai foi le talalelei ia te i latou o e ua oti, ina ia mafai ona faamasinoina i latou i la tagata i le tino, ae ola i la le Atua i le agaga.” (1 Peteru 4:6.)"},{"verse":11,"text":"A’o o’u mafaufau loloto i nei mea ua tusia, sa tatalaina mata o lo’u malamalama, ma sa afio le Agaga o le Alii i o’u luga, ma sa ’ou vaai i ’au o e ua oti, o e faatauvaa ma e ta’uta’ua."},{"verse":12,"text":"Ma sa faapotopoto faatasi i se nofoaga e tasi se vaega lē mafaitaulia o agaga o e amiotonu, o e na faamaoni i le molimau ia Iesu a’o soifua i latou i la le tino;"},{"verse":13,"text":"Ma o e na osi atu taulaga i le faatusa o le taulaga sili a le Alo o le Atua, ma sa mafatia i puapuaga i le suafa o lo latou Togiola."},{"verse":14,"text":"O i latou uma nei ua tuua le olaga i la le tino, ua mautu i le faamoemoe mo se toetu mamalu, e ala i le alofa tunoa o le Atua le Tamā ma lona Atalii Pele e Toatasi, o Iesu Keriso."},{"verse":15,"text":"Sa ou vaai ua faatumulia i latou i le olioli ma le fiafia, ma sa olioli faatasi ona ua oo mai lava le aso o lo latou lavea’iina."},{"verse":16,"text":"Sa latou potopoto e faatalitali le afio atu o le Alo o le Atua i le lalolagi o agaga, e folafola atu le togiolaina o i latou mai noataga o le oti."},{"verse":17,"text":"O o latou efuefu momoe o le a toefuatai i lona autino atoatoa, o le ivi i le ivi, ma uaua ma aano i luga o i latou, o le agaga ma le tino o le a toe faatasia e lē mafai ona toe tuueseeseina, ina ia mafai ona latou maua se atoatoaga o le olioli."},{"verse":18,"text":"A’o faatalitali ma talatalanoa lenei vaega tele o agaga, ma olioli i le itula o lo latou lavea’iga mai filifili o le oti, sa afio atu le Alo o le Atua, ma folafola atu le saolotoga i e na ave faatagataotaua, o e na faamaoni;"},{"verse":19,"text":"Ma o iina na talai atu ai e ia ia te i latou le talalelei tumau e faavavau, le aoaoga faavae o le toetutu mai ma le togiolaina o tagata mai le pa’ū, ma mai agasala a le tagata lava ia i luga o tulaga o le salamo."},{"verse":20,"text":"Ae o e amioleaga sa lē afio atu i ai o ia, ma sa lei siia lona siufofoga i e sa lē amioatua ma e sa lē salamo o e sa latou faaleagaina i latou lava a’o i ai i le tino;"},{"verse":21,"text":"Pe na vaai foi le au fouvale o e na teena molimau ma lapataiga a perofeta anamua i lona mamalu, pe na vaai i ona fofoga."},{"verse":22,"text":"O le mea na i ai i latou ia, sa nofotupu ai le pouliuli, ae i totonu o e amiotonu, sa i ai le filemu;"},{"verse":23,"text":"Ma sa olioli le au paia i lo latou togiolaina, sa tootuli tulivae ma talisapaia le Alo o le Atua o lo latou Togiola ma le Laveai mai le oti ma filifili o seoli."},{"verse":24,"text":"Sa susulu o latou fofoga, ma sa i o latou luga le malamalama o le mamalu o le Alii, ma sa latou pepese atu viiga i lona suafa paia."},{"verse":25,"text":"Sa ou ofo, aua sa ou malamalama sa faaaluina e le Faaola le tusa o le tolu tausaga i lana auaunaga i totonu o tagata Iutaia ma i latou o le aiga o Isaraelu, i le taumafai e aoao atu ia te i latou le talalelei tumau e faavavau ma valaau ia te i latou ina ia salamo;"},{"verse":26,"text":"Ma peitai, e ui i ana galuega tetele, ma vavega, ma le folafolaga o le upumoni, i le mana tele ma le pule, sa toaitiiti lava e na faalogo i lona siufofoga, ma olioli i le i ai i ona luma, ma maua le olataga mai ona aao."},{"verse":27,"text":"Ae o lana auaunaga i totonu o i latou o e ua oti sa faatapulaaina i se taimi puupuu i le va o le faasatauroga ma lona toetu mai;"},{"verse":28,"text":"Ma sa ou fesilisili ifo e uiga i upu a Peteru—lea na fai mai ai o ia e faapea na talai atu le Alo o le Atua i agaga i le falepuipui, o e sa lē usiusitai i se taimi, a’o faatalitali i se taimi le tali-tiga o le Atua i ona po o Noa—ma le ala na mafai ai e ia ona talai atu i ia agaga ma faia le galuega e tatau ai i totonu o i latou i se taimi puupuu lava."},{"verse":29,"text":"Ma a’o ou fesilisili ifo, sa tatalaina o’u mata, ma sa faavaveina lo’u malamalamaaga, ma sa ou vaai sa lei afio atu le Alii lava ia i totonu o e amioleaga ma lē usiusitai o e na teena le upumoni, e aoao atu ia te i latou;"},{"verse":30,"text":"Ae faauta, sa faatulaga e ia mai totonu o e amiotonu, ana ’au ma tofia avefeau, ua faaofuina i le mana ma le pule, ma sa valaauina i latou e o atu ma avatu le malamalama o le talalelei ia te i latou o e sa i ai i le pouliuli, i agaga o tagata uma lava; ma sa faapea ona talai atu o le talalelei i e ua oti."},{"verse":31,"text":"Ma sa o atu avefeau filifilia e talai atu le aso e talia ai e le Alii ma folafola atu le saolotoga i e ua faatagataotauaina o e ua noanoatia, e oo lava ia i latou uma o e o le a salamo mai ia latou agasala ma talia le talalelei."},{"verse":32,"text":"Sa faapea ona talai atu o le talalelei ia te i latou o e na oti ia latou agasala, e aunoa ma se malamalama e uiga i le upumoni, po o le solitulafono, ona ua latou teena perofeta."},{"verse":33,"text":"Sa aoao atu ia te i latou le faatuatua i le Atua, le salamo mai agasala, le papatisoga sui mo le faamagaloina o agasala, le meaalofa o le Agaga Paia e ala i le faaee atu o lima,"},{"verse":34,"text":"Ma isi mataupu autu uma o le talalelei sa tatau ia te i latou ona iloa ina ia latou agavaa ina ia mafai ona faamasino i latou e tusa ma tagata i le tino, ae ola i le Atua i le agaga."},{"verse":35,"text":"Ma sa faapea ona faailoa atu i totonu o e ua oti, o e faatauvaa ma e ua ta’uta’ua, o e amioletonu faapea foi ma e ua faamaoni, ua aumai le togiolaina e ala i le taulaga a le Alo o le Atua i luga o le satauro."},{"verse":36,"text":"Sa faapea ona faailoa mai sa faaalu e lo tatou Togiola lona taimi a o afio o ia mo sina taimi i le lalolagi o agaga, i le aoaoga ma le sauniuniga o agaga faamaoni o perofeta o e na molimau ia te ia i la le tino;"},{"verse":37,"text":"Ina ia mafai ona latou avatu o le savali o le togiolaina i e uma ua oti, ia i latou o e sa lē mafai ona afio atu i ai o ia lava, ona o lo latou fouvale ma soligatulafono, ina ia mafai e i latou e ala atu i le auaunaga a ana auauna, ona faalogo foi i ana afioga."},{"verse":38,"text":"Sa i ai i totonu o e ta’uta’ua ma malolosi sa potopoto i lenei faapotopotoga tele o e amiotonu, o le Tama ia Atamu, o le Anamua o Aso ma le tamā o tagata uma,"},{"verse":39,"text":"Ma lo tatou Tinā mamalu o Eva, faatasi ma le toatele o ana fanau tamaitai faamaoni o e na soifua i vaitausaga ma tapuai atu i le Atua moni ma soifua."},{"verse":40,"text":"O Apelu, le uluai maturo, sa i ai iina, ma lona uso o Setu, o se tasi o e malolosi, o lē sa foliga tonu lava i lona tamā, o Atamu."},{"verse":41,"text":"O Noa, o lē na lapatai atu e uiga i le lolo; ma Semu, le faitaulaga sili ta’uta’ua; o Aperaamo, le tamā o le au faatuatua; o Isaako, Iakopo, ma Mose, le faitulafono ta’uta’ua o Isaraelu;"},{"verse":42,"text":"Ma Isaia, o lē na folafola mai e ala i valoaga e faapea sa faauuina le Togiola e fusifusi i e ua loto-momomo, e folafola atu le saolotoga i e ua ave faatagataotaua, ma le tatalaina o le falepuipui ia te i latou o e ua noanoatia, sa i ai foi iina."},{"verse":43,"text":"E le gata i lea, o Esekielu, o lē na faaali i ai i se faaaliga vaaia le vanu tele o ivi mamago, o le a faaoofuina i aano, ia toetutu mai i le toetutu o e ua oti, o ni tagata ola;"},{"verse":44,"text":"O Tanielu, o lē na mua’i vaai ma valoia le faatuina o le malo o le Atua i aso e gata ai, e lē toe faaumatia pe tuuina atu i ni isi tagata;"},{"verse":45,"text":"O Elaia, o lē sa faatasi ma Mose i le Mauga o Liua;"},{"verse":46,"text":"Ma Malaki, le perofeta na molimau e uiga i le oo mai o Elia—o lē foi na fetalai i ai Moronae i le Perofeta o Iosefa Samita, ma folafola mai e tatau ona sau o ia a’o lei oo mai le aso tele ma le mata’utia o le Alii—sa i ai foi iina."},{"verse":47,"text":"O le Perofeta o Elia na te totoina i loto o fanau folafolaga na faia i o latou tamā,"},{"verse":48,"text":"Ua faaataata mai ai le galuega tele o le a faia i malumalu o le Alii i le tisipenisione o le atoaga o taimi, mo le togiolaina o e ua maliliu, ma le faamauina o fanau i o latou matua, ina ne’i taia le lalolagi atoa i se fetuu ma faama’umauina uma ai i lona afio mai."},{"verse":49,"text":"O i latou uma nei ma isi e toatele, e oo i perofeta na soifua i totonu o tagata sa Nifaē ma molimau e uiga i le afio mai o le Alo o le Atua, sa feofoofoa’i i totonu o lenei faapotopotoga tele ma faatalitali mo lo latou lavea’iga,"},{"verse":50,"text":"Aua sa vaai e ua maliliu i le umi o le tuuesea o o latou agaga mai i o latou tino, o se pologa."},{"verse":51,"text":"O i latou ia na aoaoina e le Alii, ma tuu atu ia te i latou le mana e tutulai mai ai, pe a mavae lona toetu mai i le oti, e ulu atu i le malo o lona Tamā, e faapaleina iina i le tino ola pea ma le ola e faavavau,"},{"verse":52,"text":"Ma faaauau pea mai le taimi lena ma le agai i luma a latou galuega e pei ona sa folafolaina e le Alii, ma avea ma e e tofusia i faamanuiaga uma sa faapolopolo mo i latou o e alolofa ia te ia."},{"verse":53,"text":"O le Perofeta o Iosefa Samita, ma lo’u tamā, o Ailama Samita, Brigham Young, Ioane Taylor, Wilford Woodruff, ma isi agaga filifilia o e sa faapolopolo e o mai i le atoaga o taimi e auai i le faataootoina o faavae o le galuega tele o aso e gata ai,"},{"verse":54,"text":"E aofia ai le fausiaina o malumalu ma le faia ai o sauniga i totonu mo le togiolaina o e ua oti, sa i ai foi i le lalolagi o agaga."},{"verse":55,"text":"Sa ou vaai foi sa i ai i latou i totonu o e mamalu ma ta’uta’ua o e na filifilia i le amataga e avea ma pule i le Ekalesia a le Atua."},{"verse":56,"text":"I le taimi lava ae lei fananau mai i latou, o i latou, faatasi ma le toatele o isi, sa latou maua a latou lesona muamua i le lalolagi o agaga ma sa saunia e o mai i le taimi e tatau ai a le Alii e galulue i lona tovine mo le faaolataga o agaga o tagata."},{"verse":57,"text":"Sa ou vaai o toeaina faamaoni o lenei tisipenisione, pe a tuua e i latou lenei olaga faaletino, e faaauau a latou galuega i le talaiga o le talalelei o le salamo ma le togiolaina, e ala i le taulaga a le Atalii Pele e Toatasi o le Atua, i totonu o e o loo i le pouliuli ma o loo i lalo o le pologa o le agasala i le lalolagi tele o agaga o e ua oti."},{"verse":58,"text":"O e e salamo o e ua oti o le a togiolaina, e ala i le usiusitai i sauniga o le maota o le Atua,"},{"verse":59,"text":"Ma a uma ona latou totogi o le sala o a latou solitulafono, ma ua mulumuluina mamā, o le a latou maua se taui e tusa ma a latou galuega, aua o i latou o ni suli o le faaolataga."},{"verse":60,"text":"Sa faapea ona faaali mai ia te a’u o le faaaliga vaaia o le togiolaina o e ua oti, ma ou te molimau atu, ma ua ou mautinoa ua moni lenei molimau, e ala i le faamanuiaga a lo tatou Alii ma le Faaola, o Iesu Keriso, ua faapea lava. Amene."}]}]},{"id":"official-declarations","title":"Folafolaga Aloaia","englishTitle":"Official Declarations","volume":"Doctrine and Covenants","volumeId":"dc-testament","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"I E Ua Tatau I Ai:"},{"verse":2,"text":"Ona o lipoti o tala fou a nusipepa ua auina atu mo faamoemoega faafaigamalo, mai le Aai o Sate Leki, ia ua faasalalauina faalauaitele, e faapea ua fai mai le Komiti o Iutā, i la latou lipoti talu ai nei i le Failautusi o le Initerio, o loo faia pea faaipoipoga ma avā e tele ma e faapea e fasefulu pe sili atu faaipoipoga faapena na faia i Iutā talu mai Iuni ua mavae atu po o le tausaga ua mavae, o lenei foi e faapea sa aoaoina, faamalosia ma uunaia e taitai o le Ekalesia i a latou lauga i tagata, le faaauauina o le faia o avā e tele—"},{"verse":3,"text":"O lea, o a’u, o le Peresitene O Le Ekalesia a Iesu Keriso o le Au Paia o Aso e Gata Ai, ou te tautino atu, i le ala sili ona mamalu, e ala atu i lenei folafolaga, o ia tuua’iga ua sese. Matou te lē o aoaoina le faia o avā e tele po o faaipoipoga i avā e toatele, pe o faatagaina se tagata e faia lena mea, ma ou te teena le tala e faapea e fasefulu po o se isi aofai ia faaipoipoga i avā e toatele na faia i le vaitaimi lena i o matou Malumalu po o se isi lava mea i le Teritori."},{"verse":4,"text":"E tasi le mea na lipoti mai, na fai mai ai i latou na aumaia le tala, e faapea na faia se faaipoipoga faapena i le Fale o Faaeega, i le Aai o Sate Leki, i le Tautotogo o le 1889, ae sa lē mafai ona ou iloa po o ai na faia le sauniga; po o le a lava le mea na faia i lea mataupu sa aunoa ma lo’u malamalama i ai. Ona o lenei mea e faapea na tupu, na tala ai i lalo i la’u faatonuga le Fale o Faaeega, e aunoa ma se faatuai."},{"verse":5,"text":"Talu ai ona ua faia e le Konakaresi tulafono e faasa ai le faaipoipo i avā e toatele, o ni tulafono ua ta’ua e le faamasinoga na tāpā mulimuli lava ua tusa ai ma le tulafono faavae o le malo, o lea ou te folafola atu ai nei lo’u faamoemoe e usiusitai i ia tulafono, ma faaaoga a’u uunaiga i tagata o le Ekalesia ua ou pulefaamalumalu ai i luga, ia faapea foi ona latou faia."},{"verse":6,"text":"E leai se mea o i ai i a’u aoaoga i le Ekalesia po o i aoaoga a i latou o a’u aumea, i le taimi faapitoa lea ua ta’ua, e mafai ona faauiga ma le mafaufau lelei ua uunaia pe faamalosia ai le faia o avā e toatele; ma i soo se taimi na faaaoga ai e se Toeaina o le Ekalesia ni upu na foliga mai ai le tuuina atu o se aoaoga faapena, sa vave lava ona aoa’iina o ia. Ma o lenei ou te folafola atu nei o la’u fautuaga i le Au Paia o Aso e Gata Ai, ia ’alo’alosa mai le faia o se faaipoipoga ua faasaina e le tulafono o le laueleele."},{"verse":7,"text":"Wilford Woodruff"},{"verse":8,"text":"Peresitene O Le Ekalesia a Iesu Keriso o le Au Paia o Aso e Gata Ai."},{"verse":9,"text":"O upu nei na tuuina mai e Peresitene Lorenzo Snow:"},{"verse":10,"text":"“Ou te tuuina atu se lafo e faapea, i le tatou aloa’ia ai o Wilford Woodruff o le Peresitene O Le Ekalesia a Iesu Keriso o le Au Paia o Aso e Gata Ai, ma ona pau lea o le tagata e toatasi o i le lalolagi i le taimi nei o loo umia ki o sauniga faamau, ua matou manatu ua i ai ia te ia le pule atoa e tusa ai ma lona tulaga e tuu atu ai le Manifeso sa faitauina i la tatou faafofogaaga, ma na tusia i le aso 24 o Setema, 1890, ma e faapea o i tatou o se Ekalesia ua potopoto i se Konafesi Aoao, ua tatou talia lana folafolaga e faatatau i faaipoipoga i avā e toatele o se folafolaga ua faia i le pule tatau ma mautu.”"},{"verse":11,"text":"Aai o Sate Leki, Iutā, Oketopa 6, 1890."},{"verse":12,"text":"E lē tuua lava e le Alii a’u po o se isi lava tagata e tu e avea ma Peresitene o le Ekalesia lenei na te taitai sese outou. Ua lē i ai lena mea i le polokalama. Ua lē o i ai i le finagalo o le Atua. Afai ou te taumafai e fai lena mea, o le a aveesea a’u e le Alii mai lo’u tulaga, ma o le a faapea foi ona Ia faia i soo se isi lava tagata e taumafai e taitai sese le fanauga a tagata mai faaaliga a le Atua ma mai i lo latou tiute. (O le lona Onosefulu-Tasi o Konafesi Aoao Faaleafatausaga a le Ekalesia, Aso Gafua, 6 Oketopa, 1890, Aai o Sate Leki, Iutā. Lipotia i le Deseret Evening News [Tala Fou o le Afiafi a le Tesareta], 11 Oketopa, 1890, itulau 2.)"},{"verse":13,"text":"E lē afaina po o ai e ola po o ai e oti, po o ai e valaaulia e taitaia le Ekalesia lenei, ae e tatau lava ona latou taitaia e ala i musumusuga a le Atua Malosi Aoao. Afai latou te lē faia i le ala lena, e lē mafai lava ona latou faia. …"},{"verse":14,"text":"Sa ou maua ni faaaliga talu ai nei, ma ua taua tele ia ia te a’u, ma o le a ou ta’u atu ia te outou le mea na fetalaia mai e le Alii ia te a’u. Se’i ou aumai i o outou finagalo le mea ua ta’ua o le manifeso. …"},{"verse":15,"text":"Na fetalai mai le Alii ia te a’u ou te fesili atu i le Au Paia o Aso e Gata Ai se fesili, ma sa fetalai mai foi o Ia ia te a’u, e faapea afai latou te faalogo i le mea na ou te fai atu ai ia te i latou ma tali le fesili e tuu atu ia te i latou, e ala i le Agaga ma le mana o le Atua, o le a latou tali tutusa uma mai, ma o le a latou talitonu tutusa uma foi e uiga i lenei mataupu."},{"verse":16,"text":"O le fesili lenei: O le a le ala e sili ona poto e tatau ona mulimuli ai le Au Paia o Aso e Gata Ai—o le faaauau pea ona taumafai e fai faaipoipoga i avā e toatele ma le tetee i ai o tulafono a le atunuu ma le tetee i ai o le onosefulu miliona o tagata, ma le tau o le aveesea ma le toesea ai o Malumalu uma, ma le taofia ai o sauniga uma ua faia ai i totonu, mo e o ola ma e ua oti, ma le falepuipui ai o le Au Peresitene Sili ma le Toasefululua ma ulu o aiga i le Ekalesia, ma le aveesea ai o meatotino faaletagata lava ia a le nuu (o ia mea uma lava o le a taofia ai le faia o lea tu); pe, a uma ona faia ma mafatia i mea na tatou faia e ala i lo tatou tausisi i lenei mataupu autu e taofi le faia o lenei tu ma lolo atu i le tulafono, ma ala ai i le faia faapea ona tuu o Perofeta, Aposetolo ma tamā i aiga, ina ia mafai ona latou aoao le nuu ma faasaga atu i tiute o le Ekalesia, ma tuu ai foi malumalu i lima o le Au Paia, ina ia mafai ona latou faasaga atu i sauniga o le Talalelei, mo e o ola ma e ua maliliu?"},{"verse":17,"text":"Na faaali mai e le Alii ia te a’u i se faaaliga vaaia ma se faaaliga le mea tonu lava e tupu mai pe a na tatou lē taofia lenei tu. A na tatou lē taofia, po ua leai se aoga ia te outou o … soo se alii o i totonu o lenei malumalu i Logan; ona o le a taofia sauniga uma i le laueleele atoa o Siona. O le a nofotupu le fenumia’i ia Isaraelu atoa, ma e toatele alii o le a ave faapagota. Po ua oo mai lenei faalavelave i luga o le Ekalesia atoa, ma po ua faamalosia i tatou e taofi lenei tu. O lenei, o le fesili e faapea, pe tatau ona taofia i le ala lenei, po o i le ala ua faaali mai e le Alii ia te i tatou, ma tuu ai o tatou Perofeta ma Aposetolo ma tamā o ni tagata saoloto, ma malumalu i lima o le nuu, ina ia mafai ona togiolaina e ua maliliu. E i ai se vaega tele ua uma ona laveaiina mai le falepuipui i le lalolagi o agaga e lenei nuu, ma e faia pea ea le galuega pe taofi? O le fesili lenei ou te faataatia atu i luma o le Au Paia o Aso e Gata Ai. E tatau ona outou faamasino mo outou lava. Ou te manao ia outou talia mo outou lava. O le a ou lē taliina; ae ou te fai atu ia te outou o le tulaga tonu lava lena semanu tatou te oo i ai o se nuu pe a na tatou lē faia le mea ua tatou faia."},{"verse":18,"text":"… Sa ou vaai tonu lava i le mea semanu e oo mai pe a na leai se mea e faia. Sa i luga o a’u lenei agaga mo se taimi umi lava. Ae ou te fia fai atu le mea lenei: Semanu ua ou tuu atu malumalu uma e o ese atu mai o tatou lima; semanu ua ou alu atu a’u lava i le falepuipui, ma tuu atu i isi alii uma e o atu iina, pe a na lē poloaiina a’u e le Atua o le lagi e fai le mea na ou faia; ma ina ua oo mai le itula na poloaiina ai a’u e faia lena mea, sa manino atoa ia te a’u. Sa ou alu atu i luma o le Alii, ma sa ou tusia le mea na fetalai mai le Alii ia te a’u ia tusia. …"},{"verse":19,"text":"Ou te tuu atu lenei mea ia te outou, mo outou tou te manatunatu loloto ma mafaufau i ai. O loo galue le Alii faatasi ma i tatou. (Konafesi a le Siteki o Kesi, Lokeni, Iutā, Aso Sa, 1 Novema, 1891. Lipotia i le Deseret Weekly [Tesareta Faalevaiaso], 14 Novema, 1891.)"},{"verse":20,"text":"O le a ou ta’u atu nei ia te outou le mea na faaali mai ia te a’u ma le mea na faia e le Alo o le Atua i lenei mea. … E pei ona soifua le Atua Malosi Aoao, o nei mea uma semanu e oo mai, pe a na lē tuuina atu le Manifeso. O lea, sa i le finagalo o le Alo o le Atua ia tuu atu lena mea i le Ekalesia ma le lalolagi mo faamoemoega o i lona lava finagalo. Sa faatonuina e le Alii le faatuina o Siona. Sa ia faatonuina le faamaeaina o lenei malumalu. Sa ia faatonuina e tatau ona tuuina atu i nei vanu o mauga le faaolataga o e o ola ma e ua maliliu. Ma sa faatonuina e le Atua Malosi Aoao ia lē taofia e le Tiapolo. Afai e mafai ona outou malamalama i lena mea, o le ki lena i ai. (Mai se lauga i le sauniga lona ono o le faapaiaga o le Malumalu i Sate Leki, Aperila 1893. Faamatalaga lomia o Sauniga o le Faapaiaga, mai Potutusi, o le Matagaluega o Talafaasolopito o le Ekalesia, Aai o Sate Leki, Iutā.)"}]},{"chapter":2,"verses":[{"verse":1,"text":"I E Ua Tatau I Ai:"},{"verse":2,"text":"I le aso 30 o Setema, 1978, i lona 148 o Konafesi Aoao Faaleafatausaga O Le Ekalesia a Iesu Keriso o le Au Paia o Aso e Gata Ai, na fofoga atu ai le saunoaga lenei e Peresitene N. Eldon Tanner, le Fesoasoani Muamua i le Au Peresitene Sili o le Ekalesia:"},{"verse":3,"text":"I le amataga lava o Iuni o le tausaga nei, na folafola atu ai e le Au Peresitene Sili ua maua e Peresitene Spencer W. Kimball se faaaliga ua tuu atu ai le perisitua ma faamanuiaga o le malumalu i alii agavaa uma o le Ekalesia. Ua talosaga mai Peresitene Kimball ia ou faailoa atu i le konafesi e faapea ina ua mavae ona maua e ia lenei faaaliga, lea na oo mai ia te ia ina ua mavae le manatunatu loloto ma talosaga uumi i totonu o potu paia o le malumalu, sa ia tuuina atu i ona fesoasoani, o e na taliaina ma ioe i ai. Ona tuu atu lea i le Korama a Aposetolo e Toasefululua, o e na ioe autasi i ai, ma tuu atu mulimuli ane ai i isi uso uma o au Pulega Aoao, o e foi na ioe autasi i ai."},{"verse":4,"text":"Ua talosaga mai Peresitene Kimball ia ou faitau atu nei le tusi lenei:"},{"verse":5,"text":"Iuni, 1978"},{"verse":6,"text":"I taitai aoao uma ma taitai o le perisitua i lotoifale O Le Ekalesia a Iesu Keriso o le Au Paia o Aso e Gata Ai i le lalolagi atoa:"},{"verse":7,"text":"Uso Pele e:"},{"verse":8,"text":"A’o matou molimauina le faalauteleina o le galuega a le Alii i le lalolagi, matou te faafetai tele i le talia e tagata o atunuu e tele le savali o le talalelei toefuataiina, ma ua auai i le Ekalesia i se aofai faateleina pea. O lenei mea, ua uunaia ai i matou i se manaoga e tuu atu i tagata agavaa uma o le Ekalesia avanoa ma faamanuiaga uma ua tuuina mai i le talalelei."},{"verse":9,"text":"I le matou iloa lelei o folafolaga na faia e perofeta ma peresitene o le Ekalesia o e na muamua ia te i matou, e faapea e i ai se taimi, i le fuafuaga e faavavau a le Atua, o le a mafai ona maua ai o le perisitua e o tatou uso uma ua agavaa, ma i le molimauina o le faamaoni o i latou o e ua taofia mai ai le perisitua, na matou aioi umi atu ai ma le naunautai mo i latou nei, o o tatou uso faamaoni, ma faaaluina itula e tele i le Potu Aluga o le Malumalu i le talosagaina o le Alii mo se taitaiga paia."},{"verse":10,"text":"Ua faafofogaina e ia a matou talosaga, ma ua faamaonia mai i se faaaliga na oo mai i lena aso ua loa ona folafolaina e mafai ai ona maua e alii faamaoni ma agavaa uma o le Ekalesia le perisitua paia, faatasi ma le mana e faaaoga ai lana pule paia, ma olioli faatasi ma e ua pele ia te ia i faamanuiaga uma e tafe mai ai, e aofia ai faamanuiaga o le malumalu. E tusa ai la ma lea, ua mafai nei ona faauuina i le perisitua alii agavaa uma o le Ekalesia e aunoa ma se manatu i le ituaiga o tagata po o le lanu. Ua faatonuina taitai o le perisitua ia mulimuli i le aiaiga faavae e faatatau i le faatalanoaina lelei o alii uma ua faamoemoeina mo le faauuga i le Perisitua Arona po o le Mekisateko ina ia mautinoa ua latou ola i tulaga faatonuina mo le agavaa."},{"verse":11,"text":"Matou te folafola atu ma le mamalu ua faailoa mai nei e le Alii lona finagalo mo le faamanuiaina o ana fanau uma i le lalolagi atoa o e e faalogo i le leo o ana auauna tofia, ma saunia i latou lava e maua faamanuiaga uma o le talalelei."},{"verse":12,"text":"Spencer W. Kimball"},{"verse":13,"text":"N. Eldon Tanner"},{"verse":14,"text":"Marion G. Romney"},{"verse":15,"text":"O Le Au Peresitene Sili"},{"verse":16,"text":"I lo tatou aloa’ia ai o Spencer W. Kimball o le perofeta, tagatavāai, ma talifaaaliga, ma le peresitene O Le Ekalesia a Iesu Keriso o le Au Paia o Aso e Gata Ai, ua tuuina mai ia i tatou o se tino potopoto e taliaina lenei faaaliga o le afioga ma le finagalo o le Alii. O i latou uma o e e finagalo i ai ia faailoa mai i le sii mai o o outou aao taumatau. Ai se e faatuiese ia faaali mai i lea lava faailoga."},{"verse":17,"text":"Na autasi le lagolagoina o le palota i le lafo faatu."},{"verse":18,"text":"Aai o Sate Leki, Iutā, 30 Setema, 1978."}]}]},{"id":"moses","title":"Mose","englishTitle":"Moses","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"O afioga a le Atua, na ia fetalai ai ia Mose i le taimi na aveina a’e ai Mose i se mauga maualuga tele lava,"},{"verse":2,"text":"Ma sa vaai faafesagai o ia i le Atua, ma sa la talanoa ma ia, ma sa i luga o Mose le mamalu o le Atua; o lea na mafai ai e Mose ona gafataulimaina lona mamalu."},{"verse":3,"text":"Ma sa fetalai mai le Atua ia Mose, ua fai mai: Faauta, o A’u o le Alii le Atua Malosi Aoao, ma e Lē Gata o lo’u igoa lea; ona ua aunoa A’u ma se amataga o aso po o se gataaga o tausaga; ma pe lē o le lē gata ea lea?"},{"verse":4,"text":"Ma, faauta, o oe lava o lo’u atalii; o le mea lea ia vaai, ma o le a Ou faaali atu ia te oe galuega a o’u lima; ae lē o galuega uma, aua o a’u galuega ua aunoa ma se gataaga, ma a’u upu foi, aua e lē uma lava i latou."},{"verse":5,"text":"O le mea lea, e leai se tagata e mafai ona vaai i a’u galuega uma, vagana ua vaai o ia i lo’u mamalu atoa; ma e leai se tagata e mafai ona vaai i lo’u mamalu atoa, ma tumau pea i la le tino i le lalolagi."},{"verse":6,"text":"Ma ua ia te a’u se galuega mo oe, Mose e, lo’u atalii; ma ua tusa oe ma la’u Toatasi na Fanaua; ma o la’u Toatasi na Fanaua o le Faaola ma o le a avea ma Faaola, ona ua tumu o ia i le alofa tunoa ma le upumoni; peitai ua leai se isi Atua e ese mai ia te a’u, ma ua i ai mea uma i o’u luma, ona ua Ou iloa i latou uma."},{"verse":7,"text":"Ma o lenei, faauta, o le mea lenei e tasi Ou te faaali atu ia te oe, Mose e, lo’u atalii; aua o loo e i le lalolagi; ma o le a Ou faaalia atu nei ia te oe."},{"verse":8,"text":"Ma sa oo ina vaai atu Mose, ma vaai atu i le lalolagi na foafoa ai o ia i ona luga; ma sa vaaia e Mose le lalolagi ma ona tuluiga, ma le fanauga uma a tagata o i ai, ma e na foafoaina; o lea lava mea sa ofo ma maofa tele ai o ia."},{"verse":9,"text":"Ma sa oo ina afio ese le Atua mai ia Mose, sa oo ina lē i ai lona mamalu i luga o Mose; ma sa tuua Mose ia te ia lava. Ma ina ua tuua o ia ia te ia lava, sa pa’ū ifo o ia i le eleele."},{"verse":10,"text":"Ma sa oo ina faato’ā toe maua e Mose i le va o itula e tele lona malosi e masani ai e pei lava o le tagata; ma sa fai ifo o ia ia te ia lava: O lenei, ona o lenei mea ua ou iloa ai o le tagata ua le aoga o ia, o se mea ou te le’i mafaufauina lava."},{"verse":11,"text":"A’o lenei ua vaai o’u lava mata i le Atua; ae e lē o o’u mata faaletino, a’o o’u mata faaleagaga, aua sa lē mafai e o’u mata faaletino ona vaaia; po ua ou mamae ma oti i ona luma; ae sa i ai lona mamalu i o’u luga; ma sa ou vaai i ona fofoga, ona sa liua a’u i ona luma."},{"verse":12,"text":"Ma sa oo ina ua uma ona fai atu e Mose nei upu, faauta, sa alu ane Satani ma faaosooso ia te ia, ua fai mai: Mose e, le atalii o le tagata, ifo mai ia te a’u."},{"verse":13,"text":"Ma sa oo ina vaai atu Mose ia Satani ma fai atu: O ai oe? Aua faauta, o a’u o se atalii o le Atua, i le faatusa o lana Toatasi na Fanaua; ma o fea o i ai lou mamalu, e tatau ai ona ou ifo atu ia te oe?"},{"verse":14,"text":"Aua faauta, sa lē mafai ona ou vaai atu i le Atua, vagana ua oo mai lona mamalu i o’u luga, ma liua a’u i ona luma. Ae ua mafai ona ou vaai atu ia te oe i le tulaga tagata faaletino. Pe ua lē moni ea lea?"},{"verse":15,"text":"Ia faamanūina lava le suafa o lo’u Atua, ona ua lē alu ese atoa lona Agaga mai ia te a’u, a lē o lea o fea o i ai lou mamalu, aua ua pouliuli ia te a’u? Ma e mafai ona ou iloa le eseesega o oe ma le Atua; ona na fetalai mai le Atua ia te a’u: Ifo atu i le Atua, aua na’o ia lava e te auauna atu i ai."},{"verse":16,"text":"Alu ese ia oe, Satani; aua e te taufaasese mai ia te a’u; aua na fetalai mai le Atua ia te a’u: Ua tusa oe ma la’u Toatasi na Fanaua."},{"verse":17,"text":"Ma sa ia tuu mai foi ia te a’u poloaiga ina ua fetalai mai o ia ia te a’u i le laau na mu, ua fai mai: Valaau atu i le Atua i le suafa o la’u Toatasi na Fanaua, ma ifo mai ia te a’u."},{"verse":18,"text":"Ma sa toe fai atu Mose: O le a ou lē tuua le valaau atu i le Atua, ua i ai ia te a’u isi mea e ole atu ai ia te ia: aua sa i ai lona mamalu i o’u luga, o le mea lea ua mafai ai ona ou iloa le eseesega o ia ma oe. Alu ese ia ma iinei, Satani."},{"verse":19,"text":"Ma o lenei, ina ua uma ona fai atu e Mose o nei upu, sa alaga Satani ma le leo tele, ma sa leoleoā i luga o le eleele, ma faatonu mai, ua fai mai: O a’u o le Toatasi na Fanaua, ifo mai ia te a’u."},{"verse":20,"text":"Ma sa oo ina amata ona fefe tele Mose; ma ina ua amata ona fefe o ia, sa vaai o ia i le inosia o seoli. Ae ui i lea, sa maua e ia le malosi, i le valaau atu i le Atua, ma sa ia faatonu atu, e faapea: Satani, alu ese ia mai ia te a’u, aua ua na’o le Atua lenei e tasi o le a ou ifo atu i ai, o le Atua lea o le mamalu."},{"verse":21,"text":"Ma o lenei sa amata ona gatete Satani, ma sa luluina le eleele; ma sa maua e Mose le malosi, ma valaau atu i le Atua, ua fai atu: I le suafa o le Toatasi na Fanaua, alu ese ia ma iinei, Satani."},{"verse":22,"text":"Ma sa oo ina alaga Satani ma le leo tele, i le tagi, ma le tagiauē, ma le lilivau o nifo; ma sa alu ese o ia mai iina, mai luma lava o Mose, sa oo ina ia lē vaaia o ia."},{"verse":23,"text":"Ma o lenei sa molimau ai Mose i lenei mea; ae ona o le amioleaga ua lē i ai ai i totonu o le fanauga a tagata."},{"verse":24,"text":"Ma sa oo ina ua alu ese Satani mai luma o Mose, sa tepa a’e mata o Mose i le lagi, ua tumu i le Agaga Paia, lea e molimau e uiga i le Tamā ma le Alo;"},{"verse":25,"text":"Ma a’o valaau atu i le suafa o le Atua, sa toe vaaia e ia lona mamalu, aua sa i luga o ia; ma sa ia faalogoina se siufofoga, ua fetalai mai: Amuia lava oe Mose, ona o A’u, o le Malosi Aoao, na filifilia oe, ma o le a faia oe ia e malosi e sili atu nai lo vai e tele, ona o le a latou usiusitai i lau poloai e pei o oe o le Atua."},{"verse":26,"text":"Ma faauta, Ou te faatasi ma oe, e oo lava i le iuga o ou aso; aua o le a e laveai lo’u nuu mai le nofopologa, o Isaraelu lava lea ua ou filifilia."},{"verse":27,"text":"Ma sa oo ina a’o fetalai mai pea le siufofoga, sa tepa atu mata o Mose ma vaai atu i le lalolagi, ioe, le lalolagi atoa lava; ma sa leai sona vaega itiiti sa lei vaaia e ia, ma iloatino ai e ala i le Agaga o le Atua."},{"verse":28,"text":"Ma sa vaai foi o ia i e o nonofo ai, ma sa leai se agaga sa lei vaaia e ia; ma sa iloa e ia i latou e ala i le Agaga o le Atua; ma o o latou aofai sa matua toatele lava, sa lē mafaitaulia lava e pei o le oneone o le matafaga."},{"verse":29,"text":"Ma sa ia vaai i laueleele e tele; ma sa ta’ua ia laueleele taitasi o lalolagi, ma sa i ai ni isi sa nonofo ai."},{"verse":30,"text":"Ma sa oo ina valaau atu Mose i le Atua, ua faapea atu: Ou te ole atu ia te oe, sei ta’u mai ia te a’u, pe aisea ua faapea ona i ai o ia mea, ma o a mea na e faia ai i latou?"},{"verse":31,"text":"Ma faauta, sa i luga o Mose le mamalu o le Alii, o lea na tulai ai Mose i luma o le Atua, ma talanoa faafesagai ma ia. Ma sa fetalai mai le Alii le Atua ia Mose: E mo la’u lava fuafuaga na Ou faia ai nei mea. O le poto lenei ma e tumau pea ia te a’u."},{"verse":32,"text":"Ma o le upu a lo’u mana, na Ou foafoa ai i latou, o ia lea o lo’u Atalii Pele e Toatasi, o lē ua tumu i le alofa tunoa ma le upumoni."},{"verse":33,"text":"Ma e lē mafaitaulia lalolagi ua Ou foafoaina; ma sa Ou foafoaina foi i latou mo lo’u lava faamoemoe; ma o lo’u Atalii Pele e Toatasi, na Ou foafoaina ai i latou."},{"verse":34,"text":"Ma o le uluai tagata o tagata uma ua Ou faaigoaina o Atamu, o lona uiga e toatele."},{"verse":35,"text":"Ae ua na’o se tala o le lalolagi lenei, ma e o nonofo ai, Ou te tuu atu ia te oe. Aua faauta, e i ai lalolagi e tele ua mavae atu e ala i le upu a lo’u mana. Ma e i ai le tele o loo tutu nei, ma ua lē mafaitaulia i latou i le tagata; ae ua faitaulia mea uma ia te a’u, aua e a a’u i latou ma ua Ou iloa i latou."},{"verse":36,"text":"Ma sa oo ina fai atu Mose i le Alii, ua faapea atu: Ia e alofa mutimutivale mai i lau auauna, E, le Atua e, ma ta’u mai ia te a’u e uiga i le lalolagi lenei, ma e o nonofo ai, ma le lagi foi, ona malie ai lea o lau auauna."},{"verse":37,"text":"Ma sa fetalai mai le Alii le Atua ia Mose, ua fai mai: O lagi, e tele, ma e lē mafai ona faitaulia i latou i le tagata; ae ua faitaulia i latou ia te a’u, ona e a a’u i latou."},{"verse":38,"text":"Ma e pei ona o le a mavae atu le tasi lalolagi, ma ona lagi o le a faapea foi ona tulai mai se isi; ma e leai se gataaga i a’u galuega, e pei o a’u upu."},{"verse":39,"text":"Aua faauta, o la’u galuega ma lo’u mamalu lenei—ia aumaia le tino ola pea ma le ola faavavau o le tagata."},{"verse":40,"text":"Ma o lenei, Mose e, lo’u atalii, o le a Ou tautala atu ia te oe e uiga i le lalolagi lenei o loo e tulai ai; ma ia e tusia mea o le a Ou tautala atu ai."},{"verse":41,"text":"Ma i se aso e manatu ai le fanauga a tagata i a’u upu o ni meanoa ma aveese le tele o i latou mai le tusi o le a e tusia, faauta, o le a Ou faatulai mai se tasi e pei o oe; ma o le a toe i ai ia mea i totonu o le fanauga a tagata—i totonu o le toatele o e e talitonu."},{"verse":42,"text":"(O upu nei na tulei mai ia Mose i le mauga, o lona igoa o le a lē iloa i totonu o le fanauga a tagata. Ma o lenei ua fetalaia atu ia te oe. Aua ne’i faaali atua i soo se tasi vagana ai i latou o e e talitonu. E faapea lava. Amene.)"}]},{"chapter":2,"verses":[{"verse":1,"text":"Ma sa oo ina fetalai mai le Alii ia Mose, ua fai mai: Faauta, Ou te faaali atu ia te oe e uiga i le lagi lenei, ma le lalolagi lenei; ia tusi upu o le a Ou tautala atu ai. O A’u o le Amataga ma le Gataaga, le Atua Malosi Aoao; o la’u Toatasi na Fanaua na Ou foafoa ai ia mea; ioe, na Ou foafoaina i le amataga le lagi, ma le lalolagi ua e tu ai."},{"verse":2,"text":"Ma sa aunoa le lalolagi ma se faatulagaga, ma sa gaogao; ma sa Ou faia le pouliuli ia oo mai i luga o le moana; ma sa fegaoioiai lo’u Agaga i luga o le fogatai; aua o A’u o le Atua."},{"verse":3,"text":"Ma o A’u, o le Atua, na Ou fai atu: Ia i ai le malamalama; ma sa i ai le malamalama."},{"verse":4,"text":"Ma o A’u, o le Atua, sa vaai atu i le malamalama; ma ua lelei lena malamalama. Ma o A’u, o le Atua, na vavaeeseina le malamalama mai le pouliuli."},{"verse":5,"text":"Ma o A’u, o le Atua, na ta’ua le malamalama o le Ao; ma o le pouliuli, sa Ou ta’ua o le Po; ma o lenei mea sa Ou faia i le upu a lo’u mana, ma sa faia lava e pei ona sa Ou fai atu ai; ma o le afiafi ma le taeao o le aso muamua lea."},{"verse":6,"text":"Ma sa toe fai atu A’u, o le Atua: Ia i ai se vanimonimo i le lotolotoi o le vai, ma sa faapea ona fai, e pei lava ona Ou fai atu; ma sa Ou fai atu: Ia tuu atu e vavae ai vai mai vai; ma sa faia lava;"},{"verse":7,"text":"Ma o A’u, o le Atua, na faia le vanimonimo ma vaevaeina vai, ioe, vai tetele i lalo o le vanimonimo mai vai sa i luga o le vanimonimo, ma sa faapea lava e pei ona sa Ou fai atu ai."},{"verse":8,"text":"Ma o A’u, le Atua, na ta’ua le vanimonimo o le Lagi; ma o le afiafi ma le taeao o le aso lua lea."},{"verse":9,"text":"Ma o A’u, o le Atua, na Ou fai atu: Ia tuu atu i vai o i lalo ifo o le lagi ia faapotopoto faatasi i se mea e tasi, ma sa faapea lava; ma o A’u, o le Atua, na Ou fai atu: Ia i ai se laueleele matutu; ma sa faapea lava."},{"verse":10,"text":"Ma o A’u, o le Atua, na Ou ta’ua le laueleele matutu o le Eleele; ma o le faapotopotoina faatasi o vai, na Ou ta’ua o le Sami; ma o A’u, o le Atua, sa Ou vaai atu o mea uma sa Ou faia ua lelei."},{"verse":11,"text":"Ma o A’u, o le Atua, sa Ou fai atu: Ia tuu atu i le eleele ia faatutupu mai mutia, le laau afu ia fua mai i fatu, ma le laau ’aina ia fua mai i fua, e tusa ma lona ituaiga, ma le laau fua ia fua mai i fua, o ona fatu e tatau ona i ai ia te ia lava i luga o le eleele, ma sa faapea lava e pei ona sa Ou fai atu."},{"verse":12,"text":"Ma sa aumai e le eleele le mutia, laau afu uma e fua i fatu e tusa ma lona ituaiga, ma le laau e fua mai i fua, o ona fatu ua i totonu o ia lava, e tusa ma lona ituaiga; ma o A’u, o le Atua, sa Ou vaai atu ua lelei mea uma ua Ou faia;"},{"verse":13,"text":"Ma o le afiafi ma le taeao o le aso tolu lea."},{"verse":14,"text":"Ma o A’u, o le Atua, na Ou fai atu: Ia i ai ni malamalama i le vanimonimo o le lagi, e vavae ai le ao mai le po, ma ia tuu i latou e avea ma faailoga, ma mo tau, ma mo aso, ma mo tausaga;"},{"verse":15,"text":"Ma ia tuu i latou e avea ma malamalama i le vanimonimo o le lagi e tuu atu ai le malamalama i luga o le lalolagi; ma sa faapea lava."},{"verse":16,"text":"Ma o A’u, o le Atua, na faia ni malamalama tetele e lua; o le malamalama tele e pulea le ao, ma le malamalama itiiti e pulea le po, ma o le malamalama tele o le la, ma o le malamalama itiiti o le masina; ma sa faia foi fetu e tusa lava ma la’u upu."},{"verse":17,"text":"Ma o A’u, o le Atua, na tuua i laua i le vanimonimo o le lagi e tuu mai ai le malamalama i luga o le lalolagi,"},{"verse":18,"text":"Ma o le la e pule i le ao, ma le masina e pule i le po, ma vavae ai le malamalama mai le pouliuli; ma o A’u, o le Atua, na vaai atu ua lelei mea uma ua Ou faia;"},{"verse":19,"text":"Ma o le afiafi ma le taeao o le aso fa lea."},{"verse":20,"text":"Ma o A’u, o le Atua, na faapea atu: Ia tuu atu i vai ia aumai ia matua tele meaola fegaoioiai ua i ai le ola, ma manufelelei e mafai ona felelei i luga a’e o le lalolagi i le vanimonimo taalaelae o le lagi."},{"verse":21,"text":"Ma o A’u, o le Atua, na foafoaina tafola tetele, ma meaola uma e gaoioi, sa tele ona aumai e vai, e tusa ma o latou ituaiga, ma manufelelei faiapaau taitasi e tusa ma lona ituaiga; ma o A’u, o le Atua, sa Ou vaai atu ua lelei mea uma ua Ou foafoaina."},{"verse":22,"text":"Ma o A’u, o le Atua, sa faamanuiaina i latou, ua fai atu: Ia uluola, ma faateleina, ma faatumu ai vai i le sami; ma ia tuu atu i manufelelei ia faateleina i le lalolagi;"},{"verse":23,"text":"Ma o le afiafi ma le taeao o le aso lima lea."},{"verse":24,"text":"Ma o A’u, o le Atua, na fai atu: Ia tuu atu i le eleele e aumai meaola e tusa ma lona ituaiga, o manu faatoaga, ma mea fetolofi, ma manu vaefa o le lalolagi e tusa ma o latou ituaiga; ma sa faapea lava;"},{"verse":25,"text":"Ma o A’u, o le Atua, na faia manu vaefa o le lalolagi e tusa ma o latou ituaiga, ma manu faatoaga e tusa ma o latou ituaiga; ma mea fetolofi taitasi uma i luga o le lalolagi e tusa ma lona ituaiga; ma o A’u, o le Atua, na vaai atu ua lelei ia mea uma."},{"verse":26,"text":"Ma o A’u, o le Atua, na faapea atu i la’u Toatasi na Fanaua, lea sa faatasi ma A’u mai le amataga: Inā ta faia ia o le tagata i lo ta’ua faatusa, e tusa ma o ta’ua foliga; ma sa faapea lava. Ma o A’u, o le Atua, na faapea atu: Ia tuu atu ia te i laua e pule i i’a o le sami, ma manufelelei o le ea, ma lafu manu, ma le lalolagi atoa, ma mea fetolofi uma e fetolofi i luga o le lalolagi."},{"verse":27,"text":"Ma o A’u, o le Atua, na foafoaina le tagata i lo’u lava faatusa, o le faatusa o la’u Toatasi na Fanaua na Ou foafoaina ai o ia; o le tane ma le fafine na Ou foafoaina ai i laua."},{"verse":28,"text":"Ma o A’u, o le Atua, na faamanuiaina i laua, ma faapea atu ia te i laua: Ia fanafanau, ma uluuluola, ma faatumuina le lalolagi, ma faato’a i ai, ma ia pule i i’a o le sami, ma manufelelei o le ea, ma meaola uma e fegaoioia’i i le lalolagi."},{"verse":29,"text":"Ma o A’u, o le Atua, sa faapea atu i le tagata: Faauta, ua Ou tuu atu ia te oe laau afu uma e fua i fatu, ia ua i le lalolagi atoa, ma laau uma e i ai fua o laau e fua i fatu; ia avea ia ma meaai ia te oe."},{"verse":30,"text":"Ma o manuvaefa uma o le lalolagi, ma manufelelei uma o le ea, ma mea uma e fetolofi i le lalolagi, ua Ou tuuina i ai le ola, o le a tuu atu i ai laau afu mama uma mo meaai; ma sa faapea lava, e pei ona sa Ou fai atu ai."},{"verse":31,"text":"Ma o A’u, o le Atua, na vaai atu i mea uma na Ou faia, ma, faauta, o mea uma na Ou faia sa lelei tele lava; ma o le afiafi ma le taeao o le aso ono lea."}]},{"chapter":3,"verses":[{"verse":1,"text":"Sa faapea ona mae’a o le lagi ma le lalolagi, ma ’au uma o i latou."},{"verse":2,"text":"Ma o le aso fitu na faagata ai e A’u, o le Atua, la’u galuega, ma mea uma na Ou faia; ma sa Ou malolo i le aso lona fitu mai la’u galuega atoa, ma o mea uma sa Ou faia ua mae’a, ma o A’u, o le Atua, sa Ou vaai atu ua lelei i latou;"},{"verse":3,"text":"Ma o A’u, o le Atua, sa Ou faamanuiaina le aso fitu, ma faapaiaina; aua o le aso lea na Ou malolo ai mai a’u galuega uma lea na foafoa ma faia e A’u, o le Atua."},{"verse":4,"text":"Ma o lenei, faauta, Ou te fai atu ia te oe, o vaevaega ia o le lagi ma le lalolagi, ina ua foafoaina i latou, i le aso na faia ai, e A’u, o le Alii le Atua, le lagi ma le lalolagi,"},{"verse":5,"text":"Ma laau taitasi o le fanua ae lei i ai i le lalolagi, ma laau afu taitasi o le fanua ae lei tupu mai. Aua o A’u, o le Alii le Atua, na foafoaina faaleagaga mea uma, ia ua Ou fai atu ai, ae lei i ai faaletino i latou i luga o le fogaeleele. Aua e lei faia e A’u, o le Alii le Atua, ia timu i luga o le fogaeleele. Ma o A’u, o le Alii le Atua, na foafoaina le fanauga uma a tagata; ma sa lei i ai se tagata e galueaiina le eleele; aua sa Ou foafoaina i latou i le lagi; ma sa lei i ai se tino aano i le lalolagi, po o le vai, po o le ea;"},{"verse":6,"text":"Peitai o A’u, o le Alii le Atua, sa Ou fai atu, ona alu a’e ai lea se puao mai le lalolagi, ma faasūsū ai le eleele atoa."},{"verse":7,"text":"Ma o A’u, o le Alii le Atua, na faia le tagata mai le efuefu o le eleele, ma mānava i ona pogaiisu le mānava o le ola; ma sa avea ai le tagata o se tagata ola, o le tino aano muamua lea i luga o le lalolagi, o le tagata muamua foi; ae ui i lea, o mea uma sa foafoaina muamua; ae sa foafoaina faaleagaga i latou ma faia e tusa ma la’u upu."},{"verse":8,"text":"Ma o A’u, o le Alii le Atua, na totoina se faatoaga i sasa’e i Etena, ma o iina na Ou tuuina ai le tagata na Ou faia."},{"verse":9,"text":"Ma o A’u, o le Alii le Atua, na faia ia tutupu mai, faaletino, mai le eleele, laau uma e matagofie i le vaai a le tagata; ma sa mafai ona vaai i ai le tagata. Ma sa avea foi o se tagata ola. Ona sa faaleagaga i le aso na Ou foafoaina ai; aua ua tumau i le siosiomaga na foafoa ai e A’u, o le Atua, ioe, e oo i mea uma lava na Ou saunia mo le faaaogaina e le tagata; ma sa iloa e le tagata ua lelei mo meaai. Ma o A’u, o le Alii le Atua, sa totoina foi le laau o le ola i le totonugalemu o le faatoaga, ma le laau foi e iloa ai le lelei ma le leaga."},{"verse":10,"text":"Ma o A’u, o le Alii le Atua, na faia se vaitafe ia tafe atu i fafo mai Etena e faasūsū ai le faatoaga; ma sa vavaeina mai ai iina, ma avea ma ni vaitafe autu e fa."},{"verse":11,"text":"Ma o A’u, o le Alii le Atua, na faaigoaina le igoa o le muamua o Pisona, ma sa tafe taamilo atu i le laueleele atoa o Havila, i lea mea, na foafoa ai e A’u, o le Alii le Atua, auro e tele;"},{"verse":12,"text":"Ma sa lelei le auro o lena laueleele, ma sa i ai le petala ma maa soama."},{"verse":13,"text":"Ma o le igoa o le vaitafe lona lua sa ta’ua o Kaiona; o lea lava ua taamilo i le laueleele atoa o Aitiope."},{"verse":14,"text":"Ma o le igoa o le vaitafe lona tolu o Hitekelu; o lena lea na alu atu agai i sasa’e o Asuria. Ma o le vaitafe lona fa o le Eufirate."},{"verse":15,"text":"Ma sa ave e A’u, o le Alii le Atua, le tagata, ma tuu o ia i le Faatoaga o Etena, e galueaiina, ma ia tausia."},{"verse":16,"text":"Ma o A’u, o le Alii le Atua, na poloaiina le tagata, ua fai atu: O laau uma o le faatoaga e mafai ona e ’ai saoloto ai,"},{"verse":17,"text":"Ae o le laau e iloa ai le lelei ma le leaga, aua e te ’ai ai; ae ui i lea, e mafai ona e filifili mo oe lava, ona ua tuuina atu ia te oe; peitai, ia manatua ua Ou faasaina, aua o le aso e te ’aia ai e te oti moni ai lava."},{"verse":18,"text":"Ma o A’u, o le Alii le Atua, na faapea atu i la’u Toatasi na Fanaua, e lē lelei ona nofo toatasi o le tagata; o le mea lea, o le a Ou faia ai se fesoasoani e talafeagai mo ia."},{"verse":19,"text":"Ma na faia e A’u, o le Alii le Atua, mai le eleele, manu vaefa uma o le fanua, ma manufelelei uma o le ea; ma poloaiina ia latou o mai ia Atamu, e vaai po o a igoa o le a ia faaigoa ai i latou; sa o ni mea ola foi i latou; aua sa mānava atu e A’u, o le Atua, ia te i latou le mānava o le ola, ma poloaiina o soo se mea e faaigoa ai e Atamu mea ola taitasi, o lona igoa lava lena."},{"verse":20,"text":"Ma sa tuu atu e Atamu igoa i lafu manu uma, ma manufelelei o le ea, ma manu vaefa uma o le fanua; ae o Atamu, sa lei maua se fesoasoani e talafeagai mo ia."},{"verse":21,"text":"Ma o A’u, o le Alii le Atua, na faia ia oo mai se moe gase i luga o Atamu; ma sa moe o ia, ma sa Ou to mai se tasi o ona ivi ’aso’aso ma faasoo le aano i lona tulaga;"},{"verse":22,"text":"Ma o le ivi ’aso’aso na to mai e A’u, o le Alii le Atua, mai le tane, na Ou faia ai se fafine, ma aumai o ia i le tane."},{"verse":23,"text":"Ma sa fai mai Atamu: Ua ou iloa nei o le ivi lenei o o’u ivi, ma le aano o o’u aano; o le a ta’ua o ia o le Fafine, aua sa to mai fafo o ia mai le tane."},{"verse":24,"text":"O lea e tu’ua ai e se tane lona tamā ma lona tinā, ma o le a pipii atu i lana ava; ma o le a avea i laua ma tino e tasi."},{"verse":25,"text":"Ma sa lē lavalavā i laua uma, o le tane ma lana ava, sa lē maasiasi foi i laua."}]},{"chapter":4,"verses":[{"verse":1,"text":"Ma o A’u, o le Alii le Atua, na fai atu ia Mose, ua faapea atu: O Satani lena, o lē na e faatonu i le suafa o la’u Toatasi na Fanaua, o ia lava lea sa i ai mai le amataga, ma sa sau o ia i o’u luma, ma fai mai—Faauta, o a’u lenei, auina atu a’u, o le a avea a’u mo ou atalii, ma o le a ou laveaiina tagata uma, ina ia leai se agaga e toatasi e se ese, ma e moni lava o le a ou faia lena mea; o le mea lea, ia tuu mai ia te a’u lou mamalu."},{"verse":2,"text":"Ae, faauta, o lo’u Atalii Pele, o lē o la’u Pele ma Filifilia mai le amataga, na fai mai ia te a’u—Le Tamā e, ia faia lou finagalo, ma e a oe pea le mamalu e faavavau."},{"verse":3,"text":"O le mea lea, ona sa fouvale Satani ia te a’u, ma saili e faaumatia le faitalia a le tagata, lea na tuu atu e A’u, o le Alii le Atua ia te ia, ma lea foi, ia Ou avatu ia te ia lo’u lava mana; i le mana o la’u Toatasi na Fanaua, na Ou faia ai ia lafoaiina i lalo o ia;"},{"verse":4,"text":"Ma sa avea o ia ma Satani, ioe, o le tiapolo lava lea, o le tamā o pepelo uma, e faasese ma faatauaso tagata, ma taitai faatagataotaua i latou i lona loto, le toatele lava lea o i latou o e e lē faalogo mai i lo’u leo."},{"verse":5,"text":"Ma o lenei sa sili atu le atamai o le gata nai lo soo se isi o manu vaefa uma o le fanua ia na faia e A’u, o le Alii le Atua."},{"verse":6,"text":"Ma sa tuu e Satani i le loto o le gata, (ona e toatele na ia taitai ese ia mulimuli atu ia te ia,) ma sa saili foi o ia e faasese Eva, aua sa lē iloa e ia le mafaufau o le Atua, o le mea lea na saili ai o ia e faaumatia le lalolagi."},{"verse":7,"text":"Ma sa fai atu o ia i le fafine: Ioe, na fetalai mai ea le Atua—Aua lua te aai i laau uma o le faatoaga? (Ma sa tautala mai o ia i le gutu o le gata.)"},{"verse":8,"text":"Ma sa fai atu le fafine i le gata: E mafai ona ma aai i fua o laau uma o le faatoaga;"},{"verse":9,"text":"Ae o le fua o le laau lena ua e vaai atu i ai o i le totonugalemu o le faatoaga, na fetalai mai le Atua—Aua e te lua aai ai, pe e te lua pa’i atu i ai, ne’i oti ai oulua."},{"verse":10,"text":"Ma sa fai atu le gata i le fafine: Lua te lē oti lava;"},{"verse":11,"text":"Aua ua silafia e le Atua o le aso lua te aai ai, ona pupula ai lea o oulua mata, ma o le a avea ai oulua e pei o ni atua, e iloa le lelei ma le leaga."},{"verse":12,"text":"Ma ina ua vaai atu le fafine ua lelei le laau mo meaai, ma ua matagofie i le vaai, ma o se laau ua manaomia e faapoto ai o ia, sa ave e ia lona fua, ma ’ai, ma sa avatu foi e ia i lana tane faatasi ma ia, ma sa ai ai foi o ia."},{"verse":13,"text":"Ma sa pupula mata o i laua uma, ma sa la iloa sa laua lē lavalavā. Ma sa la su’i faatasi lau o le mati ma fai ni ufiufi mo i laua lava."},{"verse":14,"text":"Ma sa la faalogoina le siufofoga o le Alii le Atua, a’o la savalivali i le faatoaga, i le mālū o le aso; ma sa o atu Atamu ma lana ava e faalalafi i laua lava mai luma o le Alii le Atua i totonu o laau o le faatoaga."},{"verse":15,"text":"Ma o A’u, o le Alii le Atua, na valaau atu ia Atamu, ma fai atu ia te ia: O fea ua e alu i ai?"},{"verse":16,"text":"Ma sa tali mai o ia: Sa ou faalogoina lou siufofoga i le faatoaga, ma sa ou fefe, aua sa ou vaai ua ou le lavalavā, ma sa ou lafi ai."},{"verse":17,"text":"Ma o A’u, o le Alii le Atua, na fai atu ia Atamu: O ai na fai atu ia te oe ua e lē lavalavā? Ua e ’ai i le laau na Ou poloaiina ai oe e aua e te ’ai ai, afai e te ’ai ai o le a e oti lava?"},{"verse":18,"text":"Ma sa fai mai le tane: O le fafine na e aumai ia te a’u, ma poloaiina ia mau faatasi ma au, na ia aumai ia te au le fua o le laau ma na ou ’ai ai."},{"verse":19,"text":"Ma o A’u, o le Alii le Atua, na faapea atu i le fafine: O le a lenei mea ua e faia? Ma sa fai mai le fafine: Na faasese au e le gata, ma na ou ’ai ai."},{"verse":20,"text":"Ma o A’u, o le Alii le Atua, na fai atu i le gata: Ona ua e faia lenei mea o le a sili ona fetuuina oe i lo manu faatoaga uma, ma manu vaefa uma o le fanua; o lou manava o le a e sosolo ai, ma o le efuefu o le a e ’ai i aso uma o lou ola;"},{"verse":21,"text":"Ma o le a Ou tuu le feitagai i le va o oe ma le fafine, i le va o lau fanau ma lana fanau; ma o le a ia faamanu’alia lou ulu, ma o le a e faamanu’alia lona mulivae."},{"verse":22,"text":"I le fafine, o A’u, o le Alii le Atua, na faapea atu i ai: O le a Ou matuā faateleina lou tiga ma lou ma’itaga. O le a e fanau mai fanau ma le tiga, ma o lou manao o le a ua’i atu i lau tane, ma o le a pulea oe e ia."},{"verse":23,"text":"Ma ia Atamu, o A’u, o le Alii le Atua, na fai atu i ai: Ona sa e faalogo i le leo o lau ava, ma ’ai i le fua o le laau na Ou poloaiina oe, e faapea—Aua e te ’ai ai, o le a fetuuina le eleele ona o oe; o le tiga o le a e ’ai mai ai i aso uma o lou ola."},{"verse":24,"text":"O laau tuitui foi, ma laau talatala o le a ia aumai ia te oe, ma o le a e ’ai laau afu o le fanua."},{"verse":25,"text":"O le a e ’ai ai au meaai ma le afu o ou mata, seia e toe foi i le eleele—aua o le a e oti lava—ona o le eleele na aumai ai oe: o le efuefu oe, ma o le a e toe foi lava i le efuefu."},{"verse":26,"text":"Ma sa faaigoa e Atamu lana ava o Eva, aua o ia o le tinā o tagata ola uma; ona sa faapea ona faaigoa e A’u, o le Alii le Atua, le uluai fafine o fafine uma, e toatele."},{"verse":27,"text":"Ma sa faia e A’u, o le Alii le Atua, ofu pa’u manu, mo Atamu ma lana ava foi, ma faaoofu ai i laua."},{"verse":28,"text":"Ma o A’u, o le Alii le Atua, na fai atu i la’u Toatasi na Fanaua: Faauta, ua avea le tagata e pei o se tasi o i tatou e iloa le lelei ma le leaga; ma o lenei ne’i tuu atu lona lima ma ’ai foi i le laau o le ola, ma ’ai ma ola ai e faavavau,"},{"verse":29,"text":"O lea, o A’u, o le Alii le Atua, o le a auina ese atu o ia mai le Faatoaga o Etena, e galueaiina le eleele na aumai ai o ia;"},{"verse":30,"text":"Auā e pei ona ola A’u, o le Alii le Atua, ua faapea foi ona lē mafai ona foi aunoa mai a’u upu, ona e pei ona o atu i latou mai lo’u gutu o le a faapea lava ona faataunuuina i latou."},{"verse":31,"text":"O lea na Ou tuli ese ai i fafo le tagata, ma sa Ou tuu i le itu i sasa’e o le Faatoaga o Etena, kerupi ma se pelu afi mumu, sa feliuliuai i itu uma e leoleo le ala o le laau o le ola."},{"verse":32,"text":"(Ma o upu nei na Ou tautala atu ai i la’u auauna o Mose, ma ua moni i latou e pei lava ona Ou loto i ai; ma ua Ou tautala atu i latou ia te oe. Vaai ia e lē faaalia atu i latou i se tagata, seia ou poloaiina ai oe, vagana ia i latou o e e talitonu. Amene.)"}]},{"chapter":5,"verses":[{"verse":1,"text":"Ma sa oo ina ua mavae ona tutuli ese o i laua e A’u, o le Alii le Atua, sa amata ona galueaiina e Atamu le eleele, ma pule i manu vaefa uma o le fanua, ma ’ai ana meaai ma le afu o lona muaulu, e pei ona poloaiina ai o ia e A’u o le Alii. Ma sa galue foi Eva, lana ava, faatasi ma ia."},{"verse":2,"text":"Ma sa iloa e Atamu lana ava, ma sa fanau e ia ia te ia o atalii ma afafine, ma sa amata ona latou fanafanau ma uluuluola i le lalolagi."},{"verse":3,"text":"Ma e mai lena taimi ma agai atu i le lumanai, sa amata ona vaevae taitoalua o atalii ma afafine o Atamu i le laueleele, ma e galueaiina le laueleele, ma tausi lafu manu, ma sa latou fananauina foi atalii ma afafine."},{"verse":4,"text":"Ma o Atamu ma Eva, lana ava, sa valaau atu i le suafa o le Alii, ma sa laua faalogoina le siufofoga o le Alii mai le ala agai i le Faatoaga o Etena, ua fetalai mai ia i laua, ae sa laua lē vaai atu ia te ia; aua sa punitia i laua mai ona luma."},{"verse":5,"text":"Ma sa tuu mai e ia ia i laua poloaiga, ia la tapuai atu i le Alii lo laua Atua, ma ofoina atu uluai manu o a laua lafu, mo se taulaga i le Alii. Ma sa usiusitai Atamu i poloaiga a le Alii."},{"verse":6,"text":"Ma ina ua mavae aso e tele, sa oo mai se agelu a le Alii ia Atamu, ua fetalai mai: Aisea ua e osi atu ai taulaga i le Alii? Ma sa fai atu Atamu ia te ia: Ou te lē iloa, ae na poloaiina ai a’u e le Alii."},{"verse":7,"text":"Ma ona fetalai mai lea o le agelu, e faapea mai: O lenei mea o se faatusa lea o le taulaga a le Toatasi na Fanaua e le Tamā, o lē ua tumu i le alofa tunoa ma le upumoni."},{"verse":8,"text":"O le mea lea, ia e faia mea uma e te faia i le suafa o le Alo, ma ia e salamo ma valaau atu i le Atua i le suafa o le Alo e faavavau."},{"verse":9,"text":"Ma i lena aso na afio ifo ai le Agaga Paia i luga o Atamu, o lē e molimau i le Tamā ma le Alo, ua fetalai mai: O A’u o le Toatasi na Fanaua e le Tamā mai le amataga, mai le taimi nei ma le agai i luma ma le faavavau, aua talu ai ona ua e pa’ū ia mafai ona laveaiina oe, ma tagata uma, le toatele lava e mananao i ai."},{"verse":10,"text":"Ma i lena aso na viia ai e Atamu le Atua ma sa faatumuina, ma sa amata ona vavalo e uiga i aiga uma o le lalolagi, ua fai mai: Ia viia lava le suafa o le Atua, aua ona o la’u solitulafono ua pupula ai o’u mata, ma o le a ou maua i le olaga lenei le olioli, ma o le a ou toe vaai i le Atua i le tino."},{"verse":11,"text":"Ma o Eva, lana ava, sa faalogo atu i nei mea uma ma sa fiafia, ua fai mai: Ana lē seanoa la ta solitulafono po ua lē maua e i taua ni fanau, ma po ua lē mafai ona ta iloa le lelei ma le leaga, ma le olioli o le togiolaina o i ta’ua, ma le ola e faavavau ua tuu mai e le Atua ia i latou uma o e e usiusitai."},{"verse":12,"text":"Ma sa viia e Atamu ma Eva le suafa o le Atua, ma sa la faailoa atu mea uma i o laua atalii ma afafine."},{"verse":13,"text":"Ona sau ai lea o Satani i totonu o i latou, ua fai mai: O a’u foi o se atalii o le Atua; ma sa ia faatonu mai ia te i latou, ua fai mai: Aua tou te talitonu i ia mea; ma sa latou lē talitonu i ai, ma sa sili atu lo latou alolofa ia Satani nai lo le Atua. Ma e sa amata mai i lena taimi ma agai atu i le lumanai ona faaletino, faalelagona, ma faatiapolo tagata."},{"verse":14,"text":"Ma sa valaau atu le Alii le Atua i tagata uma i soo se mea e ala i le Agaga Paia ma poloaiina i latou e ao ina latou salamo;"},{"verse":15,"text":"Ma o le toatele sa talitonu i le Alo, ma salamo i a latou agasala, o le a faaolaina; ma o le toatele sa lē talitonu ma lē salamo, o le a tausalaina; ma sa tulei atu afioga mai le fofoga o le Atua i se poloaiga mau; o le mea lea, o le a faataunuuina lava i latou."},{"verse":16,"text":"Ma o Atamu ma Eva, lana ava, sa lē tu’ua le valaau atu i le Atua. Ma sa iloa e Atamu lana ava o Eva, ma sa to o ia ma fanauina Kaino, ma sa fai mai: Ua ou maua se tama tane mai le Alii; o le mea lea o le a lē mafai ai e ia ona teena ana afioga. Ae faauta, sa lē faalogo Kaino, ua fai mai: O ai le Alii e tatau ai ona ou iloa o ia?"},{"verse":17,"text":"Ma sa toe to Eva ma fanauina lona uso o Apelu. Ma sa faalogo Apelu i le siufofoga o le Alii. Ma o Apelu sa leoleo mamoe, ae o Kaino sa galueaiina le fanua."},{"verse":18,"text":"Ma sa sili atu le alofa o Kaino ia Satani nai lo le Atua. Ma sa faatonu o ia e Satani, ua fai atu: Fai se taulaga i le Alii."},{"verse":19,"text":"Ma i le gasologa o taimi, sa oo ina aumai e Kaino mai fua o le eleele se taulaga i le Alii."},{"verse":20,"text":"Ma o Apelu, sa aumai foi e ia mai ulua’i manu o lana lafu, ma le ga’o o i ai. Ma sa aloaia e le Alii Apelu, ma lana taulaga;"},{"verse":21,"text":"Ae o Kaino, ma lana taulaga, sa lē aloaia e le Alii. O lenei sa iloa e Satani lenei mea, ma sa fiafia i ai o ia. Ma sa ita tele Kaino, ma sa faa’ū’ū o ia."},{"verse":22,"text":"Ma sa fetalai mai le Alii ia Kaino: Aisea ua e ita ai? Aisea ua e faa’ū’ū ai?"},{"verse":23,"text":"Afai e te faia mea lelei, e talia oe. Ma afai e te lē faia mea lelei, ua taoto mai le agasala i le faitotoa, ma ua manao Satani ia maua oe; ma vagana ua e faalogo mai i a’u poloaiga, o le a Ou tuu atu oe, ma o le a faia ia te oe e tusa ma lona manao. Ma o le a e pule ia te ia;"},{"verse":24,"text":"Aua e mai le taimi nei i luma o le a avea oe ma tamā o ana pepelo; o le a ta’ua oe o le Malaia; aua sa e faapea foi ae le’i i ai le lalolagi."},{"verse":25,"text":"Ma o le a faapea ane i taimi e oo mai—E faapea o nei mea inosia na mai ia Kaino; ona sa teena e ia le fautuaga sili na mai le Atua; ma o se fetuu lenei o le a Ou tuu i luga o oe, vagana ai ua e salamo."},{"verse":26,"text":"Ma sa ita Kaino, ma sa lē toe faalogo i le siufofoga o le Alii, po o Apelu, lona uso, o lē na savali i le paia i luma o le Alii."},{"verse":27,"text":"Ma sa faanoanoa Atamu ma lana ava i luma o le Alii, ona o Kaino ma ona uso."},{"verse":28,"text":"Ma sa oo ina ave e Kaino se tasi o afafine o ona uso ma ana ava, ma sa sili atu lo laua alolofa ia Satani nai lo le Atua."},{"verse":29,"text":"Ma sa fai atu Satani ia Kaino: Tauto mai ia te a’u i lou fa’aī, ma afai e te ta’ua o le a e oti; ma ia faatauto ou uso i o latou ulu, ma i le Atua soifua, ia latou le ta’ua; ona afai latou te ta’ua, o le a latou feoti lava; ma o lenei ina ia lē iloa e lou tamā; ma o le aso nei o le a ou tuu atu ai lou uso o Apelu i ou lima."},{"verse":30,"text":"Ma sa tauto Satani ia Kaino o le a faia e ia e tusa ma ana poloaiga. Ma o nei mea uma sa faia faalilolilo."},{"verse":31,"text":"Ma sa fai mai Kaino: E moni lava o a’u o Mahana, o le pule o lenei mealilo tele, ina ia mafai ona ou fasioti ma maua mea. O le mea lea na ta’ua ai Kaino o Mahana Pule, ma sa mitamita o ia i lana amioleaga."},{"verse":32,"text":"Ma sa alu atu Kaino i le fanua, ma sa talanoa Kaino ma Apelu, lona uso. Ma sa oo a’o i ai i laua i le fanua, sa tulai atu Kaino e faasaga ia Apelu, lona uso, ma fasioti ia te ia."},{"verse":33,"text":"Ma sa mitamita Kaino i le mea ua ia faia, ua fai mai: Ua ou saoloto; e moni lava o lafu a lo’u uso ua i o’u lima."},{"verse":34,"text":"Ma sa fetalai mai le Alii ia Kaino: O fea Apelu, lou uso? Ma sa fai atu o ia: Ou te lē iloa. O a’u ea o se leoleo o lo’u uso?"},{"verse":35,"text":"Ma sa fetalai mai le Alii: O le a le mea ua e faia? Ua tagi mai ia te a’u le leo o le toto o lou uso mai le eleele."},{"verse":36,"text":"Ma o lenei o le a fetuuina oe mai le eleele ua faamaga mai lona gutu e tali le toto o lou uso mai lou lima."},{"verse":37,"text":"A e galueaiina le eleele o le a lē tuu mai e ia ia te oe lona malosi mai le taimi nei ma le agai i luma. O le a avea oe o se tagata solasola ma maumausolo i le lalolagi."},{"verse":38,"text":"Ma sa fai atu Kaino i le Alii: Sa faaosoosoina a’u e Satani ona o lafu a lo’u uso. Ma sa ou ita foi; ona sa e talia lana taulaga ae lē o la’u; ua tele atu lo’u faasalaga nai lo le mea ou te lavatia."},{"verse":39,"text":"Faauta ua e tuli ese a’u i le aso nei mai luma o fofoga o le Alii, ma o le a natia a’u mai i ou fofoga; ma o le a avea a’u ma tagata solasola ma maumausolo i le lalolagi; ma o le a oo mai foi o ia o lē e mauaina a’u o le a fasioti ia te a’u, ona o a’u amioletonu, ona o ia mea ua lē natia mai le Alii."},{"verse":40,"text":"Ma o A’u o le Alii na fai atu ia te ia: Ai se e faaoo le oti ia te oe, o le a faafitu ona tauimasui ia te ia. Ma o A’u o le Alii sa tuuina se faailoga i luga o Kaino, ne’i faaoo le oti ia te ia e se e maua o ia."},{"verse":41,"text":"Ma sa tapunia ese Kaino mai luma o le Alii, ma sa mau faatasi ma lana ava ma le toatele o ona uso i le laueleele o Nota, i le itu i sasa’e o Etena."},{"verse":42,"text":"Ma sa iloa e Kaino lana ava, ma sa to o ia ma fanauina Enoka, ma sa fanauina foi e ia atalii ma afafine e toatele. Ma sa fausia e ia se aai, ma sa ta’u e ia le igoa o le aai i le igoa o lona atalii, o Enoka."},{"verse":43,"text":"Ma sa fanauina Irata ia Enoka, ma isi atalii ma afafine. Ma sa fanaua e Irata Mekuala, ma isi atalii ma afafine. Ma sa fanaua Metusaeli e Mekuala, ma isi atalii ma afafine. Ma sa fanaua e Metusaeli o Lameko."},{"verse":44,"text":"Ma sa ave e Lameko ia te ia ni ava e toalua; o le igoa o le tasi o Ata, ma o le igoa o le isi, o Sela."},{"verse":45,"text":"Ma sa fanaua Iapalu e Ata; o ia o le tamā o e e mau i faleie, ma sa avea i latou ma tagata tausi lafu manu; ma o le igoa o lona uso o Iupalu, o lē o le tamā o i latou uma o e ta kitara ma okeni."},{"verse":46,"text":"Ma o Sela, sa fanauina foi e ia Tupalu Kaino, o se tufuga o mea uma e fai i apamemea ma le u’amea. Ma o le tuafafine o Tupalu Kaino o Naama."},{"verse":47,"text":"Ma sa fai atu Lameko i ana ava, o Ata ma Sela: Faalogo mai i lo’u leo, oulua ava a Lameko, faalogo mai i la’u tautala atu; ona ua ou fasiotia se tagata i lo’u manu’a, ma o se taule’ale’a i lo’u tiga."},{"verse":48,"text":"Afai e faafitu ona tauimasui o Kaino, e moni o Lameko o le a faafitugafulu ma le fitu;"},{"verse":49,"text":"Ona sa ulu atu Lameko i se feagaiga ma Satani, e pei ona faia e Kaino, lea na avea ai o ia ma Mahana Pule, o le pule o lena mealilo tele na tuuina mai e Satani ia Kaino; ma o Irata, le atalii o Enoka, ina ua iloa e ia la latou mealilo, sa amata ona faaali atu e ia i atalii o Atamu;"},{"verse":50,"text":"O le mea lea, ona o le ita, na fasioti ai e Lameko o ia, e lē pei ona faia e Kaino, i lona uso o Apelu, ina ia maua ai mea; ae sa fasiotia Irata e Lameko ona o le tautoga."},{"verse":51,"text":"Ona, mai i aso o Kaino, sa i ai se pulega faalilolilo, ma o a latou galuega sa faia i le pouliuli, ma sa latou iloa tagata taitoatasi o o latou uso."},{"verse":52,"text":"O le mea lea na fetuu ai Lameko e le Alii, ma lona aiga, ma i latou uma o e na osifeagaiga ma Satani; ona sa latou lē tausia poloaiga a le Atua, ma sa lē fiafia ai le Atua, ma sa lē auauna mai o ia ia te i latou, ma o a latou galuega sa o ni mea inosia ia, ma sa amata ona salalau atu i totonu o atalii uma o tagata. Ma sa i ai ia mea i totonu o atalii o tagata."},{"verse":53,"text":"Ma o ia mea sa lē tautalagia i totonu o afafine o tagata, ona sa ta’u e Lameko le mealilo i ana ava, ma sa la’ua fouvale e faasaga ia te ia, ma sa ta’u atu ia mea faalauaitele, ma sa lē i ai le agaalofa;"},{"verse":54,"text":"O le mea lea na inosia ai Lameko, ma tuli ese i fafo, ma lē sau ai i totonu o atalii o tagata, ne’i oti o ia."},{"verse":55,"text":"Ma sa faapea ona amata ona salalau galuega o le pouliuli i totonu o atalii uma o tagata."},{"verse":56,"text":"Ma sa fetuu e le Atua le lalolagi i se fetuu tiga, ma sa toatama’i i e amioleaga, atoa ma atalii uma o tagata o e na faia e ia;"},{"verse":57,"text":"Aua sa latou lē faalogo i lona siufofoga, pe talitonu i lona Atalii Pele e Toatasi, o ia lava na ia folafola mai o le a afio mai i le vaeluaga o taimi, o lē na saunia a o le i faavaeina le lalolagi."},{"verse":58,"text":"Ma sa faapea ona amata ona talai atu o le Talalelei, mai le amataga, ua folafola atu e agelu paia ua auina atu mai luma o le Atua, ma i lona lava siufofoga, ma i le meaalofa o le Agaga Paia."},{"verse":59,"text":"Ma sa faapea ona faamautuina o mea uma ia Atamu, i se sauniga paia, ma talai atu ai le Talalelei, ma auina atu se poloaiga, e tatau ona i ai i le lalolagi, seia oo i lona iuga; ma sa faapea lava. Amene."}]},{"chapter":6,"verses":[{"verse":1,"text":"Ma sa faalogo Atamu i le siufofoga o le Atua, ma sa valaau atu i ona atalii ia salamo."},{"verse":2,"text":"Ma sa toe iloa e Atamu lana ava, ma sa fanauina e ia se atalii, ma sa ta’ua e Atamu lona igoa o Setu. Ma sa viia e Atamu le suafa o le Atua; ona sa fai mai o ia: Ua tofia mai e le Atua ia te a’u se tasi atalii, i le tulaga o Apelu, o lē na fasiotia e Kaino."},{"verse":3,"text":"Ma sa faaali mai e le Atua o ia lava ia Setu, ma sa lē fouvale o ia, ae sa tuuina atu e ia se taulaga na talia, e pei o lona uso o Apelu. Ma sa fanau mai foi ia te ia se atalii, ma sa ta’ua e ia lona igoa o Enosa."},{"verse":4,"text":"Ma ona amata lea ona valaau atu o nei alii i le suafa o le Alii, ma sa faamanuiaina i latou e le Alii;"},{"verse":5,"text":"Ma sa tausia se tusi faamanatu, lea sa tusia ai i le gagana a Atamu, ona sa tuuina mai i le toatele na valaau atu i le Atua e tusitusi e ala i le agaga o musumusuga;"},{"verse":6,"text":"Ma o i latou na aoaoina a latou fanau e faitau ma tusitusi, i se gagana na mamā ma lē eleelea."},{"verse":7,"text":"O lenei o lea lava Perisitua, lea sa i ai i le amataga, o le a i ai foi i le iuga o le lalolagi."},{"verse":8,"text":"Ma o le valoaga lenei na fofogaina e Atamu, a’o uunaia o ia e le Agaga Paia, ma sa tausia se gafa o le fanau a le Atua. Ma o le tusi lenei o augatupulaga a Atamu, ua fai mai: I le aso na foafoa ai e le Atua le tagata, na faia ai e ia o ia i le faatusa o le Atua;"},{"verse":9,"text":"O le faatusa o lona lava tino, o le tane ma le fafine, na foafoa ai e ia i laua, ma faamanuia ia te i laua, ma ta’ua lo laua igoa o Atamu, i le aso na foafoa ai i laua ma avea ai ma tagata ola i le laueleele o le tuuaao o le Atua."},{"verse":10,"text":"Ma sa ola Atamu i le selau tolugafulu o tausaga, ma fanaua se atalii i lona lava faatusa, i ona lava foliga, ma ta’ua lona igoa o Setu."},{"verse":11,"text":"Ma o aso o Atamu, ina ua uma ona fanaua e ia o Setu, e valu selau tausaga, ma sa fanaua e ia atalii ma afafine e toatele;"},{"verse":12,"text":"Ma o aso uma na ola ai Atamu e iva selau ma le tolusefulu tausaga, ma sa maliu o ia."},{"verse":13,"text":"Sa ola Setu i le selau ma le lima o tausaga, ma fanaua Enosa, ma sa vavalo i ona aso uma, ma aoao i lona atalii o Enosa ala o le Atua; o le mea lea na vavalo ai foi Enosa."},{"verse":14,"text":"Ma sa ola Setu, ina ua uma ona fanaua e ia Enosa, i tausaga e valu selau ma le fitu, ma fanaua ni atalii ma afafine e toatele."},{"verse":15,"text":"Ma sa toatele le fanauga a tagata i le laueleele atoa. Ma i aso na sa i ai se puleaga tele a Satani i totonu o tagata, ma sa sasao i o latou loto; ma mai le taimi lena ma le agai i luma na oo mai ai taua ma le faamasaatoto; ma sa sii atu le lima o le tagata faasaga i lona lava uso, e fasioti, ona o galuega faalilolilo, i le sailiga o le pule."},{"verse":16,"text":"O aso uma o Setu e iva selau ma le sefululua tausaga, ma sa maliu o ia."},{"verse":17,"text":"Ma sa ola Enosa i tausaga e ivasefulu, ma fanaua Kainano. Ma o Enosa ma e na totoe o le nuu o le Atua na o ese mai i le laueleele, lea sa ta’ua o Sulona, ma nonofo i se laueleele o le folafolaga, lea sa ta’ua e ia i le igoa o lona lava atalii, o lē na faaigoa e ia o Kainano."},{"verse":18,"text":"Ma sa ola Enosa, ina ua uma ona fanaua e ia Kainano, i tausaga e valu selau ma le sefululima, ma fanaua ni atalii ma afafine e toatele. Ma o aso uma o Enosa, e iva selau ma le lima tausaga, ma sa maliu o ia."},{"verse":19,"text":"Ma sa ola Kainano i tausaga e fitusefulu, ma fanaua Maalaelu; ma sa ola Kainano ina ua uma ona fanaua e ia Maalaelu, i tausaga e valu selau fagafulu, ma fanaua atalii ma afafine. Ma o aso uma o Kainano e iva selau ma le sefulu tausaga, ma sa maliu o ia."},{"verse":20,"text":"Ma sa ola Maalaelu i tausaga e onosefulu ma le lima, ma fanaua Iareto; ma sa ola Maalaelu, ina ua uma ona fanaua e ia Iareto, i tausaga e valu selau ma le tolusefulu, ma fanaua atalii ma afafine. Ma o aso uma o Maalaelu e valu selau ma le ivasefulu-lima tausaga, ma sa maliu o ia."},{"verse":21,"text":"Ma sa ola Iareto i tausaga e selau onosefulu-lua, ma fanaua Enoka; ma sa ola Iareto, ina ua uma ona fanaua e ia Enoka, i tausaga e valu selau, ma fanaua atalii ma afafine. Ma sa aoao e Iareto ia Enoka i ala uma o le Atua."},{"verse":22,"text":"Ma o le gafa lenei o atalii o Atamu, o lē o le atalii o le Atua, o lē na fetautalatalaai ma le Atua lava ia."},{"verse":23,"text":"Ma sa o ni tagata talai o le amiotonu i latou, ma sa tautatala ma vavalo atu, ma valaau atu i tagata uma, i soo se mea lava, ia salamo; ma sa aoao atu le faatuatua i le fanauga a tagata."},{"verse":24,"text":"Ma sa oo ina o aso uma o Iareto e iva selau ma le onosefulu-lua tausaga, ma sa maliu o ia."},{"verse":25,"text":"Ma sa ola Enoka i tausaga e onosefulu-lima, ma fanaua ai Metusela."},{"verse":26,"text":"Ma sa oo ina malaga atu Enoka i le laueleele, i totonu o le nuu; ma a’o malaga atu o ia, sa afio ifo le Agaga o le Atua mai le lagi, ma afio i ona luga."},{"verse":27,"text":"Ma sa faalogoina e ia se leo mai le lagi, ua fetalai mai: Enoka, lo’u atalii e, vavalo atu i lenei nuu, ma fai atu ia te i latou—Ia salamo, ona ua faapea ona fetalai mai o le Alii: Ua Ou ita i lenei nuu, ma ua sasao a’e lo’u ita tele e faasaga ia te i latou; ona ua faasolo ina malo o latou loto, ma ua feū o latou taliga e faalogo, ma ua lē mafai ona vaai mamao o latou mata;"},{"verse":28,"text":"Ma i le tele o nei augatupulaga, talu mai lava le aso na Ou foafoaina ai i latou, ua latou o sese ai, ma teena a’u, ma latou saili ai a latou lava taupulepulega i le pouliuli; ma ua latou fuafuaina le fasioti tagata i a latou lava mea inosia, ma ua latou lē tausia poloaiga, ia sa Ou tuu atu i lo latou tamā, o Atamu."},{"verse":29,"text":"O le mea lea, ua latou molimau pepelo ai i latou lava, ma, ua latou aumai i luga o i latou lava, ia latou tautoga le oti; ma ua Ou saunia se seoli mo i latou, pe afai latou te lē salamo;"},{"verse":30,"text":"Ma o se tulafono lenei, mai lo’u lava gutu, sa Ou auina atu i le amataga o le lalolagi, mai lona faavaega, ma o fofoga o a’u auauna, ou tamā, na Ou poloaiina ai, e pei lava ona o le a auina atu i le lalolagi, seia oo atu i ona tuluiga."},{"verse":31,"text":"Ma ina ua faalogo Enoka i nei upu, sa ifo o ia lava i le eleele, i luma o le Alii, ma tautala atu i luma o le Alii, ua fai atu: Aisea ua amanaia ai a’u i lau silafaga, ma o a’u ua na’o se tama, ma ua inoino mai tagata uma ia te a’u; ona e gese la’u tautala; o lea, aisea ua avea ai a’u ma au auauna?"},{"verse":32,"text":"Ma sa fetalai mai le Alii ia Enoka: Alu atu ma fai e pei ona Ou poloaiina ai oe, ma e leai se tagata o le a atia oe. Tatala lou gutu, ma o le a faatumuina, ma o le a Ou tuu atu ia te oe upu e te tautala ai, aua ua i o’u lima tagata uma, ma o le a Ou faia e tusa ai ma le lelei ia te a’u."},{"verse":33,"text":"Fai atu i lenei nuu: Ia outou filifili i le aso nei, e auauna atu i le Alii le Atua o lē na faia outou."},{"verse":34,"text":"Faauta ua i ou luga lo’u Agaga, o le mea lea o au upu uma o le a Ou ta’utonuina; ma o le a sosola mauga ai ou luma, ma o le a liliu vaitafe mai i o latou alātafe; ma o le a mau oe ia te a’u, ma a’u ia te oe; o lea, savali faatasi ma a’u."},{"verse":35,"text":"Ma sa fetalai mai le Alii ia Enoka, ma fai mai ia te ia: Ia nini ou mata i le palapala, ma fufulu lea, ma o le a mafai ona e vaai. Ma sa faapea ona faia e ia."},{"verse":36,"text":"Ma sa vaai o ia i agaga na foafoaina e le Atua; ma sa vaai foi o ia i mea sa lē vaaia e mata faalenatura; ma mai i le taimi lena ma le agai i luma na oo mai ai le tala faalauaitele i le laueleele: Ua faatuina a’e e le Alii se tagatavāai i lona nuu."},{"verse":37,"text":"Ma sa oo ina alu atu Enoka i le laueleele, i totonu o le nuu, ua tu i luga o maupuepue ma mea maualuluga, ma alaga atu ma le leo tele, ua molimau atu e faasaga ia latou galuega; ma sa tausuai tagata uma ona o ia."},{"verse":38,"text":"Ma sa latou o mai e faalogologo ia te ia, i luga o mea maualuluga, ua fai atu i e e tausi-faleie: Ia outou nonofo iinei ma vaavaai faleie, a’o matou o i ’o e vaavaai i le tagatavāai, ona ua vavalo o ia, ma ua i ai se mea uiga ese i le laueleele; ua sau se tagata valevale i totonu o i tatou."},{"verse":39,"text":"Ma sa oo ina ua latou faalogo atu ia te ia, sa leai se tagata na faaoo atu lima ia te ia; ona sa oo mai le mata’u ia i latou uma o e na faalogo atu ia te ia; aua sa savavali o ia faatasi ma le Atua."},{"verse":40,"text":"Ma sa sau se tagata ia te ia, o lona igoa o Maaisa, ma fai mai ia te ia: Ta’u manino mai ia i matou po o ai oe, ma le mea e te sau ai?"},{"verse":41,"text":"Ma sa fai atu o ia ia te i latou: Na ou aluese mai le laueleele o Kainano, o le laueleele o o’u tamā, o se laueleele o le amiotonu e oo mai i le aso nei. Ma sa aoaoina a’u e lo’u tamā i ala uma o le Atua."},{"verse":42,"text":"Ma sa oo ina a’o ou malaga mai le laueleele o Kainano, i tafatafa o le sami i sasae, sa ou vaaia se faaaliga vaaia; ma faauta, sa ou vaai i le lagi, ma sa fetalai mai le Alii ia te au, ma tuu mai ia te au se poloaiga; o le mea lea, ona o le pogai lenei, ia tausia le poloaiga, ua ou tautala atu ai nei upu."},{"verse":43,"text":"Ma sa faaauau e Enoka lana lauga, ua faapea atu: O le Alii o lē na fetalai mai ia te au, o lea lava o le Atua o le lagi, ma o ia o lo’u Atua, ma lo outou Atua, ma o outou o o’u uso, ma aisea ua outou taupulepule ai ia te outou lava, ma faafitia le Atua o le lagi?"},{"verse":44,"text":"O le lagi na faia e ia; o le lalolagi o lona tuuaao; ma o lona faavae o lana lava. Faauta, o ia na faataotoina, na ia aumai i ona luga se ’au o tagata e toatele."},{"verse":45,"text":"Ma ua oo mai le oti i luga o o tatou tamā; ae ui i lea, ua tatou iloa i latou, ma lē mafai ona faafitia, ma e oo lava i lē ua muamua i tagata uma ua tatou iloa, o Atamu lava."},{"verse":46,"text":"Ona ua tatou tusia i totonu o i tatou se tusi faamanatu, e tusa ma le ata na tuu mai e le tamatamaiaao o le Atua; ma sa tuuina mai i la tatou lava gagana."},{"verse":47,"text":"Ma a’o fetalai atu e Enoka afioga a le Atua, sa gatete tagata, ma lē mafai ona tutulai i ona luma."},{"verse":48,"text":"Ma sa fai atu o ia ia te i latou: Ona sa pa’ū Atamu, ua tatou i ai; ma o lona pa’ū ua oo mai ai le oti; ma ua oo mai ai ia i tatou le pagatia ma le malaia."},{"verse":49,"text":"Faauta ua sau Satani i totonu o le fanauga a tagata, ma faaosooso i latou e ifo atu ia te ia; ma ua avea ai tagata ua faaletino, faalelagona, ma faaletiapolo, ma ua tapunia ese mai luma o le Atua."},{"verse":50,"text":"Peitai sa faailoa mai e le Atua i o tatou tamā e ao i tagata uma ona salamo."},{"verse":51,"text":"Ma sa fetalai mai o ia i lo tatou tamā o Atamu i lona lava siufofoga, ua faapea mai: O A’u o le Atua; o A’u na faia le lalolagi, ma tagata a o lei i ai i latou i la le tino."},{"verse":52,"text":"Ma sa fetalai mai foi o ia ia te ia: Afai e te liliu mai ia te a’u, ma faalogo mai i lo’u leo, ma talitonu, ma salamo i au soligatulafono uma, ma papatiso, i le vai lava, i le suafa o lo’u Atalii Pele e Toatasi, o lē ua tumu i le alofa tunoa ma le upumoni, o Iesu Keriso lea, le suafa lava lea e tasi o le a tuuina atu i lalo o le lagi, o le a oo mai ai le faaolataga i le fanauga a tagata, o le a e maua le meaalofa o le Agaga Paia, ma ole mai i mea uma i lona suafa, ma o soo se mea e te ole mai ai, o le a tuuina atu ia te oe."},{"verse":53,"text":"Ma sa fai atu lo tatou tamā o Atamu i le Alii, ua faapea atu: Aisea e tatau ai i tagata ona salamo ma papatiso i le vai? Ma sa fetalai mai le Alii ia Atamu: Faauta ua Ou faamagaloina oe i lau solitulafono i le Faatoaga o Etena."},{"verse":54,"text":"O lea na oo mai ai le tala i totonu o le lautele o le nuu, e faapea ua togiola le Alo o le Atua mo le uluai sala, lea e lē mafai ai ona tali o agasala a matua i luga o ulu o fanau, ona ua mamā i latou mai le faavaega o le lalolagi."},{"verse":55,"text":"Ma sa fetalai mai le Alii ia Atamu, e faapea: Talu ai ona ua fananau mai au fanau i le agasala, e faapea lava pe a amata ona latou ola a’e, ona tuputupu o le agasala i o latou loto, ma latou te tofo i le oona, ina ia latou iloa ai ona faataua le lelei."},{"verse":56,"text":"Ma ua tuu atu ia te i latou ia iloa le lelei mai le leaga; o le mea lea o i latou o ni pule ia i latou lava, ma ua Ou tuu ia te oe se isi tulafono ma poloaiga."},{"verse":57,"text":"O le mea lea ia aoao atu i lau fanau, e ao i tagata uma, i soo se mea lava, ona salamo, po o o le a leai se ala e mafai ai ona latou mautofi i le malo o le Atua, ona e leai se mea lē mamā e mafai ona mau iina, pe mau i ona luma; ona, i le gagana a Atamu, o le Tagata Paia o lona suafa lea, ma o le suafa o lana Toatasi na Fanaua o le Atalii o le Tagata, o Iesu Keriso lava, o se Faamasino amiotonu, o lē o le a afio mai i le vaeluaga o taimi."},{"verse":58,"text":"O lea Ou te tuu atu ia te oe se poloaiga, ia aoao saoloto atu ia mea i lau fanau, ua fai atu:"},{"verse":59,"text":"Ona o le solitulafono ua oo mai ai le pa’ū, o le pa’ū lea ua aumaia le oti, ma talu ai ona sa outou fananau mai i le lalolagi i le vai, ma le toto, ma le agaga, lea na Ou faia, ma faapea ona avea ai o le efuefu o se tagata ola, e faapea lava ona tatau ona toe fanauina o outou i le malo o le lagi, i le vai, ma i le Agaga, ma faamamaina i le toto, o le toto lava lea o la’u Toatasi na Fanaua; ina ia mafai ona faapaiaina outou mai agasala uma, ma olioli i afioga o le ola faavavau i le lalolagi lenei, ma le ola faavavau i le lalolagi a sau, o le mamalu ola pea lava;"},{"verse":60,"text":"Ona o le vai tou te tausia ai le poloaiga; o le Agaga e ta’uamiotonu ai outou, ma o le toto e faapaiaina ai outou;"},{"verse":61,"text":"O lea ua tuuina atu ai e mau ia te outou; o le mau o le lagi; o le Fesoasoani; o mea filemu o le mamalu ola pea; o le upumoni o mea uma; o lē e faavaveina mea uma, lea na te faaolaina mea uma; o lē na te silafia mea uma, ma ua i ai le mana uma tau i le atamai, alofa mutimutivale, upumoni, fai mea tonu, ma le faamasinotonu."},{"verse":62,"text":"Ma o lenei, faauta, Ou te fai atu ia te oe: O le fuafuaga o le faaolataga lenei mo tagata uma, e ala i le toto o la’u Toatasi na Fanaua, o lē o le a afio mai i le vaeluaga o taimi."},{"verse":63,"text":"Ma faauta, e i ai se faatusa o mea uma, ma ua foafoaina mea uma ma faia e molimau ia te a’u, o mea faaletino, atoa ma mea faaleagaga; o mea o i le lagi i luga, ma mea o i luga o le lalolagi, ma mea o i totonu o le lalolagi, ma mea o i lalo o le lalolagi, i luga atoa ma lalo: ua molimau mea uma ia te a’u."},{"verse":64,"text":"Ma sa oo ina ua uma ona fetalai mai o le Alii ia Atamu, lo tatou tamā, sa tagi atu Atamu i le Alii, ma sa segia ese o ia e le Agaga o le Alii, ma sa aveina ifo o ia i lalo i totonu o le vai, ma sa faataatia i lalo o le vai, ma sa aveina a’e o ia i fafo mai le vai."},{"verse":65,"text":"Ma sa faapea ona papatisoina o ia, ma sa afio ifo le Agaga o le Atua i luga o ia, ma sa faapea ona fanauina o ia i le Agaga, ma faaolaolaina i totonu o lona tagata."},{"verse":66,"text":"Ma sa faalogoina e ia se leo mai le lagi, ua fetalai mai: Ua papatisoina oe i le afi, ma le Agaga Paia. O le mau lenei a le Tamā, ma le Alo, mai le taimi nei ma le aga’i i luma ma le faavavau;"},{"verse":67,"text":"Ma o oe o se tasi o le faatulagaga a ia o lē ua aunoa ma se amataga o aso po o se gataaga o tausaga, mai le vavau atoa e oo i le faavavau atoa."},{"verse":68,"text":"Faauta, ua tasi oe ia te a’u, o se atalii o le Atua; ma ua faapea ona mafai ona avea tagata uma ma o’u atalii. Amene."}]},{"chapter":7,"verses":[{"verse":1,"text":"Ma sa oo ina faaauau e Enoka lana lauga, ua faapea atu: Faauta, sa aoao mai e lo tatou tamā o Atamu nei mea, ma e toatele sa talitonu ma ua avea ma atalii o le Atua, ma e toatele sa lē talitonu, ma ua fano ia latou agasala, ma o loo tulimata’i i luma ma le mata’u, i le mafatiaga, mo le matamataita aasa o le toasa o le Atua e oo mai i o latou luga."},{"verse":2,"text":"Ma e mai lena taimi ma agai atu i le lumanai na amata ai ona vavalo atu o Enoka, ua fai atu i tagata, e faapea: A’o ou malaga, ma tulai i luga o le nofoaga o Mausa, ma tagi atu i le Alii, sa oo mai ai se siufofoga mai le lagi, ua fetalai mai—Ia e liliu, ma ia e alu i luga o le mauga o Simeona."},{"verse":3,"text":"Ma sa oo ina sa ou liliu ma alu a’e i luga o le mauga; ma a’o ou tulai i luga o le mauga, sa ou vaai atu ua avanoa le lagi, ma sa faaofuina a’u i le mamalu;"},{"verse":4,"text":"Ma sa ou vaai i le Alii; ma sa tulai mai o ia i luma o o’u mata, ma sa talanoa o ia ma a’u, e pei ona talanoa se tagata ma se isi, faafesagai lava; ma sa fetalai mai o ia ia te a’u: Vaai, ma o le a Ou faaali atu ia te oe le lalolagi i le va o augatupulaga e tele."},{"verse":5,"text":"Ma sa oo ina ou vaaia le vanu o Suma, ma faauta, o se nuu tele sa nonofo i faleie, le nuu lea o Suma."},{"verse":6,"text":"Ma sa toe fetalai mai le Alii ia te a’u: Vaai; ma sa ou vaai agai atu i matu, ma sa ou vaaia le nuu o Kanana, o e sa nonofo i faleie."},{"verse":7,"text":"Ma sa fetalai mai le Alii ia te a’u: Vavalo atu; ma sa ou vavalo, ua faapea atu: Faauta o le nuu o Kanana, o e ua toatele, o le a o atu e tau faasaga i le nuu o Suma, ma o le a latou fasioti ia i latou ina ia matua faaumatia atoa ai i latou; ma o le a vaevaeina e le nuu o Kanana i latou lava i le laueleele, ma o le a lafulafua le laueleele ma lē fua mai, ma o le a leai se isi nuu e nonofo iina ae na’o le nuu o Kanana;"},{"verse":8,"text":"Aua faauta, o le a fetuu e le Alii le laueleele i le vevela tele, ma o lona lafulafua o le a oo atu e faavavau; ma sa i ai se faauliuli na oo mai i luga o le fanauga uma a Kanana, sa inosia ai i latou i totonu o tagata uma."},{"verse":9,"text":"Ma sa oo ina fetalai mai le Alii ia te a’u: Vaai; ma sa ou vaai, ma sa ou iloa atu le laueleele o Sarona, ma le laueleele o Enoka, ma le laueleele o Ominara, ma le laueleele o Heni, ma le laueleele o Semu, ma le laueleele o Hana, ma le laueleele o Hananaia, ma e uma o nonofo ai;"},{"verse":10,"text":"Ma sa fetalai mai le Alii ia te a’u: Alu atu i lenei nuu, ma fai atu ia te i latou—Ia salamo, ne’i Ou alu atu ma taia i latou i se fetuu, ma latou feoti ai."},{"verse":11,"text":"Ma sa ia tuu mai ia te a’u se poloaiga e tatau ona ou papatiso atu i le suafa o le Tamā, ma le Alo, o lē ua tumu i le alofa tunoa ma le upumoni, ma le Agaga Paia, o lē e molimau e uiga i le Tamā ma le Alo."},{"verse":12,"text":"Ma sa oo ina faaauau ona valaau atu o Enoka i tagata uma, vagana ai le nuu o Kanana, ia salamo;"},{"verse":13,"text":"Ma sa faapea ona matua tele lava le faatuatua o Enoka sa ia taitaia ai le nuu o le Atua, ma sa o mai o latou fili e tau faasaga mai ia te i latou; ma sa ia fetalai atu le afioga a le Alii, ma sa gatete le laueleele, ma mou ese atu mauga, e tusa ai ma lana faatonuga; ma sa liliu ese vaitafe mai i o latou alatafe; ma sa faalogoina le tagi a leona mai le vao; ma sa matata’u tele atunuu uma, ona o le mamana tele o le upu a Enoka, ma ona o le matua tele o le mana o le gagana na tuu mai e le Atua ia te ia."},{"verse":14,"text":"Sa alu a’e foi i luga se laueleele mai le loloto o le sami, ma sa faapea ona matua tele lava le matata’u o fili o le nuu o le Atua, sa oo ina latou sosola ma tutulai mamao ese ma o atu i luga o le laueleele na alu a’e mai le loloto o le sami."},{"verse":15,"text":"Ma o tagata tino ese o le laueleele, sa tutulai mamao ese foi; ma sa oo atu se fetuu i luga o tagata uma sa faasagatau i le Atua;"},{"verse":16,"text":"Ma e mai lena taimi ma le agai atu i le lumanai sa i ai taua ma le faamasaatoto i totonu o i latou; ae sa afio mai le Alii ma mau faatasi ma lona nuu, ma sa latou ola ai i le amiotonu."},{"verse":17,"text":"Sa i luga o atunuu uma le mata’u i le Alii, ona sa matua tele lava le mamalu o le Alii, sa i luga o lona nuu. Ma sa faamanuia e le Alii le laueleele, ma sa faamanuiaina i latou i luga o mauga, ma i luga o mea maualuluga, ma sa uluuluola."},{"verse":18,"text":"Ma sa ta’ua e le Alii lona nuu o Siona, ona sa tasi o latou loto ma tasi le mafaufau, ma sa mau i le amiotonu; ma sa leai se mativa i totonu o i latou."},{"verse":19,"text":"Ma sa faaauau e Enoka lana talaiga i le amiotonu i le nuu o le Atua. Ma sa oo i ona aso, sa fausia e ia se aai sa ta’ua o le Aai Paia, o Siona lava."},{"verse":20,"text":"Ma sa oo ina talatala Enoka faatasi ma le Alii; ma sa fai atu o ia i le Alii: E moni lava o le a mau Siona i le saogalemu e faavavau. Ae sa fetalai mai le Alii ia Enoka: Ua Ou faamanuiaina Siona, ae o le vaega o totoe o tagata ua Ou fetuuina."},{"verse":21,"text":"Ma sa oo ina faaali mai e le Alii ia Enoka tagata uma e nonofo i le lalolagi; ma sa vaai atu o ia, ma faauta, o Siona, i le taualumaga o le taimi, ua aveina a’e i le lagi. Ma sa fetalai mai le Alii ia Enoka: Faauta i lo’u nofoaga e faavavau."},{"verse":22,"text":"Ma sa vaai foi Enoka i le vaega na totoe o tagata o e o atalii o Atamu; ma o i latou o se tuufaatasiga fefiloi o fanau uma a Atamu vagana ai le fanau a Kaino, ona o fanau a Kaino sa uli, ma sa leai se nofoaga i totonu o i latou."},{"verse":23,"text":"Ma ina ua mavae ona aveina a’e o Siona i le lagi, sa vaai atu Enoka, ma faauta, ua i ona luma atunuu uma o le lalolagi;"},{"verse":24,"text":"Ma sa oo mai i lea tupulaga ma lea tupulaga; ma sa maualuga Enoka ma sa siitia a’e, i le loto lava o le Tamā, ma le Atalii o le Tagata; ma faauta, sa i luga o le lalolagi atoa le mana o Satani."},{"verse":25,"text":"Ma sa vaai o ia i agelu ua afifio ifo mai le lagi; ma sa ia faalogoina se siufofoga leo tele ua fetalai mai: Oi talofa, oi talofa i e o nonofo i le lalolagi."},{"verse":26,"text":"Ma sa vaai o ia ia Satani; ma sa i ai ia te ia se filifili tele i lona lima, ma sa ufitia ai luga o le lalolagi atoa i le pouliuli; ma sa tepa a’e o ia ma ’ata, ma sa olioli ana agelu."},{"verse":27,"text":"Ma sa vaaia e Enoka agelu ua afifio ifo mai le lagi, ua molimau atu e uiga i le Tamā ma le Alo; ma sa afio ifo le Agaga Paia i luga o le toatele, ma sa segia a’e i latou i luga i Siona e mana o le lagi."},{"verse":28,"text":"Ma sa oo ina silasila ifo le Atua o le lagi i luga o e na totoe o le nuu, ma sa tutulu o ia; ma sa molimauina e Enoka lea mea, ua fai mai: Pe ua faapefea ea ona tutulu o le lagi, ma faamaligi ifo o latou loifofoga e pei o uaga i luga o mauga?"},{"verse":29,"text":"Ma sa fai atu Enoka i le Alii: Pe ua mafai faapefea ona e tutulu, ona ua vaai ua e paia, ma ua mai le faavavau atoa i le faavavau atoa?"},{"verse":30,"text":"Ma a na mafai e le tagata ona faitau vaega itiiti o le lalolagi, ioe, le miliona o lalolagi e pei o lenei, e lē mafai ona avea o se amataga i le atoaga o au foafoaga; ae ua toso atu pea ou ie pupuni; ma peitai o loo i ai oe iina, ma ua i ai iina lou loto; ma ua e fai mea tonu foi; ua e alofa mutimutivale ma agalelei e faavavau;"},{"verse":31,"text":"Ma ua e avea Siona i lou lava loto, mai au foafoaga uma, e mai le faavavau atoa i le faavavau atoa; ma ua leai se mea ae ua nao le filemu, faamasinotonu, ma le upumoni le afioaga o lou nofoaalii; ma o le a alu atu le alofamutimutivale i luma o ou fofoga ma e leai se gataaga; pe ua mafai faapefea ona e tutulu?"},{"verse":32,"text":"Sa fetalai mai le Alii ia Enoka: Faauta ia i latou nei o ou uso; o i latou o galuega a o’u lava lima, ma sa Ou tuu atu ia te i latou lo latou malamalama, i le aso na Ou foafoa ai i latou; ma sa Ou tuu atu i le tagata i le Faatoaga o Etena, lona faitalia;"},{"verse":33,"text":"Ma sa Ou fai atu i ou uso, ma tuuina atu foi le poloaiga, e tatau ona latou alolofa o le tasi i le isi, ma e tatau ona latou filifili a’u, lo latou Tamā; ae faauta, ua aunoa i latou ma le alofa, ma ua latou inoino i o latou lava toto;"},{"verse":34,"text":"Ma ua sasao a’e le afi o lo’u ita e faasaga ia te i latou; ma o le aasa o lo’u lē fiafia o le a Ou auina atu ai lolo i luga o i latou, ona ua sasao a’e lo’u ita tele e faasaga ia te i latou."},{"verse":35,"text":"Faauta, o A’u o le Atua; o le Tagata Paia o lo’u igoa lea; o le Tagata Fautua o lo’u igoa lea; ma o Lē Gata ma Faavavau o lo’u igoa foi lea."},{"verse":36,"text":"O le mea lea, e mafai ona faaloloa atu o’u lima ma umia foafoaga uma ua Ou faia; ma e mafai foi ona ati lau vaai ia te i latou; ma i totonu o galuega uma a o’u lima sa le’i i ai lava se amioleaga tele e pei ona i ai i totonu o ou uso."},{"verse":37,"text":"Ae faauta, o a latou agasala o le a i luga o ulu o o latou tamā; o le a avea Satani ma o latou tamā, ma o le a avea le pagatia ma o latou malaia; ma o le a tutulu le lagi atoa i luga o i latou, o le galuega atoa lava a o’u lima; o le mea lea, pe ua lē tatau ea ona tutulu o le lagi, i le vaai atu o le a mafatia i latou nei?"},{"verse":38,"text":"Ae faauta, o i latou ia o loo silasila atu i ai i luga ou fofoga o le a fano i lologa; ma faauta, o le a Ou tapunia i latou; ua Ou saunia se falepuipui mo i latou."},{"verse":39,"text":"Ma o ia o lē ua Ou filifilia ua aioi mai i luma o o’u mata. O le mea lea, ua mafatia o ia mo a latou agasala; e tusa ai ma lo latou salamo i le aso e foi mai ai la’u Au Filifilia ia te a’u, ma seia oo mai lena aso, o le a latou i ai i mafatiga;"},{"verse":40,"text":"O le mea lea, ona o lenei mea o le a tutulu ai le lagi, ioe, ma galuega uma a o’u lima."},{"verse":41,"text":"Ma sa oo ina fetalai mai le Alii ia Enoka, ma ta’u mai ia Enoka mea uma ua faia e le fanauga a tagata; o le mea lea na iloa ai e Enoka, ma sa vaai atu i lo latou amioleaga, ma lo latou pagatia, ma ua tagi ma faaloloa atu ona lima, ma sa fefete naua lona loto e pei o le faavavau, ma mutimutivale ona lagona; ma sa luluina le faavavau atoa."},{"verse":42,"text":"Ma sa vaai foi Enoka ia Noa, ma lona aiga; e faapea o le a laveaiina fanau a atalii uma o Noa i se faaolataga faaletino;"},{"verse":43,"text":"O le mea lea na vaai ai Enoka sa fausia e Noa se vaa; ma sa fiafia le Alii i le vaa, ma umia i lona lava aao; ae o e na totoe o e na amioleaga na oo mai i ai lolo ma tofatumoanaina i latou."},{"verse":44,"text":"Ma a’o vaai atu Enoka i lenei mea, sa ia te ia le faanoanoa o le agaga, ma tagi e uiga i ona uso, ma fai atu i le lagi: O le a ou musu e faamafanafanaina; ae na fetalai mai le Alii ia Enoka: Ia siitia a’e lou loto, ma fiafia; ma vaai."},{"verse":45,"text":"Ma sa oo ina vaai atu Enoka; ma sa iloa e ia aiga uma o le lalolagi mai ia Noa; ma sa tagi atu o ia i le Alii, ua fai atu: O afea e oo mai ai le aso o le Alii? O afea e faamaligi ai le toto o le Amiotonu ina ia mafai ona faapaiaina ma maua le ola e faavavau e i latou uma o e e faanoanoa?"},{"verse":46,"text":"Ma sa fetalai mai le Alii: O le a i le vaeluaga o taimi, i aso o le amioleaga ma le tauimasui."},{"verse":47,"text":"Ma faauta, sa vaai Enoka i le aso o le afio mai o le Atalii o le Tagata, i le tino lava; ma sa olioli lona agaga, ua fai mai: Ua sii i luga le Amiotonu, ma ua fasia le Tamai Mamoe mai le faavaega o le lalolagi; ma ua ou i ai i le loto o le Tamā e ala i le faatuatua, ma faauta, ua faatasi Siona ma a’u."},{"verse":48,"text":"Ma sa oo ina vaai atu Enoka i le lalolagi; ma sa ia faalogoina se leo mai le manava o le eleele, ua faapea mai: Oi talofa, oi talofa ia te a’u, le tinā o tagata; ua ou tiga, ua ou vaivai, ona o le amioleaga o la’u fanau. O afea ea ou te mapu ai, ma faamamaina mai le eleelea ua tea atu mai ia te a’u? O afea ea e faapaiaina ai a’u e lo’u Foafoa, ina ia ou mapu, ma mau ai le amiotonu i o’u luga mo se vaitau?"},{"verse":49,"text":"Ma ina ua faalogo atu Enoka i le faanoanoa o le lalolagi, sa tutulu o ia, ma tagi atu i le Alii, ua fai atu: Le Alii e, pe e te lē agaalofa ea i le lalolagi? Pe e te lē faamanuiaina ea le fanau a Noa?"},{"verse":50,"text":"Ma sa oo ina faaauau e Enoka lana tagi atu i le Alii, ua fai atu: Ou te ole atu ia te oe, Le Alii e, i le suafa o lau Toatasi na Fanaua, o Iesu Keriso lava, ia e alofa mutimutivale ia Noa ma lana fanau, ina ia lē toe ufitia le lalolagi i lolo."},{"verse":51,"text":"Ma sa lē mafai e le Alii ona taofia; ma sa osifeagaiga o ia ma Enoka, ma tauto mai ia te ia i se tautoga, o le a ia taofi lolo; o le a ia valaau atu i fanau a Noa;"},{"verse":52,"text":"Ma sa ia auina atu se poloaiga lē masuia, o le a i ai pea se vaega o totoe o ana fanau o le a i ai i atunuu uma, a’o i ai pea le lalolagi;"},{"verse":53,"text":"Ma sa fetalai mai le Alii: Amuia lava o ia o lē o le a ala mai i ana fanau le afio mai o le Mesia; ona ua fetalai mai o ia—o A’u o le Mesia, o le Tupu o Siona, o le Papa o le Lagi, ua lautele e pei o le faavavau; ai se e sau i totonu i le faitotoa ma ’a’e mai i luga e ala ia te a’u, e lē pa’ū lava; o le mea lea, amuia lava i latou o e ua Ou fai atu ai, ona o le a latou o mai ma pese o le olioli e faavavau."},{"verse":54,"text":"Ma sa oo ina tagi atu Enoka i le Alii, ua fai atu: A afio mai le Atalii o le Tagata i le tino, e mapu ea le lalolagi? Ou te talosaga atu ia te oe, faaali mai ia te a’u ia mea."},{"verse":55,"text":"Ma sa fetalai mai le Alii ia Enoka: Vaai, ma sa vaai o ia ma vaai atu i le Atalii o le Tagata ua sii a’e i luga o le satauro, e tusa ma le tu a tagata;"},{"verse":56,"text":"Ma sa ia faalogoina se siufofoga leotele; ma sa tapunia le lagi; ma sa aue foafoaga uma a le Atua; ma sa oi le lalolagi; ma sa mavaevae papa; ma sa tutulai mai le au paia, ma sa faapaleina i le aao taumatau o le Atalii o le Tagata, i palealii o le mamalu;"},{"verse":57,"text":"Ma o le toatele o agaga sa i ai i le falepuipui sa o mai, ma laulaututu i le aao taumatau o le Atua; a’o le vaega na totoe sa faapolopolo i filifili o le pouliuli seia oo i le faamasinoga o le aso tele."},{"verse":58,"text":"Ma sa toe tutulu Enoka ma tagi atu i le Alii, ua fai atu: O afea ea e mapu ai le lalolagi?"},{"verse":59,"text":"Ma sa vaaia e Enoka le Atalii o le Tagata ua afio a’e i le Tamā; ma sa valaau atu o ia i le Alii, ua fai atu: Pe e te lē toe afio mai ea i le lalolagi? Talu ai ona o oe o le Atua, ma ua ou iloa oe, ma sa e tauto mai ia te a’u, ma poloaiina a’u ia ou ole atu i le suafa o lau Toatasi na Fanaua; na e faia a’u, ma tuu mai ia te a’u se aiā i lou nofoalii, ma e lē ona o a’u lava, ae e ala i lou lava alofa tunoa; o le mea lea, ou te fesili atu ai ia te oe pe e te lē toe afio mai i le lalolagi."},{"verse":60,"text":"Ma sa fetalai mai le Alii ia Enoka: E pei ona Ou ola, o le a faapea lava ona Ou alu atu i aso e gata ai, i aso o le amioleaga ma le tauimasui, e faataunuu le tautoga na Ou faia ia te oe e uiga i le fanau a Noa;"},{"verse":61,"text":"Ma o le a oo mai le aso o le a mapu ai le lalolagi, peitai ae lei oo mai lena aso o le a faapouliuligia le lagi, ma o le a ufitia le lalolagi i se veli o le pogisa; ma o le a luluina le lagi, ma le lalolagi foi; ma o le a i ai puapuaga e tele i totonu o le fanauga a tagata, ae o lo’u nuu o le a Ou faasaoina;"},{"verse":62,"text":"Ma o le a Ou auina ifo i lalo mai le lagi le amiotonu; ma o le a Ou auina atu le upumoni mai le eleele, e molimau atu i la’u Toatasi na Fanaua; lona toetu mai le maliu; ioe, ma le toetutu mai foi o tagata uma; ma o le a Ou faia ia tafia le lalolagi i le amiotonu ma le upumoni e pei o se lolo, e faapotopoto mai i fafo la’u au filifilia mai itu e fa o le lalolagi, i se nofoaga o le a Ou saunia, o se Aai Paia, ina ia mafai e lo’u nuu ona fusia i o latou sulugatiti, ma tulimatai i le taimi o lo’u alu atu; ona o iina o le a i ai lo’u fale fetafai, ma o le a ta’ua ai o Siona, o se Ierusalema Fou."},{"verse":63,"text":"Ma sa fetalai mai le Alii ia Enoka: Ona feiloa’i ai lea o oe ma lou aai atoa ma i latou iina, ma o le a tatou talia i latou i o tatou loto, ma o le a latou vaai mai ia te i tatou; ma o le a tatou fusi i o latou ua, ma o le a latou fusi foi i o tatou ua, ma o le a tatou feasogi foi le tasi i le isi;"},{"verse":64,"text":"Ma o le a iina lo’u nofoaga, ma o le a avea ma Siona, lea o le a sau mai foafoaga uma ua Ou faia; ma o le a mapu le lalolagi i va o le afe tausaga."},{"verse":65,"text":"Ma sa oo ina vaai Enoka i le aso o le afio mai o le Atalii o le Tagata, i aso e gata ai, e afio i le lalolagi i le amiotonu i le va o le afe tausaga;"},{"verse":66,"text":"Peitai ae lei oo mai lena aso, sa vaai o ia i puapuaga tetele i totonu o e ua amioleaga; ma sa vaai foi o ia i le sami, ua loulouā, ma loto o tagata ua faavaivai, ua tulimatai i luma ma le matata’u i faamasinoga a le Atua Malosi Aoao, o le a oo mai i luga o e ua amioleaga."},{"verse":67,"text":"Ma sa faaali mai e le Alii ia Enoka mea uma, e oo lava i le gataaga o le lalolagi; ma sa vaai o ia i le aso o e ua amiotonu, le itula o lo latou togiolaina, ma maua se atoatoaga o le olioli;"},{"verse":68,"text":"Ma o aso uma o Siona, i aso o Enoka, e tolu selau onosefulu ma le lima tausaga."},{"verse":69,"text":"Ma sa savavali Enoka ma lona nuu atoa faatasi ma le Atua, ma sa afio o ia i le lotolotoi o Siona; ma sa oo ina lē toe i ai Siona, ona ua aveina a’e i luga e le Atua i lona lava loto; ma mai i le taimi lena na alu atu ai le upu, Ua sola Siona."}]},{"chapter":8,"verses":[{"verse":1,"text":"Ma o aso uma o Enoka e fa selau tolusefulu tausaga."},{"verse":2,"text":"Ma sa oo ina lei avea Metusela, le atalii o Enoka, ina ia mafai ona faataunuu o feagaiga a le Alii, na faia e ia ia Enoka; ona sa osifeagaiga moni lava o ia ma Enoka o le a avea Noa ma fua o ona sulugatiti."},{"verse":3,"text":"Ma sa oo ina vavalo atu Metusela o le a tutupu mai i ona sulugatiti malo uma o le lalolagi (e ala ia Noa), ma sa ia ave le mamalu ia te ia lava."},{"verse":4,"text":"Ma sa oo mai se oge tele i le laueleele, ma sa fetuu e le Alii le laueleele i se fetuu tiga, ma e toatele e sa nonofo ai na feoti."},{"verse":5,"text":"Ma sa oo ina ola Metusela i tausaga e selau valusefulu ma le fitu, ma fanaua Lameko;"},{"verse":6,"text":"Ma sa ola Metusela, ina ua uma ona fanauina e ia Lameko, i tausaga e fitu selau valusefulu ma le lua, ma fanauina atalii ma afafine;"},{"verse":7,"text":"Ma o aso uma o Metusela e iva selau onosefulu ma le iva tausaga, ma sa maliu o ia."},{"verse":8,"text":"Ma sa ola Lameko i tausaga e selau valusefulu ma le lua, ma fanaua se atalii,"},{"verse":9,"text":"Ma sa faaigoa e ia o Noa, ua fai mai: O le atalii lenei o le a faamafanafanaina i tatou e faatatau i la tatou galuega ma le tautiga o o tatou lima, ona o le eleele ua fetuuina e le Alii."},{"verse":10,"text":"Ma sa ola Lameko, ina ua uma ona fanauina e ia Noa, i tausaga e lima selau ma le ivasefulu lima, ma fanauina atalii ma afafine;"},{"verse":11,"text":"Ma o aso uma o Lameko e fitu selau fitusefulu ma le fitu, ma sa maliu o ia."},{"verse":12,"text":"Ma sa fa selau limasefulu tausaga o le matua o Noa, ma sa fanauina Iafeta; ma o le fasefulu ma le lua tausaga ina ua mavae lea, na fanauina ai e ia Semu mai ia te ia o lē o le tinā o Iafeta, ma ina ua lima selau tausaga o lona matua sa fanauina e ia Hamo."},{"verse":13,"text":"Ma sa faalogo Noa ma ona atalii i le Alii, ma uai atu, ma sa ta’ua i latou o atalii o le Atua."},{"verse":14,"text":"Ma ina ua amata ona uluuluola nei alii i luga o le lalolagi, ma fananau mai afafine ia te i latou, sa vaai mai atalii o tagata i ia afafine ua lalelei, ma sa latou ave i latou e fai ma ava, e pei lava ona latou filifili i ai."},{"verse":15,"text":"Ma sa fetalai mai le Alii ia Noa: Ua faatau atu e afafine o ou atalii i latou lava; aua faauta, ua sasao a’e lo’u ita e faasaga i atalii o tagata, ona ua latou lē fia faalogo mai i lo’u leo."},{"verse":16,"text":"Ma sa oo ina vavalo atu Noa, ma aoao atu mea a le Atua, e pei lava ona sa i ai i le amataga."},{"verse":17,"text":"Ma sa fetalai mai le Alii ia Noa: O le a lē finau pea lo’u Agaga i le tagata, ona o le a iloa e ia o le a oti tagata uma; e ui i lea o ona aso o le a selau luasefulu tausaga; ma afai e lē salamo tagata, o le a Ou auina atu lolo i luga o i latou."},{"verse":18,"text":"Ma i aso na sa i ai tagata tino ese i le lalolagi, ma sa latou saili Noa e faaumatia lona ola; peitai sa faatasi le Alii ma Noa, ma sa i ona luga le mana o le Alii."},{"verse":19,"text":"Ma sa faauu e le Alii ia Noa i lana lava faatulagaga, ma poloaiina o ia e tatau ona alu atu o ia ma folafola atu lana Talalelei i le fanauga a tagata, e pei lava ona tuuina atu ia Enoka."},{"verse":20,"text":"Ma sa oo ina valaau atu Noa i le fanauga a tagata e tatau ona latou salamo; peitai sa latou lē faalogo mai i ana upu;"},{"verse":21,"text":"O lenei foi, ina ua uma ona latou faalogo mai ia te ia, sa latou o mai i luma o ia, ua fai mai: Faauta, o i matou o atalii o le Atua; matou te lei avea ea ia te i matou afafine o tagata? Ma matou te lē o aai ea ma feinu, ma faiava ma tuuina atu i le faaipoipoga? Ma ua fanauina e a matou ava mo matou ni fanau, ma o latou lava o ni tagata malolosi, ua faapei o alii anamua, o ni alii ta’uta’ua tele. Ma sa latou lē faalogo mai i upu a Noa."},{"verse":22,"text":"Ma sa silasila mai le Atua ua faateteleina le amioleaga o tagata i le lalolagi; ma ua faafefeteina i luga tagata taitoatasi i manatunatuga o mafaufauga o lona lava loto, ua na’o le leaga e lē aunoa."},{"verse":23,"text":"Ma sa oo ina faaauau pea e Noa lana talaiga i le nuu, ua fai atu: Faalogo mai ia ma uai mai i a’u upu;"},{"verse":24,"text":"Ia talitonu ma salamo ia outou agasala ma papatiso i le suafa o Iesu Keriso, le Alo o le Atua, e pei lava o o tatou tamā, ma o le a outou maua le Agaga Paia, ina ia mafai ona faaali mai o mea uma ia te outou; ma afai tou te lē faia lenei mea, o le a oo mai lolo i luga o outou; ae ui i lea, sa latou lē faalogo."},{"verse":25,"text":"Ma sa salamo Noa, ma sa tiga lona loto ona ua faia e le Alii le tagata i le lalolagi, ma sa faanoanoa ai o ia i lona loto."},{"verse":26,"text":"Ma sa fetalai mai le Alii: O le a Ou faaumatia le tagata o lē na Ou faia, mai le lalolagi, o tagata atoa ma manu vaefa, ma mea fetolofi ma manu felelei o le ea; ona ua salamo Noa ua Ou foafoaina i latou, ma ua Ou faia i latou; ma ua valaau mai o ia ia te a’u; aua ua latou saili lona ola."},{"verse":27,"text":"Ma sa faapea ona maua e Noa le alofa tunoa i fofoga-silasila o le Alii; aua o Noa o se tagata sa amiotonu, ma atoatoa i lana tupulaga; ma sa savavali o ia faatasi ma le Atua, faapea foi ona atalii e toatolu, o Semu, Hamo, ma Iafeta."},{"verse":28,"text":"Sa amioletonu le lalolagi i luma o le Atua, ma sa tumu i le faasaua."},{"verse":29,"text":"Ma sa silasila mai le Atua i le lalolagi, ma, faauta, ua amioletonu, ona ua faapi’opi’o e tagata uma o latou ala i le lalolagi."},{"verse":30,"text":"Ma sa fetalai mai le Atua ia Noa: Ua oo mai le iuga o tagata uma i o’u luma, ona ua tumu le lalolagi i le faasaua, ma faauta o le a Ou faaumatia ese tagata uma mai le lalolagi."}]}]},{"id":"abraham","title":"Aperaamo","englishTitle":"Abraham","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"I Le laueleele o sā Kaletaia, i le nofoaga o o’u tamā, o a’u, o Aperaamo, sa vaai ua tatau ia te a’u ona maua se isi mea ou te nofo ai;"},{"verse":2,"text":"Ma, ina ua ou iloa e i ai se fiafia tele atu ma se filemu ma se mapusaga mo a’u, sa ou saili i faamanuiaga a tamā, ma le aiā e tatau ona faauu i ai a’u e taulimaina ia lava faamanuiaga; aua sa avea a’u o se soo o le amiotonu, i le manao foi ia avea ma se tasi ua mauaina le malamalama tele, ma avea o se soo sili atu o le amiotonu, ma maua se malamalama sili atu, ma avea o se tamā o atunuu e tele, o se aloalii o le filemu, ma manao e maua faatonuga, ma tausi i poloaiga a le Atua, sa avea a’u ma suli moni, o se Faitaulaga Sili, ua umia le aiā e a tamā."},{"verse":3,"text":"Sa faaee mai i o’u luga mai tamā; sa faasolo ifo mai i tamā, mai i le amataga o taimi, ioe, mai i le amataga lava, pe a o le i faavaeina le lalolagi, seia oo mai i le taimi nei, le aiā lava lea a le ulumatua, po o le uluai tagata, o Atamu lea, po o le uluai tamā, e ala mai i tamā ia te a’u."},{"verse":4,"text":"Sa ou saili i lo’u tofiga i le Perisitua e tusa ma le tofiga a le Atua i tamā e faatatau i le fanau."},{"verse":5,"text":"Ona sa liliu ese o’u tamā mai i lo latou amiotonu, ma mai poloaiga paia na tuu mai ia te i latou e le Alii lo latou Atua, i le tapuai atu i atua o tagata faapaupau, sa matua mumusu lava e faalogo mai i lo’u leo;"},{"verse":6,"text":"Ona sa naunau o latou loto e fai le leaga, ma sa liliu atoatoa atu i le atua o Elekana, ma le atua o Lipena, ma le atua o Mamakara, ma le atua o Korasi, ma le Atua o Farao, le tupu o Aikupito;"},{"verse":7,"text":"O lea na liliu atu ai o latou loto i le taulaga a tagata faapaupau i le taulagaina atu o a latou fanau i ia tupua lē gagana, ma lē faalogo mai i lo’u leo, a ua taumafai e aveese lo’u ola i le lima o le faitaulaga a Elekana. O le faitaulaga a Elekana o le faitaulaga foi lea a Farao."},{"verse":8,"text":"O lenei, o le taimi lea, sa o se tu a le faitaulaga a Farao, le tupu o Aikupito, le osi atu o taulaga i luga o le fatafaitaulaga sa fausia i le laueleele o Kaletaia, mo le taulaga atu i ia atua ese, o tane, fafine, ma tamaiti."},{"verse":9,"text":"Ma sa oo ina osia atu e le faitaulaga se taulaga i le atua o Farao, ma i le atua foi o Sakaira, e tusa lava ma le tu a tagata Aikupito. O lenei o le atua o Sakaira o le la."},{"verse":10,"text":"E oo i le taulaga-faafetai e osi i se tamaitiiti sa faia e le faitaulaga a Farao i luga o le fatafaitaulaga sa tu i tafatafa o le mauga sa ta’ua o le Mauga o Potifara, i le amataga o le fanua laugatasi o Olisema."},{"verse":11,"text":"O lenei, sa osi atu e lenei faitaulaga i luga o lenei fatafaitaulaga ni taupou e toatolu i le taimi e tasi, o afafine ia o Onaita, o se tasi o le gafa tautupu e tupuga tonu lava mai sulugatiti o Hamo. O ia taupou sa ofoina atu ona o lo latou amiomamā; sa latou lē fia ifo i lalo e tapuai atu i atua laau po o maa, o lea na fasiotia ai i latou i luga o lenei fatafaitaulaga, ma sa faia e tusa ma le tu a tagata Aikupito."},{"verse":12,"text":"Ma sa oo ina faaoo mai e faitaulaga le faasaua i o’u luga, ina ia latou fasioti ia te a’u, e pei ona sa latou faia i na taupou i luga o lenei fatafaitaulaga; ma ina ia outou maua se malamalama e uiga i lenei fatafaitaulaga, o le a ou faasino atu outou i le ata faatusa o loo i le amataga o lenei talafaamaumau."},{"verse":13,"text":"Sa fausia lenei fatafaitaulaga i foliga o se moega, e faapei ona sa i ai i tagata Kaletaia, ma sa tu i luma o atua o Elekana, Lipena, Mamakara, Korasi, ma le atua foi e pei o le atua o Farao, le tupu o Aikupito."},{"verse":14,"text":"Ina ia outou malamalama e uiga i ia atua, ua ou tuu atu ia te outou ni faatusa o i latou i ni faatagata i le amataga, o ni ituaiga o faatagata ua ta’ua e tagata Kaletaia o Relino, o lona uiga o hairokilifi."},{"verse":15,"text":"Ma a’o sii a’e o latou lima i o’u luga, ina ia latou osi atu a’u ma aveese lo’u ola, faauta, sa ou siitia a’e i luga lo’u leo i le Alii lo’u Atua, ma sa faafofoga ma lagonaina e le Alii, ma sa ia faatumuina a’u i se faaaliga vaaia o le Malosi Aoao, ma sa tulai mai i o’u tafatafa se agelu mai ona luma, ma tatala o’u noanoaga i le taimi lava lea;"},{"verse":16,"text":"Ma sa fetalai mai lona siufofoga ia te a’u: Aperaamo, Aperaamo e, faauta, o lo’u igoa o Ieova, ma ua Ou faalogoina oe, ma ua Ou sau i lalo e laveai oe, ma aveese oe mai le fale o lou tamā, ma mai i tagata uma o lou aiga, i se laueleele ese e te lē iloa lona uiga;"},{"verse":17,"text":"Ma o lenei ona ua latou liliu ese o latou loto mai ia te a’u, e tapuai atu i le atua o Elekana, ma le atua o Lipena, ma le atua o Mamakara, ma le atua o Korasi, ma le atua o Farao, le tupu o Aikupito; o lea ua Ou sau ai i lalo e asiasi mai ia te i latou, ma faaumatia o ia o lē ua siitia a’e i luga lona lima e faasaga ia te oe, Aperaamo e, lo’u atalii, e aveese lou ola."},{"verse":18,"text":"Faauta, o le a Ou taitai oe i lo’u lima, ma o le a Ou ave oe, e tuu i ou luga lo’u igoa, o le Perisitua lava lea o lou tamā, ma o le a i ai i ou luga lo’u mana."},{"verse":19,"text":"E faapei ona sa faia ia Noa o le a faapea foi ona faia ia te oe; ae o lau auaunaga o le a ala atu ai ona iloa o lo’u igoa i le lalolagi e faavavau, ona o A’u o lou Atua."},{"verse":20,"text":"Faauta, o le Mauga o Potifara sa i le laueleele o Uro, o Kaletaia. Ma sa lepeti i lalo e le Alii le fatafaitaulaga o Elekana, ma atua o le laueleele, ma matua faaumatia lava i latou, ma taia le faitaulaga na oo ina oti ai o ia; ma sa i ai se faanoanoa tele i Kaletaia, ma i le malae foi o Farao; o le Farao lea o lona uiga o le tupu e ala i le toto tautupu."},{"verse":21,"text":"O lenei o lea tupu o Aikupito o se na tupuga mai i sulugatiti o Hamo, ma o se sa i ai le toto o sa Kananā i le fanau mai."},{"verse":22,"text":"Mai lea gafa na tupuga mai ai tagata Aikupito uma, ma sa faapea ona faasaoina o le toto o sa Kananā i le laueleele."},{"verse":23,"text":"Ona o le laueleele o Aikupito sa maua muamua e se fafine, o lē o se afafine o Hamo, ma se tama teine a Aikupeta, o lona uiga i le faa-Kaletaia o Aikupito, o lona uiga o se mea ua faasaina;"},{"verse":24,"text":"Ina ua maua e lenei fafine le laueleele sa i lalo o le vai, o lē na ia faanonofo ai ana tama tane ina ua mavae lea; ma sa faapea, ona tupuga mai ia Hamo o le ituaiga lena na tumau ai le fetuu i le laueleele."},{"verse":25,"text":"O lenei o le uluai malo o Aikupito sa faatuina e Farao, le tama tane matua a Aikupeta, le afafine o Hamo; ma sa faia e tusa ai ma le faiga o le malo o Hamo, sa faapeteriaka."},{"verse":26,"text":"O Farao, ona o ia se tagata amiotonu, sa ia faatuina lona malo ma faamasino lona nuu i le poto ma le fai mea tonu i ona aso uma, ma saili ma le maelega e faataitai i le faatulagaga lena sa faatuina e tamā i tupulaga muamua, i aso o le uluai nofoaiga faapeteriaka, i le nofoaiga lava a Atamu, ma Noa foi lona tamā, o lē na faamanuia ia te ia i faamanuiaga o le lalolagi, ma faamanuiaga o le poto, ae fetuu ia te ia e tusa ma le Perisitua."},{"verse":27,"text":"O lenei, ona o Farao o se tasi o le gafa lena e lē mafai ona maua ai e ia le aiā o le Perisitua, e ui ina fai mai Farao na latou mauaina mai ia Noa, e ala mai ia Hamo, o lea na taitaieseina ai lo’u tamā e lo latou ifo i tupua;"},{"verse":28,"text":"Ae o le a ou taumafai, i se taimi o mulimuli mai, e faamatala manino atu le faasologa e agai i tua mai ia te a’u i le amataga o le foafoaga, ona ua oo mai talafaamaumau i o’u lima, ia ua ou umia e oo mai i le taimi nei."},{"verse":29,"text":"O lenei, ina ua uma ona taia o le faitaulaga a Elekana na oti ai o ia, sa oo mai se faataunuuga o mea sa fai mai ia te a’u e uiga i le laueleele o Kaletaia, e faapea o le a oo mai se oge i le laueleele."},{"verse":30,"text":"E tusa ai ma lea, sa faateteleina se oge i le laueleele atoa o Kaletaia, ma sa mafatia tele lo’u tamā ona o le oge, ma sa salamo o ia i le leaga sa gauai o ia e fai faasaga mai ia te a’u, e aveese lo’u ola."},{"verse":31,"text":"Ae o talafaamaumau o tamā, le au peteriaka lava lea, e faatatau i le aiā o le Perisitua, sa faasaoina e le Alii lo’u Atua i o’u lava lima; o lea o le malamalama e uiga i le amataga o le foafoaga, ma paneta foi, ma fetu foi, e pei ona faaalia i tamā, ua ou tausia e oo mai lava i le aso nei, ma o le a ou taumafai e tusi ni isi o ia mea i luga o lenei talafaamaumau, mo le manuia o a’u fanau o ē o le a o mai mulimuli mai ia te a’u."}]},{"chapter":2,"verses":[{"verse":1,"text":"O lenei, sa faia e le Alii le Atua le oge ia faateteleina lava i le laueleele o Uro, sa oo ina oti ai lo’u uso, o Arana; ae o Tara, lo’u tamā, sa nofo pea i le laueleele o Uro, o sa Kaletaia."},{"verse":2,"text":"Ma sa oo ina ave e a’u, o Aperaamo, Sarai e fai ma a’u ava, ae sa ave e Nakori, lo’u uso, ia Meleka, o lē o le afafine o Arana, e fai ma ana ava."},{"verse":3,"text":"O lenei sa fetalai mai le Alii ia te a’u: Aperaamo e, alu ese atu oe i fafo o lou nuu, ma mai tagata o lou aiga, ma mai le fale o lou tamā, i se laueleele o le a Ou faaali atu ia te oe."},{"verse":4,"text":"O lea na ou tuua ai le laueleele o Uro, o sa Kaletaia, ou te alu i le laueleele o Kanana; ma sa ou ave Lota, le atalii o lo’u uso, ma lana ava, ma Sarai la’u ava; ma sa mulimuli mai foi lo’u tamā ia te a’u, i le laueleele sa matou ta’ua o Arana."},{"verse":5,"text":"Ma sa oo ina faaitiitia le oge; ma sa nofo lo’u tamā i Arana ma mau iina, aua sa tele lafu manu i Arana; ma sa toe liliu lo’u tamā i lona ifo i tupua, o lea na nofo ai pea o ia i Arana."},{"verse":6,"text":"Ae o a’u, o Aperaamo, ma Lota, le atalii o lo’u uso, sa ma tatalo atu i le Alii, ma sa faaali mai le Alii ia te a’u, ma fetalai mai ia te a’u: Tulai, ma ave Lota faatasi ma oe; ona ua Ou faamoemoe e aveese oe i fafo mai Arana, ma fai oe o se faifeau e tauave lo’u igoa i se laueleele ese o le a Ou tuu atu i au fanau pe a mavae atu oe mo se tofi e faavavau, pe a latou faalogo mai i lo’u leo."},{"verse":7,"text":"Aua o A’u o le Alii lou Atua; ua Ou nofo i le lagi; o le lalolagi o lo’u tuuaao; Ou te faaloaloa atu lo’u lima i luga o le sami, ma e usiusitai mai le sami i lo’u leo; Ou te faia le matagi ma le afi e avea ma a’u kariota; Ou te fai atu i mauga—O ese mai iinei—ma faauta, e aveese i latou i se asiosio, i lea lava taimi, faafuasei lava."},{"verse":8,"text":"O lo’u igoa o Ieova, ma ua Ou iloa le iuga mai le amataga; o lea o le a i ai lo’u lima i luga o oe."},{"verse":9,"text":"Ma o le a Ou faia mai ia te oe se atunuu tele, ma o le a Ou faamanuiaina oe e lē mafuatiaina, ma faasilisili lou igoa i totonu o atunuu uma, ma o le a avea oe ma se faamanuiaga i au fanau e mulimuli mai pe a mavae atu oe, ina ia latou tauaveina i o latou lima lenei auaunaga ma le Perisitua i atunuu uma;"},{"verse":10,"text":"Ma o le a Ou faamanuiaina i latou e ala i lou igoa; ona o le toatele e taliaina lenei Talalelei o le a ta’ua i lou igoa, ma o le a faitauina o au fanau, ma o le a tutulai a’e ma faamanuia ia te oe, o lo latou tamā;"},{"verse":11,"text":"Ma o le a Ou faamanuia i latou o e e faamanuia ia te oe, ma fetuu i latou o e e fetuu ia te oe; ma o oe (o lona uiga, o lou Perisitua) ma o au fanau (o lona uiga, o lou Perisitua), aua Ou te tuu atu ia te oe se folafolaga o lenei aiā o le a i ai pea ia te oe, ma i au fanau e mulimuli mai pe a mavae atu oe (o lona uiga, o le fanau moni lea, po o le fanau totino) o le a manuia ai aiga uma o le lalolagi, i faamanuiaga lava o le Talalelei, o faamanuiaga ia o le faaolataga, o le ola faavavau lava."},{"verse":12,"text":"O lenei, ina ua mavae ona afio ese le Alii mai le fetalai mai ia te a’u, ma aveese ona fofoga mai ia te a’u, sa ou faapea ifo i lo’u loto: Ua saili atu lau auauna ia te oe ma le naunau lava; o lenei ua ou maua oe;"},{"verse":13,"text":"Sa e auina mai lau agelu e laveai a’u mai atua o Elekana, ma o le a lelei ia te a’u ona faalogo atu i lou siufofoga, o lea ia tuu mai i lau auauna e tulai i luga ma alu ese i le filemu."},{"verse":14,"text":"O lea o a’u, o Aperaamo, sa alu ese e pei ona sa fetalai mai ai le Alii ia te a’u, ma Lota faatasi ma a’u; ma o a’u, o Aperaamo, sa onosefulu ma le lua tausaga le matua i le taimi na ou alu ese ai mai Arana."},{"verse":15,"text":"Ma sa ou ave Sarai, o lē na ou ave e fai ma a’u ava a’o ou i ai i Uro, i Kaletaia, ma Lota le atalii o lo’u uso, ma a matou mea uma sa matou faaputuputu, ma agaga na matou mauaina i Arana, ma matou o mai i le ala e tau i le laueleele o Kanana, ma nonofo i faleie a’o matou o mai i lo matou ala;"},{"verse":16,"text":"O lea, o le faavavau sa fai ma o matou faapaologa ma o matou papa ma o matou faaolataga, a’o matou malaga mai Arana e ui atu ia Seasona, e o atu ai i le laueleele o Kanana."},{"verse":17,"text":"O lenei o a’u, o Aperaamo, sa ou faia se fatafaitaulaga i le laueleele o Seasona, ma faia se taulaga i le Alii, ma tatalo atu ina ia aveesea le oge mai le fale o lo’u tamā, ina ia lē fano i latou."},{"verse":18,"text":"Ma ona matou te’a atu lea mai Seasona e ala atu i le laueleele i le nuu o Sekema; sa tu lea nuu i le fanua laugatasi o More, ma ua matou oo mai ai i tuaoi o le laueleele o sa Kananā, ma sa ou osi atu se taulaga iina i le fanua laugatasi o More, ma valaau atu i le Alii ma le naunautai, ona ua matou oo mai i le laueleele o lenei atunuu ifo i tupua."},{"verse":19,"text":"Ma sa faaali mai le Alii ia te a’u i le tali mai i a’u talosaga, ma sa fetalai mai ia te a’u: O le a Ou tuu atu lenei laueleele i au fanau."},{"verse":20,"text":"Ma o a’u, o Aperaamo, sa ou tulai mai le mea sa i ai le fatafaitaulaga na ou fausia i le Alii, ma ou alu ese mai iina i se mauga i le itu i sasae o Peteli, ma faatu lo’u faleie iina, o Peteli i sisifo, ma ’Ai i sasae; ma o iina na ou fausia ai se isi fatafaitaulaga i le Alii, ma toe valaau atu ai i le suafa o le Alii."},{"verse":21,"text":"Ma o a’u, o Aperaamo, sa ou malaga, ma alu atu pea agai i saute; ma sa i ai pea se faaauauga o se oge i le laueleele; ma o a’u, o Aperaamo, na faia se tonu ou te alu i lalo i Aikupito, e nofo ai iina, ona sa faateteleina lava le oge."},{"verse":22,"text":"Ma sa oo ina ua lata ona ou ulu atu i Aikupito, sa fetalai mai le Alii ia te a’u: Faauta, o Sarai, lau ava, o se fafine lalelei tele i le vaai atu i ai;"},{"verse":23,"text":"O lea, o le a oo mai, a vaai mai tagata Aikupito ia te ia, o le a latou fai ane—O ia o lana ava; ma o le a latou fasioti oe, ae o le a latou faaolaina o ia; o lea vaai ia faapenei ona e faia:"},{"verse":24,"text":"Tuu atu ia Sarai e fai atu i tagata Aikupito, o ia o lou tuafafine, ma o le a ola ai lou tagata."},{"verse":25,"text":"Ma sa oo ina o a’u o Aperaamo, sa ou ta’u atu ia Sarai, la’u ava, mea uma na fetalai mai ai le Alii ia te a’u—O lea ou te aioi atu ai ia te oe, fai atu ia te i latou, o oe o lo’u tuafafine, ina ia lelei ia te a’u mo oe, ma o le a ola ai lo’u tagata ona o oe."}]},{"chapter":3,"verses":[{"verse":1,"text":"Ma o a’u, o Aperaamo, sa ia te a’u le Urima ma le Tumena, lea na tuu mai e le Alii lo’u Atua ia te a’u, i Uro o sa Kaletaia;"},{"verse":2,"text":"Ma sa ou vaai i fetu, sa matua sili lava i latou, ma o se tasi o i latou sa sili lona latalata i le nofoalii o le Atua; ma sa tele isi e sili sa latalata atu i ai;"},{"verse":3,"text":"Ma sa fetalai mai le Alii ia te a’u: O i latou nei e pule; ma o le igoa o le tasi e sili o Kolape, ona ua latalata mai ia te a’u, aua o A’u o le Alii lou Atua: Ua Ou faatuina le tasi lenei e pulea i latou uma na ua i ai i le faatulagaga e tasi e pei o lena o loo e tulai ai."},{"verse":4,"text":"Ma sa fetalai mai le Alii ia te a’u, e ala mai i le Urima ma le Tumena, o Kolape ua tusa ma le faatulagaga a le Alii, e tusa ma ona taimi ma tau e tusa i ana taamilosaga; e faapea o le taamilosaga e tasi o se aso lea i le Alii, e tusa ma lana ala faitau, o le tasi afe lea o tausaga e tusa ma le taimi ua tofia i lena o loo e tulai ai. O le faitauga lea o le taimi a le Alii, e tusa ma le faitauga o Kolape."},{"verse":5,"text":"Ma sa fetalai mai le Alii ia te a’u: O le paneta lea e itiiti le malamalama, e itiiti ifo nai lo lena e pulea le ao, o le po lava, ua sili pe tele atu nai lo o lena o loo e tulai ai i luga i le faitauga o le taimi, ona e telegese atu le alu i le faatulagaga; ua tusa ai lea ma le faatulagaga ona ua tulai o ia i luga a’e o le lalolagi o loo e tu ai, o lea o le faitauga o lona taimi ua lē tele na’uā e pei o le aofai o ona aso, ma ona masina, ma ona tausaga."},{"verse":6,"text":"Ma sa fetalai mai le Alii ia te a’u: O lenei, Aperaamo e, o mea moni nei e lua o loo i ai, faauta ua vaai atu i ai ou mata; ua tuu atu ia te oe ia e iloa le faitauga o taimi, ma le taimi faatuina, ioe, le taimi faatuina o le lalolagi o loo e tulai ai, ma le taimi faatuina o le malamalama tele ua faatuina e pulea le ao, ma le taimi faatuina o le malamalama itiiti ua faatuina e pulea le po."},{"verse":7,"text":"O lenei o le taimi faatuina o le malamalama itiiti e umi atu lona faitauga nai lo le faitauga o le taimi o le lalolagi o loo e tulai ai."},{"verse":8,"text":"Ma i le mea e i ai ia mea moni e lua, e i ai se isi mea moni e i luga a’e o i laua, o lona uiga, e i ai se isi paneta e sili atu foi le umi o le faitauga o lona taimi."},{"verse":9,"text":"Ma o le a faapena lava le faitauga o le taimi o le tasi paneta i luga a’e o le isi, seia oo lava ina e latalata atu ia Kolape, o Kolape lea ua tusa ma le faitauga o le taimi o le Alii; o Kolape lea ua faatuina latalata i le nofoalii o le Atua, e pulea paneta uma na e i ai i le faatulagaga e tasi e pei o lena o loo e tulai ai."},{"verse":10,"text":"Ma ua tuuina atu ia te oe ia e iloa le taimi faatulagaina o fetu uma ua faatutu e tuu atu le malamalama, seia oo ina e oo latalata atu i le nofoalii o le Atua."},{"verse":11,"text":"Sa faapea ona talanoa a’u, o Aperaamo, ma le Alii, faafesagai lava, e pei ona talanoa se tasi tagata ma le isi; ma sa ta’u mai e ia ia te a’u e uiga i galuega na faia e ona aao;"},{"verse":12,"text":"Ma sa fetalai mai o ia ia te a’u: Lo’u atalii e, lo’u atalii e, (ma sa faaloaloa mai lona aao), faauta o le a Ou faaali atu ia te oe nei mea uma. Ma sa tuu e ia lona aao i luga o o’u mata, ma sa ou vaai atu i na mea uma na faia e ona aao, o ni mea sa tele; ma sa faateleina i latou i luma o o’u mata, ma sa lē mafai ona ou vaai atu i so latou gataaga."},{"verse":13,"text":"Ma sa fetalai mai o ia ia te a’u: O Saianea lenei, o le la lea. Ma sa fetalai mai o ia ia te a’u: O Kokapo, o se fetu. Ma sa fetalai mai o ia ia te a’u: O Ole’a, o le masina lea. Ma sa fetalai mai o ia ia te a’u: O Kokaupi, o lona uiga o fetu, po o malamalama tetele uma, sa i ai i le vanimonimo o le lagi."},{"verse":14,"text":"Ma o le taimi o le po na fetalai mai ai e le Alii upu nei ia te a’u: O le a Ou faauluolaina oe, ma lau fanau e mulimuli mai pe a mavae atu oe, e pei o i latou nei; ma afai e mafai ona e faitauina le aofai o oneone, o le a faapea foi le aofai o au fanau."},{"verse":15,"text":"Ma sa fetalai mai le Alii ia te a’u: Aperaamo e, Ou te faaali atu nei mea ia te oe ae e te lei alu atu i Aikupito, ina ia mafai ona e folafola atu ia upu uma."},{"verse":16,"text":"Afai e i ai ni mea se lua, ma ua i ai le tasi i luga a’e o le isi, e i ai ni mea ua sili atu i luga a’e o i la’ua; o lea o Kolape o le silisili lea o Kokaupi uma na e vaai i ai, ona ua latalata tele mai o ia ia te a’u."},{"verse":17,"text":"O lenei, afai e i ai ni mea se lua, o le tasi i luga a’e o le isi, ma o le masina e i luga a’e i le lalolagi, ona atonu lea e i ai se paneta po o se fetu e i luga a’e o ia; ma e leai se mea e ave e le Alii lou Atua i lona loto e fai ae o le mea o le a faia e ia."},{"verse":18,"text":"Faapei ona faia e ia le fetu sili atu; e pei, foi, afai e i ai ni agaga se lua, ma ua sili atu le atamai o le tasi nai lo le isi, ae o ia agaga e lua, e ui ina sili atu le atamai o le tasi nai lo le isi, ua leai se amataga; sa i ai i laua muamua, o le a leai so laua gataaga, o le a i ai pea i laua pe a mavae le lalolagi, ona o i laua e nolama, pe faavavau."},{"verse":19,"text":"Ma sa fetalai mai le Alii ia te a’u: O mea moni nei e lua ua i ai, ua i ai ni agaga se lua, e sili atu le atamai o le tasi nai lo le isi; o le a i ai foi se isi e sili atu le atamai nai lo i laua; o A’u o le Alii lou Atua, ua sili atu lo’u atamai nai lo i latou uma."},{"verse":20,"text":"Sa auina atu e le Alii lou Atua lana agelu e laveai oe mai lima o le faitaulaga a Elekana."},{"verse":21,"text":"Ua Ou nofo i le lotolotoi o i latou uma; o lea, ua Ou sau nei i lalo ia te oe e ta’u atu ia te oe galuega na faia e o’u lima, lea e sili atu ai lo’u poto nai lo i latou uma, aua ua Ou pule i le lagi i lugā, ma le lalolagi i lalō, i le poto ma le faautauta atoa, i luga o atamai uma na vaai i ai ou mata mai le amataga; sa Ou alu ifo i le amataga i le lotolotoi o atamai uma na e vaai i ai."},{"verse":22,"text":"O lenei sa faaali mai e le Alii ia te a’u, o Aperaamo, o atamai na faatulagaina ae lei i ai le lalolagi; ma i totonu o i latou uma ia sa i ai le toatele o e tamalii ma ta’uta’ua;"},{"verse":23,"text":"Ma sa silasila atu le Atua i ia agaga ua lelei i latou, ma sa tulai o ia i le lotolotoi o i latou, ma sa fetalai o ia: O i latou ia o le a Ou faia ma a’u pule; aua sa tulai o ia i le lotolotoi o i latou o ni agaga, ma sa silasila atu o ia ua lelei i latou; ma sa fetalai mai o ia ia te a’u: Aperaamo e, o oe o se tasi o i latou; sa filifilia oe ae e te lei fanau mai."},{"verse":24,"text":"Ma sa tulai mai se tasi i totonu o i latou sa pei o le Atua, ma sa fai atu o ia ia te i latou o e sa faatasi ma ia: O le a tatou o i lalō, ona o loo i ai se avanoa iina, ma o le a tatou ave mea nei, ma o le a tatou faia se lalolagi e nonofo ai i latou nei;"},{"verse":25,"text":"Ma o le a tatou tofotofoina ai i latou, e vaai pe latou te faia mea uma o soo se mea e poloaiina ai i latou e le Alii lo latou Atua;"},{"verse":26,"text":"Ma o i latou o e e tausia lo latou esetete muamua, o le a faaopoopoina i ai; ma o i latou o e e lē tausia lo latou esetete muamua o le a latou lē maua le mamalu i le malo e tasi faatasi ma i latou o e e tausia lo latou esetete muamua; ma o i latou o e e tausia lo latou esetete lona lua o le a faaopoopo i luga o o latou ulu le mamalu e faavavau ma faavavau lava."},{"verse":27,"text":"Ma sa fetalai mai le Alii: O ai Ou te auina atu? Ma sa tali mai se tasi e pei o le Atalii o le Tagata: O A’u lenei, auina atu a’u. Ma sa tali mai le isi ma fai mai: O a’u lenei, auina atu a’u. Ma sa fetalai mai le Alii: O le a Ou auina atu le muamua."},{"verse":28,"text":"Ma sa ita le lona lua, ma sa lē tausia lona esetete muamua; ma, i lena aso, e toatele na mulimuli atu ia te ia."}]},{"chapter":4,"verses":[{"verse":1,"text":"Ma ona fetalai mai lea o le Alii: Sei tatou o i lalō. Ma sa latou o ifo i lalo i le amataga, ma o i latou, o lona uiga o Atua, sa faatulagaina ma foafoaina le lagi ma le lalolagi."},{"verse":2,"text":"Ma o le lalolagi, ina ua uma ona foafoaina, sa gaogao ma tuufua, ona sa latou lei foafoaina se mea ae na’o le lalolagi; ma sa ufitia e le pouliuli luga o le moana, ma sa faamalumalu le Agaga o Atua i luga o vai."},{"verse":3,"text":"Ma sa latou (o Atua) fetalai: Ia i ai le malamalama; ma sa i ai le malamalama."},{"verse":4,"text":"Ma sa latou (o Atua) silafia le malamalama, ona sa pupula; ma sa latou vavae le malamalama, pe faia ia vavaeeseina, mai le pouliuli."},{"verse":5,"text":"Ma sa ta’ua e Atua le malamalama o le Ao, ma o le pouliuli sa latou ta’ua o le Po. Ma sa oo mai le afiafi seia oo i le taeao sa latou ta’ua o le po; ma mai le taeao seia oo i le afiafi sa latou ta’ua, o le ao; ma o le muamua lea, po o le amataga, o le mea lena ua latou ta’ua o le ao ma le po."},{"verse":6,"text":"Ma sa fetalai foi Atua: Ia i ai se vanimonimo i le lotolotoi o vai, ma ia vavae ai vai mai vai."},{"verse":7,"text":"Ma sa faatonu e Atua le vanimonimo, ina ia vavaeina vai sa i lalo o le vanimonimo, mai vai sa i luga o le vanimonimo; ma sa faapea lava, e pei ona sa faatonu ai i latou."},{"verse":8,"text":"Ma sa ta’ua e Atua le vanimonimo, o le Lagi. Ma sa oo mai le afiafi seia oo i le taeao sa latou ta’ua o le po; ma sa oo mai le taeao seia oo i le afiafi sa latou ta’ua o le ao; ma o le taimi lona lua lea sa latou ta’ua o le po ma le ao."},{"verse":9,"text":"Ma sa faatonu e Atua, ma fetalai atu: Ia tuu atu i vai o i lalo o le lagi ia faapotopoto faatasi i le mea e tasi, ma ia tuu atu i le eleele ia mānu a’e o se eleele matutu; ma sa faapea lava e pei ona sa latou faatonuina;"},{"verse":10,"text":"Ma sa ta’ua e Atua le eleele matutu, o le Eleele; ma o le faapotopotoga faatasi o vai, sa latou ta’ua, o Vai Tetele; ma sa silasila atu Atua ua usiusitaia i latou."},{"verse":11,"text":"Ma sa fetalai atu Atua: Sei tatou saunia le eleele ia tupu mai ai le mutia; le laau afu e fua i fatu; le laau aina e fua mai ai fua, e tusa ma lona lava ituaiga, o lona fatu ia te ia lava e fua mai i ona lava foliga i luga o le lalolagi; ma sa faapea lava, e pei ona sa latou faatonuina."},{"verse":12,"text":"Ma sa faatulaga e Atua le eleele ia tutupu mai ai le mutia mai i ona lava fatu, ma le laau afu ia tupu mai ai le laau afu mai i ona lava fatu, e fua mai ai fatu o lona lava ituaiga; ma le eleele ia tupu mai ai le laau mai i ona lava fatu, e fua mai i fua, o ona fatu e nao ona lava fua e mafai ona tutupu mai ia te ia lava, e tusa ma lona ituaiga; ma sa silasila atu Atua, ua usiusitaia i latou."},{"verse":13,"text":"Ma sa oo ina latou faitauina aso; mai le afiafi seia oo i le taeao sa latou ta’ua o le po; ma sa oo mai i le taeao seia oo i le afiafi sa latou ta’ua o le ao; ma o le taimi lona tolu lea."},{"verse":14,"text":"Ma sa faatulaga e Atua malamalama i le vanimonimo o le lagi, ma faia i latou e vavae ai le ao mai le po; ma faatulaga i latou e avea ma faailoga ma mo tau, ma mo aso ma mo tausaga;"},{"verse":15,"text":"Ma faatulaga i latou e avea ma malamalama i le vanimonimo o le lagi e susulu mai ai le malamalama i luga o le lalolagi; ma sa faapea lava."},{"verse":16,"text":"Ma sa faatulaga e Atua malamalama tetele e lua, o le malamalama tele e pulea le ao, ma le malamalama itiiti e pulea le po; sa latou tuu foi fetu faatasi ma le malamalama itiiti;"},{"verse":17,"text":"Ma sa tuu i latou e Atua i le vanimonimo o le lagi, e susulu mai ai le malamalama i le lalolagi, ma pule ai i le ao ma le po, ma faia ia vavae ese ai le malamalama mai le pouliuli."},{"verse":18,"text":"Ma sa matau e Atua na mea na latou faatonuina seia oo lava ina ua faataunuuina i latou."},{"verse":19,"text":"Ma sa oo ina faapea e mai i le afiafi seia oo i le taeao o le po lea; ma sa oo ina faapea e mai le taeao seia oo i le afiafi o le ao lea; ma o le taimi lona fa lea."},{"verse":20,"text":"Ma sa fetalai Atua: Sei tatou saunia vai ia tutupu tele mai ai manu feoa’i e i ai le ola; ma manu felelei, ina ia mafai ona latou felelei i luga o le lalolagi i le vanimonimo vavaloloa o le lagi."},{"verse":21,"text":"Ma sa saunia e Atua vai ina ia latou maua ai tafola tetele, ma mea ola taitasi uma e feoa’i, ia sa tatau ona tele ona maua i vai e tusa ma o latou ituaiga; ma manu felelei fai apaau taitasi uma e tusa ma o latou ituaiga. Ma sa silasila atu Atua o le a usiusitaia i latou, ma ua lelei la latou fuafuaga."},{"verse":22,"text":"Ma sa fetalai Atua: O le a tatou faamanuia i latou, ma faia i latou ia uluola ma faateleina, ma faatumuina vai i sami po o vai tetele; ma faia manu felelei ia faateleina i le lalolagi."},{"verse":23,"text":"Ma sa oo ina faapea e mai i le afiafi seia oo i le taeao sa latou ta’ua o le po; ma sa oo ina faapea e mai i le taeao seia oo i le afiafi sa latou ta’ua o le ao; ma o le taimi lona lima lea."},{"verse":24,"text":"Ma sa saunia e Atua le laueleele ia tutupu mai ai mea ola e tusa ma lona ituaiga, o lafu manu ma mea fetolofi, ma manu vaefa o le laueleele e tusa ma o latou ituaiga; ma sa faapea lava, e pei ona sa latou fetalai atu ai."},{"verse":25,"text":"Ma sa faatulaga e Atua le laueleele ia tutupu mai ai manu vaefa e tusa ma o latou lava ituaiga, ma lafu manu e tusa ma o latou ituaiga, ma mea taitasi uma e fetolofi i le lalolagi e tusa ma lona ituaiga; ma sa silasila atu Atua o le a usitaia i latou."},{"verse":26,"text":"Ma sa fono Atua ia i latou lava ma faapea ane: Tatou o i lalō ma faia le tagata i lo tatou faatusa, e tusa ma o tatou foliga; ma o le a tatou tuu atu ia te i latou le pule i i’a o le sami, ma i manu felelei o le ea, ma i lafu manu, ma i le lalolagi atoa, ma i mea fetolofi taitasi uma e fetolofi i luga o le fogaeleele."},{"verse":27,"text":"O lea na afifio ifo ai Atua i lalo e faatulaga le tagata i lo latou lava faatusa, e fai e i latou o ia i le faatusa o Atua, e fai e i latou i la’ua o le tane ma le fafine."},{"verse":28,"text":"Ma sa fetalai ane Atua: O le a tatou faamanuia i la’ua. Ma sa fetalai ane Atua: O le a tatou faia i la’ua ia fanafanau ma uluuluola, ma faatumuina ai le lalolagi, ma faato’ilalo i ai, ma ia pule i i’a o le sami, ma i manu felelei o le ea, ma i mea ola taitasi uma e fetolofi i luga o le fogaeleele."},{"verse":29,"text":"Ma sa fetalai ane Atua: Faauta, o le a tatou tuu atu ia te i la’ua laau afu taitasi uma e fua mai i fatu e oo mai i luga o le lalolagi atoa, ma laau taitasi uma o le a fua mai i fua i ona luga; ioe, o fua o le laau e tupu mai ai fatu o le a tatou tuu atu ia te i la’ua; o le a avea lea mo a la’ua meaai."},{"verse":30,"text":"Ma i manu vaefa taitasi o le fogaeleele, ma i manu felelei taitasi o le ea, ma mea taitasi uma e fetolofi i luga o le fogaeleele, faauta, o le a tatou tuu atu i te i latou le ola, ma o le a tatou tuu atu foi ia te i latou laau afu mata uma mo meaai, ma o nei mea uma o le a faapea ona faatulagaina."},{"verse":31,"text":"Ma sa fetalai ane Atua: O le a tatou faia mea uma ua tatou fai atu ai, ma faatulaga i latou; ma faauta, o le a latou usiusitai lava. Ma sa oo ina sa faapea e mai i le afiafi seia oo i le taeao sa latou ta’ua o le po; ma sa oo ina sa faapea e mai i le taeao seia oo i le afiafi, sa latou ta’ua o le ao; ma sa latou faitauina le taimi lona ono."}]},{"chapter":5,"verses":[{"verse":1,"text":"Ma o le a faapea ona tatou faamae’aina le lagi ma le lalolagi, ma a la’ua ’au uma."},{"verse":2,"text":"Ma sa fai ane Atua ia i latou lava: O le a tatou faauma la tatou galuega i le taimi lona fitu, lea sa tatou taupule i ai; ma o le a tatou malolo i le taimi lona fitu, mai la tatou galuega atoa sa tatou taupuleina."},{"verse":3,"text":"Ma sa faaiuina e Atua la latou galuega i le taimi lona fitu, ona o le taimi lona fitu o le a latou malolo ai mai ia latou galuega uma ia sa latou taupule ai (o Atua) ia i latou lava e fai; ma faapaiaina ai. Ma sa faapea a latou tonu i le taimi na latou taupule ai i latou lava e faia le lagi ma le lalolagi."},{"verse":4,"text":"Ma sa afifio ifo Atua i lalo ma faia tupulaga ia o le lagi ma le lalolagi, i le taimi na faia ai i latou i le aso na faia ai e Atua le lalolagi ma le lagi,"},{"verse":5,"text":"E tusa ma mea uma sa latou fetalai i ai e uiga i laau taitasi o le fanua a’o lei i ai i le lalolagi, ma laau afu taitasi o le fanua a’o lei tupu mai; ona sa lei faia e Atua ia timu mai i luga o le lalolagi i le taimi na latou taupule ai e fai i latou, ma a’o lei faia se tagata e galueaiina le eleele."},{"verse":6,"text":"Peitai sa alu a’e i luga se puao mai le lalolagi, ma sa faasūsū ai luga o le eleele atoa."},{"verse":7,"text":"Ma sa fai e Atua le tagata mai le efuefu o le eleele, ma ave lona agaga (o lona uiga, o le agaga o le tagata), ma tuu i totonu ia te ia; ma mānava i totonu o ona pogaiisu le mānava o le ola, ma ua avea ai le tagata ma se tagata ola."},{"verse":8,"text":"Ma sa totō e Atua se faatoaga, i sasa’e i Etena, ma o iina ua latou tuu ai le tagata, o lē o lona agaga na latou tuu i totonu o le tino lea sa latou faia."},{"verse":9,"text":"Ma sa faia e Atua ia tutupu a’e mai le eleele laau taitasi uma e matagofie i le vaai ma lelei mo meaai; o le laau o le ola, foi, i le totonugalemu o le faatoaga, ma le laau e iloa ai lelei ma le leaga."},{"verse":10,"text":"Sa i ai se vaitafe sa tafe atu i fafo mai Etena, e faasūsū ai le faatoaga, ma sa ala eseese atu mai iina ma avea ma ni vaitafe se fa."},{"verse":11,"text":"Ma sa ave e Atua le tagata ma tuu o ia i le Faatoaga o Etena, e teuteu ma tausi i ai."},{"verse":12,"text":"Ma sa poloaiina e Atua le tagata, e faapea: O laau uma o le faatoaga e mafai ona e ’ai saoloto ai,"},{"verse":13,"text":"Ae o le laau e iloa ai le lelei ma le leaga, aua e te ’ai ai; aua o le taimi e te ’aia ai, e te oti ai lava. O lenei, o a’u o Aperaamo, sa ou vaai o lea taimi sa tusa ma le taimi a le Alii, lea sa tusa ma le taimi o Kolape; ona e lei tuuina atu e Atua ia Atamu i le taimi lea le faitauga o lana taimi."},{"verse":14,"text":"Ma sa fetalai ane Atua: Inā tatou faia ia o se fesoasoani e tatau ai mo le tane, aua e lē lelei ona nofo toatasi o le tane, o le mea lea o le a tatou faia ai se fesoasoani e tatau mo ia."},{"verse":15,"text":"Ma sa faia e Atua ia oo mai se moegase i luga o Atamu; ma sa moe o ia, ma sa latou toina mai se tasi o ona ivi ’aso’aso, ma so’o le aano i lona tulaga;"},{"verse":16,"text":"Ma o le ivi ’aso’aso na to mai e Atua mai le tane, na latou faia ai se fafine, ma aumai o ia i le tane."},{"verse":17,"text":"Ma sa fai mai Atamu: O le ivi lenei sa o se ivi o o’u ivi, ma aano o o’u aano; o lenei o le a ta’ua o ia o le Fafine, aua sa to mai o ia i fafo o le tane;"},{"verse":18,"text":"O lea e tuua ai e se tane lona tamā ma lona tinā, ma pipii atu i lana ava, ma avea i la’ua ma tino e tasi."},{"verse":19,"text":"Ma sa lē lavalavā i la’ua uma, le tane ma lana ava, ma sa lē maasiasi."},{"verse":20,"text":"Ma sa faia e Atua mai le eleele manu vaefa tetele taitasi o le fanua, ma manu felelei taitasi o le ea, ma aumai i latou ia Atamu e vaai po o a e ta’ua ai e ia i latou; ma o le a lava na ta’ua ai e Atamu meaola taitasi, o lona igoa lava lena."},{"verse":21,"text":"Ma sa tuu atu e Atamu ni igoa i lafu manu uma, i manu felelei uma o le ea, ma manu vaefa uma o le fanua; ae o Atamu, sa maua se fesoasoani e tatau ai mo ia."}]}]},{"id":"joseph-smith-matthew","title":"Iosefa Samita—Mataio","englishTitle":"Joseph Smith-Matthew","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Aua Ou te fai atu ia te outou, o le a outou lē vaai mai ia te a’u mai le taimi nei ma le agai i luma ma iloa o A’u o ia o lē ua tusi i ai perofeta, seia outou fai ane: Faamanu lava ia te ia o lē ua maliu mai i le suafa o le Alii, i ao o le lagi, ma agelu paia uma faatasi ma ia. Ona malamalama ai lea o ona soo o le a toe afio mai o ia i le lalolagi, pe a uma ona faamamaluina ma faapaleina o ia i le lima taumatau o le Atua."},{"verse":2,"text":"Ma sa ulufafo atu Iesu, ma afio ese mai le malumalu; ma sa o ane ona soo ia te ia, e fia faalogologo ia te ia, ua faapea atu: Le Matai e, faaali mai ia te i matou e uiga i fale o le malumalu, e pei ona e fetalai mai—O le a soloia i latou i lalo, ma tuua tuufua ia te outou."},{"verse":3,"text":"Ma sa fetalai atu Iesu ia te i latou: Tou te le vaai atu ea i nei mea uma, ma outou le malamalama i ai? E moni Ou te fai atu ia te outou, o le a le toe i ai iinei, i luga o lenei malumalu, se maa e tasi i luga o le isi e lē soloia i lalo."},{"verse":4,"text":"Ma sa tuua e Iesu i latou, ma afio a’e i le Mauga o Olive. Ma a’o nofo o ia i luga o le Mauga o Olive, sa o ane ona soo ia te ia na’o i latou, ua faapea atu: Ta’u mai ia te i matou po o afea e oo mai ai ia mea na e fetalai mai ai e uiga i le faatafunaga o le malumalu, ma tagata Iutaia; ma o le a foi le faailoga o lou afio mai, ma le iuga o le lalolagi, po o le faaumatiaga o e e amioleaga, o le iuga lea o le lalolagi?"},{"verse":5,"text":"Ma sa tali atu Iesu, ma fetalai atu ia te i latou: Ia faaeteete ia lē faaseseina outou e se tagata;"},{"verse":6,"text":"Aua e toatele o le a o mai i lo’u igoa, ma faapea—o a’u o Keriso—ma o le a faaseseina ai le toatele;"},{"verse":7,"text":"Ona latou tuuina atu ai lea o outou ia faapuapuagatiaina, ma fasioti ia te outou, ma o le a itagia outou e atunuu uma, ona o lo’u igoa;"},{"verse":8,"text":"Ma ona tausuai ai lea o le toatele, ma o le a faalata le tasi i le isi, ma o le a inoino le tasi i le isi;"},{"verse":9,"text":"Ma e toatele perofeta pepelo o le a tutulai mai, ma o le a latou faaseseina le toatele;"},{"verse":10,"text":"Ma ona o le a tele le amioleaga, o le a faasolo ina faaitiitia le alofa o le toatele;"},{"verse":11,"text":"Ae o ia o le e nofo tumau ma lē faatoilaloina, o ia lava lea o le a faaolaina."},{"verse":12,"text":"O lea, a outou vaai i le inosia o le faatafunaga, na fetalai ai Tanielu le perofeta, e faatatau i le faafanoga o Ierusalema, ona outou tutulai lea i le mea paia; ’ai se e faitau ia tuu atu ia te ia ia malamalama."},{"verse":13,"text":"Ona tuu atu lea ia i latou o e o i ai i Iutaia ia sosola i mauga;"},{"verse":14,"text":"Ia tuu atu ia te ia o lē ua i luga o le tumutumu o le fale ia sola ese, ma ia le foi mai e ave se mea i fafo mai lona fale;"},{"verse":15,"text":"Pe tuu atu ia te ia o lē o i le fanua e foi atu e ave ona ofu;"},{"verse":16,"text":"Ma oi talofa ia te i latou e maitaga, ma i latou o e e failelele i aso na;"},{"verse":17,"text":"O lea, ia outou tatalo atu i le Alii ia lē i le taumalulu la outou sola’aga, pe i le aso Sapati foi;"},{"verse":18,"text":"Aua o le taimi lea, i na aso, o le a i ai le puapuaga tele i luga o tagata Iutaia, ma luga o e e nonofo i Ierusalema, sa lei faapea ona oo atu muamua i luga o Isaraelu, e le Atua, talu mai le amataga o lo latou malo seia oo mai i le taimi nei; e leai, pe toe auina atu lava i luga o Isaraelu."},{"verse":19,"text":"O mea uma ua pa’u’ū ifo ia te i latou ua na’o se amataga o faanoanoaga ia o le a oo mai i o latou luga."},{"verse":20,"text":"Ma vagana ai ua faapupuuina na aso, o le a leai se tagata o i latou e faaolaina; ae ona o e ua filifilia, e tusa ma le feagaiga, o le a faapupuuina na aso."},{"verse":21,"text":"Faauta, o nei mea ua Ou tautala atu ai ia te outou e faatatau i tagata Iutaia; ma le tasi, a mavae le puapuagatia o aso na o le a oo mai i luga o Ierusalema, afai e fai mai se tagata ia te outou, Faauta, o iinei Keriso, po o iina, aua nei talitonu ia te ia;"},{"verse":22,"text":"Aua i aso na o le a tutulai a’e ai foi Keriso pepelo, ma perofeta pepelo, ma o le a latou faaali mai faailoga tetele ma mea e ofo ai, e oo ina a mafai, o le a latou faaseseina ai lava e ua filifilia, o e ua filifilia e tusa ma le feagaiga."},{"verse":23,"text":"Faauta, ua Ou tautala atu nei mea ia te outou ona o e ua filifilia; ma o le a outou faalogo foi i taua ma tala o taua; vaai ia lē faaatuatuvaleina outou, aua o mea uma ua Ou ta’u atu ia te outou o le a faataunuuina lava; peitai e lei oo mai lava le iuga."},{"verse":24,"text":"Faauta, sa Ou ta’u muamua atu ia te outou;"},{"verse":25,"text":"O le mea lea, afai latou te fai mai ia te outou: Faauta, ua i ai o ia i le toafa; aua tou te o i ai: Faauta, ua i ai o ia i afeafe faalilolilo; aua tou te talitonu i ai;"},{"verse":26,"text":"Aua e pei ona sau le malamalama o le taeao mai sasa’e, ma susulu atu lava i sisifo, ma sulugia ai le lalolagi atoa, o le a faapea foi le afio mai o le Atalii o le Tagata."},{"verse":27,"text":"Ma o lenei Ou te faaali atu ia te outou se faataoto. Faauta, soo se mea e i ai se tino mate, o iina e aofaga faatasi i ai aeto; o le a faapena foi ona faapotopotoina o la’u au filifilia mai itu e fa o le lalolagi."},{"verse":28,"text":"Ma o le a latou faalogo i taua, ma tala o taua."},{"verse":29,"text":"Faauta, ou te tautala atu ona o la’u ’au filifilia; aua o le a tulai a’e le atunuu e faasaga i le tasi atunuu, ma le malo e faasaga i le tasi malo; o le a i ai oge, ma faama’i, ma mafuie, i nofoaga eseese."},{"verse":30,"text":"Ma o lea foi, ona o le a tele le amioleaga, o le a faasolo ina faaitiitia le alofa o tagata; ae o ia o lē e lē faatoilaloina, o ia lava lea o le a faaolaina."},{"verse":31,"text":"Ma o lea foi, o lenei Talalelei o le Malo o le a tala’i atu i le lalolagi atoa, mo se molimau i atunuu uma, ma ona oo mai ai lea o le iuga, po o le faaumatiaga o e e amioleaga;"},{"verse":32,"text":"Ma o lea foi o le mea inosia e faatafuna ai, na tautala i ai le perofeta o Tanielu, o le a faataunuuina."},{"verse":33,"text":"Ma i le taimi lava pe a mavae atu le puapuagatia o na aso, o le a faapouliuligia le la, ma o le a lē faasusuluina mai e le masina lona malamalama, ma o le a pa’u’ū ifo fetu mai le lagi, ma o le a lūlūina ai mana o le lagi."},{"verse":34,"text":"E moni, Ou te fai atu ia te outou, o lenei tupulaga, lea o le a faaali atu ai nei mea, o le a lē mavae atu seia faataunuuina mea uma ua Ou fai atu ai ia te outou."},{"verse":35,"text":"E ui i lea, e oo mai aso, o le a mavae atu ai le lagi ma le lalolagi; ae o a’u upu o le a le mavae atu lava, ae o le a faataunuuina uma."},{"verse":36,"text":"Ma, e pei ona Ou muai fai atu, a mavae le puapuagatia o na aso, ma lūlūina mana o le lagi, ona vaaia ai lea o le faailoga o le Atalii o le Tagata i le lagi, ma ona faavauvau ai lea o ituaiga uma o le lalolagi; ma o le a latou vaai i le Atalii o le Tagata ua afio mai i ao o le lagi, ma le mana ma le mamalu tele;"},{"verse":37,"text":"Ma ai se na te teu faaoloaina taua a’u upu, o le a lē faaseseina, aua o le a afio mai le Atalii o le Tagata, ma o le a ia auina mai ana agelu i luma o ia ma le leo tele o se pu, ma o le a latou aofaga faatasi le vaega o totoe o lana ’au filifilia mai matagi e fa, mai le tasi tuluiga o le lagi i le isi."},{"verse":38,"text":"O lea ia a’oa’o i se faataoto e uiga i le laau o le mati—A’o mu’amu’a lava ona lala, ma amata ona ia faafotu mai lau, tou te iloa ai ua latalata lava ona oo mai le tau mafanafana;"},{"verse":39,"text":"E faapena foi, la’u ’au filifilia, pe a latou vaai i nei mea uma, o le a latou iloa ua lata mai o ia, ua i faitotoa lava;"},{"verse":40,"text":"Ae i lena aso, ma le itula, e leai se tasi na te iloaina; e leai, e le iloa e agelu a le Atua i le lagi, ae nao lo’u Tamā lava."},{"verse":41,"text":"Ae e pei ona sa i ai i aso o Noa, o le a faapea foi ona i ai i le afio mai o le Atalii o le Tagata;"},{"verse":42,"text":"Ona o le a i ai ia te i latou, e pei ona sa i ai i aso ao lei oo mai le lolo; auā seia oo mai i le aso na ulu ai Noa i totonu o le vaa sa latou aai ma inu, faaipoipo ma tuuina atu i le faaipoipoga;"},{"verse":43,"text":"Ma sa latou lē iloa seia oo ina sau le lolo, ma aveesea i latou uma; o le a faapena foi ona i ai i le afio mai o le Atalii o le Tagata."},{"verse":44,"text":"Ona faataunuuina ai lea o le mea ua tusia, e faapea i aso e gata ai, e toalua o le a i ai i le fanua, o le a aveina le tasi, ma e tuua le isi;"},{"verse":45,"text":"E toalua o le a olo i le mea olo saito, o le a aveina le tasi, ma e tuua le isi;"},{"verse":46,"text":"Ma o le mea Ou te fai atu ai i le toatasi, Ou te fai atu ai i tagata uma; o lea, ia mataala ai, auā tou te le iloa le itula e afio mai ai lo outou Alii."},{"verse":47,"text":"Ae ia outou iloa le mea lenei, a na fai e iloa e le matai o le fale le itupo e sau ai le gaoi, semanu e vaavaai o ia, ma semanu e le tuua lona fale ia lepetia, ae manu o saunia."},{"verse":48,"text":"O lea ia outou saunia foi, ona o se itula faapea tou te lē manatu i ai, e afio mai ai le Atalii o le Tagata."},{"verse":49,"text":"O ai, la, o se auauna faamaoni ma le poto, o lē ua faia e lona alii e pule i lona auaiga, e tuu atu ia te i latou meaai i le tau e tatau ai?"},{"verse":50,"text":"Amuia lava lena auauna o lē e maua mai e lona alii, pe a afio mai o ia, o faia faapea e ia; ma e moni Ou te fai atu ia te outou, o le a faia e ia o ia ma pule i ana mea uma."},{"verse":51,"text":"Ae afai e fai ifo lena auauna leaga i lona loto: Ua faatuai e lo’u alii lona afio mai,"},{"verse":52,"text":"Ma amata ona ia sasa ona uso-a-auauna, ma ’ai ma inu faatasi ma e onanā,"},{"verse":53,"text":"O le a afio mai le alii o lena auauna i se aso pe a lē vaavaai o ia mo ia, ma i se itula e lē iloa e ia,"},{"verse":54,"text":"Ma o le a vavae ese o ia, ma o le a tofi ia te ia lana vaega faatasi ma e e talapepelo; o iina o le a i ai le tagiauē ma le lilivau o nifo."},{"verse":55,"text":"Ma o le a faapea ona oo mai le iuga o e amioleaga, e tusa ma le valoaga a Mose, ua faapea: O le a vavae ese i latou mai totonu o le nuu; peitai e lei oo mai lava i le iuga o le lalolagi, ae ua lata mai lava."}]}]},{"id":"joseph-smith-history","title":"Iosefa Samita—Talafaasolopito","englishTitle":"Joseph Smith-History","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Ona o le tele o tala ua faasalalauina e tagata loto leaga ma fai togafiti, e faatatau i le tulai mai ma le alualu i luma O Le Ekalesia a Iesu Keriso o le Au Paia o Aso e Gata Ai, o ia tala uma ua fuafua e tagata na faia e tau faasaga ai i lona ta’uleleia o se Ekalesia ma lona alualu i luma i le lalolagi—o lea ua uuna’ia ai a’u e tusia lenei talafaasolopito, e faasa’o ai mafaufau o tagata lautele, ma tuu atu ai i tagata sailiili uma le mea moni ia maua tala sa’o, e pei ona tutupu mai, e faatatau uma ia te a’u ma le Ekalesia, e pei ona i ai ia te a’u le tonu o ia mea."},{"verse":2,"text":"I lenei talafaasolopito o le a ou tuu atu ai mea eseese na tutupu e faatatau i lenei Ekalesia, i le moni ma le amiotonu, e pei ona tutupu mai, pe e pei ona i ai nei, i le tausaga lenei lona valu [1838] talu le faatulagaina o le Ekalesia ua ta’ua."},{"verse":3,"text":"Na ou fanau i le tausaga o lo tatou Alii e tasi le afe valu selau ma le lima, i le aso luasefulu-tolu o Tesema, i le nuu o Sarona, i le itumalo o Uinisoa, i le Setete o Veromota. … Sa tuua e lo’u tamā, o Iosefa Samita, Matua, le Setete o Veromota, ma siitia atu i Palamaira, i le itumalo o Onatario (ua ta’ua nei o Wayne), i le Setete o Niu Ioka, ina ua sefulu o’u tausaga, po o se mea latalata i lena. Pe tusa o le fa tausaga talu ona taunuu lo’u tamā i Palamaira, na siitia atu ai o ia ma lona aiga i Manaseta i le itumalo lava lea o Onatario—"},{"verse":4,"text":"Sa i ai i lona aiga ni tagata e toasefulutasi, o igoa, o lo’u tamā, o Iosefa Samita; lo’u tinā, o Lusi Samita (o lona igoa faaiu, ae lei faaipoipo o ia, o Maki, o le afafine o Solomon Maki); o’u uso, o Alevini (o lē na maliu ia Novema 19, 1823, i le tausaga e 26 o lona matua), o Ailama, o a’u, Samuel Harrison, Viliamu, Don Carlos; ma o’u tuafafine o Sophronia, Katerina, ma Lusi."},{"verse":5,"text":"I se taimi i le lona lua o tausaga ina ua mavae lo matou siitia atu i Manaseta, sa i ai i le nofoaga i le mea na matou nonofo ai se vāvāō tulaga ese e uiga i le mataupu tau lotu. Sa amata i le Metotisi, ae sa vave ona salalau atu i totonu o ituaiga uma o lotu i le itulagi lena o le atunuu. E moni, sa foliga mai ua aafia ai le itu atoa o le atunuu, ma sa faapotopoto faatasi tagata e toatele i a latou lava aulotu eseese, lea e le o se vevesi ma se fevaevaeaiga itiiti na tupu mai ai i totonu o tagata, sa alalaga ni isi, “Faauta, o iinei!” ma o isi, “Faauta, o iina!” O ni isi sa finau mo le faatuatuaga Metotisi, o ni isi mo le Peresipeteriana, ma isi mo le lotu Papatiso."},{"verse":6,"text":"Ona, e ui i le alofa tele sa ta’ua e tagata liliu i ia faatuatuaga eseese i le taimi o lo latou liliu atu, ma le sogasoga tele sa faaalia e faifeau eseese, o e sa toaaga e tutulai ma faalauteleina lenei vaaiga uiga ese o lagona faalelotu, ina ia faaliliu mai tagata uma, e pei ona sa latou fiafia e ta’u ai lena mea, e tuu i latou po o le a le ituaiga e fia auai; ae ina ua amata ona o atu o tagata liliu, o ni isi i se tasi vaega ma ni isi i se isi, sa foliga mai o lagona lelei o faifeau atoa ma tagata liliu mai sa tele atu ona faatagafai nai lo le moni; ona o’o mai ai lea o se tulaga o se faanunununu tele ma le loto leaga—ua finau lea faifeau e faasaga i lea faifeau, ma lea tagata liliu e faasaga i lea tagata liliu mai; sa oo ina o latou lagona lelei uma o le tasi mo le isi, pe afai sa i ai ia i latou ni lagona lelei, sa mou ese atoa i se feupua’iga ma se finauga e uiga i manatu."},{"verse":7,"text":"O le taimi lea ua savali ai le sefululima o o’u tausaga. Sa tala’i mai le faatuatuaga Peresipeteriana i le aiga o lo’u tama, ma e toafa i latou na auai i le ekalesia lena, o o latou igoa, o lo’u tinā, o Lucy; o o’u uso o Ailama ma Samuel Harrison; ma lo’u tuafafine o Sophronia."},{"verse":8,"text":"I le gasologa o lea taimi o le vāvāō tele sa faaosoina ai lo’u mafaufau e manatunatu mamafa ma le mautonu tele; ae e ui ina sa loloto o’u mafaufauga ma malosi i le tele o taimi, ae sa ou le auai lava i se tasi o ia vaega uma, e ui ina sa ou auai i a latou faatasiga eseese i le tele o taimi sa mafai ai. A’o faasolo le taimi sa oo ina tau faapito lava lo’u mafaufau i le lotu Metotisi, ma sa ou lagona se manao e auai faatasi ma i latou; peitai sa matua tele na’uā le faanunununu ma le fefinauai i totonu o lotu eseese, sa le mafai e se tagata talavou e pei ona sa ou i ai, ma le lē masani tele i tagata ma mea, ona maua se faaiuga mautinoa po o ai ua sa’o ma o ai foi ua sese."},{"verse":9,"text":"Sa faaosoina tele lo’u mafaufau i lea taimi ma lea taimi, ona sa matua tele lava ma le le mataofia le alaga ma le vevesi. Sa malosi tele le au Peresipeteriana e faasaga i le au Papatiso ma le au Metotisi, ma sa latou faaaoga mana uma o le faalemafaufau ma faafilosifia e faamaonia ai o latou sese, pe ina ia, uunaia ai tagata ia manatu ua sese i latou. Ae i le isi itu, sa faapea foi ona tutusa o le sogasoga o le au Papatiso ma le au Metotisi i la latou itu pa i le taumafaiga e faamaumautu a latou lava mataupu ma ta’u sese isi uma."},{"verse":10,"text":"I le taulotoaiga o lenei taua o upu ma vevesi o taofi, sa masani ona ou fai ifo ai ia te a’u lava ia: O le a le mea e ao ina faia? O ai o nei vaega uma ua sa’o; pe, ua sese faatasi ea i latou uma? Afai e i ai se tasi o i latou ua sa’o, o ai lea, ma e faapefea ona ou iloaina?"},{"verse":11,"text":"A’o ou mafatia faalemafaufau ona o faigata sili na mafua mai finauga a nei vaega o tapuaiga, sa ou faitauina i se tasi aso le Tusi a Iakopo, mataupu muamua ma le fuaiupu lima, e faitau faapea: Ae afai ua leai se poto i so outou, inā ole atu ia i le Atua, o lē foai tele mai i tagata uma, ma le lē toe a’oa’ia; ona foa’iina mai ai lea ia te ia."},{"verse":12,"text":"E leai lava se mau o tusitusiga paia na oo mai i le loto o se tagata ma le mana tele nai lo o lenei mau i lo’u loto i lea taimi. Sa foliga ua ulu mai ma se mana tele i lagona uma o lo’u loto. Sa ou mafaufau ma saga mafaufau pea i ai, i lo’u iloa afai e i ai se tagata ua ia manaomia le poto mai le Atua, o a’u lava; ona sa ou le iloa le mea e tatau ona fai, ma e vagana ai e mafai ona ou maua o se poto atili atu nai lo lena sa i ai ia te a’u i le taimi lena, o le a ou le iloaina lava; aua sa matua eseese lava malamalama o faiaoga o mea tau lotu o ituaiga eseese i mau e tasi sa lepetia ai le faamoemoe atoa o le liliu atu i le Tusi Paia e tali ai le fesili."},{"verse":13,"text":"Ina ua mavae se taimi, sa oo ina ou taunuu i le faaiuga o lo’u tumau pea i le pogisa ma le fenumiai, pe ou te faia e pei ona faatonu mai e Iakopo, o lona uiga, ia ole atu i le Atua. Ina ua mavae se taimi sa ou filifili e “ole atu i le Atua,” i le manatu ifo afai e tuu mai e ia le poto ia i latou ua leai se poto, ma foai tele mai, ma lē a’oa’ia mai, atonu o le a ou taumafai i ai."},{"verse":14,"text":"O lea, e tusa ai ma lenei faamoemoe, o la’u filifiliga e ole atu ai i le Atua, sa ou alu atu ai i le togavao e faia lenei taumafaiga. O le taeao o se aso matagofie lava ma le manino, i le amataga lava o le tau totogo o le afe valu selau luasefulu. O le taimi muamua lava lea i lo’u olaga na ou faia ai se taumafaiga faapea, ona i le lotolotoi o o’u atuatuvalega uma, sa ou lei faia lava se taumafaiga e tatalo atu ma le leo."},{"verse":15,"text":"Ina ua mavae ona ou taunuu i le mea na ou muai filifilia ou te alu atu i ai, ina ua mavae ona ou vaavaai solo faataamilo ane ia te a’u, ma ina ua ou iloa ua na’o a’u lava, sa ou tootuli ifo ma amata ona tuu atu manaoga o lo’u loto i le Atua. Sa lei umi lava ona ou faia faapea, ae vave loa ona taofia o a’u e se mana sa lofitu atoa ai a’u, ma sa i ai sona mana uiga ese i luga o a’u sa taofia ai lo’u laulaufaiva ina ia lē mafai ona ou tautala. Sa siomia a’u i se pouliuli mafiafia, ma sa foliga mai ia te a’u i se taimi e peiseai ua malaia a’u i se faafanoga faafuasei."},{"verse":16,"text":"Peitai, i le faaaogaina o lo’u malosi atoa e valaau atu ai i le Atua e laveai a’u mai le mana o lenei fili sa taofia a’u, ma i le taimi tonu lava na ou sauni ai e goto ifo i se tulaga e aunoa ma se faamoemoe ma tuu atu a’u lava i le faafanoga—e lē i se malaia fai fua faalemafaufau, ae i le mana o se tagata moni lava mai le lalolagi lē vaaia, o lē sa i ai se mana ofoofogia tele faapea ou te lei faalogoina muamua lava i se tagata—i lea lava taimi o le atuatuvale tele, na ou vaaia ai se malamalama faaniutu i luga a’e tonu lava o lo’u ulu, ua sili atu le pupula i le la, ua alu ifo malie lava seia oo mai i o’u luga."},{"verse":17,"text":"Sa lei pine lava ona oo mai ae ou faalogoina ua laveaiina a’u mai le fili na taofia a’u. Ina ua oo mai le malamalama i o’u luga, sa ou vaaia ni Tagata e toalua, o lo la’ua pupula ma le mamalu e lē mafaamatalaina, o tutu a’e i o’u luga i le ea. Sa fetalai mai le tasi o i la’ua ia te a’u, ma fofoga mai ia te a’u i lo’u igoa ma fetalai mai, a’o tusi ane i le isi—O Lo’u Atalii Pele lenei. Faalogo ia te Ia!"},{"verse":18,"text":"O lo’u faamoemoe i le alu e ole atu i le Alii o le fia iloa lea po o le fea o nei lotu uma ua sa’o, ina ia ou iloa le lotu ou te auai. O lea, sa lei umi ona ou maua o le pule ia te a’u, ina ia mafai ona ou tautala atu, sa ou fesili atu i Tagata o e sa tutu mai i o’u luga i totonu o le malamalama, po o le fea o nei lotu uma ua sa’o (ona o le taimi lea sa lei oo mai lava i lo’u loto e faapea ua sese lotu uma)—ma pe o le fea e tatau ona ou auai."},{"verse":19,"text":"Sa tali mai ia te a’u ia ou le auai i se tasi o i latou, aua ua sese i latou uma; ma sa fai mai le Tagata o lē na fetalai mai ia te a’u e faapea o o latou talitonuga uma o ni mea inosia i lana silafaga; o na polofesa ua sese uma; e faapea: “ua latou faalatalata mai ia te a’u i o latou laugutu, a o o latou loto ua mamao mai ia te a’u, ua latou a’oa’o mo aoaoga faavae poloaiga a tagata, ua foliga ua faaleatua, ae ua latou faafitia le mana o i ai.”"},{"verse":20,"text":"Sa ia toe vavao a’u mai i le ’auai i soo se tasi o nei lotu; ma e tele isi mea na ia fetalai mai ia te a’u, e lē mafai ona ou tusia i le taimi nei. Ina ua ou toe malamalama, sa ou iloa ua ou taoto i lo’u tua, ma vaai a’e i le lagi. Ina ua alu ese atu le malamalama, sa leai so’u malosi; ae e lei umi ae toe maua sina malosi, sa ou alu i le fale. Ma a’o ou faalagolago atu i le magalafu, sa fesili mai lo’u tinā po o le a se mea ua tupu. Sa ou tali atu, “Aua e te popole, o loo lelei mea uma—o loo lelei lava a’u.” Ona ou fai atu lea i lo’u tinā, “Ua ou iloa nei mo a’u lava ia ua lē moni le lotu Peresipeteriana.” Sa foliga mai e peiseai sa iloa e le fili, i le vaitaimi muamua lava o lo’u olaga, ua tuupoina a’u e avea ma faalavelave ma faasoesa i lona malo; a lē o lea, aisea ua aufaatasi ai mana o le pouliuli e faasaga mai ia te a’u? Aisea ua tutupu a’e ai le tetee ma sauaga faasaga mai ia te a’u, toetoe i lo’u tamameamea?"},{"verse":21,"text":"I ni nai aso itiiti ina ua mavae ona ou maua o lenei faaaliga vaaia, sa ma faatasi ai ma se tasi o faifeau Metotisi, o lē sa malosi lava i le vāvāō faalelotu sa ta’ua muamua; ma, a’o ma talanoa ma ia e uiga i le mataupu o mea tau lotu, sa ou faaaogaina, le avanoa e tuu atu ai ia te ia se tala e uiga i le faaaliga lea na ou maua. Sa ou ofo lava i lona uiga; sa lē gata ina manatu faatauvaa o ia i la’u faamatalaga, ae ma le inoino tele, ua fai mai o lea mea atoa ua mai le tiapolo, e faapea ua lē toe i ai ni mea faapea o faaaliga vaaia po o faaaliga i ona po nei; e faapea o mea uma faapena sa gata i aposetolo, ma e faapea o le a lē toe i ai lava ia mea."},{"verse":22,"text":"E ui i lea, sa vave ona ou iloa, o lo’u faamatala atu o le tala sa faaosoina ai se faailoga tagata tele faasaga mai ia te a’u i totonu o polofesa o mea tau lotu, ma sa avea ma pogai o sauaga tele, sa faateteleina pea lava; ma e ui o a’u o se tama lē taualoa, na’o le sefulufa i le sefululima tausaga le matua, ma o o’u tulaga i le olaga o le ituaiga e faia ai se tama e lē taulia i le lalolagi, peitai sa lava ona matau lelei e tagata tulaga maualuluga e faaosofia ai mafaufauga o tagata lautele e faasaga mai ia te a’u, ma faatupu ai se sauaga tele; ma sa taatele lenei mea i totonu o ituaiga uma—sa aufaatasi uma e sauaina a’u."},{"verse":23,"text":"O ia mea sa mafua ai ona ou mafaufau loloto ai i le taimi lena, ma i le tele o taimi talu mai ai, i le uiga ese moni lava, o le avea o se tama lē taualoa, e sili laitiiti atu i le sefulufa tausaga le matua, ma o se tasi foi, o se sa faamalosia i le tatau ai ona maua o ni nai mea iti e ola ai i ana galuega i aso taitasi, ma se tagata sa mafaufauina ua lava lona taua e amanaia ai e tagata maualuluga o ituaiga lotu sili ona lauiloa o le taimi, ma faatupuina ai ia te i latou i se ala se agaga o le sauaga sili ona malosi ma le taufaifai. Ae e uiga ese pe leai, sa faapea lava, ma sa avea ma pogai o le faanoanoa tele ia te a’u i le tele o taimi."},{"verse":24,"text":"Ae ui i lea, o se mea moni lava na ou vaai i se faaaliga vaaia. Sa ou mafaufau talu mai lena mea, pei e tai tutusa o’u lagona ma Paulo, i le taimi na faia ai e ia lana faamatalaga tetee i luma o le Tupu o Akeripa, ma faamatala atu le tala e uiga i le faaaliga vaaia na maua e ia i le taimi na vaai ai o ia i se malamalama, ma faalogoina se leo; ae sa toaitiiti lava e sa talitonu ia te ia; sa fai mai ni isi ua lē faamaoni o ia, o ni isi sa fai mai ua fasa o ia; ma sa tauemuina ma upuleagaina o ia. Peitai o nei mea uma sa lē faaumatia ai le moni o lana faaaliga vaaia. Sa vaai o ia i se faaaliga vaaia, sa mautinoa e ia sa vaai i ai, ma e lē mafai e sauaga uma e i lalo ifo o le lagi ona faia i ai se isi mea; ma e tusa pe latou te sauaina ai o ia e oo i le oti, peitai sa iloa e ia, ma o le a ia iloa pea e oo lava i lana toe manava, sa vaai o ia i se malamalama ma faalogoina se leo o fetalai mai ia te ia, ma e lē mafai lava e le lalolagi atoa ona faia o ia ia manatu pe talitonu i se isi mea."},{"verse":25,"text":"Sa faapea foi ia te a’u. Sa ou vaai moni lava i se malamalama, ma i totonu o lena malamalama na ou vaai ai i ni Tagata se toalua, ma sa la’ua fetalai moni mai lava ia te a’u; ma e ui ina sa inosia ma sauaina a’u i lo’u fai atu sa ou vaai i se faaaliga vaaia, ae ua moni; ma a’o latou sauaina a’u, upuleagaina a’u, ma faia ituaiga o tala sese uma o mea leaga e faasaga mai ia te a’u i lo’u fai atu faapea, sa taitaiina a’u e fai ifo i lo’u loto: Aisea ua sauaina ai a’u i lo’u ta’u atu o le mea moni? Sa ou vaai moni lava i se faaaliga vaaia; ma o ai a’u ou te vavao atu ai i le Atua, pe aisea ua manatu ai le lalolagi e faia ia te a’u ia ou faafitia ai le mea na ou vaai moni lava i ai? Aua sa ou vaai i se faaaliga vaaia; sa ou mautinoa lena mea, ma sa ou mautinoa sa silafia e le Atua lena mea, ma e lē mafai ona ou faafitia lena mea, pe ou te fiatoa e fai; sa ou iloa lava o le faia o lea mea o le a ou faatausuai ai i le Atua, ma oo ifo ai i le tausalaga."},{"verse":26,"text":"Ua faamalieina nei lo’u mafaufau e faatatau i le lalolagi faalelotu—e lē o so’u tiute le auai faatasi ma soo se tasi o i latou, ae ia ou tumau pea e pei ona sa ou i ai seia toe faatonuina atili. Sa ou iloa ua moni le molimau a Iakopo—e faapea e mafai e se tagata o se ua leai se poto ona ole atu i le Atua, ma maua mai, ma le lē a’oa’ia."},{"verse":27,"text":"Sa ou faaauau pea ona faia o a’u galuega masani ai i le olaga seia oo i le aso luasefulu-tasi o Setema, tasi le afe valu selau luasefulu-tolu, a’o ou mafatia i taimi uma i sauaga malolosi i lima o vasega eseese uma o tagata, e lolotu ma lē lolotu, aua sa ou ta’utino atu pea sa ou vaai i se faaaliga vaaia."},{"verse":28,"text":"I le va o le taimi na sosoo ane ma le va o le taimi na ou maua ai le faaaliga vaaia ma le tausaga e afe valuselau ma le luasefulu-tolu—ina ua faasaina a’u e auai i soo se ituaiga o lotu o le vaitaimi, ma ona sa ou itiiti lava i tausaga, ma sa sauaina e i latou o e sa tatau ona avea ma a’u uo ma sa agalelei mai ia te a’u, ma afai sa latou manatu ua faaseseina a’u sa tatau ona taumafai i se ala tatau ai ma le alofa e toe aumai ai a’u—sa tuua a’u i ituaiga uma o faaosoosoga; ma, i lo’u faatasitasi ai ma ituaiga uma o tagata eseese, sa masani ona ou pa’ū atu soo i sese valea e tele, ma faaalia vaivaiga o le talavou, ma sese o uiga faalenatura o le tagata; o se mea, ou te faanoanoa e ta’u atu, sa taitai atu ai a’u i faaosoosoga eseese, e inosia i le silafaga a le Atua. I lo’u fai atu o lenei ta’utinoga, e lē tatau ona manatu ane se tasi na ou sala i ni agasala tetele pe matuia. Sa lē i ai lava se uiga e fai se mea faapena i lo’u natura. Ae sa ou sala i le manatu faatauvaa, ma le faatasi ai i ni isi taimi ma aumea totoē, ma isi mea faapena sa lē tusa ai ma le amio lena e tatau ona tauaveina e se tasi o lē ua valaaulia e le Atua e pei ona sa ou i ai. Peitai o le a lē foliga uiga ese lenei mea i soo se tasi o lē na te manatua lo’u talavou, ma ua masani i lo’u uiga masani o le fiafia."},{"verse":29,"text":"Ona o nei mea, sa ou lagona soo ai le tausalaina i o’u vaivaiga ma lē atoatoa; ae i le po o le aso luasefulu-tasi o Setema e pei ona ta’ua i luga, ina ua mavae ona ou malolo atu i lo’u moega i le po, na ou tatalo ma aioi atu ai i le Atua Malosi Aoao mo se faamagaloga o a’u agasala uma ma sese, ma mo se faaaliga mai ia te a’u, ina ia mafai ona ou iloa e uiga i lo’u tulaga ma le mea ou te tulai ai i ona luma; ona sa ia te a’u se faamoemoe atoa i le mauaina o se faaaliga paia, talu ai ona sa ou mauaina se tasi muamua."},{"verse":30,"text":"A’o faapea ona ou valaau atu i le Atua, sa ou vaaia se malamalama ua oo mai i lo’u potu, sa faaauau pea ona faateleina seia oo ina sili atu le malamalama o le potu nai lo le aoauli, ae faaali mai loa se tagata i tafatafa o lo’u moega, ua tulai i le ea, ona sa lē papai ona vae i le fola."},{"verse":31,"text":"Sa ofu o ia i se ofu talaloa lusi sa matuā paepae ma lava. O se paepae sa silisili atu nai lo soo se mea faalelalolagi ua ou vaai i ai; ou te le talitonu foi e i ai se mea faalelalolagi e mafai ona faia ia foliga mai e faapea lona paepae ma le iila. Sa aliali mai ona alofilima, ma ona lima foi, i luga a’e teisi o tapulima; sa faapea foi, ona aliali mai o ona alofivae, faapea ma ona vae, i luga a’e teisi o tapuvae. Sa lē ufitia foi lona ulu ma lona ua. Sa mafai ona ou iloaina sa leai se isi ona ofu sa ofuina ae na’o lea ofu talaloa, aua sa matala, ina ia mafai ona ou vaai atu i lona fatafata."},{"verse":32,"text":"Sa lē gata ina matua paepae tele lona ofu talaloa, ae o lona tagata atoa sa matua mamalu e lē mafai ona faamatalaina, ma o ona fofoga sa pei moni lava o le uila. Sa malamalama tele lava le potu, ae sa lē pupula tele atu e pei ona latalata faataamilo i lona tagata. I le taimi muamua na ou vaai atu ai ia te ia, sa ou fefe; peitai sa vave ona alu ese o le fefe mai ia te a’u."},{"verse":33,"text":"Sa fetalai mai o ia ia te a’u i lo’u igoa, ma fetalai mai ia te a’u o ia o se avefeau na auina mai le Atua ia te a’u, ma e faapea o lona igoa o Moronae; e faapea o i ai i le Atua se galuega mo a’u ou te faia; ma e faapea o lo’u igoa o le a tauleleia ma tauleagaina i totonu o atunuu uma, ituaiga, ma gagana, po o le a tauleleia ma tauleagaina i totonu o nuu uma."},{"verse":34,"text":"Sa fai mai o ia o loo i ai se tusi ua teuina, ua tusia i luga o papatusi auro, ua tuu mai ai se tala e uiga i tagata muamua sa nonofo i le konetineta lenei, ma le mea na latou tupuga mai ai. Sa fai mai foi o ia o loo i ai i totonu o lenei tusi le atoatoaga o le Talalelei tumau e faavavau, e pei ona sa tuuina atu e le Faaola i tagata sa i ai anamua;"},{"verse":35,"text":"Sa i ai foi, ma ni maa e lua i totonu o ni faavaa siliva—ma o ia maa, pe a faapipii i se ufifatafata, ua tino a’i le mea ua ta’ua o le Urima ma le Tumena—ua teuina faatasi ma papatusi; ma o le umia ma le faaaogaina o ia maa sa ta’ua ai tagata o “tagatavāai” i aso anamua po o taimi ua mavae; ma e faapea ua saunia e le Atua ia mea mo le faamoemoe o le faaliliuina o le tusi."},{"verse":36,"text":"Ina ua uma ona ia ta’u mai o ia mea ia te a’u, sa amata ona ia sii mai o valoaga o le Feagaiga Tuai. Sa ia sii muamua mai se vaega o le mataupu lona tolu o le Malaki; ma sa ia sii mai foi le mataupu fa po o le mataupu mulimuli o lea lava valoaga, ae sa i ai sina eseesega itiiti mai le ala ua faitauina ai i a tatou Tusi Paia. Nai lo le sii mai o le fuaiupu muamua e pei ona faitauina i a tatou Tusi Paia, sa sii mai e ia faapea:"},{"verse":37,"text":"Auā faauta, e oo mai le aso o le a mu ai e pei o se umu, ma o e uma e faamaualuluga, ioe, ma e uma e fai amioleaga o le a mu e pei o tagutugutu o saito; ona o le a susunuina i latou e i latou o le a o mai, ua fetalai mai ai le Alii o ’Au, e lē tuua ai mo i latou se a’a po o se lala."},{"verse":38,"text":"Ma le tasi, sa sii mai foi e ia le fuaiupu lima e faapea: Faauta, o le a ou faaali atu ia te outou le Perisitua, e ala i le lima o Elia le perofeta, ae lei oo mai le aso tele ma le matautia o le Alii."},{"verse":39,"text":"Sa ese foi ona ia sii mai o le fuaiupu ua sosoo ai: Ma o le a ia totoina i loto o fanau folafolaga na faia i tamā, ma o le a liliu atu loto o fanau i o latou tamā. Afai e lē faapea, o le a faaumatia atoa le lalolagi i lona afio mai."},{"verse":40,"text":"E faaopoopo i ia mau, sa ia sii mai le mataupu e sefulutasi o le Isaia, ua fai mai ua lata ona faataunuuina. Sa sii mai foi e ia le mataupu e tolu o Galuega, fuaiupu luasefulu-lua ma le luasefulu-tolu, e pei tonu lava ona i ai ia fuaiupu i la tatou Feagaiga Fou. Sa fai mai o ia o lena perofeta o Keriso; ae lei oo mai le aso e “vavae ese ai mai totonu o le nuu i latou o e e lē faalogo i lona leo,” ae ua lata ona oo mai."},{"verse":41,"text":"Sa ia sii mai foi le mataupu lona lua o le Ioelu, mai le fuaiupu luasefulu-valu seia oo i le faaiuga. Sa fai mai foi o ia e lei faataunuuina foi lenei mea, ae ua lata ona faataunuuina. Ma sa ia fetalai faaopoopo mai e faapea ua lata ona oo mai o le atoatoaga o Nuuese. E tele isi mau o tusitusiga paia sa ia sii mai, ma tuuina mai faamalamalamaga e lē mafai ona ta’ua iinei."},{"verse":42,"text":"Ma lenei, sa fai mai o ia ia te a’u, e faapea a ou mauaina na papatusi sa tautala i ai o ia—ona e lei oo mai le taimi e tatau ona maua ai i latou—e lē tatau ona ou faaali atu i latou i soo se tagata; po o le ufifatafata faatasi ma le Urima ma le Tumena; na’o i latou o e o le a poloaiina a’u e faaali atu i ai; afai ou te faia o le a faaumatia a’u. A’o talanoa mai o ia ia te a’u e uiga i papatusi, sa tatalaina se faaaliga vaaia i lo’u mafaufau sa mafai ai ona ou vaai i le mea sa teuina ai papatusi, ma sa matua manino ma malamalama tele sa ou toe iloa lea mea i le taimi na ou asiasi atu i ai."},{"verse":43,"text":"Ina ua mavae lenei fesootaiga, sa ou vaai i le malamalama i totonu o le potu ua amata ona faapotopoto vave ane faataamilo i le tagata o lē na fetalai mai ia te a’u, ma sa faapea lava ona faia pea seia oo ina toe tuua le potu i le pogisa, sei vagana ai le latalata ane faataamilo ia te ia; ae, faafuasei ona ou vaaia, se mea e peiseai, o se ave malamalama sa’o a’e lava i luga i le lagi, ma ua alu a’e ai o ia i luga seia oo ina mou atoa atu o ia, ma sa tuua ai le potu e pei ona sa i ai ae lei oo mai lenei malamalama faalelagi."},{"verse":44,"text":"Sa ou taoto ma mafaufau i le uiga ese o lenei vaaiga, ma ofo tele i mea na ta’u mai ia te a’u e lenei avefeau uiga ese; ae, i le lotolotoi o o’u mafaufauga, sa faafuasei lava ona ou iloa ua amata ona toe malamalama mai lo’u potu, ma i lea lava taimi, e pei ona sa i ai, ua toe tu mai ai lea lava avefeau faalelagi i tafatafa o lo’u moega."},{"verse":45,"text":"Sa amata o ia, ma toe faamatala mai mea tonu lava ia e tasi na ia faia i lana asiasiga muamua, e aunoa ma se eseesega itiiti; o se mea ina ua uma ona faia, sa ia ta’u mai ia te a’u e uiga i faamasinoga tele o le a oo mai i le lalolagi, ma faafanoga tele e ala mai i le oge, le pelu, ma faama’i; ma e faapea o le a oo mai ia faamasinoga mamafa i le lalolagi i le tupulaga lenei. Ina ua uma ona ia faamatala mai o ia mea, sa toe afio a’e o ia e pei ona ia faia muamua."},{"verse":46,"text":"E oo mai i le taimi lea, sa faapea ona matua loloto lava uunaiga ua oo mai i lo’u mafaufau, ua sola ese le fia moe mai i o’u mata, ma sa ou taoto lofituina i le maofa i mea sa ou vaaia ma faalogoina. Ae sa ou ofo ina ua ou toe vaaia lea lava avefeau e tasi i tafatafa o lo’u moega, ma faalogo atu ia te ia ua toe faamatala pe ua toe ta’u mai ia te a’u ia lava mea e tasi e pei o taimi muamua; ma faaopoopo mai se lapataiga ia te a’u, i le fai mai ia te a’u o le a taumafai Satani e faaosooso ia te a’u (ona o le tulaga mativa o le aiga o lo’u tamā), ia maua mai papatusi mo le faamoemoe ia mau’oa ai. O lenei mea sa ia faasa mai ia te a’u, ua fai mai e ao lava ona lē i ai ia te a’u se isi lava faamoemoe i le maua mai o papatusi tau lava o le faamamaluina o le Atua, ma e ao ona lē tosina i se isi lava manaoga nai lo le atiinaeina o lona malo; a lē o lea e lē mafai ona ou mauaina papatusi."},{"verse":47,"text":"Ina ua mavae lenei asiasiga lona tolu, sa toe afio a’e o ia i le lagi e pei o taimi muamua, ma sa toe tuua ai a’u e mafaufau i le uiga ese o mea na faatoa oo mai nei ia te a’u; ae sa toeitiiti vave ane lava ina ua mavae ona afio a’e o le avefeau i le lagi mai ia te a’u i le taimi lona tolu lea, ona vivini lea o le toa, ma sa ou iloa ai ua lata mai le ao, o lea o la ma faatalanoaga sa alu ai lena po atoa."},{"verse":48,"text":"Sa lei umi ona mavae lea ae ou tulai a’e i luga mai lo’u moega, ma, e pei ona masani ai, sa ou alu i galuega tatau ai o le aso; peitai, a’o ou taumafai e galue e pei o isi taimi, sa ou iloa sa matua itiiti lava lo’u malosi sa lē mafai ai ona ou faia se mea. O lo’u tamā, o lē sa galue faatasi ma a’u, sa vaai mai e i ai se mea ua faaletonu ia te a’u, ma fai mai ia te a’u ou te alu i le fale. Sa amata ona ou alu ma le faamoemoe ou te alu i le fale; peitai, ina ua ou taumafai e sopoia le pa i fafo atu o le fanua lea sa ma i ai, sa matua leai lava so’u malosi, ma ou pa’ū vaivai ai i luga o le eleele, ma ou matua lē iloa ai se mea mo se taimi."},{"verse":49,"text":"O le mea muamua lava e mafai ona ou manatua o se leo na fetalai mai ia te a’u, ua valaau mai ia te a’u i lo’u igoa. Sa ou tepa a’e i luga, ma vaaia le avefeau lava lea e tasi o tulai mai i luga a’e o lo’u ulu, na siomia i le malamalama e pei o taimi muamua. Ona ia toe faamatala mai foi lea ia te a’u mea uma na ia faamatala mai ia te a’u i le po ua mavae, ma poloaiina a’u ou te alu i lo’u tamā ma ta’u atu ia te ia e uiga i le faaaliga vaaia ma poloaiga na ou mauaina."},{"verse":50,"text":"Sa ou usiusitai; sa ou toe foi atu i lo’u tamā i le faatoaga, ma faamatala atu ia te ia le mea atoa. Sa tali mai o ia ia te a’u ua mai le Atua, ma fai mai ia te a’u ou te alu ma fai e pei ona poloaiina e le avefeau. Sa ou tuua le faatoaga, ma ou alu i le mea na ta’u mai e le avefeau ia te a’u o loo teuina ai papatusi; ma ona o le manino o le faaaliga vaaia na ou maua e faatatau i ai, sa ou iloa le nofoaga i le taimi lava na ou taunuu ai iina."},{"verse":51,"text":"Latalata i le nuu o Manaseta, i le itumalo o Onatario, i Niu Ioka, o loo tu ai se maupu’epu’e telē lava, ma ua sili ona maualuga i lo soo se isi i le vaiaai. O le itu i sisifo o lenei maupu’epu’e, e lē mamao mai le tumutumu, i lalo o se maa telē lava, sa taatitia ai papatusi, sa teuina i totonu o se pusa maa. O lenei maa sa mafiafia ma lapotopoto i le ogatotonu i le itu i luga, ma manifinifi agai atu i pito, ina ia aliali ai lona ogatotonu i luga o le eleele, ae o le autafa faataamilo atoa sa tanumia i le eleele."},{"verse":52,"text":"Ina ua uma ona ou aveese o le eleele, sa ou aumai se taumoa, lea na ou sulu i lalo o le pito o le maa, ma laga i luga i sina uunaiga itiiti lava. Sa ou tilotilo i totonu, ma o iina na ou vaaia moni ai lava papatusi, le Urima ma le Tumena, ma le ufifatafata, e pei ona sa ta’u mai e le avefeau. O le pusa sa i ai i totonu ia mea sa faia i le faapipii faatasi o ni maa i le ituaiga o simā. I le ta’ele o le pusa sa taatitia faalava ai i le pusa ni maa se lua, ma o luga o ia maa sa taatitia ai papatusi faatasi ma isi mea."},{"verse":53,"text":"Sa ou faia se taumafaiga e aumai na mea i fafo, ae sa vavao mai e le avefeau, ma sa toe ta’u mai e lei oo i le taimi e aumai ai ia mea, pe e oo mai, seia fa tausaga mai le taimi lena; ae sa fai mai o ia ia te a’u e tatau ona ou sau i lena nofoaga i le taimi tonu lava e atoa i ai le tasi o le tausaga mai le taimi lena, ma o le a ia feiloai ai ma a’u iina, ma e tatau ona ou faia pea lava faapea seia oo mai le taimi e tuu mai ai papatusi."},{"verse":54,"text":"Sa faapea lava, e pei ona sa poloaiina ai a’u, ona ou alu i le faaiuga o tausaga taitasi, ma o taimi taitasi na ou maua ai lea lava avefeau iina, ma maua faatonuga ma le malamalama mai ia te ia i taimi taitasi o ā ma faatalanoaga, e faatatau i mea o le a faia e le Alii, ma pe faapefea ma o le a le ala e ta’ita’ia ai lona malo i aso e gata ai."},{"verse":55,"text":"Ona o tulaga faalesoifuaga o lo’u tamā sa utiuti lava, sa tatau ai ia te i matou ona galulue i o matou lima, i le galulue totogi i le aso ma isi mea, pe a matou maua le avanoa. O ni isi taimi sa matou i le fale, ma o ni isi taimi sa matou o ese ai, ma o le galulue pea lava na mafai ai ona matou maua se olaga lelei."},{"verse":56,"text":"I le tausaga e 1823 na feagai ai lo matou aiga ma se puapuaga tele i le maliu o lo’u uso matua, o Alevine. I le masina o Oketopa, 1825, na ou galue totogi ai i se alii matua e suafa ia Josiah Stoal, o lē sa nofo i le itumalo o Seneko, i le Setete o Niu Ioka. Sa faalogo o ia i se tala e uiga i se maina siliva e faapea sa eliina e tagata Sepania i Heremoni, i le itumalo o Susikuana, i le Setete o Penisilevania; ma sa ia eli, ae ou te lei faigaluega ia te ia, ina ia mafai, pe a mafai, ona maua le maina. Ina ua mavae ona ou alu atu e nonofo faatasi ma ia, sa ia ave a’u, faatasi ma le vaega na totoe o ana tagata faigaluega, e eli e su’e le maina, o se mea sa ou galue ai pea e lata i le masina, e aunoa ma se faamanuiaina o la matou taumafaiga, ma sa i’u ina ou faatalitonuina le alii matua e taofi le eli e su’e le maina. O le mea lena na tupu mai ai le tala salalau e faapea o a’u o se tagata eli-tupe."},{"verse":57,"text":"I le taimi na ou faigaluega ai faapena, sa tuu atu ai a’u ou te nofo totogi i le fale o le Susuga a Isaako Hale, o le nuu lena; o iina na ou vaai muamua ai i lo’u toalua o Emma Hale (lona afafine). O le 18 o Ianuari, 1827, na ma faaipoipo ai a’o ou galue pea i le galuega a le alii o Sitolo."},{"verse":58,"text":"Ona o lo’u fai atu pea sa ou vaai i se faaaliga vaaia, sa mulimuli mai ai pea sauaga ia te a’u, ma sa tetee tele le aiga o le tamā o la’u avā i lo ma faaipoipo. O lea, sa tatau ai ia te a’u, ona ou ave o ia i se tasi mea; o lea na ma o ai ma faaipoipo i le fale o Squire Tarbill, i Peniperisi i Saute, i le itumalo o Seneko, Niu Ioka. I se taimi vave lava ina ua uma la’u faaipoipoga, na ou tuua ai le Susuga a Sitolo, ma ou alu i le fale o lo’u tamā, ma faifaatoaga faatasi ma ia i le tau lena."},{"verse":59,"text":"Sa oo ina oo mai le taimi mo le aumaia o papatusi, le Urima ma le Tumena, ma le ufifatafata. O le aso luasefulu-lua o Setema, tasi le afe valu selau luasefulu-fitu, ina ua ou alu atu e pei ona masani ai i le faaiuga o se tausaga i le mea na teu ai ia mea, na tuu mai ai ia te a’u e lea lava avefeau faalelagi ma le poloaiga lenei: e faapea ua ia te a’u le tausiga o ia mea; e faapea afai ou te tuua solo ia mea ma le faatalalē, pe i so’u faatamala, o le a vavaeeseina a’u; ae afai ou te faaaoga a’u taumafaiga uma e faasaoina ai, sei oo ina sau ai o ia, le avefeau lea, mo ia mea, o le a puipuia lava ia mea."},{"verse":60,"text":"Sa vave ona ou iloa le pogai na ou mauaina ni poloaiga patino ia tausia saogalemu ia mea, ma le pogai na fai mai ai le avefeau a uma ona ou faia o le mea ua manaomia mai lo’u lima, o le a ia sau mo ia mea. Ona sa lei umi lava ona iloa ua ia te a’u ia mea, ae faaaoga taumafaiga malolosi silisili e aveese ai mai ia te a’u. Sa faaaoga togafiti uma sa mafai ona faia mo lena faamoemoe. Sa oo ina matua faateleina le feitagai ma le matautia o sauaga nai lo le taimi muamua, ma sa nofouta pea lava motu o tagata e fao ia mea mai ia te a’u pe a mafai. Peitai o le poto o le Atua, na tumau malupuipuia ai pea ia mea i o’u lima, seia oo ina maea ona ou faataunuuina ai mea na manaomia mai lo’u lima. Ma oo ai e tusa ma tuutuuga, na oo mai le avefeau mo ia mea, ma ou tuu atu ai ia te ia; ma ua i ai ia mea i lana tausiga seia oo mai i le aso nei, le aso lua lea o Me, tasi le afe valu selau ma le tolu sefulu-valu."},{"verse":61,"text":"E ui i lea, sa faaauau pea lava le vāvāō, ma o tala aave ma ona laulaufaiva e afe sa galue i taimi uma e faasalalau ai tala sese e uiga i le aiga o lo’u tamā, ma e uiga ia te a’u. Afai ou te faamatala atu le tasi vae afe o i latou, e tutumu ai tusi e tele. E ui i lea, sa oo ina matuā lē magafatiaina sauaga ma sa tatau ai ia te a’u ona tuua Manaseta, ma o atu ma la’u avā i le itumalo o Susikuana, i le Setete o Penisilevania. A’o ma sauni e amata ona malaga atu—i le matitiva tele, ma le mamafa tele o sauaga i luga o i ma’ua sa leai se mea atonu o le a ma i ai i se isi tulaga ese mai—i le lotolotoi o lo ma puapuagatia na ma maua ai se uo i se alii e suafa ia Matini Harisi, o lē na sau ia i ma’ua ma tuu mai ia te a’u se limasefulu tālā e fesoasoani ia i ma’ua i la ma malaga. O le Susuga a Matini Harisi o se sa nofo i le nuu o Palamaira, i le itumalo o Wayne, i le Setete o Niu Ioka, ma o se faifaatoaga aloaia."},{"verse":62,"text":"O lea lava fesoasoani na oo mai i le taimi na manaomia ai, na mafai ai ona ou oo atu i le nofoaga o lo’u faamoemoe i Penisilevania; ma i le taimi lava ina ua mavae lo’u taunuu atu na amata ai ona ou kopiina togitogiga mai papatusi. E tele togitogiga na ou kopiina, ma sa ou faaliliuina ni isi o i latou e ala i le Urima ma le Tumena, o se mea sa ou faia i le va o le taimi na ou taunuu ai i le fale o le tamā o la’u ava, i le masina o Tesema, ma Fepuari na sosoo ai."},{"verse":63,"text":"I se taimi o le masina lenei o Fepuari, na sau ai i lo ma fale le Susuga a Matini Harisi sa ta’ua muamua, ave togitogiga ia na ou tusia mai papatusi, ma alu ma ia i le aai o Niu Ioka. O le mea na tupu e faatatau ia te ia ma togitogiga, o le a ou tuu atu i lana lava tala, e pei ona ia faamatala mai ia te a’u ina ua mavae lona foi mai, e faapenei:"},{"verse":64,"text":"“Sa ou alu atu i le aai o Niu Ioka, ma tuu atu togitogiga ua uma ona faaliliuina, faatasi ma lo latou faaliliuga, ia Polofesa Charles Anthon, o se alii sa ta’uta’ua i lona atamai i mea tau tusitusiga. Sa fai mai Polofesa Anthon ua sa’o le faaliliuga, ua sili atu le sa’o nai lo so’o se isi na ia vaai muamua i ai ua faaliliuina mai le gagana Aikupito. Ona ou faaali atu lea ia te ia togitogiga na sa lei faaliliuina, ma sa fai mai o ia o ni togitogiga Faa-Aikupito, Faa-Kaletaia, Faa-Asuria, ma Faa-Arapi; ma fai mai o ia o ni togitogiga ua moni. Sa ia tuu mai ia te a’u se tusi faamaonia, e faamaonia atu ai i tagata o Palamaira o ni togitogiga moni, ma o le faaliliuga o na mea ua uma ona faaliliuina ua sa’o. Sa ou ave le tusi faamaonia ma tuu i totonu o le taga o lo’u ofu, ma toetoe ina ou tuua lava le fale, ae valaau mai le Susuga a Anthon ou toe foi atu, ma sa fesili mai ia te a’u pe na faapefea ona iloa e le alii talavou o loo i ai ni papatusi auro i le mea na ia maua ai. Sa ou tali atu sa faaalia e se agelu a le Atua ia te ia."},{"verse":65,"text":"“Ona ia fai mai lea ia te a’u, ‘Se’i tuu mai le tusi faamaonia lena se’i ou vaai i ai.’ Sa faapea ona ou ave i fafo le tusi faamaonia mai le taga o lo’u ofu ma tuu atu ia te ia, ma ua ia ave ma saesae ninii, ua fai mai ua lē o toe i ai nei ni mea faapena o auaunaga a agelu, ma afai ou te aumai papatusi ia te ia, o le a ia faaliliuina. Sa ou fai atu ia te ia ua faamauina se vaega o papatusi, ma ua faasaina a’u ona aumaia. Sa tali mai o ia, ‘E lē mafai ona ou faitauina se tusi ua faamauina.’ Sa ou tuua o ia ma ou alu ia Dr. Mitchell, o lē na faamaonia mea na fai mai ai Polofesa Anthon e faatatau i togitogiga ma le faaliliuga.”"},{"verse":66,"text":"O le aso 5 o Aperila, 1829, na sau ai Oliva Kaotui i lo’u fale, ma ou te lei vaai ia te ia se’i oo mai i le taimi lea. Sa fai mai o ia ia te a’u ona sa faiaoga o ia i le vaiaai sa nofo ai lo’u tamā, ma o lo’u tamā o se tasi lea o i latou o e na auina atu a latou fanau i le aoga, sa alu atu o ia ma nofo totogi i lona fale i se vaitau, ma a’o i ai iina sa faamatala atu e le aiga ia te ia tulaga o lo’u mauaina o papatusi, ma ua faapea ona sau ai o ia e fesili mai ia te a’u."},{"verse":67,"text":"E lua aso talu ona mavae le taunuu mai o le Susuga a Kaotui (o le aso 7 lea o Aperila) sa amata ona ou faaliliuina le Tusi a Mamona, ma sa amata ona tusitusi o ia mo a’u."},{"verse":68,"text":"Sa faaauau pea ona ma galulue i le faaliliuina o le tusi, ae, i le masina na sosoo ai (o Me, 1829), na ma o atu ai i se aso faapitoa i le vao e tatalo ma ole atu i le Alii e uiga i le papatisoga mo le faamagaloina o agasala, lea na ma maua o ta’u mai i le faaliliuga o papatusi. A’o faapea ona ma faia, o tatalo ma valaau atu i le Alii, sa afio ifo mai le lagi se avefeau i se ao o le malamalama, ma ina ua faae’e ona lima i luga o i ma’ua, sa ia faau’uina i ma’ua, ua fetalai mai:"},{"verse":69,"text":"I luga o oulua o’u uso a auauna e, i le suafa o le Mesia, ou te faae’e atu i ai le Perisitua o Arona, ua umia ki o le auaunaga a agelu, ma o le talalelei o le salamo, ma o le papatisoga i le faatofuina mo le faamagaloina o agasala; ma o le a lē toe aveesea lava lenei perisitua mai le lalolagi, seia toe osia e atalii o Levi se taulaga i le Alii i le amiotonu."},{"verse":70,"text":"Sa fai mai o ia ua lē o i ai i lenei Perisitua Arona le mana o le faae’e atu o lima mo le meaalofa o le Agaga Paia, ae o le a faae’e mai lea mana i luga o i ma’ua i se taimi o mulimuli mai; ma sa ia poloaiina i ma’ua ma te o ma papatisoina, ma tuu mai ia i ma’ua faatonuga e tatau ona ou papatiso Oliva Kaotui, ma a uma lena ona tatau lea ona ia papatisoina a’u."},{"verse":71,"text":"E tusa ma lea sa ma o atu ma papatisoina. Sa ou papatisoina muamua o ia, ma ina ua uma sa ia papatisoina a’u—ina ua uma lea sa ou faae’e o’u lima i luga o lona ulu ma faau’u o ia i le Perisitua Arona, ma ina ua uma lea sa ia faae’e ona lima i o’u luga ma faau’u a’u i lea lava Perisitua—aua sa faapea ona poloaiina ai i ma’ua.*"},{"verse":72,"text":"O le avefeau na asiasi mai ia i ma’ua i lea taimi ma faae’e mai lenei Perisitua i luga o i ma’ua, na fai mai o lona igoa o Ioane, o lea lava ua ta’ua o Ioane le Papatiso i le Feagaiga Fou, ma ua galue o ia i lalo o le taitaiga a Peteru, Iakopo ma Ioane, o e na umia ki o le Perisitua Mekisateko, o le Perisitua lea, na fai mai o ia, o le a faae’e mai i luga o i ma’ua i le taimi e tatau ai, ma e tatau ona ta’ua a’u o le Toeaina muamua o le Ekalesia, ma ia o (Oliva Kaotui) o le lona lua. O le aso sefululima o Me, 1829, na faau’u ai i ma’ua i lalo o le lima o lenei avefeau, ma papatisoina."},{"verse":73,"text":"O le taimi lava na ma o a’e ai i luga mai le vai ina ua uma ona papatisoina i ma’ua, na oo mai ai ia i ma’ua faamanuiaga tetele ma le mamalu mai lo tatou Tamā Faalelagi. O le taimi lava na mae’a ai ona ou papatisoina Oliva Kaotui, na afio ifo ai le Agaga Paia i luga o ia, ma sa tulai o ia ma valoia mea e tele ua lata ona oo mai. Ma le tasi, e lei umi lava ona papatisoina a’u e ia, sa ia te a’u foi le agaga o valoaga, ma sa ou tulai, ma ou vavalo atu e uiga i le tulai mai o le Ekalesia lenei, ma isi mea e tele e faatatau i le Ekalesia, ma le tupulaga lenei o le fanauga a tagata. Sa faatumulia i ma’ua i le Agaga Paia, ma olioli i le Atua o lo ma’ua faaolataga."},{"verse":74,"text":"Ona ua faapupulaina nei o ma’ua mafaufau, sa amata ona tatala mai tusitusiga paia i o ma’ua malamalamaaga, ma faaali mai ia i ma’ua i se ala sa lē mafai ona ma maua muamua, pe sa ma mafaufau i ai muamua, uiga moni ma faamoemoega o o latou mau sili ona lilo. I le va o lea taimi, sa uunaia i ma’ua e tausi faalilolilo tulaga o le ma mauaina o le Perisitua ma le papatisoina o i ma’ua, ona o se agaga o sauaga ua uma ona faaalia i le vaiaai."},{"verse":75,"text":"Sa faamata’uina i ma’ua i le osofaia, mai lea taimi i lea taimi, ma o lenei foi mea, sa faia e polofesa o mea tau lotu. Ma o o latou faamoemoega e osofai i ma’ua, sa na’o le uunaiga a le aiga o le tamā o la’u ava (i lalo o le taitaiga Paia), o e sa alolofa tele ia te a’u, ma o e sa tetee i tagata leaga, ma sa finagalo malilie e tatau ona tuu o a’u e faaauau le galuega o le faaliliuga e aunoa ma se faalavelaveina, sa punitia ai; ma o lea na latou ofo ma folafola mai ai ia i ma’ua le puipuiga mai taualumaga uma e lē tusa ai ma le tulafono, i mea latou te mafai ai."},{"verse":76,"text":"Ua faapenei ona faamatalaina e Oliva Kaotui ia mea na tutupu: “O nei aso e lē mafai ona faagaloina—o le nofo i lalo o le leo o se siufofoga na fetalai mai e ala i le musumusuga a le lagi, na fagua ai le faafetai silisili i lenei loto! O lea aso ma lea aso, sa ou faaauau ai, e aunoa ma le faalavelaveina, e tusia mai lona fofoga, a’o ia faaliliu i le Urima ma le Tumena, pe, e pei ona ta’ua e tagata sa Nifaē, ‘O faamatala gagana,’ le talafaasolopito po o le talafaamaumau ua ta’ua o le ‘Tusi a Mamona.’"},{"verse":77,"text":"“O le faailoa atu, i nai upu itiiti lava, le tala manaia na tuuina mai e Mamona ma lona atalii faamaoni, o Moronae, e uiga i se nuu sa pele ma alofagia e le lagi, e mamao atu mai lo’u faamoemoe o le taimi nei; o lea o le a ou tuu ai lea faamoemoe i se taimi o i le lumanai, ma, e pei ona ou fai atu i le faatomuaga, o le a ou faasolo tonu atu lava i ni nai mea itiiti faapitoa e faatatau i le tulai mai o le Ekalesia lenei, o ni mea atonu o le a fiafia i ai ni afe o e ua tutulai mai i luma, i le lotolotoi o le mata faasiasia o e faailoga tagata ma le tuuaiga a tagata pepelo, ma opoopo le Talalelei a Keriso."},{"verse":78,"text":"“E leai ni tagata, e mafaia i lo latou manatu malamalama, ona faaliliu ma tusia faatonuga na tuuina atu i tagata sa Nifaē mai le fofoga o le Faaola, e uiga i le ala tonu lava e tatau ai i tagata ona atia’e Lana Ekalesia, aemaise lava i se taimi a’o faasalalau e le amioleaga se lē mautonu i luga o ituaiga ma ala eseese uma ua faia i totonu o tagata, e aunoa ma se naunau i se avanoa e faaali atu ai le naunauga o le loto e ala i le tanumia i se tuugamau vai, e tali atu ai i ‘se mafaufau fuatiaifo lelei i le toetu mai o Iesu Keriso.’"},{"verse":79,"text":"“Ina ua uma ona tusia o le tala na tuuina mai e uiga i le auaunaga a le Faaola i le vaega o totoe o le fanau a Iakopo, i luga o le konetineta lenei, sa faigofie ona vaaia, e pei ona fai mai ai le perofeta, le ufitia o le lalolagi i le pouliuli ma le pouliuli tele i mafaufau o tagata. I le manatunatu atili i ai sa faapea foi ona faigofie ona vaaia, i le totonugalemu o lenei vevesi tele ma le vāvāō e uiga i mataupu tau lotu, sa leai se tasi na i ai le pule mai le Atua e fai ai sauniga o le Talalelei. Ona e mafai ona fai le fesili, pe i ai i ni tagata se pule e auauna ai i le suafa o Keriso, o e e faafitia faaaliga, ae o Lana molimau ua lē o le agaga ea lea o valoaga, ma o Lana tapuaiga sa faavae, atiina a’e, ma lagolagoina i faaaliga tuusa’o mai, i tupulaga uma o le lalolagi a’o i ai sona nuu i le lalolagi? A na fai na tanumia nei mea moni, ma natia faaeteete e ni tagata o lo latou faiva po ua lamatia pe a na tuu e susulu atu i mata o tagata, sa lē toe faapea ia te i ma’ua; ma sa nao lo ma faatalitali mo le tuuina mai o le poloaiga ‘Tulai ia ma papatiso.’"},{"verse":80,"text":"“Sa lei umi ona manaomia o lenei mea ae faataunuuina. O le Alii, o lē ua tumu i le alofa mutimutivale, ma o se e finagalo pea i taimi uma e tali mai i le tatalo fai fai pea a lē ua agamalu, ina ua uma ona ma valaau atu ia te Ia i se auala faatauanau, e ese mai nofoaga o tagata, sa afio ifo e faaali mai ia te i ma’ua Lona finagalo. Sa faafuasei lava, e pei e mai le totonugalemu o le faavavau, ona fetalai mai e le siufofoga o le Togiola le filemu ia i ma’ua, a’o tatalaina le veli ma afio ifo i lalo le agelu a le Atua sa ofu i le mamalu, ma tuuina mai le savali sa tulimatai i ai ma le naunau tele, ma ki o le Talalelei o le salamo. Oka se olioli! oka se matagofie! oka se ofoofogia! A’o fālō tigaina ma fenumiai le lalolagi—a’o tau tagotago le miliona ma miliona o tagata e pei o le tauaso mo le puipui, ma a’o nonofo i le lē mautinoa, o se anoano lautele, sa vaai o ma mata, sa faalogo o ma taliga, e pei o le ‘malamalama o le aoauli’; ioe, e sili atu—i lo le pupula o ave o le la i le masina o Me, ona susulu ifo ai lea o lona pupula i luga o mea uma! Ona oo mai lea o lona siufofoga, e ui ina mālū, ae sa ati i le totonugalemu, ma o ana upu, ‘O a’u o lo oulua uso-a-auauna,’ na aveesea ai mea uma na fefefe ai. Sa ma faalogologo, sa ma sioa, sa ma saafi! O le leo o se agelu mai le mamalu, o se savali mai le Silisili Ese! Ma a’o ma faalogologo atu sa ma olioli, a’o mumū a’e lona alofa i o ma’ua agaga, ma sa fusia i ma’ua i le faaaliga vaaia o lē ua Malosi Aoao! O fea se avanoa mo le masalosalo? Sa leai se mea; ua sola ese le lē mautonu, ua goto ifo le masalosalo ma ua lē toe tu mai, a’o tala fatu ma taufaasese ua sosola ese e faavavau!"},{"verse":81,"text":"“Peitai, le uso pele e, mafaufau ifo, toe mafaufau ifo i sina taimi, i le olioli na faatumuina ai o ma loto, ma le ofo tele atonu na ma ifo ai, (ona o ai e lē tootuli le tulivae mo se faamanuiaga faapea?) ina ua ma mauaina mai lalo o lona aao le Perisitua Paia a’o fetalai mai, ‘I luga o oulua o’u uso a auauna e, i le suafa o le Mesia, ou te faae’e atu ai lenei Perisitua ma lenei pule, lea o le a tumau i le lalolagi, ina ia mafai e Atalii o Levi ona osia se taulaga i le Atua i le amiotonu!’"},{"verse":82,"text":"“O le a ou lē taumafai e faaali atu ia te outou lagona o lo’u nei loto, po o le matagofie malualii ma le mamalu sa siomia ai i ma’ua i lena mea; ae tou te talitonu mai ia te a’u pe a ou fai atu, e lē mafai e le lalolagi, po o tagata, i le maoae o le taimi, ona amata ona faamatalaina i le gagana i se ala uiga ese ma le mamalu e pei o lenei tagata paia. E leai; po o i ai foi i lenei lalolagi le mana e tuuina mai ai le olioli, pe tuuina mai ai le filemu, pe malamalama ai i le poto sa i ai i fuaiupu taitasi e pei ona tuuina mai i latou e le mana o le Agaga Paia! Atonu e mafai e le tagata ona faasese ona uso-a-tagata, atonu e mulimuli mai lea taufaasese i lea taufaasese, ma atonu e maua e le fanau a lē amioleaga le mana e tosina ai tagata valelea ma le lē aoaoina, seia leai se mea ae na’o pepelo e fafaga ai tagata e toatele, ma ave atu ai e le fua o le pepelo i ona tafega e valevale i le tuugamau; ae o le pa’i tasi mai o le tamatamai aao o lona alofa, ioe, o se ave e tasi o le mamalu mai le lalolagi i lugā, po o se upu e tasi mai le fofoga o le Faaola, mai le loto o le faavavau, e taia uma ai i le faatauvaa, ma soloiesea ai e faavavau mai le mafaufau. O le mautinoa na ma i ai i luma o se agelu, o le mautinoa na ma faalogo ai i le siufofoga o Iesu, ma le moni a’ia’i a’o tafe mai se tagata mamā, na faatonuina e le finagalo o le Atua, ia te a’u lava ia, e lē mafai ona faamatalaina, ma o le a ou vaai pea i luga o lenei faaaliga o le agalelei o le Faaola ma le maofa ma le faafetai a’o faatagaina pea a’u ou te tumau; ma i maota na ua i ai le atoatoaga ma e lē sao atu i ai se agasala, ou te faamoemoe o le a ou faapelepeleina i lena aso e lē gata.”—Messenger and Advocate (Avefeau ma le Fautua), vol. 1 (Oketopa 1834), itulau 14–16."}]}]},{"id":"articles-of-faith","title":"Mataupu Faavae o le Faatuatua","englishTitle":"Articles of Faith","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Matou te talitonu i le Atua, le Tamā Faavavau, ma Lona Alo, o Iesu Keriso, ma le Agaga Paia."},{"verse":2,"text":"Matou te talitonu o le a faasalaina tagata ona o a latou lava agasala, ae lē ona o le solitulafono a Atamu."},{"verse":3,"text":"Matou te talitonu e ala i le Togiola a Keriso, e mafai ai ona faaolaina tagata uma, e ala i le usiusitai i tulafono ma sauniga o le Talalelei."},{"verse":4,"text":"Matou te talitonu o uluai mataupu autu ma sauniga nei o le Talalelei: muamua, Faatuatua i le Alii o Iesu Keriso; lona lua, Salamo; lona tolu, Papatisoga e ala i le faatofuina mo le faamagaloga o agasala; lona fa, Faaeega o lima mo le meaalofa o le Agaga Paia."},{"verse":5,"text":"Matou te talitonu e ao ina valaauina se tagata e le Atua, e ala i le valoaga, ma ala i le faaeega o lima o i latou o e o i ai le pule, e tala’i atu ai le Talalelei ma faia sauniga o i ai."},{"verse":6,"text":"Matou te talitonu i le faatulagaga lava lea sa i ai i le Ekalesia Anamua, e pei o, aposetolo, perofeta, epikopo, aoao, tagata folafola le talalelei, ma isi tofiga faapena."},{"verse":7,"text":"Matou te talitonu i le meaalofa o gagana, valoaga, faaaliga, faaaliga vaaia, faamaloloina o ma’i, faamatalaga o gagana, ma isi mea faapena."},{"verse":8,"text":"Matou te talitonu o le Tusi Paia o le afioga ia a le Atua e tusa ma mea ua tonu ona faaliliuina; matou te talitonu foi o le Tusi a Mamona o le afioga ia a le Atua."},{"verse":9,"text":"Matou te talitonu i mea uma na faaali mai e le Atua, mea uma ua ia faaali mai nei, ma matou te talitonu foi o le a ia faaali mai le tele o mea silisili ma le tāua tau i le Malo o le Atua i le lumanai."},{"verse":10,"text":"Matou te talitonu i le faapotopotoina moni o Isaraelu ma le toefuataiga mai o Ituaiga e Sefulu; ma o le a faatuina Siona (le Ierusalema Fou) i luga o le konetineta o Amerika; o le a nofotupu lava Keriso i le lalolagi; ma, o le a faafouina le lalolagi ma maua lona mamalu faaparataiso."},{"verse":11,"text":"Matou te ta’utino atu ua ia i matou le aiā tatau matou te tapuai atu ai i le Atua Mamana e tusa ai ma o matou lava lotofuatiaifo, ma ua matou tuuina atu foi lea lava aiā tatau i tagata uma, e faitalia i latou, pe faapefea, po o fea, po o le a foi le mea latou te tapuai atu i ai."},{"verse":12,"text":"Matou te talitonu i le usiusitai i tupu, peresitene, faipule, ma faamasino, i le usiusitai, faamamaluina, ma le lagolagoina o le tulafono."},{"verse":13,"text":"Matou te talitonu i le faamaoni, amiotonu, nofomama, agalelei, amiomama, ma le faia o mea lelei i tagata uma; e moni, e mafai ona matou faapea atu, ua matou mulimuli i le apoapoaiga a Paulo—Matou te talitonu i mea uma, matou te faamoemoe i mea uma, ua uma ona matou onosai i mea e tele, ma ua faamoemoe o le a mafai ona matou onosai i mea uma. Afai o i ai nisi mea e mamā, matagofie, pe logoleleia pe tauleleia, matou te saili atu i nei mea."},{"verse":14,"text":"Iosefa Samita."}]}]}]'),i={language:"smo",sourceLanguage:"smo",sourcePage:a,books:e};export{i as r};
